INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nerdeydim', 'nerdeydim-yasemin-yarar-6ww1g', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'kendimi kitaplarda buldum

kitapları yaşamda bulamadım

öyleyse ben nerdeydim.', 'kendimi kitaplarda buldum kitapları yaşamda bulamadım öyleyse ben nerdeydim....', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/nerdeydim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sessizce Gel', 'sessizce-gel-gurcan-gunay-iedjt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Karanlığını böl 

Geç saatlerinde gecenin

Tenhalara atıl bulmak için beni

Sus! Bağırma sakın! 

Giz olmalı gelişin...

Fısıldasan adımı duyarım

Koş en koyusuna doğru

Dipsiz karanlıkların

Beyazı olmayan bir dünyada

Perişanım

Ayaklarım prangada

Günahı boynumda yılların

Aşinasıyım çok evvelden

Bu ayrılıkların

Gel hayat dediğim

Görkemli zindanıma

Usandım gayrı

Yokluğun tak etti canıma

Gel, aydınlıkları da 

Peşinde getir

Korkum yok güzelim

Elinden olsun yeter ki ölümüm...', 'Karanlığını böl  Geç saatlerinde gecenin Tenhalara atıl bulmak için beni Sus! Bağırma sakın!  Giz olmalı gelişin... Fısıldasan adımı duyarım...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sessizce-gel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Adımı Unutacağım', 'adimi-unutacagim-yasemin-yarar-ze818', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Adımı unutacağım

çağıran yok

çöl sınırsızdır

yalnızlık da öyle

çarpıp dünyanın kapısını

dönmemek üzere gitmek', 'Adımı unutacağım çağıran yok çöl sınırsızdır yalnızlık da öyle çarpıp dünyanın kapısını dönmemek üzere gitmek...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/adimi-unutacagim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bambaşka Bir Yaşam', 'bambaska-bir-yasam-hanife-yasemin-xt50m', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seni bekliyor aklar içinde bu gelin.

ellerini açmış

bense arkanda, siyahlar içinde

dönmek istermisin, bakarmısın 

gözlerime? 

''BAMBAŞKA''bir yaşam, seni bekliyen

ve sen merhaba diyorsun güleç neşeli

senelerdir bekler gibi, büyük bir hasretle.

''BAMBAŞKA''bir duygu bu 

tamamen kaybetmek seni.

BAMBAŞKA bir kıskançlık bu

tenimi acıtan

BAMBAŞKA BİR YAŞAM BU 

BAMBAŞKA çiçekler, 

bambaşka gök yüzü, 

bambaşka bir mevsim 

ve bu evren, dönerek üzerime düşen, bomboş bir kuyu dibi kadar karanlık.hücre kadar dar

ve ben göz yaşlarına boğulmuş nefes alamıyacağım.

peki ya o, düşünmektemi benim kadar seni? 

feda edermi canını? 

bir bakışın, bir sösün, bir dakikan için.

sevmekdemi benim kadar, 

tapmaktamı''ALLAH''tan sonra sana.

incitmeden sevebilirmi seni, 

ellerine dokunduğunda tutuşuyormu kalbinin ucu? 

dudaklarını yakarmı dudakları? 

hissedermi yanında olmasanda her dakika seni? 

oysa sen gidiyorsun

''BAMBAŞKA BİR  YAŞAMA''

ve ben ''SEVİYORUM SENİ''', 'Seni bekliyor aklar içinde bu gelin. ellerini açmış bense arkanda, siyahlar içinde dönmek istermisin, bakarmısın  gözlerime?  ''BAMBAŞKA''bir ...', ARRAY['Türk Edebiyatı','Şiir','Hanife Yasemin']::text[], 8.5, '{"poet":"Hanife Yasemin","poet_slug":"hanife-yasemin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bambaska-bir-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küsme', 'kusme-hasan-turgut-yb1g3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'güneş güne küsse etrafına ışık saçmaz

ay geceye küsse karanlıkta parlamaz

bulut yağmura küsse yağmur yağmaz

ve kalbimde yaşadığım sen bana küssen kalbim atmaz', 'güneş güne küsse etrafına ışık saçmaz ay geceye küsse karanlıkta parlamaz bulut yağmura küsse yağmur yağmaz ve kalbimde yaşadığım sen bana k...', ARRAY['Türk Edebiyatı','Şiir','Hasan Turgut']::text[], 8.5, '{"poet":"Hasan Turgut","poet_slug":"hasan-turgut","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kusme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum Demenin En ''Saf'' Hali', 'seni-seviyorum-demenin-en-saf-hali-mehmet-sercan-tezcanoglu-mih9t', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nasıl söylesem

Seviyorum seni, diye.

Kelimeler, kelimeler sığmıyor ki cebime...

Mesela diyorum kendi kendime: 

Yanardağlar gibi seviyorum onu, 

Gördükçe için için yanıyorum.

Ya da bir çocuğun elma şekerini sevdiği gibi

Özenle, dürüstçe, saf ve temiz.

Hayır bunlar değil aradığım kelimeler! 

Cebimi karıştırıyorum.

Başka kelimeler alıyorum ellerime.

Seni öyle seviyorum ki...

Güneş gibi doğuyor içim seni her gördüğümde, 

Ve sen her gittiğinde, batıya batıya gidiyorum.

Batıyorum ben de gemiler gibi.

Sonra ayışığında yeniden canlanıyor hayalin, 

Yıldız yapıp seni gökyüzüne serpiştiriyorum.

Tuhaf, bunlar sevgimi anlatmıyor biliyorum.

Yeni kelimeler alıyorum cebimden, 

Tanıdık...

Seni seviyorum, seni seviyorum diyorum.

Evet bunlar işte aradığım kelimeler! 

Ceketimin cebinde unuttuğum, 

Bir türlü söyleyemediğim...', 'Nasıl söylesem Seviyorum seni, diye. Kelimeler, kelimeler sığmıyor ki cebime... Mesela diyorum kendi kendime:  Yanardağlar gibi seviyorum on...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seni-seviyorum-demenin-en-saf-hali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mitologya, Din, Ölüm ya da Hiçbir Şey', 'mitologya-din-olum-ya-da-hicbir-sey-mehmet-sercan-tezcanoglu-2sezf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yanlış yaptın yanlış yaptın! 

Cezanı kendine kendin ver, dediler.

Bir çarmıh buldum bir yerlerden, 

Gerildim! 

Göğe çıktım sandım, 

Baktım yerdeyim.

Yerle ben, bir başına

Kaldık dağın başında.

Çarmıh ellerimde, 

Ellerim kanıyor.

Çiviler paslı, 

Gözlerim yaşlı, 

Yaşlarım hüzün içinde

Ağlarken, 

Yağmur bulut içinde

Yaşlarıma eşlik ederken, 

Sular yükselirken göğe

Nuh''un gemisi geçti önümden.

Beni del al, beni de al diye haykırırken dilim...

Çarmıh ellerimdeyken

ve ellerim çiviliyken

ve çiviler paslıyken

ve de sular yükselirken, 

Nuh''un gemisi geçerken önümden, 

Yasak elma Havva''nın ellerinde, 

Adem olan bitenden habersiz.

Medine fethedilirken, 

Kızıldeniz yarıldı ikiye.

Ramses ağzı açık

Düştü beriye.

Yağdı yağmur, 

Odunlar balık oldu.

İndi bir melek adı Cebrail: 

Oku, dedi bana.

Okudum! 

Ellerim çarmıha geriliyken

ve çiviliyken ellerim.

Paslıyken çiviler

Ve sular yükselirken, 

Geçerken önümden Nuh''un gemisi, 

Kızıldeniz yarılıp ikiye, 

Havva elma yerken, 

Medine fethedilirken, 

ve ben ve ben ölürken...

Okudum! 

Hiçbir şey olmadı.

Sular yükseldi, 

Paslı çiviler çözüldü.

Çarmıh düştü, 

Medine düştü, 

Kızıldeniz kapandı.

Yaralı balıklar doğdu.

ve ben öldüm

Okurken...', 'Yanlış yaptın yanlış yaptın!  Cezanı kendine kendin ver, dediler. Bir çarmıh buldum bir yerlerden,  Gerildim!  Göğe çıktım sandım,  Baktım y...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/mitologya-din-olum-ya-da-hicbir-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kardanadam Falı', 'kardanadam-fali-mehmet-sercan-tezcanoglu-qbx70', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kış günü... Şehir beyaz

Öykü beyaz

İki çocuk

Çocuklar beyaz

Ellerinde kar taneleri

Akıllarında kardan bir adam

Yuvarlayıp karları

Yığıp bir köşeye

Biriktiriyorlar düşlerini

Önce bedeni yapıp

Koyuyorlar üstüne

Düşüneni

İki kömür takıp gözlerine

Bir havucu yerleştirip

Belledikleri burun yerine

Boynuna bir atkı

Elinde bir küçük ağaççık

Ve işte

Kömür gözlü

Havuç burunlu

Kardanadamcık

.........

Düşünüyor kardanadam

Ne kadar yaşarım diye

Soğuğu seviyor

Beyazı da

Burnu kaşınıyor ara sıra

Ama kaşıyamıyor

Gözlerini ovmak istiyor

ama elleri yok...

......................

Çocuk 

Düş

Çocuk ve düşü

Bir çocuk

Çocukta bir düş

Düşte bir kardanadam

Üşüyor

Kalkıyor çocuk

Elinde montu

Montu elinde

Kardanadamın yanında

Montu giydiriyor kendince

Üşümezsin artık kardanadam düşümde...

.......................

Ölüyor kardanadam

montun içinde

Çocuk 

Düş

Çocuk ve düşü

Bir çocuk

Çocukta bir düş

Düşte bir kardanadam

Eriyor

Kalkıyor çocuk

Eli boş

Boş eliyle

Kardanadamın yanında

Yanında değil kardanadam

Kardanadam artık yok

..................

Bir kış giderken

Yanında anıları, özlemleri

Kardanadamları alıp da gidiyor

Hiç sormuyor çocuklara

bir de Kardanadamlara', 'Bir kış günü... Şehir beyaz Öykü beyaz İki çocuk Çocuklar beyaz Ellerinde kar taneleri Akıllarında kardan bir adam Yuvarlayıp karları Yığıp ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/kardanadam-fali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Önemi Var Ki!', 'ne-onemi-var-ki-fethi-hur-giray-lclk4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tanıklık yapar mı tanıdık yüzler? 

yoksa başlamadan biter mi bazı galibiyetler? 

Bir, 

iki, 

üç, 

Diyerek saydığım isimler

kaybolurlar mı zihnimden? 

Şuradayken, o da vardı sanırım diyerek

başlasa cümle.

Nasıl, 

nerede, 

kimle, 

hangi zamanda biter? 

Rüyadan rüyaya mı koşuyorum? 

yoksa masaldan masala mı? 

Ne kadar çok yedi cüce var! 

Ve ne kadar çok işe yaramaz adam

her biri sanki kendi masalında kahraman...

Hayat; gerçek mi? 

Yoksa bana mı öyle geliyor? 

Gözümle gördüklerime bile inanmıyorum artık

Hepsi yalan, 

gerçek.

Yalan, 

gerçek...

Ne önemi var ki benim duyduklarımın! 

Farzedelim hepimiz iyiyiz

Hadi şimdi, hep beraber

gülelim geçelim.', 'Tanıklık yapar mı tanıdık yüzler?  yoksa başlamadan biter mi bazı galibiyetler?  Bir,  iki,  üç,  Diyerek saydığım isimler kaybolurlar mı zi...', ARRAY['Türk Edebiyatı','Şiir','Fethi Hür Giray']::text[], 8.5, '{"poet":"Fethi Hür Giray","poet_slug":"fethi-hur-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/ne-onemi-var-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sempatik', 'sempatik-fethi-hur-giray-3fmoc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Pul kanatçıklarınız kadar, 

narin mi gözleriniz? 

Ay ışığında kalbinizi kamaştıran

sevgiler karşısında.

İnci tanecikleri dökülüyor mu? 

o öpülesi yanaklarınızdan. 

Yoksa hala eksik olmuyor mu? 

bitmez tükenmez gülücükler dudaklarınızdan.

Yaz akşamlarıyla gelen simanız, 

hatırlanıyor kimi zaman özlemle

Bir kuş kadar değil ağırlığınız, 

uzun bir yokuş gibi ulaşılmazlığınız.', 'Pul kanatçıklarınız kadar,  narin mi gözleriniz?  Ay ışığında kalbinizi kamaştıran sevgiler karşısında. İnci tanecikleri dökülüyor mu?  o öp...', ARRAY['Türk Edebiyatı','Şiir','Fethi Hür Giray']::text[], 8.5, '{"poet":"Fethi Hür Giray","poet_slug":"fethi-hur-giray","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sempatik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmuştum', 'unutmustum-daisy-daisy-wxfb8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'unutmuştum

gökyüzünün maviliğini

ve güneşin parlaklığını

unutmuştum

nemli toprağın

genzi yakan buğusunu

ve papatyanın

masum tatlı kokusunu

unutmuştum

doğan günün

taze sabahını

ve içime çektiğim baharı

unutmuştum

yaşamın sıcaklığını

ve damarımda kanın

hala aktığını

unutmuştum

sıradan olmuştum

hatırlattın

hatırladım

hatırlattın

hatırladım

hatırladım

hayatı', 'unutmuştum gökyüzünün maviliğini ve güneşin parlaklığını unutmuştum nemli toprağın genzi yakan buğusunu ve papatyanın masum tatlı kokusunu u...', ARRAY['Türk Edebiyatı','Şiir','Daisy Daisy']::text[], 8.5, '{"poet":"Daisy Daisy","poet_slug":"daisy-daisy","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutmustum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duha', 'duha-ayhan-birinci-538al', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kuşluk vaktinden güzelsin...

Sen zamanların en tatlısı, en şahanesisin.

Çok küçüksün belki ama gözümde umman gibisin.

Duyguların en ''best''ini yaşattın bana, 

Teşekkür ederim küçük oğlum ''DUHA'' sana.

Hayat zor, yaşamak nasılmış onu biraz büyüde gör? 

Nekadar zor olursa olsun oğul, 

Yüreğin sağlam, gözün pek olsun.

Kazancın helal, gönlün sevgi pınarı olsun.

Kim nerde, nasıl, nekadar yaşar? 

Bunu kimse bilmez lakin, her olayda bir hayır var.

Bunu görmek istersen, herşeyi zamana bırak.

Göreceksin Yaradanın her canlı üzerinde

Yüce adaleti var.

Sen dürüst ol, varsın dünya batsın...

Yalan söylemek için hiç mumun olmasın

Bilgi için ''Çİn'' güzergahın

Kısa veya uzun değil, dolu dolu

Güzel bir ömrün olsun.

Beni sorma oğul; nasıl, nerde, 

Dolu mu boş mu yaşadın? 

Ben senin için, hep sana yaşadım.

Hayı hayır.''Benim için sana yaşadım...''

Dua için ''DUHA'' yı yaşadım.', 'Kuşluk vaktinden güzelsin... Sen zamanların en tatlısı, en şahanesisin. Çok küçüksün belki ama gözümde umman gibisin. Duyguların en ''best''in...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Birinci']::text[], 8.5, '{"poet":"Ayhan Birinci","poet_slug":"ayhan-birinci","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/duha-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Güzellik', 'mavi-guzellik-necmettin-davulcu-1yalp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Güzelliğe gideceğim

Kırmızı umutların ötesindeki şehirlere

Kaçıp kötülük ve çirkinliklerden

Kaçıp umutlarımla

Düşlerimle

Yeniden varoluşa

Güzelliğe gideceğim

Sana güzelliği getireceğim

Kokusuz olmayacak öpücüğün

Renksiz olmayacak', 'Güzelliğe gideceğim Kırmızı umutların ötesindeki şehirlere Kaçıp kötülük ve çirkinliklerden Kaçıp umutlarımla Düşlerimle Yeniden varoluşa Gü...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/mavi-guzellik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söylence', 'soylence-haydar-ergulen-u3we6', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'akdeniz gülüşlü bir çocuk olsaydın

ağzının kıyısında gülüşler biriktiren

yüzünde bin bir haylazlıkla sevseydin beni

yüreğinden beyaz kuşlar uçardı yüreğime

dokundukça portakal çiçekleri dökerdi

sevilmekten ürpertili dingin gövden

ah çocuk ah kadın ah sevgili

sözlerin aşkı anımsatsa da

gülüşünde onulmaz acılar gizli.', 'akdeniz gülüşlü bir çocuk olsaydın ağzının kıyısında gülüşler biriktiren yüzünde bin bir haylazlıkla sevseydin beni yüreğinden beyaz kuşlar ...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/soylence-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaprak Tekrarı', 'yaprak-tekrari-haydar-ergulen-saym2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'güz, resimlerde bir yaprak tekrarı hala

özlendiği odalarda açmayan nergis

ateşi mırıldanıyor kovulduğu bahçede, 

şehrin yeni yağmuru yangınlardan habersiz

belleğin uzak anılarıyla veda; 

büyük kalbine rüzgarlar çağıran çocukluğun

yoksul bir gülü övgüyle taşımasına

sen, yüzüne yurt arayan yolcunun güzelliği

gözlerinde bir gülümseme hazırlığı, derin

unutuluşların gövdesinde uyanmış

incesin, bir yaraya sarmak istemem seni

sen kendine küsersen belki ben de küserim', 'güz, resimlerde bir yaprak tekrarı hala özlendiği odalarda açmayan nergis ateşi mırıldanıyor kovulduğu bahçede,  şehrin yeni yağmuru yangınl...', ARRAY['Türk Edebiyatı','Şiir','Haydar Ergülen']::text[], 8.5, '{"poet":"Haydar Ergülen","poet_slug":"haydar-ergulen","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yaprak-tekrari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Soluk Geceler', 'soluk-geceler-necmettin-davulcu-demwx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'alır götürürdü geceyi rüzgar

karanlığın siyah saçlarını

ölümün sarı saçlarına katarak

bir çocuk ağlardı

suskun gecede karanlığı yırtan

bir sel olu akardı

ve rüzgar dolaşırdı kapı tokmaklarında

ölümün habercisi gibi

yağmur pencerelerde oynarken gelirdi ölüm

aynada kendimi ararken gelirdi

ve bir ağıta dönüşürdü

soluk gecelerde

çocuğun karanlığı yırtan sesi', 'alır götürürdü geceyi rüzgar karanlığın siyah saçlarını ölümün sarı saçlarına katarak bir çocuk ağlardı suskun gecede karanlığı yırtan bir s...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/soluk-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Merhaba', 'merhaba-necmettin-davulcu-6730m', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gün açıyor gün

tatlı

coşkulu koklaşmalar üstüne

yedirenk gökkuşağı olmuş gökyüzü

öpüşler var ılık

ılık

merhaba yeni gün

merhaba

bulutsuz

sıcak

bir uçtan bir uca merhaba

kırmızı umutlarım', 'gün açıyor gün tatlı coşkulu koklaşmalar üstüne yedirenk gökkuşağı olmuş gökyüzü öpüşler var ılık ılık merhaba yeni gün merhaba bulutsuz sıc...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/merhaba-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzel Şey', 'guzel-sey-necmettin-davulcu-zvrj4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gülebilmek ne güzel şeymiş

umarsızlıklar içinde tatlı tatlı

ne güzelmiş kadınımın ıslak dudakları

sarılmak ne tatlı şeymiş

unutuvermek tüm sorunları

yaşamın maviliğine dalmak

tozkoparan yağmurun

altında', 'gülebilmek ne güzel şeymiş umarsızlıklar içinde tatlı tatlı ne güzelmiş kadınımın ıslak dudakları sarılmak ne tatlı şeymiş unutuvermek tüm s...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/guzel-sey-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeşilin Resmi', 'yesilin-resmi-necmettin-davulcu-c8oi9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yeşilin resmini yapmak istiyorum

veya

mavinin imgesel çağrışımını yazmak

kırmızı umutlarımdan bir kent kurup

güzelliği yaşatmak istiyorum

kısacası sevdiğim

insanlık dışı bir iş yapmak istiyorum

insancıklar için', 'yeşilin resmini yapmak istiyorum veya mavinin imgesel çağrışımını yazmak kırmızı umutlarımdan bir kent kurup güzelliği yaşatmak istiyorum kı...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yesilin-resmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Güzellikler Adına', 'butun-guzellikler-adina-necmettin-davulcu-94vti', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sorumluluğumuz büyük

''yaşamı güzelliği yeşertmek

rüzgarda meşeler gibi dik

dağbaşlarının suskunluğuna direnmişliğimizle

umarsızlığın karanlığına dalmadan

amacımız bir

''serin yıldızlı

harman sonu kokan gecelerde

toprakta asfaltta duyarak ekimin güzsü kokusunu

ağılanmışlıktan kurtulmak

hep omuz omuza elele

''okulda fabrikada kaldırım taşlarında

taş ocakları zindan

ve de hayınlık kötülük içinde

karatmadan sevebilmek kardeşliği

direnebilmek

''kurutmadan yüreklerimizi umutlarımızı

sonbahar rüzgarında bir kucak çiçekle

akıtabilmek yaşamı gönlümüzce

dimdik kalabilmek önemli olan

bir avuç mavi için güz mevsiminde''

türkiye memleketim için', 'sorumluluğumuz büyük ''yaşamı güzelliği yeşertmek rüzgarda meşeler gibi dik dağbaşlarının suskunluğuna direnmişliğimizle umarsızlığın karanlı...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/butun-guzellikler-adina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dışarıdan İçerisi', 'disaridan-i-cerisi-necmettin-davulcu-w9ex2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hep geceyi yaşadılar hücrelerinde

karanlığa karışıp dağıldı umutları

günışığına özlem dolu

ölümü beklediler

hergün

günde üç öğün

tabağa koyup yediler

katık edindiler kuru ekmeklerine acıyı

bitiremediler

diken oldu

gözbebeklerine durdu

günışığı

karanlığı uğuldayan rüzgara devredip

türkü olup

yüreklere doldular

hep geceyi yaşadılar

umutları kaldı dört duvar

hücrelerinde', 'hep geceyi yaşadılar hücrelerinde karanlığa karışıp dağıldı umutları günışığına özlem dolu ölümü beklediler hergün günde üç öğün tabağa koyu...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/disaridan-icerisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-necmettin-davulcu-n5lwp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'götür bu gece yıldızları da

ayışığı gözlerin olmasın varsın

sessizliğim varya yanımda

bir tutam rüzgar ol savur saçlarını

taşır ırmakları bu gece ne olur sanki

iki damla gözyaşı bana yeter

çorak ovaların kırçiçeği

güzgülü

yağmur bakışlı

al git bende ne varsa senden

ağıtlar yakayım ardından

uyku uğramasın yanı başıma bu gece

kollarımla sararken senseizliğimi

kum sarsın yüreğimi

karlar yağsın bu gece', 'götür bu gece yıldızları da ayışığı gözlerin olmasın varsın sessizliğim varya yanımda bir tutam rüzgar ol savur saçlarını taşır ırmakları bu...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/bu-gece-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Küçük Na''t', 'kucuk-na-t-sezai-karakoc-adpsa', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Göz seni görmeli, ağız seni söylemeli

Hafıza seni anmak ödevinde mi

Bütün deniz kıyılarında seni beklemeli

Sen Eskimoların ısınması sevgililer mahşeri

Aklım yeni bir akıldır çiçeklerden

Mantığım mantığın üstünde yeni

İçimde Nuh''un en yeni tufanı

Dünyaya ayak basıyorum yeniden

Göz seni görmeli ağız seni söylemeli

Bütün deniz kıyılarında seni beklemeli

Yüzlerce yıl geçiyor belki bir bulut geçiyor

Ben yeni doğmuş bir çocuk gibi

Herkesin konuştuğu dilden mahrum

Ama yepyeni bir dil konuşmanın sevinci

Bütün deniz kıyılarında seni anmalı

Sen buzulların erimesi Eskimoların ısınması', 'Göz seni görmeli, ağız seni söylemeli Hafıza seni anmak ödevinde mi Bütün deniz kıyılarında seni beklemeli Sen Eskimoların ısınması sevgilil...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kucuk-na-t-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vatan Bayrak', 'vatan-bayrak-fevzi-kurtulus-6vcap', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yabancı bankalara yatar paralar

Hasta oldunuz mu amerikalar

Allahınız olmuş mark ile dolar

Vatan bayrak diyen siz sahtekarlar

Amerikan modelinde olur traşı

Vaşington babası rambo kardaşı

Kelle avlamada çeker en başı

Vatan bayrak diyen siz sahtekarlar

Hey sen

FBI yazılı şapkanla

Tişörtündeki amerikan bayrağı, cebindeki

Marlboranla

Güzel dilimizi katleden o garip konuşmanla

Ne kadar vatanseversin bir düşün! 

Ve sen

Acıkınca hamburger yiyen

Susuzluğunu kola ile gideren

Çikolatası alplerden, peyniri hollandadan gelen

Pir Sultanı, Karacaoğlanı, Veyseli tanımayan

Elvis ile hüzünlenen, Madonna ile gülen

Favorisi uzun, kulağında küpe

Fabrika önlerinde emekçi kızları tavlamaya çalışan

Züppe

İşaret ve serçe parmağınla yaptığın sembolünle

Ne kadar vatanseversin bir düşün! 

Ve siz

Muhalefette emperyalizme kafa tutanlar

İktidarda söylediklerini bir bir yutanlar

Mazlum halklar karşısında aslan

Efendiler karşısında süt dökmüş kediye dönenler

Anadolu halklarının kanıyla sulanmış bayrak ile

Yolsuzlukların üstünü örtenler

Siz cumhuriyetin ve bağımsızlığın düşmanları

Siz Abdulhamit in ve Enver Paşa nın torunları

Siz yeni dünya düzeninin temsilcileri ve ortaçağ

Kalıntıları

Siz vatan bayrak diyen sahtekarlar

Sattınız onuru emperyalizme

Çiğner bayrağımızı yabancı çizme

O yalan söyleyen dillerinizle

Vatan bayrak diyen siz sahtekarlar

Kuva-i milliye onurumuzdur

Kurtuluş savaşı gururumuzdur

Bağımsız Türkiye şiarımızdır

Size layık değil pis sahtekarlar

Vatan bayrak diyen siz sahtekarlar', 'Yabancı bankalara yatar paralar Hasta oldunuz mu amerikalar Allahınız olmuş mark ile dolar Vatan bayrak diyen siz sahtekarlar Amerikan model...', ARRAY['Türk Edebiyatı','Şiir','Fevzi Kurtuluş']::text[], 8.5, '{"poet":"Fevzi Kurtuluş","poet_slug":"fevzi-kurtulus","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/vatan-bayrak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz Yürüyelim El Ele İstanbul Sokaklarinda', 'biz-yuruyelim-el-ele-i-stanbul-sokaklarinda-emrullah-erdinc-8uhsl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Istanbul sokaklarinin anisi biz olalim

gezelim elele kol kola fisildiyalim sevgimizi 

sessiz sözcuklerle oksuyalim ruhumuzu

sevincimizi disariya vuralim görenler 

gulumseyip gecsinler yanimizdan 

anlasinlar sevgimizi  saygi duysunlar

gezelim istanbul sokaklarinda elele kol kola 

istanbul sokaklarinin anisi biz olalim 

oturup biryerde aksam yemegimizi yiyelim 

sen yemekle sarabini yudumlarsin

ben ise o guzel gözlerine bakar

 hayallere dalarim belki beni sever 

 basini yavasca koyarsin omuzuma 

guzel yumusak saclarini oksarim

 sana yavasca askimi kulagina fisildarim

 istanbul sokaklarinin anisi biz olalim

gezelim elele kol kola fisildiyalim 

sevgimizi

ve o sokaklari hep animsiyalim.', 'Istanbul sokaklarinin anisi biz olalim gezelim elele kol kola fisildiyalim sevgimizi  sessiz sözcuklerle oksuyalim ruhumuzu sevincimizi disa...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/biz-yuruyelim-el-ele-istanbul-sokaklarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Baktikca İçim Hüsranla Dolar', 'gozlerine-baktikca-i-cim-husranla-dolar-emrullah-erdinc-e3ojz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktikca

 icim husranla dolar

aklima sen gelince

 aglarim her an

bilki yalan degil

degil seni sevdigim

inan artik sevdigim

gözlerin ah o

 gözlerin hic 

cikmiyor

aklimdan ya sesin 

gökyuzunde sanki cennetten

 gezmeye cikmis meleklerin 

sarki mirildanislarina

 benziyor kahrolusumun 

kaybolusumun bir

eseri olacaksin sen 

dunyaya bir daha

 gelsem seninle 

ayni mahallade sokakta

 senin teneffus ettigin havayi 

etmek ister yanindan

hic ayrilmamacasina

sonsuza dek kalmak

 isterdim seninle

 yalniz seninle 

senin icin su 

akittigim 

göz yaslarim deniz

olsada bogulsam icinde

gözlerine baktikca

icim husranla dolar', 'Gözlerine baktikca  icim husranla dolar aklima sen gelince  aglarim her an bilki yalan degil degil seni sevdigim inan artik sevdigim gözleri...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gozlerine-baktikca-icim-husranla-dolar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tragedia', 'tragedia-ahmet-ferit-cosan-jet3m', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İlk gördüğümde seni, 

Yüzünde sevgiler uçuşuyordu.

Gülüyordun belki, belki mutluydun.

Sevmiştim bende seni.

İlk ağladığında ise, 

Bir yakının ölmüştü.

Beslediğin kuş kaçtı belki, 

Belki köpeğini zehirlediler.

İlk bayıldığında ise 

Çocuğunu doğurdun.

Çocuk ağlıyordu acıyla

Hem ıslak ve kanlıydı.

İlk kez bağırdığında ise

Hırslıydın belki sinirli, 

Yaşayacağım diyordun içinden, 

Belki çocuğunu emzirirken.

İkinci kez gülüyorken sen, 

Sonsuz bir huzurla, 

Ölmüştün.

Arkandan çocuğun ikinci kez ağlarken.', 'İlk gördüğümde seni,  Yüzünde sevgiler uçuşuyordu. Gülüyordun belki, belki mutluydun. Sevmiştim bende seni. İlk ağladığında ise,  Bir yakını...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/tragedia-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Piyonları Dansı', 'piyonlari-dansi-ahmet-ferit-cosan-cz8rx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Piyonların dansında,

Minnet benim kaderimdir.

Aşkımsa,

Dalda asılı elmanın vasiyeti 

Çekirdektir.

Ancak gülerek uyanabilenler

Kardeşlerimdir.

Zavallılar dostlarım,

Kaybolmuşlar gözyaşlarım.

Bir başka piyon,

Vezir olduğunu sanıpta,

Kavalyelik için çağırmasın beni.

Benim aşkım,

Dalda asılı elmanın vasiyeti

Çekirdektir.

Dans etmesini de bilmem.

Sevilmesini de.

Ve şaşkın pusuladır hayatım,

Aşkın etrafında çılgınca semah ettiği.

2002', 'Piyonların dansında, Minnet benim kaderimdir. Aşkımsa, Dalda asılı elmanın vasiyeti  Çekirdektir. Ancak gülerek uyanabilenler Kardeşlerimdir...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/piyonlari-dansi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgar', 'ruzgar-ahmet-ferit-cosan-1al1o', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gölgelikte oturan

Eski devirlerden kalan

Acımasız bir tanrıdır rüzgar.

Serinliğinden bir zeytin ağacının, 

Kavuruculuğuna bir sahilin, 

Hükmeder yaşanacak zamanlara.

Kuşları sever en çok o, 

Bir de hindibalarını.

Ki izin verir tüm gökyüzünde

Özgürce gezebilmelerine.

Rüzgardır, merhametinde hasat yapılan, 

Ve yine odur, tekneleri fırtınalarıyla batıran.

Bir acımasız tanrıdır eski zamanlardan gelip

Yeni zamanlara akan.', 'Bir gölgelikte oturan Eski devirlerden kalan Acımasız bir tanrıdır rüzgar. Serinliğinden bir zeytin ağacının,  Kavuruculuğuna bir sahilin,  ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruzgar-19-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çarkıfelek', 'carkifelek-ahmet-ferit-cosan-n40ir', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolun ortasında bir lastik papuç

Sahibi belli olmayan.

Zümrütçe, 

En güzel renk nasıl yeşilse

Adamca en güzel şey kayıp papucu.

Adam koskoca şehirde yalnız

Bir papuçsuz.

Gölgeler hapisteyken

Adam, izdüşümü hayatta 

Terli, yorgun hissetmekte.

Adam koskoca bir dişli, 

Başkaları tarafından çevrilen, 

Hep aynı yöne dönen, 

Başkalarını döndüren.

Ama bir dişi yok onun artık, 

Yolun ortasındaki lastik papucu.

Çeviremez artık diğerlerini

Döndüremez çark_ı feleği', 'Yolun ortasında bir lastik papuç Sahibi belli olmayan. Zümrütçe,  En güzel renk nasıl yeşilse Adamca en güzel şey kayıp papucu. Adam koskoca...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/carkifelek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Zamanlar', 'boyle-zamanlar-ahmet-ferit-cosan-o8plg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir fırtınanın tam ortasında sanki martılar.

Dönüp duruyorlar.

İşte böyle zamanlarda

Çiçekler hallerine ağlar.

Böyle anlarda yası olan kadınlar

Karalar bağlar, 

Böyle vakitlerde 

Çekilir dalyanlarda ağlar, 

Bilinmeyen uzaklarda 

Bilinmeyen insanlar

Ufka doğru koşar, 

Zaman geçer azar azar, 

Bekçiler uykuya dalar

Coşup ta deniz azar dalgalar.

Bir çoban bir derenin içinde

Bir karanfil gördüğünü sanar.

Bilinmeyen geçmişte 

İnsanlar saatleri kurar.

Bilinmeyen gelecekte 

O saatler bir bir çalar.

Bu zamanlarda nice yıldız, 

Aşka doğar, 

Aşk nice insanı yakar

Sevilenler sevenlere

Mutlu, kaygısız bakar

Böyle zamanlarda bir yıldız, 

Bir dilek için kayar.

Ve böyle anlarda kurulur hayaller.

Saatlerce hatta sabaha kadar.', 'Bir fırtınanın tam ortasında sanki martılar. Dönüp duruyorlar. İşte böyle zamanlarda Çiçekler hallerine ağlar. Böyle anlarda yası olan kadın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/boyle-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölümler', 'olumler-ahmet-ferit-cosan-5tvfl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ölümler, ölümleri dinmez bir heyecan ve istekle kovalarken

Üzgün bir yüreğin içten içe acı çekmesini kim hissedebilir ki? , 

Merdivenlerdeki, akşam olunca durmadan öten cırcır böcekleri mi

Bir kuşun gözünden görebilsek dünyayı, ufuklara doğru dalıp gitsek umarsızca

Her dertli zamanımızda

Acılar hiçbir zaman yetişemese bize

Gül bahçesi olsa her günümüz, tomurcuklar bitse her saniyemizde

Sevsek sevilirken, 

Gülebilsek içten her türlü zorluklara yılmadan

Sen dediğim belirse sonra

''onca acına rağmen geldim'' dese

uzatsa narin ellerini

onu '' hoşgeldin ey dost ''  diyerek selamlasam

tutsam ellerinden

öpsem

öpsem

ölümler yorulsa kovalamaktan

düşlerime dostumu ortak etsem

ölenlere göz yaşı dökerek, yaşadığıma şükretsem

düşlerim, günlerimden  daha az gerçek değil

sen, olmasan bile dostumsun

ölümlerse gerçek deneyimlediğimiz an ve an

tıpkı ölenler gibi

tıpkı öldürenler gibi…', 'Ölümler, ölümleri dinmez bir heyecan ve istekle kovalarken Üzgün bir yüreğin içten içe acı çekmesini kim hissedebilir ki? ,  Merdivenlerdeki...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/olumler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlıkta', 'karanlikta-ahmet-ferit-cosan-x5wk9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ve karanlıkta boğuştum yalnızlığımla, 

Tek silahım, aşkının ışığıydı.

Önce umut serptim hayallerimle üstüne, 

Sonra saldırdım yalnızlığıma sessizce.

Şaşırdı, inanamadı yaşlı gözleri, 

Tek dost bildiğinin kin taşıyan ellerini hissedince, 

Tek dost bildiğinin, 

Onu satıverdiğine.

Oysa, o değilmiydi ki uzun, ıssız gecelerimde

Çaresizliğime yoldaş olup, beni avutan

Ne zaman sarılmak istesem, 

Bana herdaim dost kucağını sunan.

Ve gün doğunca da

Gömdüm onu usulca

Kalbimin en ıssız, el değmemiş yöresine.

Üzerinide senin için kurduğum hayallerle örttüm.', 'Ve karanlıkta boğuştum yalnızlığımla,  Tek silahım, aşkının ışığıydı. Önce umut serptim hayallerimle üstüne,  Sonra saldırdım yalnızlığıma s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/karanlikta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dört Duvar Oda', 'dort-duvar-oda-yasemin-yarar-pb9fp', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dünya dört duvar oda

bağırıyorum

kimse yok mu

kimse yok mu

korkuyorum

çökelip

karanlığı kabullenecem

korkuyorum

ölüm öncesi ölüm', 'Dünya dört duvar oda bağırıyorum kimse yok mu kimse yok mu korkuyorum çökelip karanlığı kabullenecem korkuyorum ölüm öncesi ölüm...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/dort-duvar-oda-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boşluk', 'bosluk-musa-eker-18l5u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Mecalsiz yarınlar

ve simsiyah düş...

Elleri çocukça kaybolan ben

ve şahidi korkusuz yüreklerin 

kocaman kocaman çocuklar

ve korkusuz yürekleri...

Hay senide...

Senide kahretsin felek.

Eyvallah eylül

Karanlığında bulutların

ve mahmurluğunda sabahın

Eyvahına yandığım

Kaç hüzün daha gelecek kapına? 

Yürü bre...

Yürü de ense tıraşını görsün yıllar

Sersemliği geçecek bu anın

ve dinecek elbet göz yaşların...', 'Mecalsiz yarınlar ve simsiyah düş... Elleri çocukça kaybolan ben ve şahidi korkusuz yüreklerin  kocaman kocaman çocuklar ve korkusuz yürekle...', ARRAY['Türk Edebiyatı','Şiir','Musa Eker']::text[], 8.5, '{"poet":"Musa Eker","poet_slug":"musa-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/bosluk-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçarı', 'ucari-musa-eker-5wnry', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Dünyalar tatlısı biricik Hacere

Kuytusundayım karanlıkların

Ellerin geliyor aklıma; çıldırıyorum

Yok çağırma beni böyle git dercesine

Al senin olsun yalancı aşkımız

Ben senin olmaya

Sana kalmaya gidiyorum...', 'Dünyalar tatlısı biricik Hacere Kuytusundayım karanlıkların Ellerin geliyor aklıma; çıldırıyorum Yok çağırma beni böyle git dercesine Al sen...', ARRAY['Türk Edebiyatı','Şiir','Musa Eker']::text[], 8.5, '{"poet":"Musa Eker","poet_slug":"musa-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ucari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarkın', 'yarkin-elif-gultekin-46yvb', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bakışların insin kalbime

Gözlerinden.

Aşkınla dolsun

Her bir sözcüğün.

Seni seviyorum derken, 

Dudakların sevgi dolsun.

Görmeliyim, 

Gözlerin yaşarmalı

Ölebilmelisin sevgi uğruna

Sessizce bakarken sahilden bana 

Öpebilmeliyim seni doyasıya...

Kuşlar uçar, 

Gün biter, 

Belki unutursun sevdiğini beni...

Dolunaylı gecede, 

Aşkım dolsun yüreğine, 

Gözlerin hep orada olsun, 

Gökyüzünde...

Bu sahil, bu kuşlar

Telefonum çalmayı bekliyor.

Herkes susmuş

Bir sen bir ben varım sahilde

Konuşmanı bekliyor yüreğim

Bekletme artık yeter

Ölmek üzereyim artık gel...', 'Bakışların insin kalbime Gözlerinden. Aşkınla dolsun Her bir sözcüğün. Seni seviyorum derken,  Dudakların sevgi dolsun. Görmeliyim,  Gözleri...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/yarkin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekinin Türküsü', 'ekinin-turkusu-hakki-varoglu-nexg8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Başağımızdan ayırdılar birer

Toprağın kara bağrına saçtılar bizi

Korkmadık, yılmadık, direndik

Ulaşmak için ışığa

Kök saldık sürgün verdik

Ne güzeldi

Güneş hava su

Ve ne tavlıydı toprak anamız

Bulutlardan aldık suyumuzu yeşerdik

Ilık bahar yelleriyle göverdik

Nisanda tanelendi başaklarımız

Onurlandık dağlar gibi dimdik

Yerle gün arasına dizildik

Mayısta altın sarısı başaklardık

Olgunlaşıp eğildik

Biçtiler bizi demet demet

Savurdular yığın yığın tane tane

Gözellerden eleklerden geçirip elediler

Bitmedi sevda yüklü çilemiz

Değirmen taşıyla başımızı ezdiler

Yıllar asırlara inat adımızı emek koyduk

Şimdi sofranızda bir dilim ekmek olduk

Bir sarı saçlı kızın öyküsüdür bu

Ekin tarlasında başakların türküsüdür bu

Aziz olmak istersen gülüm

Bir damla su ol berrak ve duru

Öfkeni şimşeklerden sesini gök gürültüsünden al

Sonra dağ başında bir kaynak ol uyu

Toprak kurumuşsa boynunu bükmüşse ekincikler

Uyan salın coş

Yeni başaklar yaratmaya koş

Bir sarı saçlı kızın öyküsüdür bu

Ekin tarlasında başakların türküsüdür bu

Umut olmak istersen gülüm

Bir demet ışık ol aydınlık ve sıcak

Gücünü güneşlerden öcünü karanlıklardan al

Dağıt şavkını aya yıldıza dünyamıza

Isıt toprağı uyansın ekincikler

Sevdasını söylesin göğe başı dik

Ekildik biçildik ezildik

Ama yenilmedik

Bir sarı saçlı kızın öyküsüdür bu

İmbiklerden süzülmüş umudun türküsüdür bu

Sevgi olmak istersen gülüm

Bir kaya ol dağ başında

Ko yel üfürsün sel götürsün seni

Parçalasın unufak toprak yapsın bedenini

Sevdanı dağlara kinini sulara sal

Gör bak renk renk çiçekler çıkacak topraktan

O zaman ineğin memesinde süt

O zaman arının peteğinde bal

Hoşçakal sarı saçlı kız

Altın sarısı başak hoşçakal

Unutma azizim

Unutma umudum

Sevgilim unutma

Ekilip biçiliyorsa toprak

Ve durmadan doğuruyosa analar

Korkma gülüm

Ne zulüm kazanır

Ne de ölüm

                                              21 Mart 2001  Newroz

                                                           Ha-Va', 'Başağımızdan ayırdılar birer Toprağın kara bağrına saçtılar bizi Korkmadık, yılmadık, direndik Ulaşmak için ışığa Kök saldık sürgün verdik N...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Varoğlu']::text[], 8.5, '{"poet":"Hakkı Varoğlu","poet_slug":"hakki-varoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":63,"source_url":"https://www.antoloji.com/ekinin-turkusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kişiye Bir Dünya', 'i-ki-kisiye-bir-dunya-hakki-varoglu-bmfa7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İki kişiydiler

Önlerinde bir gazete

Kız reklamları okuyordu

Oğlan kızı

İki kişiydiler

Önlerinde bir duble

Kız birasını içiyordu

Oğlan kızı

İki kişiydiler

Önlerinde bir tabak

Kız balığını yiyordu.

Oğlan kızı

                                     20 Mayıs 1993-Sinop

                                               Ha-Va', 'İki kişiydiler Önlerinde bir gazete Kız reklamları okuyordu Oğlan kızı İki kişiydiler Önlerinde bir duble Kız birasını içiyordu Oğlan kızı İ...', ARRAY['Türk Edebiyatı','Şiir','Hakkı Varoğlu']::text[], 8.5, '{"poet":"Hakkı Varoğlu","poet_slug":"hakki-varoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/iki-kisiye-bir-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boya Fırçası', 'boya-fircasi-bettie-youngs-m93m9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'fırçam hep yanımdadır

gittiğim bir yerde kendimi

gizlemem gerekebilir diye

size gerçek beni göstermekten

çok korkuyorum

yapacaklarınızdan korkuyorum

belki güler belki kaba şeyler söylersiniz

sizi kaybetmekten korkuyorum

aslında kendimi gizlemek değil

size gerçek beni göstermek istiyorum

ama anlamaya çalışmanızı da istiyorum

gördüğünüz ne ise

onu kabul etmenize ihtiyacım var

eğer sabırlı olur ve gözlerinizi kaparsanız

üzerime sürdüğüm bütün boyaları silerim

lütfen gerçek beni göstermenin

ne kadar zor olduğunu anlayın

işte şimdi bütün boyaları sildim

kendimi çıplak ve basit hissediyorum

hem de üşüyorum

bu gördüklerinize rağmen beni seviyorsanız

benim arkadaşımsınız

saf altın kadar katıksız

ama yine de boya fırçamı yanımda taşımalıyım

elimin altında olmalı

beni anlamayan birilerine rastlarım diye

sevgili arkadaşım  lütfen beni koru

beni içten sevdiğin için teşekkür ederim sana

ama izin ver boya fırçam yanımda kalsın

ben de kendimi sevene kadar.', 'fırçam hep yanımdadır gittiğim bir yerde kendimi gizlemem gerekebilir diye size gerçek beni göstermekten çok korkuyorum yapacaklarınızdan ko...', ARRAY['Türk Edebiyatı','Şiir','Bettie Youngs']::text[], 8.5, '{"poet":"Bettie Youngs","poet_slug":"bettie-youngs","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/boya-fircasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gemi', 'gemi-orhan-seyfi-orhon-vhqt1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sahilden uzaklaşan, 

Yüce dalgalar aşan

Beyaz kanatlı gemi.

Şimdi bocalıyarak

Götürüyor pek uzak

Bir yere sevdiğimi.

Ey gemi, senin için

Bir tek acı söz demem.

Ağlarım için için, 

Şikayetler edemem.

Dilerim ki: Şu deniz; 

Korkusuz, tehlikesiz

Geçilen bir yol olsun! 

Kolların ufka açık; 

Yürü, enginlere çık; 

Rüzgaların bol olsun! 

Gerçi sendin, bu sabah, 

Ayıran ikimizi.

Fakat yine sensin, ah, 

Kavuşturacak bizi!', 'Sahilden uzaklaşan,  Yüce dalgalar aşan Beyaz kanatlı gemi. Şimdi bocalıyarak Götürüyor pek uzak Bir yere sevdiğimi. Ey gemi, senin için Bir...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi Orhon","poet_slug":"orhan-seyfi-orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gemi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geri Dönemeyeceğim', 'geri-donemeyecegim-emre-altinok-seeid', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'gözyaşlarım resimlerimizde umutlarım hayalimizde

artık selam vermene gerek yok, geri dönemeyeceğim

artık beni arama, çünkü sensiz cehennemdeyim

sevdamızı artık arama ne olur, geri dönemeyeceğim

hasretinle kavrulacağım geri dönemeyeceğim

birleşsek te bi yerlerde buluşamayız. çünkü sensiz cehennemdeyim

günahlarımı artık yakma çünkü sensiz cehennemdeyim

günahlarımı artık yakma bebeğim geri dönemeyeceğim.', 'gözyaşlarım resimlerimizde umutlarım hayalimizde artık selam vermene gerek yok, geri dönemeyeceğim artık beni arama, çünkü sensiz cehennemde...', ARRAY['Türk Edebiyatı','Şiir','Emre Altınok']::text[], 8.5, '{"poet":"Emre Altınok","poet_slug":"emre-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/geri-donemeyecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Peri Kızı ile Çoban Hikayesi', 'peri-kizi-ile-coban-hikayesi-orhan-seyfi-orhon-qt0ew', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok eski zamanda, 

- Oğuz Han Hükümdarmış. -

İşitmiştim Turan''da

Bir peri kızı varmış.

Bu nazlı peri kızı, 

Bu güzellik yıldızı, 

Her gönülde bir sızı

Bırakarak yaşarmış.

Issız dağlarda gezer, 

Yokmuş izinden eser, 

Bazen göründüğü yer, 

Bir sihirli pınarmış.

Yüzü penbe bir şafak, 

Gülse güller açacak...

Yaşarmış Elden uzak, 

Dostları çobanlarmış.

Bu kız öyle güzel ki: 

Çıldırtır aşkı belki.

O kadar muhayyel ki: 

Akıllara zararmış.

Cefa imiş adeti! 

Hiç yokmuş merhameti.

Sevmeyen bu afeti, 

Sevenden bahtiyarmış.

Vururlurmuş kalbinden, 

Bir kere onu gören, 

Aşıkları tahminen, 

Gür saçları kadar mış.

Gençlerin yüzü solmuş, 

Gözleri yaşla dolmuş.

Aşkı bir afet olmuş, 

Bütün cihanı sarmış...

Ulu Hakan Oğuz Han, 

Bu kızı merak eder, 

Görmek ister yakından.

Çağırtır yanına.. Der: 

Sevimli kız, güzel kız! 

Dağ başlarında yalnız

Yaşıyorsun, bu neden? 

Bu güzelliğinle sen

Bir sihirli güneşsin! 

Sevimli kız, güzel kız! 

Tek yaratmaz, Tanrımız

Kimseyi tabiatte.

Var bir eşin elbette, 

Sen de birine eşsin! 

Kız, böyle tek yaşamak

Yaraşır mı -hele bak! -

Senin gibi güzele? 

Gel, karış artık ''El''e; 

Neslimiz güzelleşsin! 

Kız der ki: Ulu Hakan, 

Ben de sevdim bir zaman.

Vaktile genç bir çoban

Sevgilimdi, eşimdi; 

Yalnızım fakat şimdi.

Dağlarda bahtiyar, şen, 

Sevişerek yaşarken

Bir söz onu incitti; 

Bana darıldı gitti.

Ne kendi geldi geri; 

Ne duyuldu haberi..

İşte o günden beri

Hissizim, kayıtsızım; 

Tek yaşayan bir kızım.

Hakan -düşünür biraz-

Der: Bu doğru olamaz! 

Senin gibi güzel kız, 

Daima böyle yalnız, 

Dağ başında yaşar mı? 

Kız der ki: Çare var mı? 

Ben bir eşsiz güneşim, 

Gösterin nerde eşim? ..

Sevenler beni belki, 

Şu geniş göklerdeki

Yıldızlardan daha çok, 

Fakat istediğim yok.

İnanın buna siz de; 

Bulunmaz içinizde.

Hakan der ki: Ne zarar, 

Bulunmasa da, arar; 

Şüpheden kurtuluruz.

Sen cevap ver, buluruz

İstediğini belki...

Kız der: O halde peki! 

Kimlerse beni seven, 

- Haber verin şimdiden -

Deneyim onları ben

Bir sihirli oyunla.

İçlerinden bana kim

Cevap verirse.. benim

O, olacak sevdiğim; 

Ben yaşarım onunla! 

Bu haber, dalga dalga

Dağılır ortalığa.

Aşıklar; uzak, yakın

Yollardan akın akın

Gelirler.. zavallılar, 

- Hep birden genç, ihtiyar -

Kapılıp ümitlere: 

Toplanırlar bir yere.

Peri kızı, güzel kız; 

Ufka doğan bir yıldız

Gibi, yüksek bir gurur

İçinde gelir, durur.

Silkinince ansızın, 

Değişir şekli kızın: 

Kuş olur, çiçek olur, 

Bazı kelebek olur.

Bir gül olur açılır, 

İnci olur saçılır...

Bir buluta bürünür; 

Bin şekilde görünür..

Aşıkları hep birden, 

Şaşırıp kalır buna..

Bulunmaz cevap veren

Bu sihirli oyuna.

Kız: ''Artık ne çare! '' der; 

Hakana veda eder.

Ayrılacağı zaman; 

Ta uzaktan bir çoban

-Gözleri dolu yaşla-

Helecanla, telaşla

Koşar; huzura girer: 

''Ruhsat olursa eğer, 

''Taliimi deneyim! 

''Sormayın; kimim, neyim..

''Bir sevda havasile, 

''Bir hicranın yasile, 

''Aşarak yüce dağlar, 

''Gezerken diyar diyar; 

''Ansızın bu haberi

''Duyunca döndüm geri.

''Bir sevinçli duyguya

''Kapıldım.. gönül bu ya! 

Hakan der ki o zaman: 

Küstahlık etme çoban! 

Bu kız senin ufkuna

Doğacak güneş değil.

Bir zavallı çobana

Layık olan eş değil.

Doğrusu şu teklifin

Bu peri kızı için

Bir lekedir, bir züldür.

Kız der: O da gönüldür, 

İncitmeyiniz sakın, 

Ben razıyım bırakın.

Dururlar kızla çoban

Karşılıklı o zaman.

Silkinince ansızın, 

Değişir şekli kızın: 

Kuş olur; uçup konar

Hakanın otağına.

Çoban bakar, ah eder; 

O da bu sihri meğer

Biliyormuş eskiden.

Bir kafes olur hemen, 

Bu güzel kuşu alır, 

O anda kucağına.

- Bu birinci imtihan.

Bunu kazandın çoban! 

Kuş silkinir ansızın, 

Değişir şekli kızın: 

İnci olur bu sefer.

Saçılır birer birer

Hakanın ayağına.

Kafes te her yerinden

Dağılıp düşer hemen; 

Bir sedef olur, alır

İnciyi kucağına.

- Bu ikinci imtihan.

Adın ne senin çoban! 

İnci yanar ansızın, 

Değişir şekli kızın: 

Her inci bu sefer de

Bir başka çiçek olur.

Canlanır hemen, yerde

Boş kalan sedefler de

Birer kelebek olur.

Bir yanda, öyle renk renk

Açılırken çiçekler; 

Bir yanda, titreşerek

Dolaşır kelebekler..

- Bu sonuncu imtihan.

Tanıdım seni çoban, 

Anladım şimdi kimsin! 

Sen, beni ta eskiden

Sevip sonra terkeden

Vefasız sevdiğimsin.

Bunu artık iyi bil: 

Eş olmam mümkün değil

Sen gibi vefasıza.

Çoban; gözünde yaşlar, 

O zaman nakle başlar

Macerasını kıza: 

''Sevda, o bir peridir, 

''Karar etmez yerinde.

''Gönül ki serseridir, 

''Dolaşır izlerinde.

''Sevda, o gizli bir ok, 

''Görünmez kanatmadan.

''Kavuşmanın tadı yok, 

''Ayrılığı tatmadan.

''Ben ki, pek çok ağladım, 

''Gezdim hicrana giden

''Yolları adım adım.

''Beni artık yeniden

''Hicrana atma, güzel, 

''Yeter ağlatma, güzel! 

''O her derde tahammül

''Gösteren deli gönül; 

''Kah eder dünyaya naz, 

''Her dakika bulunmaz

''Bir halde, bir kararda.

''Sevdiği zamanlarda

''Gül yaprağından ince! ..

''Bir sitem işitince

''Yaralanır derinden, 

''İncinir her yerinden.

''Bir gündü.. yandı içim; 

''Dağıldı hep sevincim...

''Elveda artık! ..'' Dedim.

''Tahammül edemedim

''Bir söze, bir siteme.

''Düşün ki: Terketmeme, 

''Yine aşkımdı sebep.

''Serseri, dünyayı hep

''Dolaştım adım adım; 

''Bir teselli aradım.

''Bulamadım kimsede.

''Bir günah ettimse de, 

''Şimdi işit ahımı, 

''Bağışla günahımı

''Düştüğüm aşka, güzel! 

''Sebep yok başka, güzel! 

''Deniz geçtim, dağ aştım; 

''Haylı sene dolaştım, 

''Bahtım kara, saçım ak, 

''Ne şekle girmişim bak! 

''Başımın tacı güzel, 

''Halime acı güzel! 

Oğuz Han: Artık yeter; 

Bu gamlı sözlerle, der, 

Beni ağlatacaksın! 

Şüphe etme ki çoban, 

Sevdiğinin her zaman

Affına müstahaksın! 

Var mı kızım, sen de bak, 

Bir başka eş olacak

Senin gibi güzele! 

Elverir bu ayrılık! 

Gelin birleşin artık! 

Haydi verin elele! 

Geçsin neşe, eğlence

İçinde hep gününüz! 

Tamam kırk gün, kırk gece

Yapılsın düğününüz.

İşte hemen o günü

Başlayan bu düğünü

''Felek'' dedikleri pir

Görünce, girmiş denir

Yeniden bir yaşıma! 

Bu düğün öyle uzun, 

Sevinçli bir düğün ki; 

Bu, o şerefli gün ki: 

Darısı yurdumuzun

Güzelleri başına!', 'Çok eski zamanda,  - Oğuz Han Hükümdarmış. - İşitmiştim Turan''da Bir peri kızı varmış. Bu nazlı peri kızı,  Bu güzellik yıldızı,  Her gönüld...', ARRAY['Türk Edebiyatı','Şiir','Orhan Seyfi Orhon']::text[], 8.5, '{"poet":"Orhan Seyfi Orhon","poet_slug":"orhan-seyfi-orhon","theme":"Türk Şiiri","is_hero":false,"total_lines":267,"source_url":"https://www.antoloji.com/peri-kizi-ile-coban-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yokluğunu Sevdim', 'yoklugunu-sevdim-sair-cakar-eli2r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'gittiğin gün senin için ağladım

gittiğine

ilk ve son defa, 

seni ilk buluşum

ve son kaybedişimdi bu

kayboldun

bilirsin ''seni mi yoksa yokluğunu mu seviyorum? ''

evet yine yokluğunu sevdim

yok olmanı

sen yokken ben resmini sevdim

gülümseyen, hüzünlü

bana bakan gözlerini

tenini kokladım

geride bıraktığın eşyalarından

ve yerine

yastığa sarıldım sımsıkı

sıcaklığından

ter içinde kalarak 

yapamadıklarımızı yaptım, sensiz; 

bardaktan boşalırcasına yağan

nisan yağmurları altında yürüdüm

ayaklarım çıplak

yalnız

şarkılarımı haykırdım

komşu kadının çığlıklarına karışan

ve, dağlara verdim kendimi

yıldızlara biraz daha yakın, 

sana uzak

ama sana dost

belki binlerce ''seni seviyorum'' cezası verdim

sayfalar dolusu

defterime karaladığım

söyleyemediğim

bilirsin yokluğunu sevdim

yok olmanı

gecenin bilmem bir vakti

sen uyuyorsun, ben

ders çalışıyorum, mum ışığı altında

malum

elektrikler kesik

bitirme sınavları..

başımı bir an kaldırıp

notlarımdan

senin gözlerinle buluşuyor gözlerim

dudaklarım, ellerim

tenim

herşeyim.

bitirme sınavları

bitirme

bitiş.

ama sen uyuyorsun, olsun

bu benim hayalim

dedim ya

ben senin yokluğunu sevdim

yok olmanı

(1998)', 'gittiğin gün senin için ağladım gittiğine ilk ve son defa,  seni ilk buluşum ve son kaybedişimdi bu kayboldun bilirsin ''seni mi yoksa yokluğ...', ARRAY['Türk Edebiyatı','Şiir','Şair Çakar']::text[], 8.5, '{"poet":"Şair Çakar","poet_slug":"sair-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/yoklugunu-sevdim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezsin', 'bilmezsin-necmettin-davulcu-sjv79', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yağmurlar şahit

ben ağlayamam

içime gömerim seni

dağlar bilir beni

gece gibi koynumda sakladıklarımı

saçlarının her bir teline

bir yürek bağladığımı

gözlerindeki her ışıltıya

gökten yıldız kaydıracağımı

gülüşünle yüreğimde

kopardığın her fırtına

rüzgar ağaçlarında dinginleşir

ve örter üstünü yüreğim

sen bilmezsin

sen bilmezsin dağlardaki kuytu çağlayanları

bilmezsin her damlasında

yüreğime  bir parçanı gömdüğümü

bilmezsin', 'yağmurlar şahit ben ağlayamam içime gömerim seni dağlar bilir beni gece gibi koynumda sakladıklarımı saçlarının her bir teline bir yürek bağ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/bilmezsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Canımın Yaprakları', 'canimin-yapraklari-kayahan-acar-4ltqp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bugün....  uyandığımda yoktun yanımda

Canım...   bugün ilaçlarımı almadım..

Bugün;  ne kadar alışmışım anladım

Canım;   bugün ilk defa sensiz kaldım....

Güller.....      denize bakıyor günlerdir, 

Güller;  güneşi özlüyor sensiz....

Canım, Canımın Yaprakları gözlerin yok! 

Çok canımı yakıyor.... özlemin..

Çook çook çok! 

Her şeyden çok! 

Sönmeyen ateşlerde günahlarım yanıyor

Bıraktığın bu yerde hayallerim ağlıyor ah! 

Canım....   mahvediyor karanlıklar

Sönmeyen ateşlerde günahlarım yanıyor

Bıraktığın bu yerde yüreğim kan ağlıyor ah! ...

Canım....   Mahvediyor karanlıklar..

Her şeyden çok! ....', 'Bugün....  uyandığımda yoktun yanımda Canım...   bugün ilaçlarımı almadım.. Bugün;  ne kadar alışmışım anladım Canım;   bugün ilk defa sensi...', ARRAY['Türk Edebiyatı','Şiir','Kayahan Acar']::text[], 8.5, '{"poet":"Kayahan Acar","poet_slug":"kayahan-acar","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/canimin-yapraklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmezsin 2', 'bilmezsin-2-necmettin-davulcu-gq4sv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'atabilsem sevdamı uçurumlara

ateşlerde yakabilsem

savursam külleri rüzgara karşı

olmuyor

sevdam dağlara

sevdam yollara

çok uzaklarda sen

sarı saçlarından suçlu değilsin

çaresizliğim senden

çarem sen

korkularım doyumsuz

sensizliğim diz boyu

gecelerimde sen vardın

sesin sevgimdi

sevgim gülüşün oldu

sarı saçlarında asılıydı yaşam

rüzgar rüzgar olurdu gecelerim

bir sevda bulutu geçerdi düşüncelerimden

haykırsam duyacak gibiydin

ateşe keserdi her bir parçam

yüreğim yangın yeri

bilirsin 

bilmezlenirsin', 'atabilsem sevdamı uçurumlara ateşlerde yakabilsem savursam külleri rüzgara karşı olmuyor sevdam dağlara sevdam yollara çok uzaklarda sen sar...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/bilmezsin-2-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağların Ardı', 'daglarin-ardi-necmettin-davulcu-i9t13', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dağların ardında sevda nehirleri var

ayaz geceler üşütmez seni oralarda

oralarda kır çiçekleri bezemiş yolları

gör desem sarı saçlım görecekmisin

yediverenler açmış sabah çiği içinde

rüzgarlar sarmış dört yanı ayaz gecelerde

bulut tadında sevdalar yaşanırmış oralarda

sar desem sarı saçlım saracakmısın

kaybolan gecelerim geri gelmeyen gençliğim

hüzün dolu yaşam sensiz günlerim de var

yaşayamadığım duygular gözlerinde eriyen umutlar

bul desem sarı saçlım bulacakmısın

(08/09/2000)', 'dağların ardında sevda nehirleri var ayaz geceler üşütmez seni oralarda oralarda kır çiçekleri bezemiş yolları gör desem sarı saçlım görecek...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/daglarin-ardi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarın', 'yarin-necmettin-davulcu-njn73', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'uzaktan sevdim seni

çok uzaktan

tutmadan ellerini

cismin hiç yokken daha

sözcüklerinin ağırlığı omuzlarımda

gülüşünü gördüm sözlerinde

ve ağlarken sen gizlice

umutsuzluğunun duvarları arkasında

söyleyebilirmiydim diye düşünüyorum

anlamazsan beni

bilemezsen esintilerimi

yarın sana geleceğim

tutmaya ellerini

saçlarını koklamaya

bir gülüşüne kurban olmaya

gözlerindeki her ışıltıya

saçlarının her teline gökten yıldız bağlamaya

yarın umutsuzluğumun son günü

yarın sensizliğin bittiği yer

yarın', 'uzaktan sevdim seni çok uzaktan tutmadan ellerini cismin hiç yokken daha sözcüklerinin ağırlığı omuzlarımda gülüşünü gördüm sözlerinde ve ağ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yarin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavgam Dağlara', 'kavgam-daglara-necmettin-davulcu-r39yk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'doyamadım sana hasretim

gökler ağlasa sel olup aksa

toprak yutar hasret bitmez

sesinle sen hasretimsin

sen yokken seni aradım hep

gelse dedim

konuşsa dedim benimle

dinginliğim geçer hasret biter dedim

yanılmışım

duyduğumda sesini

daha da kabardı yüreğim

dağlara sığmaz oldu hasretim

bildim ki benden büyük

sığmaz hiçbir yere

gün geçecek

günler akacak

günlerce büyüyecek sevdam

ve hasretim

ve hiçbir kavuşmada sana çağlayamayacak

sevdam hasretime koca bir engel

sen sevdama karşı

sevdam benden önde

sen yanımdasın

ellerimi uzatıyorum

ama ulaşamıyorum

kavgam dağlara

kavgam sarı saçlarına

kavgam seninle sensizliğime', 'doyamadım sana hasretim gökler ağlasa sel olup aksa toprak yutar hasret bitmez sesinle sen hasretimsin sen yokken seni aradım hep gelse dedi...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/kavgam-daglara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Karanlık', 'ay-karanlik-necmettin-davulcu-1z1qq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ay karanlık gel yıldızım ol bu gece

sen orda çığlık çığlığa

ben burda suskunlardayım

gönül düştü bir yangına

gül dalında diken misali

al batır beni canına

ay karanlık

ıssız gecelerdeyim

sen yoksun ki

sen gelmedin ki

kış baharı neyleyim

ay bakışlım sevdiceğim

dilimde türkü oldun

ay ışığım yıldızımsın

sevdam oldun içime doldun

sen nerdesin ben nerdeyim

ay karanlık

penceremde yoksun sen', 'ay karanlık gel yıldızım ol bu gece sen orda çığlık çığlığa ben burda suskunlardayım gönül düştü bir yangına gül dalında diken misali al bat...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ay-karanlik-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeditepeli Şehrin Gülü', 'yeditepeli-sehrin-gulu-necmettin-davulcu-48rza', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yeditepeli şehrin sarı gülü

sevdamı anlatsam anlamazsın

hüznümü anlatsam çağlamazsın

bilmezsin yüreğimi

çaresizliğimde sen varsın

çarem değilsin

ben seni sevdim

sevdalandım

bir gülücük

bir yeşil göz

ahhhhh o sarı saçlarından sen suçlusun

bulut olup yağsam

güneş olup yaksam

sel olup yıksam sevdamca büyük

sen çıkarsın karşıma

ben seni sevdim çok uzaktan

sevdim sevdalandım sarı saçlım

sevdalım

yeditepeli şehrin sarı gülü', 'yeditepeli şehrin sarı gülü sevdamı anlatsam anlamazsın hüznümü anlatsam çağlamazsın bilmezsin yüreğimi çaresizliğimde sen varsın çarem deği...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/yeditepeli-sehrin-gulu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlıksız', 'basliksiz-necmettin-davulcu-ffx3a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sevda türküleri söyler yüreğim

başımda esen kavak yelleri

bir yanım yosun tutmuş paramparça

güzgüllerinin baharsı tadı bir yanım

sevdam benden uzak ben ondayım

koşarken yaşam dolu dizgin benden uzağa

yüreğim ağlar sen ağlarsın ben ağlarım

uzaklarda bir yerde kopar yaşam birden', 'sevda türküleri söyler yüreğim başımda esen kavak yelleri bir yanım yosun tutmuş paramparça güzgüllerinin baharsı tadı bir yanım sevdam bend...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/basliksiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herşey Güzel', 'hersey-guzel-necmettin-davulcu-o6qk5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şimdi herşey güzel bir tanem

sevdalar diz boyu

umutlar uçuşuyor kuşlarla kolkola

geleceğin gizini bilmeden

tatlı bir heyecanla doluyuz

öyle tatlı ki

sesinde tüm renkleri

sesinde kokuları

sesinde sevdamı buluyorum

yorgunluklarım diniyor birden

birden kuş oluyorum

sende buldum yaşamı

yaşamın renklerini

renklerin cümbüşünü

ayrılırsak bir gün

sen hep yüreğimde olacaksın', 'şimdi herşey güzel bir tanem sevdalar diz boyu umutlar uçuşuyor kuşlarla kolkola geleceğin gizini bilmeden tatlı bir heyecanla doluyuz öyle ...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Davulcu']::text[], 8.5, '{"poet":"Necmettin Davulcu","poet_slug":"necmettin-davulcu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hersey-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Derinde Bile', 'en-derinde-bile-ozgur-kale-j1wln', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En derinde bile yokken  gökyüzünün rengi, 

Şiirlerin seslenmelerinden bile kaçarken, 

Ölüm basit geliyormuş kovalanırken...

Hayallerin arkasından gelen ölüm, 

Gözlerdeki ateşin de körükleyicisiymiş

Uçurumun derin olduğu yerde bile....', 'En derinde bile yokken  gökyüzünün rengi,  Şiirlerin seslenmelerinden bile kaçarken,  Ölüm basit geliyormuş kovalanırken... Hayallerin arkas...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/en-derinde-bile-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülüyorum', 'guluyorum-ozgur-kale-rmbkl', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Uzaklığın artık iki kat artacak, 

Ben de sanırım başka dünyalara uçmuş olacağım, 

Ama gözlerini unutmayacağıma emin olabilirsin, 

Hep aldanışlardı ama olsun...

Gülüyorum  şimdi...

O kadar zamanı harcadık, gitti....

Düşünsene birlikte olsaydık, 

Sence dolu mu olacaktı, 

Ondan da emin değilm ya, 

Gülüyorum şimdi.....', 'Uzaklığın artık iki kat artacak,  Ben de sanırım başka dünyalara uçmuş olacağım,  Ama gözlerini unutmayacağıma emin olabilirsin,  Hep aldanı...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guluyorum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fal', 'fal-bekir-sitki-erdogan-z5cfq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen karşıma, her özlediğim anda çıkarsın! 

İzmir''de çıkar; Kars''da çıkar, Van''da çıkarsın...

Hiç böyle vefa görmedi alemde hakikat; 

Yollar kapanır, sen yine fincanda çıkarsın!', 'Sen karşıma, her özlediğim anda çıkarsın!  İzmir''de çıkar; Kars''da çıkar, Van''da çıkarsın... Hiç böyle vefa görmedi alemde hakikat;  Yollar ...', ARRAY['Türk Edebiyatı','Şiir','Bekir Sıtkı Erdoğan']::text[], 8.5, '{"poet":"Bekir Sıtkı Erdoğan","poet_slug":"bekir-sitki-erdogan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/fal-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-ahmet-ferit-cosan-kz08j', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Olacak her şey

Olmasın dünyadaki

Yerlerine olmayacaklar olsun.

Aşık ol bana

Sevme sevdiğini

Ölmesin insanlar

Doğmasın bebekler 

Gebe kalmasın kadınlar

Dünya bize yeter.', 'Olacak her şey Olmasın dünyadaki Yerlerine olmayacaklar olsun. Aşık ol bana Sevme sevdiğini Ölmesin insanlar Doğmasın bebekler  Gebe kalması...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayal-14-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-ahmet-ferit-cosan-kfi53', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yapılmazı yapar yağmur, 

Ruhları temizler.

Hayat verir bizlere 

Toprağa yaptığı gibi.

Yağmur, umutları yeşertir, 

Şarkılar söyletir insana.

Bir garip sarhoştur insan yağmurda

Öyle ki uçacak gibi olur, uçamaz; 

Koşacak gibi olur,  koşamaz; 

Sevecek gibi olur, sevemez.

Bir ateş yakmak ister insan 

Büyük bir ateş, öyle ki

Tek lokmada yutuversin bütün kenti.

Ama tutuşturamaz ki en ufak kibriti.

Bir garip his dolanır yağmurda

Bir garip sarhoştur insan

Ama, daha doyamadan

Yağmur diniverir güzel duyguların ardından.', 'Yapılmazı yapar yağmur,  Ruhları temizler. Hayat verir bizlere  Toprağa yaptığı gibi. Yağmur, umutları yeşertir,  Şarkılar söyletir insana. ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yagmur-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Hiç Unutmadan Yaşlanan Yalnızlığım', 'seni-hic-unutmadan-yaslanan-yalnizligim-gultekin-gulses-bixws', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanırdım seni küçük kız

Hani ben daha çocukken

Sabahların soğuk gölgelerinden kaçıp

Ilık güneşlere sığınarak birlikte giderdik okulumuza

Hatırlıyormusun nasıl da coşkulu 

Ve ciyak ciyak koşardık zille beraber

Top oynar, ip atlardık sonra

Hani o küçük yazılılarda nasıl da atardı

Yüreğimiz pır pır

Hatırlıyormusun ''ANNE'' kelimesini

Büyük harfle yazdığın için 

Kırık not aldığın günü

Küçük ''ANNESİZ'' kız

O sonbahar günü uçuşuyordu

Yine güneşli saçların

Hep aklımda kaldığı gibi

Yeniden bulutlanmıştı gökyüzü gözlerin

Ardından gelen sağanağın habercisi

Annemin seni her öpüşünde

Ağladığın gibi.

O ayyaş baban her dövdüğünde

Bize kaçardın hatırlıyormusun

Tombala oynardık, evcilik salatası bile

Yapardık bazen tarifi ikimizin sırrı

Sonra bir büyümeler aldı bizi

Ayırdı küçücük mutlulullarımızdan

Seni o adama verdiler

Bizi bize çok gördüler

Hatırlıyormusun arabaya binip

Gittiğin o günü

Bembeyaz gelinlikle 

Mezara gider gibi

Hani baktık birbirimize de konuşamadık

Kelimeler mantar gibi tıkandı boğazımıza

Sonra sen gittin gök gözlerinde

Yine aynı sağanakla

Ben büyüyen yalnızlığımda

Seni hiç unutmadan.

Bende hep 

Gökyüzü gözlü, güz saçlı

Küçük kız kaldın

Şöyle bir düşündüm de

Ne çok yaşlar akmış

Senden sonra gözlerimden

Oysa hiç kuruyup gitmesin istemiştim

O gün ki yaşlarım tenimden

Şimdi buruşuk yapraklar gibi

Ağır ağır iniyorum hayat merdivenini

Kara tren yaklaşıyor son durağına

Yıllar kırağı mı çaldı ne solgun saçlarıma? 

Artık ulaşıyorum özlemle hayatın anası toprağa

Yaşlanan yalnızlığımda seni hiç unutmadan.

Bursa-1990

Güz saclı', 'Tanırdım seni küçük kız Hani ben daha çocukken Sabahların soğuk gölgelerinden kaçıp Ilık güneşlere sığınarak birlikte giderdik okulumuza Hat...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Gülses']::text[], 8.5, '{"poet":"Gültekin Gülses","poet_slug":"gultekin-gulses","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/seni-hic-unutmadan-yaslanan-yalnizligim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Erkekler Yanlızken Ağlar', 'erkekler-yanlizken-aglar-abdullah-yildiz-1ng01', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Göremezsin gözyaşlarını, silemezsin

İçten içten ağlar, köşelerde ağlar

Duyamazsın hıçkırıklarını

Bilemezsin neden ağladığını

Anlayamazsın senin için ağladığını

Bak şu kançanağı gözlere

Hissediyormusun seni sensiz yaşamanın acısını

Yıkılmış umutların içinde

Virane gezen şu sarhoşun

Söyleyemediği aşk sözcükleriyle boşutuğunu

Görebiliyormusun kançanağı gözlerimde...

Yine ağlıyorum

Yapayalnız karanlık gecemde

Sensiz geçen sensizliğimde

Sen hala görmüyorsun

Çünkü; ben yanlızken ağlarım', 'Göremezsin gözyaşlarını, silemezsin İçten içten ağlar, köşelerde ağlar Duyamazsın hıçkırıklarını Bilemezsin neden ağladığını Anlayamazsın se...', ARRAY['Türk Edebiyatı','Şiir','Abdullah Yıldız']::text[], 8.5, '{"poet":"Abdullah Yıldız","poet_slug":"abdullah-yildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/erkekler-yanlizken-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Hikayesi', 'askin-hikayesi-berna-yasmut-x6xmt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'seni sevmek; 

bir gülün dikenini okşamaktan farksız.

bir gün bu sevgi kanatacak parmaklarımı

bir başıma kalacağım yapayalnız.

seni hissetmek; 

tanrıya yakarış ya da bir soruydu cevapsız.

ben çözemedim, bir de yoksun yanımda

bu şehir sensiz çok daha ıssız...

anlayamadığın sana sunduğum aşksa

gözlerime bak göreceksin.

orada aşkın hikayesi yazıyor; 

aşk kırmızı, aşk çılgın, aşk yalansız.', 'seni sevmek;  bir gülün dikenini okşamaktan farksız. bir gün bu sevgi kanatacak parmaklarımı bir başıma kalacağım yapayalnız. seni hissetmek...', ARRAY['Türk Edebiyatı','Şiir','Berna Yaşmut']::text[], 8.5, '{"poet":"Berna Yaşmut","poet_slug":"berna-yasmut","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/askin-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Monna Rosa -IV- Ve Monna Rosa', 'monna-rosa-iv-ve-monna-rosa-sezai-karakoc-20q1d', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Peygamber çiçeğinin aydınlığında ara

Sana doğru uzanan çaresiz ellerimi.

Sırrımı söylüyorum vefakar balıklara:

Yalnız onlar tutacak bu dünyada yerimi.

Koyverip telli pullu saçlarımı rüzgara,

Bir çocuğun ardına düşen heykellerimi

Peygamber çiçeğinin aydınlığında ara...

Bir çevre sağ elimden bulanık suya düştü

Ve boğazımı sıktı parmaklar ince, uzun.

Günahkar toprağıma saçından bir tel düştü; 

Sana ne olmuş Rosa, bir derde tutulmuşsun.

Bir ekmek kadar aziz fikirler böyle pişti:

Noel ağaçları ve manolyalar kahrolsun,

Bir çevre sağ elimden bulanık suya düştü...

Şu şapkayı çıkarıp atıyorum ırmağa; 

Her şeyim sizin olsun, hep sizin kesik başlar.

Rüyasında örümcek başlarsa ağlamağa,

İçine gül koyduğum tüfek ölmeğe başlar.

Günahını sırtına yüklenen kaplumbağa

Gibi ölüm önünde öz benliğim yavaşlar.

Öyleyse şu şapkayı fırlatayım ırmağa.

Bu erkekler kokuyu kediler gibi alır

Ve kediler her gece sürünür yastıklara.

Denizleri bahtiyar eden günler kısalır; 

Satılmayan çiçekler, zehirli ve kapkara,

Unutulmuş erkekler ve kadınlara kalır.

Bir geyiğin gözleri düşer eriyen kara

Ve erkekler kokuyu kediler gibi alır.

Ve yalnızlık, sigara külü kadar yalnızlık! 

Ve toprağın rüyaya yılan gibi girişi.

Sana da, Monna Rosa, taş bebeği bıraktık,

Ellerinde kılçıklı balıkların bir dişi.

Senin hatıran gibi büyük, yeni, karanlık; 

Senin hatıran kadar Allah ve şeytan işi...

Ve yalnızlık, sigara külü kadar yalnızlık! 

Bugün yalnız yağmura tahammül edeceğim; 

Ta boğazıma kadar çıkan deli yağmura.

Tüyüme horozdan çok itimat edeceğim,

İtimat edeceğim şu belalı yağmura.

Ruhuma bayrak yapıp ben teslim edeceğim

Asılmış bir adamın iki eli yağmura.

Bugün yalnız yağmura tahammül edeceğim.

Bir tren ışığına, güneşe çekmek seni

Ve bir şehir yaratmak, ruhundan Gülce diye.

Parçalanan gemiyi ve yırtılan yelkeni

Katıvermek sessizce söylenen bir türküye.

Ve sonra bir köşede öldürmek ölmeyeni

Ve son vermek bitmeyen, bu bitmeyen şarkıya,

Bir tren ışığına, güneşe çekmek seni.

Sana tavuskuşunun içime girdiğini

Son, en son söz olarak söylemek istiyorum.

İçime girdiğini, tüyünü yolduğunu

Son, en son söz olarak söylemek istiyorum.

İçimde tavusların bir bir kaybolduğunu,

Bana da bir çift ak kanat kaldığını

Son, en son söz olarak söylemek istiyorum.

Peygamber çiçeğinin aydınlığında ara

Sana doğru uzanan çaresiz ellerimi.

Sırrımı söylüyorum vefakar balıklara; 

Yalnız onlar tutacak bu dünyada yerimi.

Koyverip telli pullu saçlarını rüzgara.

Bir çocuğun ardına düşen heykellerimi

Peygamber çiçeğinin aydınlığında ara...

1952, Kış (Yılbaşı Gecesi)', 'Peygamber çiçeğinin aydınlığında ara Sana doğru uzanan çaresiz ellerimi. Sırrımı söylüyorum vefakar balıklara: Yalnız onlar tutacak bu dünya...', ARRAY['Türk Edebiyatı','Şiir','Sezai Karakoç']::text[], 8.5, '{"poet":"Sezai Karakoç","poet_slug":"sezai-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/monna-rosa-iv-ve-monna-rosa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sütünlar', 'sutunlar-turan-alptekin-9t4d1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Aynı yıldızların altındayız, 

Yüzyıllar geçmiş yaşamımızdan

Ruhlarımızı seyrediyoruz, 

Yan yana sütunlar gibi duran

Yankılarıyla vuruşlarının

Yeryüzünün uzak bir yerinde

Dalgalar gibi kıyıya doğru, 

Acının, insan bedenlerinde.

Bir yazgı oluyor bütün doğa, 

Birlikte soluduğumuz dünya

Yok oluşların var oluşunu

Nesnelerin sonsuz sayısınca, 

Bir uğuldayış, bir yakınlaşış, 

İçinde evrenin duyulduğu

Atardamarı bir dolaşımın, 

Bir yenilenişin sarhoşluğu.

Birlikte bir yürek oluyoruz; 

Yıkık sütunlar altında sanki

Bedenlerimizi arıyoruz, 

Var oluşların özünde gizli.

Aynı sütunlar altında şimdi

Oluşu tadıyoruz birlikte.

Bütünleyici gücü varlığın, 

Yaşamı ve doğayı bizlerle, 

Yeniliyor böylece; bu yüzden, 

Gözyaşı dolduruyor yaşamı; 

Bu yüzden yıldızlar sayısınca, 

Duyulan, insanın yalnızlığı.

Ey gözyaşından acılar doğan, 

Ölen güzelliklerin tanrısı, 

Bütün o sonrasız yaşamlara

Dağıtan sensin bu yalnızlığı; 

Parıltısıyla acının, dünya

Derinleşiyor yüreğimizde, 

Hava buluta dönüyor gibi, 

Buğulanıyor sevgi hüzünle.

Aynı sütunların altındayız, 

Yüzyıllar geçmiş yaşamımızdan; 

Sen saçlarına dokunuyorsun

Ve gökler aydınlanıyor o an, 

Ruhlarımızı seyrediyoruz, 

Acıyla, sevgiyle yükseltilen

Bir çığlık gibi göğe doğru

Bir zaman yaşanmış bir öyküden.

Sanki görülmemiş düşlerdeyiz, 

Hiç uyanılmayacak ve uzun; 

Birbirimizi anımsıyoruz, 

Çiçekler açışlarıyla ruhun.

Ey gözyaşından acılar doğan! 

		Yüzüme yağan nedir, 

                                Yoksa ağlıyor musun?', 'Aynı yıldızların altındayız,  Yüzyıllar geçmiş yaşamımızdan Ruhlarımızı seyrediyoruz,  Yan yana sütunlar gibi duran Yankılarıyla vuruşlarını...', ARRAY['Türk Edebiyatı','Şiir','Turan Alptekin']::text[], 8.5, '{"poet":"Turan Alptekin","poet_slug":"turan-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":51,"source_url":"https://www.antoloji.com/sutunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Bİr Taş Basma Resim Üzerine', 'eski-bi-r-tas-basma-resim-uzerine-turan-alptekin-piuq4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sözlerin gizlerinden

Girilen bir bahçede

Sonrasız çınarların

Altında yürüyoruz; 

Uçuşan yazılarla

Geçmiş yaşantılardan; 

Belki hiç yaşanmamış

Anlardan geçiyoruz, 

İnsanlar gölge gibi

Sessiz kımıldaşıyor, 

Ağır devinimlerle

Bir yere koşuyorlar.

Belki bir taş gömütün

Önünde duruyoruz

Elinde bir sunuyla

Bizden bir adım önde, 

Birinin soluğunu

Duyuyoruz birlikte.

Belki, hiç anlamadan

Birbirimizi, uzak

Ve tanımadığımız

Kentleri geziyoruz

Dalıp yüzlerimize.

Dünya bütünleşiyor

Bizimle ve bizlersiz.

Bir yokluğun içinden

Dönüp benliğimize

Sanki unuttuğumuz

Bir göğe doğuyoruz.

Sesler ve uğultular, 

Uzak bir yerde sanki, 

İçimizde bir yanı

Yan yana getiriyor; 

Güçleniyor gitgide, 

Uzun titreyişlerle, 

Çözülen insanların

Gönül bağlanışları.', 'Sözlerin gizlerinden Girilen bir bahçede Sonrasız çınarların Altında yürüyoruz;  Uçuşan yazılarla Geçmiş yaşantılardan;  Belki hiç yaşanmamı...', ARRAY['Türk Edebiyatı','Şiir','Turan Alptekin']::text[], 8.5, '{"poet":"Turan Alptekin","poet_slug":"turan-alptekin","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/eski-bir-tas-basma-resim-uzerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Veda Anı', 'bir-veda-ani-sabahattin-ozkan-s81h0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şahin’e

Bir şiir, bir şarkıdır dostun yüzünde

Açılır, okunur bize yürekler

Dizelerin, ezgilerin aydınlığında

Yol bulur öteye, özge dilekler

Evler ne canlıdır, susarken bile

Konuşur gönüller, kendi dilince

Ruh güler, ten güler o serinlikte

Döner kederlerin hemen sevince

Bulutlar ordusu yükselir durur

Uçar Torosların ufuklarından

Erguvan yaprağın ışığı vurur

İkindi vaktinin mor sularından

Kavuşma, göğsünü zorlayan kuvvet

Umuttur ayrılık, başka zamana

Bunalma, boğulma, terk-i diyâr et

Yolda bütün oklar kalplerden yana

Bir vedâ ânına uyanmak bile

Her  akşam, her seher, bir ufuk düşü

Yıldızlar tahtını geçiren ele

Ne yapsın altını, pulu, gümüşü? ..

Sen gittin, güneşin karardı yüzü

Hatırlamaz artık yangınlarımı

Dağlanmış bağrımda tuhaf bir sızı, 

Doldurmak istiyor yarınlarımı

                           11 Ağustos 1999, 

                               AYVAGEDİĞİ', 'Şahin’e Bir şiir, bir şarkıdır dostun yüzünde Açılır, okunur bize yürekler Dizelerin, ezgilerin aydınlığında Yol bulur öteye, özge dilekler ...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Özkan']::text[], 8.5, '{"poet":"Sabahattin Özkan","poet_slug":"sabahattin-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bir-veda-ani-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyledir', 'boyledir-sabahattin-ozkan-9s2x3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düştüm eteğine ki bir deli rüzgârın

Bir enginindeyim bir gölgesinde, bulutların

Boğuyor her ateşini feleğin öfke selleri; 

Nasıl dayansın, ömrü kelebek kadar umutların

Uyutur da beni saf gerdeninde tabiat ana

Uyanırım girdâbında düşsel boyutların

Kapansa tekmil kapılar, bin kapı açar Hudâ! 

Ne hükmü var ki mâverâda hudutların

Ezgisini güzeline söyletir, âşıkını ağlatır; 

Böyledir bu zamanda şölenleri yurtların

			Mersin,1996', 'Düştüm eteğine ki bir deli rüzgârın Bir enginindeyim bir gölgesinde, bulutların Boğuyor her ateşini feleğin öfke selleri;  Nasıl dayansın, ö...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Özkan']::text[], 8.5, '{"poet":"Sabahattin Özkan","poet_slug":"sabahattin-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/boyledir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gazel', 'gazel-zemci-cetinkaya-46vc8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu can bin kerre kurbandır hedef Subhan olan yerde

Ne yaksın âteş-i Nemrut bağ-ı iman olan yerde.

Bırak ehrâm-ı zulmüyle Kelîm''in hasmı kibretsin

Gururdan saltanat olmaz şakk-ı ummân olan yerde.

Çölün sonsuz serâbından niçin Mecnun habersizdir; 

Su istenmez, yemek yenmez dem-i hicrân olan yerde.

Saçın salmış, devâ olsun deyip derd-i derûnumda

Şifâsın beklemem zülfün leb-i cânân olan yerde.

Nigâh-ı yâre bir an vasl için bâzâr kurulmaz hiç, 

Bâhâsın sorma ey gâfil bu nâçiz can olan yerde.

Hezârın nağmesin susmaz gül-i terin firâkından

Baharlar neşve-yâb olmaz hemân hazan olan yerde.

Özün bilmek sevâbından beni ya Rab cüdâ kılma; 

Edeb dâim mukaddemdir ilim irfan olan yerde

Ümîdin kesme, Rehber menzilinden hiç uzak düşmez

Cemâl-i Yâr''e mazhârız Habib burhan olan yerde', 'Bu can bin kerre kurbandır hedef Subhan olan yerde Ne yaksın âteş-i Nemrut bağ-ı iman olan yerde. Bırak ehrâm-ı zulmüyle Kelîm''in hasmı kibr...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gazel-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim Eylül''üm', 'benim-eylul-um-zemci-cetinkaya-4nhyq', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Eylül sana ne anlatır ey çınar

Hicran demlerinde gel de gör beni

Mukadderdir size yeni bir bahar

Kuşluk geçti ikindiden sor beni

Bütün bir hayat ki vuslatı yoktu

Yeşerdi sahralar nehirler aktı

Gül mevsimi geçti ve hazan çöktü

Aramadı gitti nazlı yar beni

Yollara düşerim yollar lâl olur

Sürûrla başlarım pür-melâl olur

Leyla Leyla derim kîl ü kâl olur

Bir destan eyledi âh u zar beni

Bakarsın dağ aynı nehir yerinde

Bir özge akış var inler derinde

Ağustos ayında yaz günlerinde

Nasıl buldu bu sahrada kar beni', 'Eylül sana ne anlatır ey çınar Hicran demlerinde gel de gör beni Mukadderdir size yeni bir bahar Kuşluk geçti ikindiden sor beni Bütün bir h...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/benim-eylul-um-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Itır Kıza', 'itir-kiza-zemci-cetinkaya-28tbr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Itır kız gönlüne gam ile keder

Bazan gelse bile durmasın emi

Zaman gelir geçer ve hüzün biter

Dünya hâli seni yormasın emi

Dağlara bak nasıl mutlu ve sakin

Hem Tanrı''ya yakın hem bize yakın

Görürüz  onları bilmeyiz lâkin

Kent büyüsü aklın sarmasın emi

Bahar gelir umduğumuz bir bahar

Açılsın çiçekler donansın yollar

Âlemde ne de çok güzellikler var

Gözlerin çirkinlik görmesin emi

Göğün kuşlarını düşün ve anla

Selamla onları başla ve canla

Hayat başladığı gibi biter ezanla

Zihnine özge ses girmesin emi', 'Itır kız gönlüne gam ile keder Bazan gelse bile durmasın emi Zaman gelir geçer ve hüzün biter Dünya hâli seni yormasın emi Dağlara bak nasıl...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/itir-kiza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Bahçesinin Sebebi', 'gul-bahcesinin-sebebi-zemci-cetinkaya-3s6hp', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Âzer babası da olsa

İbrahim''i bilmemişti

Ne güneşle ne de ayla

Hiç yüz yüze gelmemişti

İsmail oğlu da olsa

Üfûl eder Halil için

Kurban edilmeyen ne ki

Ol Rahîm ü Cemîl için

Batarak kaybolan herşey

Fedâ edilmezse aşka; 

Âteşin gülzâr olması

Nasıl olabilir başka.', 'Âzer babası da olsa İbrahim''i bilmemişti Ne güneşle ne de ayla Hiç yüz yüze gelmemişti İsmail oğlu da olsa Üfûl eder Halil için Kurban edilm...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gul-bahcesinin-sebebi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Çitlembik Ağacı', 'i-ki-citlembik-agaci-zemci-cetinkaya-t3rox', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki çitlembik ağacı

Bir câminin avlusunda

Bilirler mi şunu acep

Dostları dost kaygusunda

Belki Meyveleri buruk

Belki soluk yaprakları

Ne de olsa hava soğuk

Hem de kurak toprakları

Ağaçlar da dağlar gibi

Mağrurlara selam derler

Ağaçlar da ağlar gibi

Mağdurlara selam derler

Serçe konar bu dallara 

Bu dallara güvercinler

Sabır lâzım bu yollara

Ve bu yollara hecinler

Hangi mesâfe aşılmaz

Çitlembikler var oldukça

Anneler annaedir zâten

Sevgililer yâr oldukça', 'İki çitlembik ağacı Bir câminin avlusunda Bilirler mi şunu acep Dostları dost kaygusunda Belki Meyveleri buruk Belki soluk yaprakları Ne de ...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/iki-citlembik-agaci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçtim', 'vazgectim-akin-kir-86vtm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bekledim güzel günleri, 

Elbet gelecekler dedim.

Günler geçti, 

Hep bekledim seni.

Yoruldum kimi zaman, 

Yine de bekledim.

Geleceğini hayal ettim.

Ulaştığımı sandım o günlere.

Yüreğimde taze bir heyecan, 

Yıllanmış şarap kadar değerli.

Gülümsediğini sandım yüzüme, 

Elimi uzattım.

Tutmadın.

Gözlerimi açtım.

Karanlığın ortasındaydım.

Artık, 

Hayallerimden vazgeçtim; 

Beklemekten vazgeçtim.', 'Bekledim güzel günleri,  Elbet gelecekler dedim. Günler geçti,  Hep bekledim seni. Yoruldum kimi zaman,  Yine de bekledim. Geleceğini hayal ...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/vazgectim-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülerek Gir Şehre', 'gulerek-gir-sehre-zemci-cetinkaya-rzgs2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne yazarsa yazsın rakım ve nüfus

Gülerek gir şehre ağlayarak çık

Yeni zamanlara ait bu husus

Gülerek gir şehre ağlayarak çık

Gezip görme ayrı savuşma farklı

Lügat aynı lügat konuşma farklı

Hasreti bir garip kavuşma farklı

Gülerek gir şehre ağlayarak çık

Herkes kendisidir kendinden saymaz

Ah etsen birisi ahını duymaz

Karnın doyar ancak gözlerin doymaz

Gülerek gir şehre ağlayarak çık

Tramvaya binmiş Keremle Aslı

Tanımaz birbirin geçti aşk faslı

Ferhat kravatlı Şirin çok süslü

Gülerek gir şehre ağlayarak çık

Kıssa-i aşk kitapçıda duruyor

Leyla yeni moda etek soruyor

Mecnun şimdi kiralık ev arıyor

Gülerek gir şehre ağlayarak çık

Mazlumların boynu kementlerinde

Zerrece erdem yok niyyetlerinde

Bir nevi işgal var mâbetlerinde

Gülerek gir şehre ağlayarak çık

Dervişleri tören için dönüyor

Fukaranın ocakları sönüyor

Mücahitler mercedese biniyor

Gülerek gir şehre ağlayarak çık', 'Ne yazarsa yazsın rakım ve nüfus Gülerek gir şehre ağlayarak çık Yeni zamanlara ait bu husus Gülerek gir şehre ağlayarak çık Gezip görme ayr...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/gulerek-gir-sehre-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayyam''ın Rubaisini Türkçe Söyleyiş', 'hayyam-in-rubaisini-turkce-soyleyis-zemci-cetinkaya-tzz0u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayyam''ın Rubaisini Türkçe Söyleyiş

Bir öküz var yeri taht-ı zemindir

Dİğeri de  gökte ismi pervindir

Bunlar efsânedir ama şu doğru

Aradaki meydan eşeklerindir

Kara yerin altında bir koca öküz var derler

Pervin adlı bir öküz de dolaşırmış gökleri

Bu efsânedir lâkin saymaya kalkan halt eder

İkisi arasında dönüp dolaşan eşekleri', 'Hayyam''ın Rubaisini Türkçe Söyleyiş Bir öküz var yeri taht-ı zemindir Dİğeri de  gökte ismi pervindir Bunlar efsânedir ama şu doğru Aradaki ...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/hayyam-in-rubaisini-turkce-soyleyis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuz Aydınlık Gazeli', 'sonsuz-aydinlik-gazeli-zemci-cetinkaya-3eita', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sonsuz Aydınlık Gazeli

Ey kalbimin şakâyıkı sonsuz bir baharla geldin

Karanlıklar sahrasına ebedî neharla geldin

Bir gemiyle bir gömlekle bir kurbanla bir değnekle

Rahmet muştusu sağnakla mübârek kuşlarla geldin

Söndü Kisrâ''nın ateşi tanıştı erdemle Roma

Fesat yuvası Hayber''e Seyf-i Zülfikar''la geldin

Kâinatın mihr ü mâhı ne hâcet var mucizeye

Örümcekle güvercinle ve o yâr-ı garla geldin

Kelîmle Davut söyledi Mesih''ten de haber aldık

Habib olan yalnız sensin sen dürr-i güftarla geldin

Nice medineler doğdu handesi budur cihânın

Semerkant’tan Endülüs’e binlerce gülzarla geldin

Bosnalı Ayşe bebeğin şakağında bir damla gül

Grozni''de  ak sakallı gazi ihtiyarla geldin

Göğsüne gökdelen konmuş Harlemin Bilallerine

En umutsuz anlarında Allahuekberle geldin

Tuğyânımız pek büyüktür lâkin Bargâh-ı Rahmetten

Ümit-varız şanlı Nebi bize bergüzarla geldin', 'Sonsuz Aydınlık Gazeli Ey kalbimin şakâyıkı sonsuz bir baharla geldin Karanlıklar sahrasına ebedî neharla geldin Bir gemiyle bir gömlekle bi...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/sonsuz-aydinlik-gazeli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişin Geçişi', 'gecmisin-gecisi-akin-kir-nqgr2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yüreğimi sızlatıyor geçmişe bakmak.

Geçmişten birşeyler aramak

Ya da yeniden yaşamak.

Sevinçler, hüzünler

Hepsi yan yana duruyor

Eski bir defterin sayfalarında.

Arayıp bulmak.

Geçmişten sıyrılamamak.

Sevinci de hüzün oluyor bugüne geçmişin.

Gözyaşlarım yine akıyor

Ve öksüz kalıyor yüzümde

Dudağımdaki masum tebessüm.

Geçmişe dalmak.

Aslında hepsi, 

Geçmişin geçtiğine inanamamak.', 'Yüreğimi sızlatıyor geçmişe bakmak. Geçmişten birşeyler aramak Ya da yeniden yaşamak. Sevinçler, hüzünler Hepsi yan yana duruyor Eski bir de...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/gecmisin-gecisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şehrimi İstiyorum', 'sehrimi-i-stiyorum-akin-kir-83wke', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şehrimi istiyorum.

Taşına toprağına alıştığım, 

Sokaklarında kendimi aradığım, 

Hayatı tanıdığım, 

Şehrimi istiyorum.

Gündüzüyle kucak açan, 

Gecesiyle bağrına basan, 

Her zaman beni barındıran, 

Şehrimi istiyorum.

Bağladılar elimi kolumu, 

Ulaşamıyorum oraya.

Işıklarını yakmış beklerken şehir, 

Gidemiyorum ona.', 'Şehrimi istiyorum. Taşına toprağına alıştığım,  Sokaklarında kendimi aradığım,  Hayatı tanıdığım,  Şehrimi istiyorum. Gündüzüyle kucak açan,...', ARRAY['Türk Edebiyatı','Şiir','Akın Kır']::text[], 8.5, '{"poet":"Akın Kır","poet_slug":"akin-kir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sehrimi-istiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana', 'sana-sair-tarikcan-1um2o', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben sevecektim, hazırdım

Dalmaya dipsiz kuyulara

Elbette korkularım vardı, yalnızlıklarım

Çocuklarım vardı ve birde karım

Uykusuzdum, açtım, liman aradım sende

Oysa sen çekip gittin, yelkenini aldın

Açılıverdin denizlere

Ben durgun sularda bir balık

Sen aşkını aryan bir kadın

Tutuverseydin ellerinle beni

Ki ben tutulmaya öyleysine hazırdımki

Ertelemekten yorulmuştum hayatı

Aşk, ah; bir ağıttır

Bende, bir başka bahara saklı kalan', 'Ben sevecektim, hazırdım Dalmaya dipsiz kuyulara Elbette korkularım vardı, yalnızlıklarım Çocuklarım vardı ve birde karım Uykusuzdum, açtım,...', ARRAY['Türk Edebiyatı','Şiir','Şair Tarıkcan']::text[], 8.5, '{"poet":"Şair Tarıkcan","poet_slug":"sair-tarikcan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sana-21-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeğenime', 'yegenime-sair-cakar-17dvg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'canım

Ulaş Can''ım

biz seni çok sevdik

baban bir devrimcinin

adını

annende sana canını 

verdi

bense sevgimi verebildim

olanca yüreğimle

küçücük kalbin, upuzun hayatından

yalnız on yıl çalabildi

on kısa yıl.

oysa çocuk tadında

yaşamak 

senin de hakkındı..hakkın olmayarak

var olması muhtemel yerden

tanrıdan

çiçek açmışsın görmeyeli

hayat vermişsin 

bir kelebeğe

yaşadığın hayat kadar

kısacık

üç, dört gün öncede

yağmur olup yağmışsın

duyduğuma göre

arkadaşlarınla bir olup

hiç olamadığın gibi

top oynamışsınız

bıkmadan

usanmadan, 

ama yorulmadan, maviye çalmadan tenin...

hepsi güzelde

bir de bizi ardından

böyle boynu bükük ve dingin

böyle umarsız koymasan

canım

Ulaş Can''ım

biz seni çok sevmiştik

                                 Şubat.2000', 'canım Ulaş Can''ım biz seni çok sevdik baban bir devrimcinin adını annende sana canını  verdi bense sevgimi verebildim olanca yüreğimle küçüc...', ARRAY['Türk Edebiyatı','Şiir','Şair Çakar']::text[], 8.5, '{"poet":"Şair Çakar","poet_slug":"sair-cakar","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yegenime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'In Ruhumun Derinliklerine', 'in-ruhumun-derinliklerine-emrullah-erdinc-mqimd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bak gözlerime  tatli tatli tut ellerimi 

in ruhumun derinliklerine 

ölumsuzluge dogru

sev beni  ama fazla yaklasma

askimada saygi göster 

birak inansin askina dönusmesin kedere

tut ellerimi  hisset sana olan sicakligini askimin 

sana baktikca  cok huzunluyum

askimada bir yer tani

birak guleyim bende mutluluga

bak gözlerime tatli tatli

in ruhumun derinliklerine

ölumsuzluge dogru

birak kalbimi kendinle bas basa  kalsin.', 'Bak gözlerime  tatli tatli tut ellerimi  in ruhumun derinliklerine  ölumsuzluge dogru sev beni  ama fazla yaklasma askimada saygi göster  bi...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/in-ruhumun-derinliklerine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düş Değilmi', 'dus-degilmi-hayrettin-tarhan-r9lbw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ömür dediğin nedir ki? 

Bir kerrat cetveli gibi

Çarpa çarpa birbirine

Şu çile dolu günleri.

Bakarsın, bir anda bitmişsin.

Ömrün akmış, bir su gibi.

Hiç anlamadan gelirsin.

Ömür denilen zamanın

Hesaplaşma kapısına.

Dur! bir hesap yap, burada.

Topla! sevgilerini bir yerde. 

Çıkar! dertlerini onlardan.

Ve böl! kalanı yıllara.

Nedir, elinde kalanlar? 

Hepsi birer düş değil mi?', 'Ömür dediğin nedir ki?  Bir kerrat cetveli gibi Çarpa çarpa birbirine Şu çile dolu günleri. Bakarsın, bir anda bitmişsin. Ömrün akmış, bir s...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/dus-degilmi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Kahretsin', 'allah-kahretsin-hayrettin-tarhan-szozb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sevmek istedim, ömrümce hiç anlayan olmadı.

Aşkı sordum, sevdim diyenlere anlatan olmadı.

Aramaktan sevgiyi dizlerimde derman kalmadı.

Bulduğumu sandım, oda yalanmış. Allah kahretsin.

Seviyorum dedim, razıydım, her gün yalvarmaya.

En büyük sevgi deyip de koşarken kaldım yine yaya.

Bütün benliğim onundu yine onunla girdi, komaya.

Bir busesi ebedi hayattı yok oldu. Allah kahretsin.

Yıllar sonra bu kadar çok sevmek kolay mıydı? 

Bütün sözlerin, o bakışların hepsi yalan mıydı? 

Tuttuğum o soğuk ellerin yoksa bir yılan mıydı? 

Kaderim böyleymiş neyleyim. Allah kahretsin.

Her uyanışta ayrı bir ıstırap yaşadım düşlerden

Hiç bir umut ışığı bırakmadın, gelecek günlerden.

Ne zaman sevdim, desem böyle ölesiye gönülden

Gözlerimden hep yaş aktı. Allah kahretsin.

Ne gerek vardı, yalana neydi  istediğin  benden? 

Hiç mi mutlu olmadın, bu kadar çok sevilmekten? 

Yıllarca utanacaksın, belki artık karanfillerden? 

Nergislerim bile kurudu gitti. Allah kahretsin

Senin dağlarına hiç ama hiç kar yağmamış.

Senin her günün ayrı ayrı birer baharmış.

Senin ormanlarında hiç ağaç yanmamış.

Benim halâ yanıyor; alev alev Allah kahretsin.

Olmasa da artık söndüren bu yangınımı

Akıtsam da senin için bütün kanımı

Yok desende gururun yıksan da şanımı

Yinede çok seviyorum, seni Allah kahretsin.', 'Sevmek istedim, ömrümce hiç anlayan olmadı. Aşkı sordum, sevdim diyenlere anlatan olmadı. Aramaktan sevgiyi dizlerimde derman kalmadı. Buldu...', ARRAY['Türk Edebiyatı','Şiir','Hayrettin Tarhan']::text[], 8.5, '{"poet":"Hayrettin Tarhan","poet_slug":"hayrettin-tarhan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/allah-kahretsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Arzu(m) Larım', 'arzu-m-larim-serkan-akoglu-fejev', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ayın en parlak zamanı bir gece vakti 

Yıldızlar gökyüzünü doldurmuşken canım 

Oynuyoruz yıldızlarla, talip oluyoruz 

Bir yıldız sen oluyorsun bir yıldız ben 

O an zamanı durdurmak istiyorum saatı atıyorum 

Geçmesin dakikalar saatler ilerlemesin diye 

Bitmesin istiyorum o guzel gecemiz yıldızlar kaybolmasın 

Hep o an kalsın guneş doğmasın sabah olmasın 

Kızıl saclarını okşuyorum gözlerını okuyorum 

Sarılıyorum sana sarıyorum senı sıkıca 

Öpüyorum senı defalarca doymadan 

Seviyorum seni umutsuz olsanda, hayal olsanda 

Güzel bir masa hazırlıyoruz mum ışığı altında 

kadeh kaldırıyoruzkarsılıklı o mutlu ana! ! 

Hoş bir müzik cınlıyor kulaklarımızda 

Dans edıyoruz kendımızden gecmişiz usul usul 

Sevişiyoruz sabaha kadar yıldızlar altında 

Isıtıyoruz bedenlerimizi soğuk gecelerde 

Hissediyorum sıcaklığını içime cekiyorum nefesini 

Özlemini duyduğumuz duyguları kusuyoruz bu gece 

Başını omuzuma yaslıyorsun gözün uzaklarda 

Ellerini sarıyorum kokunu çekiyorum hissediyorum seni 

Mutsuzluklar içindeyiz mutluluk arıyoruz sankı, gülüyoruz 

Hayal! de olsa unutulmaz dakikalar, saatler geçiyor belkide 

Belkide bunlar yaşamak istediklerimiz umutlarımız 

Arzularımız, özlemlerimiz belkide hasretlerimiz 

Kana kana içiyoruz aşkıda sevgiyide bulmuşken 

Ne olur kızma bebeğim o bizim dunyamız', 'Ayın en parlak zamanı bir gece vakti  Yıldızlar gökyüzünü doldurmuşken canım  Oynuyoruz yıldızlarla, talip oluyoruz  Bir yıldız sen oluyorsu...', ARRAY['Türk Edebiyatı','Şiir','Serkan Akoğlu']::text[], 8.5, '{"poet":"Serkan Akoğlu","poet_slug":"serkan-akoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/arzu-m-larim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kosova', 'kosova-ahmet-ferit-cosan-wncui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir kucak gül

Yugoslavya''nın bahtsız evladı

Kosova''ya gitsin.

Gitsin de güller

Silahları sustursun.

Sonra dört rüzgar, dağlarınıza

Günbatımından koparılmış

Bulutlar sersinler.

Güneş dansetsin yüzlerinizde, 

Sevdalım yağmur

Yıkasın kanlarınızı sokaklardaki.

İnsanlar ölmesin, 

Dedeler, nineler, torunlara

Masallar anlatsın.

Anlatsın da barış ne demekmiş

Yeniden öğrensin çocuklar.

Artık Kosava''nın dağlarında

Toprak, su, yeşil, kol, bacak

Parçalamasın toplar.

Gözyaşarındaki acılarla

Zehirlenmesin toprak.

Hey, hey insanoğlu hey! 

Sen, kendi kendinin düşmanı olan

Dünyadaki tek varlıksın.

Ve ben her yeni doğan günle

Daha çok utanıyorum insanlığımdan.', 'Bir kucak gül Yugoslavya''nın bahtsız evladı Kosova''ya gitsin. Gitsin de güller Silahları sustursun. Sonra dört rüzgar, dağlarınıza Günbatımı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kosova-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk & Şefkat', 'ask-sefkat-ahmet-ferit-cosan-mo9l6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sen, 

Ey gecelerimin huzurunu

Benden çalan

Huysuz sevgili.

Uykumun davetsiz misafiri

Hayallerimin gediklisi.

Duy artık bu biçarenin haykırışlarını, 

Duy ki

Şefkat duy bu miskine, 

Bakarsın 

Şefkat, aşka durur

Zaman geçtikçe.', 'Sen,  Ey gecelerimin huzurunu Benden çalan Huysuz sevgili. Uykumun davetsiz misafiri Hayallerimin gediklisi. Duy artık bu biçarenin haykırış...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-sefkat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaçma', 'kacma-ahmet-ferit-cosan-uy7ed', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne gerçeklerden, 

Ne de yalanlardan korkuyorsan, 

Gel bana.

Çünkü gerçek ve yalan

Hayatın loş sahnesinde

Binlerce yıldır

Farklı farklı oyunlar sergileyen

İki yaşlı aktördür.

Onlardan korkarsan; 

Hayattan korkarsın.

Onlardan kaçarsan; 

Aşktan kaçarsın.', 'Ne gerçeklerden,  Ne de yalanlardan korkuyorsan,  Gel bana. Çünkü gerçek ve yalan Hayatın loş sahnesinde Binlerce yıldır Farklı farklı oyunl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kacma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelleme', 'guzelleme-ahmet-ferit-cosan-wdjw1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Erik yeşilim

Nasıl da pırıl pırıl

Işıldarsın yağmurdan sonra, 

Bulutların beyazından beyaz

Çiçekler açarsın 

Yalancı baharlarda.

Kiraz olursun, kayısı olursun, 

Kestane olursun, 

Demet demet çiçek yükleyip sırtına.

Halbuki kabuğundan başka bir şey yok gövdende, 

Bir kırağılı sabahta, 

Dökülüverir çiçeklerin

Köklerinin dibine.', 'Erik yeşilim Nasıl da pırıl pırıl Işıldarsın yağmurdan sonra,  Bulutların beyazından beyaz Çiçekler açarsın  Yalancı baharlarda. Kiraz olurs...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/guzelleme-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece', 'gece-ahmet-ferit-cosan-qil9n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Zorlamasıyla dinlediğim şiirlerin, 

Duyduğum hüzünlü ezgilerin

Bende uçuyorum işte en sonunda.

Kuşlar, ağaçlar: bende artık

Yükseklerdeyim sizler gibi.

Yatağında uyuyan küçük çocuk, 

Gördüğün rüyalardan daha hızlıyım.

Yetişemezsin bana.

Sevdiğim kız, 

Ben bu kadar yüksekteyken

Aşkın bile ulaşamaz bana

Ağlatamaz beni, 

Gömemez geceye

Ve ben inadına senin, 

Güneşi yakalamk için

Daha da yükselip, daha da hızlanıp, 

Daha da hislenip, daha da sevip, 

Tutacağım güneşi, yalnızca bir hüzmesini bile olsa.

Sevdiğim kız.

Sevemezsin beni bu kadar yüksekteyken

Anlayamazsın beni, ben inmedikçe aşağılara.', 'Zorlamasıyla dinlediğim şiirlerin,  Duyduğum hüzünlü ezgilerin Bende uçuyorum işte en sonunda. Kuşlar, ağaçlar: bende artık Yükseklerdeyim s...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gece-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Özlemi', 'gece-ozlemi-ahmet-ferit-cosan-4otfv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şiir günleri başladı yine, 

Acımı harmanlama zamanıdır şimdi.

Taa derinden çıkarayım ki ateşimi

Sevsinler mısralarımı.

Aşkı, doğası, özlemi vesairesi

Dökülsün kalemimden, aksın kağıda

Şu samandan tuvale

Kelimelerden portre yapayım icabında.', 'Şiir günleri başladı yine,  Acımı harmanlama zamanıdır şimdi. Taa derinden çıkarayım ki ateşimi Sevsinler mısralarımı. Aşkı, doğası, özlemi ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gece-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben kaba olamam', 'ben-kaba-olamam-emrullah-erdinc-u3pac', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sögleme gulum sögleme 

ben kaba olamam

bir daha cok kabasin deme

ben insani kiramam

tek hatam sevmek

askimi mudafa etmek

onuda cok göruyorsan

al senin olsun

ben yine severim 

ben kaba olamam kimseye 

saygida kusur edemem

yoksa incilir ruhum dagilir

kaybolur yok olurum

hele bir bayani 

asla ve asla kiramam

ya sevdigimi askimi 

gulumu asla kesinlikle  kiramam 

tek hatam soguyabilirim 

sevdigim askimda olsa

kutuplardaki buz  daglari gibi

erir bir daha aramam 

hayatindan  ebedi

sonsuza dek cekilir yok olurum.', 'Sögleme gulum sögleme  ben kaba olamam bir daha cok kabasin deme ben insani kiramam tek hatam sevmek askimi mudafa etmek onuda cok göruyorsa...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/ben-kaba-olamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskici', 'eskici-ahmet-ferit-cosan-rlutz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Giz dolu bir sokaktan

Düşüncelerle geçiyordum ki

Bir eskiciye rastladım.

Eski hatıralar, eski zamanlar alıp, 

Ümitlerle takas ediyordu.

O geçtikçe, her sokak lambası

Daha çok titriyordu zakkumların arasından.

Her adımdan sonra, 

Ayrı güzellikte çiçekler açıyordu bahçelerde.

Her bir limon ağaçlarında türküler tutturuyordu.

Sokak eskicinin bağırışıyla uyanıyordu.

Sonra çekip gitti.

Elimde takas için eski bir aşk hatırası

Bir ümitle değiştirilemediği için mahsun kalakaldı.', 'Giz dolu bir sokaktan Düşüncelerle geçiyordum ki Bir eskiciye rastladım. Eski hatıralar, eski zamanlar alıp,  Ümitlerle takas ediyordu. O ge...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/eskici-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dosta Öğüt', 'dosta-ogut-ahmet-ferit-cosan-5cp9x', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umut bahara kalmadı dostum.

Doğa varken, şiir varken, 

Müzik varken

Umutsuzluk olur mu hiç? 

Bizler biliriz, 

En karanlık anlarda 

En aydınlık ateşleri yakmayı.

Bizler biliriz, 

Gecenin sonunda 

Elbet günün doğacağını.

Bizler biliriz

Günü geldiğinde 

Umudun dalga dalga yayılacağını.

İpteki cambaz misali 

Olsan da hayatta, 

Her ne kadar düşürmeye çalışsalarda

Sarıl umuda

Sarıl aşka.

Kucakla sımsıkı hayatı.

Tıpkı bir ağacın 

Toprağı kucaklaması gibi.

Gülümse bir bebeğin saflığıyla, 

Ağlama zor zamanlarda 

Göğüs ger acılara ki

Umudun yeşertsin ruhunu, 

Aşk sarsın dört bir yanını.

Neşemiz gençleştirir bizi dostum, 

Çocukça gülüşlerimiz, 

Yersiz hislenişlerimiz.

Ve bunların tümü

Senden kalsın sonrakilere ki

Yaşanacak güzel bir yer olsun dünya.', 'Umut bahara kalmadı dostum. Doğa varken, şiir varken,  Müzik varken Umutsuzluk olur mu hiç?  Bizler biliriz,  En karanlık anlarda  En aydınl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dosta-ogut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Gidersin', 'sen-gidersin-mustafa-cem-sarikaya-5e8pa', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yıldızların yalnızlığını dinlerim, 

Karanlık sessizliğini bozup anlatır, 

Rüzgarlar yetişir bize

Nefes nefese, yorgun

Yağmurlar sırılsıklam...

Anlatırlar.

Ben dinlerim.

Duvarlar az konuşur, 

Dakikalar yavaş yavaş, 

Zaman çok kısa...

Anlatırlar.

Ben dinlerim.

Hepsi anlatır, 

Bir sen susarsın.

Derken usul usul sabah gelir.

Herkes gider, 

Sen gidersin.

Ben ayak seslerini dinlerim.

Belki birgün gelir, 

Sende anlatırsın beni ne çok sevdiğini, 

İşte ben o günü beklerim.', 'Yıldızların yalnızlığını dinlerim,  Karanlık sessizliğini bozup anlatır,  Rüzgarlar yetişir bize Nefes nefese, yorgun Yağmurlar sırılsıklam....', ARRAY['Türk Edebiyatı','Şiir','Mustafa Cem Sarıkaya']::text[], 8.5, '{"poet":"Mustafa Cem Sarıkaya","poet_slug":"mustafa-cem-sarikaya","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sen-gidersin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağların Sihri', 'daglarin-sihri-ahmet-ferit-cosan-w1g6e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu karşı dağın doruğuna çık.

Sonra aç kollarını.

Bir elin yeşil ovaları örtsün, 

Diğeri mavilim denizi.

Düşün sonra, 

Düşün, düşün ve

Rüzgar ol.

Kon taze tomurcuklarına erik ağaçlarının.

Danset pamuklu kavaklarla, 

Kambur söğütlerle, 

Yarış yarışabilirsen uğurböcekleriyle.

Düşün, düşün ve

Aynı anda, ayrı yerlerde

Hasat ol, 

Yelkene dolan güç ol, 

Yağmur ol, 

Bir garibin bağrındaki ateşi

Söndüren ol.

Gel bereketlim ol.

Beni de al yanına

Yoldaşım ol.', 'Şu karşı dağın doruğuna çık. Sonra aç kollarını. Bir elin yeşil ovaları örtsün,  Diğeri mavilim denizi. Düşün sonra,  Düşün, düşün ve Rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/daglarin-sihri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çaresizlik', 'caresizlik-ahmet-ferit-cosan-kv5rg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hayatım senindir.

Al hadi.

Bak gördün mü? 

Avucunun içindeki o 

Zavallı şey benim.

Bir sıksan belki öleceğim.

Sık hadi.

Ellerin kıpkırmızı aşka bulansın.

Sonra bir türkü dinleyip, ağla

Gözyaşlarınla ellerini yıkarsın', 'Hayatım senindir. Al hadi. Bak gördün mü?  Avucunun içindeki o  Zavallı şey benim. Bir sıksan belki öleceğim. Sık hadi. Ellerin kıpkırmızı a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/caresizlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyü', 'buyu-ahmet-ferit-cosan-2h5rl', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Elimde değnek olsa sihirli

Sevdirsem yedi düvele kendimi

En çok ta sana

Sonra kırsam değneyi ikiye 

Sırf büyü bozulmasın diye.', 'Elimde değnek olsa sihirli Sevdirsem yedi düvele kendimi En çok ta sana Sonra kırsam değneyi ikiye  Sırf büyü bozulmasın diye....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/buyu-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulutsuzluk Özlemi', 'bulutsuzluk-ozlemi-ahmet-ferit-cosan-3xjy8', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sizin notalarınız

Umut dağıtıyor farkında mısınız? 

	Bence farkındasınız.

Sizin telleriniz benim ilk aşkım

Ve melodileriniz

İlk aşkıma asla söyleyemediğim şarkım

	Biliyor musunuz? 

Biliyorsunuz çünkü siz 

Ben''siniz

Eğer insanlar çiçeklerse, sizler

Aşk falına bakılmış çiçeklersiniz, 

Görkeminiz yüreğinizde

Diğer şık çiçeklerden farkınız.', 'Sizin notalarınız Umut dağıtıyor farkında mısınız?  	Bence farkındasınız. Sizin telleriniz benim ilk aşkım Ve melodileriniz İlk aşkıma asla ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/bulutsuzluk-ozlemi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karanlık', 'karanlik-ahmet-ferit-cosan-hf8fc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Benim adım karanlıktır.

Bir yüreğimde, 

Bin dünya saklarım.

Sen, aydınlık düşlerinle

Beni yoketsene.', 'Benim adım karanlıktır. Bir yüreğimde,  Bin dünya saklarım. Sen, aydınlık düşlerinle Beni yoketsene....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/karanlik-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sendeki Ben', 'sendeki-ben-anil-yalazi-ssup4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiçbir saat çalamadı sana aşık olduğum anı...

Sonsuzluktu o...

Belki doğmadan önceki birkaç saat...

Sen...

Ruhunun ikizini bulamayan sevdiğim...

Er geç bana döneceksin...

İçindeki bütün çirkinlikleri avuç avuç 

Savur da gel...

Aşkı yaşamamışsın sen daha...

Çünkü aşk 

Sendeki bendir...', 'Hiçbir saat çalamadı sana aşık olduğum anı... Sonsuzluktu o... Belki doğmadan önceki birkaç saat... Sen... Ruhunun ikizini bulamayan sevdiği...', ARRAY['Türk Edebiyatı','Şiir','Anıl Yalazı']::text[], 8.5, '{"poet":"Anıl Yalazı","poet_slug":"anil-yalazi","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sendeki-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çikolata Renkli Simitçilerin Ardından', 'cikolata-renkli-simitcilerin-ardindan-anil-yalazi-1hu7u', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duş alsam mı acaba? 

Çikolata renkli simitçiler geçerken

İçim üşür hep...

Dünyadaki bütün simitlere küsüm...

Sabahın dokuzunda çiikolata renkli simitçiler geçerken

Aklımda aynı soru: 

Duş alsam mı acaba? 

Ne fark eder ki...

İçim üşüyor yalnızlıktan...

Çikolata renkli çocukların simit sattıkları 

Dünyadan...

Saat 9: 30

Yorgunluk ve yalnızlık suda erir belki

Sabun misali köpük olup uçmak istiyorum

Duş alsam mı acaba?', 'Duş alsam mı acaba?  Çikolata renkli simitçiler geçerken İçim üşür hep... Dünyadaki bütün simitlere küsüm... Sabahın dokuzunda çiikolata ren...', ARRAY['Türk Edebiyatı','Şiir','Anıl Yalazı']::text[], 8.5, '{"poet":"Anıl Yalazı","poet_slug":"anil-yalazi","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/cikolata-renkli-simitcilerin-ardindan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Dair', 'sana-dair-anil-yalazi-uewbv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Telefon tuşları arasından

Aşkımız geçiyor...

Kalbim sıkışıyor sesini duyduğum an...

Usul usul ağlıyorum sesimi duyma diye...

Yüreğim titriyor ama çıkmıyor ağzımdan o büyülü iki kelime...

Sığıntı umutlarla her gece, 

En parlak yıldıza sarılıyorum...

Gözlerim yüne ıslak, 

Bilmiyorsun...', 'Telefon tuşları arasından Aşkımız geçiyor... Kalbim sıkışıyor sesini duyduğum an... Usul usul ağlıyorum sesimi duyma diye... Yüreğim titriyo...', ARRAY['Türk Edebiyatı','Şiir','Anıl Yalazı']::text[], 8.5, '{"poet":"Anıl Yalazı","poet_slug":"anil-yalazi","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-dair-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Ölümü', 'askin-olumu-anil-yalazi-q4lxs', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kapkara bir gecenin sis kokan vakitlerinde 

Sevdim seni...

Dar zamanlara kocaman bir aşkı 

Sığdırmak istedim...

Anlamadın, peşinde dolanıp durduğum saatlerde

Gülüşümde açan ebemkuşağı renkli sevgiyi...

Göremedin yüreğimde açan çiçekleri...

Oysa tüm kalbim senindii o anlarda...

Portakal ağaçlarının gölgesinde düşünürken seni

Bordo renkli duvarda asılı bir tablodan ibaret dünya

Yalnızca seni hatırlatırdı bana...

Yalnızca seni görürdüm kalabalığın arasında...

Tablo ne kadar küçüktü! 

Ve sen ne kadar büyüktün gözümde! 

Simsiyah gözlerinin 

İçine içine bakmaktan hoşlanırdım en çok...

Oyun sanırdın...

Camlara yansıyan görüntünde bile simsiyahtı gözlerin

Kaybolurdum gözlerinin içindeki çıkmaz sokaklarda...

Ben aşkı ararken

Her köşebaşında kocaman bir hiç beklerdi beni...

Gözlerin, gözlerin o kadar küçük değildi...

Daha ne kapılar vardı açmadığım...

Daha ne kapılar vardı beni bekleyen...

Yüreğin desen, gözlerinden daha siyahtı

Kaybolurdum...

Gülüşüne dalıp gittiğim akşamlarda

Bir kez daha gülerdin halime

Çocuk sandın! 

Yanıldın! 

Küçücük yüreğimdeki kocaman sevdayı

Bilmedin...

Şimdi yalnızca rüyalarımdasın...

Düşlerimde bile simsiyah gözlerin...

Gözlerin...

Oysa o gözler hatırımda silik silik şimdi

Gözyaşlarım da sana değil üstelik

Küçücük yüreğime sığmayan 

Buruk sevdama ağlıyorum...', 'Kapkara bir gecenin sis kokan vakitlerinde  Sevdim seni... Dar zamanlara kocaman bir aşkı  Sığdırmak istedim... Anlamadın, peşinde dolanıp d...', ARRAY['Türk Edebiyatı','Şiir','Anıl Yalazı']::text[], 8.5, '{"poet":"Anıl Yalazı","poet_slug":"anil-yalazi","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/askin-olumu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Tek Kişilik', 'ask-tek-kisilik-i-lker-sahin-zx8t3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Aşk, acıyla eşdeğer, 

Kaç zamandır acılar biriktiriyorum hep, 

Eskimeyen acılar..

Yangın yeri yüreğime, 

Bir yağmur damlası diyordum oysa..

Neden bu sancılı yalnızlık, 

Avuçlarımdayken ellerin..

Aşk tek kişilik mi yoksa? ...', 'Aşk, acıyla eşdeğer,  Kaç zamandır acılar biriktiriyorum hep,  Eskimeyen acılar.. Yangın yeri yüreğime,  Bir yağmur damlası diyordum oysa.. ...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ask-tek-kisilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Akşam Üstü Yanlızlığı', 'bir-aksam-ustu-yanlizligi-i-lker-sahin-ac1ou', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Adı konulmamış bir akşam üstü yalnızlığıydı, 

Gözlerindeki mağrurluk, 

Her an boşalmaya hazır bir nisandı..

Saçlarından büyük, uzak ormanların

Yansıması geçerdi geceye..

Puslu ve tenha bir sokaktı, yüzün.

Kışın ayazında donmuş gibi

Kenarında dudağının, bir parça

Eski bir tebessüm...', 'Adı konulmamış bir akşam üstü yalnızlığıydı,  Gözlerindeki mağrurluk,  Her an boşalmaya hazır bir nisandı.. Saçlarından büyük, uzak ormanlar...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/bir-aksam-ustu-yanlizligi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Acı', 'bu-aci-i-lker-sahin-s4l50', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu acı bıçak acısı değil, 

Bu yara kurşun yarası değil..

Bu acı yürek acısı, 

Bu yara yokluğunun yarası..

Ne işkenceler gördüm de, güçlü oldum hep, 

Zindanlar, falakalar..

Ne kadar güçsüzüm oysa şimdi, 

Tıpkı ölümü bekleyen bir idam mahkumu gibi...', 'Bu acı bıçak acısı değil,  Bu yara kurşun yarası değil.. Bu acı yürek acısı,  Bu yara yokluğunun yarası.. Ne işkenceler gördüm de, güçlü old...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bu-aci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıkmaz Bir Sokaktır Hayalin', 'cikmaz-bir-sokaktir-hayalin-i-lker-sahin-qku93', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sokağıma yağan yağmurlar, 

Gözlerinden mi boşanır.

Islatır beni sırılsıklam..

Gece sokak lambalarında 

Gözlerini görürüm..

Yıldızsız, aysız akşamlardır saçların..

Yalayıp geçer yüzümü bir rüzgar, 

Savurmuşsundur saçlarını..

Çek gözlerini, saçlarını sokağımdan, 

Islatma sokağımı...', 'Sokağıma yağan yağmurlar,  Gözlerinden mi boşanır. Islatır beni sırılsıklam.. Gece sokak lambalarında  Gözlerini görürüm.. Yıldızsız, aysız ...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/cikmaz-bir-sokaktir-hayalin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gecelere Yazdım Adını', 'gecelere-yazdim-adini-i-lker-sahin-oihpq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gecelere yazdım adını

Belki de bu yüzden geceleri sevişim

Senin sıcak tenini bulurum gecelerde

Tıpkı sana sokulur gibi sokulurum usulca

Gecenin koynuna

Sabahın olmasını hiç istemeyişim bu yüzden belki

Sevişmelerimiz bitmesin diye

Bu yüzden belki de yıldızlara bakıp

Saatlerce dalmam

Gözlerini bulurum çünkü yıldızlarda

Bir o kadar uzak ve bir o kadar da çekidir gözlerin

Bir rüzgar esip geçse, 

Senin ılık nefesin sanırım

Ve bir yağmur yağsa, 

Usulca düşse pencereme

Yokluğuma mı ağlarsın ne? ...', 'Gecelere yazdım adını Belki de bu yüzden geceleri sevişim Senin sıcak tenini bulurum gecelerde Tıpkı sana sokulur gibi sokulurum usulca Gece...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gecelere-yazdim-adini-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya', 'gittin-ya-i-lker-sahin-3e8kh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana bakmaya doyamaz, 

Dokunmaya kıyamazdım.

Bir rüzgar değse saçlarına düşmanım olurdu, 

Geçtiğin yollardan kimse geçsin istemezdim bir daha, 

Silinmezsin ayak izlerin diye..

Sen narin, küçük bir güldün, 

Korkardım koklamaya bile, 

Solmanı hiç istemedim..

İşte, şimdi gittin ya...', 'Sana bakmaya doyamaz,  Dokunmaya kıyamazdım. Bir rüzgar değse saçlarına düşmanım olurdu,  Geçtiğin yollardan kimse geçsin istemezdim bir dah...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gittin-ya-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Hiç Yalan Söylemedi', 'gozlerin-hic-yalan-soylemedi-i-lker-sahin-qu5ng', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Maviler gelir, maviler geçer

Siyahlar kalırdı gözlerinde.

Sevinçler gelir, sevinçler geçer

Hüzünler kalırdı gözlerinde.

Gözlerin ki; 

İnkar etmedi aşkı senin gibi.

Gözlerin ki; 

Hiç yalan söylemedi...', 'Maviler gelir, maviler geçer Siyahlar kalırdı gözlerinde. Sevinçler gelir, sevinçler geçer Hüzünler kalırdı gözlerinde. Gözlerin ki;  İnkar ...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozlerin-hic-yalan-soylemedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin Ki', 'gozlerin-ki-i-lker-sahin-8yiyk', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerin aydınlatır geceyi, 

Ay ışığı gibi..

Her sabah güneşin doğuşu gözlerindir..

Gözlerindir; çiçeklere, ağaçlara

Rengini veren, 

Denizlere enginliği, 

Gökyüzüne sonsuzluğu..

Her umut gözlerinde tomurcuklanır, 

Sevgi anlamını gözlerinde bulur.

Kapatma gözlerini

Hayat son bulmasın...', 'Gözlerin aydınlatır geceyi,  Ay ışığı gibi.. Her sabah güneşin doğuşu gözlerindir.. Gözlerindir; çiçeklere, ağaçlara Rengini veren,  Denizle...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gozlerin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerin', 'gozlerin-i-lker-sahin-kuz5c', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerin vurdumduymaz

Gözlerin acımasız

Gözlerin yakar cehennem ateşleri gibi..

Bazen bir okyanus olur gözlerin, 

Coşar..

Bir çocuk oynar gözlerinde, umarsızca

Bazen iç çeker, 

Dokunsan ağlayacaktır

Oyuncağı elinden alınmış gibi..', 'Gözlerin vurdumduymaz Gözlerin acımasız Gözlerin yakar cehennem ateşleri gibi.. Bazen bir okyanus olur gözlerin,  Coşar.. Bir çocuk oynar gö...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerin-30-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerine Baktığımda', 'gozlerine-baktigimda-i-lker-sahin-hldoe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözlerine baktığımda; 

Okyanuslar aşardım, 

En uzun yolları koşardım soluksuz, 

En sert rüzgarlar bile çatlatmazdı ellerimi, 

En uçsuz çöllerde bulurdum yönümü, 

En delice yağmurlar ıslatmazdı beni, 

En uzun geceler, bir andı...

Gözlerin nerede? ..', 'Gözlerine baktığımda;  Okyanuslar aşardım,  En uzun yolları koşardım soluksuz,  En sert rüzgarlar bile çatlatmazdı ellerimi,  En uçsuz çölle...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gozlerine-baktigimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-i-lker-sahin-n5uwx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hasretin kalbime saplanan

Soğuk bir kurşun gibi, 

Derinlerde ta derinlerde, 

Acıtıyor içimi..

Yokluğun bıçak yarası, 

Kanatıyor her yerimi, 

Damarlarımdan oluk oluk yokluğun akıyor..

Uzaklığın boynuma geçirilmiş

Yağlı bir ip

Ve üzerimdeki idam gömleği, 

Sensizlik; kolsuz ve ölçüsüz..

Gel kurtar beni ölümlerden...', 'Hasretin kalbime saplanan Soğuk bir kurşun gibi,  Derinlerde ta derinlerde,  Acıtıyor içimi.. Yokluğun bıçak yarası,  Kanatıyor her yerimi, ...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/hasret-35-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyimsin Sen Benim', 'her-seyimsin-sen-benim-i-lker-sahin-ulwk3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şeyimsin sen benim; 

Soğuk gecelerde içime dolan sıcaklığım, 

Işığım ıpıssız karanlıklarda.

Düşlerimsin umuda dair.

Suyum, ekmeğim, havam

Ciğerlerime kadar çektiğim tütün.

Şiirlerimin her hangi bir  mısrası

Ya da bir kitabın her hangi bir sayfasında, 

Çıkan karşıma takılıp kaldığım...', 'Her şeyimsin sen benim;  Soğuk gecelerde içime dolan sıcaklığım,  Işığım ıpıssız karanlıklarda. Düşlerimsin umuda dair. Suyum, ekmeğim, hava...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/her-seyimsin-sen-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün Mevsimleri', 'huzun-mevsimleri-i-lker-sahin-vyudj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şimdilerde gönlüm sonbaharlarda dolaşıyor

Soğuk yağmurlar yağıyor gecelerime

En sert rüzgarlar esiyor başımda

Dalga dalga düşüncelerim

Fırtınalı denizler gibi

Gözlerinin uzaklığı mı bunların sebebi

Ellerinin olmayışı mı avuçlarımda

Siyah saçlarını hissedemeyişim mi

Dokunamayışım mı onlara..

Gel kurtar beni bu mevsimlerden...', 'Şimdilerde gönlüm sonbaharlarda dolaşıyor Soğuk yağmurlar yağıyor gecelerime En sert rüzgarlar esiyor başımda Dalga dalga düşüncelerim Fırtı...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/huzun-mevsimleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kaybederken Bu Kent Beni', 'kaybederken-bu-kent-beni-i-lker-sahin-9nwzn', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni aradım kaybettiğim kentin sokaklarında.

Gece yarıları ışıkları yanan

Evlerden hangisindeydin sen? ..

Uzaklardan duyduğum seslerden

Hangisine karışmıştı sesin? ..

Hangi sarışındın sen, hangi esmer, 

Boşalırken kadehler bir yerlerde..

Sabah çökerken geceye inat, 

Hangi otel odasında dalardın uykuya, 

Yorgun, bitkin bir geceydi geride bıraktığın..

Kaybederken biraz daha ben seni..

Kaybederken bu kent beni...', 'Seni aradım kaybettiğim kentin sokaklarında. Gece yarıları ışıkları yanan Evlerden hangisindeydin sen? .. Uzaklardan duyduğum seslerden Hang...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kaybederken-bu-kent-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkutuyor Beni Yokluğun', 'korkutuyor-beni-yoklugun-i-lker-sahin-mbttf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yağmurlar kadar hüzünlü, 

Bulutlar kadar doluyum bugün.

Gözlerim bir şimşek çakımı..

Fırtınalar kopuyor içimde, 

Dalgalı bir deniz gibi, 

Vuruyor öfkelerim kalbimin kıyılarına..

Bir karabasan gibi çöküyor üzerime yokluğun, 

Deliriyorum..

Korkuyorum sevgili, 

Korkutuyor beni yokluğun.

Gözlerini özlüyorum, 

Ellerini özlüyorum, 

Seni özlüyorum..

Bu özlem korkutuyor beni, 

Ölüm an meselesi, 

Korkmuyorum ama ölümden sevgili, 

Ne durdurabilir başka bu özlemi, 

Ne yok edebilir yalnızlığımı..

Gözlerin yoksa, 

Ellerin yoksa, 

Sen yoksan yaşamışım neye yarar? ...', 'Yağmurlar kadar hüzünlü,  Bulutlar kadar doluyum bugün. Gözlerim bir şimşek çakımı.. Fırtınalar kopuyor içimde,  Dalgalı bir deniz gibi,  Vu...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/korkutuyor-beni-yoklugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neye Yarar', 'neye-yarar-i-lker-sahin-8ggde', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hangi şiiri yazsam anlamını bulur acılar, 

Hangi söz yarımsız anlatabilir yalnızlığımı..

Resimler çizsem hasretine dair, 

Renkleri sen olmayınca neye yarar..

Elim ne kağıda varıyor, ne de kaleme..

Ayrılık şiirini çoktan yazmış, 

Resimler hüznü çoktan çizmiş, 

Söyleyecek ne bir tek sözüm kaldı, 

Ne de çizecek bir resmim...', 'Hangi şiiri yazsam anlamını bulur acılar,  Hangi söz yarımsız anlatabilir yalnızlığımı.. Resimler çizsem hasretine dair,  Renkleri sen olmay...', ARRAY['Türk Edebiyatı','Şiir','İlker Sahin']::text[], 8.5, '{"poet":"İlker Sahin","poet_slug":"i-lker-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/neye-yarar-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurtar Beni', 'kurtar-beni-mahmut-kuru-ipyqz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gürültünün esaretinde yalnızım

eğlen eğlenebildiğince hatta coş

Nasılsa bu benim tercihim

hiçe karşı çok oyla aldığım

Yusuf''a zindanlar huzurlu

Züleyha''nın aşkı doğranmış parmaklarda

kan lekesi parçalanmış gömleklerde

Bense aldatacak vezirler peşindeyim

Baştan çıkarıcı kokusuyla kadınsa

kölelik aşksa Züleyha''ya

Yusuf yok ben varım saraylarda

Talibim günahların en çılgınına

Aksak bir yağmur sızar 

Düş ülkemdeki çatlaklardan

Düşlerim bozguna uğrar

Züleyha''mı ararım umutsuz rüyalarda

Yusuf bir köle çöllerde

Saraylara atanacak peygamber

Seccademde Züleyha''nın soluk nefesi

Düşlerimin amansız takipçisi

Ben Züleyhamı arıyorum

Züleyha küçük bir kız 

Benim küçük kadınım

Gül kokan çölde pusu

Ben seni seviyorum Züleyha

yani seni Küçük Kız

yorgun düştüğüm masallardan

gelip kurtarmanı bekliyorum

düştüğüm bu düş batağından.

		3.8.2001-Dilovası', 'Gürültünün esaretinde yalnızım eğlen eğlenebildiğince hatta coş Nasılsa bu benim tercihim hiçe karşı çok oyla aldığım Yusuf''a zindanlar huzu...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/kurtar-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolunay Hüznü', 'dolunay-huznu-mahmut-kuru-13ked', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Dolunay güzelliğinde geceye düşen

yakamozlar adedince çırpınış

taşlar sektikçe deniz seviyesinde

gökyüzüne saçtığım yıldızlar avucumda

bir bir sayıp yanyana dizdiğim

gönülleri mavi kadar deniz

göğe düşmüş salkım taneleri

ışıkların gerdanlık parıltısı körfez

kıyı kıyı dizilmiş sahile gemiler

elele gönül gönüle yüklenirler

tüm geceyi beyaza boyar

fırçasından kan damlayan ressam

karanlıklar mahkumdu dolunaya

ışığa boğulurdu gece

Şarkılar uzak değildir sevdalara

ben uzak olsam da sana

sıcaklığın sarar tenimi

kokun siner üstüme

gözlerin düşer gözlerime

Bakışlarımız dolunay hüznü açar

Pencerenden sızar aynı dolunay

arala perdeyi çekinme bırak süzülsün

gönlüne düşsün aşkımın harareti

kokla avuçlarına sinmiş kokumu

içindeki ürpertiyi hisset doyasıya

yasak kelimeleri dök yüreğine

düşlerini serbest bırak çakışmalara

tüm engelleri parçala sevginle

Şarkılar uzak değildir sevdalara

sen uzak olsan da bana

sıcaklığım sarar tenini

kokum siner üstüne

gözlerim düşer gözlerine

Bakışlarımız dolunay hüznü açar

Dolunay parlaklığında bir gece

Düşlerimizle boğulur ışığa.

		4 Ağustos 2001-Tavşancıl', 'Dolunay güzelliğinde geceye düşen yakamozlar adedince çırpınış taşlar sektikçe deniz seviyesinde gökyüzüne saçtığım yıldızlar avucumda bir b...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/dolunay-huznu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar Kuşlar Ve Şair', 'cocuklar-kuslar-ve-sair-mahmut-kuru-h7qsw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şehrin ilk ışıkları korkakça

şehrin arka kapısından

sızmaya çalışırken gizli gizli

uyku sersemi şehir şaşkın

insanlar umutsuz, limana giren gemiden

hayat yine sıkıcı başlıyor güne

canhıraş gürültülerin ardında bıraktığı

sessizlikler boğuyor kalabalıkları

asık suratlar peydah oluyor sokaklarda

bezgin yığınları taşıyor kaldırımlar

çöpçüler dünün izlerini silmekle meşgul

bugüne yetişmeye çalışıyor şehir

caddeler klaksonlara teslim

bir didişme bir telaş arabalarda

herkes başını eğmiş adımlarını saymakta

gözgöze gelmeme için tüm çaba

Şehir ansızın ve sinsice gelen güne

hazırlıksız yakalanmanın utancında

bir tek kuşlar sevinçli sanki

ağaçlarda cıvıltılarla kutsuyorlar sabahı

bir de çocuklar mutlu şehirde

oyunlarını gündüz oynuyorlar çünkü

babalarının aksine

şair de umutla karşılıyor sabahı

yeni umutlar biriktiriyor yüreğinde

günahlarını geceye gömerek

sabahın ilk ışıklarıyla fırlıyor sokağa

dizelerine taşıyacak kelimelerin peşinde

attığı her adımda bir kelime topluyor

bezgin yığınların yerlere düşürdüğü

Yine günün sonu belirir uzaktan

sabah korkakça arka kapıdan sızan ışıklar

akşam cesurca terkediyor şehri ön kapıdan

çocuklar, kuşlar ve şair üzgün

şehrin geceye dönmesine

onlar oyunlarını gündüz oynuyorlar çünkü

babalarının aksine

şairin günahları kaplıyor geceyi

yeni günlerin umudunu yüreğine gömerek

O da terkediyor şehri ön kapıdan.', 'Şehrin ilk ışıkları korkakça şehrin arka kapısından sızmaya çalışırken gizli gizli uyku sersemi şehir şaşkın insanlar umutsuz, limana giren ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/cocuklar-kuslar-ve-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye Yakarış', 'sevgiliye-yakaris-mahmut-kuru-jmco3', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkın yaramaz bir ırmak gibi

Vadileri yararcasına yokuşları tırmanmakta

Anlamsız bakışlar çökmüş gözlerime

Anlamlandıracak gözler aramakta

Seni aramakta sis bulvarında

Ruhum asılı odamın duvarında

Çok zamandır kendinde değil yüreğim

Sürgünüm uzun sürdü sıkıldım artık

Sensizlik ülkesi sığmıyor şarkılara

Masamda kağıdım ve kalemim

Seni anlatmaktan yoruldu

Sigaramın dumanı bile dinlemiyor beni

Sürgünüm yeter çağır beni kendine

Anlatmak değil yaşamak istiyorum seni

Yakından solumak nefesini

Beraber ıslanmak güz yağmurlarında

Sahipsiz sokakları sahiplenmek elele

Şiirlerimi göğe değil gözlerine okumak

Gel yine yaramaz bir ırmak ol

Eskisi gibi özgürce dolaş vadilerimde

Tırman yokuşlarıma çekinme

Kaldır at üstümdeki kahır yükünü

Gel nolursun ya da çağır beni kendine

Ayrılıkların aşkımızı boğmasına izin verme

Gel yüreğim çöle dönmeden

Bu kez şarkılar uzak olmasın sevdalara

Uzak olmasın sevdamıza...

			6 Ağustos 2001 Dilovası', 'Aşkın yaramaz bir ırmak gibi Vadileri yararcasına yokuşları tırmanmakta Anlamsız bakışlar çökmüş gözlerime Anlamlandıracak gözler aramakta S...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Kuru']::text[], 8.5, '{"poet":"Mahmut Kuru","poet_slug":"mahmut-kuru","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sevgiliye-yakaris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Pişmanlık', 'son-pismanlik-rafet-malkoc-1r2bz', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıllar önce bir sevgili bıraktım uzaklarda

O şimdi gözü yaşlı pişmanlıkla geçmişteki günleri arıyor.

ikimizde suçluluk duyuyoruz o günleri hatırladıkca

birbirimize söyleyemedik delicesine sevgimizi

imkansız artık birbirimizin olamayız diyorsun

Bunu ikimizde biliyoruz yaşadığımız pişmanlıkla

Unut gitsin diyorsun o güzel günleri

Dost kalalım artık seninle hayatımız boyunca

Unutabilirmiyiz ikimizde yaşadıgımız güzel günleri

Sen, ben unutabiliriz belki o yaşanan günleri

Yıllar affetmez unutmaz unutamaz unutturmaz

Şimdi sana soruyorum ikimizde unutabilirmiyiz o yılları

İşte yıllar sonra ilk şiirimi yazıyorum acıyla

Sana olan özlemimle göz yaşlarıyla birlikte

Yıllar önce haykırmak istiyordum sana olan sevgimi

şimdi sadece beyaz sayfalara yazıyorum seni sevdiğimi', 'Yıllar önce bir sevgili bıraktım uzaklarda O şimdi gözü yaşlı pişmanlıkla geçmişteki günleri arıyor. ikimizde suçluluk duyuyoruz o günleri h...', ARRAY['Türk Edebiyatı','Şiir','Rafet Malkoç']::text[], 8.5, '{"poet":"Rafet Malkoç","poet_slug":"rafet-malkoc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/son-pismanlik-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem-1-*', 'sitem-1-bayram-tunca-bt5dm', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yine, elimde kalem, dilimde kelam

Yazayım dedim, ona üç beş kelam

Gözlerim uyku yüreğim duygu yüklü

Yaban gülümün hasreti belimi büktü

İçimdeki fırtınalar dalgalar oluşturdu

Dalgalar ruhumda girdaplar oluşturdu

Şair ümit ve hayaller peşinde koşturdu

Soğuk gecelerde hep ellerini ovuşturdu

Geceleri uykularım bölük börçüktü

Gözyaşım damla değil, oluk oluktu

Kınamayın dostlar saçım yoluk yoluktu

Ah betim benzim de soluk mu soluktu

İçimdeki fırtınalar soğuk mu soğuktu

Yüreğimdeki yaralar ovuk mu ovuktu

Hayallerim ümitlerim kopuk mu kopuktu

Gözyaşım damla değil, sanki oluk oluktu

Bağırayım dedim bağıramadım sesim çok kısıktı

Yaban gülümün nazları çok mu çok canımı sıktı

Yaban gülün gittikçe artan hasreti, belimi büktü

Şair onu beklemekten yaprak gibi ömrünü döktü

05.08.2001-14.45', 'Yine, elimde kalem, dilimde kelam Yazayım dedim, ona üç beş kelam Gözlerim uyku yüreğim duygu yüklü Yaban gülümün hasreti belimi büktü İçimd...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sitem-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözün Gizemleri*', 'gozun-gizemleri-bayram-tunca-q565i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen kalbimizin ve ruhumuzun aynasısın

Sen bellekle kalp arasında bir kontaksın

Vücut yapımızın inci mercanı yakutusun

Gönül pınarımızın en güzel çağlayanısın

Ey göz! bazen hoş, bazı da nahoş bakarsın

Ey göz! bazen neşe, bazen dehşet saçarsın

Ey göz! hakikati görürsen başımızda taçsın

Hakikati görmezsen, nazarımızda bir hiçsin

Sen en güzel ve en gelişmiş bir kamerasın

Her gördüğünün filmini bellekte arşivlersin

Sen en gelişmiş geniş açılı bir teleskopsun

Dünya ve ahret adına da en güzel şahitsin

Sendeki mıknatıs özelliği  hiçbir azada yoktur

Sendeki sıcaklık, Ay’da yıldızlarda dahi yoktur

Sıcacık bir bakışınla ne yürekleri hoplattırırsın

Her bakışla ya kazandırır, ya da kaybettirirsin

Bizi en güzel anlatıp/tanıtan nazar boncuğusun

Bir kitap dolusu sözün anlatamadığını anlatırsın

Sen çoğu kez, lâl-i güher sözden daha tesirlisin

Öyle bi etkilisin ki; kıldan ince, kılıçtan keskinsin

Sözler birbirine benzer, fakat gözler benzemezler

Gözler sanki vücudumuzun kara kutusu gibidirler

Gözler karakterimizi en iyi tanıtan bir organımızdır

Parmak izlerimiz gibi; bizi ele veren, gözlerimizdir

Sen nurunu kalpten, emri akıldan alan, bir yıldızsın

Ummanları dolduracak kadar bereketli bir kaynaksın

Kökü bütün vücudumuzu saran sanki asırlık çınarsın

Kalp, dünyamızın dışa açılan kristal iki penceresisin

Sayende görür, sayende severiz tüm sevdiklerimizi

Senin sayende öreriz, kalplerde en güzel dantelleri

Senin sayende seyrederiz o inci mercan güzellikleri

Sayende tadarız aşkı, sayende ulaşırız mutlulukları

Sen; hem alımlı, hem çalımlı, hem çekici, hem iticisin

Kalpler arasındaki diyaloğu sağlayan en güzel ileticisin

Senin sayende önümüzü görür, yönümüzü tayin ederiz

Seni O’nun bize armağan ettiği, en iyi bir azamız biliriz

Ey gözüm; esasen bir saman çöpünü dahi kaldıramazken

Nasıl oluyor da,  bu kadar ağır yükü kaldırabiliyorsun sen

Etrafına etten duvar ördürüp, üstüne de okla çitiletmişsin

Akvaryumun en güzel yerine yerleştirilmiş, inci mercansın

Ey iki gözüm, size şudur son sözüm, sakın kem bakmayın 

Dünyanın geçici güzelliğine aldanıp da başıma iş açmayın

Hem Nebimiz ''helal dairesi, keyfe kafidir'' dememiş miydi

Hem O, her halimizi her an, nigahbandır denmemiş miydi

15.05.2001-15.05', 'Sen kalbimizin ve ruhumuzun aynasısın Sen bellekle kalp arasında bir kontaksın Vücut yapımızın inci mercanı yakutusun Gönül pınarımızın en g...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/gozun-gizemleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynada Gördüklerim*', 'aynada-gorduklerim-bayram-tunca-i6j5i', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir elimde gençlik diğer elimde şimdiki resmim

Kendi kendime sordum nerde benim gençliğim

Akıl durdu, dil tutuldu, karşıdaki ayna konuştu

Öyle konuştu ki; her şeyi alenen ortaya koydu

Aynalar sadık bir dost gibi gerçekleri gösteriyor

Başımdaki alameti farikalar, aynayı doğruluyor

Her baktığımda, az daha yaşlandığımı söylüyor

Şöyle ihtar ediyor, geçlik gitti, ihtiyarlık geliyor

Ölüm, yaş-baş tanımıyor, her yaşa-başa geliyor

Aynanın yansıttığı gerçeklerden ibret alan alıyor

Alın çizgileri, hayatta yürünen patika yollar gibi

Gözler de güzde batmaya yüz tutan güneş gibi

Baştaki saçlar sanki hazan görmüş yapraklar gibi

Yüzdeki gamzeler solmaya yüz tutmuş güller gibi

Göz çukurları sanki darbe görmüş buzlu cam gibi

Bacaklar sanki işkence görmüş mahkumunki gibi

Şair bilir, yazsa gibilerin ardı arkası gelmeyeceğini

Bırak uğraşma anlatmaya aynalar anlatsın gerçeği

İnsan aynaya baktıkça zamanla anlar yaşlandığını

Yaşlandıkça ancak anlar şu dünyanın da faniliğini

05.08.2001.14.45', 'Bir elimde gençlik diğer elimde şimdiki resmim Kendi kendime sordum nerde benim gençliğim Akıl durdu, dil tutuldu, karşıdaki ayna konuştu Öy...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/aynada-gorduklerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Gülüm+', 'ah-gulum-bayram-tunca-xufls', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şu kalp gözümü ilk sende açsaydım

Keşke ilk seni görüp seni tanısaydım

İlklerimi, iliklerimde sende tatsaydım

Senden gayrilerinden hep kaçsaydım

Ah gülüm ah, kâtip arzun ben olaydım

Arzu ve isteklerini de bir bir sorsaydım

Yerine getirmek için seferber olsaydım

Getiremediğimde karınca gibi olsaydım

Gönül sarayımı sadece sana açsaydım

Ömür boyu sarayımda konuk etseydim

N’ iyi olurdu muradıma sende erseydim

Mutluluktan da ta arşı âlâya değseydim

Yıllardır senin gibi bir yabangülü düşledim

Ben de senin gibi bir gülüm olsun isterdim

Ömür boyu aşkımla gülmüş olsun isterdim

Bende onun sevdiği bülbül olmak isterdim

Aşk ateşimden ömür boyu korlansın isterdim

Her an, aşkımla şarj ve deşarj olsun isterdim

Hayatım boyunca koklayıp okşamak isterdim

Kem nazarlardan koruyup, kollamak isterdim

Ne edem kader işte; acele edip, kışta geldim

Baharda gelen, o yabangülüne yâr olamadım

Tek bir kerecik de olsa, sarılıp koklayamadım

Uktedir içimde hiç gül suyuyla paklayamadım 

Farklı zaman, farklı mekânda, gelmişiz dünyaya

Ah Leyla’m, tersine çeviremeyiz ki artık dünyayı

Haşa, sanki Allah, zıtlıklar için yaratmış dünyayı

Belki de bundan birlikte gelmemişizdir dünyaya

www.baysab.com/29.07.2001-10:20

''Aşk Ateşten Gömlek''', 'Şu kalp gözümü ilk sende açsaydım Keşke ilk seni görüp seni tanısaydım İlklerimi, iliklerimde sende tatsaydım Senden gayrilerinden hep kaçsa...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/ah-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Şu Geceler', 'ah-su-geceler-bayram-tunca-fqfxl', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yine sessizliğe büründü, mehtaplı geceler

Bak dökülüyor gözden yaş, dilden heceler

Şu fani dünyadan hep gelip geçiyor niceler

Gel artık sayıklayıp duruyorum kaç geceler

Yine karanlığa büründü sensiz kasvetli geceler

Hasretinden, içimde çay demledim kaç geceler

Siluetin gitmiyor gitmez gözümden kaç geceler

Hep seni sayıklayıp duruyorum, sayısız geceler

Yine deli gönül hasretinden sessizliğe büründü

Bak şafak söküp, çoban yıldızı ufuktan göründü

Bayram Mecnun’un olup, susuz çöllerde süründü

Neredesin saç sakal ağardı, ihtiyarlığım göründü

Bak yine deli gönül sensizliğin hasretiyle üzüldü

Dillerden dökülen incilerle methiyelerin düzüldü

Yokluğunda Bayram yıllarca, yetim gibi büzüldü

Bak! şair saçı sakalı ağartıp ihtiyarlığa büründü

Olaydım, olaydım; Yaban Gülüme eş ben olaydım

Olaydım, olaydım; ela gözündeki kaş ben olaydım

Olaydım, olaydım; gözlerindeki oklar ben olaydım

Olaydım, olaydım; kalbindeki ilk aşk ben olaydım

Olaydım olaydım senin Mecnun’un ben olaydım

Olaydın, olaydın sen de benim  Leylâ''m olaydın

Ne olurdu, sen de bana Leylâ gibi âşık olsaydın

Ne olurdu; ben de senin aşkınla mutlu olsaydım

B. TUNCA/29.07.2001-10.20', 'Yine sessizliğe büründü, mehtaplı geceler Bak dökülüyor gözden yaş, dilden heceler Şu fani dünyadan hep gelip geçiyor niceler Gel artık sayı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ah-su-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ekonomik Kriz', 'ekonomik-kriz-bayram-tunca-9aeu6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle bir savaş verdik ki; cephedekileri aratmazdı

Şiddeti ve etkisi ağustos depreminkinden etkiliydi

Öyle bir savaş ki; ne cephesi, ne de düşmanı belli

Aslında düşmanı siyasi ve enflasyon canavarı belli

Bu verdiğimiz savaş öyle hasar meydana getirdi ki

Öyle tesirliydi ki; Çernobil nükleerinden daha tesirli

Hasarı cephedeki ve depremdekinden daha da tesirli

Hasarı hem bedenlerde, hem de ruhlarda daha etkili

Cephedeki savaşta ölseydik belki de şehit olurduk

Biz ekonomik krizden ölmedik; fakat niyazi olduk

Ölenler belki kurtuldu, kalanlar çok saç baş yoldu

Ekonomik kriz, cephe savaşından daha çok yordu

Kısa sürede zengin daha zengin, fakir daha fakir oldu

Buna, en çok siyasilerimizin yersiz beyanı sebep oldu

Uğrunda canını vereceği ülkesinden; nefret eden oldu

Vize alabilen arkasına bakmadan ülkeyi terk eder oldu

Onbinlerce aile, yüzlerce firma, bu krizden heder oldu

Öyle aileler vardı ki, evine ekmek bile götüremez oldu

Öyle aileler vardı ki, sebze ve meyvenin tadını unuttu

Öyle aileler vardı ki,  hane ve pazarının yolunu unuttu

Şu bir gerçekti ki, gariban halkımız suçsuz ve pâktı

Buna rağmen ekonomik kriz yine de halkımızı yaktı

Zam yağmurları sağanak sağanak halkın üzerine aktı

Ülkenin durumuna Uganda halkı bile, çok garip baktı

Kimileri bankaları hortumladı, kimileri de hortumlattı

Kimileri çilingir sofrasında göbek atıp, $''ı havaya attı

Halkımız baştan bir şey anlayamadı, şaşkın şaşkın baktı

Sonunda olanlar oldu, ülke ekonomik kriz batağına battı

Siyasilerimiz her zaman olduğu gibi suçu başkasına attı

Krizi anlatmak için insanlar yapmadığı eylem bırakmadı

Grev, yazar kasa, tiyatro, intihar, eşekli eylemler yapıldı

Halkımız meramını anlatamadı; gözyaşları oluk oluk aktı

Tarihten ders almamışız ki; önceki gibi masada kaybettik

Ülkenin ekonomisini önce ''imf'' sonra Dervişe teslim ettik

Kurtuluruz ümidiyle ''imf'' ne derse yaptık fakat yine battık

Millet olarak, Mehdi gibi bir kurtarıcının gelmesini bekledik

Ekonomik kriz için kimler neler yazıp, neler söylemedi ki

Krizden etkilenen biri olarak bir şeyler yazayım dedim ki

Tarihe ışık tutsun, fakat dil söylemez, kalem yazmaz oldu

Söyleyeceklerimi tam söyleyemedim elim ayağım tutuldu

B. TUNCA/23.07.2001-16.50', 'Öyle bir savaş verdik ki; cephedekileri aratmazdı Şiddeti ve etkisi ağustos depreminkinden etkiliydi Öyle bir savaş ki; ne cephesi, ne de dü...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/ekonomik-kriz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayatın Cilvesi', 'hayatin-cilvesi-bayram-tunca-fkoim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Çekemez iken bir Muhacir kızın nazını

Hayat yolunda rast geldim bir de.. kızına

Ben nasıl çekerim ikisinin birlikte nazını

Verin bana sazımı anlatayım alın yazımı

Hayatta o Muhacir kızı çok kök söktürdü

Bir......... kızı da çok saçlarımı döktürdü

İkisinin sızısı şair yapıp derdimi döktürdü

Birinin nazı, diğerinin de hasreti öldürdü

Alsaydım; sağ koluma Muhacir kızını

Alsaydım sol koluma da......... kızını

Derman olurlar mıydı dersin acaba sızıma

Bence tabip dahi dindiremezdi artık sızımı

Ah ….. kızı bir de sen açtın sinemde yara

Nasıl olup da girdin, belleğimle/yüreğime

Bazen şikayet edesim geliyor seni Allah’a

Ama, kıyamıyorum ki senin şu gençliğine

Ne diyebilirim ki sağlık ve bahtın açık olsun

Temenni gün gelir, sen de dengini bulursun

Hayat varsın hep böyle zıtlıklarla dolu olsun

Mecnunluğuma varsın, o sebep olmuş olsun

Bu aşık bir gün çalıştığın hastaneye düşerse eğer

Senin özleminden dolayı düştüğünü anlasan yeter

Serum falan takmaya kalkma sevgini göster yeter

O son nefesinde bunu hissedebilirse bu ona yeter

14.07.2001-11:30', 'Çekemez iken bir Muhacir kızın nazını Hayat yolunda rast geldim bir de.. kızına Ben nasıl çekerim ikisinin birlikte nazını Verin bana sazımı...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/hayatin-cilvesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahilde Gördüklerim-2-', 'sahilde-gorduklerim-2-bayram-tunca-vebft', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Deniz yaz sıcağıyla buram buram terliyordu

Sema güneşin voltajlı lambasıyla yanıyordu

İkisi arasında kalan cisimler de kavruluyordu

Ilık esen rüzgârla denizde met-cezir oluyordu

Kıyıdaki tüm canlılar çifter çifter geziyordu

Martıların mutluluk çığlıkları yankılanıyordu

Sevenlerin mutluluğu gözlerinden okunuyordu

Bu güzellikler Ferhat''a teselli yerine üzüyordu

Sahilde yalnız gezen bir ördek, bir de Ferhat vardı

O gözlerini uzak ufuklara dikmiş Leyla''yı arıyordu

Ördek kara ve havada bulamadığını suda arıyordu

Ferhat da kaybettiği Leyla''sını denizlerde arıyordu

Dalgalar kıyıya değil, Ferhat''ın sinesine çarpıyordu

Ferhat''ın kalbi; kurulu saat gibi Leyla için atıyordu

Ilık ılık esen meltem yeli, iğdenin dalını okşuyordu

Şairde iğdenin dalını Leyla''nın saçı gibi okşuyordu

Ferhat martılar gibi Leyla için çığlıklar atıyordu

Leyla ya duymuyor ya da duyup da aldırmıyordu

Ferhat, Leyla için ördekten bile yardım diliyordu

Ferhat, Leyla''sı için ördeğe şöyle sesleniyordu; 

Ördek suya dal da gel, yârden haber al da gel

Eğer o yâr gelmez ise; tut kolundan al da gel

Eğer getiremez isen, o yârdan haber al da gel

Hiç olmazsa, ipek saçlarından bir tel al da gel

B. TUNCA/14.07.2001-18.00', 'Deniz yaz sıcağıyla buram buram terliyordu Sema güneşin voltajlı lambasıyla yanıyordu İkisi arasında kalan cisimler de kavruluyordu Ilık ese...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/sahilde-gorduklerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şeyim Oldun (aşkta)', 'her-seyim-oldun-askta-bayram-tunca-wqkkm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün pazar, benim gönlü sanki hazar

Şair oturmuş sahilde senin şiirini yazar

O yazdıkça yüreğindeki hasreti de azar

O bu nedenle, çoğu zaman dertli yazar

Ah sözlerin kor gibi içime düşüp yaktı

Benim yanışım Mecnun’unkinden farklı

Yanış nedenimi gizledim yüreğimde saklı

Benim yarim Leyla ile Şirinden daha tatlı

Aşk hayatımda bir tek idealim, emelim vardı

O da Leyla''ma ulaşıp, aşkımı duyurabilmekti

Onu yapabildim, ölsem de gam yemem artık

Ben Leyla''dan başka bir şey düşünmem artık

Daha düne kadar hülya ve rüyalarımdaydın

Bugünse, artık idealim ve tek gayem oldun

Sevgi ve muhabbetinle kalbime konuk oldun

Sen benim, Ay’ım, Güneş’im, yıldızım, oldun

Leyla, tutan ellerim, yürüyen ayağım oldun

Gören gözlerim ve duyan kulaklarım oldun

Duygum, düşüncem, idealim, aşkım, oldun

Oldun/oldun, aşkta benim her şeyim oldun

Sıçrattığın kıvılcımla tüm benliğimi alev topu yaptın

Daha elin/elime, gözün/gözüme, değmeden yaktın

Daha kolun/koluma, dizin/dizime, değmeden yaktın

Tenin/tenime, dudağın/dudağıma, değmeden yaktın

İçimdeki yangını söndürmek için, itfaiyecim olmadın

Gece-gündüz, imdat çığlıklarıma da kulağına kapadın

Aşkınla yanan sineme su yerine sanki benzin döktün

Aşkınla yanan yüreğime sanki yanardağa döndürttün

Bende benlik diye bir şey bırakmayıp alıp götürdün

Şimdi sanki ben ben değilim de senin kölen gibiyim

Seninle atıyor yüreğim, seninle bakıyor ela gözlerim

Sanki sen olmazsan, duracakmış gibi oluyor kalbim

Bak dilim sen, fikrim sen, zikrim sen, her şeyim sensin

Hülyalarımda, rüyalarımda yalnız bırakmayan da sensin

Hülyalarım ve rüyalarımda da kucağıma aldığım sensin

Aşkta benim, Leyla''m, Şirinim, Aslım, her şeyim sensin

B. TUNCA/15.07.2001-11.35', 'Bugün pazar, benim gönlü sanki hazar Şair oturmuş sahilde senin şiirini yazar O yazdıkça yüreğindeki hasreti de azar O bu nedenle, çoğu zama...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/her-seyim-oldun-askta-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşin Doğuşu+', 'gunesin-dogusu-bayram-tunca-zfrkk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Güneş ufuktan doğdu doğacak

Mutluluk beni, boğdu boğacak

Güneş ufukta sanki altın portakal

Güneş ne olursun öylece orda kal

Güneş karabulutları kovup ak eyledi

Doğuşuyla latifelerimize apak eyledi

Eyledi-eyledi her şeyi ne güzel eyledi

Gündüzleri gecelerden daha ak eyledi

Doğuşuyla sevinç/neşe dolar içimize

Batışıyla hasret, çile dolar kalbimize

Senin tükenmez yakıtın nurun kimden

Senin intizam ve nizamın acep kimden

Seninle olduğumuzda, ufkumuz sanki derya olur

Seninle olmadığımızda, ufkumuz sanki kuyu olur

Seninle olduğumuzda elimiz kolumuz iyi iş yapar

Sen hiç doğmasaydın, bütün cisimler ne iş yapar

Hey kul, aç gözlerini bak güneş ufuktan doğuyor

Sen de gör Güneş gece karanlığını nasıl kovuyor

Tüm varlık, onu görünce sanki yeniden doğuyor

Onun gelişiyle tüm cisimler mutluluğa boğuluyor 

Aah, hep sensizliğin hasretini çekiyoruz geceleri

Uykumuz kaçıyor, şiirlerimizi döküyoruz hecelere

Sen olmasaydın her şey çok soğuk gelirdi bizlere

Gece gibi gündüzün de karanlıkta bırakma bizleri

Her batışında, ya bir de dönmezsen deyip üzülürüz

Seni görmezsek, öksüz/yetim çocuk gibi büzülürüz

Ne olur, sakın gidip de geriye dönmemezlik yapma

Bizleri, anasız babasız gibi yetim ve öksüz bırakma

19.07.2001-10:45', 'Güneş ufuktan doğdu doğacak Mutluluk beni, boğdu boğacak Güneş ufukta sanki altın portakal Güneş ne olursun öylece orda kal Güneş karabulutl...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/gunesin-dogusu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim-1-*', 'siirlerim-1-bayram-tunca-zkprn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bazen yaş damlar gözlerimden

Bazen ter damlar bedenimden

Bazen kan damlar yüreğimden

Bazen inciler dökülür dilimden

Elbet kimse ağlamaz keyfinden

Benim çektiklerim kaderimden

Şiirlerimin içeriyi öykülerimden

Etkilenir dostlarım şiirlerimden

Şiirlerim manili ve pek manidardır

Kalemle satırlara dizilen incilerdir

Gönül deryamdan çıkan türkülerdir

Hayatta bizzat yaşanılan öykülerdir

Hecelerini akıl süzgecimde süzdüm

İki yılda beş yüz küsur şiir düzdüm

Kelimeleri tespih gibi satıra dizdim

Öykülerimi ayrı ayrı şiirlere dizdim

Öykülerini akıl kütüphanemden aldım

Sansürsüz duygularımla harmanladım

Gözyaşlarımla yoğurup da mayaladım

Şiirlerimi alın teri göz nuruyla yazdım

Kendi akkorlu fırınımda pişirip sundum

Karşılığında, ne para/ne de pul umdum

Çile çekenlerden, ne ilk, ne de sondum

İsteyen çilemden içebilir yudum yudum

Hayatım boyunca oradan oraya kondum

Çoğu defa da, bir stepne yerine kondum

Dayanabilecekleri çilemin şiirine sundum

Arzu eden, çilemden içsin yudum yudum

Kader mahkumu hayat hapishanesindeydim

Hayat boyunca, acıklı çile çeken, bir neydim

Kimse bilmedi, bir Mecnun muydum neydim

Her şeye rağmen, çilelerle yaşamayı sevdim

Bilerek almadım bir başkasının hamurundan

Eğer ki bir iki hece karışmışsa, dostlarımdan

Buda komşularının tuzu, biberi, mayası olsun

Her kim şiirlerimden maya alırsa, helal olsun

Şiirimi okuyan, kendini benim yerime koysun

O zaman şiirimi okuma zevkine doymuş olsun

Şiirlerim bir kere okunmakla tadına doyulmaz

Her şiirim bir hayat öykümdür, ayrı koyulmaz

Her kim internetdeki şiir sitemi ziyaret ederse

Bizzat şahsıma ziyaret etmiş gibi kabul ederim

Her kim şiirlerimi yapıcı yönde yorum yaparsa

O’nu sırtımdaki akrebi alan dost olarak bilirim

21.11.2000-14.34

not:Duygu Harmanı kitabımın 10-11 sayfasında yayınlanmıştır', 'Bazen yaş damlar gözlerimden Bazen ter damlar bedenimden Bazen kan damlar yüreğimden Bazen inciler dökülür dilimden Elbet kimse ağlamaz keyf...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/siirlerim-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiirlerim-2', 'siirlerim-2-bayram-tunca-rbekf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Şiirlerimdeki öyküler yaşantımı anlatır

Şiirlerimdeki sitemler çilelerimi yansıtır

Şiirlerimdeki hatalar zaaflarımı gösterir

Şiirlerimdeki gizemler sırlarımı ele verir

Şiirlerimin hecelerini bir bir belleğimde süzdüm

Satırlarını alt alta getirerek methiyeler düzdüm

Kelimeleri yan yana tesbih gibi satırlara dizdim

Şiirlerimle, sizi bazen sevindirip, bazen üzdüm

Şiirlerimdeki gibi bazen yaz, bazen de güzdüm

Bazen yanardağdaki sönmek bilmeyen közdüm

Şiirlerimi türkü sözlerine yatkın sözlerle düzdüm

Şiirlerimle bazen sevindirip, bazen böyle üzdüm

Mısralarımı merdiven yapsaydım ta arşa çıkardım

Zaten hayalen yedi kat semada deveran ederdim

Yolum gökkuşağından, fenerim ise Ay ışığındandı

Yazdıklarım, duyup/görüp/yaşadığım öykülerimdi

Gece gündüz hayalen şu küre-i arzı arşınlardım 

Gördüklerimden hem ilham/hem de ibret alırdım

Görüp duyduklarım karşısında, hayli şoke oldum

Bazen de mutluluk tufanına tutulup boğulurdum

09.07.2001-10:10', 'Şiirlerimdeki öyküler yaşantımı anlatır Şiirlerimdeki sitemler çilelerimi yansıtır Şiirlerimdeki hatalar zaaflarımı gösterir Şiirlerimdeki g...', ARRAY['Türk Edebiyatı','Şiir','Bayram Tunca']::text[], 8.5, '{"poet":"Bayram Tunca","poet_slug":"bayram-tunca","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siirlerim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçer Gider', 'gecer-gider-johann-wolfgang-von-goethe-egkr0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'geçer gider yeryüzünde                                                                en güzel nimetler bile                                                                    zaman sınırlarını aşan düşüncelerimizle                                      yaptığımız etki düşünenlere                                                           bir tek o vardır                                                                                o kalır sonsuzluğa', 'geçer gider yeryüzünde                                                                en güzel nimetler bile                                ...', ARRAY['Türk Edebiyatı','Şiir','Johann Wolfgang von Goethe']::text[], 8.5, '{"poet":"Johann Wolfgang von Goethe","poet_slug":"johann-wolfgang-von-goethe","theme":"Türk Şiiri","is_hero":false,"total_lines":1,"source_url":"https://www.antoloji.com/gecer-gider-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Sen', 'ya-sen-ahmet-sahin-soner-kjvtr', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şimdi sen yoksun yanımda....

İşte ben, 

Bizim dediğimiz o küçük deniz ülkesinde, 

Martıların dans ettiği uçurumun 

Suların körük, köpük çağladığı, 

Uçurumun bir ucundan 

Sessizce dalgalanan o bizim denizimize, 

Sevgi çiçekleri atarken...

Sisli bir günün sabahında, 

Karşı kayalıklarda seni hayal ediyorum.

Biliyorum birkaç ay önce, 

Yine biz, 

Yine ikimiz, 

Senli, ama sensiz 

Umutla ilerlerken yelkenliler

Ayaklarımızın yanışına aldırmadan

Ve aldırmadan kabukların ayaklarımızı kesmesine 

İnatla yaşamaya çalışmıştık hayatı

Sen ve martılar, 

Ben ve deniz, her birimiz....

Bizim yalnızlığımızdı hani; 

Bir rüzgar esmiş, dalgalar savurmuştu tenini, 

Unutamadım seni alabora edişini, 

Ürkek, masum tavrını ve gidişini, 

Sen ölmeden önce, 

Biz ağlamadık hiç, 

Sen ölmeden önce biz hiç çıplak kalmadık....

Ağlamadık......

Hatırla; 

O yaz akşamını, 

Yüksekteki bir taşın üstünde....

Bizim dediğimiz denizden, 

Bizim dediğimiz göktaşına, 

Söylerken şarkıları ve şiirlerin en güzel mısralarını, 

Eğer bir gün bıkarsan benden, 

Ama yüreğin severse, benden kalma bir umudu 

Ve çekip alamazsan, bizden beni benden seni 

Burada ol demiştin, işte tam şurada

Ay’ ın denize teğet düştüğü, 

Dalgaların çağlarken, 

Küçük balıkçı barınağında sustuğu sahilde......

Beni  düşün demiştin, 

Her güneş batışında, 

Uzak bir sahilde bir akşam üstü serinliğinde

Farklı bir deniz ülkesinde, 

Seni düşünüyor olacağım demiştin ya; 

Hatırımda biliyor musun! ! ! ! ! 

Ama ben senden bıkmadım, 

Seni sevmekten asla yılmadım, 

Denizler aldığı günden beri seni benden; 

Ben; 

Her gece, 

Senin şerefine kadeh kaldırıyorum denize....

Seni benden alan o kahrolası denize, 

Ay düşüyor üzerime titriyorum, 

Ben sensiz bir ay ışığında ısıtamam ki yüreğimi....

Seni düşünüyorum.....

Sus konuşma biliyorum, 

Uzak deniz ülkelerine uçan kuşlara sesleniyorum

Biliyorum duyuyorsun veya  avunuyorum 

Ama olsun, belki duyarsın diye 

Seni Seviyorum 

Seni Seviyorum

Seni Seviyorum 

Nefesimi yollarken sana rüzgardan sana sesleniyorum

Ya sen.........', 'Şimdi sen yoksun yanımda.... İşte ben,  Bizim dediğimiz o küçük deniz ülkesinde,  Martıların dans ettiği uçurumun  Suların körük, köpük çağl...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/ya-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gel Sana Doğur Beni', 'gel-sana-dogur-beni-mine-bahceci-tpqfa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sen / yüreği dağda delikanlı

Bulutsuz düşmüş gönlüne güneş

Olduğundan da güzelsin bende

Kışkırtır isyana sesin

Büyük düşler yaraşır gecene

Düşlerine sar beni! ..

Ben / haritası yitik define

Mülteciyim yurduna

Alıp gidemem başımı

Dudağından ayışığı içtiğim

Kutsal günahlarımın anası

Sevdana emzir beni! ..

Söyle / karanfillerin saldığı rüzgar

Bu kaçıncı ihtilal

menekşe hülyaların türküsüyle öptüğüm

Öldüm, ölüm de yakıştı koynunda

Sende düşmüş yüreğim

Gel, sana doğur beni', 'Sen / yüreği dağda delikanlı Bulutsuz düşmüş gönlüne güneş Olduğundan da güzelsin bende Kışkırtır isyana sesin Büyük düşler yaraşır gecene D...', ARRAY['Türk Edebiyatı','Şiir','Mine Bahçeci']::text[], 8.5, '{"poet":"Mine Bahçeci","poet_slug":"mine-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gel-sana-dogur-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Çal da Gel Geceden', 'ay-cal-da-gel-geceden-mine-bahceci-worh1', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen miydin kapımı çalan

Hüzünlü sevda gecemin

		onur konuğu

Ayrılığın ilk dakikası, 

		son saniyesi; 

Hoş geldin...

Kendini mi ararsın gönül evimde

Bilmez misin, 

Yokluk içindeyken odam

	kapımı ilk aralayan sen

		kilitleyen yine sen

Sıkılır mısın

Başka konuk seçmesem? 

Yüzlerce, binlerce kez

Seni seninle çarpıp

		sana bölsem...

Nasılsın görmeyeli? 

Ben hep böyle

İkili yalnızlıklarla çarpışıyorum

	gittin gideli

Uykusuz karşılıyorum nicedir

	sabahın gürültüsünü

Sonunda yorgun, bitkin, çaresiz

Akşamın dinginliğine gömüyorum kendimi

	o da içimi acıtıyor

		biliyor musun? ..

Sahi neden gelmiştin

Yıllardır aradığını bulamadın da

	sormaya mı? 

Yoksa

	toplamaya mı unuttuklarını? 

Bıraktığın o güneş

	çok var ki battı; 

Saçlarımda üç beş tel

	bende gece olurken

		sıkıldı da, gündüzle nikâhlandı! ...

İşte böyle sevdiceğim, 

Her şeye karşın

	taktınsa yine de aklına beni

		al tedbirini önceden

Yok artık sabahlarım

Ay çal da gel geceden...

MERSİN', 'Sen miydin kapımı çalan Hüzünlü sevda gecemin 		onur konuğu Ayrılığın ilk dakikası,  		son saniyesi;  Hoş geldin... Kendini mi ararsın gönül...', ARRAY['Türk Edebiyatı','Şiir','Mine Bahçeci']::text[], 8.5, '{"poet":"Mine Bahçeci","poet_slug":"mine-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ay-cal-da-gel-geceden-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğe Sitem', 'bebege-sitem-abdurrahim-karakoc-revtr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', '''Aman gelme'' dedim, bak geldin işte

Dünyaya meylin var, ''beşer''sin bebek

Bir bilsen dünyamız neyin nesidir

Ayırır ağzını işersin bebek.

Kimisi su katar içtiğin süte

Kimisi at sokar yediğin ete

Günahtan, hileden, haramdan öte

Zulmet kuyusuna düşersin bebek.

Yukarıya gitsen ''köle'' sayarlar

Aşağıya insen tefe koyarlar

Her saat bir başka renge boyarlar

Baktıkça sen sana şaşarsın bebek.

Önün bal-petekli, elin mühürlü

Omuzun kötekli, dilin mühürlü

Haftan ipotekli, yılın mühürlü

Aydan, günden mahrum yaşarsın bebek.

Sevgimiz rüşvettir seversek seni

Aldatmak içindir ne versek seni

Kalleş çağımızla eversek seni

Gerdeğe girmeden boşarsın bebek.

(Beşinci Mevsim)', '''Aman gelme'' dedim, bak geldin işte Dünyaya meylin var, ''beşer''sin bebek Bir bilsen dünyamız neyin nesidir Ayırır ağzını işersin bebek. Kimi...', ARRAY['Türk Edebiyatı','Şiir','Abdurrahim Karakoç']::text[], 8.5, '{"poet":"Abdurrahim Karakoç","poet_slug":"abdurrahim-karakoc","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bebege-sitem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öyle Bir Gitki! Kelimeler Tükensin', 'oyle-bir-gitki-kelimeler-tukensin-sair-bera-xjv94', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tutmasın gözlerini küskün bir buğu 

Zaman herzamankinden  çabuk tükensin 

Ne anısı kalsın güzel günlerin

Ne sancısı kirli dünlerin

Hiç ardına bakma hiç soru sorma 

Öyle bir git ki kelimeler tükensin

Yalınayak kalmış bir sevda gibi 

Zaman haklıyıda haksız çıkarsın 

Hepsi hepsi birkaç yudum mutluluk 

Ne küfret ne yakın ne kız kendine 

Bırak öyle kalsın hayaller bile 

Öyle bir git ki kelimeler tükensin

Dağılsın ağzında bütün gülüşler

Yol bulamaz olsun hayaller düşler 

Sensizde yaşanır yarınlar dünler 

Mutluluğun resmi baştan çizilsin

Bir tren gürültüsü bırakma izde

Öyle bir gitki kelimeler tükensin

Bu aşkın sırlarını rüzgara verip verip 

Anılarla kalan hesabı kesip 

Ağlama boşuna çok geç sevgili 

Son bir gülüş fırlat maziye dair 

Öyle bir git ki kelimeler tükensin', 'Tutmasın gözlerini küskün bir buğu  Zaman herzamankinden  çabuk tükensin  Ne anısı kalsın güzel günlerin Ne sancısı kirli dünlerin Hiç ardın...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/oyle-bir-gitki-kelimeler-tukensin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün Kesişirse Yollarımız', 'birgun-kesisirse-yollarimiz-sair-bera-cdsub', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir gün kesişirse yollarımız istiklal caddesinde

arka cebimdeki kelimelerden bir demet sunacağım sana

açık bir çay içecegiz beraber

bir papatyanın henüz koparılmamış yapraklarını

sonu belli bir falla açacağız

kimin yüzü kızaracakilk önce

ve kim kalkıp gidecek masadan erken davranıp

kim laf sokacak

kimin umrunda bile olmayacak

bu aşkın hesabını kim kimden soracak

hiç dert etme gözbebeğim

zaman öylesine açki 

senide benide bir lokmada yutacak', 'bir gün kesişirse yollarımız istiklal caddesinde arka cebimdeki kelimelerden bir demet sunacağım sana açık bir çay içecegiz beraber bir papa...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/birgun-kesisirse-yollarimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Garson', 'garson-sair-bera-7xauy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tadını aldın giderken 

emirganda çayların

garson! bir çay, bir soda 

birde yanım daki boş koltuğa 

eski zamanlardan kalma

vefasızlığın türküsünü getir

sanki o varmış gibi konuşmalarıma 

aldırma 

çünkü biliyorum 

gelecek bir başkasıyla buraya 

o zaman 

bir katre ihanet akıtırsın içeceğine 

anlamaz korkma 

sakın yalnız geldiğimi söyleme ona 

sevinir

of canım sıkılıyor ya 

köfteler kalsın 

sen yinede al parasını 

benden 

adam gibi sevebilenlere 

ısmarlarsın', 'tadını aldın giderken  emirganda çayların garson! bir çay, bir soda  birde yanım daki boş koltuğa  eski zamanlardan kalma vefasızlığın türkü...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/garson-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Bir Çocuk', 'yuregimde-bir-cocuk-bulent-pinarbasi-t00rm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Her şey çoğalır dünyada yaşamak adına Kanundur bu.

Sevgi çoğalır, övgü çoğalır, kaygı çoğalır

Kin, nefret, düşmanlık

Yalan ve yalınlık

Yılanlık

Çıyanlık çoğalır

Sitemler de, görkemler de çoğalır.

Göz pınarlarındaki yaş, 

dudak kenarlarındaki kırık dökük ve yavaş

Ve tedirgin gülüş ve bakış

Ve kaçışlar da çoğalır, kaçınılmaz

Her şey çoğalır dünyada

Var olan ve olacak

Yar olan ve sıcak

Kurak ve bireysel sevgiler

Sevgililer

Kahrolası ihanetler çoğalır

Yakınlıklar çoğalır teknoloji gereği

Hasretlikler çoğalır yaklaştıkça

insan insana uzaklaşır

Uzaklar çoğalır ulaşılmaz biçimde

Us almaz bunu

Her şey çoğalır kolay ya da yapay

İnkar edilemez bir gercek ve isyan

Kar eylemez çoğalsa da zamana uyup

Çığ gibi çoğalsa da çağ tekdüze

Bil yalnızlık yerinde sayar uygun adım

Çünkü o zaten çoktur, 

Ve yalnızlık suçtur bu zamanda

Ve çocuktur...

Ve çocuk, 

Umuttur her daim yüreklerde.

İşte ben de böyle

Çoğalmakla çocukluk arasında

Med-cezirler yaşamakla

İhanet etmekteyim insanlığa

Yüreğimde bir çocuk, 

Yüreğim de bir çocuk...', 'Her şey çoğalır dünyada yaşamak adına Kanundur bu. Sevgi çoğalır, övgü çoğalır, kaygı çoğalır Kin, nefret, düşmanlık Yalan ve yalınlık Yılan...', ARRAY['Türk Edebiyatı','Şiir','Bülent Pınarbaşı']::text[], 8.5, '{"poet":"Bülent Pınarbaşı","poet_slug":"bulent-pinarbasi","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/yuregimde-bir-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yarının Hesabını Yapmadım.', 'yarinin-hesabini-yapmadim-cengiz-yazici-iklge', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir bugüne, Bir düne, birde sana baktım...

Ben vardım da, seni bir bir yere koyamadım.? 

Bu gün için, belkide çok geçti zaman.

Dün se, erkendi vakit.DAHA DOĞMAMIŞTIN...

Ama bir gerçek vardı.Sen ve ben vardık.

Tam isyan noktasında buldum gerçeği, 

YARIN''ın hesabını.Hiç yapmamıştık...! ! ! !', 'Bir bugüne, Bir düne, birde sana baktım... Ben vardım da, seni bir bir yere koyamadım.?  Bu gün için, belkide çok geçti zaman. Dün se, erken...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yarinin-hesabini-yapmadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nush Makamında', 'nush-makaminda-zemci-cetinkaya-upohp', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Vefa görmeyince yâr u ağyardan

Sen de bir vefasız olma be Hasan

Gülün ayrılması mümkün mü hardan

Dostluğa bahane bulma be Hasan

Kara bahtım bir kez gülmüyor diye

İnsanlar kadrimi bilmiyor diye

Hiçbir istediğim olmuyor diye

Saçını başını yolma be Hasan

Bilirsin ki unutulur her hata

Salihçe bakmalı insan hayata

Güçlü durumdayken asla ve kat''a

Mazlumun âhını alma be Hasan

Ne ağa ne paşa ne hanım diye

İnsanlar gönenir insanım diye

Konyalı meşhur bir Hasanım diye

Benlik davasını çalma be Hasan

Muhabbet satılmaz otuza kırka

Fedâkârlık ister dikenli hırka

Seyahat et derim garb ile şarka

Bu güzel öğüde gülme be Hasan

Âleme nush için kendini yorma

Sorana cevap ver sen soru sorma

Gün olsun işitme gün olsun görme

Bazen bildiğini bilme be Hasan

Sevgiyle gelmişiz biz bu cihana

Bu yolda ahdimiz vardır Sultana

Gürûni dostundur gül attı sana

İncinip kusura kalma be Hasan', 'Vefa görmeyince yâr u ağyardan Sen de bir vefasız olma be Hasan Gülün ayrılması mümkün mü hardan Dostluğa bahane bulma be Hasan Kara bahtım ...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/nush-makaminda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İtiraf', 'i-tiraf-zemci-cetinkaya-z6840', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir virane hana döndüm yıllardır

Kervan gelip geçmez yolcum kalmadı

Seyrangâhım dağlar, hânem çöllerdir

Terk edecek tahtım tâcım kalmadı

Belâ dedim kelâmına cânânın

Şâhidim ben ilâmına cânânın

Meftun oldum selâmına cânânın

Düşmanlığım, kinim, öcüm kalmadı

Mihnetiyle deli gönlüm şâd olur

Sensiz vatan yaban olur yâd olur

Vuslat için her zerrem Ferhad olur

Lâkin ayrılığa gücüm kalmadı

Esirgemiş canı, vermiş cihânı

Övünmesin boşa çölün mihmânı

Üç harf beş noktaymış Leylâ destânı

Efsâneye ihtiyacım kalmadı

Rüyâ dillenirse zindan nâfile

Buğday çuvalında ne kutlu hile

Söküğü sırtında bir gömlek ile

Dönünce  sılaya acım kalmadı.', 'Bir virane hana döndüm yıllardır Kervan gelip geçmez yolcum kalmadı Seyrangâhım dağlar, hânem çöllerdir Terk edecek tahtım tâcım kalmadı Bel...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/itiraf-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşuni ve Yeşil Şehre Serenat', 'kursuni-ve-yesil-sehre-serenat-zemci-cetinkaya-yfwj6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir ikindi vakti şu Boztepe''den

Gözlerin ve engin denizin rengi

Alıp giden beni alıp hapseden

Yağmur bakışınla derya âhengi

Ayışığı fındık bahçelerinden

Meltem ile bir serenat söylüyor

Dalgaların iniltisi derinden

Kulağıma kutlu bir ad söylüyor

Akarmış dereler yokuş yukarı

Bakışların çevrilince yabana

Yeşil unutturur leyl ü neharı

Bir bambaşka devran sunar insana

Kurşuni ufuklar hicran söylüyor

Her yelken içimde vedâ bûsesi

Leylâ kitabından destan söylüyor

Melet vadisinde Bülbül deresi', 'Bir ikindi vakti şu Boztepe''den Gözlerin ve engin denizin rengi Alıp giden beni alıp hapseden Yağmur bakışınla derya âhengi Ayışığı fındık b...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kursuni-ve-yesil-sehre-serenat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Duhan', 'duhan-zemci-cetinkaya-25i2o', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Farkındayım elbet bilmez değilim

Mürtefi yerlerde duman oluyor

Bunu söylemeye varmıyor dilim

Ehl-i dilin hali yaman oluyor

Felek mağlup olup dize gelse de

Mutlu yaşayarak mutlu ölse de

Onsuz ağlasa da onsuz gülse de

Aşksız geçen hayat ziyan oluyor

Nice elif boyu yaye döndüren

Bir ateştir otu nâye döndüren

Harabiyi harabeye döndüren

Niçin sevda değil duhan oluyor

Anlasın sitemim müfti efendi

Âşıklar daima nefsini yendi

Mecnun''un da ciğerleri tükendi

Ama dost dilinde destan oluyor', 'Farkındayım elbet bilmez değilim Mürtefi yerlerde duman oluyor Bunu söylemeye varmıyor dilim Ehl-i dilin hali yaman oluyor Felek mağlup olup...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/duhan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diğer Tufan', 'diger-tufan-zemci-cetinkaya-ecvrv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Vuslat sıla kadar yakın olsaydı

Ne söylerdi şiir neye yarardı

Cünûn denen şeyi Leylâ bilseydi

Yalnızlık çölünde kimler ağlardı

Rüzgârdan buluttan sorulan haber

Belki ebediyyen cevapsız kalır

Şehirde kimsesiz gezen derbeder

Sahra müjdesini nereden alır

Hangi kentte mümkün canânla halvet

Hangi dağ başında bir saray vardır

Divâne gönlüme her diyar gurbet

Âşık için cihân külbe-i yardır

Kıssalar hissesiz bense yorgunum

Yağmurlarla yoldaş olamadım hiç

Masallar kimsesiz bense yorgunum

Hümâ ile ankâ bulamadım hiç

Zafer kazanılmaz mağlûp olunmaz

Bu kavganın sükûnu yok sulhu yok

O deryaya kolay kolay dalınmaz

Aşk bir âteş tufanıdır Nuh''u yok', 'Vuslat sıla kadar yakın olsaydı Ne söylerdi şiir neye yarardı Cünûn denen şeyi Leylâ bilseydi Yalnızlık çölünde kimler ağlardı Rüzgârdan bul...', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/diger-tufan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güz Neşideleri', 'guz-nesideleri-zemci-cetinkaya-7d2xj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir güz sabahı

Yağmurla

Zeburdan bir cümleyle

Terk etmek istemezdim mutantan kentinizi.

Ta öbür başından koşarak gelen

Bir adamın olmadığı...

/ Kelimelerim bir şey söylemedi

Ama ya gözlerim

Öbürleri gibi salladın başını sen de

Öbürleri gibi/

Ne hasret-i sıla ne firkat-i yâr

İşliyor başka bir yare derinden.

Yine de dağdan inmiştim

İyileştirmek gibi bir iddiam olmasa da 

Cüzzamlı valideleri.

Ne hummalılara ne kötürümlere müjdem oldu.

Yalnızca taşları meshettim

Okşanmamış başlar diyarında.

Tek akçem olmadı

Balık ağzından alınmış, 

Ağızlarından avladım oysa onları.

Ve olmadı evvel-i dünyadan kalma sırlarım

Yine de dağdan inmiştim.

Kuşlara bakmayı akletmediniz

Neden kimse memnun değil yerinden

Bir mersiye gibi kaldım

Mutarraf dudaklarda

Ceviz yapraklarındaki karıncalaradır

Hüznüm ve muğberliğim.

Hem tül hem güneş gözlüğü aldım

Bulutlu havalar için

Yürüdüğümü gören olmadı sokaklarda.

Haksızlık etmesin boş yere Mecnun

Leyla uzak değil çöl kederinden.

Bütün kuyular serbesttir 

Sürüsüz çobanlara

Başka bir himmet beklemesin, 

Kayaları tepeye yorulmadan çıkarmak gibi

Yorumsuz rüyalar görmek gibi, 

Harman için toprak ve rüzgar gibi.

Derûn-ı gazelde hafiyim ey yar

Oku ki bûs edeyim leblerinden.', 'Bir güz sabahı Yağmurla Zeburdan bir cümleyle Terk etmek istemezdim mutantan kentinizi. Ta öbür başından koşarak gelen Bir adamın olmadığı.....', ARRAY['Türk Edebiyatı','Şiir','Zemçi Çetinkaya']::text[], 8.5, '{"poet":"Zemçi Çetinkaya","poet_slug":"zemci-cetinkaya","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/guz-nesideleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüzün,', 'yuzun-goksen-aydemir-5ooeh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Dün gece resmine baktım, 

Yüzünü yüzüme yaklaştırdım

Eskisi gibi bakmıyor, umut vermiyordun.

Biz niye böyle olduk.

Dedim

yoksa sahte yüzlermiydik

ZAMANIN SONSUZLUĞUNDA İLERLEYEN

çok şeymi istedik, 

birbirimizin, imkansızı olduğumuzu bile bile', 'Dün gece resmine baktım,  Yüzünü yüzüme yaklaştırdım Eskisi gibi bakmıyor, umut vermiyordun. Biz niye böyle olduk. Dedim yoksa sahte yüzlerm...', ARRAY['Türk Edebiyatı','Şiir','Gökşen Aydemir']::text[], 8.5, '{"poet":"Gökşen Aydemir","poet_slug":"goksen-aydemir","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yuzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamam', 'anlatamam-daisy-daisy-5qq6f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anlatamam sana

seni nasıl duyduğumu

bir ruhun

iki bedende durduğunu

nasıl benzer ve farklıydık

aynı canda can bulup

senden fazla sen oldum

asla vazgeçemedim

ben seninle ben oldum', 'anlatamam sana seni nasıl duyduğumu bir ruhun iki bedende durduğunu nasıl benzer ve farklıydık aynı canda can bulup senden fazla sen oldum a...', ARRAY['Türk Edebiyatı','Şiir','Daisy Daisy']::text[], 8.5, '{"poet":"Daisy Daisy","poet_slug":"daisy-daisy","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/anlatamam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yolculuk', 'yolculuk-alp-aker-8yez4', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gideceğim bu diyardan, 

Sessiz ve tek başına.

Bir yaprağın ağaçtan eksilmesi gibi

Kimse bilmeyecek

Soran olmayacak “nereye? ”

Hatıram da solacak zamanla, 

Bu dünyadan hiç geçip gitmedi olacak', 'Gideceğim bu diyardan,  Sessiz ve tek başına. Bir yaprağın ağaçtan eksilmesi gibi Kimse bilmeyecek Soran olmayacak “nereye? ” Hatıram da sol...', ARRAY['Türk Edebiyatı','Şiir','Alp Aker']::text[], 8.5, '{"poet":"Alp Aker","poet_slug":"alp-aker","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yolculuk-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat', 'saat-alp-aker-95e7r', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boşlukta sallanan sarkaç

Ve yokluğa ilerleyen saat

Çözülen gecedir

Merdivenlerde bir ses 

Tik tak…

Bir pençe, kapının ardında

Kapı kapalı, üstünde bir kilit 

Pençe kalınlığında.

Zamansızlıklardan bir ses

Söz olma yolunda, 

Merdivenlerden çıkmakta

Ağır aksak.

Asırlardır  arıyorum

Karanlıktan başka 

Bir şey vardır umarak

Yüzümü dönüyorum

Işık ha parladı ha parlayacak

Pençe hala kapının ardında.', 'Boşlukta sallanan sarkaç Ve yokluğa ilerleyen saat Çözülen gecedir Merdivenlerde bir ses  Tik tak… Bir pençe, kapının ardında Kapı kapalı, ü...', ARRAY['Türk Edebiyatı','Şiir','Alp Aker']::text[], 8.5, '{"poet":"Alp Aker","poet_slug":"alp-aker","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/saat-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her İnsan Kendi Yalnızlığını Yazar', 'her-i-nsan-kendi-yalnizligini-yazar-bulent-ozcan-4ucg4', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her insan kendi yalnızlığını yazar

Her insan kendi yalnızlığını oynar

Her insan bir yalnızlıktır

Her insan kendini yaşar...

9 Temmuz 1992, Gaziantep', 'Her insan kendi yalnızlığını yazar Her insan kendi yalnızlığını oynar Her insan bir yalnızlıktır Her insan kendini yaşar... 9 Temmuz 1992, G...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/her-insan-kendi-yalnizligini-yazar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayal', 'hayal-ayhan-comert-ukc9j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sıcacık hayallerle örtündü akşam

ve özendirdi martıya, ah bir uçsam...

Çiçek dolu vadilere konup, uzansam

ucundan biraz güzelliği koklasam

Serin cıvıltılarla uyandı sabah

kokladığım tazelikten ayrılmasam

Daha sakin daha mutlu daha ferah

olurdum sanki, bu hayalde kalsam..', 'Sıcacık hayallerle örtündü akşam ve özendirdi martıya, ah bir uçsam... Çiçek dolu vadilere konup, uzansam ucundan biraz güzelliği koklasam S...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Cömert']::text[], 8.5, '{"poet":"Ayhan Cömert","poet_slug":"ayhan-comert","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/hayal-15-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çünkü Ben...', 'cunku-ben-i-sa-seker-fok2q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Güzel giyiniyorum, 

Güzel olmasam da.

Gülümsemeye çalışıyorum, 

Yüz kaslarım alıkoysa da.

Elbise olmaktan korkuyorum

İnsan olmayan içinde.

Göründüğüm gibi olmaya çalışıyorum, 

Olduğum gibi görünemesem de.

Çünkü ben Mevlana''yı seviyorum.

Çünkü ben...

Çünkü ben susmayı tercih ediyorum.

Çünkü ben gözlerime güveniyorum.', 'Güzel giyiniyorum,  Güzel olmasam da. Gülümsemeye çalışıyorum,  Yüz kaslarım alıkoysa da. Elbise olmaktan korkuyorum İnsan olmayan içinde. G...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cunku-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Avuç', 'avuc-mahmut-capar-3p35o', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Duman bastım gözlerime

Her sigara yakışımda

Ve de

Yürek yangınlarımda.

Sevda çektim içime

Fitil fitil

Ve yemin ettim dünyaya

Bir yağmur damlası olarak

Avuçlarına

Dolmaya...', 'Duman bastım gözlerime Her sigara yakışımda Ve de Yürek yangınlarımda. Sevda çektim içime Fitil fitil Ve yemin ettim dünyaya Bir yağmur daml...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/avuc-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-mehmet-vefik-yazicioglu-tx6zw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yine sensiz bu akşam

Gitmiyor şu bulutlar

Başımda dönüp duran

Felaket tellalları

Nerden çıktınız yine

Haber bile vermeden

Olmadı hiç bir zaman

Sensizlik hiç olmadı', 'Yine sensiz bu akşam Gitmiyor şu bulutlar Başımda dönüp duran Felaket tellalları Nerden çıktınız yine Haber bile vermeden Olmadı hiç bir zam...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Vefik Yazıcıoğlu']::text[], 8.5, '{"poet":"Mehmet Vefik Yazıcıoğlu","poet_slug":"mehmet-vefik-yazicioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sensiz-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-mahmut-capar-taq8r', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Boş gözlerle bakıyorum dünyaya

Yine içlendim

unutmak istiyorum herşeyi

Ve seni

Olmuyor! 

Onca şeye ragmen

Olmuyor işte.

Aşk bu olsa gerek

Ylnızlık

Bu olsa gerek

Kahvem yine acı kokuyor

Düşlerim siyah

Elerinde yok artık

Bu çamurdan ''beni'' çıkaracak

Yok artık anlamı yaşamanın

Bacaklarım uyuşmaya başladı bile

Üşüyorum

Vakit geldi gibi

Ecel trenine binmek

Hasret trenne binmekten daha kolay

Sen yine anlamasanda

Seni yeniden

Yine de

Seviyorum', 'Boş gözlerle bakıyorum dünyaya Yine içlendim unutmak istiyorum herşeyi Ve seni Olmuyor!  Onca şeye ragmen Olmuyor işte. Aşk bu olsa gerek Yl...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/seviyorum-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Gül Ya Papatya', 'ya-gul-ya-papatya-mahmut-capar-bjoy3', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Muson yagmurları yagıyor

Ya güz gülü ek ya papatya

Ya da bahçeden çık git.

İkisinide ektirmezler adama

Birini eksen digeri solacak

Hay akıllım! 

Bigün daha bekleseydin ya

Şmdi b... çıkarsın işin içinden

Bu kafayla sen 

Daha çook yazarsın

Titreye titreye

Dken diken

Boş boş', 'Muson yagmurları yagıyor Ya güz gülü ek ya papatya Ya da bahçeden çık git. İkisinide ektirmezler adama Birini eksen digeri solacak Hay akıll...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/ya-gul-ya-papatya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dîvân-ı İlâhîyât 165', 'd-v-n-i-i-l-h-y-t-165-aziz-mahmud-hudayi-lla57', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tînet-i Âdemde konmasa eğer sevdâ-yı aşk

 Cenneti bir dâneye satmazdı ol dânâ-yı aşk

 Kenz-i mahfîden zuhûra geldi eşyâ lâ-cerem

 Bâd-ı hubbiyle temevvüc etdi çün deryâ-yı aşk

 Tâlib-i dîdâr olup ayılmaya tâ haşredek

 Kim ki nûş ede ezel bezminde ger sahbâ-yı aşk

 Aşk ü müşg olmaz nihân ânı bilir halk-ı cihân

 Âşık-ı bî-çâreye mümkün müdür ihfâ-yı aşk

 Bülbülün hâlin bilenler gûş ederler nâlesin

 Bir gül-i bî-hâr içündür bunca hûy u hây-ı aşk

 Aşk-ı Şîrîn oldu feryâdına Ferhâd''ın sebep

 Ey nice dânâyı Mecnûn eyledi Leylâ-yı aşk

 Ey Hüdâyî hâlet-i aşkı ne bilsin her meges

 Kulle-i Kâf-ı hakîkat mürgüdür ankâ-yı aşk', 'Tînet-i Âdemde konmasa eğer sevdâ-yı aşk  Cenneti bir dâneye satmazdı ol dânâ-yı aşk  Kenz-i mahfîden zuhûra geldi eşyâ lâ-cerem  Bâd-ı hubb...', ARRAY['Türk Edebiyatı','Şiir','Aziz Mahmud Hüdayi']::text[], 8.5, '{"poet":"Aziz Mahmud Hüdayi","poet_slug":"aziz-mahmud-hudayi","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/divan-i-ilahiyat-165-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dîvân-ı İlâhîyât 72', 'd-v-n-i-i-l-h-y-t-72-aziz-mahmud-hudayi-ist9z', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşka düşürdün kendüzün

N''eyleyeyin gönül seni 

Bir oldu gecen gündüzün

Âh n''ideyin gönül seni

 Düşeli aşkına yârin

 Yerde gökte yok karârın

 Gitti elden ihtiyârın

 N''eyleyelin gönül seni

 Hakk ile her kim bileşdi

 Vâdî-i hayrete düşdü

 Aşk deryâsı başdan aşdı

 Âh n''ideyin gönül seni

 Âşık olaldan dîdâra

 Derd ile kaldın âvâre

 Döymez oldun intizâre

 N''eyleyeyin gönül seni

 Aşk ile hoş oldu başın

 Ma''şûk ile doldu işin

 Kalmadı gayrı teşvîşin

 Âh n''ideyin gönül seni

 Her gün Hakk''tan ihsân ola

 Her müşkil iş âsân ola

 Her derdine dermân ola

 N''eyleyeyin gönül seni

 Ma''şûktan ericek kemend

 Uşşâkı eyler kayd ü bend

 N''itsin Hüdâyî derd-mend

 Âh n''ideyin gönül seni', 'Aşka düşürdün kendüzün N''eyleyeyin gönül seni  Bir oldu gecen gündüzün Âh n''ideyin gönül seni  Düşeli aşkına yârin  Yerde gökte yok karârın ...', ARRAY['Türk Edebiyatı','Şiir','Aziz Mahmud Hüdayi']::text[], 8.5, '{"poet":"Aziz Mahmud Hüdayi","poet_slug":"aziz-mahmud-hudayi","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/divan-i-ilahiyat-72-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Vakti', 'gitme-vakti-sair-kebeli-37-uxs97', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir koca kadının torununu sevmesi gibi

Yalnızlık oyununa kaptırmış gibi yürüyorum

Aklımın bile alamadığı yerlerdeyim

Kabusumun umutsuzluğumun, yaşamımın en son yerlerinde

Anasının kucağındaki bir melek gibi

Yalnızılğın oyununu oynuyor çocuklar

Belki de umutsuzluk oyunudur bu

Nerden bilinir ki yaşamın bu olduğunu

Nereden tahmin edilir ki hayat

İnsanların hep yalnız kalacağı yaşam boyunca

Ne demişler '' İnsan yalnız doğar

                                  yalnız yaşar

                                  yalnız ölür....

İşte hayatı ve yaşamı anlatan kelimeler

Öbürleri gibi oldum bende dünyada yalancı

Lale bahçesinin içinde bir hayal yılanı bir sürüngen

Ümitsizlik dünyasında ise bir bekçi

Madem böyleyim hayatta dostum

                O zaman gitme vakti...', 'Bir koca kadının torununu sevmesi gibi Yalnızlık oyununa kaptırmış gibi yürüyorum Aklımın bile alamadığı yerlerdeyim Kabusumun umutsuzluğumu...', ARRAY['Türk Edebiyatı','Şiir','Şair Kebeli_37']::text[], 8.5, '{"poet":"Şair Kebeli_37","poet_slug":"sair-kebeli-37","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gitme-vakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'An Mıdır Anlar Mı Yaşam', 'an-midir-anlar-mi-yasam-mine-bahceci-k6igx', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yelesinde düş yıkımları asılı

	bendini yıkan kısrak

Son dönüşte solluyor şansı

İçerek karanlığı

		yaşam aynasından.

Ayak izlerince çıplak

	sızlıyor meydan

Anılar çölünde ıslak

Çabuk sallıyor

	süpürgesini zaman...

II

Öfkesini zor tutuyor 

		akşamüstleri

Uykusu kaçmış kapılar aralık

Bekçi düdüğünde

		bir umut, sabah

Tabut ağırlığında arzular

Yaşından önce yaşlanıyor

	yürek

Sararmışı değil ilk düşen

Yorulmuşu oluyor tutunmaktan

An mıdır

Anlar mı yaşam? 

Bakmadan aza çoğa

Çabuk sallıyor

		süpürgesini zaman.', 'Yelesinde düş yıkımları asılı 	bendini yıkan kısrak Son dönüşte solluyor şansı İçerek karanlığı 		yaşam aynasından. Ayak izlerince çıplak 	s...', ARRAY['Türk Edebiyatı','Şiir','Mine Bahçeci']::text[], 8.5, '{"poet":"Mine Bahçeci","poet_slug":"mine-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/an-midir-anlar-mi-yasam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Otostopçu', 'otostopcu-mine-bahceci-1a70z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne zaman bir sevda aralasam

Cilalı tutukluğuma

Yangınıma yelini katar

Toz duman sonra

Giderek biçimlenir

Ayrılıklarda.

Yıkıntılarımdan ürker

Kanımca

Belki de

Acizdir kendini yaşamaya...

Yarım kalır sevinçlerin günlüğü

Makaslanmış öykünün rötuşlarında

Temize çekilmiş eskizlerde

Yalnızlığa küflenir

Çocukluk çığlıklarım.

Hep içimden okurum

Çok sesli şarkıları

Amatör ses yarışması başlar

Hüzünler kanalında

Kullanmadığım hıçkırıklar

Paket programlarda

Kırmızı ışıkta çatılmış

Kahkahalarım

Oysa bütün yanılgılarım

Otostopçu

Yeşil ışık yaktığım

Sinyalsiz kavşaklarda.', 'Ne zaman bir sevda aralasam Cilalı tutukluğuma Yangınıma yelini katar Toz duman sonra Giderek biçimlenir Ayrılıklarda. Yıkıntılarımdan ürker...', ARRAY['Türk Edebiyatı','Şiir','Mine Bahçeci']::text[], 8.5, '{"poet":"Mine Bahçeci","poet_slug":"mine-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/otostopcu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dizin/e Düşen', 'dizin-e-dusen-mine-bahceci-fisss', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sesin mi

           gizler giyinmiş şarkı

Söyleme! 

           gömlek değiştirir gönlüm

                      yanarım içime sönebilmez/im! ..

Gözlerin mi

           ışığında bademlerin çiçeklendiği öykü

Bakma! 

           çeker kuytusuna burgacı

                      batarım yüreğine yüzebilmez/im! ..

Aşk mı

           dizin/e düşen

Korkma! 

           tutuşarak akıyor içimin ırmağı

                      kapıldım seline tutabilmez/im! ..

Bir yanımız acılar öreni

Öteki, sabaha süzülen seher

Sıkıysa kessin ömrümüzden

             okşamaları berber! ..', 'Sesin mi            gizler giyinmiş şarkı Söyleme!             gömlek değiştirir gönlüm                       yanarım içime sönebilmez/im! ....', ARRAY['Türk Edebiyatı','Şiir','Mine Bahçeci']::text[], 8.5, '{"poet":"Mine Bahçeci","poet_slug":"mine-bahceci","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dizin-e-dusen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağıt', 'agit-ugur-uludag-11oq5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bir küstüm her şeye

ki

artık ne denizleri paklar beni

ne masmavi gökleri memleketimin

yanaktaki yaşa endeksli

uzak bir yalnızlık düşündeyim

çekip gitmek var

alıp elime elini

yitip gitmek var

varsın olmasın yüreğimi titreten şarkılar

varsın olmasın yitirilmiş dakikalar sokaklarda

buğulanan göz benimdir

unuttuğum dostlar benim

artık çok iyi biliyorum

anlıyorsun yaş kemale erince

bir kez gittin mi

hep yolcusun gayrı

dokuz sekizlik majör notalar düşlerim sonra

gözlerim, melekler şehri ufuklarında

seni ağlarım usulca

sana ağlarım

ne melekler görür beni

ne şehri

beni sensiz yapan

zaaflarımın bedeli

bir bilsen her dakka seni öptüğümü

ucuca eklenen cigaralarda

bir bilsen

bakırköy sokaklarını düşlerim sonra

dudaklarım kasılır

erkekliğe toz kondurtmaya kondurtmaya

ıslanır

yanaklarım

kalp sana

el klavyeye vurgun

bilmem ki bu hep böyle gider mi

“şu kahpe dünya seni bana düşman eder mi”

bir kez olsun diye yalvarırım allaha

bir kez olsun kaybetmesem

hep bunu düşlerim mesela

mesela

hep seninle

hep daha güzel

hep aynı güneşe

hep beraber uyandığımız

sabahları

dostlarla

hep beraber coştuğumuz

karanlıktan hep beraber korktuğumuz

yarınları

bir gün olur mu diye düşlerim

ama bilirim olmaz

o bizi düşünmez

olsun

nasılsa

“su akar yatağını bulur”

valla 

öyle bir küstüm ki

ölüm bile döndürmez beni

otuz yaşında bir delikanlıyı durup dururken ağlatan bu hayat

artık paklamaz beni

otuz yaşında bir delikanlıyı yalnız bırakan bu hayat

artık aklamaz beni

otuz yaşında bir delikanlıyı çocuktan, sanattan, aşktan nefret ettiren bu hayat

artık saklamaz beni

otuz yaşında bir delikanlıyı kendinden bıktıran bu hayat

artık beklemez beni

otuz yaşında bir delikanlıyı pes ettiren bu hayat

artık zaten bi daha

yoklamaz beni

iş bu yüzden

yani sırf bu yüzden

hoşçakal kontes

gidiyorum

nereye mi? 

bilmiyorum...', 'bir küstüm her şeye ki artık ne denizleri paklar beni ne masmavi gökleri memleketimin yanaktaki yaşa endeksli uzak bir yalnızlık düşündeyim ...', ARRAY['Türk Edebiyatı','Şiir','Uğur Uludağ']::text[], 8.5, '{"poet":"Uğur Uludağ","poet_slug":"ugur-uludag","theme":"Türk Şiiri","is_hero":false,"total_lines":76,"source_url":"https://www.antoloji.com/agit-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ankara', 'ankara-ugur-uludag-i7qw3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dumanlı bir tepeden geliyor sesin

bir derviş gibi

sanki bir tuzak

sanki dudağın gibi

ankaranın sokakları başlattı tüm puştluğu

köşedeki dönerci bile hatırlar

herşeyi

hani baban öldüğü gün

sen, ben, o ağladığımızı

zaman yalanı açığa çıkarıyor

ve tarih denen dede

pişmanlık koyuyor adını

sevdanın

her şeyden vazgeçiyor

delikanlı dediğin

bir lanet

hep bir gölge gibi

üstünde

ankaranın

keşke gitmeseydim bulvara

keşke aynı ıhlamura uzanmasaydı elimiz

boşuna akmasaydı kanımız

keşke çakmaklarımı kaybetme adetim

olmasa da ateş istemese

keşke sigarayı zamanında bıraksaydım

keşke bir lanet gibi

çökmeseydi ankarama bulutlar

keşke sen yağmurdan korkmasan

keşke koltuğuma sığınmasan

keşke seni öpmeseydim

yağmura güvenip

keşke sana tip tip

bakan pasajdaki çocuğu

dövmeseydim

keşke okulu zamanında bitirip

kalmasaydım gözlerinin ikmaline

keşke senle hiç sevişmesem

sevişme nedir bilmesem

keşke her sabah sana

ölmeseydim

işte o zaman

ankara başka olurdu

sen başka ben başka

dünya başka olurdu

dedim ya

dumanlı bir tepeden geliyor sesin

dedim ya

eceline susuyor usum

ankara sokakları başlattı tüm puştluğu

mini eteğini mi çıkarmalı aklımdan

beraber ilk esrar içişimizi mi

silmeli dizeden

ankara sokakları

hayatımın

en kara sokakları', 'dumanlı bir tepeden geliyor sesin bir derviş gibi sanki bir tuzak sanki dudağın gibi ankaranın sokakları başlattı tüm puştluğu köşedeki döne...', ARRAY['Türk Edebiyatı','Şiir','Uğur Uludağ']::text[], 8.5, '{"poet":"Uğur Uludağ","poet_slug":"ugur-uludag","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/ankara-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üçüncü Türden Yakın İlişkiler Adlı Oyunun Final Şiiri', 'ucuncu-turden-yakin-i-liskiler-adli-oyunun-final-siiri-ugur-uludag-7deih', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nereye gidersen git

Arkandan gelecek bu gemi

Ne başkasına inanır

Kızgın gönül

Ne kibire kapılır

Yüreğim

Sen yalana esirsin bilirim

Sen yalana aşık

İki uzaylıya sattın beni

Yazık sana

Çok yazık

Ama

Nereye gidersen git

Arkandan gelecek bu gemi

Ellerini özleyeceğim en çok

Beni hem seven

Daha çok döven

Hem uğruna ölünen

Ellerini

Sen yalana esirsin bilirim

Sen dolana aşık

İki uzaylıya sattın beni

Yazık sana

Çok yazık

Git tabi

Ama yine de

Sen nereye gidersen

Arkandan gelecek bu deli', 'Nereye gidersen git Arkandan gelecek bu gemi Ne başkasına inanır Kızgın gönül Ne kibire kapılır Yüreğim Sen yalana esirsin bilirim Sen yalan...', ARRAY['Türk Edebiyatı','Şiir','Uğur Uludağ']::text[], 8.5, '{"poet":"Uğur Uludağ","poet_slug":"ugur-uludag","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/ucuncu-turden-yakin-iliskiler-adli-oyunun-final-siiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökhan, Koray, ben', 'gokhan-koray-ben-ugur-uludag-nfyx2', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '“biz üç kişiydik”

gökhan, koray bir de ben

james dean gibi ölebilen tek kişi, gökhan

bruce willis – ahmet kaya kırması, koray

bar köşelerinin suskun çocuğu, ben

biz

biz- bakırköy’ün kalbi

“munzurdan bir kuş indi”

ne yakışırdı ağzına

korkak bakışları

kör olurdu sahnede

bir bakış baktı mı

çığlıklar kopardı ovada

neyi unutulabilir ki

unutulsun kalp atışı

“kerhaneden kovulan tek kul olasın

benden başkasını seversen eğer”

değiştirdiğin şarkılar mıydı

yanlış yazılan

yoksa başka bir dilek miydi

tanrı tarafından

yanlış anlaşılan

ya ben

zavallı ben

ne dostunu

ne düşmanını bilen

yanılgı dert oldu

çekiyorum

dostum yok

ölüyorum

biliyorum

her şeyimi verirdim

tekrar birlikte olmak için

neyim varsa

herşeyimi...', '“biz üç kişiydik” gökhan, koray bir de ben james dean gibi ölebilen tek kişi, gökhan bruce willis – ahmet kaya kırması, koray bar köşelerini...', ARRAY['Türk Edebiyatı','Şiir','Uğur Uludağ']::text[], 8.5, '{"poet":"Uğur Uludağ","poet_slug":"ugur-uludag","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/gokhan-koray-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şerefin Var', 'serefin-var-kerim-atlihan-9jbc7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sence herşey para ise 

   Al senin şerefin var.

   Paranla pis denize, 

   dal senin şerefin var.

dostluklar yiterken, 

İnsanlık biterken, 

baykuşlar öterken, 

Gül senin şerefin var.

Aklında hep para pul, 

ezilirken onca kul, 

ney, zurna davul

Çal senin şerefin var

Kerim sorar ne dersin, 

Yaşadığın gibi gidersin, 

Allah belanı versin, 

öl senin şerefin var,', 'sence herşey para ise     Al senin şerefin var.    Paranla pis denize,     dal senin şerefin var. dostluklar yiterken,  İnsanlık biterken,  ...', ARRAY['Türk Edebiyatı','Şiir','Kerim Atlıhan']::text[], 8.5, '{"poet":"Kerim Atlıhan","poet_slug":"kerim-atlihan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/serefin-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölene Bakın! ..', 'olene-bakin-bulent-ozcan-6uy8j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Koşar adım bir sevdaya

Gelene bakın! ..

Gülü sarıp da yaraya

Gülene bakın! ..

“Ölmem” diyordu, ölüm bu ya

Ölene bakın! ..

          1993, Gaziantep', 'Koşar adım bir sevdaya Gelene bakın! .. Gülü sarıp da yaraya Gülene bakın! .. “Ölmem” diyordu, ölüm bu ya Ölene bakın! ..           1993, Ga...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/olene-bakin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Haykırış', 'haykiris-suleyman-karakas-9et33', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şafak   sökmese  güneş  doğmasa

Otlar  yeşermese çiçekler  açmasa

Bulutlar  görünüp  şimşek  çakmasa

Yine   seni  seveceğim 

Sensiz  olan  yerde   yağmur yağmasa

Çağlayanlar  durulsa sular akmasa

Kuruyan   dudağın  beni   tatmasa

Yine   seni   seveceğim

Yudum,   yudum   aşkımızı tatsalar

Yıldız   deyip   gökyüzüne baksalar

Cennet   diye   cehenneme  atsalar 

Yine  seni   seveceğim 

Yeşiller   kuruyup  sararı verse de

Denizler  kuruyup çöle   dönse de 

Senin  aşkın  için zehir  deseler

Bu  aşkı yudum, yudum içeceğim', 'Şafak   sökmese  güneş  doğmasa Otlar  yeşermese çiçekler  açmasa Bulutlar  görünüp  şimşek  çakmasa Yine   seni  seveceğim  Sensiz  olan  y...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Karakaş']::text[], 8.5, '{"poet":"Süleyman Karakaş","poet_slug":"suleyman-karakas","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/haykiris-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Göçmen Kuş', 'gocmen-kus-adil-han-talat-xtah1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ben bir göçmen kuş değilim ki; 

Kış geldiği zaman, 

Uçarak kollarından, 

Baharı başka kollarda arayayım...

Aksine ben toprak gibi, 

Uyur gibi bir daha uyanmamacasına, 

Ve saklıyarak içimde cenneti, 

Sabırlı bir kibirle beklerim; 

Toprağa bir dokunuşu ile 

Baharı getiren yağmur gibi, 

Senin de bir öpücüğünle bitirmeni hasreti.

Çünkü benim için bahar, 

Ancak senin kollarındadır...', 'Ben bir göçmen kuş değilim ki;  Kış geldiği zaman,  Uçarak kollarından,  Baharı başka kollarda arayayım... Aksine ben toprak gibi,  Uyur gib...', ARRAY['Türk Edebiyatı','Şiir','Adil Han Talat']::text[], 8.5, '{"poet":"Adil Han Talat","poet_slug":"adil-han-talat","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gocmen-kus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Matematik', 'matematik-sair-arachnite-n7epr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Matematik farklı diğer bilimlerden

Etkilenmez fikirlerden insanlardan ölümlerden

Anlamayan için bilinçsizce çalınan bir gürültü

Anlayana dinlemeye doyulmayan bi semfonidir

Asla bıkamazsın dinlemekten.

Toplamak bölmek çarpmak hayatın birer önemli kesidi

Çıkarmak ise bunlara olumsuz ölüm seli

Hepsi birbirine baglı ve saygılı

Tıpkı ölüm ve hayat gibi', 'Matematik farklı diğer bilimlerden Etkilenmez fikirlerden insanlardan ölümlerden Anlamayan için bilinçsizce çalınan bir gürültü Anlayana din...', ARRAY['Türk Edebiyatı','Şiir','Şair Arachnite']::text[], 8.5, '{"poet":"Şair Arachnite","poet_slug":"sair-arachnite","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/matematik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sesimi Duyan Güller', 'sesimi-duyan-guller-i-brahim-i-smailoglu-pxxij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sesimi duyan güller, 

açar yaprak, eder secde, 

secde eder hakka güller, 

yâre kavuşsun diye bana dua eyler.', 'sesimi duyan güller,  açar yaprak, eder secde,  secde eder hakka güller,  yâre kavuşsun diye bana dua eyler....', ARRAY['Türk Edebiyatı','Şiir','İbrahim İsmailoğlu']::text[], 8.5, '{"poet":"İbrahim İsmailoğlu","poet_slug":"i-brahim-i-smailoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sesimi-duyan-guller-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
