INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm', 'olum-aysun-elagoz-78v1d', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ölüm korkusu sarıyor bazen bedenimi, 

Ve hatalarım geliyor aklıma bir bir...

Belki yaşayamadığım duygulara üzülüyorum, 

Ya da yaşadıklarımdan utanıyorum....

Düşündükçe toprak kokusu doluyor genzime, 

Yağmuru doya doya içmiş toparağın çiğ kokusu...

Belki toprağın soğukluğunu düşünmek beni titreten, 

Ya da yok olup gitmek düşüncesi beni bitiren......

Sonra çılgınca koşmak geçiyor içimden çılgınca, 

Önde ben peşimde ölüm..Koşmak sonsuza...', 'Ölüm korkusu sarıyor bazen bedenimi,  Ve hatalarım geliyor aklıma bir bir... Belki yaşayamadığım duygulara üzülüyorum,  Ya da yaşadıklarımda...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/olum-31-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılığın Eşiğinde', 'ayriligin-esiginde-aysun-elagoz-40nvg', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gözlerini öyle dikme gözlerime, 

Ellerinle sıkı sıkı tutma ellerimi, 

Ne olur güzel sözler fısıldama kulaklarıma, 

Böyle ayrılığın eşiğindeyken, 

Sevdiğini söyleme bana.....

Ayrılmak 

Ölüm gibi zaten....

Deli gönül

Al diyor, 

Sev diyor, 

Git bu diyarlardan diyor.....

Gönül işte, 

Deli işte, 

Ne dediğini bilmiyor işte....', 'Gözlerini öyle dikme gözlerime,  Ellerinle sıkı sıkı tutma ellerimi,  Ne olur güzel sözler fısıldama kulaklarıma,  Böyle ayrılığın eşiğindey...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ayriligin-esiginde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bozkurt Duası', 'bozkurt-duasi-hanifi-celebioglu-ud35s', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Düşümde gördüm yine dün gece, 

Bir bozkurt uluyordu, sessizce, 

Neden bu mahsunluk diye sordum, 

Haykırdı, paramparça olmuş ordum.

Göster dedim, bana bir çıkış yolu, 

Feda olsun budun’a bu Türk oğlu, 

Baktı bana çakmak gözlerle, 

Çevirdi yönünü yine göklere.

Belliki yakarıyordu Tanrı’ya, 

Sanki, şunu diyordu Ulu’ya, 

Ya bay kıl bu asil ırkı, 

Hükmetsin bütün acuna, 

Ya yeryüzünden sil gayrı.

Gök Tanrı, ulu Tanrı, Tek Tanrı, 

Soysuz emrine koma, ordun soyluları, 

Ya kaan olsun cihana Börteçine, 

Ya övdürme bir daha son elçine.

Bölük, pörçük olmuş Türk yurtları, 

Kan kusuyor yiğit Bozkurtları, 

Nerede Turan, nerede anayurtları, 

Ya ordun kıl, şahlandır bu milleti, 

Ya kutlu kitaptan çıkar bu milleti.

Sonra Bozkurt, söktü yüreğini, verdi bana, 

Yüreğime od düştü, yaktı, sevda oldu bana, 

Ben bozkurt, bozkurt ben, bir uluduk Tanrı’ya, 

Yakardık tek sesle, yüceler yücesi Ulu’ya, 

‘Ya kırk çeriden biriyim, bir Kür’şad yolla bana, 

Ya Kür’şad benim, kırk çeri yolla bana’

Gök Tanrı, Ulu Tanrı, Tek tanrı, 

Yakartma bu kullarını gayrı, 

Ya bay kıl bu asil ırkı, 

Boynu bükük koma artık, 

Ya yeryüzünden sil gayrı.', 'Düşümde gördüm yine dün gece,  Bir bozkurt uluyordu, sessizce,  Neden bu mahsunluk diye sordum,  Haykırdı, paramparça olmuş ordum. Göster de...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Çelebioğlu']::text[], 8.5, '{"poet":"Hanifi Çelebioğlu","poet_slug":"hanifi-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/bozkurt-duasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Kür''Şad Gözlerim', 'bir-kur-sad-gozlerim-hanifi-celebioglu-nf4jp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Anlatamam derdimi bu anlamsız mısralarla, 

anlamak istiyorsan bak göz pınarlarıma, 

pınarlık bitti, sel oldu çağlıyor göz''lerim, 

hiç olmazsa, Çin''i basacak 

bir Kür''şad gözlerim.

Deli diyorlar bana el''ler, varsın desinler, 

İster maphus, ister şehit yada gazi desinler, 

Yeter ki ülkeme sömürge, 

Milletime köle demesinler, 

Neyin bedeli bu Tanrım, ödülü bu(mu)  sevdamın

Çilesi ağır biliyorum benim kutlu davamın

Ağır gelmesin hiç bir gardaşıma sözlerim, 

Yok kalmadı, bitti(mi)  soylu direnişçi yiğitlerim, 

Mustafa, Selçuk, Halil, 

dahası urganda solan çiçeklerim, 

velhasıl bütün bozkurtları, diriltecek 

bir Kür''şad gözlerim.

Ağrıma gidiyor Gardaş, neden bu muhatapsızlık, 

Ülkeyi sarmış, aymazlık, bağnazlık, hesapsızlık, 

Köle ettiler asil milleti, üç paralık soysuzlara, 

40 yiğitten biriyim, emre amade hazırım da

başımıza bir komutan, emir verecek, 

Bismillah deyip yıkacak bu köhne düzeni, 

bir Kür''şad gözlerim.

Soysuzlar, katiller, hırsızlar hep dışarda, 

üç yaşında kıza bile musallatlar, sokaklarda

Yeter artık, Malatyalı gardaşın çilegahı zindanı da, 

Dümdüz edecek, yıkacak

bir Kür''şad gözlerim.

Dedim ya anlatamıyorum derdimi, 

sığmıyor, yırtıyor ruhum şu aciz bedenimi, 

Soylu direnişlerin kızılca kıyameti kopsun, 

Mehmet''ler, hepsi, hepsi şehit olsun(da) , 

yaşasın milletim, hür olsun devletim, 

Asaletimi, hürriyetimi haykıracak, 

Bir Kür''şad gözlerim.', 'Anlatamam derdimi bu anlamsız mısralarla,  anlamak istiyorsan bak göz pınarlarıma,  pınarlık bitti, sel oldu çağlıyor göz''lerim,  hiç olmazs...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Çelebioğlu']::text[], 8.5, '{"poet":"Hanifi Çelebioğlu","poet_slug":"hanifi-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bir-kur-sad-gozlerim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Din Yobazına', 'din-yobazina-hanifi-celebioglu-xl13s', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bana iman’sız, ırkçı diyen ey dönme, 

Bir bak hele mazi’ye, biraz dön de, 

Siz oynaşırken, istismar ettiğiniz din’le, 

Neden, niçin, düşün hele, imanımızın bedeli, 

Yediğimiz kurşunlar hala bedenimizde.

Neyin bedeliydi ödediğimiz, bilirmisin, imanımın, 

Gardaşlarım şehit oldu, uğruna dinim islamın, 

Sen sadece mezarda okurken ONU, 

Biz hatmettirdik bütün cihana ONU.

Anlatsam da, anlamazsın, ey ormanımın odunu.', 'Bana iman’sız, ırkçı diyen ey dönme,  Bir bak hele mazi’ye, biraz dön de,  Siz oynaşırken, istismar ettiğiniz din’le,  Neden, niçin, düşün h...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Çelebioğlu']::text[], 8.5, '{"poet":"Hanifi Çelebioğlu","poet_slug":"hanifi-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/din-yobazina-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Devşirmelere', 'devsirmelere-hanifi-celebioglu-gh295', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kimi şan ile taşır yediği kurşunu bacağında, 

Kimi Vatanı satar, soysuzların kucağında, 

Piyon, soysuz, dönme, şeref yoksulu, devşirme

Sen meşgul ol hele, piçlerini büyütmekle, 

Büyüt, öğret devşirmeliği, yolla ki üstüme, 

Kılıcım  paslanmasın kınında, öylece, 

Mohaç’ı unuttun, geldin de istiklal harbinde, 

Yollamadık mı, canını tamu’nun ta dibine.', 'Kimi şan ile taşır yediği kurşunu bacağında,  Kimi Vatanı satar, soysuzların kucağında,  Piyon, soysuz, dönme, şeref yoksulu, devşirme Sen m...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Çelebioğlu']::text[], 8.5, '{"poet":"Hanifi Çelebioğlu","poet_slug":"hanifi-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/devsirmelere-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben, Bayrağım, Turan', 'ben-bayragim-turan-hanifi-celebioglu-syhmw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben kim miyim, bakmayın ‘ben’ mağdur olduğuma, 

Uçmağ’a varan, Başbuğumuzun yoldaşlığında, 

Ülkücüyüm ben, Ülkü Ocağın ateşinde pişen, 

Bozkurt soyunda, ülkü yolunda, sayım milyonlarca.

Sığınağım, yurdum, umudu milletin, sancağım üç kutlu hilal

Boya cihanı kızıla, koy üstüne göklerden bir yıldız, bir de hilal, 

Gölgesinde dinlenirken atlarımız, ısınırız kızıllığında, 

Hilalinde iman sebil, gel, kaçma, sende, sende nasibini al.

Toy’lar kurarız orada, Bilge Liderin Yolbaş’lığında, 

Bugün Erciyes, yarın da Türkistan yaylalarında, 

Türkmen, Gagavuz, Azeri,  tüm boylar aynı çadırda, 

Kavuşuruz, avunduğumuzu sanma kutlu Anadolu’da.', 'Ben kim miyim, bakmayın ‘ben’ mağdur olduğuma,  Uçmağ’a varan, Başbuğumuzun yoldaşlığında,  Ülkücüyüm ben, Ülkü Ocağın ateşinde pişen,  Bozk...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Çelebioğlu']::text[], 8.5, '{"poet":"Hanifi Çelebioğlu","poet_slug":"hanifi-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ben-bayragim-turan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bayrağım', 'bayragim-hanifi-celebioglu-gdqjz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Niçin bakarsın öyle kederli, mahsun, 

Divanen yok, kalmadı benden başka, 

Sen ki şehidimin kanı, şerefisin vatanın, 

Seni bu hallere koyan şerefsizler utansın.

Şanınla, şerefinle dalgalanırken üç kıta’da, 

Asaletin, soyun söylenirdi herbir kıta’da, 

Sen mapus, ben mahsun bu kutlu yarım ada’da, 

Senden yüksekte bugün pekçok soysuz paçavra.

Fırtına, boran, kar, tipi, hepsi palavra, yalan, 

Bilirim beklersin küçük bir ruzgar, soylu olan, 

Yakarım, yanarım, olurum kutlu bir rüzgar sana, 

Dalgalanırsın yine nazlı nazlı, tüm alemin semalarında.

Türk’üm ben, Oğuz’dur soylu boyum, 

Tanrı dağı kadar mazi’dir benim kutlu soyum, 

Yarın geç olur, ayrılsın bedenimle boynum, 

Şafakla dalgalanmazsan tüm alemin semalarında.

Pek çok sevdalın vardı, seninle oldu hepsi yüce, 

Kimi şimdi uçmağ’da şerefle, kimi sefa aleminde cüce, 

Bir ben kaldım aşığın, bir sen mahsun, şu kutlu beldede, 

Beni garip, seni mahzun koyan şerefsizler utansın.

Beşbin Bozkurt fidan oldu uğruna, kara toprakta, 

Fidanlar boy verdi, ben oldum soylu meyvesi, 

Büyüdüm, vuruldum, serpildim al’ında beyazında, 

Yaktı, kavurdu içimi, ruhumu, renginin her zerresi.

Al, feda canım, boya beni de kan kızıl rengine, 

Yeterki, yeterki sen çık yükseklere, dengine, 

Haram olsun, anamın ak sütü, babamın asaleti, 

Dönersem sevdamdan, çıkarmazsam seni göklere.

Gazilik nişanı mermi dursada şerefle vucudumda, 

Dikmezsem seni arşı-aleme, dolsun başım da kurşunla, 

Haydi kalk, direk et, sarıl boynuma, yüksel ufuklara, 

Gülsün artık, gülmeyi unutan şu Bozkurt soylu bahtı kara.

Bozkurt’tu anam, doyamasam da içtim helal sütünden, 

Asildi atam, görmesem de geldim kutlu ağbudun’dan, 

Doyurdum ruhumu, kaynağı Kur’an, öğüdü Orhun’dan

Kalk artık, ısıt beni kızıllığında, göklerde dalgalan.', 'Niçin bakarsın öyle kederli, mahsun,  Divanen yok, kalmadı benden başka,  Sen ki şehidimin kanı, şerefisin vatanın,  Seni bu hallere koyan ş...', ARRAY['Türk Edebiyatı','Şiir','Hanifi Çelebioğlu']::text[], 8.5, '{"poet":"Hanifi Çelebioğlu","poet_slug":"hanifi-celebioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/bayragim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Aralık Gecesiydi', 'bir-aralik-gecesiydi-garip-fahri-dwjkf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir aralık gecesiydi

Saçların kadar karanlık

Lapa lapa yağan kara yazmıştım adını

Karlar eridi sen yoksun

Şimdi bekliyorum

Belki bir nisan günü

Bulutlara verdiğim umutlarım, 

Yağmur olur düşer saçlarına...', 'Bir aralık gecesiydi Saçların kadar karanlık Lapa lapa yağan kara yazmıştım adını Karlar eridi sen yoksun Şimdi bekliyorum Belki bir nisan g...', ARRAY['Türk Edebiyatı','Şiir','Garip Fahri']::text[], 8.5, '{"poet":"Garip Fahri","poet_slug":"garip-fahri","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bir-aralik-gecesiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Kömür Gözlerinde', 'senin-komur-gozlerinde-metehan-selcuk-8cowk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'senin kömür gözlerinde

 kararır  gider ömrüm

vebali sensin günahımın

 yalnız senin için dolaştım 

 tek tek meyhaneleri

sırf sende sarhoş oldum

yalnız seni anlattım martılara

her gemiye seni sordum

akan su değil zamandı 

ağlıyordun kuruyan nehirlerde, 

bir yaprağın sararan yalnızlığıydın.

şimdi,  dertliler denizinde

bir gurbet türküsü yüreğimde

''kara gözlüm sen bu elden gidersen'' 

yıldızlar göz kırpar kirpiklerden

oysa sen, 

zaman içinde akıp gittin 

bir daha dönmemek üzere

ne bir el ne de bir mendil bile sallamadan 

eşkıya oldun şimdi yüreğimde', 'senin kömür gözlerinde  kararır  gider ömrüm vebali sensin günahımın  yalnız senin için dolaştım   tek tek meyhaneleri sırf sende sarhoş old...', ARRAY['Türk Edebiyatı','Şiir','Metehan Selçuk']::text[], 8.5, '{"poet":"Metehan Selçuk","poet_slug":"metehan-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/senin-komur-gozlerinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiroşima', 'hirosima-umit-yasar-oguzcan-4926p', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Önce bir bulut yükseldi

Yerden göğe dogru

Ben gördüm

Akahito gördü

Yuhara gördü

Hisaki gördü

Yaşayanların hepsi gördüler

şimdi yaşayanlar diyorum

Oysa ben kaldım

Onlar öldüler

Pirinç tarlasında kadınlar öldü

Memede çocuklar öldü

Çiçekler öldü

Kuşlar öldü

Ve sevgilim sanuki öldü

Sanuki''yi seviyordum

Sanuki öldü

Sanuki öldü

Ateşten top kayboldu göklerde

Ardından

Bir çölün sessizliği çöktü şehre

Bulutlar gitti

Renkler gitti

Sesler gitti

Gülerkken ölmüştü babam

Anam Chiyo-No ağlıyordu

Ve kız kardeşim Shirara

Ah Shirara

O da saçlarını tararken öldü

Shirara, ah Shirara

Aynada unuttu gençliğini

Ve ben Yamamura

Bizim sokaktan bir ben sağ kaldım

Bizim sokağın ağaçları da öldü

Ve ben Yamamura

17 yıl geçti aradan

Hala yaşıyorum

Ağaçları, çiçekleri görmeden

Ben Yamamura

Kör ve sağır

Çoktan öldüm

Kimse farkında değil', 'Önce bir bulut yükseldi Yerden göğe dogru Ben gördüm Akahito gördü Yuhara gördü Hisaki gördü Yaşayanların hepsi gördüler şimdi yaşayanlar di...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/hirosima-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Yine Akşam Aldu', 'gun-yine-aksam-aldu-metehan-selcuk-rsbru', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün yine akşam oldu

Penceremden bakarken dışarıya

Ben güne hasret, 

Ben güne hasretken

Özgürlük yalçın dağlarda

Özgürlük yamaçlarda

Özgürlük gün batımında 

Süphan dağında, 

Dışarıda kuşlar öter

Dostlar sohbet eder, 

Bir kıvılcım içimi yakar 

Ben güne hasret

Ben hapis, dört duvar arasında 

Gün akşam olur

Benimde diyeceğim elbet olur 

Güneşle ayın seviştiği gecede

Yansın varsın için 

Seni anlayanda  bulunur

Hayallerin konuştuğu gecede

Yıldızlar göz kırpar 

Ben yalnız, hem de çok yalnız 

Düşüncelerimle dövüşürken 

Ah bir gülebilseydim  doğan güne 

Ben güne hasret, 

Ben güne hasretken

Özgürlük yalçın dağlarda

Özgürlük yamaçlarda

Özgürlük gün batımında 

Süphan dağında

Beni dört duvar arasına sıkıştıran 

Beni hayata mahkum eden  yaşantı

Gün gelir sende kıskanır

Özgürlüğe kavuştuğum anı 

31.05.2001', 'Gün yine akşam oldu Penceremden bakarken dışarıya Ben güne hasret,  Ben güne hasretken Özgürlük yalçın dağlarda Özgürlük yamaçlarda Özgürlük...', ARRAY['Türk Edebiyatı','Şiir','Metehan Selçuk']::text[], 8.5, '{"poet":"Metehan Selçuk","poet_slug":"metehan-selcuk","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/gun-yine-aksam-aldu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynı Şey', 'ayni-sey-i-sa-seker-m7fzt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aynı anda bebekler doğuyor, 

Aynı anda ölenler oluyor.

Bir şey ya vardır ya da yoktur, 

İkisi de aynı anda olmuyor.

Aynı yerde hatalar yapılıyor, 

Aynı yerde doğrular bulunuyor.

İnsan her güzelden hoşlansa da

Bir kalpte iki aşk yer bulmuyor.

Aynı şeyi düşünüyorlar, 

Aynı şeyi hissediyorlar.

Her gün göz göze gelseler de

Aynı şeyi söyleyemiyorlar.', 'Aynı anda bebekler doğuyor,  Aynı anda ölenler oluyor. Bir şey ya vardır ya da yoktur,  İkisi de aynı anda olmuyor. Aynı yerde hatalar yapıl...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayni-sey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdadır', 'sevdadir-gulcihan-atalay-b4tow', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıkılır suskunluğun duvarları

Bir ses

Bir gülüş akar

Günışığı çehresinden; 

Sevdadır…

Gece

Yürek sıcağı

Titretir bedenimi.

Kavganın namlusu

Bebeğin uykusu

Gülün türküsü gibi

Büyür gelir gecelerden.

Alnında Altındağ sırtları

Peşinde Anadolu türküleri

Soluksuz geçer bütün caddelerden.

Dokunur parmak uçlarıyla yüreğime

Yüreğim lime lime.', 'Yıkılır suskunluğun duvarları Bir ses Bir gülüş akar Günışığı çehresinden;  Sevdadır… Gece Yürek sıcağı Titretir bedenimi. Kavganın namlusu ...', ARRAY['Türk Edebiyatı','Şiir','Gülcihan Atalay']::text[], 8.5, '{"poet":"Gülcihan Atalay","poet_slug":"gulcihan-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sevdadir-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vietnam''lı Bir Çocuk İçin Ağıt', 'vietnam-li-bir-cocuk-i-cin-agit-umit-yasar-oguzcan-ied22', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Babasını döve döve öldürmüşler

Küçümencik gözleirnin önünde

Anasının yarısını bir bomba alıp götürmüş

Kan ve et yığını öbür yarısı

Oturmuş ağlıyor Vietnamlı bir çocuk

Minik yumrukları sıkılmış kinle

Belli bir şeyler düşünüyor

Kederden harap olmuş bir beyinle

Aklı ermiyor olanlara Vietnamlı çocuğun

Bilmiyor yaşamak nedir, ölmek nedir

Çoktan unutmuş sevinmek, gülmek nedir

Savaşın ne olduğunu anlamıyor bir türlü

Sadece açlık şimdi anlayabildiği

Midesini ve beynini kemiren bir açlık

Anası yok ki ona sıcak yemekler pişirsin

Babası yok ki ona renkli giysiler getirsin

Savaşın bu kadar alçak ve insafsız olduğunu

Vietnamlı çocuk nereden bilsin

Burası onun kendi toprağı, kendi yurdu

Anası onu burada

Şimdi yerle bir olan evlerinde doğurdu

vietnamlı çocuk ninnilerle uyudu burada

Anasının pişirdiği ekmeklerle büyüdü

Tozlu sokaklarında koştu köyünün

Kendi gibi çekik gözlü arkadaşları vardı

Hepsi de savaşın varlığından habersiz

Bu ormanda oynarlardı

Kim derdi ki bir gün

Kara bir bulut çökecekti üzerlerine

Masallardaki umacı gelecekti köylerine

Vuracaklar, kıracaklar, yakacaklardı

Her yere ateş ve lüm saçacaklardı

Korkudan, yorgunluktan, işkenceden

Yüz olmaktan çıkacaktı Vietnamlıların yüzleri

Kim derdi ki bir gün

Hınçla sıkılmış birer yumruk gibi

Yuvalarından fırlayacaktı gözleri

Her şeyi gördü Vietnamlı çocuk her şeyi gördü

Ve tükürdü yüzlerine babsını dövenlerin

Döve döve öldürenlerin

Sonra kaçtı bu uzak ormana

Bu ormanda kuşlarla, hayvanlarla yan yana

Ot yedi, böcek yedi

Ve hep böyel cılız kaldı Vietnamlı çocuk

Büyümedi

Şimdi oturmuş bir tümseğin üstüne

Hatırlamaya çalışıyor olanları

Geçen o korkunç zamanları

Bir rüya gibi unuttuğu insanları

Ve o masallardaki umacılar 

Onu da bulurlar, öldürürler korkusuyla

Elinde bir taş var Vietnamlı çocuğun

Çekik gözlerinde yaş

Siz de ağlayın ey dünya çocukları

Vietnamlı çocuk ölüyor yavaş yavaş', 'Babasını döve döve öldürmüşler Küçümencik gözleirnin önünde Anasının yarısını bir bomba alıp götürmüş Kan ve et yığını öbür yarısı Oturmuş a...', ARRAY['Türk Edebiyatı','Şiir','Ümit Yaşar Oğuzcan']::text[], 8.5, '{"poet":"Ümit Yaşar Oğuzcan","poet_slug":"umit-yasar-oguzcan","theme":"Türk Şiiri","is_hero":false,"total_lines":55,"source_url":"https://www.antoloji.com/vietnam-li-bir-cocuk-icin-agit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evlilik', 'evlilik-i-sa-seker-w40xt', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Elinin hamuruyla desem, 

Hamur yoğurmayı bilmez.

Saçı uzun diye alay etsem, 

Bir tutam saçı var zaten.

Kahvaltı yapmayalı aylar oldu, 

Gömleğimin yakası kirle doldu.

Gündüzleri yorgun, geceleri uykulu, 

Yumurtamız sahanda, makarnamız soslu.

Ne yapalım ama zaman değişmiş, 

Bulaşıkları yıkamak bana düşmüş.

Ufaklığı emzirmek de zor bir iş, 

Allah''tan o iş de bize düşmemiş.

Aslına bakarsanız o iyi birisi: 

Çünkü o herşeyi paylaştığım kişi.

Bir şey var zamanın değiştiremediği: 

Evlilik aşkın ta kendisi.

Varsın olmasın gömleğimin ütüsü, 

Benimkisi nazlanmaktı altı üstü.

Razıyım yumurtaya ben her akşam üstü, 

Yeter ki eksilmesin dudağımdan öpücüğü.', 'Elinin hamuruyla desem,  Hamur yoğurmayı bilmez. Saçı uzun diye alay etsem,  Bir tutam saçı var zaten. Kahvaltı yapmayalı aylar oldu,  Gömle...', ARRAY['Türk Edebiyatı','Şiir','İsa Şeker']::text[], 8.5, '{"poet":"İsa Şeker","poet_slug":"i-sa-seker","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/evlilik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dolanış', 'dolanis-yunus-emre-np9qe', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu fena mülkünde ben nice nice hayran olam

Ye nice handan olam ye nice bir giryan olam

Geh feleklerden meleklerden dileklerden dileyem

Gah arş u şemste gerdun olam gerdan olam

Adımım attım yedi dört onsekizden ben öte

Dokuzu yolda kodum şah emrine ferman olam

Dost ferah kıldı terahtan ben teberra eyledim

Suret-i insan olam hem can olam hem kan olam

Gah bir müfti müderris geh mümeyyiz gah temiz

Gah bir müdbir-ü nakıs (naks)  ile noksan olam

Gah batn-ı hut içinde Yunus ile söyleşem

Geh çıkam arş üzere bir can olam Selman olam

Gah inem esfellere şeytan ile şerler düzem

Geh çıkam arş üzre vü seyran (olam)  cevlan olam

Gah işidirem işitmezem işümezem aceb

Nice bir nisyan olam hayvan olam insan olam

Gah ma''kuulat-ı mahsulat takrir-ü beyan

Gah maksurat olam geh sahib-i Keyvan olam

Nice bir surette insan ü sıfatta canver

Nice bir tilki olam ya kurt u ya arslan olam

Nice bir tecrid ü ferd ü mücerred münferid

Ye nice (cin)  nice ins ü nice bir şeytan olam

Nice bir aşk meydanında nefs atın seyittirem

Ye nice bir başımı tup eyleyip çevgan olam

Gah birlik içre birlik eyleyem ol bir ile

Geh dönem derya olam katre olam umman olam

Gah düzahta yanam Fir''avn ile Haman ile

Gah cennete varam gılman ile Rıdvan olam

Gah bir gaazi olam Efrenk ile cenk eyleyem

Geh dönem Efrenk olam nisyan ile isyan olam

Gah ola odlar yakam diler yıkam canlar yakam

Gah varam arşa çıkam geh şah u geh sultan olam

Nice bir dertler ile odlara yanam yakılam

Nice bir şakir olam zakir olam mihman olam

Gönlümün gencine renc irgörmeden bir yol bulam

Yahu deryaya girem bi reng ü  bi elvan olam

Ye nice bir ben diyem sensin diyem utanmadan

Ye nice deksiz olam dilsiz olam hayran olam

Nice bir balçıkt'' olan alçakta olam har olam

Gah varam gevher olam yakuut olam mercan olam

Ademilikten çıkam uçam melekler mülküne

Levn olam bi levn olam geh kevn olam bi kan olam

Gah zındandan çıkam azad olam abad olam

Geh yine der-ban olam mahbus olam zindan olam

Dar olam girdar olam Mansur olam ber-dar olam

Ten olam hem can olam hem in olam hem an olam

Yunus''a Taptuğ u Saltuğ u Barak''tandır nasib

Çün gönülden cuş kıldı ben nice pinhan olam

Yunus imdi bu sözüben aşıka di aşıka

Kim sana ben sıdk olam hem derd ü hem derman olam

Gah halis gah muhlis olam uş Furkaan ile 

Gah Rahman''ur-Rahim ya Hayy ü ya Mennan olam

Geh dönem bir şems olam zerremde yüzbin arş ola 

Geh yien tuğyn olam alemlere tufan olam

Evveli Hu ahırı Hu ya Hu illa Hu olam

Evvel ahır ol kala vu '' Men aleyha fan '' olam

                                     Yunus Emre', 'Bu fena mülkünde ben nice nice hayran olam Ye nice handan olam ye nice bir giryan olam Geh feleklerden meleklerden dileklerden dileyem Gah a...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/dolanis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Ateşi', 'ask-atesi-yunus-emre-169sn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Girdim aşkın denizine bahrılayın yüzer oldum

Geştediben denizleri Hızır''layın gezer oldum

Cemalini gördüm düşte çok aradım yazda kışta

Bulamadım dağda taşta denizleri süzer oldum

Sordum deniz malikine ırak değil salığına

Girdim gönül sınığına gönülleri düzer oldum

Viran gönlüm eyledim şar bunculayın şar nerde var

Haznesinden aldım gevher dükkan yüzün bozar oldum

Ben ol dükkan-dar kuluyum gevherler ile doluyum

Dost bağının bülbülüyüm budaktan gül üzer oldum 

Ol budakta biter iman iman bitse gider güman

Dün gün isim budur heman nefsime bir Tatar oldum 

Canım bu tene gireli nazarım yoktur altına

Düştüm ayaklar altına topraklayın tozar oldum

Tenim toprak tozar yolca nefsim iltir beni önce

Gördüm nefsin burcu yüce kazma aldım kazar oldum

Kaza kaza indim yere gördüm nefsin yüzü kara

Hümeti yok Peygamber''e bentlerini bozar oldum

Bu nefs ile dünya fani bu dünyaya gelen hanı

Aldattın ey dünya beni işlerinden bezer oldum

Yunus sordu girdi yola kamu gurbetleri bile

Kendi ciğerim kanıyla vasf-ı halim yazar oldum', 'Girdim aşkın denizine bahrılayın yüzer oldum Geştediben denizleri Hızır''layın gezer oldum Cemalini gördüm düşte çok aradım yazda kışta Bulam...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/ask-atesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hala Bekleyebilirm', 'hala-bekleyebilirm-betul-kondu-vqf2c', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bazen insanin 

Bütün umutlari 

Bir kusun bulutlara kaçisi gibi

Kaçar, gider

Sadece kaçar gider

İnsani, yalniz bir 

Yavru kedi gibi bırakıp gider

Umutlar bir tür

Bir tür bekleyistir

Ama bir gün 

Beklemeler, umutlar

Biter

İnsan tükenir

Hava kararır ve

Öfkeli bulutlar üzerimi kaplar

Sanki  hayatim umutlar ve bekleyisler içersinde tükenmistir

Ama benim hala umudum var hala 

Biliyorum bir kaç dakika sonra ölüyorum

Bunu senden ve öfkeli bulutlardan saklayamam

Bunu yapamam

Ama bir seyi yaparim 

Seni bir kaç dakika daha beklemeyi', 'Bazen insanin  Bütün umutlari  Bir kusun bulutlara kaçisi gibi Kaçar, gider Sadece kaçar gider İnsani, yalniz bir  Yavru kedi gibi bırakıp g...', ARRAY['Türk Edebiyatı','Şiir','Betül Kondu']::text[], 8.5, '{"poet":"Betül Kondu","poet_slug":"betul-kondu","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/hala-bekleyebilirm-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşıkmı Diyem', 'asikmi-diyem-yunus-emre-sq2q6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Erenlerin gönlünde ol sultan dükkan açtı

Nice bizim gibiler anda konuban geçti

Cümle erenler uçtu dağlar yazılar geçti

Aşk kazanına düştü kaynayıbanı pişti

Bu dünyanın meseli benzer murdar gövdeye

İtler gövdeye düştü Hak dostu kodu geçti

Aşıkmı diyem ona can terkini urmadı

Aşık ona diyeler kim melamete düştü

Yine esridi Yunus Taptuk yüzün görelden

Meğer onun gölünden bir cur''a şerbet içti', 'Erenlerin gönlünde ol sultan dükkan açtı Nice bizim gibiler anda konuban geçti Cümle erenler uçtu dağlar yazılar geçti Aşk kazanına düştü ka...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/asikmi-diyem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sitem', 'sitem-musa-eker-sesim', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biricik aşkım Hacere

Sevmeye mecburum

Sevilmeye muhtaç

Her şeye tok şu gönlüm

Bir sana aç

Kırdın kalbimi

Attın yerlere

Şimdi kim olacak

Derdime ilaç

Yaşa be! 

Sevin sen hep

Ben ağlar 

Çile çekerim

Kimseye demem yaptığın zulmü

Birgün çeker giderim

Her şey böyle gitmez

Sanma seni hep severim

Sana gelişim olur

Dönüşüm olmaz

Bu aşkın üstüne

Bir yudum su içerim', 'Biricik aşkım Hacere Sevmeye mecburum Sevilmeye muhtaç Her şeye tok şu gönlüm Bir sana aç Kırdın kalbimi Attın yerlere Şimdi kim olacak Derd...', ARRAY['Türk Edebiyatı','Şiir','Musa Eker']::text[], 8.5, '{"poet":"Musa Eker","poet_slug":"musa-eker","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sitem-23-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum Bu Yara Hiç Kapanmayacak', 'biliyorum-bu-yara-hic-kapanmayacak-cezmi-ersoz-ml4ka', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Telefonlarıma cevap vermeyeceksin…Cevap versen bile, öyle yorgun öyle

isteksiz çıkacak ki sesin, bir küfür gibi…

   Sevmeyeceksin beni…Biliyorum bu şehri bana dar edeceksin…

  Çünkü anladın; sevgimden tanıdın beni.O yanık, o hasta bakışımdan…Uçuruma

atlar gibi sevdalanışımdan…

  Sevmek deyince, hemen ardından, ölüm, dememden anladın…

  Anladın ve kardeşini bir kabustan uyandırır gibi çırılçıplak gerçeğe

uyandırdın beni; uyandırdın ve kaçtın… 

  Çünkü sen de benim gibiydin; sen de benim gibi seni sevmeyeni sevdin hep.Sana

acı çektireni…Seni aramayanı, telefonlarına çıkmayanı, çıkınca seninle bir küfür

gibi konuşanı sevdin…Sen de benim gibi seni incitip üzeni sevdin hep.

  Bakışından hissettim bunu, kokundan, dokunuşundan…

  Beni sevmeyecektin biliyorum ama…Ama, öyle susamıştımki kendim gibi birini

sevmeye…Öylesine muhtaçtımki gercekten incitilmeye, gercekten acı

çekmeye, kendim gibi birini özlemeye öylesine muhtaçtım ki, seni tanır tanımaz

çözüldüm…

  Sana da olmuştur…Öylesine susamışsındır ki sevilmeye, kendin gibi birini

bulunca tutamaz kendini, herşeyi, belkide söylenmiycek her şeyi o an, garip bir

telaşla söylersin…

  Hatta söylerken anlarsın, söylememen gereken şeyleri söylediğini

hissedersin, battığını, giderek çıkmaza girdiğini…Ama yine de engelleyemezsin

kendini tutamazsın.

  Aleyhinde olabilecek herşeyi söylersin…Üstelik bunu anladıkca daha da

batırmak istersin kendini…Biraz daha zor duruma düşürmek…

  Daha da kaybetmek, daha da dibe batmak istersin…Sanki bile isteye kendi

mutlulugunu kendi elinle bozmak istersin…Kendinden gizli bir öç alır gibi.

  Sanki hiç mutlu olmak istemiyormuş gibi…Sanki hiç sevilmek istemiyormuş

gibi…

  Bir tür gurur muydu bu? 

  Birgün nasılsa ve hiç olmadık bir anda alınıp kopartılmadan, kendi

ellerimizle onu yok etmek, bizim gibilerin mutluluğuna tahammül edemeyen bu

hayatta, bu hayatın zorba kurallarına bir tür başkaldırmak mıydı? 

  Bir şizofren çocuk tanımıştım bir gün.Tam karşımda

oturuyordu.gencecik, yakışıklı bir çocuktu.Şizofren olduğunu

biliyordu.Biliyordu iyileşemiyeceğini…İki de bir, önce kolunu uzatıp, sonra

avucunu açıyor; Mutluluk avuçlarımdaydı, yakalamıştım ama kaçtı

diyor, kaçtı, derken avuçlarını boşluğa kapatıyordu…

  Hiç unutmuyorum, bu hareketi defalarca yapmıştı…

  Yine hiç unutmuyorum; burjuvalara özenen bir ailede büyüdüm ben.Görgü kitabı

masanın üstünde dururdu hep.

  Annem o kitabı defalarca ezberletirdi bize.Yemeğe nasıl oturulacak..çorba

nasıl içilir? Kaşık nerede, çatal nerede durmalı…Balık nasıl yenir? Peçete nasıl

katlanır…Sinemada nasıl oturulur…

  Ben de eskiden senin gibi saftım.İnanırdım bu dünyada bile şölenler

olacağına…Bu dünyada anne, baba, kardeşler, bir sofrada lekesiz bir mutluluk

yaşayabilirler diye inanırdım…O kasvetli görgü kuralları kitabına rağmen

inanırdım…

  Önce dilediğim gibi başlardı herşey.Herkes bir arada, sonsuz mutlu gibi…Sonra

birden hiç beklenmedik bişey olur, biri ağlayarak odaya kaçardı…İçerden, arka

odadan, ağlamaklı, sonsuz küskün sesler gelirdi; bıktım artık, bıktım, usandım

hepinizden, gideceğim buralardan, yetti artık! …

  Ben de senin gibi saftım o zamanlar…Gidilecek neresi var dı ki derdim…İşte

hep birlikteyiz…Alemi var mı bu mutluluğu bozmanın? …

  Sonraları çok sonraları anladım.Meğer biz, bizim aile, herkes, tesadüfen bir

araya gelmişiz tesadüften de öte…Biz…bizim aile, herkes, aslında hiç

istemeden, nedeni bilinmeyen bir zorunluluk sonucu bir araya gelmişiz…

  Aslında biz bir araya gelmemek için yaratılmışız.

  Hayatın en büyük yanlışıymış bizim bir arada olmamız! …

  Evet cok geç anladım…

  Bıraktım lekesiz mutlulukları; ben kavgasız, üzüntüsüz bir pazar sofrası

özlerken, aslında herkes…annem, babam, kardeşim o evden uzaklara, hiç dönmemek

üzere çok uzaklara gitmek istiyormuş…

  Dünyanın en mutsuz otogarı…Dünyanın en imkansız istasyonuydu bizim

evimiz…Yıllarca uzaklara, cok uzaklara gitmek isteyip, bir türlü gidemeyenlerin

sonsuz bekleme durağıydı bizim evimiz…

  İşte bu yüzden sevmek benim için bir tutsaklıktı, tuzaktı böylesi sevip

bağlanmak.Uzaklara cok uzaklara gitmek isteyenleri engellemekti.

  Sevgi yüzünden bizim ailedeki hiç kimse istediği yere

gidemiyordu…Birbirimize duyduğumuz sevgi, aynı zamanda bizi birbirimize düşman

ediyordu…

  Hem biz, bizim aile…Güneşli bir günde ansızın başlayan sağanak yağmurlar

gibiydik…

  Bu yüzden hep hırçın, hüzünlü, kırgındık…

 Bu yüzdendi, her şeyi, çok iyi gidiyor sanırken, içimizde yükselmesine bir türlü

engel olamadığımız o felaket duygusu…

  Anlamıştım senin ailen de böyleydi…

  Üstelik öyle severlerdi ki sizi, birgün hiç olmadık bir anda, aslında

istenmeyen çocuklar olduğunuzu söylerlerdi size! …

  Sana ya da kardeşine…Tesadüfen dünyaya geldiğinizi…Beklenmedik bir misafir

olduğunuzu! …Aksi gibi, istikbaliniz için hiçbir şeyi esirgemediklerini

söyledikten sonra söylerlerdi böyle sıradan şeyleri! …

  Sizin için…Senin için hiçbir fedakarlıktan kaçınmadıklarını söyledikten

sonra…

  Senin de ailen benimki gibiydi…Güneşli bir günde ansızın başlayan sağanak

yağmurlar  gibiydi…Bu yüzden sen de benim gibi böyle hırçın, hüzünlü, kırgınsın

her şeye…

  Yıllar önce tanıdığım o şizofren çocuk gibi; tam mutluluğu yakalamışken

kaybetmiş gibisin hep…

  Ben beni istediğim gibi sevmemiş olan annemin hayaletini arıyorum imkansız

kadınlarda…

  Sen, seni istediğin gibi sevmemiş olan babanın hayaletini arıyorsun imkansız

erkeklerde…

  Biliyorum ne ben o kadını bulacağım ne de sen o erkeği bulacaksın…

  Ve ne acı ki, hep bizi sevmemiş olanları seveceğiz ikimizde…Ne acıki, hep bizi

incitip üzenlere bağlanacağız…Telefonlarımıza çıkmayanlara… Çıksa bile küfür

gibi konuşanlara sevdalanacağız…

  Bizden bir çift güzel laf esirgeyenleri özleyecegiz…

  Ölesiye, amansız seveceğiz onları…

  Biliyorum, bu yüzden odan böyle…Güncelerin ortalık yerde…Kitapların

orada, burada…Anıların saçılmış ortalık yere…Her şeyin darmadağın…

  Biliyorum bu yüzden düzenden, adı düzen olan her şeyden nefret ediyorsun…Sen

de benim gibi; toparlayıp da ne yapacağım, düzenli olunca ne olacak; sonunda bir

gün biri gelip her şeyi, biriktirdiğim, düzenlediğim, üzerine özenle titrediğim

her şeyi daha önce hep olduğu gibi hiç beklemediğim bir anda savurup, bozup

gitmeyecek mi, diye düşünüyorsun…

  Biliyorum, sen benim için hiç bir zaman ulaşamayacağım annemin

hayaletisin…Ailemdeki insanlar gibisin çok duygusal çok güçlü, çok yaralı…

  Onlar da senin gibi seninkiler gibiydi…Aklı başında, mazbut insan rolünü

oynamaktan ve ertelenmiş düşleri yüzünden yorgun düşmüş, yarı çılgınlardı…Hepsi

yanlış evde ve yanlış bir yerde yaşadıklarını söylerlerdi…Düşleri çok

garipti…En kısa yolculuk bile onları yorduğu halde; okyanusları aşmayı ve başka

kıtalara gitmeyi düşlerlerdi…

  Yine aradım seni, yoksun…bulsam, benimle küfür gibi konuşacaksın…

  Bir kere çözüldüm sana…Bir kere sana senin gibi olduğumu hissettirdim…

  Oysa baştan beri biliyordum; sen.seni sevmeyenleri seversin.Tıpkı benim

gibi…

  Ama öyle özledim ki benim gibi birini sevmeyi…Öyle özledimki kendim gibi

biri tarafından incitilmeyi, üzülmeyi…

  Yine aradım seni yoksun…Beni de birileri arıyor…Beni de kendi gibi birini

sevmeyi özleyenler arıyor…Kendi gibi biri tarafından incitilmeyi, üzülmeyi

özleyen birileri arıyor.

  Hiç cevap vermiyorum…BEN SENİ İSTİYORUM, SENİ ARIYORUM…

  Kayıtsızlığınla beni yok ediyorsun, geride sen kalıyorsun.Ama seni de biri

yok ediyor…

  Aslında bu oyunda herkes birbirini yok ediyor…

  Ben birilerini, o birileri başkalarını.Sen beni…Seni bir başkası…

  Hem çok iyi biliyorum; beni sevsen bile hiç kapanmayacak bu yaram…Seni biri

sevse de hiç kapanmayacak bu yaran…

  Hiç kapanmayacak! …Avuçların hep boşluğa kapanacak.Tıpkı o şizofren genç

gibi…', 'Telefonlarıma cevap vermeyeceksin…Cevap versen bile, öyle yorgun öyle isteksiz çıkacak ki sesin, bir küfür gibi…    Sevmeyeceksin beni…Biliy...', ARRAY['Türk Edebiyatı','Şiir','Cezmi Ersöz']::text[], 8.5, '{"poet":"Cezmi Ersöz","poet_slug":"cezmi-ersoz","theme":"Türk Şiiri","is_hero":false,"total_lines":130,"source_url":"https://www.antoloji.com/biliyorum-bu-yara-hic-kapanmayacak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Küllerini Bıkakıyorum', 'sana-kullerini-bikakiyorum-sair-bera-fdawd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'tuz gibi buz gibi  bir aşk hikayesi 

tuz buz olmuş yaşananlar 

bir merhabaya bıçak sallar gibi 

gözlerinde bakışlar                                                                       

sadece sen yanmadın 

anılar çakmak çakmak 

bir kibrit alevinin verdiği kadar mutluluk

en az onun kadar çabuk yanacak

bu aşkın güzelliklerini 

çirkinlikleriyle aynı anda yakıyorum

kederim bana ders olsun 

kelimeler asılı kaldı dudaklarımda giderken 

herşeyi yaktım 

sana küllerini  bırakıyorum

 uçurumlar çizdim yüzünde 

hiç dert etme

adam olana; 

sırdaş olarak şiirler 

ibret olarak dünler yeterli

tutuşsun gecenin rengi 

son sözü söyleme şansı madem bana verildi 

deliler gibi bir sukut

ne anlarsan anla gayri 

pembe düşleri 

sahte gülüşleri 

ıslak öpücükleri 

nasıl siliyorsa zaman 

bende öyle yaktım eskileri

sana küllerini bırakıyorum.', 'tuz gibi buz gibi  bir aşk hikayesi  tuz buz olmuş yaşananlar  bir merhabaya bıçak sallar gibi  gözlerinde bakışlar                         ...', ARRAY['Türk Edebiyatı','Şiir','Şair Bera']::text[], 8.5, '{"poet":"Şair Bera","poet_slug":"sair-bera","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sana-kullerini-bikakiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaz Yağmuru', 'yaz-yagmuru-fatih-cinar-po4mx', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir yaz yağmuru gibi düştün yüreğime

sen çare oldun ağlayan gözlerime

dört duvar arasında hayalin gölgen

gitmedi gitmeyecek gözlerimden

gördüğüm en güzel yazdı bu yaz

yüreğim can buldu düştükçe aşka

gördüğüm en güzel yazdı bu yaz

hayatın nesi var sevmekten başka

istemem bir gölge düşsün sevdama

razıyım ömrümce yaz değil kışlara

beni öldürmeye hançer arama

bir gözyaşı bir ayrılış bir veda yeter

müzik: fatih çınar', 'bir yaz yağmuru gibi düştün yüreğime sen çare oldun ağlayan gözlerime dört duvar arasında hayalin gölgen gitmedi gitmeyecek gözlerimden görd...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yaz-yagmuru-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Seviyorum', 'seni-seviyorum-fatih-cinar-j7xnv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sensiz bir akşamüstü gezerken sahilde

hırçın dalgalar vuruyordu taşlara

ayağım takıldı kumsaldaki hecelere

yağan yağmur eş oldu gözümdeki yaşlara

sevenin gözyaşları döküldüğünnde denize

şu imzayı atar dalgalar sahile

seni seviyorum seni seviyorum

seni seviyorum seni çok çok seviyorum

müzik: fatih çınar

0312 431 10 19', 'sensiz bir akşamüstü gezerken sahilde hırçın dalgalar vuruyordu taşlara ayağım takıldı kumsaldaki hecelere yağan yağmur eş oldu gözümdeki ya...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/seni-seviyorum-47-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeter Bana', 'yeter-bana-hasan-ozemek-j6qwt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yaşanmış mutluluklar kısa sürdü, bir gün batımı gibi

Sevginin ne olduğunu anlamadım, çiçeklerini döken ağaç misali

En son gözlerinde yakalamıştım güneşi

Gökyüzünde son maviliği aldı karanlıklar, 

Yokluğunda güneş yok vakit hep gece, 

Beni hep o gecelere mecbur ettin, soğuk gecelere

Sen gündüzlerde yaşa

Senin olsun gökyüzünün  mavileri...

Gözlerinin kıyılarındaki güneş yeter bana...', 'Yaşanmış mutluluklar kısa sürdü, bir gün batımı gibi Sevginin ne olduğunu anlamadım, çiçeklerini döken ağaç misali En son gözlerinde yakalam...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yeter-bana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlar Mısın?', 'hatirlar-misin-ahmet-selcuk-i-lkan-ppodt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Seninle zamanların en ölmezini yaşamıştık

En büyük çemberini çizmiştik mutluluğun

En geniş açılarına aşkı taşımıştık beraberce

Hatırlar mısın? 

Yağmurlar yağdırmıştık en kurak mevsimlerde

Boy boy umutlar yeşertmiştik içimizde

O ne özlemlerdi gizlediğimiz

Hatırlar mısın? 

Bir şarkımız vardı ki en içlisiydi şarkıların

Şiirlerim vardı sana okurdum mısra mısra

Ve sonra göz göze gelirdik uzun uzun

Hatırlar mısın? 

Sen bensiz ben sensiz az mı ağladık

Az mı kaçtık gölgesinden ayrılığım? 

Tanrıya kaç geceler avuç açtık

Hatırlar mısın? 

Ve neden sonra sarardı yaprakları mutluluğun

Ve neden bir bir kuruttuk umutları, özlemleri? 

Oysa bir ağaçtık dal dal çiçek açan, meyve veren

Hatırlar mısın? 

Öyle ya bir kara tren ayırmaya yetti bizi

Bir mendil bile sallayamadım ardından

Öylece yalnız, öylece sensiz kaldım

Hatırlar mısın? 

Şimdi boş vagonlarda arıyorum seni

Anıları yaşıyorum yeni baştan

Elimde değil seni hatırlıyorum

bilmem ki sen de beni

Hatırlar mısın?', 'Seninle zamanların en ölmezini yaşamıştık En büyük çemberini çizmiştik mutluluğun En geniş açılarına aşkı taşımıştık beraberce Hatırlar mısı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/hatirlar-misin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fenerli Sokak', 'fenerli-sokak-ahmet-selcuk-i-lkan-5cy62', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Fenerli Sokak''ta gün altıda batar

Bir başka renge bürünür Fenerli Sokak

Fenerli Sokak''ta bütün adamlar

Konuşurlar benim gibi hep susarak

Seni Fenerli Sokak''ta bekliyorum.

Yağmurlar yağmaya görsün

Meyhanelerde cümbüş

Sen orada kimleri görürsün

Ben gibi sevdaya tutulmuş, düşmüş

Seni Fenerli Sokak''ta bekliyorum.

Kesilir çocuk sesi, kadın sesi

Fenerli Sokak''ta yanınca ışıklar

Benim gönlümde bir sarhoş neşesi

Bana ümitler taşır bu sakin akşamlar

Seni Fenerli Sokak''ta bekliyorum.

Dönemem bir adım geriye 

Biraz ötede belki sen varsın

Boşver aldırma sen hiç kimseye

Yolun düşerse beni meyhanede ararsın

Seni Fenerli Sokak''ta bekliyorum

Biraz da seninle dolaşalım bu sokağı

Aşkımı kaldırımlardan, parke taşlarından sor

Tanımaz gözlerim senden daha uzağı

Sensiz olmak senle olmaktan da zor

Seni Fenerli Sokak''ta bekliyorum.

Seni Fenerli Sokak''ta bekliyorum

Gönlüm Ümit pınarı, yüreğim sabır taşı

Bugün olmazsa yarın geleceksin biliyorum

Seneler silemeyecek asla bu aşkı

Seni Fenerli Sokak''tan daha çok seviyorum...', 'Fenerli Sokak''ta gün altıda batar Bir başka renge bürünür Fenerli Sokak Fenerli Sokak''ta bütün adamlar Konuşurlar benim gibi hep susarak Sen...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/fenerli-sokak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bulamadığım Yolların Öyküsü', 'bulamadigim-yollarin-oykusu-mestan-ozyer-jcu2l', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yeni bir şair bulmalıyım şimdi

Yada oturup kendim yazmalıyım

Bulamadığım yolların öyküsünü

Tüm bildiklerimi bir bir unutup

Yollara düşmeliyim yeniden

Sen daha uyanmadan yarılamalıyım yolu

Belki kara bir sevda değilde

Unutmaktır belleğimi geri getirecek olan

Kara bir delikten geçipte varmak gibi

Yaşadıklarımdır belki

Bu yitirişte ilk bulacağım

Alnıma dayalı bir namluyla yaşadım

İnce bir tel üstünde yıllardır

Parçalanmiş bir yürekle de yaşarım

Yeniden ateş olurum zirvesinde dağların

Yanıtlanmadan kalan sorular

Gerçek cezası ömrümün

Toplayabilseydim, hep çözülen saçlarını

Gelip tutarmıydın bir deli rüzgarın elinden

Sorular yanıtsız kaldı

Ne sen ne ben bilebildik

Bir uzun yürüyüştü belki yapamadığımız

Kalakaldık başladığımız yerde

''Hayallerini yak, evi ısıt'' diyordu ya şair

sen şairini bulmuşsun belli

Bense yeni bir şair bulmalıyım şimdi

Yada oturup kendim yazmalıyım

Bulamadığım yolların öyküsünü

(08.2001, İzmir)', 'Yeni bir şair bulmalıyım şimdi Yada oturup kendim yazmalıyım Bulamadığım yolların öyküsünü Tüm bildiklerimi bir bir unutup Yollara düşmeliyi...', ARRAY['Türk Edebiyatı','Şiir','Mestan Özyer']::text[], 8.5, '{"poet":"Mestan Özyer","poet_slug":"mestan-ozyer","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/bulamadigim-yollarin-oykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Kahretsin', 'allah-kahretsin-ahmet-selcuk-i-lkan-r85r7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu böyle sürüp gitmeyecek biliyorum

Bir sabah bir dilencinin avuçlarına bırakacağım kalbimi

Kim ne derse desin! 

Tahammülüm kalmadı artık

Bıktım seni sensiz yaşamaktan

Nasılsa döneceğin yok senin

Çıldıracağım bu gidişle

Allah kahretsin! ..

Durup durup seninle gezdiğim yerlerde dolaşıyorum

Sanki köşe başından sen çıkacaksın

Sanki duraklarda beni bekliyorsun

Geçen gün birine rastladım aynı sokakta

Saçları sen gözleri sen kaşları sen

Koştum heyecanla peşinden 

Ve hayatımda ilk defa bir tokat yedim senin yüzünden

Allah kahretsin! ...

Dünya ateşler içinde

Savaşlar almış başını gidiyor

Afrika''da insanlar açlıktan ölüyor

Bense bu gidişle sensizlikten öleceğim

Umurunda mı senin? 

Kimbilir hangi cehennemdesin? 

Allah kahretsin! ..

Hangi masaya otursam 

Senin sevdiğin içikiyi koyuyorlar önüme

Vazomda hep senin sevdiğin çiçekler

Ve dudaklarımda hep senin sevdiğin şarkılar

Senin doğumgünlerini kutluyorum senden habersiz

Ve her sabah dualar ediyorum mutluluğun için

Ne yapsam, ne etsem, nereye gitsem

Ecel gibi peşimdesin

Allah kahretsin! ..

İşte böyle bir sevda benimkisi

Bu zamanda, bu devirde

Haklısın adam olacağım yok benim

En güzeli artık son vermek bu hayata

En korkunç uçurumlardan bırakmak kendimi

Ya da en yüksek tepelerden

En uçsuz bucaksız denizlere bırakmak bedenimi

Ama içimde sen varsın 

Ya sana bir şey olursa? 

Allah kahretsin! ..', 'Bu böyle sürüp gitmeyecek biliyorum Bir sabah bir dilencinin avuçlarına bırakacağım kalbimi Kim ne derse desin!  Tahammülüm kalmadı artık Bı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/allah-kahretsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Kere İki Dört', 'i-ki-kere-i-ki-dort-ahmet-selcuk-i-lkan-hfpfz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bitmeyen ne var ki dünyada? 

Dağ mı? 

Deniz mi? 

Çöl mü? 

Biter! 

Şan mı? 

Şöhret mi? 

Para mı? 

Biter! 

Öyleyse aşk da biter

Ya uzakta! 

Ya kucakta!', 'Bitmeyen ne var ki dünyada?  Dağ mı?  Deniz mi?  Çöl mü?  Biter!  Şan mı?  Şöhret mi?  Para mı?  Biter!  Öyleyse aşk da biter Ya uzakta!  Ya...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/iki-kere-iki-dort-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çark', 'cark-monad-balkan-096xl', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'özleminin

yüzünü gördüm ilk kez

çocukluğumun bahçesinde

bir sonsuzluk geçmişti

oysa

gökler

bedenimin biçiminde oluştu

ayağımı ısıran çıngıraklı yılan

ben kendim miydim

tersine dönen felek gibi

rastlasam

ona ah bir kez daha

bırakmam artık

mevlevi gibi

dönersem çevremde

gerisin geri

ankara 1993', 'özleminin yüzünü gördüm ilk kez çocukluğumun bahçesinde bir sonsuzluk geçmişti oysa gökler bedenimin biçiminde oluştu ayağımı ısıran çıngıra...', ARRAY['Türk Edebiyatı','Şiir','Monad Balkan']::text[], 8.5, '{"poet":"Monad Balkan","poet_slug":"monad-balkan","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/cark-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ay Işığı', 'ay-isigi-vedat-i-zci-1v3qs', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gündüz gözü ile ay ışığını görmek istedim

Ay ışıktan saklanır dediler

Halbuki ay; karanlıktaki bir ışık: 

Sevgiler ay ışığında saklı...', 'Gündüz gözü ile ay ışığını görmek istedim Ay ışıktan saklanır dediler Halbuki ay; karanlıktaki bir ışık:  Sevgiler ay ışığında saklı......', ARRAY['Türk Edebiyatı','Şiir','Vedat İzci']::text[], 8.5, '{"poet":"Vedat İzci","poet_slug":"vedat-i-zci","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ay-isigi-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Selam Olsun', 'selam-olsun-mine-erkut-aezus', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Selam olsun dostlar size

Doğan güneşe

Yeni bir güne

Selam olsun her yöne

Yeni bir gün başlıyor

Neşesiyle hüznüyle

Seninle ve sensizliğiyle

Selamım tüm sevgilere

Günün ağarmasıyla başlar sancılar

Dert, tasa ve keder

Bir gün daha geçer

Selam olsun geçmişe, geleceğe

Selam olsun seninle geçirdiğim her güne', 'Selam olsun dostlar size Doğan güneşe Yeni bir güne Selam olsun her yöne Yeni bir gün başlıyor Neşesiyle hüznüyle Seninle ve sensizliğiyle S...', ARRAY['Türk Edebiyatı','Şiir','Mine Erkut']::text[], 8.5, '{"poet":"Mine Erkut","poet_slug":"mine-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/selam-olsun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğlum''a Özel', 'oglum-a-ozel-mine-erkut-ackr0', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Oğlum 

Bir tanemsin sen

Seni ilk hissettiğim anda

Mutluluğun en yücesini tattım biranda

İşte o an

Girdin hayatıma

Sana ilk dokunduğumda

Yeniden geldim seninle dünyaya

Gözlerinle bana baktığında

Minik ellerine dokunduğumda

O mükemmel kokunu aldığımda

Anneliğimi yaşattın bana

İlk yürüyüşündeki heyecan 

Bana sarılışın

İlk anne deyişin

Yüzündeki gülüşün

Yaşattığın mutluluk

Hissetirdiğin duygular

O doyumsuz sevginle

Biriciğimsin oğlum', 'Oğlum  Bir tanemsin sen Seni ilk hissettiğim anda Mutluluğun en yücesini tattım biranda İşte o an Girdin hayatıma Sana ilk dokunduğumda Yeni...', ARRAY['Türk Edebiyatı','Şiir','Mine Erkut']::text[], 8.5, '{"poet":"Mine Erkut","poet_slug":"mine-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/oglum-a-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İmkansız Sevdamız', 'i-mkansiz-sevdamiz-mine-erkut-lhln4', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğimde bir resmin acısını taşıyorum

Kaç zamandır amansız bir tutkudayım

Çocukta değilim oysa

Kirpiklerime astığım bir sevdanın

İmkansızlığındayım

Kim derdi bu mevsimde 

Yapraklar uçuşacak diye

Kim derdiki durup dururken

Yüreğim tutuşacak diye

Biliyorum imkansız sevdamız

Öyle de olsa

Ancak ikimize yakışacak diye

Kimbilir kaç gece geçti

Sabahları sabaha

Umutları yarına yükledim

Ve gecelerimdeki yanlızlığı

Sendeki imkansızlığa ekledim

Sakın sanma 

Yokluğuna yanlızlığına üzüldüğümü

Unutmaki

Ben yıllarca

Sendeki imkansızlığı özledim

Kimbilir kaç gece geçti

Ararken umutlarımı

Çalsın diye kapımı

Ne seni nede başkasını özledim

Ben yanlızca 

Yüreğime astığım mektuplarına

Sendeki imkansızlığı özledim', 'Yüreğimde bir resmin acısını taşıyorum Kaç zamandır amansız bir tutkudayım Çocukta değilim oysa Kirpiklerime astığım bir sevdanın İmkansızlı...', ARRAY['Türk Edebiyatı','Şiir','Mine Erkut']::text[], 8.5, '{"poet":"Mine Erkut","poet_slug":"mine-erkut","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/imkansiz-sevdamiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dedikodu', 'dedikodu-ahmet-selcuk-i-lkan-7yw7j', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'O ağlamazdı

Ağlattılar! 

Önce gözlerini çivilediler boşluğa

Ve kulaklarını çaldılar

Ne varsa ne yoksa

Bir bir anlattılar.

''sevmiyordu'' dediler

Aldattılar

Ümitlerini, hayallerini

Özlemlerini, rüyalarını

Parça parça

Kopardılar! ..

Sonra unutulduğuna, terkedildiğine

İnandırdılar.

Dudaklarını ısırdı zavallı

Yumrukladı masayı olanca hıncıyla

Ve kalktı yerinen gitti o gidiş

Sevdiğinden

Ayırdılar...', 'O ağlamazdı Ağlattılar!  Önce gözlerini çivilediler boşluğa Ve kulaklarını çaldılar Ne varsa ne yoksa Bir bir anlattılar. ''sevmiyordu'' dedil...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/dedikodu-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Neden Soğuksun Öyle?', 'olum-neden-soguksun-oyle-ahmet-selcuk-i-lkan-fxgp0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kemal''in gemisinde gitti sarıldığım umutlar

İsyanım şimdi Hamit''in Makber''indedir! 

Ağlasam sesimi duyar mı mısralarında Orhan Veli? 

Dokunabilir mi gözyaşlarıma inceden? 

YA Cahit! Bir teselli verir mi Yaş Otuzbeş''inden? 

İşte eteklerimde bir yığın gümüş yaprak

İşte Haşim bakıyorum semaya ağlayarak! 

İçimde çaresizliğin binbir ahı

İçimde en korkunç yalnızlıklar

Fikret''im bu gecenin de olur mu sabahı? 

Bir el var sonsuzluğa alıyor beni

Bir el var çekiyor beni anılardan

Ya o karanlığı bölen sesler

Uğultular, akisler, gölgeler

Nerdesin? Nerdesin? Tecer! 

Bak! Bu resme nasıl imrenmedetim

Sanırım ki gülüyor! 

Hani o saadetten bile yoksunum şimdi sen kadar

Ama öyle ya Akif''im

Değil yalnız dostlara, sevgililere, analara

Daha nicelerine kucak açar bu topraklar! 

Yummak ne çare elleri göğe doğru

Söyle hangi gerçekte bunca yalan var? 

Acımı binlerce şiirin anlatamaz Ümit Yaşar! 

Ama gel gör ağlayamıyorum gönlümce

Gel gör şuramda nasıl bir yara kanar

Zira; boş değil bu ağıt bu şarkılar

''Ağlarsa anam ağlar, gayrısı yalan ağlar... ''', 'Kemal''in gemisinde gitti sarıldığım umutlar İsyanım şimdi Hamit''in Makber''indedir!  Ağlasam sesimi duyar mı mısralarında Orhan Veli?  Dokuna...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/olum-neden-soguksun-oyle-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Ahmet Abi', 'ah-ahmet-abi-ahmet-selcuk-i-lkan-bgu09', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biz böyle olacak adam değildik Ahmet abi

Bu değildi hayattan beklediğimiz

Ne hayallerimiz vardı seninsle

Gel gör ki beş para etmedi ümitlerimiz

Yıldırımlar düştü güvendiğimiz dağlara

Hep boş çıktı sarıldığımız eller

Hep taş çıktı inandığımız kalpler

Kaç kez sırtından vuruldu hayallerimiz

Kaç kez yıkılıp kaldık köşe başlarında

Kaç kez delik deşik oldu yüreğimiz

Görüyorsun ya Ahmet Abi

Görüyorsun ya

Bozuk para gibi harcandı gençliğimiz.

Kimbilir nerede senin o liseli

Kimbilir nerede benim o üniversiteli

Birimiz doktor olacaktık birimiz mühendis

Gel gör ki beş para etmedi ümitlerimiz

Oku adam ol derdin bana hatırlar mısn? 

Oysa daha okumadan elimden aldılar kitaplarımı

Sayfa sayfa yırttılar umutlarımı...

İşte bu yüzden hala ıpıslak bakışlarım

İşte bu yüzden hala yumruk yumruk ellerim

İşte bu yüzden hep böyle çatıktır kaşlarım

Adam olamadımsa

Kendini adam sananlar utansın be Ahmet Abi! 

Kendini adam sananlar utansın...

Bak bir türlü bitmedi hayat kavgamız

Hep başka bahara kaldı sevdamız

Kim vurduya gitti yarınlarımız

Yalan mı be Ahmet Abi? ..

Yalan mı be? ..

Sınırı olmayan bir dünya yok mu? 

Kavgasız savaşsız bir hayat yok mu? 

insanca yaşamak bu bize çok mu? 

Konuşsana be Ahmet Abi..

Konuşsana be...

Elveda aşklara

Elveda yıllara

Bu nankör hayata

Yenildik be Ahmet Abi

Yenildik be...

İnsanın insanı ezdiği bu yerde

Bak bir ömür harcadık

Ve harcandık be Ahmet Abi

Harcandık be! ..

Ah Ahmet Abi ahh..', 'Biz böyle olacak adam değildik Ahmet abi Bu değildi hayattan beklediğimiz Ne hayallerimiz vardı seninsle Gel gör ki beş para etmedi ümitleri...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/ah-ahmet-abi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklesene', 'beklesene-ahmet-selcuk-i-lkan-a6u9w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her şarkı bir sevdadan dökülür mısra mısra

Her şarkı yaşanmış bir masalı resmeder Selene

Düşün çamlar arasını, mehtaplı geceleri, masmavi denizleri

Düşün şimdi yollara serpilen ümitleri

Hadi bir şarkı da sen 

Söylesene! ..

Bak büütün güzelliklerin tümü sende

Bak sen de gülümsüyor en amansız özlemler

Unut bir yerde bensiz olduğunu, çaresiz

Ayrılıklar sevenlerle yücelir Selene

Hadi sil gözlerini

Gülsene! ..

Bitimsiz bir sevdadır yaşamak

SEvmekse en güseli mutlukların

Sense içimde en tanrısal gerçeksin Selene

İşte yüreğim bildiğince çarpıyor sen, sen diye

Sende gözlerim, sende ellerim, sende sen olan varlığım

Düşünsene! ..

Bakma sen yağmurların sağnak döküldüğüne

Bakma sen gecelrin karanlığına Selene

Bu pembe umut sütten de beyaz

Bu senli hayal gülden de kırmızı

İşte renk renk çiçekleri aşkımızın

Görsene! ..

Ve bir gün dur diyeceğim geçip giden zamana

Son kurşunu sıkacağım sensizliğe Selene

Öbek öbek mutluluklar taşıyacağım dağ eteklerinden

Sana gökten yıldızları koparacağım bir bir

Sana bitmez tükenmez sevdalar getireceğim

Beklesene! ..', 'Her şarkı bir sevdadan dökülür mısra mısra Her şarkı yaşanmış bir masalı resmeder Selene Düşün çamlar arasını, mehtaplı geceleri, masmavi de...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/beklesene-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Agop Ahh', 'ah-agop-ahh-ahmet-selcuk-i-lkan-24eao', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', '''Bütün ekranlarda kısa metrajlı aşklar

                                                                  Durdurun Dünya''yı inecek var''

Son şişeyi hakladık Agop

Mezemizde tükendi böylece

Sustur artık bu kaseti

Deşmesin ''aman''lı'' şarkılar yüreğimizi

Bir of daha çekmeyin 

Şu kavanoz dipli dünya ya Agop

Ah Agop ah

Çekmesen dayanır mı yürek? 

Çekmesen biter mi ömür be? 

Bir kere düşmüşüz

Bir kere yanmışız Allah''ına kadar

Ne anlar halimizden süt kuzuları, 

Ne anlar derdimizden beyefendiler

Sen hepsini sil defterinden

En kralına çizgiyi çek be Agop

Of Agop of 

Masama o''nu getir hasretim dinsin artık

Zaten azgın boğalar gibi içimde tepiniyor yalnızlık

''O'' yoksa 

''Az acılı'' bir sevda getir masama

Bıktım bu zehir zıkkım sevdalardan

''İhaneti az'' bir gece koy önüme 

Hilesiz-maskesiz dertleşelim seninle

Zaten bıçak çekiyor her gece bana hatıralar

Sıkıştırıp beni bir köşeye

Ya o''nu bul

Ya da bizi rahat bırak diye

          

Ah agop ah

Buzları da kadehime değil yüreğime dök bu gece

İçim yanıyor içim

Benzine bulanmış fitil gibiyim

Gözlerimin musluğunu bir açsam

Gözyaşlarım beni boğacak

Boşver sigarayı tütünü Agop

Son kibriti üstüme çak

Gönlümce yanayım bu gece

Oldu olacak

Oy dibi delik dünya oy

Nasıl da harcıyoruz gençliğimizi? 

Nasıl da can çekişiyor umutlarımız? 

Oysa

Kan ter içinde taşıdık biz ne ayrılıkları

Kitabını yazdık biz ne yanlızlıkların

Ne fotoğraflarını çektik bir bilsen Agop

O yüzsüz suratların

Anlayacağın ne acılar çakmiş

Ne günler görmüşüz

Sözde yaşamak diyorlar buna Agop yaşamak

Yaşamak buysa biz çoktan ölmüşüz! 

Gel gör ki ağlayanımız yok...

Anlamadım gitti be Agop

Sevgili çok da bu alemde

Niye bir dostumuz yok? 

Niye hiç dostumuz yok? 

Ahh Agop Ahhh!', '''Bütün ekranlarda kısa metrajlı aşklar                                                                   Durdurun Dünya''yı inecek var'' Son ş...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ah-agop-ahh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ara', 'ara-ahmet-selcuk-i-lkan-fz473', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yorgun bir hasretle dönersen bir gün 

Beni burda değil kalbinde ara! .. 

Ne kadar yıkılmış olsan da o gün 

Beni bende değil kendinde ara! ..

	

Saçında beyazlar taradığın gün 

Maziyi yeniden aradığın gün 

Hıçkıra hıçkıra ağladığın gün 

Beni gözyaşında gözünde ara.', 'Yorgun bir hasretle dönersen bir gün  Beni burda değil kalbinde ara! ..  Ne kadar yıkılmış olsan da o gün  Beni bende değil kendinde ara! .....', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ara-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayrılık Kapıyı Çalıyor', 'ayrilik-kapiyi-caliyor-ahmet-selcuk-i-lkan-65qcs', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ayrılık kapıyı çalıyor açma

Biraz daha düşün zamanımız var.. 

Ne günler yaşadık bak sayfa sayfa 

Seninle yazılmış romanımız var..

Gönül kapısından hemen uçma dur! 

Selamsız vedasız böyle kaçma dur! 

Bilinmez yerlere yelken açma dur! 

Seninle mutluluk limanımız var! ...

Bir anda yokuşa çevirme düzü

Dargınlık bir aşkın tadı ve tuzu

Hatırla Tanrıya verdiğin sözü

Ayrılmak yok diye yeminimiz var...', 'Ayrılık kapıyı çalıyor açma Biraz daha düşün zamanımız var..  Ne günler yaşadık bak sayfa sayfa  Seninle yazılmış romanımız var.. Gönül kapı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Selçuk İlkan']::text[], 8.5, '{"poet":"Ahmet Selçuk İlkan","poet_slug":"ahmet-selcuk-i-lkan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ayrilik-kapiyi-caliyor-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Diyarbakır''da', 'diyarbakir-da-baver-beser-cc8my', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle olsaydık eğer; 

Yani sen ve ben, biz işte.

Derin sohbetlere dalardık.

Belki ülkeyi kurtaramazdık ama, 

En azından sorumlu birer birey olma gereğini yerine getirirdik.

Gezinmedik sokak arası bırakmazdık.

Sakız satan küçük kızdan aldığımız, 

Sakızlardan çıkan aşk nedirleri, telafuz çabası belirirdi bizde.

Kaçak çay içerdik, yediğimiz tandır ekmekleri üstüne.

Hevsel Bahçelerini hayal ederdik, bilmeden hikayesini.

Yol üstünde bulunan çiğerciye uğrar akşam üzeri, 

İki büyük dürüm yaptırırdık.

Yada nenemlere uğrar ve nenemim bize zorla yemek yedirme çabalarına maruz kalırdık.

Bana seni anlatırdı, sen anlamazdın.

Sanırım tatlı ama anlamadım der gibi, 

Bir tebessüm belirirdi yüzünde.

Diyarbakır dedim sana ve suskunluk kaplardı beni.

Bilirim birlikteliğimizin kutsallığını, 

Bilirim ayrılacağımızı... Bilirim de suskunlaşırım.

Ölümsüzlük dedikleri aşka ait bir kavram.

Onu da bilirim, suskunluğum ondandır.

Etnik bir sentez yapma çabasıydı birlikteliğimiz.

Biz mi hayalciydik, onlar mı gerçekçi? 

Dost ama mağlup iki el buluştu bir otobüs durağı altında.

Ayrıldık... Bu kentin gözyaşları arasında.

Diyarbakır''da...', 'Seninle olsaydık eğer;  Yani sen ve ben, biz işte. Derin sohbetlere dalardık. Belki ülkeyi kurtaramazdık ama,  En azından sorumlu birer bire...', ARRAY['Türk Edebiyatı','Şiir','Baver Beşer']::text[], 8.5, '{"poet":"Baver Beşer","poet_slug":"baver-beser","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/diyarbakir-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Sevdası', 'bahar-sevdasi-fatih-cinar-t26w6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'bir bahar sevdasıdır gidiyor bende

unnuttum çiçeklerin kokusunu

unuttum gökyüzünün mavisini

ormanların yeşilini

denizlerin o çılgın sesini

rüzgarların o serinleten çehresini

bir bahar sevdasıdır gidiyor bende

ismi bahar amma kış var sanki gözlerinde', 'bir bahar sevdasıdır gidiyor bende unnuttum çiçeklerin kokusunu unuttum gökyüzünün mavisini ormanların yeşilini denizlerin o çılgın sesini r...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/bahar-sevdasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmam Seni', 'unutmam-seni-zeki-gunsan-x7xb7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerim kararsa görmesem seni, 

Hafızam silinse tanımasam kimseyi, 

Ayrılık rüzgarı savursa bizi, 

Kendimi unutsam, unutmam seni.

Kim unutabilir o güzel gözleri, 

Gül dikenli olur, bülbül çileli, 

Hayat ebedidir, ömür süreli, 

Kendimi unutsam, unutmam seni.

Bedenim olsada kara toprak, 

tomurcuk kalsa güllerim açmasa yaprak, 

Ahirette bile arar bulurum seni, 

Kendimi unutsam, unutmam seni

(Eylül - 1996)  (Gaziantep)', 'Gözlerim kararsa görmesem seni,  Hafızam silinse tanımasam kimseyi,  Ayrılık rüzgarı savursa bizi,  Kendimi unutsam, unutmam seni. Kim unuta...', ARRAY['Türk Edebiyatı','Şiir','Zeki Günsan']::text[], 8.5, '{"poet":"Zeki Günsan","poet_slug":"zeki-gunsan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/unutmam-seni-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cesaretin Varsa', 'cesaretin-varsa-fatih-cinar-j4mtb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'cesaretin varsa gel yanıma

aşkı yaşayalım sessiz sedasız

kıyıya vuran hırçın dalgalara inat

sevda denizine girelim zamansız

cesaretin varsa tut ellerimi

yanalım seninle kor ateşlerde

cesaretin varsa sar bedenimi

kül olalım seninle mavi gecelerde

cesaretin varsa gel yanıma

yüreğine gömüp dinmez acını

kimse görmesin sakla gözyaşlarını

takalım başımıza mutluluk tacını

cesaretin varsa unut eski aşkları

yeni bir aşk yaratalım biz kendimize

cesaretin varsa yırt eski mektupları

yeniden yazalım biz onları hece hece', 'cesaretin varsa gel yanıma aşkı yaşayalım sessiz sedasız kıyıya vuran hırçın dalgalara inat sevda denizine girelim zamansız cesaretin varsa ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/cesaretin-varsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eskici', 'eskici-fatih-cinar-n8dap', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'eskici geldi eskici

ben bir eskiciyim

eski yeni farketmez

bütün kederlerinizi verin bana

yerine mutluluk vereyim

mandal misali

gönül ipinize mandallayın mutlulukları

hiç bir rüzgarda düşmemecesine

eskici geldi eskici

ben bir eskiciyim

eski yeni fark etmez

bütün üzüntülerinizi verin bana

yerine sevinç vereyim

tas misali

içi silme neşe dolu

eskici geldi eskici

ben bişr eskiciyim

bende herşey bedava

keder getirin mutluluk alın

üzüntü getirin sevinç alın

kahpelik getirin dostluk alın

nasıl olsa mutluluk haram bana', 'eskici geldi eskici ben bir eskiciyim eski yeni farketmez bütün kederlerinizi verin bana yerine mutluluk vereyim mandal misali gönül ipinize...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/eskici-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trabzonda Üç Güzel', 'trabzonda-uc-guzel-fatih-cinar-5h0l6', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'trabzonun içinde

bir garip viraneyim

üç tane güzel sevdim

hepsine divaneyim

trabzonda akçaabat

bendemiydi kabahat

üç tane güzel sevdim diye

herkes eder nasihat

trabzonun sürmenesi

mavi gözlerin sürmesi

yaralıyor gönlümü

üç güzelin cilvesi

trabzonda vakfıkebir

gönül gezer sefil sefil

çok sevdiğim üç güzel

mektubuma belki gelir

trabzonda çarşıbaşı

hasret çeker gönül taşı

o sevdiğim üç güzel 

akıtır bana gözyaşı

trabzonun beşikdüzü

gönül yaşar hep güzü

üç güzelin üçüde

hem gül sever hem sümbülü

trabzonda var bir of

dilim çeker hep of of

dostlarım anlamaz beni 

hepsininde gönlü kof', 'trabzonun içinde bir garip viraneyim üç tane güzel sevdim hepsine divaneyim trabzonda akçaabat bendemiydi kabahat üç tane güzel sevdim diye ...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/trabzonda-uc-guzel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deniz', 'deniz-nesimi-kecelioglu-py7uf', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Su çırılçıplak tı o akşam

oysa Deniz parka giymişti.

Asker dört yanıbaşın daydı; 

ama siz

bikini arayan bir deniz kızı arıyordunuz', 'Su çırılçıplak tı o akşam oysa Deniz parka giymişti. Asker dört yanıbaşın daydı;  ama siz bikini arayan bir deniz kızı arıyordunuz...', ARRAY['Türk Edebiyatı','Şiir','Nesimi Keçelioğlu']::text[], 8.5, '{"poet":"Nesimi Keçelioğlu","poet_slug":"nesimi-kecelioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/deniz-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dün Bu Gün', 'dun-bu-gun-nesimi-kecelioglu-rja79', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kimi olduk suçlu gibi görüldük, 

Kimi olduk çarmıhlara gerildik.

Bre zalim yüzülse de derimiz; 

Üç beş öldük biner geri dirildik..', 'Kimi olduk suçlu gibi görüldük,  Kimi olduk çarmıhlara gerildik. Bre zalim yüzülse de derimiz;  Üç beş öldük biner geri dirildik.....', ARRAY['Türk Edebiyatı','Şiir','Nesimi Keçelioğlu']::text[], 8.5, '{"poet":"Nesimi Keçelioğlu","poet_slug":"nesimi-kecelioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dun-bu-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakarya''da', 'sakarya-da-nesimi-kecelioglu-3pela', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kulağında halka küpe, 

Saçını bağlamış ipe, 

Sosyalist geçinen züppe, 

Sakar yada yalancılar..', 'Kulağında halka küpe,  Saçını bağlamış ipe,  Sosyalist geçinen züppe,  Sakar yada yalancılar.....', ARRAY['Türk Edebiyatı','Şiir','Nesimi Keçelioğlu']::text[], 8.5, '{"poet":"Nesimi Keçelioğlu","poet_slug":"nesimi-kecelioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sakarya-da-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Sağol', 'sen-sagol-nesimi-kecelioglu-eyj9q', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir zaman bu gönül sana tapandı, 

Uğrunda her şeyi şartsız yapandı, 

Hicran mektubunun zarfı kapandı, 

Cevrinle pullandı sen sağol.......', 'Bir zaman bu gönül sana tapandı,  Uğrunda her şeyi şartsız yapandı,  Hicran mektubunun zarfı kapandı,  Cevrinle pullandı sen sağol..........', ARRAY['Türk Edebiyatı','Şiir','Nesimi Keçelioğlu']::text[], 8.5, '{"poet":"Nesimi Keçelioğlu","poet_slug":"nesimi-kecelioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-sagol-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek Ölmektir', 'sevmek-olmektir-emin-uyguner-bo7du', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Benim sevdigimin yüzü

gecedeki yıldızdan da parlak ama, 

gecekadarda kara kaşlı, siyah saçlı 

birde ceylan bakışlı 

         

           benim sevdigim leyla gibi

           tek farkı mecnunu görmedi

sevmek sevdigi için ölmektir

ölmek acıları dindirmektir

ölmenin en acı yanı ise sevgilinin 

gülüm seyişini gözlerini özlemetir 

ölmenin en acı yanı

ceylan bakışlıyı bir daha görememektir

sevmek sevdigi için kana bulanan

kalbininin içinde sevgiliyi bula bilmektir  en  sevgili', 'Benim sevdigimin yüzü gecedeki yıldızdan da parlak ama,  gecekadarda kara kaşlı, siyah saçlı  birde ceylan bakışlı                       ben...', ARRAY['Türk Edebiyatı','Şiir','Emin Uyguner']::text[], 8.5, '{"poet":"Emin Uyguner","poet_slug":"emin-uyguner","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/sevmek-olmektir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretimin Cenazesi.', 'hasretimin-cenazesi-cengiz-yazici-1a827', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Özledim seni.Özlemlerim hasretim olurdu.

Eski günleri anar, gözlerim arar.Dolardı.

Bulamazdım bazen gökyüzünde yıldızdın.

Gönlümde yaldızdın.Ama ben yanlızdım.

Hayaller kurardım, Ellerinden tutar koşardım, 

Mektuplarından, ben bir dünya kurardım.

Attığın kartlardan, ağaçlar gökyüzü yapardım.

Öyle büyürdünki, gönlümde sana taht kurardım.

Dinle bak.Bu ses can çekişen birinin sesi, 

Belki konuşamaz, birdaha yetmez.Bu nefesi.

Olmaz aslında; kimin olurki böyle gidesi, 

Bu gün cenazemiz var.-Dostlar sağ olsun...

Cenazemizin adı...! 

HASRETİMİN CENAZESİ...', 'Özledim seni.Özlemlerim hasretim olurdu. Eski günleri anar, gözlerim arar.Dolardı. Bulamazdım bazen gökyüzünde yıldızdın. Gönlümde yaldızdın...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hasretimin-cenazesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Yürüyorum.Gece Ölüyorum.', 'sana-yuruyorum-gece-oluyorum-cengiz-yazici-f06o1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Renk renk şehrin ışıkları, 

Gecemi gündüzmü belli değil? 

Vakit bile kendinden geçmiş, umrunda değil.

Renk renk kırların çiçekleri, 

Baharmı Hazanmı belli değil? 

Mevsimler bile karışmış umrunda değil.

Nispet yapıyorlar sanki birbirlerine, 

Biri açar.Diğeri ona inat yanar...

Şu sarı yananmı sensin.Yoksa beyaz açanmı? 

Leylak kokanmı sensin.Yoksa mavi yakanmı.

Hangi dağdasın.Hangi caddedesin bir bilsem? 

Ölüm toprağını delen yoksa Kardelen mi? 

Şenim mutluyum çünkü bugün bir çocuğum.

Elimdeki dondurmama, tekme atıyorum.

Işıkları kokluyorum Çiçeklere bakıyorum, 

_Yoksun kendime geliyorum.Korkuyorum...

Sana yürürken; ben bu GECE ÖLÜYORUM...', 'Renk renk şehrin ışıkları,  Gecemi gündüzmü belli değil?  Vakit bile kendinden geçmiş, umrunda değil. Renk renk kırların çiçekleri,  Baharmı...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/sana-yuruyorum-gece-oluyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-cengiz-yazici-do0v0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Şu up uzun giden ve dağları aşan yol, 

Her kesi birbiriyle buluşturur.

Ben sıramı beklerim, olsamda en son, 

Belki bir gün benide, sana kavuşturur.

Hışımla dağlardan inen, azgın ırmak, 

Denize hasrettir.Dileği onunla kavuşmak.

Kimse bilmez ondaki, aşkı sevdayı, 

Hasretinin arzusu, özlem zincirlerini kırmak.

Yazın gelmesini sabırla bekleyen, dağdaki kar, 

Yaz gelmeli çünkü, ırmakla randevusu var.

Her ne kadar engel olsada ona sonbahar, 

Mevsimlere hükmeden, güneş gibi bir güç var.

Benim sana sevdam kara, kapkara bir kış olmuş

Göz gözü görmez, duygularım tipilerde donmuş, 

Çıkmışım bir kez, dönüşü olmayan yol olmuş, 

Bu yürek, hasret, özlem, İllede sen, sen Dolmuş.', 'Şu up uzun giden ve dağları aşan yol,  Her kesi birbiriyle buluşturur. Ben sıramı beklerim, olsamda en son,  Belki bir gün benide, sana kavu...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/hasret-36-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Düğün Bayram Var Bugün.', 'dugun-bayram-var-bugun-cengiz-yazici-pyg3n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün, düğün var.Bugün bayram var.

Agop içkiler benden, kim ne isterse ver.

İçmeyenlere ısrar etme sakın, ayıp olur.

Sana zahmet, sadece huniyle döküver.

Hey! sen davulcu.Vur tokmağı ölümüne vur.

Vur patlasın çal oynasın.Sen gene gene vur.

Dön şöyle, zurnanın inceden havasıyla, 

Çal davulcum, çal zurnacım.Oynayanları savur.

Çocuklar: sizede bayram var bugün.

Çekin maytapları, ateşleyin fitilleri, 

Patlasın mantarlar.Çatlatın çatapatları.

Uçurun füzeleri, Delik deşik edin gökleri.

Bugün trafik durmalı.Sular akmamalı, 

Ay görünmemeli, Güneş hiç doğmamalı.

Yaz kış olmalı.Ekim, Cumadan sonra gelmeli, 

Gece, gündüz olmalı.Hatta hiç olmamalı.

Bugün enflasyon 0 olmalı, 

Yada benden fazla canavarlaşmalı.

Kadınlar kahvede okey oynamalı, 

Gerekirse erkekler bu gün çocuk doğurmalı.

Kuşlar, öc alıp sapanla çocuk vurmalı, 

Balıklar ağ atıp, denizden balıkçı çekmeli.

Sebzeler, meyveler işbirliği yapmalı, 

İntikamları acı olmalı, pazarcıları satmalı.

Ne varsa yer yüzünde.yerin dibinde olmalı, 

Irmaklar dağbaşlarına tersine akmalı.

Dorukta karlar değil okyanuslar olmalı, 

Kuzuların yerine, bu kez çobanlar otlamalı.

Bugün herşey allak bullak saçma sapan olmalı, 

Çünkü; bugün bayram var.

Çünkü; bugün düğün var.

Şükürler olsun.Çünkü Bugün DUALARIN KABULÜ VAR...', 'Bugün, düğün var.Bugün bayram var. Agop içkiler benden, kim ne isterse ver. İçmeyenlere ısrar etme sakın, ayıp olur. Sana zahmet, sadece hun...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/dugun-bayram-var-bugun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çileli.', 'cileli-cengiz-yazici-xshw0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ben, bitmeyen çilelerin dert çeken adamıyım.

Ben, sabahsız gecelerin doğmayan yıldızı, 

Ben, zehir sunan şişelerin bir kadeh şarabı, 

Ben, yarım kalmış aşkların adamıyım.

Güle tutkun bülbüllerin, 

Özlem dolu yüreklerin, 

Aşka hasret gönüllerin, 

Yorgun düşen adamıyım.

Ben, ümitsiz bekleyişlerin, 

Ben, rezilce ölümlerin, 

Durmadan yükselen acı feryatların, 

Sesi duyulamayan, ''''GARİP ADAMIYIM''''.', 'Ben, bitmeyen çilelerin dert çeken adamıyım. Ben, sabahsız gecelerin doğmayan yıldızı,  Ben, zehir sunan şişelerin bir kadeh şarabı,  Ben, y...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/cileli-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsyankar.', 'i-syankar-cengiz-yazici-i4wtx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düğününde ağladım, 

Çekildim bir köşeye.

Elveda ey sevgilim, 

Bunca süren herşeye.

Ben her zaman ağlarım.

Üzülme! dilerim sen mutlu ol.

Minik serçeler gibi, 

Kendine bir yuva kur.

Köşelerde ağladım, 

Çekildim bir köşeye.

Elveda sevgilim, elveda

Bunca süren herşeye.', 'Düğününde ağladım,  Çekildim bir köşeye. Elveda ey sevgilim,  Bunca süren herşeye. Ben her zaman ağlarım. Üzülme! dilerim sen mutlu ol. Mini...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/isyankar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalbimin Sahibine', 'kalbimin-sahibine-cengiz-yazici-9dl2w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün seni unutmakmı? 

Asla Bıcırık.

Seni ölünceye kadar seveceğim.

Hayat boyu hayallerimi süsleyeceksin.

Mutlu günlerimin geleceği olacaksın.

Çünkü seninle öğrendim ben yaşamayı, 

Bir gün seni unutmakmı? 

Asla Bıcırık.

Benliğim oldukça kalbimde yaşayacaksın.

Bir gün ölürsem, 

Sevdiğine hasret giden, 

Mecnun diyecekler ardımdan.

Ben ölürsem, 

Bedenim, yok olacak elbette.

Ama sana olan sevgim, sana olan sadakatim, 

Mahşerde bile benimle olacak.

Ben, bu dünyada yaşadıkça, 

Sende, sevginde yüreğimde yaşayacak.

Seni unutmakmı? 

Asla Bıcırık.

Çünkü ben seni...

''''UNUTMAK İÇİN SEVMEDİM''''', 'Bir gün seni unutmakmı?  Asla Bıcırık. Seni ölünceye kadar seveceğim. Hayat boyu hayallerimi süsleyeceksin. Mutlu günlerimin geleceği olacak...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/kalbimin-sahibine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Öğrettin.', 'sen-ogrettin-cengiz-yazici-511k7', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Öyle masum, öyle temizdiki yüreğim, 

Varlığından bi haberdi gönlüm.Mutluydum.

Sonra seni gördüm tanıdım, 

Bana sevmeyi öğrettin.

Özleminle yaşadım gün boyu.

Bağlanmayı öğrettin.

Kaleme sarıldım şiirler yazdım adına, 

Seni sordum sokaklara kaldırımlara, 

Ağlamayı öğrettin.

Çok güzeldi gözlerin, 

Kelimelerle dile gelmiyordu güzelliğin.

Erişemiyordu ellerim sana, 

Sonunda acizliği öğrettin.

Susmayı, çaresizliği, kahretmeyi, 

Sen öğrettin bana kara kara düşünmeyi.

Duygularımla alay ettin.Ağladım.

Hayallerim yıkıldı.Sabrettim.

Unuturum dedim.Başaramadım.

Öyle uysaldı ki gönlüm, 

İsyanı öğrettin.

Vel hasıl, her şeyi öğrettinde bana, 

Unut beni dedinde...

Unutmayı öğretmedin.Neden, Neden.NEDEN: NEDENN! ! !', 'Öyle masum, öyle temizdiki yüreğim,  Varlığından bi haberdi gönlüm.Mutluydum. Sonra seni gördüm tanıdım,  Bana sevmeyi öğrettin. Özleminle y...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/sen-ogrettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutmayı bilirim. 48-', 'unutmayi-bilirim-48-cengiz-yazici-13nk1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben seni nasıl sevdiysem, 

Unutmasınıda bilirim.

Çöksede üzerime karabulut gibi hasretin, 

Ağlasada gözlerim, 

Kan çanağı olsada, yokluğuna, 

Sen istediğin kadar''''Seviyor''''de.

Gururum aşkımdan üstün gelir.

Çivi çiviyi, söker misali, 

Seni, içimden silerim.

Ben seni nasıl kazandıysam, 

Kaybetmesinide bilirim.

Tek başıma kalsam dünyada.

Boğulsam böylesine yanlızlığınla, 

Sen istediğin kadar dalga geç.Alay et.

Dedim ya! gururum her şeyden üste gelir, 

Gözlerimden akan yaş misali, 

''''Damla damla''''eritirim seni.', 'Ben seni nasıl sevdiysem,  Unutmasınıda bilirim. Çöksede üzerime karabulut gibi hasretin,  Ağlasada gözlerim,  Kan çanağı olsada, yokluğuna,...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/unutmayi-bilirim-48-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Baş Koyanlardanız.', 'bas-koyanlardaniz-cengiz-yazici-k0mbh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kulak ver sesime dinle arkadaş, 

Bu dostluk ile dost olanlardanız.

Dünyanın öbür ucunda olsanız, 

Arkadaş halini soranlardanız.

Gülüm! Arkadaşını çok iyi tanı.

Zindanda olsa dünyanın her bir yanı, 

Allah''ın verdiği bu kutsal canı, 

Arkadaş için verenlerdeniz.

Memleketimiz aynı, ilçemiz mekez, 

Arkadaşlığa, önem vermeli herkes, 

Ölümlü dünyaya gelmişiz bir kez, 

Kanını arkadaş için dökenlerdeniz.

Adım adım, beraber olduğum, 

Sensiz aç kalıp, beraber doyduğum, 

Derdimi açıp, derman bulduğum, 

Arkadaş için baş koyanlardanız.', 'Kulak ver sesime dinle arkadaş,  Bu dostluk ile dost olanlardanız. Dünyanın öbür ucunda olsanız,  Arkadaş halini soranlardanız. Gülüm! Arkad...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bas-koyanlardaniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Allah Affetsin.', 'allah-affetsin-cengiz-yazici-qe4yv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırladınmı? 

Söylediğin yalanları.

O yalanlarla, 

Oynadığın duyguları.

Bak şimdi herşey açıkta, 

Yine kaldın, vijdanınla başbaşa.

Doğrular, yine senden uzak, 

Boşa çıktı, kurduğun tuzak.

Sana, teşekkür borçluyum aslında, 

Gerçek bir aşk buldurdun, bir anlamda.

Her şeyinle sahtenin tekisin, 

Geçmeyen sahte bir senet gibisin.

Başındaki peruğun, 

Tırnaklarında boyan, 

Gözlerindeki lenslerin, 

Ve yapmacık bakışların, 

Sahteydi sözlerin...

Kullandığım dişler gibi, 

Protez di sevgilerin.

Sana, bela bile HAK değil, 

Seni Allah affetsin ben değil.', 'Hatırladınmı?  Söylediğin yalanları. O yalanlarla,  Oynadığın duyguları. Bak şimdi herşey açıkta,  Yine kaldın, vijdanınla başbaşa. Doğrular...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/allah-affetsin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O nun İçin Öleceğim.', 'o-nun-i-cin-olecegim-cengiz-yazici-0yxri', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Herşeyimi aldın, elimden, 

Ama unuttuğun bir şey kaldı, 

Şükredeceğim.

Değilmi ki? ''''Mal sahibi, mülk sahibi, 

Hani nerde bunun ilk Sahibi.''''

Sabredeceğim.

Seninle hiç işim olmadıki benim, 

Unuttuğundu benim''''Meleğim'''', 

Dua edeceğim.

Namerdim kılına dokundurtmam, 

Gerekirse, icabı varsa, 

O''nun yerine, İbadet edeceğim...

O''nun için öleceğim.', 'Herşeyimi aldın, elimden,  Ama unuttuğun bir şey kaldı,  Şükredeceğim. Değilmi ki? ''''Mal sahibi, mülk sahibi,  Hani nerde bunun ilk Sahibi.''...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/o-nun-icin-olecegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklambaç Oynayalım.', 'saklambac-oynayalim-cengiz-yazici-l8yse', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gel bu gece zincirleri kıralım, 

Gel seninle, tüm yasakları delelim.

Önce güzel bir masa kuralım, 

Gel bugün, dünyanın anasını satalım.

Bize ne, olsun dosttan düşmandan, 

Bize ne, dönmüyorsa dünyadan.

Biz içelim, güzelim sevişelim, 

Pembe hayaller kuralım, bulutlara çıkalım.

Kadehlerimiz bir insin, bir kalksın.

Birinden şarap, birinden rakı aksın.

Sevişelim senle sabaha kadar, 

Bedenimiz, kanter içinde kalsın, yapışsın.

Sonra ayılalım, kendimize gelelim, 

Birbirimize, bakıp bakıp gülelim.

Aç karnına banyoda bir duş alalım, 

Birden sular kesilsin, öylece kalalım.

Aklımıza ne gelirse onu yapalım.

Gel, ortalığı bir güzel karıştıralım.

Millet ayaklansın bizi arasın, 

Bulamasınlar bizi, Saklambaç oynayalım...', 'Gel bu gece zincirleri kıralım,  Gel seninle, tüm yasakları delelim. Önce güzel bir masa kuralım,  Gel bugün, dünyanın anasını satalım. Bize...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/saklambac-oynayalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekle Beni Küçüğüm.', 'bekle-beni-kucugum-cengiz-yazici-kx8w8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Biliyormusun? 

Hep seni düşünüyorum.

Biliyorsun, adım gibi eminim.

Kısa kalıyorsun bana, 

Bu aralar seni arayamıyorum.

Anlatmıştım ya sana, 

Çaresizlik işte, 

Ama senden haberler geliyor bana.

Benim kadar olmasada, 

Beni düşündüğünü, 

Biliyorum.

Biliyormusun..? 

Merak etme beni, 

Yine, eskisi gibiyim.

Sağlığım yerine geliyor, 

Kısacası o dert bitiyor, 

Yarın yine kontrol var.

Yani, yine ilaç, 

Yine kan, kokulu ortamdayım.

Kızıyorum.

Ses kokunu, unuturmuyum...

Baya uzun zaman oldu değilmi, 

Görüşmeyeli, konuşmayalı, 

Mektuplaşmayalı da? 

Sen, hala rüyalarımdasın.

Sana geliyorum her gece, 

Bakıyorum pencerenden, 

Uyuyorsun.Kıyamıyorum, 

Öpüyorum, dönüyorum.

Düşünüyorum...

Baya uzun zaman oldu değilmi, 

Koklaşmayalı da? 

Bekle beni küçüğüm, 

Bekle beni geleceğim.

Gelsede dertler bir bir üstüme, 

Bertaraf edeceğim.

Belki yarın değil ama, 

Bir gün mutlaka, ama mutlaka, 

Döneceğim.', 'Biliyormusun?  Hep seni düşünüyorum. Biliyorsun, adım gibi eminim. Kısa kalıyorsun bana,  Bu aralar seni arayamıyorum. Anlatmıştım ya sana, ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/bekle-beni-kucugum-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yakamı Bırak.', 'yakami-birak-cengiz-yazici-pbg38', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ateş üstünde yürüyorum sanırdım, 

Buz üstünde yürüyormuşum meğer.

Seni gördüm tanıdım ya, 

Giydiğim ateşten gömlekmiş meğer.

Bu can, yıllar boyu kurşunlar yemiş, 

Acılara alışmış, delik deşik olmuş.

Sonra seni düşünmüşüm gün boyu, 

Sevdan, yıllara bedel olmuş.

Masamda, sönmeye yüz tutmuş, 

Üşüyen cigaram.

Bağrımda, bitti bitecek ciğerim, 

Bitsede ciğerim, üşüsede cigaram, 

Yitip gitmiş, sensiz geçen ömrüm.

Karlı havada ayaklarım çıplak, 

Yürüyorum ben, sana yalın ayak.

Kar, tipi, tufan, fırtına, rüzgar, 

O''nun olmalıyım, 

Kader.Yeter artık yakamı bırak.', 'Ateş üstünde yürüyorum sanırdım,  Buz üstünde yürüyormuşum meğer. Seni gördüm tanıdım ya,  Giydiğim ateşten gömlekmiş meğer. Bu can, yıllar ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yakami-birak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahlardayım.', 'gunahlardayim-cengiz-yazici-sjm7v', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Affet Allah''ım, ne olur beni, 

Farkında olmadan günahlardayım.

O''na olan sevgim değişti, 

Kızıyorum kendime isyanlardayım.

Yaptığım ibadetlerde bile şimdi ben, 

Biliyorum artık bir günahkarım.

Dualarım kabul olmazmı? bilmem, 

Tövbe etsemde, haramlardayım.', 'Affet Allah''ım, ne olur beni,  Farkında olmadan günahlardayım. O''na olan sevgim değişti,  Kızıyorum kendime isyanlardayım. Yaptığım ibadetle...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gunahlardayim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bay Kapris', 'bay-kapris-cengiz-yazici-xmu7f', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir dostum var, Ahiret''liğim benim, 

Bende onun ''''Bay Kapris''''iyim.

Bu adı o takmış, kafasına göre bana, 

Asıl kapris kendisi, birde bunu anlasa.

Adı, Aysun.Niçki, Çimen.

Memleketi, Çorum.Mesleği öğretmen.

Özeline arkadaş gider, konuşmak ister, 

Onada kapris yapar, ters gider.

Herkesle dost, arkadaş olur.

Herkeste kalkar, buna aşık olur.

Karıştırır bazen konuları, çıkmaza girer, 

Nasılsa Bay Kapris''i var.O derdini dinler.

Hiç yalanı yoktur, dosdoğrudur, 

Birde Nadiş''i var.O''nun uğurudur.

Hatta beraber tatile gittiler, 

Yalan yok.Hava yağmurluydu, geri döndüler.

Bazen oturur, mangal yakarız balkonda, 

Beraber masa kurar, yemek yeriz sofrada, 

Bazen rakı açar, bira içer şarkı söyleriz, 

Ben, İst''te.O, D.Dakırda, 

Seslerimiz birleşir ya Sinop''ta, ya Çorumda.', 'Bir dostum var, Ahiret''liğim benim,  Bende onun ''''Bay Kapris''''iyim. Bu adı o takmış, kafasına göre bana,  Asıl kapris kendisi, birde bunu an...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bay-kapris-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varsın Olsun.', 'varsin-olsun-cengiz-yazici-stjiz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir karar vermiştik.

Birbirimiziniz demiştik

Karardan öte yeminler etmiştik.

Birbirimizi sevmiştik.

Şimdi ne oldu böyle bize, 

Yazıkmı oldu sevgimize.

Her şey yalanmı yani şimdi, 

Gerek yokmu başka söze.

Seni bilmem ama ben sözümdeyim, 

Çünkü ben hala kendi özümdeyim.

Yalanla işim olmadı hiç hayatta, 

Bir seninle birde içimdeyim.

Varsın olsun, sen olmasanda olur, 

Bana senin hayalin yeter.

Bir gün olur bu dertte biter

O eski günler hala burnumda tüter', 'Bir karar vermiştik. Birbirimiziniz demiştik Karardan öte yeminler etmiştik. Birbirimizi sevmiştik. Şimdi ne oldu böyle bize,  Yazıkmı oldu ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/varsin-olsun-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelde Anlat Anlayan Çıkarsa', 'gelde-anlat-anlayan-cikarsa-cengiz-yazici-zwq9l', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çözebilmek mümkünmü, kördüğüm olmuşuz, 

Kurtulabilmek mümkünmü, tutsak olmuşuz, 

Göz yaşı olmuş, pınarlarda kurumuşuz, 

Gelde anlat bu aşkı, anlayan çıkarsa.

Yağmurlar gibi, damla damla olmuşuz, 

Kah tarlaya, kah, okyanusa yağmışız, 

Buharlaşmışız, bulutlarda buluşmuşuz

Gelde anlat bu aşkı, anlayan çıkarsa.

Yetmemişiz, bir çift gözde buluşmuşuz, 

Değmemiş ellerimiz birbirine, ağlamışız, 

Süzülüp yanaktan, dudakta birleşmişiz, 

Gelde anlat bu aşkı, anlayan çıkarsa.

Dinleyin, bu konuda biz yemin ettik, 

Yeminlerden öte, hep dualar ettik, 

El açtık Allah''a Dualar ettik, Amin dedik, 

Gelde anlat bu aşkı, anlayan çıkarsa.

Hala anlamadıysanız, anlamazsınız, 

Biri çıkıp, başınıza vura vura anlatsa..', 'Çözebilmek mümkünmü, kördüğüm olmuşuz,  Kurtulabilmek mümkünmü, tutsak olmuşuz,  Göz yaşı olmuş, pınarlarda kurumuşuz,  Gelde anlat bu aşkı,...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gelde-anlat-anlayan-cikarsa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'En Kutsal Sayılan Elçi', 'en-kutsal-sayilan-elci-cengiz-yazici-njxo6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gün, aşkına edersem ihanet, 

Ve, sende bunu duyarsan şayet, 

Olsada bunun adı, gerçekten gaflet, 

Üzülme, o an gider bendeki bu emanet.

Bu sevda, başlamadıki daha bitsin, gerçi, 

Sana, yalanda gelebilir bu sözler, belki, 

Daha küçük bir fidansın, birgün anlarsın

Buna şahit olsun, en kutsal sayılan elçi, 

Geceler arkadaşımdır, ben onda ağlarım, 

O beni, bende onu, çok iyi tanır anlarım, 

Gök, dayanamaz halimize oda bize ağlar, 

Aramızda, gözden gönüle bir yol var.

Bu sevda, başlamadıki daha bitsin, gerçi, 

Sana yalanda gelebilir bu sözler, belki, 

Daha küçük bir fidansın, birgün anlarsın

Buna şahit olsun.EN KUTSAL SAYILAN ELÇİ...', 'Bir gün, aşkına edersem ihanet,  Ve, sende bunu duyarsan şayet,  Olsada bunun adı, gerçekten gaflet,  Üzülme, o an gider bendeki bu emanet. ...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/en-kutsal-sayilan-elci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ya Seninle Ya Sensiz.', 'ya-seninle-ya-sensiz-cengiz-yazici-b96sq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aklım, yüreğimle nikah kıydı sen doğdun, 

Senden öncesi yoktu ki, sonrası olsun.

Yalanı olan, bu yolda çalı olsun, kurusun, 

Hatta bu can ölsün, çürüsün toprak olsun.

Bu gün, seninleyim ben, bak yine, 

Yine rüyalardayız, dizdize, gözgöze.

Kimse el süremez, kimse nazar edemez, 

Kutsal dediğimiz, kutsaldan öte sevgimize. 

Ah! der.Bazen yürek, taa derinlerden, 

Ah ki ne ah, ahlardan öte, vah derdinden.

Keşke önce doğsaydım, yada sen sonra, 

Veyahutta, beraber başka bir hayatta.', 'Aklım, yüreğimle nikah kıydı sen doğdun,  Senden öncesi yoktu ki, sonrası olsun. Yalanı olan, bu yolda çalı olsun, kurusun,  Hatta bu can öl...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Yazıcı']::text[], 8.5, '{"poet":"Cengiz Yazıcı","poet_slug":"cengiz-yazici","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ya-seninle-ya-sensiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bakirkoyden Mektup Var', 'bakirkoyden-mektup-var-helin-kaya-hdmmz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sensizdim, kendime bir is aradim

Bastan savip asabimi bozdular

Hatirsinas dostlarima ugradim

Sag olsunlar, Müdür neye yazdilar.....

Müdür bey gerçekten yufka yürekmis

Isim insaatta kazma, kürekmis

Bir saglik raporu almam gerekmis

Tam tesekkül hastaneye yazdilar.....

Yagisli gözümün hazan çaginda

Olur olmaz yerde baslar agida

Sinir servisine giden kagida, 

‘Aklindan zoru var’ diye yazdilar.....

Bir saat anlattim, bir tek buseni

Doktorlar efsane sandilar seni

Belki alaya aldilar beni

Belki palavraci diye kizdilar.....

Bir ara sensizlik krizim tuttu

Bilmem ki o anda ne olup bitti, 

Hekimler heyeti havale etti

Acil vaka Bakirköy’e yazdilar.....

Bu çagda bu sevda abes dediler

Cezasi çelikten kafes dediler

Ben kime ne yaptim, ne istediler

Bana bu çukuru niye kazdilar.....

Açmak için zahmet etme zarf açik, 

Hala bana sevgin varsa birazcik

Mektubumu alir almaz yola çik, 

Gözyaslarim bir acayip azdilar..................', 'Sensizdim, kendime bir is aradim Bastan savip asabimi bozdular Hatirsinas dostlarima ugradim Sag olsunlar, Müdür neye yazdilar..... Müdür be...', ARRAY['Türk Edebiyatı','Şiir','Helin Kaya']::text[], 8.5, '{"poet":"Helin Kaya","poet_slug":"helin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bakirkoyden-mektup-var-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Filiz', 'filiz-helin-kaya-399jg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Filiz filiz parelendim dallara uymak için

Kan gölünde kurulandım hayatı duymak için

Kavgalara kuyulandım sabaha varmak için

Kekik kokusu duydum, kekik kokusu koynunda huysuz gecenin

Uyandım birden bire

Haydi dedim, yüreğim gidelim bu şehirden 

Bu şehir koparmak istiyor beni özlemlerinden

Yorgunum 

Çünkü yorgunluğumun yaşamak gibi bir anlamı var

Yinede yaşamaktan duyduğum mutluluğun tadına, düşmanlarım ulaşamazlar

Katarlar gelir geçer bir geceden bir geceye

Yüreğim yare yare iz bırakır bin acıya

Gün olur şafaklanır karanlıklar bin parçaya

Denizlerde dalgalandım taşları uymak için

Doruklara sevdalandım ışığa doymak için

Irmaklarda durulandım dağları duymak için

Bir kuş çiz yavrum yüzüme gözyaşınla

Bir kuş, tel tel kirpiklerin kanat olsun

Bir kuş, çırpınan kalbi dudağında

Bir kuş yavrum, sıcaklığın beni bulsun

Bahar gelmiş balam benim

Bahar gelmiş dayanmış

Dalda yaprak bebeciğim, suda köpük uyanmış

Kuzulara özenmiş kızım benim

Körpe sesler dinlermiş

Ay ışığında yanmış yavrucuğum 

Onun için beyazmış.........

Şarkılar gelir geçer bir heceden bir heceye

Yüreğim yare yare yankılanır bin acıya

Gün olur ufalanır karanlıklar bin parçaya

Gün olur ufalanır karanlıklar bin parçaya...........................', 'Filiz filiz parelendim dallara uymak için Kan gölünde kurulandım hayatı duymak için Kavgalara kuyulandım sabaha varmak için Kekik kokusu duy...', ARRAY['Türk Edebiyatı','Şiir','Helin Kaya']::text[], 8.5, '{"poet":"Helin Kaya","poet_slug":"helin-kaya","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/filiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüme Bir Kala', 'olume-bir-kala-umut-aygun-wbnmu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gümüşi semanın esrar perdesi, 

Düş gibi gördüğüm gündüz ve gecesi, 

Zikrediyor boşluk, semada malikini, 

Bildim, fikrin edep oluş muhasebesini, 

Çıkmazdayım, altın kaplı dört duvar arasında, 

Zamanı verin geriye kalan tek uzun yolda, 

Kölesi olmuşum nefsin, edemiyorum azad da, 

Yarım sıfır, yarım sıfırın altında

Gör ey ama, gerçek aleni cihanda, 

Gösterin varmı kalan bu mekanda, 

Kabri idam ettiğin bir anda, 

Kayıpsın varla yok arasında, 

Sen bir ney''sin çalana göre değişirsin, 

Ötesinde bildiğim dört mevsim gibi dönersin, 

Zaman gittikçe sınırlı doğrultusunda, 

Oyunun son perdesinegelir sıra, 

Oyunu değil, oyuncuyu görmenin ısrarıyla, 

Uzun bir nida duyulur, işte o anda, 

Ne oyun kalır, ne oyuncu meydanda, 

Bir varlık düşün, düşün ki; esir, 

Kendi bildiği varlığının altında, 

Benim dediğin sana sahip sanatkar varda, 

Mührü kalbinin sol üst yanında, 

Ölüm labirent, baştan sona bulmaca, 

Korku içimde meydanlarca, 

Bu korkuyla, nokta nokta sona yaklaştıkça, 

Hayal görmekteyim, ruhum yüce huzurda, 

Ve geride kalan bir elbisem bir kimliğim, 

Özlemini çekeceğim bilinen tek gerçeğin, 

Ağlayan anam, neden niçin neyin, 

Ötesinde var olan ne, bana söyleyin, 

Söyleyin bumu gördüğüm rüyamda, 

Ya ölüm düşlendiği her ortamda, 

Esrarlı ürperti, yanlızca o anda, 

Yalanlarla boğulmak neden sonra; 

Böylece erdik, çetin bilmecesine, 

Hem geçmiş zamanın, hem geleceğin, 

Üstadın söylevi, birgün belki bugün, 

Göreceğiz meydanlarda büyük gerçeği....', 'Gümüşi semanın esrar perdesi,  Düş gibi gördüğüm gündüz ve gecesi,  Zikrediyor boşluk, semada malikini,  Bildim, fikrin edep oluş muhasebesi...', ARRAY['Türk Edebiyatı','Şiir','Umut Aygün']::text[], 8.5, '{"poet":"Umut Aygün","poet_slug":"umut-aygun","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/olume-bir-kala-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sancılar', 'sancilar-ahmet-ferit-cosan-4wx9z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sancılar, aymaz bir tavır alırcasına hep apansız düşüyorlar gönlüme

Gönlüm; zaten köklerini tüm hücrelerime salmış

Her daim büyümekte olan bir urun kanlı uzantılarına çoktan teslim olmuş

Aşk diyor kimleri bu hastalığa, 

Sevda diyor.

Oysa yalnızlık demeye kimsenin gücü yetmiyor, 

Korkuyorlar kelimelerden sorumlu tüm devlet büyükleri

Bu gizemli sözcüğü ciğerlerinden havaya pompalamaya.

Gün olur dostlarım

Yalnızlığın o sinsi, gaddar anlamına

''Cinayet'', ''toplukıyım'', ''ölüm'' bile yetişemez

Gün olur beynin yeni günün ışıklarına karşı 

Bir refleksmişçesine sancımaya başlar.

Mutluluk hiçbir zaman bu kadar uzak görünmez insana.

Onbinlerce ışık yılı uzakta parıldayan bir yıldız olur.

Tam gördüm zannederken, araya bir de bulut giriverir.

Gün ortasında tek ışık kaynağı, tüm ölümlülerin yalnızlık dedikleri

Bir ateşböceği kalır yanında.

Yalancı aydınlığında, en iyimser Polyanna''nın bile oynayamayacağı oyunlar oynarsın

Etrafı pırıl pırıl görmekle kalmaz, ısındım sanırsın.

Ve dünyada yine o günde ölümler bir çığlık gibi uzaya savrulur, 

Gözyaşı, bilinmez bir dere olur, geleceğe akar durur.

Sense, etrafı aydınlık zanneden bir soytarı gibi, 

Düşe kalka yürümeye çalışırsın.

Bir sevda ışıltısı ararsın yalnızlığınkini bastıracak.

Ölümler, solan çiçekler misali yitip giden canlar ırgalamaz seni 

Düşünmerzsin hangi düşünce insandaki kini bastıracak

Görmezsin kılıçları ile sahte yunan tanrılarına özenen kimi insanoğlunun 

Para ile insanına kan kusturduğunu.

Yaşarsın, sadece yaşarsın alevden görünmez bir at gözlüğüymüşçesine yalnızlığın

Ruhuna takılı iken.

Bir bitkiden farkın olmadan, kimseye yardım edemeden öylece yaşarsın', 'Sancılar, aymaz bir tavır alırcasına hep apansız düşüyorlar gönlüme Gönlüm; zaten köklerini tüm hücrelerime salmış Her daim büyümekte olan b...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ferit Coşan']::text[], 8.5, '{"poet":"Ahmet Ferit Coşan","poet_slug":"ahmet-ferit-cosan","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sancilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bahar Gelmiş', 'bahar-gelmis-necat-i-ltas-pnb0p', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Memleketimin baharı yok, 

Sadece kışı var.

Tek mevsim; 

Soğuk, 

Karanlık, 

Ve kalleş...

Rüzgar; kinle fırtına olur, 

Tozu dumana katar.

Yağmur kızgın, 

Ya yağmaz, 

Ya da sel olur.

Güneş dargın, 

ekini kurutur, 

Yangına çevirir her yanı.

Toprak sesiz, 

Kahrından ağaçlarını döker, 

Kel bırakır her tarafı, 

Dağı, ovayı, tarlayı...

Emeklerine yanar gökyüzü, 

Mümkün olsa başka yere gidecek.

Kelaynaklar yumurtlamayı bırakmış; 

Geçmişe yanarak, intiharı seçmiş...

Ceylan suya inmez olmuş, 

Ortalık yılana, çıyana, akrebe kalmış.

Nerede o mert insanlarım, 

Nerede o bolluk, bereket diyarı, 

Nerede o taşın şiire dönüştüğü yer, 

Nerede? 

İnsanlar aç, sefil, 

Köyü elinden alınmış, 

Şunlar veya bunlar tarafından yakılmış, 

Ne fark eder..

Sonuç, 

toprağından kopmuş, 

İstikameti, zamanı belirsiz, 

Gönülsüz bir göç başlamış, 

Şurada burada eğreti yerleşmiş, 

Bir göz oda, on nüfus, 

Şehirleri bombaya çevirmiş, 

Birgün çöpten, 

Birgün başka yerden ekmek almış, 

Nereye ve ne zamana kadar! ..

Bahar gelmiş...

Bana ne! ..

Hayaller bitmiş, 

Umutlar tükenmiş, 

Aşklar yaşanmıyor, 

Sevgi; bir kısrak olmuş, 

Zincirinden boşalmış küheylan, 

Dört nala terkeder bu diyarı...

Değerler yok olmuş, 

Gelenek bitmiş, 

Dünün pisliği, 

Bugünün efendisi olmuş, 

Eskiden ''muhbir'' veba idi, 

Şimdi yükselen değer, 

İhanet affedilmezken, 

Dürüstlük idam sehpasında.

Kan ekilen toprağın, 

Hasadı kin, 

Meyvesi ihanet olur, 

Bahar gelmiş...

Bana ne! ...

Sevgi, kardeşlik ve barış, 

Aşk ve muhabbet varken, 

Kavga niye! ..

Hoşgörü ve paylaşma varken, 

ihanet ve kin niye! ...

Yahuda; 

İsa''yı otuz gümüşe sattı, 

Utandı, kendini astı, 

Erguvan, bu utancı kaldırmadı, 

Kızardı bembeyaz çiçeği, 

İhanet yükünü taşıdığı için.

Peygamber mağaraya saklanır, 

Gözü dönmüş katillerden, 

İhanet içinde olanlardan, 

Örümcek bu zulme dayanmaz, 

Var gücü ile, 

Girişe mertliğin ve vefanın ağını örer..

Sezar''a öldürücü ve son darbe, 

Bürütüs''ten gelir, 

Şehzade Cem, 

Kimin tarafından öldürülür, 

Kimin tarafından, 

Kafaları kesilir Hasan ve Hüseyin''in...

Çünkü ağacın kurdudur, 

Ağacı çürüten; 

Bahar gelmiş...

Bana ne! ...

Din, dil, ırk; 

İster beyaz, ister siyah, 

Esmer veya sarı, 

Ne farkeder, 

İNSAN olmak YETER...

Dört kitap adına, 

Musa, İsa, Muhammed aşkına, 

Ateşin, toprağın, suyun ve güneşin hatırına, 

İbrahim için; 

Söküp koparın kini ve ihaneti, 

Kafdağı''nın arkasına atın öfkeyi, 

Sevgi ekin toprağınıza, 

Hasadınız kardeşlik, 

Ürününüz ''aşk'' olsun AŞK...

O zaman; 

Sevdalar yaslanır dağın tepesine, 

Keyifle seyreder, 

Yeni doğan kuzuyu, 

çiçekten çiçeğe hayat taşıyan kelebeği, 

Özgürce uçan güvercini, kuşu, böceği, 

Çeşme başında yavuklusuna sevgiyle bakan delikanlıyı, 

Tarlasındaki ürünü toplayan köylüyü, 

Güven içerisinde çalışan işçiyi, 

Bilgiye özgürce ulaşabilen gençleri, 

Yaramazlık yapan çocukları, 

Dükkanını besmele ile açan, şükür ile kapatan esnafı...

O zaman; 

Güneş, coşkulu ve sevecen, 

Toprak, bir ana gibi doğurgan ve bereketli, 

Rüzgar, şefkatli ve ılık, 

Gökyüzü, türkü mavisinde, huzurlu ve dingin, 

Fırat azgın ama sevgi dolu, hayat dolu...

Bahar gelmiş, 

Memleketimin dağlarına, ovalarına; 

Hoşgelmiş, safa gelmiş...', 'Memleketimin baharı yok,  Sadece kışı var. Tek mevsim;  Soğuk,  Karanlık,  Ve kalleş... Rüzgar; kinle fırtına olur,  Tozu dumana katar. Yağm...', ARRAY['Türk Edebiyatı','Şiir','Necat İltaş']::text[], 8.5, '{"poet":"Necat İltaş","poet_slug":"necat-i-ltas","theme":"Türk Şiiri","is_hero":false,"total_lines":125,"source_url":"https://www.antoloji.com/bahar-gelmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Koku Ve Ses', 'koku-ve-ses-ahmet-altan-mcims', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hayatımız boyunca duyduğunuz bütün sesler arasında en az tanıdığımız, dahadoğrusu hiç tanımadığımız tek ses, kendi sesimizdir. Başka sesler bize

birçok şeyi hatırlattığı halde kendi sesimiz bize hiçbir şey hatırlatmaz.

Sesimiz, hafızamızda tek bir ışık bile yakmaz. Kendi sesimiz bize

yabancıdır. Kendi kokumuzu da alamayız. Kokumuz da yabancıdır bize.

Bu kadar yakın olup da sesine ve kokusuna yabancı olduğumuz tek insan

kendimiziz. Belki de bu yüzden kendimizi tanımayız. Belki de bu yüzden bir

başka insanın sesine ve kokusuna bu kadar çok ihtiyaç duyuyoruz. Belki de

bu yüzden aşık oluyoruz. Belki de, bir başkasının sesini ve kokusunu kendi

sesimizin ve kokumuzun yerine koymaya, bir başkasının sesini ve kokusunu

bir parçamız gibi hissetmeye aşk diyoruz. Belki de, sevdiğimiz insanın

sesine doğru akıp gitmemiz, aslında kendimize doğru yaptığımız bir

yolculuk.

Kendi sesimize ve kokumuza hafızamızda yer yok. Biz kendimize yabancıyız.

O yüzden başkalarının sesiyle sevinip, başkalarının sesiyle acı duyuyoruz.

Aşkı aramak, hep kendi sesimizi, kendi kokumuzu aramak belki.

bizi dolaştıracak bir kılavuzu bulmaya çalışmak.

Terkedildiğimizde

duyduğumuz acı, bir parçamızı kaybetmekten. Terkettiğimizde ardımızda

bıraktığımız keder, terkettiğimiz insanın sesini ve kokusunu kendimizle

birlikte götürerek geride bıraktığımız boşluktan.

Aşkı yaşarken bunu hiç bitmeyeceğini sanmamız, bize bağışlanan büyük

yanılgı sonucu, aşık olduğumuz insanın sesini ve kokusunu kendi parçamız

sanmamızdan.

Sesler ve kokular olmasa geçmişimiz olmazdı. Sesler ve kokular olmasa

aşklar olmazdı. Sesler ve kokular olmasa acılar ve sevinçler olmazdı.

Aşk kendimizin sandığımız bir sesin ve kokunun aslında bize ait

olmadığını, bir başkasının sesi ve kokusu olduğunu anladığımız zaman

.

Yanıldığımız sürece aşığız biz.

Seslerini kokularını istediklerimizin, vücutlarını da isteyeceğiz. Seni

seviyorum dediğimizde, sen benim sesim ve kokumsun demek isteyeceğiz.

Kendi hafızamızda başkalarının sesleri ve kokularını kılavuz yapıp

dolaşabileceğiz ancak. Kendi geçmişimize ancak başkalarıyla

ulaşabileceğiz.

Aşk tanrısı, dünyayı yanılın emriyle yaratacak. Hep yanılacağız. Hep

yanılıp yanıldığımız için hep acı çekeceğiz. Ama sevinçlerimizi de bu

yanılgıya borçlu olacağız. Anıldığımız sürece seveceğiz. Sonra

yanıldığımızı anlayacağız. Ve gidip yeniden yanılacağız', 'Hayatımız boyunca duyduğunuz bütün sesler arasında en az tanıdığımız, dahadoğrusu hiç tanımadığımız tek ses, kendi sesimizdir. Başka sesler ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Altan']::text[], 8.5, '{"poet":"Ahmet Altan","poet_slug":"ahmet-altan","theme":"Türk Şiiri","is_hero":false,"total_lines":38,"source_url":"https://www.antoloji.com/koku-ve-ses-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmurlu Bir Günndü', 'yagmurlu-bir-gunndu-emrullah-erdinc-tc58e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Iliklerime kadar islandim dolastim durdum 

mahallende her sokak basinda durdum 

simdi  evet simdi bir köseden  cikarsin diye 

ama nerde sen belkide yataginda yada baska bir yerdeydin 

ben ise iliklerime kadar islanmistim 

sokak baslarinda seni tek  bir kerecik göreyim 

mazide kalan yarim  askimiz canlansin diye 

saatlerce ne kadar  seni beklemisimki 

elimdeki ciceklerin yapraklari yagan yagmurla

parcalanip mazide yarim kalan  askimiz gibi akip gittiler 

iliklerime kadar islandim yilmadim

sokaklara ismini kazidim yagan yagmurla akip gittiler 

kumlara ismini yazdim dalgalar  alip göturduler 

iliklerime kadar islandim  yilmadim

seni sokak sokak aradim ve

göremeden  hastalanip  yatagima yattim', 'Iliklerime kadar islandim dolastim durdum  mahallende her sokak basinda durdum  simdi  evet simdi bir köseden  cikarsin diye  ama nerde sen ...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yagmurlu-bir-gunndu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yunus Gibi...', 'yunus-gibi-bulent-ozcan-jz9mi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşk oduyla yanabilsem, 

Kevser ile yunabilsem, 

Canı bir Hakk''a adayan

Yunus gibi olabilsem...

Gönül haddini aşmayan, 

Doğru yolundan şaşmayan, 

Eğri yolu dolaşmayan

Yunus gibi olabilsem...

Gönül gözü ile gören, 

Tezgâhta sevgiyi ören, 

Canını hak yolda veren

Yunus gibi olabilsem...', 'Aşk oduyla yanabilsem,  Kevser ile yunabilsem,  Canı bir Hakk''a adayan Yunus gibi olabilsem... Gönül haddini aşmayan,  Doğru yolundan şaşmay...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yunus-gibi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Can', 'can-mahmut-capar-14wfu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Öyle dertliyim ki...

Bir yanda can

Öteki yanda yine can

Ya canından geçersin

Ya da canından.

Hangisi daha kolay

Ölmek mi, 

Sürekli ölüp 

Hiç 

Ölmemek mi? 

Öyle zordayım ki...

Artık düşünemiyorum bile

Yazarken bile tüylerim ürperiyor.

Dönecek zaman mıydı? 

Suç kimin? 

Aşağı tükürsen sakal

Yukarı niye tüküresin ki? en en iyisi

Aynaya tükür

Aynaya...', 'Öyle dertliyim ki... Bir yanda can Öteki yanda yine can Ya canından geçersin Ya da canından. Hangisi daha kolay Ölmek mi,  Sürekli ölüp  Hiç...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/can-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar Susar Bazen', 'i-nsanlar-susar-bazen-ahmet-sahin-soner-xy4d3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İnsanlar susar bazen

Sesiz sakin ve durgun

Seslensen duymaz olur

Duysan bile sesler boğulur

Gece çöker gibi üzerimize

Sessizlik çöker ağır ağır

Suskun olur gözler

Duymaz olur duyular

Hissetmez olur yürekler

Düşünemezsin

Karanlık çöker yıldız yıldız

Denizlere düşer yakamozlar

Ağaçlar suskun olur

Yeşil maviye kavuşmaz

Mavi olamaz bulut

Bulut dolup dolup yağamaz

Suskunsa yüreğin

Ağlasan olmaz

Seslensen yüreğim duymaz

Duysam sadece sen...

(10.08.2001)', 'İnsanlar susar bazen Sesiz sakin ve durgun Seslensen duymaz olur Duysan bile sesler boğulur Gece çöker gibi üzerimize Sessizlik çöker ağır a...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/insanlar-susar-bazen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kerkük''ten Mektup var', 'kerkuk-ten-mektup-var-kemal-beyatli-qr7az', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir gece karanlığında sizleri uğurladık

Kapılarımızı açık bırakıp

Lamba islerinde el salladık sizlere

Sokak sokak, adım adım

Omuzdan omuza sizi taşıdık

Yorulmayasınız diye 

Sizleri uğurladık

Gittiniz.

Ve haberiniz kesildi.

Önceleri; 

Yollarda telef olduğunuzu sandık

Veya, dağlar arasında 

Kaybolup yittiniz

Yoksa kurda kuşa yem olup 

Bittiğinizi sandık...

Hep o kara düşüncelerle, 

Rüyalarla boğuştuk.

“Olur böyle şeyler “dedik

Kendimizi avuttuk

Ve karınca bile duymadan 

Dava uğruna 

Şehitler arasına sizi de yazdık.

Yaşıyorlar, yaşıyorlar...

Müjde verdiler

Gizli gizli sevindik

Arkadaşlar, evden eve 

Elçi gönderdi

Damlara koştuk

Sırayla, nöbetleşe 

Yolları gözledik

Rüzgardan sakladık fısıltımızı

Her kes beklemede idi

Sizleri

Camilerde, eller sizin için duaya kalkardı

Gözlerden, sizin için yaşlar akardı.

Beşikteki bebek ağlıyordu

Salladıkça beşiği bebek susmuyordu

Ama, 

Sizi ninnilerle söyledikçe

Bebek susuverirdi.

Çünkü bir beklediği vardı.

Böyle umutlanıp

Böyle beklerdik sizleri.

Sonra, 

Ah bu “sonra”yı 

Keşke bu “sonra”yı 

Duymasaydık.

Bilmeseydik keşke.

Keşke haberci yolunu şaşırıp

Bir vadide kaybolsaydı

Ve “sonra”yı

Bize söylemeseydi.

Duyduk ki, 

Biriniz yatlarda

Mavi kırmızı loş ışıklar altında

Birinizgündüz ile geceyi

Karıştırmış barlarda

Ve sefilleri oynayan diğeriniz

Parklarda uyuyor.

Biz bir lokmayı beş kişiye bölüşürken

Birbirinizden ekmeği sakladığınızı 

Duyduk.

Birileri burada bizim kimliklerle oynarken

Sizler orada

Güle güle benliğinizi verip

Avara avara dolaşıyormuşsunuz

Buralarda boynumuz ipte sallanırken

Cambaz gibi birkaç ipte

Oynadığınızı duyduk.

Sanki buralı değildiniz de

Her şeyi unutup gittiniz.

Sizin sütünüz bozuk değildi

Mayanız da bozuk değildi

Ne oldu sizlere? 

Kafileyi bozguna uğrattınız

Ne oldu sizlere? 

Sürüden ayrılıp

İpliği kopmuş tespih gibi

Dağıldıınız...

Hani o yeminler

“Toprağının her zerresi dünyaya bedeldir Kerkük’üm”

Diyenler hani? 

Hani Kur’an’a el basıp 

“Ölmek var, dönmek yok”diyenler, hani? 

Bir baltaya sap olamadınız.

Kerkük’ü her lokmada düşünmedikçe

Rüyalarınıza Kerkük girmedikçe

Her adımınız Kerkük için olmadıkça

Helal etmiyoruz

Etmiyoruz

Etmiyoruz

istanbul

Pazar /08/04/20001-saat: 24: 00', 'Bir gece karanlığında sizleri uğurladık Kapılarımızı açık bırakıp Lamba islerinde el salladık sizlere Sokak sokak, adım adım Omuzdan omuza s...', ARRAY['Türk Edebiyatı','Şiir','Kemal Beyatlı']::text[], 8.5, '{"poet":"Kemal Beyatlı","poet_slug":"kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":93,"source_url":"https://www.antoloji.com/kerkuk-ten-mektup-var-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saatlerce Beklemek Vardı Kapılarında...', 'saatlerce-beklemek-vardi-kapilarinda-bahadir-yurteri-uvixg', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saatlerce beklemek vardı kapılarında

Gece vakti kar yağarken bembeyaz.

Doğuşunu beklemek vardı ya güneşin; 

Doğmayacak günü nerde beklesen olmaz.

Göğe bakarsın gördüğün yıldızlardır: 

Havada asılı kalmış mazideki gülüşler.

Ufukta ölesiye bir karanlık ve ölürsün, 

Yalnızsındır yine hani nerde melekler? ! 

Saatlerce beklemek vardı kapılarında

Telefon etmek karşıki kulübeden...

''Kim'' diye soruşuna, ''Ben'' demem yetecekken

Tanıyacaktın hep seni soluyan nefesimden.

Loş ışıklar ortasına düşecektim sonra, 

Odama kapanacaktım yine yapayalnız.

Dışarda savrulan yapraklara bakıp, 

Kızacaktım esişine rüzgârın zamansız

Saatlerce beklemek vardı diyorum

Avuçlarımda geçmiş yazların kokusu...

Martılar bile görmüş... Sordum: 

Uykusuz gecelerde gördüğüm kâbusu.

Kelimelere dokunmak istemem bu sefer

Bir kez olsun çağırmadan, gel be artık güzelim! 

Duymaz mısın aşkına yaktığım ağıtları? 

Yüreği nasır tutmuş, benim nazlı gelinim...', 'Saatlerce beklemek vardı kapılarında Gece vakti kar yağarken bembeyaz. Doğuşunu beklemek vardı ya güneşin;  Doğmayacak günü nerde beklesen o...', ARRAY['Türk Edebiyatı','Şiir','Bahadır Yurteri']::text[], 8.5, '{"poet":"Bahadır Yurteri","poet_slug":"bahadir-yurteri","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/saatlerce-beklemek-vardi-kapilarinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umudum', 'umudum-sair-hamit-05y86', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'hasretin sel olur

alır götürür senden arta kalanları

depremler oluryüreğimde

resmine her bakışımda

iki damla gözyaşı, gidişini anlatır

yokluğun girdaplar oluşturur

çeker içine varımı, yoğumu

tükenmeyen umudumu

hani sen dittin ya 

sevda türküleri ağıtlar yakar oldu

uykusuz uykular uyur oldum

sabahsız gecelerde

bir gülü soldurmadım

birde seni satırlarımda.

gururu bir kenara attım

umudu bahara sakladım...', 'hasretin sel olur alır götürür senden arta kalanları depremler oluryüreğimde resmine her bakışımda iki damla gözyaşı, gidişini anlatır yoklu...', ARRAY['Türk Edebiyatı','Şiir','Şair Hamit']::text[], 8.5, '{"poet":"Şair Hamit","poet_slug":"sair-hamit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/umudum-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öç...', 'oc-hasan-ozemek-mimb0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yağmursuz bulutlar altında uyanacaksın

Gözlerin sisler ardında solacak

Dualarını geri alacak tanrı

Kişilerin lanetine uğrayacaksın

Kaldırım taşlarına oturup, 

Pişmanlıklarını anlatacaksın.

Güller solacak avuçlarında..

Çökecek yanıbaşına yalnızlık, 

Acı gülümsemelerle çatlayacak dudağın..

Ağlayacaksın....

Titreyen ellerle kapımı çalacaksın, 

Gözyaşlarımı sormayacağım senden.

Sen! 

Kaderinle ödeşmiş olacaksın', 'Yağmursuz bulutlar altında uyanacaksın Gözlerin sisler ardında solacak Dualarını geri alacak tanrı Kişilerin lanetine uğrayacaksın Kaldırım ...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oc-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişlerini Anlatıyorum', 'gidislerini-anlatiyorum-fatih-cinar-zke5g', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gittiler yüzümüze baka baka gittiler

gittiler yürekleri gözyaşımızda gittiler gittiler

bilmemne turizm otobüsündeydiler

yolculardan kimi sılaya kavuşacağından mutlu

kimi acil işlerden telaşlı

fakat onlar hüzünlüydüler

çünkü ayrılık çünkü gözyaşı

bir tanrı misafiriymişcesine çalmıştı kapılarını

onlar bizim can dostlarımızdı

kimi zaman bir parça keder

kimi zaman bir parça sevinci paylaştığımız bacılarımızdı

evet kızdılar evet kısraktılar dişiydiler

ama yürekleri harbi 

bu gözlerinden bileklerinden belli

gittiler yüzümüze baka baka gittiler

artık kimsesiz kaldı

belki görüşecektik yine birdahaki yaz

onlar çorum elinde biz ankarada

hergün gündelik hayat bırakmayacaktı yakamızı

çılgınlıklar olmayacaktı

tekrar vuslatta sılaya kavuşmak

onlara kavuşmak hayali yakacaktı bağrımızı

yaklaştıkça o buram buram sevinç kokan

hatıra kokan temmuz günleri

ağustos akşamları

daha bir tüttürecekti 

gönül ocğımızın dumanını

gittiler yüzümüze baka baka gittiler

onların yokluğunda şarkılara sığınıyoruz

şiirle paylaşıyoruz yalnızlığı

notalara bölüyoruz

bilmem farkındamıydılar onlar giderken

bizim bir parçamızı götürdüler

bizlere kendi gönüllerini pay ettiler

gizli sırlarını üleştirdiler

birisi hatıra ayakkabı bağcığını bıraktı

birisi son içtiği şişenin mantarını

diğeri evinin kapısının anhtarlığını

aslında maddesel hatıraların ne önemi vardı

asıl hatıra birlikte gezdiğimiz

kumsallardı denizdi taştı kaldırımlardı

asıl hatıra şiirlerde şarkılardaydı

gittiler yüzümüze baka baka gittiler

gittiler ölümden beter vedayı ede ede gittiler

gittiler hasret ocağını yaka yaka gittiler

gittiler hala ara sıra mektupları gelir...

(zübeyde, seda ve şuleye)  (trabzon)', 'gittiler yüzümüze baka baka gittiler gittiler yürekleri gözyaşımızda gittiler gittiler bilmemne turizm otobüsündeydiler yolculardan kimi sıl...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":47,"source_url":"https://www.antoloji.com/gidislerini-anlatiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsteme', 'i-steme-hasan-ozemek-okcvh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yeni bir isteme benden, 

Bütün dizeler tükendi..

Kurumuş arzular içimde, 

Uzaklarda kaldı  gülüşmelerimiz..

Yeni bir şiir isteme benden, 

Üzüleceksin..

Artık unut ne varsa..

Ayrı kadehlerde başlıyor dünyalarımız.

Çığlık çığlık büyüyecek yalnızlık avuçlarımızda

Kadeh kenarlarında dönecek başlarımız, 

Düşüneceksin.

Kaybolacaksın akşamsız sokaklarda..

Bir güneş bulamayacaksın aydınlanmak için..

Yalnızlığı duyacaksın kulaklarında, 

Avuçların boşlukta kalacak...

Yeni bir şiir isteme benden

Utanacaksın.....', 'Yeni bir isteme benden,  Bütün dizeler tükendi.. Kurumuş arzular içimde,  Uzaklarda kaldı  gülüşmelerimiz.. Yeni bir şiir isteme benden,  Üz...', ARRAY['Türk Edebiyatı','Şiir','Hasan Özemek']::text[], 8.5, '{"poet":"Hasan Özemek","poet_slug":"hasan-ozemek","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/isteme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Canım mısın?', 'canim-misin-mustafa-engin-karatay-2g7l6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerinde tebessüm, bana bir hâl ediyor

Sevdâ dolu sözlerin, çok hoşuma gidiyor

Yüreğimin ipini, tatlı dilin yediyor

Ben senin mübtelânım, sen benim canım mısın? 

İşlemişsin içime, yakıp da kavurmuşsun

Samyeli gibi esip, aşkınla savurmuşsun

Etkili bakışınla, gözlerimden vurmuşsun

Dolaşıp sıcak akan, damarda kanım mısın? 

Mehtâb da dolaşırken, seyrettiğim yıldızım

Ummânlarda görünen, efsâne deniz-kızım

Derde dü-çâr olup da, çektiğim tatlı sızım

Hayâlimi süsleyen, özlenen yanım mısın? 

MECNÛN''dan çok yanmışım, belki olurum verem

İbret olur bu sevgi, gölgede kalır KEREM

FERHÂT dağları delmiş, ya benim eksik nerem? 

KAMBER''i imrendiren, övülen şânım mısın? 

Nerde beste yaptıysam, hâlâ hâtırân yaşar

İlhâmım''ın boyutu, değme aşkları aşar

Kalemim elimdeyken, kalbim coşup da taşar

İsmin söylenen yerde, canlanan anım mısın? 

Bu iksîr-i kevn ile, bulalım derde devâ

Muhabbet Rızâ için, olamaz bunda hevâ

Yâr ol bana Ukbâ''da, bendeki gâm-ı cevâ

Uçmağım''da Sultânım, sâlihâ hanım mısın? 

19.03.2000      Landsberg      07: 45', 'Gözlerinde tebessüm, bana bir hâl ediyor Sevdâ dolu sözlerin, çok hoşuma gidiyor Yüreğimin ipini, tatlı dilin yediyor Ben senin mübtelânım, ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/canim-misin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzellikler Toplanmış', 'guzellikler-toplanmis-sair-hamit-bkdmf', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'güzellikler toplanmış sende

denizin mavisi var gözlerinde

okyanuslar kadar derin

dalgalar kadar serin bakışların

güzellikler toplanmış sende

altın sarısı, gözalıcı gsaçların

ilmik ilmik güneş dokunmuş

hançer misali yüreğime sokulmuş

güzellikler toplanmış sende

şefkatin harareti var bedeninde

mutluluğun esareti elerinde

ve aşkın cesareti, kalbinin derinliklerinde

güzellikler toplanmış sende

yokluğun kelepçe bileklerimde

sarıl bana sımsıkı

nefesin nefesimde...', 'güzellikler toplanmış sende denizin mavisi var gözlerinde okyanuslar kadar derin dalgalar kadar serin bakışların güzellikler toplanmış sende...', ARRAY['Türk Edebiyatı','Şiir','Şair Hamit']::text[], 8.5, '{"poet":"Şair Hamit","poet_slug":"sair-hamit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/guzellikler-toplanmis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Rûhumu Mahkûm Ettin', 'r-humu-mahk-m-ettin-mustafa-engin-karatay-y327k', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen, vefâsız sevgili; yürekte çıban başı

İhânet sultasının, mahâretli nakkaşı

Dertler hengâmesinde, Adın; Kıdem Savaşı

Ne kadar diş bileyip, toplasam da cesâret; 

Sonu hep mağlûbiyyet, hep vehminde esâret...

Feleğimi şaşırdım; bir büktün ki belimi, 

Kerâmetler yetmiyor, döndürmüyor dilimi...

Hep zifiri karanlık, sanki zamân dilimi

Alnımdaki damganın; misli var mı? .. Bilinmez...

Yıllar tek-tek tükense, Asırlar''dan silinmez! ..

Bir yer bulsam kendime, kaçardım ya dörtnala

Azgın Okyanuslar''da, kürek çekerdim sala

Sensiz kopan tûfanda, tutunurdum bir dala

Ne bıraktın ki bende; bana, ben denilecek? 

Mahkûm ettiğin rûhum, kahrına yenilecek! ..

07.08.2001      Fürstenfeldbruck     03: 35', 'Sen, vefâsız sevgili; yürekte çıban başı İhânet sultasının, mahâretli nakkaşı Dertler hengâmesinde, Adın; Kıdem Savaşı Ne kadar diş bileyip,...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ruhumu-mahkum-ettin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Askere Haber', 'askere-haber-mehmet-ayar-asik-ayar-doi89', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'oğlum sana ne yazayım havadis, 

siz gittikten sonra ölen olmadı.

bir ay oldu siz askere gideli, 

daha dağıtıma gelen olmadı.

daha Yeni yeni yetiyor tutlar, 

oğlum bugün yarın biçilir otlar, 

yaylaya gidiyor eşşekler atlar, 

kimse yaylasından inen olmadı. 

hizayı düzgün tut sırada oğlum, 

cesur ol havada, kara da oğlum.

düğün dernek yok burada oğlum, 

sizden başka düğün çalan olmadı. 

Mehmet ayar Göksun K.Maraş

 Mehmet Ayar (Aşık Ayar)', 'oğlum sana ne yazayım havadis,  siz gittikten sonra ölen olmadı. bir ay oldu siz askere gideli,  daha dağıtıma gelen olmadı. daha Yeni yeni ...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayar (Aşık Ayar)']::text[], 8.5, '{"poet":"Mehmet Ayar (Aşık Ayar)","poet_slug":"mehmet-ayar-asik-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/askere-haber-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Gönül Yarası', 'gonul-yarasi-mustafa-engin-karatay-r6ysu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uzakta, erişilmeze yanıp sevdâlanmışım

Mükemmelin peşinde, tutuşup gâmlanmışım

Gâye-i maksûduma, kalben evhâmlanmışım

Belli ki kapanmıyor, bende gönül yarası

Ararım uzaklarda, yitirdiğim dermânı

İletmek mümkün değil, bu buyruğu fermânı

Sözün tesiri için, yeğleyemem nermânı

Böyle izhâr eyliyor, bende gönül yarası

Tâ yürekten vurgunum, hayâlimi süslerim

Vuslat adlı kelâma, ümîdimi beslerim

Uzaklara daldıkça, alevlenir hislerim

Bir fâsıla vermiyor, bende gönül yarası

Aşk oduyla yanmışım, olacak mı söndüren? 

Levh-i Mahfûz''da yazgı, var mı bahtı döndüren? 

Bir tek ''O'' olacaktır, bu sancıyı dindiren

Neden hafiflemiyor, bende gönül yarası? 

Bir suyken rahme geçtim, sonra Dünyâ''ya geldim

Bülûğa erip sevdim, nice güzeller bildim

Lâkin O''nun uğruna, hepsini birden sildim

Şimdi illâ ''O'' diyor, bende gönül yarası

Haftalar aylar böyle, kovalar birbirini

Görmüş müdür geceler, bu sevdâ''dan Pîri''ni? 

Müsâvî kılar ismim, dertlerin en Mîri''ni

Rasûl bile kullanmış, ''Hümeyrâ'' tâbirini

Kuvvetli bir rüzgâr da, esip demez yerini...

Bu hasret bitsin diyor, bende gönül yarası...

19.07.2000   Landsberg   22: 55   (İlk iki dörtlük 27.06.2000 Berlin  23: 40)', 'Uzakta, erişilmeze yanıp sevdâlanmışım Mükemmelin peşinde, tutuşup gâmlanmışım Gâye-i maksûduma, kalben evhâmlanmışım Belli ki kapanmıyor, b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/gonul-yarasi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karı', 'kari-mehmet-ayar-asik-ayar-pn6dn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'aldı aşık. 

Mahalleden eve geldim girdim ki, 

zıbarı zıbarı yatarsın karı.

hasta mısın diye halını sordum, 

dilli düdük gibi ötersin karı.

Aldı karısı

boşuna yatmıyom ağrıyor başım, 

hep senin yüzünden döküldü dişim.

şu senin yanında ne idi işim, 

çocuklar yüzünden kaldım insafsız.

 Mehmet Ayar (Aşık Ayar)', 'aldı aşık.  Mahalleden eve geldim girdim ki,  zıbarı zıbarı yatarsın karı. hasta mısın diye halını sordum,  dilli düdük gibi ötersin karı. A...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayar (Aşık Ayar)']::text[], 8.5, '{"poet":"Mehmet Ayar (Aşık Ayar)","poet_slug":"mehmet-ayar-asik-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/kari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', '.Şiir-Şair', 'siir-sair-mustafa-engin-karatay-p9gv5', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiir denilen terim, îcâd olmuş bir vakit

İlhâm adlı meleke, buna sermâye, nakit

Sözler birer bilmece, mânâlar sened, akit...

Şâirin mârifeti, mısrâları dizdirmek...

Sırlar, evet o sırlar; gizli hazînesinde

Ne fırtınalar kopar, muhteşem sînesinde

Görünülenden öte, görür âinesinde...

Erbâbının işidir, bu tılsımı çözdürmek...

Varılmaz uç noktalar, âniden olur yakın

Emir alan duygular, topluca eder akın

Önüne de geçilmez, dinlemez aman, sakın...

Bilenin vazîfesi, bilmeyene sezdirmek...

Öyle bir heyecân ki, vecdi nefesler keser

Yedi İklim birleşse, itirâz yeli eser

Dışta gülüş bahâne, iç bünyesinde küser...

Maksâdı tebessümde, kemân kaşı büzdürmek

Lodos Rüzgârları''yla, akıl karaya vurur

Çıkıp azgın dalganın, nasıl önünde durur? 

Beklenmedik ateşle, muazzam deryâ kurur...

İşte o an gemiyi, tek katrede yüzdürmek...

08.10.2000    Landsberg    05: 05', 'Şiir denilen terim, îcâd olmuş bir vakit İlhâm adlı meleke, buna sermâye, nakit Sözler birer bilmece, mânâlar sened, akit... Şâirin mârifeti...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/siir-sair-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevdiğim', 'sevdigim-mehmet-ayar-asik-ayar-4xw4u', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'ya hiç ümit verme ya bağlan bana, 

her zaman kul köle olayım sana.

sonum ne olacak hep yana yana, 

biraz insaf eyle düşün sevdiğim. 

vazgeçemem yaşım olsa da altmış, 

yaradanım ne de güzel yaratmış, 

güzel dudakların altında yatmış, 

dizilmiş bembeyaz dişin sevdiğim.

Ayaroğlum der de böyle olur mu? 

her güzel de kendi dengin bulur mu, 

aşığı ağlatmak iyi olur mu, 

bunun da sonunu düşün sevdiğim.

 Mehmet Ayar (Aşık Ayar)', 'ya hiç ümit verme ya bağlan bana,  her zaman kul köle olayım sana. sonum ne olacak hep yana yana,  biraz insaf eyle düşün sevdiğim.  vazgeçe...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayar (Aşık Ayar)']::text[], 8.5, '{"poet":"Mehmet Ayar (Aşık Ayar)","poet_slug":"mehmet-ayar-asik-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sevdigim-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güle Güle', 'gule-gule-mehmet-ayar-asik-ayar-zyvyv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'geldim ise gitmek zor değil bana, 

işte gidiyorum kal güle güle.

ne yaptımsa yaramadım ben sana, 

benden iyisini bul güle güle.

aşkın kalbimdedir kovsan kovulmaz, 

kara günler geldi çattı dağılmaz.

zaten dünya böyle seven sevilmez, 

daha yaşamış mı kul güle güle.

Ayaroğlum ne olduğum bilemem, 

tövbe olsun böyle dilek dilemem.

helal et hakkını belki gelemem, 

kendin oyna kendin çal güle güle...

 Mehmet Ayar (Aşık Ayar)', 'geldim ise gitmek zor değil bana,  işte gidiyorum kal güle güle. ne yaptımsa yaramadım ben sana,  benden iyisini bul güle güle. aşkın kalbim...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayar (Aşık Ayar)']::text[], 8.5, '{"poet":"Mehmet Ayar (Aşık Ayar)","poet_slug":"mehmet-ayar-asik-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gule-gule-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasıra Hasıra', 'hasira-hasira-mehmet-ayar-asik-ayar-2kgai', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sen orada ben burada, 

döndük esire esire.

nice engel var arada, 

dostum bu sıra sıra.

vallahi yürekten yandım, 

sizin eve doğru indim.

gören oldu geri döndüm, 

bakma kusura kusura.

ayaroğlum canıyınan, 

kurban olsun kanıyınan, 

bir kış günü seniyinen, 

yatsam hasıra hasıra..

 Mehmet Ayar (Aşık Ayar)', 'Sen orada ben burada,  döndük esire esire. nice engel var arada,  dostum bu sıra sıra. vallahi yürekten yandım,  sizin eve doğru indim. göre...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Ayar (Aşık Ayar)']::text[], 8.5, '{"poet":"Mehmet Ayar (Aşık Ayar)","poet_slug":"mehmet-ayar-asik-ayar","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hasira-hasira-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüzün', 'huzun-refik-recep-pelit-m4uqg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana bu gece öyle hasretimki, 

Özledim desem, renksiz kalır belki, 

Nereye baksam! karşımdasın sanki, 

Oluru yok biliyorum rüya bizimkisi, 

Gel gör beni, bak şimdi ne haldeyim, 

Hala Bıraktığın o ıssız çöldeyim, 

Kapıldım arkına sürüklediğin seldeyim, 

Sensizim anla beni yine kederlerdeyim, 

Yanındayken ebruli bir demet güldüm, 

Ağlamayı unuttum tek seninle güldüm, 

Yüreğimde yanan bir yudum Kordun, 

Boşluğunda kurudum bak saradım soldum, 

Sızlıyor tüm vucudum kapladı bir Hüzün! 

Yokluğunun burukluğuğu artıyor günbegün, 

Gitmiyor hayalimden o tebessüm dolu yüzün, 

Sensizlik zehir gibi, Gülmekmi ne mümkün!', 'Sana bu gece öyle hasretimki,  Özledim desem, renksiz kalır belki,  Nereye baksam! karşımdasın sanki,  Oluru yok biliyorum rüya bizimkisi,  ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/huzun-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dilek', 'dilek-sair-hamit-acm90', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sevdanın güneşi kalbine doğsun

bütün güzellikler hep seni bulsun

beraber olamasakta

dilerim tanrıdan  hep mutlu olursun...', 'sevdanın güneşi kalbine doğsun bütün güzellikler hep seni bulsun beraber olamasakta dilerim tanrıdan  hep mutlu olursun......', ARRAY['Türk Edebiyatı','Şiir','Şair Hamit']::text[], 8.5, '{"poet":"Şair Hamit","poet_slug":"sair-hamit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dilek-13-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meşrutiyet`ten Meşru Diyet`e! ...', 'mesrutiyet-ten-mesru-diyet-e-bulend-b-ki-h86ho', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beyaz`ı boyadınız, sizde kara mevcuttur! 

`Sevgi, `Saygı, rahmette, sizde para mevcuttur! 

Sizce `geri,  `yobaz, `ız, `hasta, `yız islam ile...

Asıl ruhu ölüler! Sizde `Sara, mevcuttur! ...', 'Beyaz`ı boyadınız, sizde kara mevcuttur!  `Sevgi, `Saygı, rahmette, sizde para mevcuttur!  Sizce `geri,  `yobaz, `ız, `hasta, `yız islam ile...', ARRAY['Türk Edebiyatı','Şiir','Bülend Bâki']::text[], 8.5, '{"poet":"Bülend Bâki","poet_slug":"bulend-b-ki","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/mesrutiyet-ten-mesru-diyet-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İdaRi DüŞünCe! ...', 'i-dari-dusunce-bulend-b-ki-7km6h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Akıl yaştan değil, baştan bell`òlur, 

Kuru`nun yanığı yaş`tan bell`olur, 

Siyaset zurnası, başkent çorbası...

Ağrı`dan Hatay`dan Muş`tan bell`olur! ...', 'Akıl yaştan değil, baştan bell`òlur,  Kuru`nun yanığı yaş`tan bell`olur,  Siyaset zurnası, başkent çorbası... Ağrı`dan Hatay`dan Muş`tan bel...', ARRAY['Türk Edebiyatı','Şiir','Bülend Bâki']::text[], 8.5, '{"poet":"Bülend Bâki","poet_slug":"bulend-b-ki","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/idari-dusunce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalancı', 'yalanci-sabahattin-ozkan-pbhlj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Bekle  beni,  geleceğim..'' demiştin! 

Vâdettin  kısa  vâdede

Beklettin âh ile de

Gelmedin! 

''Bekle  beni, geleceğim..'' demiştin! 

Bir  damla  suydu  sesin! 

Serptin, serinlettin beni de

Gelmedin! 

''Bekle  beni,  geleceğim..'' demiştin! 

-Serâbım, peri şanlım benim! -

Yedin senelerimi de

G  e  l  m  e  d  i  n! 

ERZURUM,1976', '''Bekle  beni,  geleceğim..'' demiştin!  Vâdettin  kısa  vâdede Beklettin âh ile de Gelmedin!  ''Bekle  beni, geleceğim..'' demiştin!  Bir  daml...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Özkan']::text[], 8.5, '{"poet":"Sabahattin Özkan","poet_slug":"sabahattin-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/yalanci-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kirpi', 'kirpi-sabahattin-ozkan-mcib7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hey, kirpi, iğneli kirpi, 

Yine geldim bak, 

Her şeyi unutup! 

Kâğıt oldum, elindeyim; 

Kâğıtta söz, sözcüklerde dudak; 

Dikenlerini öpmek için

Yine geldim, bak! ..

	1976	ERZURUM', 'Hey, kirpi, iğneli kirpi,  Yine geldim bak,  Her şeyi unutup!  Kâğıt oldum, elindeyim;  Kâğıtta söz, sözcüklerde dudak;  Dikenlerini öpmek i...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Özkan']::text[], 8.5, '{"poet":"Sabahattin Özkan","poet_slug":"sabahattin-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/kirpi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kasımpatılar Kasımpatıdır, Güller Gül, Karanfiller Karanfil', 'kasimpatilar-kasimpatidir-guller-gul-karanfiller-karanfil-sabahattin-ozkan-xgk9w', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'o bir kasımpatı mıdır, diktiğiniz? 

çiçeğe durmuş kasımpatıyım ben de

ayrı topraklarda boy versek de, 

-birimiz Mersin’de birimiz Çin’de-

hep kasımpatı kokar renklerimiz.

bir gül fidanısın sen, ben karanfilim

aynı sudan besleniriz bahçemizde

efil efil, aynı yel eser üstümüzde...

dalımızda aynı kuşları dinleriz de

sen goncalar açarsın elvan elvan, 

ben karanfillerimi katmerlerim; 

işimiz bu, yakışığımız bu bizim.

	MERSİN / Ağustos 2001', 'o bir kasımpatı mıdır, diktiğiniz?  çiçeğe durmuş kasımpatıyım ben de ayrı topraklarda boy versek de,  -birimiz Mersin’de birimiz Çin’de- he...', ARRAY['Türk Edebiyatı','Şiir','Sabahattin Özkan']::text[], 8.5, '{"poet":"Sabahattin Özkan","poet_slug":"sabahattin-ozkan","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kasimpatilar-kasimpatidir-guller-gul-karanfiller-karanfil-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek', 'bebek-necmettin-atamturk-01fbz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bebek Dünyaya Hos geldin

Hic de iyi etmedin

Yok etdiler Dünyada

Olan senin kismetini

Bunu sana söylerim

Benim tatli Bebegim

Agalasan da gülsen

Ne yapip ne eylersin

Nasip Kismet mi dersin

Tek bir degilsin sen

Karisan bu agleme Bebek.', 'Bebek Dünyaya Hos geldin Hic de iyi etmedin Yok etdiler Dünyada Olan senin kismetini Bunu sana söylerim Benim tatli Bebegim Agalasan da güls...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Atamtürk']::text[], 8.5, '{"poet":"Necmettin Atamtürk","poet_slug":"necmettin-atamturk","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bebek-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur Damlam', 'yagmur-damlam-ozan-turan-ypqjz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne zaman seni hissetmek istesem, 

Yağmur yağmasını istiyorum.

İliklerime kadar beni ıslatmasını...

Yağmur yağmasını istiyorum.

Çünkü sen benim alacakaranlıktaki yağmur damlamsın...! ! !', 'Ne zaman seni hissetmek istesem,  Yağmur yağmasını istiyorum. İliklerime kadar beni ıslatmasını... Yağmur yağmasını istiyorum. Çünkü sen ben...', ARRAY['Türk Edebiyatı','Şiir','Ozan Turan']::text[], 8.5, '{"poet":"Ozan Turan","poet_slug":"ozan-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/yagmur-damlam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebek Yeni', 'bebek-yeni-necmettin-atamturk-n1hfc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bebek 

Bebek Dünyaya Hos geldin 

Hic de iyi etmedin 

Yok etdiler Dünyada 

Olan senin kismetini 

Bunu sana söylerim 

Benim tatli Bebegim 

Agalasan da gülsen 

Ne yapip ne eylersin 

Nasip Kismet mi dersin 

Tek bir degilsin sen 

Karisan bu agleme Bebek. 

Oldu bu Dünya sanada Kismet

Adini söyle ismini et

Olur sendede bir niyet

Ya namert ya cömert

Olursun sende Bebek

Simdi bebeksin agalarsin

isteklerini cogunu saglarsin

Zamani gelince büyüp de anlarsin

Gerceklerle beraber duyar olursun bebek

Kucaklarlar cok severler

Sade Gönül goncalarini

Cünkü sevimlisin yücelerine

Güler güldürürsün  nicelerini

Hele bir büyü de görürsün 

acilarini gül bebek

Senle olan varlik cok

Sensiz hic bir varlik yok

Sensiz hic bir Dünya olamaz

Tatli seni can Bebek

Hele bir büyü görsünler seni

hele bir konus bilsinler seni

O zaman anlarsin insanlari

Baslarsin üzülmeye bebek

Cok seyler ögretirler

Yanlisiiyle egrisiyle

Düsünür kalirsin hangisi dogru

Katarlar böylece seni egrisiyle dogrusuyla

Sasirir kalirsin arada böylece Bebek

Bebek bunlari ben sana yazdim

Sanmaki moralini ben senin bozdum

Düzenin temeli böyleidi

Gercek olanlari siraya düzdüm

Hal ahval böyle idi bende yadim Bebek.', 'Bebek  Bebek Dünyaya Hos geldin  Hic de iyi etmedin  Yok etdiler Dünyada  Olan senin kismetini  Bunu sana söylerim  Benim tatli Bebegim  Aga...', ARRAY['Türk Edebiyatı','Şiir','Necmettin Atamtürk']::text[], 8.5, '{"poet":"Necmettin Atamtürk","poet_slug":"necmettin-atamturk","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/bebek-yeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Söz Vermiştik', 'soz-vermistik-ozcan-nevres-j7fto', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani söz vermiştik hiç ayrılmayacağız diye

 Bir gün terk edip gittin anlamadım niye

Hani kumrular gibi olacaktık ömür boyu

Hani ölesiye sevecektik birbirimizi yıllar boyu

Dünya yalanlar üstüne kurulmuş derler inanmazdım

Bir kez aşık olunur bilirdim yalanlara kanmazdım

Yalanmış sevgin ve göz yaşların

Yıkılmış en ölümsüz gördüğüm  aşkım

Perişanım yıkılmışım ama 

Sanma ki sana muhtacım

Uykusuz gecelerde döktüğüm göz yaşlarım

Sel olur bir gün boğar senide

Gün olur sen de terk edilirsin

Pişmanlık çöker kanayan yüreğine

Beni anarsın

Bin pişman olursun beni terk ettiğine

Eski beraberliğimizi ararsın özlemle

Bir gün düşerse yolun yaşadığım o ıssız yere

Karşılaşırsan saçı sakalı karışmış bir deliyle

O benim işte ama sakın üzülme

Yalancı dünyada yalancı bir aşkla

Nice aklını yitirenler var bir yalancı uğruna

O ben olmuşum yada başkaları ne çıkar

Dünya yalan aşklar yalan belki de yaşadığımız yalan

Unut beni güzelim sen git kendi yoluna

				Özcan Nevres 2001-08-12

					SİLİVRİ', 'Hani söz vermiştik hiç ayrılmayacağız diye  Bir gün terk edip gittin anlamadım niye Hani kumrular gibi olacaktık ömür boyu Hani ölesiye seve...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/soz-vermistik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dost', 'dost-alper-aydinci-u72r0', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yürüyoruz

Oysa bilmiyorsun nereye ve ne için gittiğimizi

Bilmiyorsun bana duyduğun güvenin sınırlarını

Kafanı karıştırsada herşey soramıyorsun bir türlü bana

Nereye diye? 

İçindeki güvensizliğe güvenip güvenememekte tereddüt ediyorsun..

''Güvenmiyorum sana, 

Yollarımızı ayıracağız..''

Diye iki cümle süzülsün dudaklarından

Ama söylemiyorsun bir türlü

Korkuyorum..

Omuz omuza gittiğimiz yollar karışıyor

Nereye sapacağımı şaşırmaya başlıyorum

Artık farkediyorum

Daha ileriye gidemiyoruz

ve 

Bir gün hakkımda ummadığın şeyler duyuyorsun birinden, 

Hemde hiç tanımadığın birinden

Kötü şeyler düşünmüş, kötü şeyler yapmışım sana

Oysa bilirsin, sana kötülük yapamam

İnanmak istemesende derin bir kuşku bürüyor kafanı.

Dostun ihanet etti sana

Bir türlü kafandan çıkaramıyor, bir türlü soramıyorsun dert ortağına

Doğru mu? diye..

Çünkü kızarım bilirsin, kızarım bana güvenmediğinde..

Başkalarına hiç sorma ''ne yapmış'' diye, kimse bilmez gerçeği, bilmekte istemez.

Oysa keşke bana sorsaydın

Onları bilmezsin sen! 

Hoş.. Tanıtamadım ya onları sana.. Ama geç değil diyorum tanırsın..

Geç kaldığımı farkediyorum, gitmişsin...

Onlar alçak, güvenemiyeceğin kadar kötüydüler

Onları ilgilendiren tek şey dostluğumuzdu

Çekemediler, 

Ama inanmak istemedin bana..

40 yıllık dostlukta yaşadıklarını bir anda unutuverdin... 

Onlar 

Alçaktır demiştimya sana

Yanılmışım

Öyle yükseldiler ki 

Bizi ayırdıklarına ben bile inanamıyorum....', 'Yürüyoruz Oysa bilmiyorsun nereye ve ne için gittiğimizi Bilmiyorsun bana duyduğun güvenin sınırlarını Kafanı karıştırsada herşey soramıyors...', ARRAY['Türk Edebiyatı','Şiir','Alper Aydıncı']::text[], 8.5, '{"poet":"Alper Aydıncı","poet_slug":"alper-aydinci","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/dost-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saat 03: 02', 'saat-03-02-mahmut-ucakcan-gr1ip', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gecenin hain karanlığıydı

Bir şehir yıkıldı orada

Öyle bir yıkıldı ki

Sancısı beni vurdu.

Ateş topu düştü yüreğime

Yaktı tüm gençliğimi, çocukluğumu

İnsanlar ağlıyordu yitirdiklerine

Siyah beyaz şehre ağlıyorlardı

Ben insanlara ağlıyordum...

Bir çocuk bağırıyordu

Yıkıntıların altındaki annesine

Umutsuzca umutlanıyorlardı

Bir ses bekliyorlardı karanlığın içinde

Bir ses bekliyordum karanlığın içinden.

Ve yağmur yağıyordu

Çoktan sönmüş ümitleri küllendiriyordu

İnsanlar aç, telaşlı, korkuyorlardı

Korunacak yerleri yok diye

Ben insanlara korkuyordum.

Gecenin hain karanlığıydı

Bir şehir yıkıldı orada

Ve ben yıkılıyordum

Doğduğum şehirdi

SAKARYA...', 'Gecenin hain karanlığıydı Bir şehir yıkıldı orada Öyle bir yıkıldı ki Sancısı beni vurdu. Ateş topu düştü yüreğime Yaktı tüm gençliğimi, çoc...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Uçakcan']::text[], 8.5, '{"poet":"Mahmut Uçakcan","poet_slug":"mahmut-ucakcan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/saat-03-02-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gece Ve Aşk', 'gece-ve-ask-mahmut-ucakcan-om3nu', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sağ yanımda gece, 

Sol yanımda aşk var.

Geziyoruz ıssız sokaklarda

Bilmediğimiz, görmediğimiz

Köşebaşlarından geçiyoruz

Arıyoruz birşeyleri

Ama; 

Ne aradığımızı da bilmiyoruz...

Birbirimize bakıp gülüyoruz bazen

Hiç yorulmuyoruz

Hatta bazen koşuyoruz da

Deliler gibi eğleniyoruz.

Sağ yanımda gece

Sol yanımda aşk var, 

Ama sen yoksun! 

Gece üşütüyor

Aşk’sa incitiyor...

Sağ yanımda gece

Sol yanımda aşk var...', 'Sağ yanımda gece,  Sol yanımda aşk var. Geziyoruz ıssız sokaklarda Bilmediğimiz, görmediğimiz Köşebaşlarından geçiyoruz Arıyoruz birşeyleri ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Uçakcan']::text[], 8.5, '{"poet":"Mahmut Uçakcan","poet_slug":"mahmut-ucakcan","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gece-ve-ask-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Varmısın', 'varmisin-burhanettin-yilmaz-vfnld', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'VARMISIN

Varmısın; 

ikimizin olmayan ne varsa

herşeyi bir kenara bırakmaya, 

yeni bir yılda

yeni bir dünya kurmaya...

Varmısın; 

sadece varlığı

güzel günleri değil, 

acılarla...

       yoksulluklarıda

birlikte paylaşmaya.

Varmısın; 

önümüzdeki engeli yıkmaya

kendimizden, geçmişimizden

                hesap sormaya.......

Varmısın; 

senden benden sorumlu

yeni bir dünya kurmaya...

Varmısın; 

Ankaranın karanlıklarında

yaşanmamış sevgimizi aramaya...

Varmısın; 

dostların durduğu yerde

sırada durmaya...

Yüreklimisin arkadaş, 

       sen yüreklimisin? 

Varmısın; 

yalnız sana ve bana ait

bir gelecek için, 

herşeyi, ama herşeyi

göze almaya.

25.07.2001

         Burhanettin YILMAZ', 'VARMISIN Varmısın;  ikimizin olmayan ne varsa herşeyi bir kenara bırakmaya,  yeni bir yılda yeni bir dünya kurmaya... Varmısın;  sadece varl...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Yılmaz']::text[], 8.5, '{"poet":"Burhanettin Yılmaz","poet_slug":"burhanettin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":34,"source_url":"https://www.antoloji.com/varmisin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisan Yağmurumsun', 'nisan-yagmurumsun-gulcihan-atalay-fqvfn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nisan yağmurumsun

Islanıyorum ılık ılık seninle 

Nasıl uyanırsa toprak 

Tenimde uyanıyor bin yıllık uykuya dalan güller 

Kalbimin sesini duyuyor musun 

Yunuyor arınıyorum seninle 

Yeniden doğuşumu görüyor musun 

Nisan yagmurumsun 

Islanıyorum ışıl ışıl seninle 

Nasıl buğulanırsa yaprak 

Gözlerimde buğulanıyor yüreğimden taşan seller 

Karanlıkta uzanıyor sana 

Ellerimi görüyor musun... 

Nasıl uzak olabilirsinki 

Kollarimda sarıp sarmalarken seni

Öpsem gözlerini sen uykuya dalınca 

Doyamamki... 

Beni uçurumlarında bırakma 

Bırakma düşerim 

Yine de bırak düşeyim yürek yangınlarına... 

Gidersen birgün 

Gitme diyeyememki sana 

Sevdim derim 

Ben çok sevdim nisan yagmurlarını 

Eylül gelmese de olur 

Ey hüzünler simdi girin kanıma... 

Nisan yağmurumsun 

Havaya kızıl hareler salan soluğumsun... 

Gidersen bir gün git cigerparem 

Kırılsın kelebek kanadı elim kolum 

Küllerin kalsın bana yangınlarından 

Ben yine tutuşurum….', 'Nisan yağmurumsun Islanıyorum ılık ılık seninle  Nasıl uyanırsa toprak  Tenimde uyanıyor bin yıllık uykuya dalan güller  Kalbimin sesini duy...', ARRAY['Türk Edebiyatı','Şiir','Gülcihan Atalay']::text[], 8.5, '{"poet":"Gülcihan Atalay","poet_slug":"gulcihan-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/nisan-yagmurumsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
