INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstesem', 'i-stesem-mahmut-capar-ic7bn', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sana bişey söylemek istesem...

Söylemeden bilsen.

Ama yine de söylememi istesen...

Bunu söylerken yüzün kızarsa, utansan

Kaçırsan gözlerini gözlerimden...

Sonra yüzüme bakmadan ısrar etsen

Söylesem; yine yüzün kızarsa

Utansan ama; çok mutlu olsan

''EVET''demeyi istesen

ama; cevap veremesen...

Ellerimi uzatsam

Ürksen, sonra çeksen ellerini.

Biraz utangaç biraz sitemkar 

Gözlerime baksan

Hafiften gülüp, 

Yine gözlarini kaçırsan...', 'Sana bişey söylemek istesem... Söylemeden bilsen. Ama yine de söylememi istesen... Bunu söylerken yüzün kızarsa, utansan Kaçırsan gözlerini ...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/istesem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'bilinmez', 'bilinmez-mustafa-ekrem-gokceoglu-10brt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İnsanoğlu yaşar durur dünyada 

Ah mı çeker of mu çeker bilinmez

Bir tencere kaynar durur ocakta

Et mi kaynar dert mi kaynar bilinmez 

Bir bahtım var içi dışı karalı

Bir şansım var yüzü gözü yaralı

Bir yarim var onu bana sormalı

Taş mı kalpli boş mu kalpli bilinmez

Seven için gerçekte bir rüyada

Ne ümitler yarım kalır dünyada

Dökülürken dudaklardan elveda

Öz mü ağlar göz mü ağlar bilinmez', 'İnsanoğlu yaşar durur dünyada  Ah mı çeker of mu çeker bilinmez Bir tencere kaynar durur ocakta Et mi kaynar dert mi kaynar bilinmez  Bir ba...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Ekrem Gökçeoğlu']::text[], 8.5, '{"poet":"Mustafa Ekrem Gökçeoğlu","poet_slug":"mustafa-ekrem-gokceoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/bilinmez-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-sair-evindar-xfhau', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', '/belki bir avuntu....

belkide gerçek...

ne diyorsun sevgili...

bence bunu ZAMAN gösterecek................/

nerdesin...

kimsin..

nesin..

senin nerde olduğunu 

kim olduğunu

ne olduğunu bile bilmeden 

seni özlüyorum...

sen yoksun ya yanımda

yokluğun yokluğum oluyor

şu anki varlığım

beni hiçten gelen bir varlığa dönüştürüyor

sanki sen olunca 

hiçten gelen varlığım

vardan gelen benliğedönüşecekmişçesine

sensizliği bir daha asla istemeyecekmişçesine

hatta sensiz ölmeyecekmişçesine

bir umuda dönüşüyor

şu asi kalbim varya hani

hani seni bekleyen

o koskoca ama minicik

o yanan ama üşüyeno gülen halbuki ağlayan

o nefret bile edemeyen o varlık varya

sen yokken ne yapmadı ki

hep ama hep seni aradı

ama sen yoktun

dedim ya yerin belli değil

aradı... aradı...aradı...ve arıyor...............

insanlarda aradı, fikirlerde aradı

sen dediği üçüncü tekil şahıslarda aradı

ama O lar sen değildin..

O lar sen olmalıydın diye kandırdı kendni

O lar ile avundu

O lar için içini yaktı

gözyaşlarını içine akıttı

ama olmadı

ne O lar sen olabildiler

nede sen O larda olabildin

zaten asla öyle olmamalıydı

sen dediğim O lar sen değildiler

çünkü Oların yokluğunda hep seni buldum

seninle yaşamayı özlüyorum

seninle paylaşmayı

acıları ve sevinçleri

seninle tatmayı

balı ve zehiri

seninle görmeyi

cenneti ve cehennemi

seninle çıkmayı

karanlıktan aydınlığa

seninle yitirmeyi 

senin içine benliğimi 

benim içinde senliğini

)  seninle gerçekleşeceğini hayal bile edemiyorum ama(

seninle ölmeyi

zaten sensiz yaşadığım günleri 

ölümle bir tutuyorum

sensiz yaşım bile ilerlemiyor 

sende doğmak 

sende büyümek istiyorum........

bak sana ne kadar ihityacım var

sen yoksun ama

acaba seninde bana ihtiyacın varmı

sende benim gibi acılar çekiyormusun

sokakta kıslarda tek başına gezerken

en acılı günlerinde 

gözyaşını kimse silmezken

insan kalabalığının ortasında

kendini yapayalnız hissederken

mutlu saydığın günlerinde

sende beni

benim seni istediğim kadar 

yanında istiyormusun

sende beni özlüyormusun

sende arıyormusun yanında beni

elinin sıcaklığını avucumda hissettiğim gibi

sende elimin sıcaklığını hissediyormusun

aynı duygularda yoğunlaştığımıza eminim

çünkü biz bir elmanın iki yarısıyız

yani sen artı ben 

eşittir ''bir''iz

ne kadarda matematik reddetse

tüm kanunlar yalanlasa

ve bu çılgınlık hiç bir kitaba sığmasa

öyle ve öyle kalacak

SEN ARTI BEN

EŞİTTİR BİR......

belkide çok zor kavuşacağız seninle

çok zor olacak

dünya reddedecek ikimizi belkide

kitaplar töreler karşı çıkacak

belkide tam kavuşmuşken

kıyamet kopacak

ama sonunda elbet kavuşma olacak.....

sabır diyorum 

umut diyorum

gayret diyorum

dayan diyorum

ha gelecek 

ha geldi diyorum

yine sabır diyorum

yine bekliyorum

sen geldim işte demiyorsun

artık bitti demiyorsun

yeter çektiklerin demiyorsun

ve bana yine sabır

yine umut

ve yine acı çekmek kalıyor

seni arıyorum

BAŞKALDIRIYORUM

asileşip hırçınlaşıyorum

deli bir tay gibi 

etrafımı kırıp döküyorum

ama yine yoksun

UYSALLAŞAMIYORUM

kendi kendime zarar veriyorum

ne yapayım 

ne edeyim

nereye gideyim

bilmiyorum

seni bulamıyorum

neredesin gel artık....

DAYANAMIYORUM! ! ! ! ! ! ! ! ! ! ! ! 

nasılki bu ilham gecesi bitecekse 

bu yağmur dinecek

güneş yeniden doğacaksa

ve yine umut vaad edecekse

sabahın ilk ışıkları

bu çıldırtan sessizliğe 

karışacaksa hayatın eşsiz melodisi

herşey iyiye gidecekse

seni sensiz yaşamakta bitecek elbet

seni senle yaşayıp

sensiz acı çeken benliğimin yerine

senle benleşen benliğimi yaşayacağım

ve ben seninle mutluluğa kavuşacağım

dedim ya

sen yokken çoooook acı çekiyorum

ama acılar beni olgunlaştırıyor

yeterince olgunlaştıma inanıyorum

hadi elini uzat....

hadi gel...........................

                               BEKLİYORUM.....', '/belki bir avuntu.... belkide gerçek... ne diyorsun sevgili... bence bunu ZAMAN gösterecek................/ nerdesin... kimsin.. nesin.. sen...', ARRAY['Türk Edebiyatı','Şiir','Şair Evindar']::text[], 8.5, '{"poet":"Şair Evindar","poet_slug":"sair-evindar","theme":"Türk Şiiri","is_hero":false,"total_lines":146,"source_url":"https://www.antoloji.com/bekliyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Müslümân Evlâdı', 'muslum-n-evl-di-mustafa-engin-karatay-n8xrf', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ey Müslümân evlâdı, senin bir kimliğin var

Yırtma hayâ perdeni; koru, zînetindir ar! ..

Düşün şöyle güzelce, neyi taklid edersin? 

Koşturup dolu dizgin, hangi yöne gidersin? 

Allı pullu bu zevkler, boyamasın gözünü! 

Hepsi bir gün bitici, belle işin özünü! ..

Tatlı görünür sana, bir kaç günlük eğlence

Sonucunda bir kârın, oluşacak mı sence? 

Benzeme gâfillere, bu zümreden sayılma! 

Her gördüğün güzele, iç çekip de bayılma! 

Sev dürüstçe birini, buna engel olan yok

Aç gözlülük yaparsan, bulacağın zarar çok

Huzûr vardır helâlde, meyletme hiç harâma! 

Kaçırırsın keyfini, mâcerâ da arama! 

Sokaklarda sürtenin, neş''esi çok mu fazla? 

Belâyı buluyorlar, gittikleri bu gazla

Yosmalar, fırlamalar, ahlâkını bozmasın! ..

Mîsâl ol etrâfına, millet hepten azmasın! ..

Unutma; her hatânın, ceremesi çekilir

Yârın evlâdın azıp, tam karşına dikilir

İster misin onlar da, kurda kuşa yem olsun? 

Hayâtın bahârında, tüm ümidleri solsun? 

Nasıl Anan-Bacın''a, istemiyorsan kem söz, 

Kimsenin nâmusuna, dikme sakın sen de göz! ..

Efendice olursan, bilki dâim faydana...

Emînlikte hep yazdır, nasîbini paydana! ..

Bilir misin Rehberin, Muhammed-ül Emîn''di...

Her kes güveniyordu, sadâkati yemîndi...

Sen O''nun Ümmeti''ysen, bağlılığını göster! 

Sana can veren Allah, en başta bunu ister...

O Peygamber Kılavuz, Gönüllere Şifâ''dır...

Sünneti''ne uyman da, vazîfeyi îfâdır...

Boşver hayât geçici, sınırsız lezzeti seç! 

Doyumsuzlar uğruna, tadımlık olandan geç! 

Hûri-Gılmânlar hazır, hakedeni bekliyor...

İşlenen her sevâba, Mevlâ yeni ekliyor...

Orda bir düğün var ki, görülmemiş mîsâli

Kim arzulamaz ki, böyle tatlı vîsâli? 

Hayâli bile güzel, anlatmaya söz yetmez...

Şeb-i Ârûz esrârı, kimin hoşuna gitmez? 

15.08.2000     Landsberg      23: 50', 'Ey Müslümân evlâdı, senin bir kimliğin var Yırtma hayâ perdeni; koru, zînetindir ar! .. Düşün şöyle güzelce, neyi taklid edersin?  Koşturup ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":41,"source_url":"https://www.antoloji.com/musluman-evladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'N''olur Bağışla Beni', 'n-olur-bagisla-beni-mustafa-engin-karatay-n83ix', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hep isyânla geçirdim, vaktimi bunca zamân

Ne cürümler işledim, mel''ânetim pek yaman

Geldim, kapına durdum, dilenirim el-amân

Çok mahcûbum Yâ Rabbî, n''olur bağışla beni...

Söylenecek sözüm yok, varmaz ki buna dilim

Kabahâtlerim büyük, su götürmez bir milim

Karşında boyun büktüm, kaldırıp iki elim

Çok pişmânım Yâ Rabbî, n''olur bağışla beni...

Aczimi unutup da, Zâtın''ı hiçe saydım

Emrin''e aldırmayıp, dâim Nehyin''e kaydım

Nâdimim ama şimdi, günâhlarımdan caydım

Tevbekârım Yâ Rabbî, n''olur bağışla beni...

Mağlûb oldum nefsime, isteklerine kandım

Üç günlük hayât zevki, hiç bitmeyecek sandım

Boşa geçen günlere, bir âh çekip de yandım

Çok üzgünüm Yâ Rabbî, n''olur bağışla beni...

Âsî, dîvâneymişim; Buyrukların''a karşı

Yazık, aldattı beni, Dünyâ denilen çarşı

Gözümden akan yaşa, şâhid tuttum bak Arş''ı

Çok mahzûnum Yâ Rabbî, n''olur bağışla beni...

25.03.2001     Landsberg     05: 25', 'Hep isyânla geçirdim, vaktimi bunca zamân Ne cürümler işledim, mel''ânetim pek yaman Geldim, kapına durdum, dilenirim el-amân Çok mahcûbum Yâ...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Engin Karatay']::text[], 8.5, '{"poet":"Mustafa Engin Karatay","poet_slug":"mustafa-engin-karatay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/n-olur-bagisla-beni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Habersiz', 'habersiz-refik-recep-pelit-yzmru', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Habersizce Gitmeliyim,           

Kimseler duymamalı Gittiğimi     

Sesim boğulmalı Sessizlikte

Benden bir parça bulunmamalı     

Tenim yok olmalı Sensizliklerde

Yokluğum Fark edilmemeli 

Bilinmemeli ölüşümün sebebi

Arayanlar Acımamalı halime      

Ne çok sevdi dememeli iççekerek

Sebebini bir ben bilmeliyim     

Kendime bile itiraf edemesemde  

Bir ben, 

Bir de O!', 'Habersizce Gitmeliyim,            Kimseler duymamalı Gittiğimi      Sesim boğulmalı Sessizlikte Benden bir parça bulunmamalı      Tenim yok ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/habersiz-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilmiyorum', 'bilmiyorum-refik-recep-pelit-wnvrd', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu nasıl Aşk, Ne biçim bir sevda 

Seviyormuyum Sevmiyormuyum 

Özlüyormuyum Direniyormuyum 

Bilmiyorum 

Bu nasıl duygudur, Nasıl bir histir

Düşünüyormuyum, konuşuyormuyum 

Yaram kanıyormu, iyileşiyormu 

Bilmiyorum 

Bu nasıl kanattır, nasıl bir uçuştur

Göklerdemiyim yoksa sürünüyormuyum

Kırk yıllık Bir özlemmi yoksa kaçışmı

Bilmiyorum 

Bu nasıl hayattır, Nasıl bir varoluştur 

Bunca yıl yaşamışım, görmüşüm

Yaşıyormuyum, yoksa bir ölümüyüm 

Bilmiyorum 

Bu nasıl Dünyadır, Nasıl Bir mekan 

Rüyadamıyız yoksa kabuslardamıyız 

Bilmiyorum!', 'Bu nasıl Aşk, Ne biçim bir sevda  Seviyormuyum Sevmiyormuyum  Özlüyormuyum Direniyormuyum  Bilmiyorum  Bu nasıl duygudur, Nasıl bir histir D...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bilmiyorum-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefasız', 'vefasiz-oguz-yener-bayazit-ye6h9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ey vefasız! 

Bir gün sana 

“Şimdiye kadar kim seni en çok sevdi ”

Diye sordukları zaman, 

Yüzün kızarmadan, kekelemeden

Kalbinin sesini dinlemeyerek

Ve gerçekleri hiçe sayarak

Beni değil de, 

Beraber olduğun kişiyi 

SÖYLEYEBİLECEKMİSİN!', 'Ey vefasız!  Bir gün sana  “Şimdiye kadar kim seni en çok sevdi ” Diye sordukları zaman,  Yüzün kızarmadan, kekelemeden Kalbinin sesini dinl...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vefasiz-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerinde', 'gozlerinde-oguz-yener-bayazit-hgf7n', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir akşam 

Gözlerinde kayboldum.

Derinlere, ta derinlere çekti beni

Bir girdap misali.

Gözlerinde kayboldum! .

Hiç bir şikayetim yoktu.

Bağırmadım, korkmadım.

Ben sonsuza kadar

Gözlerinde kaybolmaya RAZIYDIM! .....', 'Bir akşam  Gözlerinde kayboldum. Derinlere, ta derinlere çekti beni Bir girdap misali. Gözlerinde kayboldum! . Hiç bir şikayetim yoktu. Bağı...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozlerinde-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Gün', 'bir-gun-oguz-yener-bayazit-7arqn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir gün sende sevmesini öğreneceksin.

Bir gün  seninde kalbini çevreleyen duvarlar yıkılacak.

Geçmiş yıllarından arta kalan, 

Sadece BOMBOŞ ANILARIN OLACAK! ....', 'Bir gün sende sevmesini öğreneceksin. Bir gün  seninde kalbini çevreleyen duvarlar yıkılacak. Geçmiş yıllarından arta kalan,  Sadece BOMBOŞ ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bir-gun-17-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben De Mi?', 'ben-de-mi-oguz-yener-bayazit-cxkij', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ayın şavkı vuruyor denize

İnsanlar gülüp eğleniyor.

Seni düşünüyorum yine.

Ve aniden bir damla düşüyor

Gözlerimden denize.

Efkarımı dağıtmıyor şu içtiğim  sigara

Şu denize fırlattığım taş, 

Denizin üzerinde uçan martılar; 

Ve bilmiyorum bu kocaman şehirde

Sadece ben de mi HÜZÜN VAR! ....', 'Ayın şavkı vuruyor denize İnsanlar gülüp eğleniyor. Seni düşünüyorum yine. Ve aniden bir damla düşüyor Gözlerimden denize. Efkarımı dağıtmıy...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ben-de-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen De', 'sen-de-oguz-yener-bayazit-q5awa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorum sen de gideceksin

Biliyorum terk edeceksin.

Geçmiş günleri hiçe sayarak, 

Ve o güzelim anları unutarak

Biliyorum sen de gideceksin

Biliyorum terk edeceksin.

Beni umursamayacak

Ve yaramın üstüne tuz basacaksın.

Biliyorum gideceksin

Ve biliyorum asla 

Geri dönmeyeceksin.', 'Biliyorum sen de gideceksin Biliyorum terk edeceksin. Geçmiş günleri hiçe sayarak,  Ve o güzelim anları unutarak Biliyorum sen de gideceksin...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/sen-de-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Daha Dün', 'daha-dun-oguz-yener-bayazit-x5uoa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Daha dün sen vardın, ellerin vardı

Bugün sensizlik var, hüzün var

Ne kadar çabalarsam çabalayayım.

Sana çıkmıyor bütün yollar.

Daha dün sen vardın gözlerin vardı

Bugün sadece hayalin var

Her zaman buluştuğumuz sahildeki

O çay bahçesine

Uğramaz oldu martılar

Daha dün sen vardın, gülüşün vardı

Bugün sadece suretin var 

Sessizliğin akıl almaz sancısını

Dindiremiyor eski mektuplar.', 'Daha dün sen vardın, ellerin vardı Bugün sensizlik var, hüzün var Ne kadar çabalarsam çabalayayım. Sana çıkmıyor bütün yollar. Daha dün sen ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/daha-dun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidiyorsun...', 'gidiyorsun-oguz-yener-bayazit-7m4hk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidiyorsun, 

Beni böyle bir başıma  sevgisiz

Ve yapayalnız bırakarak gidiyorsun.

Başımı duvarlara vuruyorum.

Tırnaklarımla yolları deşiyorum, 

KALMIYORSUN.

Gidiyorsun, 

Beni çaresizliğin kucağına atıp, 

Vicdansızlığının ''üstüne basa basa'' 

Gidiyorsun! .....', 'Gidiyorsun,  Beni böyle bir başıma  sevgisiz Ve yapayalnız bırakarak gidiyorsun. Başımı duvarlara vuruyorum. Tırnaklarımla yolları deşiyorum...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gidiyorsun-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şehir', 'bu-sehir-oguz-yener-bayazit-i4b0d', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu şehir, bu şehir ki her vakit

Bana seni hatırlatıyor, 

Anıları hançer edip

Bir bir kalbime saplıyor.

O zaman 

BU ŞEHİRDE DURULMAZ ARTIK! ...', 'Bu şehir, bu şehir ki her vakit Bana seni hatırlatıyor,  Anıları hançer edip Bir bir kalbime saplıyor. O zaman  BU ŞEHİRDE DURULMAZ ARTIK! ....', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bu-sehir-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelmedin', 'gelmedin-oguz-yener-bayazit-0qc2u', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şimdi fırtınalar var yüreğimde

Sağanak yağmurlar, hiç durmayan rüzgarlar.

Bir tufan kopuyor içimde

Mevsimlerden kışı yaşıyor yüreğim

Oysa ben seninle en güzel, 

İlkbaharı yaşamak isterdim.

Yeni tomurcuklanan bir çiçek

Bemberrak suları olan, masmavi bir deniz gibi.

Ama şimdi; 

Dalga dalga büyüyor yalnızlığım.

Her sahile anılarımdan bir parça vuruyor.

Bağrışıyor martılar

Zemheriyi yaşıyorum bu güzel ilkbaharda.

Yitirdim anıları, 

Veda ettim şansıma, 

Gözlerim yolarda 

Hep senin gelmeni bekledim.

Gurbetten geriye dönüş gibi, 

Asırlık yalnızlığın bitişi gibi.

Bilmedin nasıl özlediğimi seni, 

GELMEDİN, GELEMEDİN! .....', 'Şimdi fırtınalar var yüreğimde Sağanak yağmurlar, hiç durmayan rüzgarlar. Bir tufan kopuyor içimde Mevsimlerden kışı yaşıyor yüreğim Oysa be...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/gelmedin-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen', 'sen-oguz-yener-bayazit-zjvkb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yanlış zamanların 

Yanlış kızısın; 

Sen ölümcül bir hastalığın

Son safhasısın! ..', 'Sen yanlış zamanların  Yanlış kızısın;  Sen ölümcül bir hastalığın Son safhasısın! .....', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sen-96-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilirmisin?', 'bilirmisin-oguz-yener-bayazit-8mcen', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ayrılığın acısını bilirmisin.

Bilirmisin haydi söyle.

Yemeden içmeden kesilirsin aniden, 

Bir hançer saplanır yüreğine.

Sen çaresizliği bilirmisin, 

Bilirmisin haydi söyle.

Elin kolun bağlanır da 

Söz geçiremezsin geceye.

Sen ümit etmesini bilirmisin, 

Bilirmisin haydi söyle: 

Bütün ümitlerini yıkıp ta gittiğinde 

Ardından bakakalırsın öylece.

Sen ağlamayı bilirmisin, 

Bilirmisin haydi söyle.

Göz pınarların kuru gider de, 

Yine de ardından ağlarsın her gece.

Sen hastalık nedir bilirmisin? 

Bilirmisin durma söyle.

Bu acılarla dertlere merhaba dersin de, 

Yine de şikayetin olmaz giden sevgiliye.

Sen hiç düşündün mü beni, 

Düşündün mü durma söyle.

Yirmisinde bir insan nasıl otuzunda gösterir, 

Ve nasıl hala ayakta kalabiliyor diye! ....', 'Sen ayrılığın acısını bilirmisin. Bilirmisin haydi söyle. Yemeden içmeden kesilirsin aniden,  Bir hançer saplanır yüreğine. Sen çaresizliği ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/bilirmisin-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne İstediler', 'ne-i-stediler-oguz-yener-bayazit-s1c8j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Önce çocukluğumuzu vurdular.

Sonra düşlerimizi.

Umutlarımızı zaten yitirmiştik.

Baharın da sinsice bir cinayete kurban gittiğini

Haber verdiler arkadaşlarım.

Neydi peki bizden istedikleri? 

Ya o cıvıl cıvıl, 

O insanın başını döndüren 

Bütün aşkların başlangıç zamanı

BAHAR dan ne istemişlerdi?', 'Önce çocukluğumuzu vurdular. Sonra düşlerimizi. Umutlarımızı zaten yitirmiştik. Baharın da sinsice bir cinayete kurban gittiğini Haber verdi...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-istediler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle Olur', 'boyle-olur-oguz-yener-bayazit-8dwmu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Böyle olur gariplerin kutlaması

Sessiz bir hıçkırık misali

İçten içe tükenirsin

Etrafını sarar yalnızlığın 

Görünmeyen duvarları! 

Herkes neşe içindeyken

SEN AĞLARSIN! 

Hem de delicesine.

Bir yumak düğümlenir boğazında, 

YUTKUNAMAZSIN! 

Havada çıldırtan bir sessizlik vardır

Ve yüreğinde bin bir  öfke

Hayata ve BİTMEYEN GECEYE!', 'Böyle olur gariplerin kutlaması Sessiz bir hıçkırık misali İçten içe tükenirsin Etrafını sarar yalnızlığın  Görünmeyen duvarları!  Herkes ne...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/boyle-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelirmisin?', 'gelirmisin-oguz-yener-bayazit-26wrq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ve ihanet oldu ayrılıklar, 

Çekilmez bir dert oldu sensizlik.

Bir son, bir çıkmaz sokak.

SEN YOKSUN ARTIK! 

Düşünmek  getirir mi ki seni? 

Gelirmisin 24 saat düşünsem seni? 

Atılırmısın kollarıma yine 

Eski günlerimizdeki gibi.

Ferhat gibi dağları delsem, 

Kerem gibi yolara düşsem

GELİRMİSİN? 

Yine sıcacık sevgini bana verirmisin?', 'Ve ihanet oldu ayrılıklar,  Çekilmez bir dert oldu sensizlik. Bir son, bir çıkmaz sokak. SEN YOKSUN ARTIK!  Düşünmek  getirir mi ki seni?  G...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gelirmisin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bana Sor', 'bana-sor-oguz-yener-bayazit-xk3bo', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kıyıya vuran hırçın dalgalar 

İsmini fısıldıyor.

Ay, gökyüzünden senin o tatlı yüzün gibi

Bana gülümsüyor.

Bu nasıl sensizlik, 

Bu nasıl cehennem, 

Bu nasıl bir ızdırap? 

Gel de bana sor.

Dost görünüp gelenleri, 

Kalleşlik yapıp gidenleri, 

Sadece iş olsun diye sevenleri

Gel sen bana sor! 

Senden başka kimse bilmez 

SENİ NASIL SEVDİĞİMİ; 

İstersen eğer yoluna, 

Canımı vereceğimi!', 'Kıyıya vuran hırçın dalgalar  İsmini fısıldıyor. Ay, gökyüzünden senin o tatlı yüzün gibi Bana gülümsüyor. Bu nasıl sensizlik,  Bu nasıl ceh...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bana-sor-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hoşgeldin', 'hosgeldin-oguz-yener-bayazit-z6ud7', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hoş geldin gözbebeğim

Gözüm yollarda kaldı

Sensizlik korkusu içimi sardı.

Nerdeydin, neredeydin? 

Kimleydin kiminleydin? 

Bilmedim gözbebeğim, 

SENİ, SENİ ÖZLEDİM.

Sensizlik çok zor geldi, 

İnan ki canım bana

Gülüşünü özledim, 

Seviyorum, ANLASANA! 

Bırakma ne olur beni

Yeniden tut ellerimi, 

Bırakma ne olur beni, 

Yeniden ver sevgini.', 'Hoş geldin gözbebeğim Gözüm yollarda kaldı Sensizlik korkusu içimi sardı. Nerdeydin, neredeydin?  Kimleydin kiminleydin?  Bilmedim gözbebeği...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hosgeldin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Boş Boş', 'bos-bos-oguz-yener-bayazit-spukz', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Boş boş bakıyorum hayata 

Çıkarsızca, umarsızca

Rezillikler arenasında

Hiç tepki göstermiyorum.

Boş ver diyorum, boş ver dünyayı, 

Hangi kapıya gitsem

Karşımda  bir yüz yalancı, 

Ve ben yine çaresiz

Hangi yüze baksam

Sinsi, çıkarcı

Ve ben yine yalnız....', 'Boş boş bakıyorum hayata  Çıkarsızca, umarsızca Rezillikler arenasında Hiç tepki göstermiyorum. Boş ver diyorum, boş ver dünyayı,  Hangi kap...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bos-bos-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin İçin', 'senin-i-cin-oguz-yener-bayazit-m8n89', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tüm yaptıklarım senin içindi.

Güzel gözlerin için.

Çocuk kalbinde sakladığın güzellikler içindi

Hangi gün seni görsem; 

BİR YILDIZ KAYARDI YÜREĞİMDEN! 

Gündüzleri hep sen vardın

Geceleri hep sen.

Gün yirmi dört saatti, 

YİRMİ DÖRT SAAT YALNIZ SEN! 

Her şey senin içindi

Kafamı yastığa her koyduğumda, 

Kalabalığın ortasında, çıldırtan yalnızlığımda

Seni görürdüm, 

SANA MUHTAÇ OLDUĞUM EN ZOR ANIMDA! 

Her şey senin içindi.

Yaptığım her işte, okuduğum her kitapta, 

Ve ağladığım da  akan her gözyaşımda

SEN VARDIN! 

Her şey senin içindi.

Güzel gözlerin için.

Çocuk kalbinde sakladığın, 

Ve benden başka hiç kimsenin bilmediği

Güzellikler içindi.

Hangi gün seni görsem, 

YÜREĞİMDEN BİR YILDIZ KAYARDI.

Çocuklar gibi sevinirdim, 

İÇİM İÇİME SIĞMAZDI! ...', 'Tüm yaptıklarım senin içindi. Güzel gözlerin için. Çocuk kalbinde sakladığın güzellikler içindi Hangi gün seni görsem;  BİR YILDIZ KAYARDI Y...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/senin-icin-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beklenen Hasret', 'beklenen-hasret-oguz-yener-bayazit-kz8pb', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bilmem bu kaçıncı yargılanışım? 

Boşuna mı sevdim ben bu dayanılmaz acıyı.

Her seferinde hasret ve özlem, 

Her seferinde tonlarca umut: 

DİZBOYU! 

Artık sonuna geldik ey! martıların 

Feryad-ı figan çığlıkları

Yine aynı sabah, 

Yine aynı yerden doğup

İçimize yaşama isteği dolduran

O sıcacık, o iyimser güneş

Doğmayacak artık! 

Usulca batarken sevgililerin sarmaş dolaş

Bakışları arasında

Belki daha değişik iklimlere, 

Daha iyi insanlara yol alırken, 

Seni son bir kez daha

Görememek gerçeği

Yakıp kavuruyor beynimi.

Biliyorsun şimdi uzaktayım, 

Geri dönüşü olmayan; 

BERBAT BİR YOLDAYIM! ...', 'Bilmem bu kaçıncı yargılanışım?  Boşuna mı sevdim ben bu dayanılmaz acıyı. Her seferinde hasret ve özlem,  Her seferinde tonlarca umut:  DİZ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beklenen-hasret-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Olursun', 'ne-olursun-oguz-yener-bayazit-biqow', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hep o şirinliğinde kal olur mu? 

Gül yanağında güller açsın.

Öyle tatlı gülme ne olursun, 

ÖLÜRÜM BAK, SEBEBİM OLURSUN!', 'Hep o şirinliğinde kal olur mu?  Gül yanağında güller açsın. Öyle tatlı gülme ne olursun,  ÖLÜRÜM BAK, SEBEBİM OLURSUN!...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/ne-olursun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-oguz-yener-bayazit-tvqgn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hasretin bağrında bir garip adamım ben

Her seferinde 

Taştan bir kalbim olduğumu sanırlar, 

Oysa benim özlediğim, tatlı mı tatlı 

BİR SEVGİLİM VAR! 

Görmeyeli sanki bin yıl olmuş

Ayrılalı kaç yüzyıl geçmiş

Ama yine de

Unutmadım  onunla ilgili hiçbir şeyi.

NASIL UNUTURUM Kİ?', 'Hasretin bağrında bir garip adamım ben Her seferinde  Taştan bir kalbim olduğumu sanırlar,  Oysa benim özlediğim, tatlı mı tatlı  BİR SEVGİL...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hasret-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ansızın', 'ansizin-oguz-yener-bayazit-dzrkq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Her zaman içimde garip bir his, 

Ansızın çekip gelecekmişsin gibi.

Hayalin içimde bir nefes, 

Çekersem bitecekmişsin gibi.

Sensiz hayat bana cehennem oldu

Gül benzim sarardı soldu

Biliyorum  o alaycı gülüşün, 

Çok acımasız bir oyundu.', 'Her zaman içimde garip bir his,  Ansızın çekip gelecekmişsin gibi. Hayalin içimde bir nefes,  Çekersem bitecekmişsin gibi. Sensiz hayat bana...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ansizin-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerime Bak!', 'gozlerime-bak-oguz-yener-bayazit-n93y8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözlerime bak birtanem.

İçinde fırtınalar kopan gözlerime.

İki gönül ayrılık rüzgarına kapılırken

Ve ortasında gecenin hıçkırarak ağlarken! 

Gözlerime bak! 

Çaresizce beklerken sonumuzu

Hep iyiye dair düşler kurarken

Yeni doğmuş bebek saflığında

Ve onca engeller karşısında umutla: 

Gözlerime bak birtanem! 

Ellerimi tut birtanem.

Nicedir süregelen bu yalnızlığımda

Geçmişe dair kötü izler taşırken

“ Yok et ” senden önceki hayatımı: 

Ellerimi tut birtanem! 

Üzüntülerimi sevince dönüştür, 

Çaresizliği umuda

Sevgine en muhtaç olduğum

Şu anda: 

Ellerimi tut birtanem! 

Bana sıkıca sarıl birtanem.

Yalnızlıktan bu denli korkarken

Ve uzunca bir ayrılığa

Bu kadar yaklaşmışken: 

BANA SIKICA SARIL BİRTANEM! ...', 'Gözlerime bak birtanem. İçinde fırtınalar kopan gözlerime. İki gönül ayrılık rüzgarına kapılırken Ve ortasında gecenin hıçkırarak ağlarken! ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/gozlerime-bak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-oguz-yener-bayazit-ztvmp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Vakit çoktan geçti

Kimsecikler kalmayacak

Sen de git ötekiler gibi, 

Bırak ne olursun beni bırak.

Ellerimde akıp giden zaman

Bir tek sen varsın eskiden kalan

Değişse her şey  ben değişemem inan

Zaman her şeyin İLACI zaman.

Düşünüp durma kararını ver hemen

Baksana geriye dönmüyor giden.

Ne arayan var ne soran, 

Zaman her şeyin SAHİBİ zaman.

Söyleme hiç bir şeyi, ya da ben duymayayım

Bari senin gidişini görmeyeyim.

Her şeye rağmen hala ayaktayım

Zaman, her şeyin UMUDU zaman.

Dertlerime çare bulamadım ki! 

Senden başkasına hiç bakmadım ki! 

Eğer sen de gideceksen DURMA ÖLDÜR BENİ! 

Zaman, her şeyin KATİLİ zaman.

İşte gidiyorsun mutluluğu sana bıraktım.

Dertleri, kederleri kendime ayırdım.

Ne yazık ki en son sende yanıldım, 

ZAMAN: CANIMA KASTEDEN ZAMAN! ....', 'Vakit çoktan geçti Kimsecikler kalmayacak Sen de git ötekiler gibi,  Bırak ne olursun beni bırak. Ellerimde akıp giden zaman Bir tek sen var...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/zaman-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilemedim', 'bilemedim-oguz-yener-bayazit-w4bk6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Senin için gözyaşı döktüm gecelerce

İsmini haykırarak uykulardan uyandım.

İyi kötü kızlar tanıdım yüzlerce

Hiç birinde  aradığım aşkı bulamadım.

Bir tek seni sevmiştim bak bir anda kaybettim.

Belki dönersin diyerek aylarca bekledim.

Kalbin taştanmış meğerse, 

Bak senin yüzünden ne hale geldim.

Şimdi yanıyorum senin için ağladığım gecelere, 

Yavaş yavaş onarıyorum kırık kalbimi

Oysa ki sen bilmiyordun bir sözünle

Hayatıma bile SONVEREBİLECEĞİMİ! 

Artık eskide kaldı bütün bunlar

Ne kadar aptalmışım diyorum şimdi kendime

Aylarca, boşu boşuna bir sevgiye

Her şeyimi vermişim bilmem ki niye?', 'Senin için gözyaşı döktüm gecelerce İsmini haykırarak uykulardan uyandım. İyi kötü kızlar tanıdım yüzlerce Hiç birinde  aradığım aşkı bulama...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bilemedim-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şiir', 'siir-oguz-yener-bayazit-f5k05', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Solgun renkli bir sonbahar akşamı gibi geçiyor

Ömrümüzün en güzel geçmesi gereken yılları.

Hatırlanacak pek fazla

Güzel anılarımız yok bizim.

Sadece diğerlerinden 

Biraz daha az acılı geçen günlerimizden, 

“En kötü günümüz böyle olsun”

Avuntularıyla süslü, 

“Buna da şükür” demekle yetindiğimiz, 

Zaman zaman da, 

“Mutlaka ileride başaracağım” diye

Kendimizi kandırdığımız günleri

HATIRLAYABİLECEĞİZ! ...', 'Solgun renkli bir sonbahar akşamı gibi geçiyor Ömrümüzün en güzel geçmesi gereken yılları. Hatırlanacak pek fazla Güzel anılarımız yok bizim...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/siir-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburmuyduk?', 'mecburmuyduk-oguz-yener-bayazit-ezr1y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Biz bu ayrılığa söyle mecburmuyduk? 

Bak şimdi iki yabancı olduk.

Ölüm geldi senden böyle ayrılmak

Biz bu ayrılığa söyle mecburmuyduk? 

Dün gece düşündüm yine seni

Dün gece hep haykırdım ismini

Hani biz böyle de çok mutluyduk

Biz bu ayrılığa söyle mecburmuyduk? 

Kimin ne hakkı vardı söz söylemeye

Bizi birbirimize düşman etmeye

Hani seninle çok mutluyduk, 

Biz bu ayrılığa söyle mecburmuyduk? 

Hiç yoktan bir sebepten bu ayrılık niye

Sen yolunu seçtin, git güle güle

Sevginin yerine nefret koyduk, 

BİZ BU AYRILIĞA SÖYLE MECBURMUYDUK?', 'Biz bu ayrılığa söyle mecburmuyduk?  Bak şimdi iki yabancı olduk. Ölüm geldi senden böyle ayrılmak Biz bu ayrılığa söyle mecburmuyduk?  Dün ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/mecburmuyduk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yaralı Kalp', 'yarali-kalp-oguz-yener-bayazit-9otmq', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hüzünlendi şiirler ağladı şarkılar

Issız kumsalda boynu bükük kaldı martılar

Duruverdi tepemizde, gitmedi kara bulutlar

Dostlar bana onu sorar, benim yüreğim ağlar.

Bilmedi hiç kimse vazomda güller niye soldu

Gönül bahçem dağıldı, dağıldı yok oldu

Bahçemden geriye bir yaralı kalp kaldı

Gönüller birleşemedi, hasret

HASRET DOĞDU! ...', 'Hüzünlendi şiirler ağladı şarkılar Issız kumsalda boynu bükük kaldı martılar Duruverdi tepemizde, gitmedi kara bulutlar Dostlar bana onu sor...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yarali-kalp-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Döndüm İşte', 'dondum-i-ste-oguz-yener-bayazit-s1lcq', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Döndüm işte! 

Hiç gelmeyeceğimi sanıyordun değil mi? 

Her şeyi unutacağımı sanıyordun.

Bütün imkansızlıkları aşıp ta geldim.

Yağmurlar yağarken, 

Fırtınalar koparken

Herkes kaçacak bir delik ararken

Ben şimşeklere tutunup ta geldim.

Gözlerim kör oldu göremedim yolu, 

Bir damla bulamadım  içecek suyu.

Düşmanlarım yollarıma kazdılar kuyu, 

Ama yine de vazgeçmedim; 

GELDİM İŞTE! 

Kă h bir gemide yelkendim

Kă h rengă renk bir çiçek.

Yine de sabretmesini bildim

Buradayım işte.

Şimdi sen yan kendi haline, 

Ben sevineceğim, 

Hayatıma kaldığım yerden

Devam edeceğim! ...', 'Döndüm işte!  Hiç gelmeyeceğimi sanıyordun değil mi?  Her şeyi unutacağımı sanıyordun. Bütün imkansızlıkları aşıp ta geldim. Yağmurlar yağar...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/dondum-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Defa', 'i-lk-defa-oguz-yener-bayazit-67fxq', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk defa başıma geliyor bu

İlk defa böyle delice özlüyorum.

Anlıyorum hasret acısını

Konuşamamanın sancısını

Özlemin o garip tadını

ANLIYORUM! ...', 'İlk defa başıma geliyor bu İlk defa böyle delice özlüyorum. Anlıyorum hasret acısını Konuşamamanın sancısını Özlemin o garip tadını ANLIYORU...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ilk-defa-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasretimsin', 'hasretimsin-oguz-yener-bayazit-06syb', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O güzelim kumral saçların

Kaç kere vurmuştur beni en derinden

O güzelim gözlerin ise

Kaç gece zorla fitil gibi içmeme sebep olmuştur (istemeden) 

İçin için yanarken kalbim

Dur durak bilmeden süren hasretim

Hain gecelerde bozguna uğramıştır.

SUÇLUDUR KALBİM! 

Çünkü o hain gecelerde 

Şeytana uyarak

SENİ UNUTMAK İSTEMİŞTİR! 

Bu yüzden sevmiyorum artık

Gece gelen hüzün saatlerini.

Velhasıl gene geldi çattı

Hasretine mısra dökmek zamanı.

Yokluğun başlı başına bir dert oldu bana

Benimle beraber hayal dünyasına

Mutluluk rüyasına gelirmisin? 

Bugün ya da yarın fark etmez; 

Unutma HASRETİMSİN! ...', 'O güzelim kumral saçların Kaç kere vurmuştur beni en derinden O güzelim gözlerin ise Kaç gece zorla fitil gibi içmeme sebep olmuştur (isteme...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/hasretimsin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkların Ötesinde', 'asklarin-otesinde-selcuk-gulnar-d5mte', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tanıdığım ilk günde		

Şimşek çaktı kalbimde		

Kurtulmaya çare yok		

Aşkı tatmaktan başka		

		

Büyülendim görünce		

Bakışında kayboldum		

Hayran kaldım gözlerine		

Maviliklerde buluştum		

		

Kirpiğin değince zülfüne		

Kalbimin derinliklerinde		

Kaynar volkan oldum		

Aşkların ötesinde', 'Tanıdığım ilk günde		 Şimşek çaktı kalbimde		 Kurtulmaya çare yok		 Aşkı tatmaktan başka		 		 Büyülendim görünce		 Bakışında kayboldum		 Hay...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Gülnar']::text[], 8.5, '{"poet":"Selçuk Gülnar","poet_slug":"selcuk-gulnar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asklarin-otesinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Arıyorum', 'seni-ariyorum-oguz-yener-bayazit-ha159', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Seni arıyorum yine

Uzak şehirlerde

Issız limanlarda

Ve bir çocuk ağlamasında.

Seni arıyorum yine

Ağaç dallarında

Hoş çiçek kokularında

Sonu olmayan yollarda

Seni arıyorum

Anlamadığım dillerin konuşulduğu

Bilmediğim ülkelerde

Hani kafamı çevirsem

Seni görecekmiş gibi oluyorum.

Bilinçsizce geziniyorum

Bir çiğ tanesisin sanki

Seni bir an önce bulamasam

Eriyip gideceksin diye düşünüyorum.

Olmuyor, bulamıyorum.

Ne yapsam ne etsem çaresiz kalıyor

Elimden bir şey gelmiyor

BİLMİYORUM! 

Seni arıyorum.

Hiç bıkmadan usanmadan.

Bir gün mutlaka bulacağım diyorum.

Oysa ki farkındayım

KENDİMİ KANDIRIYORUM! 

Seni arıyorum.

Bütün hayatımı seni bulmaya adıyorum.

Ama hiç kimsenin umurunda değil

Ve hayat bunlara rağmen

Ne yazık ki devam ediyor

BİTİP TÜKENİYORUM!', 'Seni arıyorum yine Uzak şehirlerde Issız limanlarda Ve bir çocuk ağlamasında. Seni arıyorum yine Ağaç dallarında Hoş çiçek kokularında Sonu ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Yener Bayazıt']::text[], 8.5, '{"poet":"Oğuz Yener Bayazıt","poet_slug":"oguz-yener-bayazit","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/seni-ariyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatamazlar Seni', 'anlatamazlar-seni-selcuk-gulnar-nr8ef', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Anlatamaz seni bana		

Hiçbir nesne		

Senin gözlerin kadar		

		

Ne çiçek ne de gül		

Anlamsız kalır		

Kollarını açıp sarıldığın zaman		

		

Hoş geldin deyip 		

Öptüğünde		

Aşkı tadıyorum her		

nefesinde		

		

Kalbindeki çarpıntıyı 		

Duyuyorum		

Yıllarca uzaklarda 		

Olduğunda bile', 'Anlatamaz seni bana		 Hiçbir nesne		 Senin gözlerin kadar		 		 Ne çiçek ne de gül		 Anlamsız kalır		 Kollarını açıp sarıldığın zaman		 		 Ho...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Gülnar']::text[], 8.5, '{"poet":"Selçuk Gülnar","poet_slug":"selcuk-gulnar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/anlatamazlar-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tanıştığım Gün', 'tanistigim-gun-selcuk-gulnar-wm1xe', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hatırlıyor musun sevgilim			

İlk tanıştığımız günü			

Hani sana merhaba demiştim de			

Bir ok fırlatmıştın kalbime			

			

Fırtınalar kopmuştu içimizde			

Farkında olmadan			

Aşka düştüğümüzden 			

Gülümsemiştik birbirimize			

			

İşte o günden sonra			

Tiryakisi oldum gözlerinin			

Dudaklarındaki gülümsemenin			

Bakışlarındaki anlamın			

			

Her yerde, 			

Bana bakan her gözde			

Seni aradım, mümkün olmadı			

Senin gibi bir göz bulamadım			

			

Kalbimde büyüyen kor			

Büyüdükçe büyüdü			

Sahip olamadım artık			

Ne kendime, ne de alevlere			

			

Hani bülbül gülden 			

Ayrılmaz ya.			

İşte ben de kendimi 			

Ayıramadım senden			

			

Gizlemek istedim kimseler			

Duymasın diye			

Baktım ki etrafıma			

Sadece ben varım beni görmeyen			

Herkes seni görmüş benden...			

			

Seni anlatıyorum			

Seni dinliyorum			

Şarkılarım sen			

Müziğim sen			

Aşkım sen olmuşsun			

			

Sana bağlanmışım		

Seni sayıklıyorum uyanıkken bile		

Alkolik oldum yıllarca		

Bakışınla sunduğun şarapla		

		

Seninle bir dakika		

Göz göze gelelim bir kere		

Merhaba diyelim, yeter ki		

Seni göreyim.		

Dilersen ömrümü vereyim.		

		

Seninle aşktan bahsetmek		

Çok sınırlı gelirdi 		

Oysaki sen 		

Aşkların ötesinde		

Kalbimin en güzel köşesindesin		

		

Bakamam senden başkasına		

Göremem kimseyi		

Sen benim varlığım 		

Sen benim yokluğum		

Sen benim aşkımsın		

		

Hani sokak lambasının		

Etrafında dönen kelebekler var ya		

Sevgilim, öleceklerini bile bile		

Pervane olurlar ışığın		

etrafında		

İşte benim ışığım sensin		

Etrafında pervane olup 		

Senin için öleceğim günü		

Sabırla bekliyorum.		

		

Kör oldum aşk ateşinde		

Görmez oldu gözlerim			

Duymuyorum sözleri			

Senin dudaklarından çıkan			

İnciden başka			

			

Büyülendim sana 			

Sarhoşum her an			

Uçar gibiyim			

Yürürken yollarda bile			

Gözlerinle buluşmayı			

Anlatamam hiçbir duyguyla			

Seni ayrılırken izlemeye			

Dayanamaz gözlerim			

Görmek istemem hiçbir zaman 			

Sana veda ettiğimi			

			

Aldığım her nefeste sen varsın			

Vurdun kalbimden			

Bilmiyorum farkında mısın			

			

Hatırlar mısın seni aradığımı			

Güldü gözlerim duyunca sesini			

			

Sensiz olmak zor			

İçtiğim her yudumda sen			

Sensiz yürümek zor			

Geçtiğin bu yollarda			

			

Seni bekliyorum

Gecenin sessizliğinde

İçimde korku

Merakla bakıyorum maviliğe

Üzerime gelen her dalga

Islatıyor bedenimi

Farkında bile olmuyorum

Senin sıcaklığını duyuyorum

Dalgaların sesinde

Rüzgarın fısıltıları

Seni anlatıyor bana

Dudaklarındaki sıcaklığı

Nefesindeki ılıklığı

Tüm çıplaklığı ile

Vücudunu dinliyorum', 'Hatırlıyor musun sevgilim			 İlk tanıştığımız günü			 Hani sana merhaba demiştim de			 Bir ok fırlatmıştın kalbime			 			 Fırtınalar kopmuşt...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Gülnar']::text[], 8.5, '{"poet":"Selçuk Gülnar","poet_slug":"selcuk-gulnar","theme":"Türk Şiiri","is_hero":false,"total_lines":101,"source_url":"https://www.antoloji.com/tanistigim-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimi Kendime Terkettim', 'kendimi-kendime-terkettim-aysin-ulug-6gxlk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen de biliyorsun herşey anlamsız aslında

bunca yaşanmışlık

genç yaşlarımıza sığdırmaya çalıştığımız 

günlerin yetmediği hayatlarımız

bize hafif gelen

başkalarının kaldıramadığı gelecek umutlarımız

sen de biliyorsun

elimizdekiler yetmiyor değil aslında

yanlış ellerde yanlış yerlerdeyiz

yolumuzu kim çiziyor diye sormuyorum artık

yaşadığım hayat benimse

kim bunlar da demiyorum artık

bir pencere duruyor önümde

haklısın baktığım gökyüzü ortak

herşey ortak biliyorum

ama ben o nefesi alamıyorum

ve karışmıyor nefesim o havaya artık

dedim ki çekip gitsem

dedin ya ne farkedecek

hiçbirşey biliyorum

sen de biliyorsun

biz ne kadar çaba sarfetsek de

ne kadar boğuşsak didinsek 

farketmeyecek

sanırım öğrendim şimdi şimdi

oturup beklemek lazım

sen de biliyorsun

iyiyi yaşamak için ne yaptıysak

kapılar hüsranla kapandı yüreklerimize

ne geri açıldı umutlarımıza

ne de biz açabildik yeniden

kırılmış kanatlarımızla

şimdi son noktada

binlerce hayatın dolduğu bir hayatımızla

bunu anlayacak bir hayatı beklemek

ne acı değil mi

beklemekten nefret ederken

beklemek zorunda olmak

beklemek

kaç güneş kaç karanlığa

kaç karanlık sabaha yol alır bilmiyorum

kendimi kendime terkettim

bekliyorum...', 'sen de biliyorsun herşey anlamsız aslında bunca yaşanmışlık genç yaşlarımıza sığdırmaya çalıştığımız  günlerin yetmediği hayatlarımız bize h...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/kendimi-kendime-terkettim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımı Dağlara Anlattım', 'askimi-daglara-anlattim-selcuk-gulnar-7j6cz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yine gönlüm deli bugün			

Çıktım dağlara aşkından			

Bulutlar bile şaşkındı bana			

Seyre daldım hepsini birden			

			

Her baktığım seni sordu			

Neden yalnız geldin diye			

Sanki güzelliğinden			

Onlarda sarhoş gibiydi			

			

Nereden haber aldılar			

Bilmem ama hepside duymuş			

Senin güzelliğini			

Buğday tenine maviler sürdüğünü			

			

Dağlar			

Kuşlar			

Dereler			

Ağaçlar			

Basıp ta geçtiğin yollar bile			

Hüzün doluydu			

			

Bana bakıyorlardı hep birden			

Sanki içimdeki yanlızlığı			

Görmüşler gibi.....			

Onlarda dertliydi benden dolayı			

			

Biliyor musun sevgilim			

Bende açıldım onlara			

Tutamadım kendimi hıçkırdım			

Hiçbir sırrımı bırakmadan			

Konuştum hepsini söyledim			

			

Ta ki onları bıktırana dek			

Hepsine bir ağızdan			

Bağırarak anlattım seni			

Her şeyini dinlediler			

			

Güzelliğinden bahsettim			

Hatta senin nazlarının			

Beni ne kadar mutlu ettiğini bile			

Açıldım pervasızca			

Aşkımı anlattım onlara

Ne zamandır zaten

Dert ortağı arıyordum dedim

Sizler dostumuzsunuz dedim

Sizden başkasına açılamam dedim

Onlarda dinlediler beni

Bıkmadan usanmadan

Beni dinlerken merakla

Ağlayanlar bile oldu içlerinden

Aşkım dedim

Bir tanem dedim

Sevgilim bile dedim

Güzellerin sultanıdır dedim

Ne zaman olsa severim dedim

Seni kıskandığımı anlattım

Saçlarının telini

Gözlerinin rengini

Anlattım

Vücudunu tarif ettim

İnce belinden

Tatlı dilinden bakışlarındaki

Anlamdan bahsettim

Her şeyi güzel dedim

Beni sevmeyişi bile güzel dedim

Bana bakmayışının verdiği

Hazdan bahsettim

Aşkımı sana anlatamayışımı

Anlattım onlara

Aşkımın karşısında

Hepsi dile geldi

				

Çok hüzünlendik beraberce				

Ama ben mutluydum				

Senin mutsuzluğunu görmediğim için			

Hiç mutsuz olmanı istemediğimden			

Bahsettim				

Gerçekten sevdiler beni				

Arkadaş olduk			

Sırdaş olduk hepsiyle			

Dalmışım hayallere			

Onların sıcaklığı ile			

			

Bulutlarla konuştum oracıkta			

Yeter ki gelmek istesin			

Biz taşır getiririz			

Ulaştırırız sana dediler			

			

Melektir o zaten dedim			

Onun sizin yardımınıza			

İhtiyacı yok ki...			

Kızdım istemezse üzülürüm dedim			

			

Yalcın kayaların			

Haykırışlarıyla uyandım			

Nasıl olur dediler			

Bu aşka cevap verilmez mi			

			

Belki de beni anlıyordur			

Dedim mutlaka			

Ama cefa çektirmek			

Hoşuna gidiyordur dedim			

			

Zaten bende bu cefayı			

Çekmek istiyorum			

Mutlu oluyorum onunla			

Cefasıyla da sefasıyla da			

			

Yoksa aşkımın			

Anlamı kalmaz dedim			

Aşk sevgilinin yerine			

Bütün zevkleri yaşamaktır dedim			

			

Ağaçlar sallandılar bir bir			

Selvi boylum diye diye			

Taze fidandır o dedim onlara			

			

Gerçekten memnun oldular			

Seninle tanışmaktan			

			

Yüz yüze olmasalarda			

Aşkıma aşık oldular			

Oracıkta gonca bir gül			

Takıldı gözüme			

Onunla da sohbet ettim			

Kıyamadım dokunmaya			

Dedi ki bana			

Bakma sen ona aslında			

Senden hoşlanıyor kuşkusuz			

Seviyor o da seni mutlaka			

			

Ancak beraber olmak			

İmkansız anlaşılan

Nedir sebep bilemem

Aşkına cevap gelir bir gün

Ne konuşmaydı onlarla

Yaptığım sohbet

Bütün içimi boşalttım

Hiçbir şey bırakmadan

Çok üzüldüğümü gördü

Uzaklardaki ceylan

Üzülme dostum dedi bana

Aşk o kadar kolay değil ki dedi

İstediğin an kurtulamazsın

Kaptırdın mı kendini bir kere

Dilediğin kadar yaşa aşkını

Meleklerle yaşadığın aşk gibi

Dağların hepsi bir araya gelmiş

Sohbet ediyorlardı

Toplanmışlar bir sofrada

Ortalarından akan su

Misafirleri olmuştu

Onlara sordum

Sizde aşktan anlar mısınız diye

Aşk dediler başka bir

Ses çıkmadı ağızlarından

Derin bir nefes çekti içinden

Senelerdir akar giderim dedi

Senin gibi aşık görmedim			

Ne büyük aşkmış bu			

			

Bulmuşsun			

Aşkların en güzelini			

Daha ne istersin mevladan			

Bulmuşsun en güzel meleği			

			

			

Aşkla beraber olmak			

Güzelliği tanımak			

Melekle melek olmak			

			

Aşkına aşk katar insanın			

Mutlulukların en güzeli			

Olsa gerek diye içini çekti			

			

Ne yapayım diye sordum			

Gök yüzüne doğru bağırdım			

Sesimden korkmuş			

İrkilerek yerinden oynadı			

Nedir senin derdin			

Dostum diye sordu			

			

Hiç kimseyi göremedim etrafımda			

Bakınırken birden omuzuma dokundu			

			

Döndüm ki rüzgar dostluk			

Elini uzatmış bana			

			

Bir koku getirmiş			

Senin teninden			

İmkansız dedim			

İnanamadım			

			

Nasıl olur bu			

Aşkınla yanarken sen			

Dostumla oynamam ben			

Diye gülümsedi anlamlı anlamlı			

			

Biz orada sohbet ederken			

Dinlemiş konuştuklarımızı bütün			

Gitmiş uzaklara			

Senin kokundan teninden getirmek için			

			

Zor yetiştim dedi			

Az kalsın sohbet bitecekti			

İkram etti			

Bir tepsi içinde			

Kolonya gibi döktüm üzerime			

Aşkımın kelimelerini			

Fısıldadılar bana			

En mutlu insan ben oldum			

O anda			

Ne kadar mutlu oldum bilemezsin			

Tabi ki onlar seni				

Yakından tanımadılar				

Hep ben anlattım				

Onlara				

Ama rüzgar gördüklerini

Anlattı

Hepsi hayran kaldı

Bir kez daha

Aklımda sen

Gözlerimde sen varsın

Bir dönüpte bakışına

Salınıp gidişine

Her şeyinle

Seninleyim sevgilim

Ah sevgilim

Sen dünyada

Bir kez daha sevdiğim

Tek sevgilimsin

Gördüğüm günden beri

Düşler kalırım seni

Sümbül mü desem

Gül mü desem

Seni kıyamam

Hiçbir şeye benzetmeye

Zaten gülleri sana

Benzettiğim zaman

Asla kıyamıyorum

Ne koklamaya

Ne de dokunmaya

Sen aşkımın en derin aşkısın

Gönlümün en güzel yerinde				

Her zaman hazırsın				

Dilersen gelirsin				

Dilersen yakabilirsin.', 'Yine gönlüm deli bugün			 Çıktım dağlara aşkından			 Bulutlar bile şaşkındı bana			 Seyre daldım hepsini birden			 			 Her baktığım seni sor...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Gülnar']::text[], 8.5, '{"poet":"Selçuk Gülnar","poet_slug":"selcuk-gulnar","theme":"Türk Şiiri","is_hero":false,"total_lines":219,"source_url":"https://www.antoloji.com/askimi-daglara-anlattim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toz Rüzgar Yağmur', 'toz-ruzgar-yagmur-aysin-ulug-8arfc', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'bir toz yumağıdır geçmiş

bir rüzgarı bekler isyankar

yüzüne gözüne bulaşır

kaçanın kalanın

alır içine, sürüklenirsin çaresiz 

bir ışıktır

toz yumaklarında zerre zerre yanar

söner yok olur

isyankar rüzgarlar yetmez 

alıp götürmeye

bir yağmur bekler üstüm başım

yüzüm gözüm

tozlara gömülmüş hayatım

bir yağmur beklerim

ansızın

bir ağustos akşamı

herkese anlamsız 

bana yepyeni bir başlangıç

bir yağmur yağar

tek bir zerresi bile kalmaz geçmişin

tüm ışıklar ortaya çıkar

aydınlanır gece

aydınlanır hayatım', 'bir toz yumağıdır geçmiş bir rüzgarı bekler isyankar yüzüne gözüne bulaşır kaçanın kalanın alır içine, sürüklenirsin çaresiz  bir ışıktır to...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/toz-ruzgar-yagmur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkımız Göz Yaşları', 'askimiz-goz-yaslari-selcuk-gulnar-1zioj', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşkımın yaşları		

İndiğinde gözlerimden		

Hep bir ağızdan

Ağlama dediler.

Aç derdini korkmadan

Utanmadan konuş, 

Sende bir gün

Aşkı tanırsın de....

Bakalım o zaman

Diyecek sözü

Kalır mı acaba

Hıçkırdım hiç durmadan

Yine hıçkırdım

Sarılmak, koklamak

İstedim seni, 

Ne olur gel dedim

Sana

Duy beni, anla beni

Gel bir kere

Göz göze dedim

Herşeyi anlatırdım

O zaman

Aşkım benimle

Gitsin  mezara

Yeterki sen

Üzülme meleğim.', 'Aşkımın yaşları		 İndiğinde gözlerimden		 Hep bir ağızdan Ağlama dediler. Aç derdini korkmadan Utanmadan konuş,  Sende bir gün Aşkı tanırsın...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Gülnar']::text[], 8.5, '{"poet":"Selçuk Gülnar","poet_slug":"selcuk-gulnar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/askimiz-goz-yaslari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Çocuğun Gözlerinden Bakmak Kara Geceye', 'bir-cocugun-gozlerinden-bakmak-kara-geceye-aysin-ulug-6x70u', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir çocuğun gözlerinden bakmak kara geceye 

Ne yıldız ne ay

Bir çocuğun gözleriyle tılsımlı bir karanlıkta

İnivermek içten içe, geceden gündüze.

Bir çocuğun yüreğiyle duyumsamak inancı

Ne uzak ne yakın

Bir umut balonuna üfleyip oyun bahçelerini 

Sevivermek gözden yüreğe yürekten ölüme

Bir çocuğun ilk ayağa kalkışı gibi cesaretli

ve ilk adımı atışı kadar kararlı olabilmek

Ne korku ne yalnızlık

Bir çocuk gibi saf 

Bir çocuk gibi coşkulu

ve olabildiğince doğal.

Bir çocuğun inançlarıysa sonsuza

ilk haykırışı, anne deyişiyle sarmaksa evreni

ve gözleriyle aydınlanıyorsa en kara geceler

Bir çocuğun coşkusuyla sevmeli seni.

Sonsuz bir mutluluksa elma şekeri

Parlayan gözlerine yepyeni salıncaklarsa

ve bir çocuğun soğuk düşleriyse öğle uykuları

Sarmalı bir çocuğun oyuncağına sarılışı gibi

tutkuyla sarmalı seni.

Minicik elleriyle minicik parmaklarıyla çiziyorsa

Güneşi, ağacı, dağı bir kağıda minik uyumuyla

ve kocaman bir insan sevdiği o uyumda

Çizmeli bir çocuğun gözünde babasının dağlardan yüce

Güneşten öte görünen o resmi gibi çizmeli

Elimle ellerimle çizmeli en ince ayrıntına kadar seni.

İlk adımı milyonlara dönmüş bir çocuğun büyümüşlüğüyle

ve karanlık geceleri yemyeşil yapmış düşleriyle

gerçek, tutkularıyla yol almış bir çocuğun yetişkinliğiyle

Sevmeli seni, 

Çocuk kalbinin, çocuk ruhunun saf ve doğallğıyla 

sarılmış bir yaşlılık evresinde, sımsıcak teniyle

Uyandığında hep seni görmeli şimdi ve hep ve

sana parlayan gözlerim görmeli seni.', 'Bir çocuğun gözlerinden bakmak kara geceye  Ne yıldız ne ay Bir çocuğun gözleriyle tılsımlı bir karanlıkta İnivermek içten içe, geceden günd...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/bir-cocugun-gozlerinden-bakmak-kara-geceye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüya gibidir İstanbul iki kıtada', 'ruya-gibidir-i-stanbul-iki-kitada-sukran-besisik-pnzib', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Martıların süzüldüğü Marmara’da, 

Rüya  gibidir İstanbul iki kıtada.

Dünyaya meydan okuyan edayla, 

Seyredersin tarihi parıltılarla.

Gürler gülbanklar evlad-ı fatihanla.

Yakut sütun, firuze kubbeli, 

Cenneti andıran camileri, 

Gökte yıldızlarla eşleşir minareleri.

Şanlı maziden bir hatıra, 

Meltem gibi eser  bütün haşmetiyle, 

İnci gerdanlık Dolmabahçe, 

Asırlık çınar ağaçları ile, 

Asırlık zaman tünelinde.

Sarayburnu’ndan güneş tüllenir, 

Marmara bahçe olur güllenir.

Açar dört mevsim gönlümde, 

Hicaz mı, hüzzam mı, rast mı, nihavent mi

Titrer udun tellerinde.', 'Martıların süzüldüğü Marmara’da,  Rüya  gibidir İstanbul iki kıtada. Dünyaya meydan okuyan edayla,  Seyredersin tarihi parıltılarla. Gürler ...', ARRAY['Türk Edebiyatı','Şiir','Şükran Beşışık']::text[], 8.5, '{"poet":"Şükran Beşışık","poet_slug":"sukran-besisik","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ruya-gibidir-istanbul-iki-kitada-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-aysin-ulug-1259g', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'aşk tutkudur

tutkuyla sarmak 

isteği

aşk heyecandır

nefesinde hissetmektir...

yüreğinin ağzına gelmesidir

bedeninden fırlamaya çalışmasıdır 

adeta

aşk beyninde bir kurttur

her an onu düşünme isteği...

aşk yaşama gücüdür 

yana yakıla savaşma gücü

çöl ortasında su

karanlıkta güneştir aşk...

tutkulu bir sesin sessizliği delip 

geçmesidir

titretmesidir bedenini ve diğer 

bedeni

aşk yaşama dört elle sarılmaktır

görmezden gelmektedir dikenleri ki 

aşk o dikenlerin üzerinde iken

yara almadan yürümeni sağlayan

tek büyüdür

mistik bir tutkudur aşk

...

aşk çılgınca sevişme isteğidir

sevgiliyle

ve dostuna sımsıkı sarılma arzusu

bir bebeği koklamaktır

yeniden dünyaya gelmektir aşk onunla

aşk hep çocuk bırakmaktır bir yanını

herşeyi unutmaktır sevgili 

karacasında

anne kucağında

dost yanında

aşk kopmaz bağlarla bağlı olmaktır 

hayata

ve umuda.

aşk almayı beklemeksizin verme 

tutkusudur

hesapsız sevme arzusu

derin mavi karanlık sularda

nefes alma çoşkusu

....

ve aşk

senin gözlerinde ışık

sesinde huzur

yüreğinde sevgi

ellerinde teninde sıcaklık 

bulmaktır

aşk tirtir titremesidir 

bedenimin

bunca coşku sonrası.

....', 'aşk tutkudur tutkuyla sarmak  isteği aşk heyecandır nefesinde hissetmektir... yüreğinin ağzına gelmesidir bedeninden fırlamaya çalışmasıdır ...', ARRAY['Türk Edebiyatı','Şiir','Ayşin Uluğ']::text[], 8.5, '{"poet":"Ayşin Uluğ","poet_slug":"aysin-ulug","theme":"Türk Şiiri","is_hero":false,"total_lines":54,"source_url":"https://www.antoloji.com/ask-58-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözyaşlarım da Gitti', 'gozyaslarim-da-gitti-bahtiyar-ocal-b2k6z', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Solgun bir gül oluyor önce

Ayrılıpta hasrete düşenler, 

Sonra boynu bükük, gözü yaşlı.......

Onu düşünür, onu yaşar hep fikrince, 

Ağlamak ne çare ki; 

Her bir damlanın hesabı var.

Tıpkı geri dönmeyecek anılar gibi, 

Gözyaşlarımda seninle kaybolup

Gitti...........', 'Solgun bir gül oluyor önce Ayrılıpta hasrete düşenler,  Sonra boynu bükük, gözü yaşlı....... Onu düşünür, onu yaşar hep fikrince,  Ağlamak n...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Öcal']::text[], 8.5, '{"poet":"Bahtiyar Öcal","poet_slug":"bahtiyar-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/gozyaslarim-da-gitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Bayram Günü', 'bir-bayram-gunu-emin-uyguner-p6tkx', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç olmasa bir bayram günü gidelim 

o yolu unutuğumuz 

anne babamızın oturdugu eski evize 

elimizde bir gül yüzümüzde  tebesümle 

gireim içeriye

kim bilir nekadar sevinirler yaşlı ve yaşı gözleriyle

                NOT: bir gün sizde yaşlacaksınız', 'Hiç olmasa bir bayram günü gidelim  o yolu unutuğumuz  anne babamızın oturdugu eski evize  elimizde bir gül yüzümüzde  tebesümle  gireim içe...', ARRAY['Türk Edebiyatı','Şiir','Emin Uyguner']::text[], 8.5, '{"poet":"Emin Uyguner","poet_slug":"emin-uyguner","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/bir-bayram-gunu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçup Giden Gençlik', 'ucup-giden-genclik-ozcan-nevres-p3199', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne oldu gençliğim neden küstük birbirimize

Dün beraberdik bu gün yoksun niye

Ağaran saçlarım düşünce  önüme

Ayaklarımla birlikte ihanet ettiniz

Aşkın defteri yıllar oldu kapanalı

Sağlık karnesinde yazacak sayfa kalmadı

Mezarcı Mahmut henüz gözlemese de yolumu

O dönülmez yola girişe fazla zaman kalmadı

İşte geldik işte gidiyoruz

Mutluluk rüzgarında savrulmadan

Yokluktan yoksulluktan kurtulmadan

Yaşamanın tadını anlamadan

Sırtımızdaki yükler henüz kalkmadan

Geride ince bir iz bile bırakmadan

Ot gibi yaşadık

Ne sevdalarımız kitaplara yazıldı

Ne adımız sokak çeşmelerine kazıldı

Ne de hayra gücümüz vardı

Yokluk yakamızı hiç bırakmadı

Kendisi himmete muhtaç bir dede

Kendinde yok ki kime himmet ede

Öylesine yaşadık ve gidiyoruz işte

		Özcan NEVRES    2000 – 08 – 14

			SİLİVRİ', 'Ne oldu gençliğim neden küstük birbirimize Dün beraberdik bu gün yoksun niye Ağaran saçlarım düşünce  önüme Ayaklarımla birlikte ihanet etti...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/ucup-giden-genclik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uykusuz Geçen Geceler', 'uykusuz-gecen-geceler-ozcan-nevres-mj7hw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutsuz aşıkların çektiği çiledir uykusuzluk

Diken olur yattığı yatak yorgunluktan ölse de

Hayaller kurar ulaşamadığı arzuları üstüne

Çobanaldatan kuşudur hayaller, durmadan aldatır. 

Yitik umutlarına göz yaşı döker tüm gece

Uykuya dalacakken sabahın ışıkları gelir sinsice

			Özcan Nevres  2001 – 08 – 01

			       SİLİVRİ', 'Umutsuz aşıkların çektiği çiledir uykusuzluk Diken olur yattığı yatak yorgunluktan ölse de Hayaller kurar ulaşamadığı arzuları üstüne Çobana...', ARRAY['Türk Edebiyatı','Şiir','Özcan Nevres']::text[], 8.5, '{"poet":"Özcan Nevres","poet_slug":"ozcan-nevres","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/uykusuz-gecen-geceler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlarken', 'baslarken-hulya-karaaslan-zeawv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir zaman kambur dolaştım

bir zaman da cüzzamlı

dökük nakışlı ayindi hamam

kırklandım kurnanın belleğinde

kokular sürünüp yağlandım

geçtim uzun bir adımla körlüğümü

kırıldı yalan altında gülen yüzüm

bağışsız bir aldatıyla yaşlandım

bir Düş''ün Ayvaz''ıydım

iz sürdüm yitik sevdalarda

hülya mabetlerinde

dokunulmamış saatler aradım

ikizim istiridye sularda kesik baş

inci uykusuyla karnındaydım

ölüm yüzümde yaşam

bir yar geçtim bir de ser

yumuşadı aşkın göbek taşında

donuk zihnim

birkaç kuru anıyla ovuldu

omuzlarımdan dökülen yıllar

vurdu yüzüne boşluk

evini bilmeyen ruhumun

şimdi bir kabuk olan yüreğimden

söylerken biliyorum

içnotlardan örülü

yalnız bir kenar süsüyüm

içimden uzağa düşmez gölgem', 'bir zaman kambur dolaştım bir zaman da cüzzamlı dökük nakışlı ayindi hamam kırklandım kurnanın belleğinde kokular sürünüp yağlandım geçtim u...', ARRAY['Türk Edebiyatı','Şiir','Hülya Karaaslan']::text[], 8.5, '{"poet":"Hülya Karaaslan","poet_slug":"hulya-karaaslan","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/baslarken-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Senin Şiirin', 'senin-siirin-sadece-onur-4yrgz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bulutlanmış gözlerimden, 

Bak yine yağmur yağıyor.

Ve ben her damlada 

Seni düşünüyorum 

Bir başka  bahara saklıyorum umutlarımı

Sözlerimi mısralarıma

Ve en güzel şiirleri seninle 

Senin için yazıyorum

Her  fırtına  öncesi sana

Senin gözlerine sığınıyorum

o limanda bir  ben

Bir ben kalmak istiyorum', 'Bulutlanmış gözlerimden,  Bak yine yağmur yağıyor. Ve ben her damlada  Seni düşünüyorum  Bir başka  bahara saklıyorum umutlarımı Sözlerimi m...', ARRAY['Türk Edebiyatı','Şiir','Sadece Onur']::text[], 8.5, '{"poet":"Sadece Onur","poet_slug":"sadece-onur","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-siirin-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nisâ', 'nis-cengiz-dursun-7knt5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kadınlar anadır, kadınlar yardır

Uşşak için temennay-ı mesardır

Hem yürekte yara hem gam-güsârdır

Bitmeyen çileye bahardır; nisâ...

Zaman olup yüreğini dağlayan

Sevdan olup dertlerinle ağlayan

Ne varlıktan ne yokluktan anlayan

Nevbaharda solmayan çiçektir; nisâ...

Rahmet misâli saftır, berraktır

Zemherîde ayaz, bulutta aktır

Kimi zaman necis, kimi an paktır

Gâh devâ, gâh derd-i bi-devâdır; nisâ...

Titreyen ateşe ışıktır, hardır

Boyunda salınır, nâ-mert yulardır

Kimi zaman alev, kiminde kardır

Sineye vurulan hançerdir; nisâ...', 'Kadınlar anadır, kadınlar yardır Uşşak için temennay-ı mesardır Hem yürekte yara hem gam-güsârdır Bitmeyen çileye bahardır; nisâ... Zaman ol...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Dursun']::text[], 8.5, '{"poet":"Cengiz Dursun","poet_slug":"cengiz-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/nisa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'SEnin Hayalin', 'senin-hayalin-ismail-nas-n7ril', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sehrin isiklari yaninca gece

Baslar icimdeki sonsuz bilmece

Tararim ufugu bir uctan uca

Gözlerim kalir hayalinde senin

Yildizin isigi kalbime vurur

Aysa bulutlara gizlenir durur

Gönlümde ocaklar yanar kavrulur

Gözlerim kalir hayalinde senin

Düsler rüzgarin bense ucan yaprak

Bagrina düstügüm yer kara toprak

Sensizlik icimde mekan ki corak

Gözlerim kalir hayalinde senin', 'Sehrin isiklari yaninca gece Baslar icimdeki sonsuz bilmece Tararim ufugu bir uctan uca Gözlerim kalir hayalinde senin Yildizin isigi kalbim...', ARRAY['Türk Edebiyatı','Şiir','Ismail Nas']::text[], 8.5, '{"poet":"Ismail Nas","poet_slug":"ismail-nas","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/senin-hayalin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'GüLüMSe', 'gulumse-cengiz-dursun-x2mcv', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömründe ilk kez olsun, yalnız kal benim için...

Gözlerimden akan yaşların yanağımdaki seyrinin ayak seslerini işit...

...Ve gülümse...

Gülümse ki bir lahza daha artsın ömrüm, 

ve bir parça rahatlasın sevinç nedir bilmeyen yanım...

Dökülsün teker teker kederler, 

Sökülsün birer birer yüreğimdeki hançerler...

  Artık esmesin rüzgâr; gelmesin bahar...

Örtülsün üzerime birer birer yapraklar...

Kırlangıçlar uçmasın, 

Menekşeler açmasın, 

Çimlere basmasın kıratlar...

En çetin cezalarım yazılsın, 

  Ve bir daha bozulmasın karar...

Türkülerim üşüsün....

Artık gelmesin bahar...

Bahçelerde oynamasın, 

Ninni değil ağıt emsin çocuklar.

Karanlıklar bedenime sarılsın

Gözlerimi kanlı eller dağlasın

Tüm insanlık şu halime ağlasın

Sen gülümse 

...Artık gelmesin bahar.......', 'Ömründe ilk kez olsun, yalnız kal benim için... Gözlerimden akan yaşların yanağımdaki seyrinin ayak seslerini işit... ...Ve gülümse... Gülüm...', ARRAY['Türk Edebiyatı','Şiir','Cengiz Dursun']::text[], 8.5, '{"poet":"Cengiz Dursun","poet_slug":"cengiz-dursun","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gulumse-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ruhun Kokusu', 'ruhun-kokusu-sedef-sevinc-038ts', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ruhumun bir yanı siyahlara bürünmüşse hırçın sevgilerin arasında, 

gölgemin arkasına geçmişsem bilinmez sokaklarda, 

alev alev yanmışsa bedenim düşlerimde, 

aynaya her baktığımda gözlerimin içinde boğulup gidiyorsam, 

gece rengini gösterdiğinde hüzün kapımı çalıyorsa, 

kapıyı açan sessizliğimse, 

hüznün avuçlarından süzülen benim kanımdır...', 'Ruhumun bir yanı siyahlara bürünmüşse hırçın sevgilerin arasında,  gölgemin arkasına geçmişsem bilinmez sokaklarda,  alev alev yanmışsa bede...', ARRAY['Türk Edebiyatı','Şiir','Sedef Sevinç']::text[], 8.5, '{"poet":"Sedef Sevinç","poet_slug":"sedef-sevinc","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ruhun-kokusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Şiir de Bitti', 'bu-siir-de-bitti-hasan-can-ue-ffuyt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Kim demiş bu aşk bitmez diye

Herşeyin bir sayacı var geriye doğru sayan

Herşey biter sıfır olunca sayacı

Gözündeki yaş biter, 

Kalbindeki sevgi, nefret hepsi biter

Bahar olur topraktan bir lale biter

Kışın sayacı sıfır olur onun da ömrü biter

Dertlerin de biter çilelerin de biter

Gündüzler biter, geceler biter

Güneşte biter, bilim böyle söyler

Yıldızlar söner, rüyalar biter

Zaman geçer...ömür biter 

Biter diyorum herşey biter

Aldırma bu hasret, bu acı biter 

Sayacın sonuna getiriyor bizi kader

Bilinmez kader ne der gönül ne der 

Zaten dinlemez kader

Püsküren yanardağlar diner

Kor lavlar söner

Biter heşey biter

Geceyi kıskandıracak kadar 

siyah gözlere aşk biter

Benim elimden gelen budur

Zira babamın adı hıdır

Ama inan herşey biter, Bu şiir de biter

Nasıl mı? bak işte böyle

Üç.iki.bir. sıfır 

Hasan Can', 'Kim demiş bu aşk bitmez diye Herşeyin bir sayacı var geriye doğru sayan Herşey biter sıfır olunca sayacı Gözündeki yaş biter,  Kalbindeki se...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can Ue']::text[], 8.5, '{"poet":"Hasan Can Ue","poet_slug":"hasan-can-ue","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bu-siir-de-bitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Peri', 'siyah-peri-hasan-can-ue-l49j3', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir gün yanıma bir peri geldi

Üç dilek dile benden dedi

Dedim iyi peki

Diledim en çok istediğim üç dileğimi

Kolay dedi ilk ikisi

Ama üçüncüsünü isteme en iyisi

Zira bir sandık ki bilinmez içindeki

Biz de sandıkki istediğimiz eniyisi

Israr edince kırmadı beni küçük peri

Bir şey vardı merak ettiğim doğduğum günden beri

Ne zaman ve niye sönecekti hayatımın feneri

Sustu küçük peri 

Soğudu alnımın teri

Meğer azrailmiş o peri

Dedi buyur içeri bekletme seni sevenleri

Savurdum elimdeki gülleri

Bekle beni geliyorum siyah peri..', 'Bir gün yanıma bir peri geldi Üç dilek dile benden dedi Dedim iyi peki Diledim en çok istediğim üç dileğimi Kolay dedi ilk ikisi Ama üçüncüs...', ARRAY['Türk Edebiyatı','Şiir','Hasan Can Ue']::text[], 8.5, '{"poet":"Hasan Can Ue","poet_slug":"hasan-can-ue","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/siyah-peri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Sen Kaldın Aklımda', 'bir-sen-kaldin-aklimda-bora-zihni-gkfab', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bir ordasın, hayalde, 

İçimde.

Taa uzakta.

Görmek için seni

Her gözümü kapatışımda, 

Kanar içimde açtığın uslanmaz yaralar.

Akar  gönlümün derinliklerinde 

Ağlayan Gülpembe''ye.

Bir sen kaldın aklımda

Ölüm ötesinde.

Bir de senli anılar.', 'Bir ordasın, hayalde,  İçimde. Taa uzakta. Görmek için seni Her gözümü kapatışımda,  Kanar içimde açtığın uslanmaz yaralar. Akar  gönlümün d...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/bir-sen-kaldin-aklimda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıradışı', 'siradisi-bora-zihni-t6nk0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Soruyorlar bana neden hep aşk şiiri yazıyorsun? 

Aşık olan şair başka ne yazabilir ki.

Soruyorlar bana var mı dünyada böyle bir aşk? 

Yaratılmışlığın içinde.

Soruyorlar bana  tanrı böyle aşkları yarattı mı? 

Yaratılmamışı yaşamak.

Soruyorlar bana sonunuz ne olacak? 

İki rayız, bir tren yolunun', 'Soruyorlar bana neden hep aşk şiiri yazıyorsun?  Aşık olan şair başka ne yazabilir ki. Soruyorlar bana var mı dünyada böyle bir aşk?  Yaratı...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/siradisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutsak', 'tutsak-bora-zihni-id4om', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir yol gider gönlümden gönlüne, 

sevgi dolu

Bir bakış var gözlerimden gözlerine

engel dolu

İki yanardağ gibi içimizde özlem

biri sende kaynar, biri bende

Uzanmak ister ellerim ellerine

uzanamaz titrer, 

Koşmak isterim sana doğru, koşamam.

Duymak isterim sıcak nefesini kudaklarımda, 

Duyamam.

Sarmış dört yanımızı karanlık, 

Sen çaresiz, ben çaresiz.

Kader tutsak almış ikimizi, 

Bir tutsak sevgi bu bizimki', 'Bir yol gider gönlümden gönlüne,  sevgi dolu Bir bakış var gözlerimden gözlerine engel dolu İki yanardağ gibi içimizde özlem biri sende kayn...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/tutsak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Damla', 'i-lk-damla-bora-zihni-0sria', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç ummadığın bir anda, 

Aşkından kudurduğun, Leylası olacağın, 

Bir sevgilin olacak.

Olmasa da var sayacaksın.

Cesaretini toplayıp yanına varacaksın, 

Tek başına yanmayacak; yakacaksın.

Sadece sevmeyecek, 

Ona sevildiğini bildireceksin.

Bir onu seveceksin, taparcasına.

Bir onu göreceksin, kör olurcasına.

Bir onu düşüneceksin, delirircesine.

Bir onu  öpeceksin, eritircesine, mahvedercesine.

Elinden tutamasan da

Gözlerini çalacaksın bebeğinden.

Dudakların kuruyacak, titreyeceksin sevgiden, aşktan, ihtirastan.

Gündüzleri  senin, geceleri başkasının olan

Sana tapan, 

Bir sevgilin olacak bu dünyada

Olmasa da varsayacaksın.', 'Hiç ummadığın bir anda,  Aşkından kudurduğun, Leylası olacağın,  Bir sevgilin olacak. Olmasa da var sayacaksın. Cesaretini toplayıp yanına v...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ilk-damla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kör Kara Sevda', 'kor-kara-sevda-bora-zihni-6nm1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sevdim seni güzelim, 

Sonsuzlukla birlikte.

Mutluluk kaçınılmaz, 

Ama ya olmazsa? 

Elini tuttum güzelim, 

Kalbimle birlikte.

Uçmak kaçınılmaz, 

Ama ya olmazsa? 

Öptüm seni güzelim, 

Aşkımla birlikte.

Tutuşmak kaçınılmaz, 

Ama ya olmazsa? 

Sardım seni güzelim, 

Tüm sıcaklığımla birlikte.

Sonumuz kaçınılmaz, 

Ama ya sonumuz olmazsa?', 'Sevdim seni güzelim,  Sonsuzlukla birlikte. Mutluluk kaçınılmaz,  Ama ya olmazsa?  Elini tuttum güzelim,  Kalbimle birlikte. Uçmak kaçınılma...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/kor-kara-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dünya Dur', 'dunya-dur-yasemin-yarar-l5i4n', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'dünya tuttu beni

durdurun dünyayı

kusasım geliyor

inecek var durdurun', 'dünya tuttu beni durdurun dünyayı kusasım geliyor inecek var durdurun...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/dunya-dur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yıkık kule', 'yikik-kule-yasemin-yarar-aziwc', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'çocuktum hep

beğenmeyip de 

yıktığım da 

kendimdi hep

parçalarımı toplayıp toplayıp

şizofren bir kule yapardım

kendimden kendime(93 İstanbul)', 'çocuktum hep beğenmeyip de  yıktığım da  kendimdi hep parçalarımı toplayıp toplayıp şizofren bir kule yapardım kendimden kendime(93 İstanbul...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yikik-kule-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Böyle İşte', 'boyle-i-ste-ozgur-kale-68lka', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüreğim yine düzensiz, 

Neden? 

Yarin yüzü aklımda, 

O uzak ben uzak..

Yolumu yitirdim bir kere, 

Dönmek olur mu? 

Nereye varırsam orada kalırım artık, 

Buralardan gideceğim nasıl olsa...

En iyisi onu görmemek bir daha, 

Yüreğim düzene girecek mi belirsiz

Vücudumu sarmış bir kere ateş, 

Bırakmıyor, bana biraz su verin, 

Birisis söndürsün şu alevi..

Yoksa eriyorum günden güne, 

Hem yolumu yitirdim, hem yanıyorum, 

Feryadım yine kendime

Ama ben deva olamam ki kendime, 

Keşke hiç gelmemiş olsaydım şu adi dünyaya, 

Yüreğim olmazdı en azından, 

Ne acı hissederdim, ne de aşk, 

Sadece boşluk olurdu, ne iyi....', 'Yüreğim yine düzensiz,  Neden?  Yarin yüzü aklımda,  O uzak ben uzak.. Yolumu yitirdim bir kere,  Dönmek olur mu?  Nereye varırsam orada kal...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/boyle-iste-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kolay Gün mü?', 'kolay-gun-mu-ozgur-kale-egpg4', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Kolay gün yok şu dünyada, 

Tesadüfen de yaşıyor olabilirsin, 

Ekmeğin, suyun değerini bilemezsin ki, 

Aç değilsin sen, 

Git ve aç insanları gör, 

Gör ki günlerinin değersizliğini anla.', 'Kolay gün yok şu dünyada,  Tesadüfen de yaşıyor olabilirsin,  Ekmeğin, suyun değerini bilemezsin ki,  Aç değilsin sen,  Git ve aç insanları ...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kolay-gun-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Büyük', 'buyuk-yasemin-yarar-oz4pv', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Zaman akıp geçiyor 

ben büyüdüm mü 

küçüldüm mü bilmiyorum

ama sıkıntım

hep benden büyüktü', 'Zaman akıp geçiyor  ben büyüdüm mü  küçüldüm mü bilmiyorum ama sıkıntım hep benden büyüktü...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/buyuk-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Elbette', 'elbette-ozgur-kale-1t4xd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Doğup, yaşayıp ölürsün

Kefen giyip tabuta girersin, 

Çürür toprağa karışır, yeniden hayat bulursun, 

Ve sonra birsürü şey olursun, 

Bal olursun, iplik olursun, 

Tütün olursun, 

Hatta duvar boyası olursun!', 'Doğup, yaşayıp ölürsün Kefen giyip tabuta girersin,  Çürür toprağa karışır, yeniden hayat bulursun,  Ve sonra birsürü şey olursun,  Bal olur...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/elbette-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çöz', 'coz-yasemin-yarar-ztkag', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'yaşam dolandı ayaklarıma

çöz ölüm çöz..', 'yaşam dolandı ayaklarıma çöz ölüm çöz.....', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/coz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kendimce', 'kendimce-ozgur-kale-sfolz', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sana büyü yapmıştım kendimce, 

Ama kendi silahımla ben vuruldum, 

Yanmanın acısıyla yapılmış bir büyüydü bu, 

Beklenenlerle dolu

Düşlerle sıkıştırılmış, 

Kucaklamalara varan arzularla, 

Adını yazmıştım kutsal topraklara

Dağları kıskandırırcasına, 

Çevirmiştim taşlarla, toprağa yazmıştım seni, 

Çiçeklerle tek tek süsledim taşları, 

Uzaktan şöyle bir daha baktım, 

Ve orası iki kere kutsaldı artık......', 'Sana büyü yapmıştım kendimce,  Ama kendi silahımla ben vuruldum,  Yanmanın acısıyla yapılmış bir büyüydü bu,  Beklenenlerle dolu Düşlerle sı...', ARRAY['Türk Edebiyatı','Şiir','Özgür Kale']::text[], 8.5, '{"poet":"Özgür Kale","poet_slug":"ozgur-kale","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/kendimce-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiliye', 'sevgiliye-bora-zihni-o9j0z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidelim bir tanem gidelim.

Senin prenses, benimse prens olduğum diyarımıza gidelim.

Kapat gözlerini, 

El ele girelim hayal dünyasından içeri uçarak.

Ayaklarımız yere değmesin, 

Mutluluktan.

Tut ellerimi, 

Beraber girelim aşk denizine, çırılçıplak.

Sevişelim, sevişelim, doymayalım

Aşktan.

Benimle ol, 

Birlikte duralım dert dağlarının karşısında, dimdik.

Yıkıp, dümdüz yol yapalım

Sevgiden.

Sarıl bana, 

Kurumuş pınarlara hayat verelim aşkımızla.

Suyundan içen, bir daha yanmasın

Aşktan.

Sevişelim, 

Susturalım sevgimize dil uzatanları aşkımızla

Bir daha bahsedemesinler

AŞKTAN, SEVGİDEN, MUTLULUKTAN.', 'Gidelim bir tanem gidelim. Senin prenses, benimse prens olduğum diyarımıza gidelim. Kapat gözlerini,  El ele girelim hayal dünyasından içeri...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/sevgiliye-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Felaket', 'felaket-bora-zihni-g4vga', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Başım ağrıyor, 

Gözümde uyku yok.

Hap yuttum, 

Televizyon seyrettim, 

Yok, yok, yok

Gözümde uyku yok.

Yatakta döndüm durdum yok, 

Kalktım gazete okudum yok.

Yok, yok, yok

Gözümde uyku yok

Anlayacağınız durumum BOMBOK.', 'Başım ağrıyor,  Gözümde uyku yok. Hap yuttum,  Televizyon seyrettim,  Yok, yok, yok Gözümde uyku yok. Yatakta döndüm durdum yok,  Kalktım ga...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/felaket-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Martının Kanatları', 'martinin-kanatlari-mehmet-sahin-j3pui', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Martının kanadını kırmış çocuk, martı ağlamış

Çocuk aldırmayıp devam etmiş oyuna.

Günün rüzgar olduğu bir zamanda

Kan kokulu zehir çiçeklerinden bir hediye çalar kapımı.

Not: Martının kanatları.', 'Martının kanadını kırmış çocuk, martı ağlamış Çocuk aldırmayıp devam etmiş oyuna. Günün rüzgar olduğu bir zamanda Kan kokulu zehir çiçekleri...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şahin']::text[], 8.5, '{"poet":"Mehmet Şahin","poet_slug":"mehmet-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/martinin-kanatlari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kırmızı', 'kirmizi-mehmet-sahin-zq5lt', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gümüş tadında bir kahve

Ellerimde zambak kokusu

İçimde ince bir tılsım parladı

Geçti sonbaharın sesi

Ellerim kırmızı.', 'Gümüş tadında bir kahve Ellerimde zambak kokusu İçimde ince bir tılsım parladı Geçti sonbaharın sesi Ellerim kırmızı....', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şahin']::text[], 8.5, '{"poet":"Mehmet Şahin","poet_slug":"mehmet-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/kirmizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgiler', 'sevgiler-bora-zihni-28gz4', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sevgiler; 

Zamanla sınırlı sevgiler, 

Zamanla sınırsız sevgiler.

Sevgiler; 

Bir görüşte başlayan sevgiler, 

Bin uğraşta başlayan sevgiler.

Sevgiler; 

Yaşanırken yere bastırmayan sevgiler, 

Yaşanırken süründüren sevgiler.

Sevgiler; 

Zamanla kaybolan sevgiler, 

Zamanla alevlenen sevgiler.

Sevgiler; 

Hiç bitmesin istenen sevgiler, 

Bitmesi farz olan sevgiler.', 'Sevgiler;  Zamanla sınırlı sevgiler,  Zamanla sınırsız sevgiler. Sevgiler;  Bir görüşte başlayan sevgiler,  Bin uğraşta başlayan sevgiler. S...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sevgiler-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Avuç Mavi Su', 'bir-avuc-mavi-su-bulent-ozcan-97ao7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çeken ne denizlere doğru

Beni böyle umarsız? ..

Kulaklarımda 

Dalgaların uğultusu; 

Bir avuç mavi su

Gözlerimde, acımasız...', 'Çeken ne denizlere doğru Beni böyle umarsız? .. Kulaklarımda  Dalgaların uğultusu;  Bir avuç mavi su Gözlerimde, acımasız......', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-avuc-mavi-su-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Gemisi', 'hasret-gemisi-bulent-ozcan-brlpt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uyanır mazimde bir buruk sevgi, 

Alıp eskilere götürür beni.

Hasret gemisinin sevda yelkeni, 

Çile rıhtımında bekletir beni...

1990, Gaziantep', 'Uyanır mazimde bir buruk sevgi,  Alıp eskilere götürür beni. Hasret gemisinin sevda yelkeni,  Çile rıhtımında bekletir beni... 1990, Gaziant...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hasret-gemisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Atlarını Sürdüler Rüzgârın', 'atlarini-surduler-ruzg-rin-bulent-ozcan-f52rq', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Atlarını kim sürdü rüzgârın

Kim yazdı şiirini uğuldayan

Kavaklarını kim ıslıkladı

Kim söyledi türküsünü sızlayan

Yüreğini kundakladılar rüzgârın

Esmeli mi bu rüzgâr hep aynı

                                              15 Eylül 1998, Londra', 'Atlarını kim sürdü rüzgârın Kim yazdı şiirini uğuldayan Kavaklarını kim ıslıkladı Kim söyledi türküsünü sızlayan Yüreğini kundakladılar rüzg...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/atlarini-surduler-ruzgarin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimlik', 'kimlik-bahtiyar-ocal-iq8xa', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Adını koyamadığım sevgili kimsin sen; 

Bazan toprağın bağrından ay kadar uzak, 

Bazan bedenimde hücrelerim kadar yakın, 

Bazan buzullarda eskimolar kadar yabancı, 

Bazanda annem kızkardeşim kadar içimde....

           

                                       KİMSİN SEN, KİM...? 

Adını koyamadığım karmakarışık duygular; 

Bazan sıla hasreti anlatan türkü kadar yanık, 

Bazan hazan mevsimi düşen yaprak kadar yalnız, 

Bazan yağmurla gizlenen gözyaşı kadar buruk, 

Bazanda bir mecnun, ferhat, kerem kadar sevdalı, 

                                        KİMİM BEN, KİM....? 

                                                              09/06/2001

                                                               Cumartesi', 'Adını koyamadığım sevgili kimsin sen;  Bazan toprağın bağrından ay kadar uzak,  Bazan bedenimde hücrelerim kadar yakın,  Bazan buzullarda es...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Öcal']::text[], 8.5, '{"poet":"Bahtiyar Öcal","poet_slug":"bahtiyar-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/kimlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalandın', 'yalandin-murat-yorulmaz-b1yz9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sen benim hayatla aramdaki kavgamdın, 

Belki de beni benden, benliğimden alandın, 

Seni sevdiğimi çok ama çok geç anladın, 

Belki de kendi kendime söylediğim koskoca bir yalandın...', 'Sen benim hayatla aramdaki kavgamdın,  Belki de beni benden, benliğimden alandın,  Seni sevdiğimi çok ama çok geç anladın,  Belki de kendi k...', ARRAY['Türk Edebiyatı','Şiir','Murat Yorulmaz']::text[], 8.5, '{"poet":"Murat Yorulmaz","poet_slug":"murat-yorulmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/yalandin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret Treni', 'hasret-treni-mahmut-capar-r0wci', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seni hatırlatan hiç birşey dinlemiyorum

Yine de herşey seni hatırlatıyor.

Şiirlerim hep sana dair; 

Adın geçmesede

İşitmesende.

İçimden gelip 

İçin için içimi eriten.

Yalan sevgilerim var şimdi 

Yalan sevgililerim; 

Herşeyi tozpembe gören

Pembeyi kırmızı.

Aslında kırmızıyı da bilmeyen...

Aya bakıyorum sen varsın

Sana bakıyorum...

Seni göremiyorum ki...

Yüzün bana mahpus

Ben yüzüne.

Küsüm 29 Ekimlere 

Uzak olduğum kadar yakınım sana

Yakın oldugum kadar hasret...

Bir bilseydin aşkımı... 

Korkardın.

İşte o zaman bilirdin değerimi.

Ama şairin dediği gibi: 

''Neyin değerini bildin ki 

 Benimkini bileceksin? ''', 'Seni hatırlatan hiç birşey dinlemiyorum Yine de herşey seni hatırlatıyor. Şiirlerim hep sana dair;  Adın geçmesede İşitmesende. İçimden geli...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/hasret-treni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Wahed-e''ye', 'wahed-e-ye-mahmut-capar-r35kh', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Hiç anlamayacaksın değil mi

Nasıl ateşler içinde yandığımı? 

Hiç anlamayacaksın değil mi

Sana deliler gibi nasıl sevdalandığımı? 

Hiç anlamayacaksın değil mi

Şu halimi...? 

Bir anlayabilseydim

Şuan ne düşündüğünü...

Gözlerindeki ışığın anlamını bilseydim.

Bir görseydin içimdeki ateşi.

Bir bilseydin seni nasıl sevdiğimi...

Bir sevseydin beni

Seni sevdiğim gibi...

Yook.Ağlama! 

Kıyamam

Değişmem gözündeki yaşı dünyalara, 

Bir tebessümünü

Rüyalara.

Denizler taşırır yüreğimdeki sevgiırmakları da

Bir tek seni yutamaz içinde.

Onlar bile kıyamaz ya sana, 

Onlar bile söndüremez ya ateşimi

Onlar bile duymaz ya sesimi...

Ahh bir bilseydinhalimi

Ah bir sevseydinbeni, 

Sende birgün benim gibi...', 'Hiç anlamayacaksın değil mi Nasıl ateşler içinde yandığımı?  Hiç anlamayacaksın değil mi Sana deliler gibi nasıl sevdalandığımı?  Hiç anlama...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/wahed-e-ye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıfır', 'sifir-nalan-kazazoglu-vwevg', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Nerede doğmuşsam orada kaldım, 

Susmayan yazılardan keyif aldım, 

Serüvenlerimde çoğu yaya kaldım.

İnsana hayata dair

Beceriksizce düşünüp durdum

Senaryosuz sessiz sorular sordum.

Elde ne var, 

Sıfır.

Okudu derinlerimi herkes...

Fırlatıyorlar sivri oklarını

Tutam tutam hikayelerinde, 

Tozu dumana

Bire bin katarak...', 'Nerede doğmuşsam orada kaldım,  Susmayan yazılardan keyif aldım,  Serüvenlerimde çoğu yaya kaldım. İnsana hayata dair Beceriksizce düşünüp d...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/sifir-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bilenler bilir', 'bilenler-bilir-nalan-kazazoglu-t2hzv', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bahçede kuruyan çiçekleri, 

tavanda oynaşan eski gölgeleri, 

Tutamayız..

El sallarız titrekçe..

Gitti Anneannem, 

Bilenler bilir....

anlatılmaz..

Koynunda uyuyan binlerce kişiyle, 

kendinden yaratılmış şehirde, 

Unutulmayan öyküler, 

yeniden yaşanacaklar başka biçimde...

Akşamla sabah, 

Gerçekle düş, 

Doğumla ölüm..

Öyle kalabalık tüm şehrin altı

Sevdaları gül kokulu güzelim anıları..

Kapanan mahmur gözlerde

gönüllerde

Anneannem

Diğerleri

Sıraselviler arasında saatin durgunluğa akışında...

Ansızın uçuşuyor rüzgarda kuşlar

Bakıyorum tepeden

Mevsimler geçiyor selvilerden..

Üşür müsün acaba o kapının ardında? 

Çok çok özlediğimi söyle ne olur babama..

Zamansız yoldaki toprağın üstünde

yel esince sürüklenen o öyküleri

Bilenler bilir....

anlatılmaz....', 'Bahçede kuruyan çiçekleri,  tavanda oynaşan eski gölgeleri,  Tutamayız.. El sallarız titrekçe.. Gitti Anneannem,  Bilenler bilir.... anlatıl...', ARRAY['Türk Edebiyatı','Şiir','Nalan Kazazoğlu']::text[], 8.5, '{"poet":"Nalan Kazazoğlu","poet_slug":"nalan-kazazoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/bilenler-bilir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir İlkyaz Düşüdür Ölüm', 'bir-i-lkyaz-dusudur-olum-bulent-ozcan-j912j', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir ilkyaz düşüdür ölüm

Sevi ateşidir ölüm

Her  an yaratır kendini

Çoğuldur, dişidir ölüm...

                                    26 Ekim 1996, Gaziantep', 'Bir ilkyaz düşüdür ölüm Sevi ateşidir ölüm Her  an yaratır kendini Çoğuldur, dişidir ölüm...                                     26 Ekim 199...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/bir-ilkyaz-dusudur-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'YanLızLık', 'yanlizlik-guray-sirin-eawe9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Kurumus bir gülün yaprağı kadar Kırgınım hayata 

Hiç olmadığım kadar hiçim şimdi 

Oysa. Ne kadarda umutluydum hayata 

Ben böyle değildim, beni sen bitirdin 

Kanadı kırık bir serçenin 

Ufak bir ekmek tanesine kanat çırpışı kadar içten sevmiştim seni 

Seni karada duran bir balıkçı teknesinin 

Denize olan hasreti kadar özlemiştim 

Ve..

Toprağın suya olan özlemi kadar beklemiştim 

Şimdiyse herşeyim boş 

Bom boş bir ümitle beklediğim 

Aslında geleceğim değiL 

Geride Kalan günerimi bekLiyorum..!', 'Kurumus bir gülün yaprağı kadar Kırgınım hayata  Hiç olmadığım kadar hiçim şimdi  Oysa. Ne kadarda umutluydum hayata  Ben böyle değildim, be...', ARRAY['Türk Edebiyatı','Şiir','Güray Şirin']::text[], 8.5, '{"poet":"Güray Şirin","poet_slug":"guray-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yanlizlik-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir BaşKa DünYa', 'bir-baska-dunya-guray-sirin-100tm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bana acılarda başka ne verdi? 

Şimdi sen yoksun, hasretin var. 

Sadece şişelerde gülüyor yüzüm 

tebessümüm şişelerle sadece 

Ölümü düşündüğüm şu anda 

Ve 

Ömrümün bu son damlacığında 

Sanaseslenmek gelsede içimden 

Olmuyor Çıkmıyor ağzımdan 

Sadece Kalbimle sesLenebiliyorum 

Onuda sen duyamıyorsuN 

Gurur ve Onur bir sel Gibi akıp gidiyor önümden 

Kendimi o Kadar kirLi 

vE 

O kadar sarhoş hissediyorumkİ 

Ak bir buludun üstünden akan 

Simsiyah bir su gibiyim... 

Sadece Gitmek 

Bir an önce cekip gitmek istiyorum.. 

Nereye oLursa oLsun Kİmseye veda etmeden gitmek..! 

Yanlızlıkla barıştı hayatım 

Kapkara bir gecede Bir ben varım 

Sabah olmasını beklediğim her gecenin ardından 

Her sabah gecenin gelmesini bekliyorum 

Çünkü ben Geceleri sevip Gündüzleri öLüyorum...', 'Bana acılarda başka ne verdi?  Şimdi sen yoksun, hasretin var.  Sadece şişelerde gülüyor yüzüm  tebessümüm şişelerle sadece  Ölümü düşündüğü...', ARRAY['Türk Edebiyatı','Şiir','Güray Şirin']::text[], 8.5, '{"poet":"Güray Şirin","poet_slug":"guray-sirin","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bir-baska-dunya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Hiç Olmadınki', 'sen-hic-olmadinki-turgay-karabiber-lk7cl', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen karanlığım, sen anlamsız çırpınışım 

sen metobolizmamın çözülmez denklemi

sen uzak diyarlarda  ağlayan göz

sen büyük kavgamın ütopyası 

sen hiç kimsem 

sen nefretin timsali

sen güzel ve kötü olan herşey

sen benim karamsarlığım ve serseriliğim

sen aptalca bir hülya 

ben o hülyadan bir türlü uyanamayan aptal', 'sen karanlığım, sen anlamsız çırpınışım  sen metobolizmamın çözülmez denklemi sen uzak diyarlarda  ağlayan göz sen büyük kavgamın ütopyası  ...', ARRAY['Türk Edebiyatı','Şiir','Turgay Karabiber']::text[], 8.5, '{"poet":"Turgay Karabiber","poet_slug":"turgay-karabiber","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sen-hic-olmadinki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sona Doğru', 'sona-dogru-yasemin-yarar-ua0ur', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bulantı ve

buyurtu 

sorunlu yaratılmışlık

son ver kendine', 'bulantı ve buyurtu  sorunlu yaratılmışlık son ver kendine...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sona-dogru-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yol', 'yol-yasemin-yarar-hocf0', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir ömür yol teptim

bir durak olsun ismim çağrılmadı

dönüp arkama bakmadım

içime içime 

derine derine 

delire delire 

yürüdüm', 'Bir ömür yol teptim bir durak olsun ismim çağrılmadı dönüp arkama bakmadım içime içime  derine derine  delire delire  yürüdüm...', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/yol-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sanadır Bütün Şarkılarım', 'sanadir-butun-sarkilarim-rezzan-kafali-s4nyp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nasıl da oynaşır ay ışığında sular

Boyun büker kimi zaman ağlaşır yıldızlar

Ben sensiz geçen günlerimden birini daha yaşarım

Sanadır bütün şarkılarım

Biri hüzünlü bir şarkı fısıldar geceyarısı

Başlar uykularımı kaçıran kalp ağrısı

Ben hep böyle sensiz gecelerde ağlarım

Sanadır bütün şarkılarım', 'Nasıl da oynaşır ay ışığında sular Boyun büker kimi zaman ağlaşır yıldızlar Ben sensiz geçen günlerimden birini daha yaşarım Sanadır bütün ş...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Kafalı']::text[], 8.5, '{"poet":"Rezzan Kafalı","poet_slug":"rezzan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sanadir-butun-sarkilarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitme Kal', 'gitme-kal-rezzan-kafali-kta4g', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sana gitme kal, deseydim keşke, 

Sevgine sevgimi, katabilseydim keşke, 

Kalır mıydın  bilmem, sevgisizim ben..

Sevgiyi öğretip, gitseydin keşke, 

Sana gitme kal, deseydim keşke.

Sana gitme kal, deseydim eğer, 

Gönlümdeki sevgiyi, bilseydim eğer, 

Kalır mıydın  bilmem, umutsuzum ben....

Umudu öğretip, gitseydin keşke, 

Sana gitme kal, deseydim keşke.

Sana gitme kal, deseydim keşke, 

Sevginde sonsuzu görseydim keske, 

Umudu acıyla besler miydim ben? 

Sana gitme kal, deseydim keşke.', 'Sana gitme kal, deseydim keşke,  Sevgine sevgimi, katabilseydim keşke,  Kalır mıydın  bilmem, sevgisizim ben.. Sevgiyi öğretip, gitseydin ke...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Kafalı']::text[], 8.5, '{"poet":"Rezzan Kafalı","poet_slug":"rezzan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/gitme-kal-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnsanlar Bir Başka Şimdi', 'i-nsanlar-bir-baska-simdi-rezzan-kafali-1g840', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İyiden iyiye başkalaştı insanlar arkadaş

Gözlerimi kanattı her güzel söz

Ne gerek vardı bilmem yalan söylemeye

Ben bile utanır oldum gerçeği söylemeye

İyiden iyiye başkalaştı insanlar arkadaş

Gönülden yaraladı beni her güzel söz

Aşıktım doğaya, insana sevdalıydım

Ne gerek vardı yalana, tertemiz dünyadaydım', 'İyiden iyiye başkalaştı insanlar arkadaş Gözlerimi kanattı her güzel söz Ne gerek vardı bilmem yalan söylemeye Ben bile utanır oldum gerçeği...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Kafalı']::text[], 8.5, '{"poet":"Rezzan Kafalı","poet_slug":"rezzan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/insanlar-bir-baska-simdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seninle', 'seninle-rezzan-kafali-1xcyi', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Seninle bir bütün olmuş gibiyim

İçtiğim suyla sarhoş gibiyim

Anılırsa anılsın seninle adım

Ben dünyaya yeniden gelmiş gibiyim

Bir dalgayla okyanusu aşmış gibiyim

Damlayan yağmurda  selde gibiyim

Güneşte kavrulsun seninle adım

Ben dünyaya yeniden gelmiş gibiyim', 'Seninle bir bütün olmuş gibiyim İçtiğim suyla sarhoş gibiyim Anılırsa anılsın seninle adım Ben dünyaya yeniden gelmiş gibiyim Bir dalgayla o...', ARRAY['Türk Edebiyatı','Şiir','Rezzan Kafalı']::text[], 8.5, '{"poet":"Rezzan Kafalı","poet_slug":"rezzan-kafali","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/seninle-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gökten Öte', 'gokten-ote-bulent-ozcan-9umat', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şiirini çaldılar göğün, 

Gök ağlar göksüzlüğüne...

Ben ki gökten öte sürgün, 

Ağlarım öksüzlüğüme...

Yitip giden gün gördüğün, 

Bugün oluyor dün yine...

Nedir içine gömdüğün, 

Akıt hüznünü şiirine...

                      2 Temmuz 2000, 

                      Hucknall-Notts./İngiltere', 'Şiirini çaldılar göğün,  Gök ağlar göksüzlüğüne... Ben ki gökten öte sürgün,  Ağlarım öksüzlüğüme... Yitip giden gün gördüğün,  Bugün oluyor...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/gokten-ote-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güzelleme', 'guzelleme-bulent-ozcan-ywctz', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Uyku, ölümün meleğidir; 

Şiir, şairlerin dileği...

Zaman, tanrıların eleğidir; 

Barış, çocukların yüreği...

Aşk, canın ipeğidir; 

Umut, hüznün bebeği...

İnsan insan emeğidir; 

Ölüm, yaşam gereği...

                10 Temmuz 2000, 

                 Hucknall-Notts./İngiltere', 'Uyku, ölümün meleğidir;  Şiir, şairlerin dileği... Zaman, tanrıların eleğidir;  Barış, çocukların yüreği... Aşk, canın ipeğidir;  Umut, hüzn...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/guzelleme-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Geliyorum', 'sana-geliyorum-i-lhan-yildirim-zg2sq', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gözlerimi açtığımda öyle yalnızım ki; 

Ama kapadığım zaman tam karşımdasın.

Biliyor musun? ey sevgili seni çok özledim.

Yokluğunda hayalinle kucaklaşıyorum.

Ey sevgili bilir misin? Avuçlarım bomboş,

Ama…ama hala bıraktığın sıcaklık avuçlarımda.

Bilir misin başını yasladığın omuzlarım bomboş.

Ama…ama hala sen kokuyor,yar kokuyor.

Bilir misin ey sevgili? 

Hiçbir şeyi ve hiç kimseyi artık duymuyorum.

Her yer ıpıssız…

Ama giderken fısıldadığın o çığlık hala kulaklarımda.

SENİ SEVİYORUM deyişin hala kulaklarımda.

Ey sevgili duy ne olur.Bende seni seviyorum…Bende seni…

Dön artık ne olur.Tut kaldır ellerimden.Al,şu koskoca dünyayı üzerimden.

Okyanusun ortasında batmış bir geminin enkazına tutunmuş kalmışım.

Umudum ecelimle savaşıyor.Mutlaka geleceksin değil mi? 

Umudum yorulup ecelime yenilmeden karar ver.Geleceksin değil mi yar? 

Ağır ağır batıyorum.Geleceksin değil mi? Değil mi yar? 

Sen yoksan bende yokum.Şimdi bırakıyorum ellerimi.Bırakıyorum…

Bırakıyorum soğuk derinliklere…karanlık delhizlere…

Vazgeçtim.Vazgeçtim ey sevgili.Artık gelmesen de olur…Artık gelme sakın! 

Çünkü ben sana gelmeye karar verdim.

Sana geliyorum…Aç kollarını…

Yüzümde gülücüklerle,beyazlar içinde…Sana geliyorum aç koynunu sevgili…

O kapkara yalnızlığın,

Ve yalanların,

Ve şerefsizliğin mekanı olan dünya onların olsun…

Vazgeçtim artık istemiyorum…Bütün her şey onların olsun…

Bana SEN yeter…bana YAR yeter…

GELİYORUM EY YAR…TOPRAĞINDA BANADA YER VARMI? ? ? ? 

                                                                                              İlhan YILDIRIM', 'Gözlerimi açtığımda öyle yalnızım ki;  Ama kapadığım zaman tam karşımdasın. Biliyor musun? ey sevgili seni çok özledim. Yokluğunda hayalinle...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yıldırım']::text[], 8.5, '{"poet":"İlhan Yıldırım","poet_slug":"i-lhan-yildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/sana-geliyorum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'yüzümde', 'yuzumde-burak-terzi-cjmo1', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'hani şimdi kapı çalınsa

içeri girsen

nerde kalmıştık desem

çayın hala sıcakolsa

bıraktığın gibi

yatağın gağanık olsa

yeni uyanmış gibi

hani şimdi kapı çalınsa

içeri girsen

nerde kaldın desem

ekmek almaya gitmişsin gibi

güneş batmamış

yazbitmemiş

zaman geçmemiş gibi

hani şimdi kapı çalınsaiçeri girsen

radyoda ensevdiğin  şarkı

gözlerim parlasa

yanağımda seni bulmuşum gibi', 'hani şimdi kapı çalınsa içeri girsen nerde kalmıştık desem çayın hala sıcakolsa bıraktığın gibi yatağın gağanık olsa yeni uyanmış gibi hani ...', ARRAY['Türk Edebiyatı','Şiir','Burak Terzi']::text[], 8.5, '{"poet":"Burak Terzi","poet_slug":"burak-terzi","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/yuzumde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-mahmut-capar-cynfw', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Siz neyi bilirsiniz? 

Hasretinden taşlar ufalanır, 

''çöl'' dersiniz.

yıldızlar söner aşkından, 

''Kara Delik.''

Gökler ağlar kederinden, 

''Yağmur'' dersiniz, 

Güneş yanar çaresizliğinden

''Sıcak.'' 

Hani? 

Hani siz herşeyi bilirdiniz? 

           Sevgiyi bilmiyorsunuz

Daha; 

           Aşkım''ı bilmiyorsunuz.

Öyleyse siz neyi bilirsiniz?', 'Siz neyi bilirsiniz?  Hasretinden taşlar ufalanır,  ''çöl'' dersiniz. yıldızlar söner aşkından,  ''Kara Delik.'' Gökler ağlar kederinden,  ''Yağm...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/hani-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölü Sevda', 'olu-sevda-burhanettin-yilmaz-jsak3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', '''Cevriye'' ye''

Ölü bir aşkın

bitmiş bir sevdanın

cılız akıntısına kapılıp

           sürükleniyorum.

Akıntı; kayalar arasında

bir o yana, bir bu yana savuruyor beni.

Her geçen gün

parça parça tükeniyorum.

Kendimi tekmelenmiş atılmış, 

bir ağacın dalından koparılmış

ümidi olmayan bir sonda

yolcusu olmayan bir görüyorum.

Kahroluyorum

kahroluyorum ama

bana can verecek

yeni aşklar, yeni sevdalar

arıyorum

06.08.2001', '''Cevriye'' ye'' Ölü bir aşkın bitmiş bir sevdanın cılız akıntısına kapılıp            sürükleniyorum. Akıntı; kayalar arasında bir o yana, bir...', ARRAY['Türk Edebiyatı','Şiir','Burhanettin Yılmaz']::text[], 8.5, '{"poet":"Burhanettin Yılmaz","poet_slug":"burhanettin-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/olu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Af', 'af-mahmut-capar-4zadv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevda masalıydı senle aşkımız

Bir sevgi rüyasına yatmıştık körü körüne.

Yaşamdan çokşey bekliyorduk.

Toplasan beklentilerimizi, 

Hepsi bir umut ışığı etmez.

Seni sevdiğim güne lanet ettim.

Binlerce kez ''Lanetler olsun'' dedim; 

Ama

Yine de

Sevmekten vazgeçemedim seni.

Sevgilim

N''olur bağışla beni...', 'Bir sevda masalıydı senle aşkımız Bir sevgi rüyasına yatmıştık körü körüne. Yaşamdan çokşey bekliyorduk. Toplasan beklentilerimizi,  Hepsi b...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Çapar']::text[], 8.5, '{"poet":"Mahmut Çapar","poet_slug":"mahmut-capar","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/af-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asi Ve Mavi', 'asi-ve-mavi-ahmet-can-akyol-7cp2m', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bugün kederliyim beterim bugün

Sesime ses değse çığlık oluyor

Üşüyor toprak  taşlar üşüyor

Vuslatı yakın eden yollar üşüyor

Yumma gözlerini uyuma bugün

Bütün gölgeler akşam oluyor

Üşüyor yaprak dallar üşüyor

Savrulup yırtılan rüzgar üşüyor

(İçimde kış gibi bir mevsim üşüyor) 

Oysa ben senden neler neler isterdim

Senli sevdalarda doğmak isterdim

Sabahlar isterdim asi ve mavi

Büyüsün isterdim ışığın rengi', 'Bugün kederliyim beterim bugün Sesime ses değse çığlık oluyor Üşüyor toprak  taşlar üşüyor Vuslatı yakın eden yollar üşüyor Yumma gözlerini ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Can Akyol']::text[], 8.5, '{"poet":"Ahmet Can Akyol","poet_slug":"ahmet-can-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/asi-ve-mavi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karçiçeğim', 'karcicegim-yasar-yabutlu-t21pt', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sana verdim karam, sevgilerin özünü, 

Her baktığım yerde görüyorum yüzünü, 

Sevmiyorum sensiz boşa geçen günümü, 

Karabasan gibi örtüyor gündüzümü.

Kulağımda çınlar büyülü sesin, 

Görmesem bile canım benimlesin.

Esin, deniz kokan meltemler esin

Karam''dan bana, içim serinlesin.

Hale oldun Karçiçeğim gönlümde, 

Aradığım ışık sensin ömrümde.

Gönlüm sende olursam ayrı yerde

Açık gider gözlerim öldüğümde.', 'Sana verdim karam, sevgilerin özünü,  Her baktığım yerde görüyorum yüzünü,  Sevmiyorum sensiz boşa geçen günümü,  Karabasan gibi örtüyor gün...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yabutlu']::text[], 8.5, '{"poet":"Yaşar Yabutlu","poet_slug":"yasar-yabutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karcicegim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzme Daha Fazla Ne Olur', 'uzme-daha-fazla-ne-olur-aykut-belli-xke9y', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ne olur arkadaş kalalım deme bana, 

İnsan arkadaş olabilir mi

Canından çok sevdiğiyle

Bu yürek sevdi mi bir kere

Zincir vurulmuyor, anla

Yoksa ister miydim seni üzmek

İster miydim dostluğumuzu zedelemek

Aşk ateşine düşen anlar beni

Beynin kalkar aradan

Kalbin hükmeder bütün vücuduna

Bilirsin yaptığının yanlış olduğunu

Ama elden ne gelir

Başka hiçbir şey görmez gözlerin

Ne yana baksan hatırlarsın onu

Nereye gitsen yanındadır o

Gözlerinin kapattığında karşındaki

Uyuduğunda rüyandaki

Dinlediğin şarkılardaki hep odur

İstemem seni zorlamak ama

Gelmiyor elimden seni sevmekten başka bir şey

Gör artık halimi, üzme daha fazla

Ne olur! 

	(25.05.2000)', 'Ne olur arkadaş kalalım deme bana,  İnsan arkadaş olabilir mi Canından çok sevdiğiyle Bu yürek sevdi mi bir kere Zincir vurulmuyor, anla Yok...', ARRAY['Türk Edebiyatı','Şiir','Aykut Belli']::text[], 8.5, '{"poet":"Aykut Belli","poet_slug":"aykut-belli","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/uzme-daha-fazla-ne-olur-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fırtına', 'firtina-duran-kayik-3k298', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gök gürlesin kıyamet koparcasına

Şimşekler çaksın karanlığı yırtarcasına

Yağmur yağsın bardaktan boşalırcasına

Rüzgar essin bir de ağaçları sökercesine

Hortum olsun, ne varsa silip süpürsün

Derelere sığmasın sular, sel olup taşsın

Deniz kudursun, ne varsa üzerinde batırsın

Sabah olduğunda, gördüklerine güneş şaşırsın.', 'Gök gürlesin kıyamet koparcasına Şimşekler çaksın karanlığı yırtarcasına Yağmur yağsın bardaktan boşalırcasına Rüzgar essin bir de ağaçları ...', ARRAY['Türk Edebiyatı','Şiir','Duran Kayık']::text[], 8.5, '{"poet":"Duran Kayık","poet_slug":"duran-kayik","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/firtina-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sabır Taşı', 'sabir-tasi-duran-kayik-wt06q', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ben bir sabır taşıyım, 

Hani hiç kırılmayan, aşınmayan, 

Rüzgara, güneşe, yağmura ayak direten.

Dururum sapasağlam, dim dik ayakta, 

Beni balyoz ile kırmaya çalışsalar da.

Bakarım onlara ümitle, sevgiyle, sabırla, 

Her ne kadar onlar bana kızsalar da.

Bazen üzülürüm, ümidimi kaybederim, ama, 

Ben bir sabır taşıyım.

Toparlarım tekrar, beklemeye başlarım yine.

Beni ısıtıp çatlatacak güneşe gülerim, 

Savurup sürükleyecek rüzgarla dalga geçerim, 

Beni kum yapmaya çalışan dalgaya seslenirim, 

Boşuna uğraşma, yapamazsın derim, çünkü, 

Ben bir sabır taşıyım.

Hani, derler ya, 

Bekleyen derviş muradına ermiş, 

Bekledim yıllarca muradıma ermek için, 

Ama çok bekledim, kaçtı pek çok tren.

Ben de derviş değildim, anladım zaten.

Anladım ki beklemek çare değildi dertlere, 

Hamle yapacaktın bir an önce kedere.

Güneşin, yağmurun yapamadığını yaptım kendime, 

Çatladım tam ortadan ikiye.

Artık ben çatlak bir sabır taşıyım.

Yılmadım ama mücadelemden, çünkü, 

Artık ben iki sabır taşıyım.', 'Ben bir sabır taşıyım,  Hani hiç kırılmayan, aşınmayan,  Rüzgara, güneşe, yağmura ayak direten. Dururum sapasağlam, dim dik ayakta,  Beni ba...', ARRAY['Türk Edebiyatı','Şiir','Duran Kayık']::text[], 8.5, '{"poet":"Duran Kayık","poet_slug":"duran-kayik","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/sabir-tasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'O Eski Ev', 'o-eski-ev-selcuk-yilmaz-6om4v', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karşıyaka''da bir sokağın içinde

Önünden geçerken o eski evin

Hatırası canlandı zihnimde; 

Kimbilir kimler yaşadı o eski evde, 

Belki de şehir hatlarının emekli

                                         bir kaptanı, 

Hani o beyaz badanalı odaları, 

Ve duvarında asılı o üniformalı fotoğrafı, 

 Bahçesinde kadeh tokuşturduğu

                                        serin köşesi, 

Şu ahşap çerçeveli penceresi ardında, 

Gün yüzü gördü mü taze karısı? 

Belki de bekledi kaptanını bir başına

                                          gece yarısı, 

x             x             x                   x

O nergisli baharlar gelip geçiverdi, 

Yasemin kokulu yaz akşamları, 

Mahalleli kadınlar kapı önünde

                                 hep söyleşti, 

Kekik kokuları hazanda bile 

              yamaçlarda  geziniverdi, 

Yıllar yılları kovaladı böyle gelip geçti; 

Yaşandı neşeli, hüzünlü sade anlar, 

Uğurlandı kapısından günün bir vakti, 

                                büyüdü artık çocuklar.

Kim bilir, ne sade ölümler yaşandı bu evde, 

Karşıyaka nın o eski sokağında, bir yerde, 

Anılarla kalmış bir başına, kimsesiz, 

Ayrılırken önünden, o ev şimdi çaresiz...

                                                      SY  9.8.2001 İZMİR', 'Karşıyaka''da bir sokağın içinde Önünden geçerken o eski evin Hatırası canlandı zihnimde;  Kimbilir kimler yaşadı o eski evde,  Belki de şehi...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/o-eski-ev-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburiyet', 'mecburiyet-mustafa-yildiz-demirci-fndff', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sabah dokuz erken çıktım yola...

Caddede ilerliyorum, mecburiyet caddesinde.

İnsanlar kıpır kıpır, kuşlar fısıldaşıyor.

Herkes; kendi derdinde, kendi aleminde.

Ama benim derdim başka, derdim aşk, 

Derdim sensin...

Herkes koşuyor bir yere, bir yerlere

fakat ben sana yürüyorum, sana geliyorum, 

kendi ruh alemimde.

Havuzda çocuklar oynuyor, birisi kanepede uyuyor, 

Yalnız ben oynuyorum aklımda seni, 

yalnız ben uyuyorum ayakta ve kalabalıkta...

Birisi direkteki afişi okuyor, 

Yalçın Menteş geliyormuş diyor.

Yanındaki o kim diyor? 

Ben gülüyorum.

Ben seni görüyorum afişte, 

çatıdaki leylekten seni diliyorum.

Gözlerim seni arıyor kaldırımda.

Kulağım sesini tarıyor ağızlarda, 

Lakin ne seni görüyor ne de duyuyorum, 

ama ben yürümekten usanmıyorum...

Gün erken doğuyor Uşak''ta, 

hani doğuya yakınya...

Fakat sen doğmuyorsun kalbime, 

açmıyorsun yüreğime...

Vitrinler ışıl ışıl sokakta, 

her ışık bir aşk, her aşk sensin.

Birgün bulursam, seni dar bir sokakta; 

Bu ışıklar yanacak dört bir yanda...

Yolda klakson sesi, müzik sesi uğulduyor kulağımda.

Kimisi hava atıyor, kimi evrak yetiştiriyor.

Ama ben sana yetişemiyorum, 

nefesini kulağımda duyamıyorum.

Banktaki adamın yorgun bakışlarında, 

ben hala seni arıyorum...

Gidiyorum hala ve ışıklara geliyorum.

Kırmızı yanıyor, kırmızı dudakların vardı ya hani! 

Sonra yeşil, yeşil bizim bahçemizdi deyip, 

karşıya geçiyorum, 

ve hala seni bulamıyorum...

Bir kız çiçek satıyor, saçlarının renginden; 

sarı alıyorum.

kapısında oturan yaşlı kadına, sen misali, 

veriyorum.

teşekkür ediyor nasıl da dertli bakıyor.

Ben aldırmıyorum, ben hala sana yürüyorum.

Durağa varıyorum, herkesin gözü saatte, 

bir vasıta derdinde...

Ama ben seni bekliyorum, omuzum direkte, 

gözlerim gelip geçen otobüslerde.

Gelmiyorsun özledim diyorum, artık özledim.

Bir sigara daha yakıyorum, 

gözlerim kaldırımın derinliklerinde...

Gidiyorum derinden derine, düşünceli bir şekilde; 

Bir simit alıyorum, ikiye bölüyorum.

Yarısı sana yarısı bana, 

bunu sana getiriyorum, yine bir başıma sana yürüyorum.

Belki bulurum deyip: 

Canıma, Can katıyorum.!', 'Sabah dokuz erken çıktım yola... Caddede ilerliyorum, mecburiyet caddesinde. İnsanlar kıpır kıpır, kuşlar fısıldaşıyor. Herkes; kendi derdin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız Demirci']::text[], 8.5, '{"poet":"Mustafa Yıldız Demirci","poet_slug":"mustafa-yildiz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/mecburiyet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizliği Öğrenemiyorum', 'sensizligi-ogrenemiyorum-selim-tuncbilek-95jao', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Senin 

Avuçlarında biriktirdiğin kadar

Sensizliği öğrenemiyorum...

Akreple yelkovan

Hep aynı saatte geçiyor

Acının ardından 

Sessizliğin kaldırımlarından 

Yağmıyor bu şehre 

Yasemin kokusundan 

Karanfil gölgesine yokluğun, 

Sığmıyor.

Toprağın ateşinde 

Güneşin sıcağında ilktiğim 

Ağrılı geceler çöküyor içime

Duyuluyor özlemin 

Çınar yapraklarında...

Ağlıyor içimde söylenmemiş şarkılar

Dağ başlarında çeşmeler gibi yetim 

Bıraktığın gözlerim.

Sensizliği öğrenemiyorum.', 'Senin  Avuçlarında biriktirdiğin kadar Sensizliği öğrenemiyorum... Akreple yelkovan Hep aynı saatte geçiyor Acının ardından  Sessizliğin kal...', ARRAY['Türk Edebiyatı','Şiir','Selim Tunçbilek']::text[], 8.5, '{"poet":"Selim Tunçbilek","poet_slug":"selim-tuncbilek","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sensizligi-ogrenemiyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'I-II', 'i-ii-aykut-belli-9z8i6', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İçimdeki sevgi mi ölen, yoksa ben mi? 

Denedim defalarca, 

Özlemiştim çünkü sevmeyi ve sevilmeyi.

Dolmak bilmiyor içimdeki boşluk, 

Öncekilere benzemiyor acım! 

Önceleri kalbim kanardı hep, 

İçim yanardı vefasızlardan; 

Şimdiyse beynim acıyor, 

Karar veremiyorum hayatıma.

Acaba gerçekten istediğim bu mu? 

Bir insanı sevmekse sevdim, 

Bir insan tarafından sevilmekse sevildim, 

Ama bir türlü sevinmedim.

Yüzümdeki gülücükler yalan, 

Kendimi eğlendiriyorum sadece.

Gerçek olan gönlüm: 

Beyaz bir kağıt üstündeki

Simsiyah göz yaşları gerçek! 

İnsanlardan yardım bekliyorum, 

Ne yapabilirler ben bile bilmiyorum! 

	(Mart 2001)', 'İçimdeki sevgi mi ölen, yoksa ben mi?  Denedim defalarca,  Özlemiştim çünkü sevmeyi ve sevilmeyi. Dolmak bilmiyor içimdeki boşluk,  Öncekile...', ARRAY['Türk Edebiyatı','Şiir','Aykut Belli']::text[], 8.5, '{"poet":"Aykut Belli","poet_slug":"aykut-belli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/i-ii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uyu Güzelim', 'uyu-guzelim-selcuk-yilmaz-x7g5e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Uyu güzelim haydi uyu

Koy o güzel başını dizlerime, 

Uyu canım haydi uyu; 

Belki rüyanda görürsün beni, 

Ak saçlı bir ihtiyar yol gösterir sana, 

Selvilerle dolu bir yolda buselerin

Belki de sevgi taneciklerin, 

Bir sevdalı peşinde koşar durur, 

Dizimde uyurken dalarsın hulyalara..

Belki ararsın benim gibi çocukluğunu

Sen de  bir yerde, uzak diyarlarda, 

Hep düşersin düşersin de

Hani bir türlü hiç düşemezsin, 

Lakin kabuslar görür durursun; 

Buna izin vermem hiç merak etme

Dizimde uyurken izin vermem

kabus görmene, 

Uyanışındaki o mahmur edayı

Görebilmek için seninle birlikte

Dizimde uyu güzelim uyu...', 'Uyu güzelim haydi uyu Koy o güzel başını dizlerime,  Uyu canım haydi uyu;  Belki rüyanda görürsün beni,  Ak saçlı bir ihtiyar yol gösterir s...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/uyu-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bekliyorum', 'bekliyorum-azad-uzan-a2ya4', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'umutsuzluğun ve yarına ait umutların kalbinde sevgi taşıyanlar için güzel duygularla beslenir.

kısacası: 

darmadağın düşüncelere inat; sevdaya dair duygular beslememiz öneriliyor bu şiirde...

albümü kırtasiyecilerden ve benden temin edebilirsiniz.', 'umutsuzluğun ve yarına ait umutların kalbinde sevgi taşıyanlar için güzel duygularla beslenir. kısacası:  darmadağın düşüncelere inat; sevda...', ARRAY['Türk Edebiyatı','Şiir','Azad Uzan']::text[], 8.5, '{"poet":"Azad Uzan","poet_slug":"azad-uzan","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bekliyorum-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umut', 'umut-ayca-buyukakbas-yuiht', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Adi Umut. 

Umut veren, hayat veren, 

Yurek alan insan. Umut.

Sevgiye dair herseyi ogreten yurek

Kactikca yaklasilan, 

Uzak durmaya calistikca daha gark olunan

Nev-i sahsina munhasir

Bir garip adam, Umut.

Cok uzak kentin dag cicegi

Bakislarinda dunya gizli

Oyle derin ki yuregi

Yukseklik korkularina bogan.

Izle beni.

Karda kurt surer gibi izle beni

Mezen, meyin, hayatin? 

Dans edeyim, raksedeyim, cengin olayim mi? 

Zengin olayim mi bir gulusunle bahar dokup

Dokulup ellerine bir sonraki eserin olayim mi? 

Sen soyle.

Bilirim. Sen ne zaman sevsen, 

Ne beynin, ne yuregin sigmaz bedenine

Semalar yetmez ucabilmek icin

Konacak yer sende degilken

Ne adres, ne firtina, sancilar girer her yerine

Damarlarinda gezen kan degildir

Sen sen degilsindir artik, 

Hic gelmemistir ki gitsin, 

Icin rahat, bombos, sessizsindir.

Bilmezsin gece ne uyandirir ter icinde

Bilmezsin tek nota sana hangisini hatirlatir

Kalbinin kus gibi ucmaya calistigini bilirsin

Birakmaz bedenin, hapistir kafesinin icinde

Sende degildir, baskasinda degildir

Gizimiz nerde saklidir kimse bilmez

Ne ararsin nerde ararsin, kimdir cevabin

Kimdedir en asil zamanin

Nerede ayrilmistir gercek ve hayal

Nerede kopmustur ipler, 

Nicin gece ruyalarin tarihte gezer

Bilemez, aglarsin.

Anlatamazsin. 

Ne istersin yaninda olsun saril

Ne uzaklarda olsun ozle

Ne dibinde otursun, duru ve asIL

Ne de anlatsin isteksizligini sozle

Sadece baksin. Dursun ve baksin gozlerine.

Narin bir yaz yagmuru gibi dagilsin bedenine

Cocuklugunuzdaki misketleri paylasin 

Ruyalarinizdan sarmas dolas aksamlara uyanin

Bilirim sen ne zaman sevsen, sen olmaktan cikarsin.

Yillarca bekledigim ''LA''sin. 

Notalar sana ibadet ediyor, seni bekliyor bahar

Yillarca daha bekleyebilirim anlamani

Yuzyillarca bekleyebilirim bir gun gelip beni almani. 

Umud''um, yurek alan, hayat verenim. 

Beni boyle seveceklerine, 

senin gibi nefret etsinler. 

Anliyorum ki seni kaybetmekten korkmak ve

Seni beklemek senden guzel, Umut.

Bir garip dag cicegi Umut. 

En guzel enstrumanin bastigi en guzel ''LA'' Umut.

Umut...', 'Adi Umut.  Umut veren, hayat veren,  Yurek alan insan. Umut. Sevgiye dair herseyi ogreten yurek Kactikca yaklasilan,  Uzak durmaya calistikc...', ARRAY['Türk Edebiyatı','Şiir','Ayça Büyükakbaş']::text[], 8.5, '{"poet":"Ayça Büyükakbaş","poet_slug":"ayca-buyukakbas","theme":"Türk Şiiri","is_hero":false,"total_lines":62,"source_url":"https://www.antoloji.com/umut-20-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korkak', 'korkak-mustafa-cakir-guxhb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Ben çocuklar gibi sevdim.Devler gibi acı çektim. Can Yücel''e

Korkak kalemim ne zaman yazsa

İçimden kopardığı ile kalır 

Elimden aldığı bilincimi 

Oradan oraya savurmaya başlar.

Ölümü düşündürür apansız.

.

Aştığım noktada bulabilsem kendimi

Engin olur bulut koyardım adımı 

Gömülü müydüm, yoksa ! 

Çıkmaya mı çalışıyordum.

Bilemiyorum yeniden ölmeye mi..

.

Kalbim mi ölmeliydi, ben mi !

Kalemim mi susmalıydı,yüreğim mi...', 'Ben çocuklar gibi sevdim.Devler gibi acı çektim. Can Yücel''e Korkak kalemim ne zaman yazsa İçimden kopardığı ile kalır  Elimden aldığı bilin...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/korkak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Saklı', 'sakli-mustafa-cakir-lzuio', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ne erkendi yaşam için

Ne yaşamdı içinde yaşadığımız

Her aşk çıkmazında pervasızca

Hüzün saklı.

.

Her ağlayışında içinden kopan 

Her koptuğunda ağlayan yaşam

Her aşk kendinde büyüktür.

Her aşkın içinde

Hüzün saklı...', 'Ne erkendi yaşam için Ne yaşamdı içinde yaşadığımız Her aşk çıkmazında pervasızca Hüzün saklı. . Her ağlayışında içinden kopan  Her koptuğun...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sakli-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümüz', 'omrumuz-mustafa-cakir-yqbs2', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Üç beş satır değildi ömrümüz

Nokta koymayı ise yakıştıramadık

Kendimize.

Yaşanacak ne kadar temiz duygular varsa

İçimizde

Koyduk önünüze işte biz...', 'Üç beş satır değildi ömrümüz Nokta koymayı ise yakıştıramadık Kendimize. Yaşanacak ne kadar temiz duygular varsa İçimizde Koyduk önünüze işt...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/omrumuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İsimsiz', 'i-simsiz-mustafa-cakir-cl5fm', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir gecenin sonunda arzuya uyanmak 

Seninle uyumak seninle uyanmak 

Ne getirir bilinmez, yarının adı yok

Belki ıslanmaktır, belki unutmak 

Adın yok...', 'Bir gecenin sonunda arzuya uyanmak  Seninle uyumak seninle uyanmak  Ne getirir bilinmez, yarının adı yok Belki ıslanmaktır, belki unutmak  A...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/isimsiz-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mavi Randevu', 'mavi-randevu-mustafa-cakir-gdcz2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'dedim...Derinlerde aradım gözlerinin sıcaklığını 

dedi....Üşüyordum ısıtmalıydı içimi

dedim...Mavim umudum hayalim

dedi....Korkum seni bulamamaktandı, ölümden değil 

dedim...Gül dalında buldum elma tadında kaldım senin için 

dedi....Gel okyanuslada aradığım bir damla su ol benim için

dedim...Yılgınlığım sabahım gecem canıma can olmak için 

dedi....Eğer seninde dileğin ise gel ikimiz için

dedim...Bilinmedik dağlarda bilinmeyen yollar olalım 

dedim...Su seni ısıtsın beni Rüzgar dağlasın 

dedi....Çöllerde kalmış gibi yanıyor yanıyor içim

dedi....Gel okyanusta aradığım bir damla su ol benim için

dedim...Bedenleri saran bir damla suyun kırmızısı gibiyim 

dedim...Görmek isteyene baharın müjdecisi gibiyim 

dedi....Yüreğini dağlayan rüzgarın sesi gibiyim

dedi....Randulaştım maviyle ikimiz için

dedim...Kadınım su''yum buharlaşalım ruhumuz için 

dedi....Sonra uçalım gökyüzüne bütünleşelim maviyle

dedi....Ardından yağmur olalım inelim yeryüzüne

dedim...Rüzgar atımız Güneş yolumuzu aydınlatsın 

dedi....Bir damla yağmur olup yeşertelim yeryüzünü

dedim...Gözeneklerine inelim hayatın bulamasınlar bizi

dedi....Zaman ve mekan ötesinde sonsuzlaştıralım sevgimizi

dedim...Acıdır yaşamın gerçeği yansımaz hiç bir düş e 

dedi....Yaşamda tadılan acıyı taşımamalı düşlere

dedim...Ki onlar kendi hayatlarını değiştirememişlerdir  (düşler) 

Bana neyimsin diye soruyordu..ona her şeyimsin, dedim.

Gözünden bir kaç damla yaş aktı, bana; sana muhtacım dedi...', 'dedim...Derinlerde aradım gözlerinin sıcaklığını  dedi....Üşüyordum ısıtmalıydı içimi dedim...Mavim umudum hayalim dedi....Korkum seni bulam...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/mavi-randevu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen-siz', 'sen-siz-mustafa-cakir-9t2ld', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'belli belirsiz silüetiyle beklemekte

yol

duman 

sis

bulanmış torosların eteği 

geçit vermez 

yol lar bit mez

ö l ü m  gitmez kapımdan 

şafak kırmızı 

kan kırmızı 

ben kırmızı 

güneş doğmaz gecelere 

erkendi karartma 

siyah hakim renk 

ben karardım o sardı 

yol 

duman 

sis 

gözlerinin içinden geçit verir 

bir dilek tut 

umut olmasın içinde

unutmak olmasın 

çırılçıplak gökyüzüm 

                   sen

bulutlar

                             siz', 'belli belirsiz silüetiyle beklemekte yol duman  sis bulanmış torosların eteği  geçit vermez  yol lar bit mez ö l ü m  gitmez kapımdan  şafak...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/sen-siz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yoldakiler', 'yoldakiler-mustafa-cakir-bghqt', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yudumladıkça uyuşmuş bedenim yeryüzünün dar sokaklarında 

Kör kuyularda sınadım gözlerimi, dipsiz uçurumlarda sulandım, maviyi gökyüzüne astım.

Sırtımı verdiğim taş duvar ihanetin gölgesini gösterdi bir anlam taşımıyordu ihanet.

Gözlerimi kapadım boğulduğum anılarım yaşımı hatırlattı, bir gün daha bitiyordu, 

Bir an geçmişti uyandım, uyuduğum her dakika için fazladan mavi yükledim heybeme. 

Zamana bir adım var  nasıl geçmişse hayat ırmağı donmuş suları budala istekler 

yorgun hayatlar düşmüş aklıma bir kalp bulunmuş sokakta, vurulmuş, enine boyuna düşünülmeden.Bir adam hayali günün ilk ışıkları silüetini gördüğüm anda kalbimi uzatıyorum düşünmeden 

yolculuk beni yormuş derin derin nefes alıyorum.Sabahı, akşamı günü, gündüzü mor u beyazı 

kızıl''ı ala yı herşeyi maviye veriyorum.Hesapsız yaşıyorum hesapsız.Bir ''''an'''' için ölüyorum 

bin ''''an'''' için diriyim.İnsanların aura''ları gözümün içinde parıldıyor, beynimi kemiriyorlar

yalansız yaşam arzusu, yarından önce bugünün sevgisi bırakılmış yaşam hazları, hayvanlaşmış 

istekler nabızlarını hissediyorum insanların beynimde korkak ürkek saldırgan hayvansı.

Sonu gelmez arzulara gem vurmada derinler.Dalıp gittikçe ruh seslerinin ardından

yollarca düşüncelerce bilinmezlerin peşinden koşmakta insanlar...', 'Yudumladıkça uyuşmuş bedenim yeryüzünün dar sokaklarında  Kör kuyularda sınadım gözlerimi, dipsiz uçurumlarda sulandım, maviyi gökyüzüne ast...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/yoldakiler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Evren', 'evren-mustafa-cakir-x3cj8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'o dede ki kendine demir ufuklar yapardı 

krom gözleri vardı 

gözlerine baktığımda eritirdi yaşamı

yine bir günün sonunda bana adı kaldı 

eritmişti yaşamı 

yaşam olmuştu adı dedemin 

ve ben onun yanında büyüdüm 

ırmaklarla konuşurdu 

susunca bir fırtına kopardı 

birden anımsadımki 

yeryüzünde onun adı saklıydı 

ben o nun yanında büyüdüm 

ben onda büyüdüm...', 'o dede ki kendine demir ufuklar yapardı  krom gözleri vardı  gözlerine baktığımda eritirdi yaşamı yine bir günün sonunda bana adı kaldı  eri...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/evren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asiydi', 'asiydi-mustafa-cakir-b553r', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Asılsızdı anlamsız hayat

bir gök uçurumundan düşerken 

tutundu 

tutunmasaydı tuz göllerine düşerdi 

tuz nedir bilirmisin? 

acıyan yerlerin düşmanı sevgimizin 

unutulmayan anısız acısız bir yaşamda 

buluşmak dileğiyle yandı 

tutundu

tutunduğu her yer onunla anıldı. 

Bir günün sonunda onada düşen 

acıdan aldığı paydı...', 'Asılsızdı anlamsız hayat bir gök uçurumundan düşerken  tutundu  tutunmasaydı tuz göllerine düşerdi  tuz nedir bilirmisin?  acıyan yerlerin d...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/asiydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak', 'ciplak-mustafa-cakir-ztn96', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ne aradı elbisesini

nede ölçüsünü verdi terziye

metrelerce kumaş içinde

bir benliğini saracak renk bulamadı

birdenbire anladıki

ne kraldı nede çıplak

yinede giydiği bedeni sevdi

ruhundan kömür karası aşklar yarattı kendine

bildiği bütün dualarıda unutmuştu

evrenini kendi giydirirdi açıkça...

..

...', 'Ne aradı elbisesini nede ölçüsünü verdi terziye metrelerce kumaş içinde bir benliğini saracak renk bulamadı birdenbire anladıki ne kraldı ne...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ciplak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyormusun', 'biliyormusun-mustafa-cakir-xw2jn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ki özlem 

aşktan daha derin bir yara

kimliksiz

kişiliksiz

özlediğin kadar arzu ediyorsun 

istediğin kadar ulaşıyorsun 

ve seni saran Hic lik 

ancak kanına karışıp 

susuzluğunu dindirebiliyor

belki bir an soluyorsun 

hayvan gibisin 

ne düşünmen gerektiğini değil

ne yapman gerektiğini biliyorsun 

otomatik yaşam arzusu 

bir bedende ruh olmak arzusu...', 'ki özlem  aşktan daha derin bir yara kimliksiz kişiliksiz özlediğin kadar arzu ediyorsun  istediğin kadar ulaşıyorsun  ve seni saran Hic lik...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/biliyormusun-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Deme', 'deme-fatih-ozsahin-fmq7t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Aşkta fedakarlık haddini aştı.

Bu aşkın uğruna ne verdin deme. 

Sözün dönüp geldi bana ulaştı.

Hep gönül kırmayı severdin deme.

Onulmaz aşkımın bu son gününde, 

O güzel, şirin günlerin sonunda, 

''Aşkı verdin ama aşkın yanında

Ateş lezzetini de verdin deme.', 'Aşkta fedakarlık haddini aştı. Bu aşkın uğruna ne verdin deme.  Sözün dönüp geldi bana ulaştı. Hep gönül kırmayı severdin deme. Onulmaz aşkı...', ARRAY['Türk Edebiyatı','Şiir','Fatih Özşahin']::text[], 8.5, '{"poet":"Fatih Özşahin","poet_slug":"fatih-ozsahin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/deme-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unuttum', 'unuttum-mustafa-cakir-xm3xx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yaşamak adına, sevmek adına, senin benim adıma

O sancılı bahar sabahında toprağa düşmüş

Tohumun inlemesini duyduğum sesinde

Acı ve sevinci görecek kadar uyanık 

Düşmeden o sefil düşünceye 

Unuttum adımı...', 'Yaşamak adına, sevmek adına, senin benim adıma O sancılı bahar sabahında toprağa düşmüş Tohumun inlemesini duyduğum sesinde Acı ve sevinci g...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/unuttum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensizken', 'sensizken-mustafa-cakir-2nael', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'yüzün çizilidir şehrin üstünde

yüzümün haritasında seni sevmek

seninle göz uçumda buluşmak 

santim santim sevişmek istiyorum seninle 

anısız hiç bi noktamız kalmayana kadar

arzu bu kadarmı derin olur 

sevişmek özlemi bu kadarmı çeker adamı

Şafaksız, kalıpsız, mavimsi

Ve senin yaşadığını hissederim 

Gömülmek isterim gözlerine

tabutsuz, külsüz, umarsız.

yanında olmak özlemi 

bir derinde birikir yaralarım

elini uzatabilirmisin

uzattığın elinin yanmasından korkmadan 

acılarımı okşayabilirmisin

bir kadeh rakıda adını saklasam 

Bir uçurumdan sana seslensem 

sessizce ağlasam duyarmısın 

gözlerimden girilir diye ipucu versem

karanlıklarımdan korkmadan girebilirmisin

gözlerini kapasam gözlerime doğru akıtsam 

seni, dal kırılmasına benzer ses duysan 

bir adım atmaya değil ölmeye kalksam derinliklerinde

derinlik anlamsızca büyüse yinede dalarmısın sularıma

derin bir nefes daha çeksem sigaramdan ve sen içimde dumanlı 

yollarda olsan, anlasan ne kadar derine gittiğini dumanın

her nefeste seni çektiğimi anlasan seninle dolsa sensizken...', 'yüzün çizilidir şehrin üstünde yüzümün haritasında seni sevmek seninle göz uçumda buluşmak  santim santim sevişmek istiyorum seninle  anısız...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Çakır']::text[], 8.5, '{"poet":"Mustafa Çakır","poet_slug":"mustafa-cakir","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/sensizken-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biliyorum', 'biliyorum-daisy-daisy-zvuzj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Göremiyorsam da

Duyamıyorsam da

Şimdi

Biliyorum

Atan bir yürek var

Beni gören

Beni duyan

Beni bilen

Hissediyorum

O yeter

Biliyorum', 'Göremiyorsam da Duyamıyorsam da Şimdi Biliyorum Atan bir yürek var Beni gören Beni duyan Beni bilen Hissediyorum O yeter Biliyorum...', ARRAY['Türk Edebiyatı','Şiir','Daisy Daisy']::text[], 8.5, '{"poet":"Daisy Daisy","poet_slug":"daisy-daisy","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/biliyorum-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öylesine Sevmiştim', 'oylesine-sevmistim-fatih-cinar-500eo', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'giderken bir resmini bırak bana

yalnız gecelerde bakacak

giderken bir tokanı bırak

sensiz kokularda koklayacak

giderken al yanına hatıraları

bırak bana yalnız yalnızlıkları

alt tarafı bir sevda benimki

zaten ben seni öylesine sevmiştim

giderken çantanı alırken sırtına

yükledin tüm acıları boynuma

sen ellerin yatağında 

bende hasretini alırım koynuma

                                   söz: müzik=fatih çınar

                                   ulaşım(0312 431 10 19)', 'giderken bir resmini bırak bana yalnız gecelerde bakacak giderken bir tokanı bırak sensiz kokularda koklayacak giderken al yanına hatıraları...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/oylesine-sevmistim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek', 'sevmek-mumtaz-begen-2kleb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Sevmek; 

Sevildiğini hissedebilmek, 

Sevmek; 

Sende onu sevdiğini söyleyebilmektir! ..

Sevmek; 

Yaşamın her anında onu düşünebilmek, 

Sevmek; 

Sahip olunsun olunmasın, sevebilmektir! ..

Sevmek; 

Hep beklentisiz olabilmek, 

Sevmek; 

Her şeyi ama her şeyi, 

karşılıksız verebilmektir! ..

   

Sevmek; 

Çağrılmadan yanına gidebilmek, 

Sevmek; 

Çoğu zaman ağlanacak hâle bile gülebilmektir! ..

Sevmek; 

Cepteki son metelikle alınmış simidi ikiye bölebilmek, 

Sevmek; 

Gerekirse sevilenin uğruna ölebilmektir! ..

Sevmek; 

“Delilerle sır boncuğu dizebilmek”

Sevmek; 

Her çirkinlikte bile bir güzellik görebilmektir! ..

Sevmek; 

Köroğlu’ nun   kır atına binmek, 

Sevmek; 

Dünyaya kafa tutabilmektir! ..

Sevmek; 

Kah bulutların üzerinde gezinmek, 

Sevmek; 

Kah yeryüzünde sürünmektir! ..

Sevmek; 

“Yetti gayri” dememek, 

Sevmek; 

Yorulmak nedir? .. Usanmak nedir? ..

Bilmemektir! ..

Sevmek; 

Aşkın nârında yanabilmek, 

Sevmek; 

Yandıkça “insan”  olunduğunun 

farkına varabilmektir! ..

Sevmek; 

Gerektiğinde nefsine “dur” diyebilmek, 

Sevmek; 

Her şeyden önce gururunu yenebilmektir! ..

Sevmek; 

Her karara saygı gösterebilmek, 

Sevmek; 

Neden ne olursa olsun, kin beslememek, 

nefret etmemektir! ..

Sevmek; 

İncinsen de, kırılsan da asla küsmemek, 

Sevmek; 

Sanki hiçbir şey olmamışçasına, 

çarpıp gittiğin kapıdan dönebilmektir! ..

Sevmek; 

Konuşmadan anlaşabilmek, 

Sevmek; 

Soğuk kış gününde 

paylaşabilmektir bir tek gocuğu, 

Sevmek; 

Nefes alabilmek, 

Velhâsılı sevmek; 

Yaşatabilmektir içindeki çocuğu! ..', 'Sevmek;  Sevildiğini hissedebilmek,  Sevmek;  Sende onu sevdiğini söyleyebilmektir! .. Sevmek;  Yaşamın her anında onu düşünebilmek,  Sevmek...', ARRAY['Türk Edebiyatı','Şiir','Mümtaz Beğen']::text[], 8.5, '{"poet":"Mümtaz Beğen","poet_slug":"mumtaz-begen","theme":"Türk Şiiri","is_hero":false,"total_lines":66,"source_url":"https://www.antoloji.com/sevmek-22-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadın Benim Herşeyim', 'kadin-benim-herseyim-yusuf-sabri-bagriacik-gq5jn', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kısa metrajlı reklam filmleri gibi

kısacık fakat düşündürücü, 

bi sözle başladım geceye

yazdım ve düşündüm.

anlattıklarım sonradan 

bi manaya dönüştü içimde 

sesini duyduktan sonra, 

aramızda ki kilometreleri yok sayarcasına

gülüşünü duyduktan sonra, 

düşlerimiz ayaklarımıza gelircesine.

çevremdeki insanların

birbirlerini hatırlamaları için 

belli şarkıları var

bizim ise şiirlerimiz ve düşlerimiz

atilla ilhan''ımız, edip cansever''imiz

ahmed arif''imiz ve nazım hikmet''imiz var

kısa metrajlı reklam filmlerinden sonra

başlayan uzun, upuzun filmler gibi

başladı uzun yazılarım

yazılarımın bitmesi şimdilik hayal gibi görünüyor

bi heyecanla kalktım yerimden 

annem ne var ne oldu diye sordu

gidiyorum dedim 

içimden, kendi dünyama diye de ekledim

aklımdaki satırlar öylesine ufak ki, 

öylesine fazla ki… 

korkarım ufak olmalarından

saklandıklarında bulamam

korkarım fazla olmalarından

unutup bi daha hatırlamayacağım, 

satırları bi daha tam istediğim gibi 

toparlayamayacağım diye 

yazılarım bitmeden tuvalete gidemem 

saatlerdir sıkıyorum dişimi 

ha bitti ha bitecek diye 

prostat kanseri olacağım ona yanıyorum. 

şarkıların biri bitiyor biri başlıyor 

ne ilhammış be bitmek bilmiyor

bu gidişle ben biteceğim. 

sırf sesini duymakla yazdıysam

peh be...

karşıma çıkacağın zamanlar da haber ver de

önceden bi tuvalet ihtiyacımı karşılayayım 

biliyorsun vakit olmuyor bi daha 

senden az önce 

yani sesini duymaktan az önce 

tanımadığım 

bi yerde bi şiir dinledim

bi arka sokakta

bi arka bahçe de 

başka türlü bi yerde 

belki de bi salkım söğüdün altında 

ya da 

denize sıfır bi tepeden aşağıya bakarak

neyse 

az önce, senden önce 

sesini duymadan önce 

bi şiir dinledim 

sesi titreyen

genç bi adamdan

ilk deneyimi gibiydi

belki ilk defa okuyordu bi şiiri

belki de kendi şiiriydi

ama güzeldi 

bi çınar ağacı altındaki, 

iki aşıktan bahsediyordu.

bu olaylar kendim kadar 

düşlerim kadar gerçek 

hayır 

bazen soruyorsun ya 

nereden uyduruyorsun bu yazıları diye 

sen gerçeksin dimi 

işte o anlattıklarım da gerçek

o şiir de iki bahar sonrasını anlatıyordu 

iki bahar sonra sen nerede olacaksın

nerede olacaksın

nerede kadın

yoksa o denize sıfır olan tepede mi 

ya da en eski salkım söğüdün altın da mı 

belki de arka bahçe de 

ya da başka türlü bi yerde işte 

nerede olduğunun önemi var mı 

içimiz de ki bu şiirler olduğu sürece 

şarkıların bi süresi 

vardır

üç dakika bilemedin beş dakika sonra biter

şiirin sonu var mıdır 

nazım’ın  sonumu vardır 

yazdığı şiirlerin sonu olsun

saatlerce okusan kim sana dur der ki 

ya da nakaratları istediğin kadar tekrarlasan

hızımı alamadım yine

hızlandım

bazen, 

bazen düşünürüm 

içimden acaba ters şeritte miyim diye geçiririm

karşımdan gelen ışıklar 

gözlerimi kamaştırır

gideceğim yol 

benliğime öyle bi yerleşmiş ki 

gözlerim kapalı olsa kaç yazar

bi an için, 

sesini duyar gibi olmak istemiştim sadece

sesini duymak kalp atışlarımı hızlandırdı

adrenalinim yükseldi

biraz yaşlı olsam, 

bi doktora görüneceğim neredeyse 

bana ses yolladığın da göremediğim yerlerden 

nerelerdeydin

arka bahçede mi, 

eski bi salkım söğüdün altın da mı, 

belki de başka türlü bi yerler de 

içimdeki mumun alevi 

parlaklığını yitirir gece uzadıkça 

ve yazılar bitmek bilmedikçe

kıvranmaktan hal kalmaz hiç bi yerim de 

bu gidişle iki üç yıla kalmaz prostat olurum

bi üstadım söylemiş 

“kadın bi şairin doğma sebebidir” diye

doğrudur kadın her şey 

kadın şiirlerin başlangıcı

ayrılığın temel taşı

kadın içimi sızlatan kumral

kadın benim anam, 

şimdi mışıl mışıl uyuyor 				

bi bana şiir yazmadın diye sitem eder her lahza

dur be anne bilmezsin 				

bi kavrulayım bu yağda, 				

söz sana yanmış bi yağ olmadan, 

yazacağım en güzel şiirimi		

kadın benim hayal kurduğum insan

kadın benim her şeyim

şiirlerimin, 

ayrılıklarımın, 

özlemlerimin bel kemiği

kadın benim türkçe hocam

ne diye bilirim ki 

eğer bi şairin doğma sebebiyse kadın

ve yine o kadın şairin esiriyse

işte bu karmaşalıktan çıkamamaya yazılan yazılarsa şiir

ben şiiri adam gibi yaşayanlardanım.', 'kısa metrajlı reklam filmleri gibi kısacık fakat düşündürücü,  bi sözle başladım geceye yazdım ve düşündüm. anlattıklarım sonradan  bi manay...', ARRAY['Türk Edebiyatı','Şiir','Yusuf Sabri Bağrıaçık']::text[], 8.5, '{"poet":"Yusuf Sabri Bağrıaçık","poet_slug":"yusuf-sabri-bagriacik","theme":"Türk Şiiri","is_hero":false,"total_lines":141,"source_url":"https://www.antoloji.com/kadin-benim-herseyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yine Yalnızım', 'yine-yalnizim-baris-erzincanli-0cddd', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yoklugun her geçen gün daha da zor geliyor

Sensizlik her saniye ölüm geliyor 

Hasret bukadar acımı 

Yokluğun bukadar zormu? 

Hiç yıldızlara baktınmı bazen öyle parlıyorlarki tıpkı tıpkı o ela gözlerin gibi 

Bazen öyle soluyorlarki tıpkı tıpkı benim soluk gözlerim gibi 

Parladıklarında seni yanımda hissetiyorum 

Öyle mutlu oluyorum ki hiç uyanmak istemiyorum bu güzellikten

Sen olmalıydın şimdi yanımda gezmeliydik şu dağı taşı ormanı

Sen olmalıydın yanımda bakmalıydım o doyumsuz gözlerine

sen olmalıydın ki...! 

işte herşey senle başlıyor ama sensiz bitiyor...!', 'Yoklugun her geçen gün daha da zor geliyor Sensizlik her saniye ölüm geliyor  Hasret bukadar acımı  Yokluğun bukadar zormu?  Hiç yıldızlara ...', ARRAY['Türk Edebiyatı','Şiir','Barış Erzincanlı']::text[], 8.5, '{"poet":"Barış Erzincanlı","poet_slug":"baris-erzincanli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yine-yalnizim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gittin Ya', 'gittin-ya-sair-khan-fksac', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gökyüzünü yine sen  ve kardeşlerin kaplamıştınız pırıl pırıl ışıldayarak

Bense bir sigaramdan bir senden nefes çekmekle meşgul

Sigaramın ateşi gibi sensizliğin yanmışlığıyla kavruluyorum.

Kim bilir şimdi nerelerde, kiminle hangi gönüldesin

Bu kadar mı acıtacaktı içimi bu ani gidişin

Bu kadar mı yakacaktı bu kopuşun 

Acılar denizine gömdün ayağıma taşlar bağlayarak

Ben seni ne çok sevmiştim senin için ömrümü yoluna sermiştim

Her gecenin zifiri karanlığını aydınlatan gözlerinde kaybolmaya

Güller açtıran gülüşünü mimiklerini izleyip gülmeye, 

İçli o denli güzel söylediğin ‘elbet bir gün buluşacağız’ diye başladığın şarkına

Öyle alışmıştım öyle benimsemiştim ki hiç bunlardan kopmayacağımı zannetmiştim

Aynı acıları farklı yerlerde bize çektiren bu kader değil miydi? Bizi yan yana getiren, 

Tüm umutların tükendiği, toprağımızın çatlayıp kuruduğu zaman yağan yağmur misali

Bizi kavuşturan aynı dere yatağında sürüklenmemize sebep olan.

Öyleyse neden bu ani kaçışın, sen bunu yapmazdın be gülüm söyle hadi söyle 

Söyle ne olur yaratan aşkına söyle neydi seni insafsızca değiştiren.

Ben artık bittim, eski günlerime dönmek istemiyorum artık sensiz yaşamak mı asla.

Alışamıyorum anla sensizlik inan öyle zor ki tüm dünyayı yükleseler omzuma

Ne bu kadar zor gelirdi ne de bu gidiş kadar acı verirdi güçsüz şu vücuda, 

Hiçbir şeyim düzgün gitmedi ki şu dünya da baksana yaradana ettiğim dualar, 

Sensiz olacaksam al canımı diye ettiğim feryatlar bile tutmuyor kabul görmüyor

Ah canım ama inan bu acı bu yıkılmışlığa rağmen hala bu gözler seni bekliyor.', 'Gökyüzünü yine sen  ve kardeşlerin kaplamıştınız pırıl pırıl ışıldayarak Bense bir sigaramdan bir senden nefes çekmekle meşgul Sigaramın ate...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gittin-ya-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gömelimmi Bu Aşkı', 'gomelimmi-bu-aski-sair-khan-tvpmj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gömelim mi artık bu sevdayı bu aşkı bu canlar verilmiş sevgiyi

Sen bilirsin canım sen ne dedin de ben seni kırdım

Ömrümü isteseydin daha iyi olurdu ya neyse zaten bundan farksız istediğin

Gitmeliyim buralardan diyorsun ya git bebeğim

Çıkmalısın hayatımdan dedin ya çıkayım canım

Dünyanın sonu değil yaşarsın dedin ya, işte şimdi yanıldın aşkım bu hem dünyanın sonu

Sur u üfledin hayatıma son verdin güzel gözlüm

Neden gömüyoruz ki bu güzelim günleri, umutları ve hayatımı

Neden gömmüyoruz bize yanlış yapan şu kaderimizi

Neden gömmüyoruz ki acıları dertleri kederleri

Tamam istediğin gibi olsun gömelim bu sevdayı gömelim umutlarımızı

Ama unuttuğun bir şey var can, gömdüklerimizin yeşerip çiçek olma ihtimalide var..', 'Gömelim mi artık bu sevdayı bu aşkı bu canlar verilmiş sevgiyi Sen bilirsin canım sen ne dedin de ben seni kırdım Ömrümü isteseydin daha iyi...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/gomelimmi-bu-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Serseri', 'serseri-burhan-ciftci-3o8x1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Arama hayatın cilvesine bahane

Benim gönlüm sersri ise sanane

Sanmaki bunu bana söyleten kinimdir

Bilirmisin  kızım sen serseri kimdir

Aldanır sana kem gözle bakanlar

Onlardır cihanda en mesut olanlar

Sen Eyyyy Sosyete kızı

Sil o hayalindeki karanlık eseri

Çoklarından üstündür şu gördügün serseri.', 'Arama hayatın cilvesine bahane Benim gönlüm sersri ise sanane Sanmaki bunu bana söyleten kinimdir Bilirmisin  kızım sen serseri kimdir Aldan...', ARRAY['Türk Edebiyatı','Şiir','Burhan Çiftci']::text[], 8.5, '{"poet":"Burhan Çiftci","poet_slug":"burhan-ciftci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/serseri-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ben', 'ben-sair-simyaci-7q6p0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'bilirim ümidin boş olduğunu

yinede  hayaller kurasım gelir

düzde yaşamayı beceremezken

dağa tırmanasım gelir

gönül seher ister yaşar akşamda

saadet dilesede kavrulur gamda

elime hiç silah almadıysamda

turnayı gözünden vurasım gelir

(şaiirin ismini bilmiyorum)', 'bilirim ümidin boş olduğunu yinede  hayaller kurasım gelir düzde yaşamayı beceremezken dağa tırmanasım gelir gönül seher ister yaşar akşamda...', ARRAY['Türk Edebiyatı','Şiir','Şair Simyacı']::text[], 8.5, '{"poet":"Şair Simyacı","poet_slug":"sair-simyaci","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ben-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiçbir', 'hicbir-bulent-ozcan-ih0g7', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiçbir aşk

  Hiçbir yerde

    Hiçbir zaman

Hiçbir yerde

  Hiçbir zaman

    Hiçbir aşk

Hiçbir zaman

  Hiçbir aşk

    Hiçbir yerde

                           25 Eylül `97, Londra', 'Hiçbir aşk   Hiçbir yerde     Hiçbir zaman Hiçbir yerde   Hiçbir zaman     Hiçbir aşk Hiçbir zaman   Hiçbir aşk     Hiçbir yerde            ...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/hicbir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ver Bana Sılayı', 'ver-bana-silayi-sitki-dursel-lp0dg', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Virandır geceleri gurbetin

       boynu bükük bırakır insanı

      ağlasan duyulmaz ölsen duyulmaz

      dar eder adamı buranın sokakları

    

      sıladan selamı gelir dostların

     yalnız bir alınmış selam düşer ağzından

     gene yarım kalırım üsküdarlarda

     duaları yetişir ancak anam ve bababımın

    sıla sıla hala varmıdır dağlarında duman

   serince esermi akşamları  o yüksek tepelerin

   çiğler düşermi sabahları çinkolu evlerine

  ve vaktinde yemiş verirmi  cümle meyvelerin

   sana uzaklardan avuclar dolusu hasret

  gözüm yaşlı selamlar yolluyorum

  yanında gurbet elden sılaya

  koskocaman bir dert hediye ediyorum

  Adına yar  tadına sevgi sonuna 

  Mutlu ve buruk bir şeymiş diyorum.............', 'Virandır geceleri gurbetin        boynu bükük bırakır insanı       ağlasan duyulmaz ölsen duyulmaz       dar eder adamı buranın sokakları   ...', ARRAY['Türk Edebiyatı','Şiir','Sıtkı Dürsel']::text[], 8.5, '{"poet":"Sıtkı Dürsel","poet_slug":"sitki-dursel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ver-bana-silayi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkın Balladı', 'askin-balladi-ozdemir-asaf-i2my6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'AŞKIN BALLADI

Andırırsın beni bana, bana beni, 

Dediklerinde, duyduklarında, 

Yazdıklarımda seni bana, bana seni, 

Söylemesem bile, saklamadıklarımda.

Ah hep aklımda, hep aklımda; 

Andırırsın seni sana, sana seni, 

Gözlerinde, kulaklarında, dudaklarında.', 'AŞKIN BALLADI Andırırsın beni bana, bana beni,  Dediklerinde, duyduklarında,  Yazdıklarımda seni bana, bana seni,  Söylemesem bile, saklamad...', ARRAY['Türk Edebiyatı','Şiir','Özdemir Asaf']::text[], 8.5, '{"poet":"Özdemir Asaf","poet_slug":"ozdemir-asaf","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/askin-balladi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Türkistan Neden Ağlar', 'turkistan-neden-aglar-kaya-kuzucu-3zczc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Azizim su diye ağlar

Mecnun hu diye ağlar

Deryada bir gül açmış 

o da su diye ağlar...

Ya Türkistan neden ağlar

Ağlar yüreğimi dağlar

Başucumda Musul Kerkük

Anadolum diye ağlar...

Bülbül gülüm diye ağlar

Gül bülbülüm diye ağlar

Nahçıvanım Karabağım

Bitsin zulüm diye ağlar....', 'Azizim su diye ağlar Mecnun hu diye ağlar Deryada bir gül açmış  o da su diye ağlar... Ya Türkistan neden ağlar Ağlar yüreğimi dağlar Başucu...', ARRAY['Türk Edebiyatı','Şiir','Kaya Kuzucu']::text[], 8.5, '{"poet":"Kaya Kuzucu","poet_slug":"kaya-kuzucu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/turkistan-neden-aglar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şeffaf Saray', 'seffaf-saray-mehmet-fatih-koksal-6iktm', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Aynalar kırılınca başladı sessizliğim

Şimdi ne gözüm yolda, ne seni gurbet saklar

Şeffaf saray içinde öldü kimsesizliğim

Buzdan bir perde gibi eridi uzaklıklar

Hulyânın çağrısına verdi dalgalar seni

Şekiller, mesafeler... Hangisinepes ettim? 

Fesleğen yeşilinde koklayarak yâr seni

Bir sihirli şavk ile tâ içimde hissettim

Yokluk ne, hasret ne ki vuslatın bu deminde

Yanı başımda esen zümrüt kokulu tufan

Hâtıralar uyandı bu saray âleminde

Yeniden yaşanırken zümrüt çağında zaman

....

Üç boyutlu, gölgeli hakikatle eğer

Gün olur el ederse hayâllerim sırayla

Kırık aynalarımın esrârına hükmeder, 

Şeffaf sarayda seni arar, bulurum Leylâ', 'Aynalar kırılınca başladı sessizliğim Şimdi ne gözüm yolda, ne seni gurbet saklar Şeffaf saray içinde öldü kimsesizliğim Buzdan bir perde gi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Fatih Köksal']::text[], 8.5, '{"poet":"Mehmet Fatih Köksal","poet_slug":"mehmet-fatih-koksal","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/seffaf-saray-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gözlerim Yaslanir', 'gozlerim-yaslanir-emrullah-erdinc-r7p1n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gözlerim yaslanir

sen yoksun misali usurum 

soguk bir havanin nemli 

bir yaz sicaginin buruklugu

sanki anilarimi canlandirir

sen yoksun misali

gözlerim yaslanir 

ciseliyen yagmur misali

daglardan eriyip akan kar misali 

titrerim korkmus bir cocuk misali

hep seni dusunurum gözlerin aklimdan cikmaz 

bir cift parlak zeytin misali 

ya seni kaybetme korkusu 

ya evet seni kaybetme korkusu 

iste hayallerimin dagilis misali

sonsuza dek kaybolus misali

ve gözlerim yaslanir yaslanir 

ögle yastirki bu kalbimin derinliklerine 

iner butun kötu hayallerimi siler 

beraberinde akip götururur

sanki senin kaybolusunu görur misali

sana olan askimin ancak bana 

mezarda son bulur misali', 'Gözlerim yaslanir sen yoksun misali usurum  soguk bir havanin nemli  bir yaz sicaginin buruklugu sanki anilarimi canlandirir sen yoksun misa...', ARRAY['Türk Edebiyatı','Şiir','Emrullah Erdinç']::text[], 8.5, '{"poet":"Emrullah Erdinç","poet_slug":"emrullah-erdinc","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gozlerim-yaslanir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızım', 'yalnizim-ahmet-unal-cam-5wpal', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İşte gemiler gidiyor, 

Bırakıp beni kumsalda.

Kırık gönlüm; 

Koskoca bir ıssız ada

Her yanda yalnızlık

Her yanda hüzün.

Ne sevenim var

Ne gülenim yüzüme

Yalnızım, 

yalnızlıklar içinde', 'İşte gemiler gidiyor,  Bırakıp beni kumsalda. Kırık gönlüm;  Koskoca bir ıssız ada Her yanda yalnızlık Her yanda hüzün. Ne sevenim var Ne gü...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Ünal Çam']::text[], 8.5, '{"poet":"Ahmet Ünal Çam","poet_slug":"ahmet-unal-cam","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yalnizim-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cumaları', 'cumalari-ahmet-caglar-arsu-sf3eb', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Icime derin bir huzun dolar…

Her Cuma ogleden sonra, aksamustu o aralarda

Nedendir diye sormasinlar sakin, soyleyemem ki

Qlmayacak sevgilim gecmek bilmeyen kahrolasi 48 saat boyunca diye yanimda.

Sen  olmadigini bili bile kosuyorum calan her kapiya, telefona…

Ne olur bir kere de yaniltsan sanki, 

Yeminli misin tatli sevgili, 

Hep ayni yasatmaya Cumalarin devamini sen bana!

Azla yetinmek bana gore degil demez miyim ben

Hep daha fazla, daha fazla

Dusundukce icim rahatliyor, biliyorum ya

Kalbindeyim nasil olsa, 

sen olmadigin zamanlarda benim yanimda

‘SENI SEVIYORUM’ diyen diller, bedenini saran kollar

Kahrolsunlar benim degillerse; 

Yansinlar milyonlarca, milyarlarca kez

Cehennem sicaginda

Kalbim tek birseye agliyor

Koskaca bir hayat

Ne yazik ki seni sevmek  icin cok kisa! 

Hayat zaten bastan zordu 

Cumalar sanki armagan yaninda

Ben bunlari dusunuyorum iste

O kahrolasi Cuma aksamlarinda

Seyreklik giriyor aramiza

Farkindasin yakin zamanda

Ama ben aldirmiyorum

Ayrilik degil nasil olsa

Simdiki gibi yeter ki ol yanimda

Almaya kalkisma sakin

Cumalarimi bile benden

Hersete ragmen onlari bile seviyorum

Anla tatli sevgili ANLA! ! !', 'Icime derin bir huzun dolar… Her Cuma ogleden sonra, aksamustu o aralarda Nedendir diye sormasinlar sakin, soyleyemem ki Qlmayacak sevgilim ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Çağlar Arsu']::text[], 8.5, '{"poet":"Ahmet Çağlar Arsu","poet_slug":"ahmet-caglar-arsu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/cumalari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dağcı', 'dagci-yasar-yabutlu-6ffeu', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalçındağ, 

       Hep o dağ, 

               Süslerdi rüyalarını, 

Birgün geldi, 

         Gerçekleştirdi

                 Hülyalarını.

Kolaymı ki, ulaşmak

          Yalçındağın zirvesine, 

Kaç can aldı, 

         Çoğu yarıda kaldı, 

                 Dayanamayıp cilvesine.

Ama o başardı zirvede işte! 

Mutluluk çemberi gibiydi dönüşte, 

Yıllar önceki bir sevgili gibi, 

Nedense görmedi birdaha, 

Ne rüyada, ne düşte...', 'Yalçındağ,         Hep o dağ,                 Süslerdi rüyalarını,  Birgün geldi,           Gerçekleştirdi                  Hülyalarını. Kol...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yabutlu']::text[], 8.5, '{"poet":"Yaşar Yabutlu","poet_slug":"yasar-yabutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/dagci-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Han', 'han-yasar-yabutlu-xvcye', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kara bir orman, içinde bir han, 

Yapılmış besbelli gürgenden çamdan.

Kaç yolcuya, kimbilir? 

Kucak açmış bir zaman

Hep birşeyler çalmış, 

Götürmüşler bu han''dan.

Dışı güzel, 

Ne yazık! 

İçi viran

Neye yarar, 

Gözüksede küheylan.', 'Kara bir orman, içinde bir han,  Yapılmış besbelli gürgenden çamdan. Kaç yolcuya, kimbilir?  Kucak açmış bir zaman Hep birşeyler çalmış,  Gö...', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yabutlu']::text[], 8.5, '{"poet":"Yaşar Yabutlu","poet_slug":"yasar-yabutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/han-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kiracı', 'kiraci-yasar-yabutlu-ui56e', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İçimde sancıydı, 

Çok da yalancıydı

Kalbimi boşalttı

Demek kiracıydı.', 'İçimde sancıydı,  Çok da yalancıydı Kalbimi boşalttı Demek kiracıydı....', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yabutlu']::text[], 8.5, '{"poet":"Yaşar Yabutlu","poet_slug":"yasar-yabutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kiraci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutsuz umut', 'umutsuz-umut-hulusi-cavus-y1bi1', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ne şiirler kalır kalbimde

hüzne dair aşkı anlatan

Ne yarım yamalak sevdaların 

peşinden koşarım

Bir umut için çarpışmak da olmasa

Ben bu dünyada nah kalırım', 'Ne şiirler kalır kalbimde hüzne dair aşkı anlatan Ne yarım yamalak sevdaların  peşinden koşarım Bir umut için çarpışmak da olmasa Ben bu dün...', ARRAY['Türk Edebiyatı','Şiir','Hulusi Çavuş']::text[], 8.5, '{"poet":"Hulusi Çavuş","poet_slug":"hulusi-cavus","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/umutsuz-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Onurunla Büyü Çocuk', 'onurunla-buyu-cocuk-meryem-akkin-0j33x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Onurunla büyü çocuk; 

Kaleminle, kitabınla büyü 

Türkü türkü 

Zılgıt zılgıt büyü

Gülleri koparma; 

Karanfilleri ezme çocuk, 

Sabahları temiz ellerinle şafağı kucakla 

Kondurabildiğin kadar öpücük kondur; ona, 

Başın dik; cesaretle yürü çocuk

Kerpiç bacalardaki leylek yuvaları hatırla 

Düştüğün yolları, 

Çizdiğin duvarları, 

İlle aşkını hatırla çocuk

Hudutsuz gecelerde beklediğin ananı, 

İnadına yaşadığın günleri hatırla..!', 'Onurunla büyü çocuk;  Kaleminle, kitabınla büyü  Türkü türkü  Zılgıt zılgıt büyü Gülleri koparma;  Karanfilleri ezme çocuk,  Sabahları temiz...', ARRAY['Türk Edebiyatı','Şiir','Meryem Akkın']::text[], 8.5, '{"poet":"Meryem Akkın","poet_slug":"meryem-akkin","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/onurunla-buyu-cocuk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seviyorum', 'seviyorum-soner-arica-f191o', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gidemem, 

Sana kolay gelir git demek

Gidemem.

Yapamam, 

Unutamam seni yeni bir aşkla

Yalan olabilir, 

Derse dilim inanma

Benim yerim; 

Senin yanın.

Beni asla bırakma

Seviyorum deli gibi seviyorum! 

Gözlerinden yol aldım, 

Yürüyorum...

Yokluğuna alışmayı düşünemem

Ölüm olur ayrılığın, 

Biliyorum...', 'Gidemem,  Sana kolay gelir git demek Gidemem. Yapamam,  Unutamam seni yeni bir aşkla Yalan olabilir,  Derse dilim inanma Benim yerim;  Senin...', ARRAY['Türk Edebiyatı','Şiir','Soner Arıca']::text[], 8.5, '{"poet":"Soner Arıca","poet_slug":"soner-arica","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/seviyorum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bitmeliysen Bit', 'bitmeliysen-bit-soner-arica-uy7ae', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Saçların silinir düşümden önce, 

Hayalin tutuşur düşüncelerde

Sevda mı? 

O ne ki

Erir günden güne

Bitmeliysen bit, 

Beni bitirme.

Seçmedim mevsimden ben ayrılığı, 

Zamanla bitmeyi sen belirledin

Günlerden karayı ben istemedim, 

Bitmeliysen bit, 

Beni bitirme.

Bitir kendini, 

Aşkımız gibi

Bende kalma git yeter! 

Beni bitirme.

İçim titriyor

Tüm bitişlerde

Bende kalma git yeter! 

Beni bitirme.

Anacak şarkılar belki olacak, 

Sanma ki; susacak sana dualar

O aşk ki; bir daha yaşanmayacak

Bitmeliysen bit, 

Beni bitirme...', 'Saçların silinir düşümden önce,  Hayalin tutuşur düşüncelerde Sevda mı?  O ne ki Erir günden güne Bitmeliysen bit,  Beni bitirme. Seçmedim m...', ARRAY['Türk Edebiyatı','Şiir','Soner Arıca']::text[], 8.5, '{"poet":"Soner Arıca","poet_slug":"soner-arica","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/bitmeliysen-bit-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Derbeder', 'derbeder-soner-arica-w21tk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Nasıl oldu bilmiyorum

Neden diye düşünmeden, 

Aşka düştü dertsiz başım

Dert arar gibi kendine

Gelde kader de istersen

Sana aşık olmak varmış, 

Büyüledin sardın beni

Niye yaptın bunu niye? 

Hani böyle bir aşk yoktu? 

Hani sen de çok şanslıydın

Hani bendim tek gerçeğin, 

Ölse herşey ben ölmezdim? 

Ölüyorum günden güne, 

Gülüm soldu, gönlüm soldu

İçimdeki çocuk soldu, 

Niye yoksun, 

Söyle niye? 

Perişanım, paramparça

Darıldım, kırgınım sana

Kahroldum sen gidince

Kendimi vurdum yollara

Hani nerede yeminlerin? 

Bitecekti bu gitmeler, 

Sebebi sensin halimin, 

Derbeder oldum, derbeder...', 'Nasıl oldu bilmiyorum Neden diye düşünmeden,  Aşka düştü dertsiz başım Dert arar gibi kendine Gelde kader de istersen Sana aşık olmak varmış...', ARRAY['Türk Edebiyatı','Şiir','Soner Arıca']::text[], 8.5, '{"poet":"Soner Arıca","poet_slug":"soner-arica","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/derbeder-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşında', 'karsinda-black-rose-6c9n2', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Birgün dikileceğim karsına...

Soracagım sana.

Sevgin için ne yaptın diye.

Konuşamayacaksın! ..

Düşünemeyeceksin! ..

Ağlayamayacaksın.

Ve anlayamayacaksın.

Beni Öldürmek istesen bile...

Yapamayacaksın.

Çünkü o gün; 

Ben senin karşında 

Sen ise mezarda olacaksın.', 'Birgün dikileceğim karsına... Soracagım sana. Sevgin için ne yaptın diye. Konuşamayacaksın! .. Düşünemeyeceksin! .. Ağlayamayacaksın. Ve anl...', ARRAY['Türk Edebiyatı','Şiir','Black Rose']::text[], 8.5, '{"poet":"Black Rose","poet_slug":"black-rose","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/karsinda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tutamadıklarım', 'tutamadiklarim-black-rose-4m6up', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir hayal kapladı içimi

Birdenbire bir hayal.

İmkansızlıklar geldi aklıma

Ağladım en zor yerinde mutlulugun.

Akan gözyaşlarımı bilirsiniz.

Onlar; tutamadıklarım.

Zorluklar içinde zorda kaldım.

Bulamadım bir çıkış yolu ve..

Dost aradım beni anlayacak.

Kimler bırakıp gitti bilirsiniz! 

Onlar; cayamadıklarım.

Hepsinde buldugumu zannettim.

Hepsini de ölesiye sevdim.

Sevdim onları hatalarıyla.

Hangileri terketti bilirsiniz.

Onlar; aslında sevemediklerim.', 'Bir hayal kapladı içimi Birdenbire bir hayal. İmkansızlıklar geldi aklıma Ağladım en zor yerinde mutlulugun. Akan gözyaşlarımı bilirsiniz. O...', ARRAY['Türk Edebiyatı','Şiir','Black Rose']::text[], 8.5, '{"poet":"Black Rose","poet_slug":"black-rose","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/tutamadiklarim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sahipsiz Şiir', 'sahipsiz-siir-bahtiyar-ocal-mw10n', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Saat gecenin ikisi....

Yalnızlığın en  koyusunu yaşıyorum şimdi..... 

Vicdanım perişan, gönlümse bildiğin gibi, 

Yine sen yine sen diye anlatıyor olan biteni.

Ya varsın yada yoksun, 

Aslında hepsi bu, 

Ama ne çare ki, 

Gönül anlamaz, gönül dinlemez beni, 

Sen hep varsın, hep var olacaksın.

Aslında sen hiç olmadın ki...

Güneşin olduğu gibi, yağmurun, baharın, 

Gülün olduğu gibi aslında hiç olmadın ki, 

Unutulan anıların senaryosunda, 

Adına yazılan şiirlerin başlığında, 

Hıçkırıklarla dost olan gözyaşlarının 

Boşluğadüştüğü anlarda

Hiç olmadınki.......

Kır çiçeğinin saflığında, 

Göçmen kuşun kanadında, 

Solup biten bir ömrün yıllarında, 

Umutla beklenen sevdanın yollarında, 

Aslında sen hep vardın, hep vardın...

Ama hiç olmadınki.....

Ah........bir olsaydın, bir olmayı bilseydin, 

Kimbilir neleri anlatırdım...

Sevmeyi bilmeyen gönlüne neleri...

“ Ben bir bahtı karayım, 

   Bahtımda senden yanayım, 

   Dokunma ne olur yanında kalayım, 

   Çok görme şu garibe güzel yüzünü, 

   Baktıkça sana susuzluğuma kanayım.”

Ah........bir olsaydın, bir olsaydın yanımda, 

Susuzluk neki, yürek sancısının yanında, 

Hasretin kuruttu beni, can kalmadı canımda, 

Zehir sevdan yüreğimi aştı.

Dolaşıyor şimdi vücudumda, damarlarımda.....', 'Saat gecenin ikisi.... Yalnızlığın en  koyusunu yaşıyorum şimdi.....  Vicdanım perişan, gönlümse bildiğin gibi,  Yine sen yine sen diye anla...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Öcal']::text[], 8.5, '{"poet":"Bahtiyar Öcal","poet_slug":"bahtiyar-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sahipsiz-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Niye mi?', 'niye-mi-black-rose-9gp5k', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Seni niye mi sevdim? 

Belki beni sevdigin için.

Belki de aradıgım oldugun için.

Ama bildigim ve önemli olan

Seni herseye ragmen sevmem degil mi? 

Seni karsıma aldıgımda.

Gülen gözlerin için değil.

Ellerimi tutan o biricik

Pamuk yumagı ellerin için degil

Ya da uzaktayken ben 

Beni özlemen için degil

Sevdim seni 

Sadece sevdim

Sensiz de olsa 

seni yaşamak için.

Belki bir gün namusum olman için.', 'Seni niye mi sevdim?  Belki beni sevdigin için. Belki de aradıgım oldugun için. Ama bildigim ve önemli olan Seni herseye ragmen sevmem degil...', ARRAY['Türk Edebiyatı','Şiir','Black Rose']::text[], 8.5, '{"poet":"Black Rose","poet_slug":"black-rose","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/niye-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kapını Çalan Benim', 'kapini-calan-benim-soner-arica-fzadm', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu kadar kolay değil, 

Böyle bitmez aşklar

Ellerin hasetinden böyle terkedilmez! 

Bu yanlış benim değil, 

Gözümde yaş durmaz

Yorgunum, küskün değil

Aşka göğüs gerdim.

Gidecek yerim olsaydı giderdim, 

Kapını aç ne olur, 

Kapını çalan benim...

Ellere ne oldu, dert oldu, niye? 

Gururum kirlendi

Kem gözden kem dilden, 

Sebebim olanlar bayramlar etsinler

Benim bayramlarım, şenliğim sensin.

Yetmedi sevişmeler, 

Yetmedi öpüşmeler, 

Ruhum huzur bulur

Yanımda ol yeter.', 'Bu kadar kolay değil,  Böyle bitmez aşklar Ellerin hasetinden böyle terkedilmez!  Bu yanlış benim değil,  Gözümde yaş durmaz Yorgunum, küskü...', ARRAY['Türk Edebiyatı','Şiir','Soner Arıca']::text[], 8.5, '{"poet":"Soner Arıca","poet_slug":"soner-arica","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/kapini-calan-benim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu mu Sevda', 'bu-mu-sevda-soner-arica-ivrud', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Olmadığın her yer gurbet, 

Gelmediğin evim zindan

Yatağım taştan soğuk

Dayanamaz buna insan...

Tükenecek neyim kaldı, 

Uykularım çoktan bitti, 

Yetmiyor aklım çözmeye

Bu mu sevda dedikleri? 

Bu mu sevda? 

Bu nasıl aşk? 

Bu hasret bana belkide tuzak.

Ölümü bile göze aldım

Geliyorum sana çırılçıplak...

Beni de al, 

Sen neredeysen

Nefes almak bana sensiz yasak

Ölümü bile göze aldım, 

Geliyorum sana

Çırılçıplak...

Utanırım, söyleyemem

Yaşadığım yalnızlığı

Kelimeler yetmiyor ki; 

Bu mu sevda dedikleri? 

Paylaşırım yokluğunu 

Gecenin sessizliğiyle

Yetmiyor yalnız hayaller

Bu mu sevda dedikleri?', 'Olmadığın her yer gurbet,  Gelmediğin evim zindan Yatağım taştan soğuk Dayanamaz buna insan... Tükenecek neyim kaldı,  Uykularım çoktan bitt...', ARRAY['Türk Edebiyatı','Şiir','Soner Arıca']::text[], 8.5, '{"poet":"Soner Arıca","poet_slug":"soner-arica","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/bu-mu-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bütün Gemiler Yandı', 'butun-gemiler-yandi-mehmet-sercan-tezcanoglu-s3szf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Düşmüştü bir kez toprağa cemre. 

Alev almıştı yeşiller, 

Bürünmüştü kızıllara, 

Küllere, grilere... 

Hiç kolay olmadı kalkmak ayağa, 

Biliyor musun? 

Sokaklar yarim oldu yokken sen. 

Ve şimdi kapının ardındasın 

Dönüyorsun geri, dönülmezlerime. 

Kopmuştu en kalın ipler 

Körelmiş, paslanmış çiviler gibi 

Beton duvarlara tutunamazken ben 

Kalkıp şimdi sen 

Geri dönüyorsun. 

Hiçliğimi yaşadım ben 

Kırık dökük bir dolmuş gibi 

Bir araba çöplüğünde 

Kurarken hurda düşleri 

Yollarıma kavuşuyorum derken 

Bir sürpriz yapıp 

Kapıyı çalıyorsun. 

En koyu renklerle boyarken 

Duvarlarımı, 

Pencereden güneş davetsiz girip de evime 

Çevirirken karalarımı, aklara 

Apansız 

Duruyorsun şimdi karşımda. 

Söyle bana 

Yakılan gemiler 

Limana döner mi geri?', 'Düşmüştü bir kez toprağa cemre.  Alev almıştı yeşiller,  Bürünmüştü kızıllara,  Küllere, grilere...  Hiç kolay olmadı kalkmak ayağa,  Biliyo...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/butun-gemiler-yandi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sustuğum Anlar', 'sustugum-anlar-bahtiyar-ocal-fhzvo', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Konuştuğum anlardı aslında

Sustuğum anlar, 

Avazım çıktığı kadar feryat ettğim, 

Haykırdığım anlardı o anlar, 

Sustuğum anlar...........

Anlatamadıklarımı anlattığım 

Boğazıma düğümlenip kalanları 

Kulağına fısıldadığım anlardı o anlar, 

Sustuğum anlar...........

“Ey sevdiğim saçların geceyle yarışır sanki, 

  Zifiri karanlık, 

  Ey sevdiğim gözlerin, gökyüzüyle yarışır sanki, 

  Kainat kadar derin, 

  Ey sevdiğim sözlerin yüreğime batar sanki, 

  Bir hançer kadar keskin.''

Konuştuğum anlardı aslında 

Sustuğum anlar, 

Anlatamadıklarımı anlattığım, 

Dokunurken saçlarına ellerimle, 

Kulaklarına fısıldadığım anlardı o anlar, 

Sustuğum anlar............

Kime söyleyeyim bu derdi, kim çare olur ki..., 

Sen benim son aşkımsın, 

Sevmeye doyamadığım, kıyamadığım, 

Gözümde son damlasın, içimde son sızım.

Sustuğum anlardı aslında 

Konuştuğum anlar.......

Suskun serenatların 

Anlatıldığı anlardı o anlar

Sustuğum anlar....... 

.

.

.

.

Yine sustum işte....

Ne olur konuşma sus sende, 

Yürekler söylesin gerçekleri, 

Bak kalbim ne diyor bir dinle.....

Dinle........

.

.

SENİ SEVİYORUM.....

SENİ SEVİYORUM.....

SENİ SEVİYORUM.....

				

				KARDELEN’E', 'Konuştuğum anlardı aslında Sustuğum anlar,  Avazım çıktığı kadar feryat ettğim,  Haykırdığım anlardı o anlar,  Sustuğum anlar........... Anl...', ARRAY['Türk Edebiyatı','Şiir','Bahtiyar Öcal']::text[], 8.5, '{"poet":"Bahtiyar Öcal","poet_slug":"bahtiyar-ocal","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/sustugum-anlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çiçeksiz Kalan', 'ciceksiz-kalan-mehmet-sercan-tezcanoglu-qbjb9', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'En nadir bulunan çiçekler gibiydin. 

Beş bin fitinde bir dağ lalesiydin soğuk rüzgarlarda. 

Ayazlarımda bir kar çiçeği oluveriyordun, 

Ulaşılmaz uçurumlarda.

Beyazlar içinde gülümsüyordun o zaman 

Bir gelin çiçeği gibi 

Kimi zaman da gül gibi bitiyordun Babil''in Asma Bahçeleri''nde 

Seni koparıp sana armağan ediyordum düşlerimde 

Bir çocuğun ellerindeki papatya demetlerinin arasında göründüğün de oldu 

Seviyor sevmiyora, kim vurduya gittiğin zamanlar 

Her baharda yeniden doğuyordun 

Orkideler, yaban incirleri sarıyordu etrafını 

Ilık rüzgarlarla reverans yapıyorlardı önünde her biri 

Ve sonra bir zaman geliyordu 

Açmıyordu çiçeklerin 

Kavaklar ağlıyordu toprağında 

Gözyaşlarıyla yeşertmeye çalışan seni 

Kırlangıçlar vardı, akılları sende kalan 

Bedenleri göç eden 

Çiçeklenemiyordun ya, bir çocuk ağlıyordu 

Ne gül olabiliyordun artık ne de bir papatya 

Sen doğamayınca yeniden 

Kelebekler ölüyordu 

Dereler akmam diyordu, ümitsiz 

Ve ben çiçeksiz kalıyordum çaresiz...', 'En nadir bulunan çiçekler gibiydin.  Beş bin fitinde bir dağ lalesiydin soğuk rüzgarlarda.  Ayazlarımda bir kar çiçeği oluveriyordun,  Ulaşı...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/ciceksiz-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Civ', 'civ-emre-valkan-balandi-bwa34', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Biliyorsun   Yoksun....

Anlıyorsun  Gelmiyorsun.....! 

İşte  Hepsi  Bu.....! 

                                           (hande''ye)', 'Biliyorsun   Yoksun.... Anlıyorsun  Gelmiyorsun.....!  İşte  Hepsi  Bu.....!                                             (hande''ye)...', ARRAY['Türk Edebiyatı','Şiir','Emre Valkan Balandi']::text[], 8.5, '{"poet":"Emre Valkan Balandi","poet_slug":"emre-valkan-balandi","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/civ-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görürse', 'gorurse-mehmet-sercan-tezcanoglu-y9ynj', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çingeneydi gece İstiklal''de. 

Pembeler içinde yaşlı bir fahişe; 

Tramvayla yarış edercesine, 

Kokusunu aldığı müşterinin peşinde. 

Müşterinin yüzünde bir endişe, 

Ya görürse şehir 

Söylerse birine! 

Kadın pembeler içinde, 

Yaşlı bir çingene. 

Yüzünde kulak arkası edilmiş bir gül.

Gül sahibinden güzel. 

Müşteri endişeli, 

Ya görürse gül 

Söylerse birine! 

Umurunda mı pembelinin 

Kolu müşterinin koluna girmiş bile. 

Çekiştiriyor evine... 

Kadın yaşlı bir fahişe. 

Adam endişeli, 

Ya ev görürde 

Söylerse birine! 

Kadının ağzından 5 papel dökülüyor, 

Çarpıyor müşterinin cüzdanına. 

Adam endişeli, 

Ya cüzdan görürde 

Söylerse birine! 

Anasını satayım! 

Görürlerse görsünler. 

Erkek adamım yaparım, diyor 

Müşteri düşünde. 

Adam endişeli, 

Ya düşü görürde 

Söylerse birine!', 'Çingeneydi gece İstiklal''de.  Pembeler içinde yaşlı bir fahişe;  Tramvayla yarış edercesine,  Kokusunu aldığı müşterinin peşinde.  Müşterini...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/gorurse-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat Devam Ediyor', 'hayat-devam-ediyor-mehmet-sercan-tezcanoglu-jouiz', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bugün sokaklardaydım. 

Benimdi sokaklar! 

Birkaç çocuk vardı 

Misket sallayan, 

Arada bir mızıkçılık yapan. 

Yaşlı bir adam; 

Burnuna düşmüş gözlüğünün ardından 

Benim göremediğim bir şeyleri görüyordu. 

Üstelemedim. 

Kedinin biri zamane damlarında 

Kuyruğunu sallıyordu. 

Yanında bir ağaç 

Ağaçta bir kumru 

Kediyi izliyordu. 

Yaprakları hışırdıyordu orta yaşta bir kavağın 

Altından bir genç kız geçiyordu. 

Sürmeliydi doğuştan gözleri, 

Utangaçtı da, 

Yeri süzüyordu. 

Balkonuna çamaşır asan taze gelin, 

Karnı burnunda, 

Gözlüyordu erkeğinin yolunu. 

Güneş pek bir nazlıydı bugün, 

Gösterip gösterip kaçıyordu yüzünü. 

Rüzgarsa haşindi! 

Bayrak gibi dalgalanıyordu ortalıkta, 

Elektrik telleri. 

İki otomobil geliyordu karşılıklı, 

Tek yön bir yoldan. 

Bağırışıyorlardı adamlar 

Aisopos''un keçileri misali. 

Bense izliyordum, 

Benim olan sokağı. 

Elimde bir kalem 

Çevirip duruyordum. 

Dünya dönüyordu bu sırada... 

Bir yerlerde gece olurken 

Horozlar uyanıyordu başka bir yerde. 

Ben görmüyordum. 

Ama biliyordum. 

Ne yapıyor ediyor, 

Bir şekilde 

Hayat devam ediyordu.', 'Bugün sokaklardaydım.  Benimdi sokaklar!  Birkaç çocuk vardı  Misket sallayan,  Arada bir mızıkçılık yapan.  Yaşlı bir adam;  Burnuna düşmüş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/hayat-devam-ediyor-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kılıçtan Geçirilen Susuzluğum', 'kilictan-gecirilen-susuzlugum-mehmet-sercan-tezcanoglu-y8w7v', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Toprak çatladı susuzluğunda. 

Ben nasıl dimdik ayakta durabilirdim ki? 

Tüm baykuşlar sessizliğe gömüldü. 

Yoktu kıyılarında martılar. 

Okyanuslar deniz oldu, 

Denizler göl, 

Göller yok oldu. 

Ki ben susuzdum! 

En kırmızı güller şimdi bir çöl çiçeği. 

Islak yosunlarım kayboldu çöplüklerinde, 

Güneşine ağlayan söğütler kurudu. 

Suydu hepsinin umudu, 

Buhar olup gitti 

Susuz yazlarında. 

Ki ben de uçtum bulutlarıma! 

Mavi gökyüzünü boyadık birlikte, 

Kül rengi umutlara. 

Batı döndü yüzünü 

Doğularıma, doğuşlarıma. 

Kayboldum cahilliğinde susuzluğumun. 

İnsanlarımla beraber, insanlarımla çaresiz 

Kılıçtan geçirildik. 

Kurudu dillerimiz. 

Ki ben de öldüm! 

Kurşun gibi ağır susuzluğunda, 

Gömüldüm çorak topraklarıma.', 'Toprak çatladı susuzluğunda.  Ben nasıl dimdik ayakta durabilirdim ki?  Tüm baykuşlar sessizliğe gömüldü.  Yoktu kıyılarında martılar.  Okya...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kilictan-gecirilen-susuzlugum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siz Yoktunuz!', 'siz-yoktunuz-mehmet-sercan-tezcanoglu-1l3ry', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Taşı aş ettiğim günler henüz çok taze 

Siz yoktunuz o zaman 

Bir tek ben vardım 

Nasıl yoğurmuştum, yalnızlığı ellerimle 

Mayası tutmuştu, ekmek ettim 

Yalnızlığımı 

Varlığımı koyup içine 

Aş ettim soframa 

Siz yoktunuz o zaman 

Duvarlar vardı dört yanımda 

Her birinde aynalar vardı 

Aynalar ki gerçeği göstermeye 

Cesaretleri yoktu hiçbirinin 

Umut ettim aynalarımı 

Koydum başucuma 

Siz yoktunuz o zaman 

Kitaplarım omuz verdi kollarıma 

Bir kolumda Kundera 

Bir kolumda Kafka 

Siz yoktunuz o zaman 

İyi bilirim 

Notalar vardı biz burdayız diyen 

Doldururlardı boşlarımı 

Çocuk sesleri gibi 

Hem neşeli hem ağlayan 

Kimi zaman Beatles kimi zaman Yorum.', 'Taşı aş ettiğim günler henüz çok taze  Siz yoktunuz o zaman  Bir tek ben vardım  Nasıl yoğurmuştum, yalnızlığı ellerimle  Mayası tutmuştu, e...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Sercan Tezcanoğlu']::text[], 8.5, '{"poet":"Mehmet Sercan Tezcanoğlu","poet_slug":"mehmet-sercan-tezcanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/siz-yoktunuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Al Beni Sevecenliğine', 'al-beni-sevecenligine-sukran-kurdakul-06k3k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben sevdayım, al beni sevecenliğine

Ben gülüm, dallarına aşıla beni

Çocuğum ben, göğsünde büyüt, 

Umudum ben, düşüncende geliştir.

Acıyım, gerçeği ararsan bende, 

İnancım, çoşkuyu yaşarsan bende..', 'Ben sevdayım, al beni sevecenliğine Ben gülüm, dallarına aşıla beni Çocuğum ben, göğsünde büyüt,  Umudum ben, düşüncende geliştir. Acıyım, g...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran-kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/al-beni-sevecenligine-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Burda Kalan', 'burda-kalan-sukran-kurdakul-qvfuo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Anımsama yeter mi

Bilirsin sen..

Kalan kaldı arkamızda

Bir defa geçilen yollar gibi

Unuttuğumuz günler

Nerde şimdi, 

Nerdesin sen.

Beklemekse bekledindi

Eksile azala...

Yürümekse yürüdün, 

İyi kötü zamanlar gördün

Saatler durmadı, 

Trenler bastı gitti

Burdasın sen.', 'Anımsama yeter mi Bilirsin sen.. Kalan kaldı arkamızda Bir defa geçilen yollar gibi Unuttuğumuz günler Nerde şimdi,  Nerdesin sen. Beklemeks...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran-kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/burda-kalan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendim', 'bendim-sukran-kurdakul-uoagg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Dalgalanmış deniz bendim kendi içimde

Sonra yorgun düşmüş denizlere dönüşen

Ormandım, 

Ağaçlarım düş ağaçlarından sıktı.

Tan yeriydim

Göğsüm bağrım payını aldı güneşten

Yanım yörem aydınlığa çıktı.

Gece de bendim

Uzak uzak yıldızları getiren

Su da bendim tarlanızda

Elinizin altında kitaptım

Penceredeydim odanızda

Kurşun geçmez dizeler çiçeği

Özgürlüğüm benim

Canımın saksılarında büyüdü

Ayıplara gömülen çağınızda', 'Dalgalanmış deniz bendim kendi içimde Sonra yorgun düşmüş denizlere dönüşen Ormandım,  Ağaçlarım düş ağaçlarından sıktı. Tan yeriydim Göğsüm...', ARRAY['Türk Edebiyatı','Şiir','Şükran Kurdakul']::text[], 8.5, '{"poet":"Şükran Kurdakul","poet_slug":"sukran-kurdakul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bendim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Artık Ağlamam Lazım', 'artik-aglamam-lazim-mehmet-solmaz-lpzb1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yıl 2001

Yanlız günlerimden biri

Hani herşeyi hisseden 

Hani benim yarımdın sen

Yalan söyleyende sen

Kızıyorsam sevgimdendir

Hep sevgimden

Şimdi artık git istersen

Sigaram, içkim

Bitkinim bitkin.

Kaç gündür oruçtayım

Artık Ağlamam Lazım

Kaç gündür habersizim, 

Adaletin bumu senin

Çok önemliydi sanki

Yanlızca Bir öfkeydi öfke

Şimdi sensiz gecelerde 

Bir gece daha teslim oldu sabahlara

Ne kadar sessiz 

Şimdi buralarda yapa yanlız

Beni kimlere teslim ettin

İstesem Hemen bulurdum seni

İlk sekiz günü anlatamam 

Seviyorum seni

Bu kadar konuştuğuma göre

İstanbul''u bulutlar sarıyor

Beni sardığı gibi 

İstanbul Kararyor

Gönlüm gibi 

Keşke burada olsaydın

Yani şımarsaydın

Hatta 11 gündür Atarga''da ve

11 gündür hiç olta admadım tek bir balığa

Oysa çok severim tutmayı

Tuta tuta tutmayı öğrendim galiba

Hani herşeyi hisseden 

Hani benim yarımdın sen

Yalan söyleyende sen

Kızıyorsam sevgimdendir

Hep sevgimden

Şimdi artık git istersen

Sigaram, içkim

Bitkinim bitkin.

Kaç gündür oruçsuzum

Artık Ağlamam Lazım...', 'Yıl 2001 Yanlız günlerimden biri Hani herşeyi hisseden  Hani benim yarımdın sen Yalan söyleyende sen Kızıyorsam sevgimdendir Hep sevgimden Ş...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Solmaz']::text[], 8.5, '{"poet":"Mehmet Solmaz","poet_slug":"mehmet-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/artik-aglamam-lazim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimden Geldiği Gibi Sansürsüz', 'i-cimden-geldigi-gibi-sansursuz-rifat-bayindir-j20kx', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'İkilem; içimi kavurur bitirir

Gönlüm başka, 

Dilim başka, 

Elim başka söyler.

Değerlerim ve nefsim çatışır durur.

Ne ele yar, 

Ne dile yar, 

Ne kendime yar olurum.

Bekleşirim umutsuz ve mutsuz.

Kızarım gönlüme ve kendime.

Ne hayatta umut, 

Ne ölümde umut....

(Şubat 2000 İstanbul)', 'İkilem; içimi kavurur bitirir Gönlüm başka,  Dilim başka,  Elim başka söyler. Değerlerim ve nefsim çatışır durur. Ne ele yar,  Ne dile yar, ...', ARRAY['Türk Edebiyatı','Şiir','Rıfat Bayındır']::text[], 8.5, '{"poet":"Rıfat Bayındır","poet_slug":"rifat-bayindir","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/icimden-geldigi-gibi-sansursuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yırtık Resim', 'yirtik-resim-bunyamin-nesimoglu-hklz6', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gülüm

köyde yine akşam oldu

ve sen yoksun yanımda.

sigaramdan yükselen duman

yüreğimin paradoksunun resmini çizerken

elimde yırtık bir resmin bile yok.

Biliyormusun Gülüm! 

köyde yine akşam oldu 

ve sen yoksun yanımda...', 'Gülüm köyde yine akşam oldu ve sen yoksun yanımda. sigaramdan yükselen duman yüreğimin paradoksunun resmini çizerken elimde yırtık bir resmi...', ARRAY['Türk Edebiyatı','Şiir','Bünyamin Nesimoğlu']::text[], 8.5, '{"poet":"Bünyamin Nesimoğlu","poet_slug":"bunyamin-nesimoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yirtik-resim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sebebim', 'sebebim-mustafa-yildiz-demirci-9cbxk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Neden geldim buralara, 

gurbete, yalnızlığa.yokluğa...

Sebebi herhalde sen olmalısın.

Al yazmalı, ince belli Meliha! 

Artık seninle duramadım, 

sürsün diye bir sefa, 

ayrılığı yakama bantladım, 

fakat sen hala beni anlayamadın.

Herşeyi sana bıraktım, 

evimi, günahını, sevabımı...

Mutlu günlerin resmini, umutlarımı.

Sözlerini unuttum, yalanmış yeminlerin.

Tertemiz duygularımla, baharımla, düştüm yola, 

izimi arama, beni sorma, duyma! 

Sesini duysamda, düşlerine varsamda, 

Vallahi bitti, billahi bitirdin.!', 'Neden geldim buralara,  gurbete, yalnızlığa.yokluğa... Sebebi herhalde sen olmalısın. Al yazmalı, ince belli Meliha!  Artık seninle duramadı...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız Demirci']::text[], 8.5, '{"poet":"Mustafa Yıldız Demirci","poet_slug":"mustafa-yildiz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/sebebim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Hâle Geldik', 'bu-h-le-geldik-ozan-arif-7uvpp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Çok zevk aldık komşumuzun derdinden, 

Haz yapa haz yapa bu hale geldik. 

İkimiz bir üçüncünün ardından, 

Söz yapa söz yapa bu hale geldik. 

Hep gözümüz elin ekmek aşında, 

Böylelikle kaldık safın dışında, 

Kadın işte, erkek kumar başında, 

İz yapa iz yapa bu hale geldik.

Ne kanundan korktuk ne de fermandan, 

Kestik, yaktık, tarla yaptık ormandan, 

çok savurduk den çıkmadı harmandan, 

Toz yapa toz yapa bu hale  geldik.

Adaletin ışığını söndürdük, 

Vurguncuyu avantaya  kondurkuk, 

Uyuşturduk beyinleri dondurduk, 

Buz yapa buz yapa bu hale geldik. 

Gurbetçinin feryadını duymadık, 

Ürüşvetsiz vatanına  koymadık, 

Gümrüklerde nesi kaldı soymadık, 

Kaz yapa kaz yapa bu hale  geldik.

Kaş yaparken hep çıkardık gözleri, 

Heder oldu aşıkların  sözleri, 

En basiti öz malımız sazları, 

Caz yapa caz yapa bu hale geldik. 

Seçim vakti çok sıvadık kolları, 

Boş geçirdik  aradaki yılları, 

Kürsülerde eşşek gitmez yolları, 

Düz yapa  düz yapa bu hale geldik.

Parçaladık yüce Türkün ırkını, 

Ayrı dedik garbı ile şarkını, 

Üç rey için mezheplerin  farkını, 

Koz yapa koz yapa bu hale geldik.

ç; ıkar için  girdik binbir kılığa, 

Kaypaklıkta pes dedirtdik balığa, 

Kaplumbağa ile soluk soluğa, 

Hız yapa hız yapa bu hale geldik.

İnatlıkta yarış yaptık keçiyle, 

Namussuzu kabul ettik  suçuyla, 

Kel kız gibi ablamızın saçıyla, 

Poz yapa poz  yapa bu hale geldik.

Ozan Arif ne söylesin şu anda, 

Siz söyleyin şevk  kalır mı insanda? 

Vatanını sevenleri zindanda, 

Köz yapa köz yapa  bu hale geldik.', 'Çok zevk aldık komşumuzun derdinden,  Haz yapa haz yapa bu hale geldik.  İkimiz bir üçüncünün ardından,  Söz yapa söz yapa bu hale geldik.  ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":44,"source_url":"https://www.antoloji.com/bu-hale-geldik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üzgünüm', 'uzgunum-baris-erzincanli-ec3l0', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yine bir yalnızlık hüznü var gönlümde 

nedense içimden atamıyorum 

her seferinde dahada yanıyor içim 

senin yokluğun yıkıyor beni 

nerdesin diye bağırmak istiyorum 

ama yapamıyorum nasılsa duymuyorsun 

ağlamak istiyorum ağlayamıyorum 

gülmek istiyorum gülemiyorum 

üzülüyorum seni bensiz oralarda bir başına bıraktığım için 

bağrım yanıyor ağladığında sarılamadığım için 

içim titriyor gözlerinin yaşını silemediğim için 

hasta oluşun beni daha da bir kötü yapıyor ölüm bile daha kolay geliyor 

üzülüyorum seni saramadığım için 

üzülüyorum yanında olamadığım için 

ağlıyorum sana yardım edemediğim için 

üzülüyorum seni üzdüğüm ve seni bir başına bıraktığım için', 'yine bir yalnızlık hüznü var gönlümde  nedense içimden atamıyorum  her seferinde dahada yanıyor içim  senin yokluğun yıkıyor beni  nerdesin ...', ARRAY['Türk Edebiyatı','Şiir','Barış Erzincanlı']::text[], 8.5, '{"poet":"Barış Erzincanlı","poet_slug":"baris-erzincanli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/uzgunum-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neruda''ya', 'neruda-ya-bulent-ozcan-44prf', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', '''Kimbilir nasıl acı çektin alışayım derken 

benim o yabanıl, yalnız ruhuma, herkesi ürküten adıma''

PABLO NERUDA  (Çev: Kemal Özer, S. Özbudun) 

Çok kimseyi ürküten bir adım var benim de, 

Görsünler adımızı yan yana bu şiirde...', '''Kimbilir nasıl acı çektin alışayım derken  benim o yabanıl, yalnız ruhuma, herkesi ürküten adıma'' PABLO NERUDA  (Çev: Kemal Özer, S. Özbudu...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/neruda-ya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karlarda Hüzün', 'karlarda-huzun-mustafa-yildiz-demirci-uwxij', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu sabah bembeyaz karlarda, 

önüme çıktı bir kadın, upuzun saçlarıyla...

Gözünde yaşlar vardı, belli ki gönlündede yas! 

Anlamadım halini, bu kadında bir tuhaflık vardı.

Ayağı kaydı birden, kapandı beyazlara, 

yardım edip kaldırdım, tuttum ellerinden, 

Bakamadım gözlerine kaçırdı gözlerimden! 

Paltosunu temizleyip, bir teşekkür etti derinden...

Baktım ki, bu da yaralı

Kimbilir kime aşıktı, 

kimbilir kimden ayrıldı.

Bu bembeyaz karlarda, 

Onu ağlatacak bir yar mıydı? 

Bir ocağa girdik, 

demli birer çay içtik.

Bir sigara yaktı, bir de dumanına baktı.

Bir ''ah''çekip ta yüreğinden, 

kapattı gözlerini, hayallerini, avuçlarında 

sıktı...

Anladım ki, bu da sevdalı

sevdiğine O, sadece ayak bağı.

Anımsadım kendimi, 

bu kadın bendende kahırlı.

Sordum ismin nedir; 

söylemek istemedi, hıçkırdı yeniden, 

kapandı dizlerime; Kader dedi, KADER! 

Dedim Kader, ama! ama ağlama yeter...

Daldı tekrar düşüncelerine, mazisine

ve hiç bilmediğim sevgilisine! 

Ben boynumu bükebildim, 

onun bu haline...

Anlatmaya başladı; 

sevdiği uzunca boyluymuş, mavi gözlü...

Baharımın papatyası deyip, gönlünü edivermiş.

Bir sarışının soğuk kollarında, 

onu bir anda unutuvermiş.

Aldanmış, seviyor sanmış, 

Nağmeli sözlerine bir anda kanmış.

Bu bembeyaz karlarda, 

Hep o mavi gözleri aramış...!', 'Bu sabah bembeyaz karlarda,  önüme çıktı bir kadın, upuzun saçlarıyla... Gözünde yaşlar vardı, belli ki gönlündede yas!  Anlamadım halini, b...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Yıldız Demirci']::text[], 8.5, '{"poet":"Mustafa Yıldız Demirci","poet_slug":"mustafa-yildiz-demirci","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/karlarda-huzun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demir Kapılar', 'demir-kapilar-ozan-arif-g4skw', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ülkücüyüz dedik zindana dolduk, 

Açıl artık açıl demir kapılar.

Allah`sız kanunun esiri olduk, 

Açıl artık açıl demir kapılar.

Paslanmış zincirler salmaz kolumu, 

Babam ölmüş, anam bekler yolumu, 

Ülkücü şehitler büktü belimi, 

Açıl artık açıl demir kapılar.

Arif`im yatmanın sırası değil, 

Sebebim yüzümün karası değil, 

Bozkurt`un mekânı burası değil, 

Açıl artık açıl demir kapılar.', 'Ülkücüyüz dedik zindana dolduk,  Açıl artık açıl demir kapılar. Allah`sız kanunun esiri olduk,  Açıl artık açıl demir kapılar. Paslanmış zin...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/demir-kapilar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Da Geçer', 'bu-da-gecer-ozan-arif-3x9n1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok kuraklar gördük biz. Bu da geçer evladım, 

Dostumuz Allah bizim, unutma bu gerçeği.

Etim ile besleyip, kanım ile suladım, 

Bu kurak kurutamaz ''Ülkü'' adlı çiçeği', 'Çok kuraklar gördük biz. Bu da geçer evladım,  Dostumuz Allah bizim, unutma bu gerçeği. Etim ile besleyip, kanım ile suladım,  Bu kurak kuru...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/bu-da-gecer-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Birgün', 'birgun-ozan-arif-fquks', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Maalesef adalet kana boyandı, 

Tarih yakanızdan sarılır bir gün.

Haksız kalem kıran o kanlı eller, 

Mutlaka kökünden kırılır bir gün

Not: Mustafa Pehlivanoğlu''nun infaz sabahı yazılmıştır.', 'Maalesef adalet kana boyandı,  Tarih yakanızdan sarılır bir gün. Haksız kalem kıran o kanlı eller,  Mutlaka kökünden kırılır bir gün Not: Mu...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/birgun-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yuh!', 'yuh-ozan-arif-rvu09', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Haydin hep bir ağızdan, 

Yılana yuh çekelim.

Sağ görünüp sol sazdan, 

çalana yuh çekelim.

Bizdik dün vururlan, 

Al bayrağa sarılan, 

Bize karşı kurulan, 

Pilana yuh çekelim.

Haykır sorgu olsada, 

Sonu yargı olsada, 

Adı vergi olsada, 

Talana yuh çekelim.

Görmez kendi pisini

Kaltağının süsünü, 

Bacımın örtüsünü, 

Alana yuh çekelim.

Meshep yok diyen fişman, 

Kur`an`a basar şaşman, 

İslam`a sinsi düşman, 

Olana yuh çekelim.

Tek Türkeş tutuk olan, 

Tam kahpece bir pilan.

Ecevit suçsuz mu lan? 

Salana yuh çekelim.

Adalet mağlup hayfa.

Yazanlar kızıl tayfa.

Dokuzyüz küsür sayfa, 

Yalana yuh çekelim.

Ramazan oruç demez, 

şarapsız yemek yemez, 

Bunlar geberse namaz

Kılana yuh çekelim.

Arif der ki; baş sakat, 

Sivas, Amasya, Tokat! 

Ordu yaşasın fakat

Falana yuh çekelim.', 'Haydin hep bir ağızdan,  Yılana yuh çekelim. Sağ görünüp sol sazdan,  çalana yuh çekelim. Bizdik dün vururlan,  Al bayrağa sarılan,  Bize ka...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/yuh-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıladan Gelen Mektup', 'siladan-gelen-mektup-ozan-arif-7mk59', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Her mektupta haber soruyon bizden, 

Soruyon ya fakat neyi gardaşım? 

Mektupları okuyorlar o yüzden, 

Eh işte, durumlar eyi gardaşım! 

Zannederken anarşiyi attık biz, 

Bir başka şeklinegedip çattık biz.

Yat dediler, emir ile yattık biz, 

Şimdi de diyorlar uyu gardaşım.

Milletçe güvendik ''Eylül'' ayına.

Güvendik ya, lâkin geldik oyuna.

Acaip vergi var üç baş koyuna, 

Hep sattık beygiri, tayı gardaşım.

Fiyatlar artıyor her seferinde, 

İşçinin ücreti dondu yerinde, 

Korkudan susuyom, yara derinde, 

Aç iken oynar mı ayı gardaşım? 

Bir köşe yapıyor tezgâhtan geçen, 

Ne bize soran var, ne mevzu açan, 

Yüzaltmış vekili meclise seçen

Beş tane adamın oyu gardaşım.

Bindörtyüz yıl öncesini gevenin, 

Açıkça ilâhi hükme sövenin, 

Eflâtun`un ''Devlet''`ini övenin

Kültüründen (!)   aldık payı gardaşım? 

Kadınlar başını yemeğ; e sokmuş, 

Bu yüzden birara başörtü çıkmış (!)

Meğ; erse İslâm`da örtünmek yokmuş

Duydunuz mu Paşa beyi gardaşım? 

İzi aynı eski pirinin izi, 

Meselâ gezerken Karadeniz`i, 

Anasonla karıştırdı filizi, 

Irakı zannetti çayı gardaşım.

Suçlular suçunu düşünsün kendi.

Bu belâ bizlere haktır efendi.

Sivas`ta Kur`an`a basılır dendi, 

Irganmadı halkın tüyü gardaşım.

Gözünün üstünde kaş var diyeni, 

Sokağ; a koymazdı kısa giyeni, 

Amma alkışladı oruç yiyeni, 

Değ; işti dadaşın huyu gardaşım.

Korkudan imanı rafa kaldırdık, 

Kendimizi yaşar iken öldürdük.

Kızımızın örtüsünü aldırdık, 

Namusa kazdırdık kuyu gardaşım.

Evde bile artık susmak iyisi, 

Horozu bastırdı tavuğ; un sesi, 

Garı da, erkek de evin reisi, 

Artık evde herkes dayı gardaşım.

Vallâhi hep bizde büyüğ; ü suçun, 

Ahâli taş ile siliyor gıçın.

Yüzbin gayme verdik syrf heykel için, 

Yoğ; uken köyümün suyu gardaşım.

Dinimize göre kürtaj cinayet, 

Bunu şimdi resmen yapacak devlet.

Gene ağ; zını açmıyor millet, 

Rezalet çizmenin boyu gardaşım.

Herneyse sen fazla canını sıkma, 

çok değ; il az kaldı kafanı takma, 

Patlamak üzere bu millet bakma, 

Gerildi sabırın yayı ghardaşım.

Ozan Arif ayrı, saz ayrı inler, 

Süt tozundan gıda almış beyinler, 

Değ; neksiz geziyor hinoğ; lu hinler, 

Köpeksiz buldular köyü gardaşım.', 'Her mektupta haber soruyon bizden,  Soruyon ya fakat neyi gardaşım?  Mektupları okuyorlar o yüzden,  Eh işte, durumlar eyi gardaşım!  Zanned...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":64,"source_url":"https://www.antoloji.com/siladan-gelen-mektup-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakarya', 'sakarya-kadir-eryildirim-0n09f', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gün kızıla kesmek üzre

Sakarya kana doymak üzre

Ve birinci perde: 

Dehalardan kahraman çıktı mı hiç tarihte? 

O sakarya ki bir milletin 

Ölümle kalım arasında 

Gidip geldiği...

O kahraman deha ki 

Kaderi bir milletin kaderi ile çakışan

Ölüme bir santimden fazla yaklaşan

O Sakarya ki kahramanı

Cesaretin en büyüğü ile sınayan

O kahraman deha ki ölüme rağmen

Bana rağmen sana rağmen

Ve de Sakarya’ya rağmen 

Durmaksızın ilerleyen

O Sakarya ki koca bir milletin

Umudunu ve varoluşunu taşıyan

O deha ki Sakarya’ya

Meydan okuyan

İkinci perde: 

Düşmanla boğuşulduğu yerde

Alacakaranlıkta ışılayan bir sarışın kurt gibi

O şimdi her yerde

O şimdi belleklerde



O Sakarya ki bütün umutları

Denize döken

O deha ki o umutları

Devindiren

O deha bir kudret ki

Koca bir milleti birleyen

O Sakarya ki dehanın ve  milletin

Kudretine tanık olan

O kahraman deha bir millet ki

Ki’lerle anlatılacak gibi değil

                                                 K.E', 'Gün kızıla kesmek üzre Sakarya kana doymak üzre Ve birinci perde:  Dehalardan kahraman çıktı mı hiç tarihte?  O sakarya ki bir milletin  Ölü...', ARRAY['Türk Edebiyatı','Şiir','Kadir Eryıldırım']::text[], 8.5, '{"poet":"Kadir Eryıldırım","poet_slug":"kadir-eryildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/sakarya-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlığın Yelkeni', 'yalnizligin-yelkeni-bulent-ozcan-9zaxw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Konacak bir yeri olmayan martıların hüznü

Hüznüme benzer biraz da

Yoksul ve kederli...

Martılar dedim de aklıma geldi

Bugünlerde deniz çağırıyor beni

Gel diyor, açıl bana

Yalnızlığımın yelkeni...

15 Aralık 2000, 

Enfield Island Village, Londra', 'Konacak bir yeri olmayan martıların hüznü Hüznüme benzer biraz da Yoksul ve kederli... Martılar dedim de aklıma geldi Bugünlerde deniz çağır...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/yalnizligin-yelkeni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ölüm Uykusu', 'olum-uykusu-i-lhan-yuksel-ychbj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Beş asır uyanmaz ölüm uykusundayız

Düşürdün bizans kahbe pusundayız

Üstümüze saçılmış ölü toprağısın

Yarışa ne gün uyansak ayak bağısın

Bu milleti olmadık şeyle oyaladın

Dünya asra koşar gözümüzü boyadın

Hayber olaydın da merd düşmanım nolaydı

Bizden üstün ya bir meziyyetin olaydı

İleriydik dünyada geriyiz yarışta

Bozuldu düzen iktisadımız barışta

Geçirdik zamanı yalanın laklakınla

Yücelerden leş kargası vakvakınla

Gökte kartalı alıp ayağa düşürdün

Kahbece bu milleti tuzağa düşürdün

Sığındın tahammül boş verip geçimize

Ta uzaktan gelip yamandın içimize

Yerli oldun milletimi dağa düşürdün

İninde yılan aslanı ağa düşürdün', 'Beş asır uyanmaz ölüm uykusundayız Düşürdün bizans kahbe pusundayız Üstümüze saçılmış ölü toprağısın Yarışa ne gün uyansak ayak bağısın Bu m...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/olum-uykusu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Galatanın Bizans Hayali', 'galatanin-bizans-hayali-i-lhan-yuksel-jhf2q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Şu galatanın gizli hayali

Sanma şamdanı haçı bulunmaz

Suçlu aranır yağma vatana

Sorun sırrını açı bulunmaz

Dönmeye olunca p... demek suç

Anlamak zor olur söylemek güç

İnzibatı e... savcısı p...

Bize bizden sorgucu bulunmaz

Anadolumu baştan aşağa

Soyup milleti yalın ayağa

Mahkum eden sanki bayağa

Şu galatanın suçu bulunmaz', 'Şu galatanın gizli hayali Sanma şamdanı haçı bulunmaz Suçlu aranır yağma vatana Sorun sırrını açı bulunmaz Dönmeye olunca p... demek suç Anl...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/galatanin-bizans-hayali-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyaz Bir Gemidir Ölüm', 'beyaz-bir-gemidir-olum-behcet-aysan-8f87h', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'sen bu şiiri okurken 

ben belki başka bir şehirde

olurum

kötü geçen bir güzü

ve umutsuz bir aşkı anlatan

rüzgarla savrulan

kağıt parçalarına

yazılmış

dağıtılmamış

bildiriler gibi

uzun bir yolculuğa hazırlanan

yalnız bir yolculuğa.

çünkü beyaz bir gemidir ölüm

siyah denizlerin hep

çağırdığı

batık bir gemi

sönmüş yıldızlar gibidir

yitik adreslere benzer

ölüm

yanık otlar gibi

sen bu şiiri okurken

ben belki başka bir şehirde

ölürüm..', 'sen bu şiiri okurken  ben belki başka bir şehirde olurum kötü geçen bir güzü ve umutsuz bir aşkı anlatan rüzgarla savrulan kağıt parçalarına...', ARRAY['Türk Edebiyatı','Şiir','Behçet Aysan']::text[], 8.5, '{"poet":"Behçet Aysan","poet_slug":"behcet-aysan","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/beyaz-bir-gemidir-olum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Attım Okumu Varsın Hedefe', 'attim-okumu-varsin-hedefe-i-lhan-yuksel-1f1wr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Attım okumu varsın hedefe 

Varmadı gitti uzağa düştü 

Çıkmaz sokaktan kurtulmak için 

Sürdüm atımı tuzağa düştü 

Vatan tutayım derken yurdumda 

Vardı yolum ta ırağa düştü 

Nevbahar idi çıktım yoluma 

Kara bahtıma kırağa düştü 

Düştüm yüzüstü çaresiz kalıp 

Yolum çıkılmaz sokağa düştü 

Dönmeye mutlu türküm zamanı 

Bize vatan dan firağa düştü 

Yaşa çağdaşlık ona bin öküz 

Çağdaş Türk’e bir buzağı düştü 

Elde Muharref çağdaş geçinip 

Bizim değişmez bayağa düştü 

Liman boyunca saçtılar tohum 

Soysuz bir nesil sokağa düştü 

Masum ananın yaslı günüdür 

Nesep sormayan bir cağa düştü 

Eski şeriat isterukçüler 

Devran dönünce ne yağa düştü 

Birdi yolumuz bine bölündük 

Kahin bir sola bir sağa düştü 

Üçlü piramit kıble olunca 

Benim dörtgenim ferağa düştü 

Akrepten zehir yutunca usta 

Vardı işi bir çırağa düştü', 'Attım okumu varsın hedefe  Varmadı gitti uzağa düştü  Çıkmaz sokaktan kurtulmak için  Sürdüm atımı tuzağa düştü  Vatan tutayım derken yurdum...', ARRAY['Türk Edebiyatı','Şiir','İlhan Yüksel']::text[], 8.5, '{"poet":"İlhan Yüksel","poet_slug":"i-lhan-yuksel","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/attim-okumu-varsin-hedefe-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-bora-zihni-t9zgt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Hatırlar mısın? 

Bütün gözlerden ırak olmak için çabalar, 

Kuytularda dolaşıp, 

Issızlığı arardık.

Gizliliğin telaşı, o sevimliliği içerisinde

Kısa zamanı  nasıl da doyumsuzca  yaşardık.

Hatırlar mısın? 

Küçük bir limana gider, 

Kayalara yaslanır kaçamak öpüşürdük.

İşte ordayım bir tanem.

Sensiz, yüreksiz.

Seni sordular bana aşkımıza tanık martılar, deniz ve poyraz. 

Ayrıldık dedim.

İnanmadılar.

Yemin ettim.

Güldüler.

Gizledim ıslak gözlerimi.

Esti deli poyraz, 

Kabardı deniz.

Çığlığa boğuldu martılar.

Sensizliğin suçunu bana vurdular.', 'Hatırlar mısın?  Bütün gözlerden ırak olmak için çabalar,  Kuytularda dolaşıp,  Issızlığı arardık. Gizliliğin telaşı, o sevimliliği içerisin...', ARRAY['Türk Edebiyatı','Şiir','Bora Zihni']::text[], 8.5, '{"poet":"Bora Zihni","poet_slug":"bora-zihni","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/sensiz-24-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aykırı', 'aykiri-serhat-topcu-lj6py', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Susuyorum

Bütün maskelerin

Umarsız edasına binaen

Sahtelerin arasında kalmışım

Orjinali arıyorum

Usanmadan, tükenmeden...', 'Susuyorum Bütün maskelerin Umarsız edasına binaen Sahtelerin arasında kalmışım Orjinali arıyorum Usanmadan, tükenmeden......', ARRAY['Türk Edebiyatı','Şiir','Serhat Topçu']::text[], 8.5, '{"poet":"Serhat Topçu","poet_slug":"serhat-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/aykiri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Pıhtı', 'pihti-yasemin-yarar-rfkva', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Akım yok

elektrik yok

pıhtı tıkayacak damarlarımı

tık yok..', 'Akım yok elektrik yok pıhtı tıkayacak damarlarımı tık yok.....', ARRAY['Türk Edebiyatı','Şiir','Yasemin Yarar']::text[], 8.5, '{"poet":"Yasemin Yarar","poet_slug":"yasemin-yarar","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/pihti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocuklar', 'cocuklar-serhat-topcu-8hfp5', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Issız sokaklar ardında

Nice düşlerim vardır

Gözlerinin içi gülen çocuklar gibi

İsyan kokan çığlıklarım

Lanet dolu haykırışlarım vardır

Aynı çocukların saf sözleri 

Ve zamanı çeviren topaçları

Kısa kalmış saçları

Mini mini dudaklarıyla öpüşleri gibi

Heyecanımı yitirişim

Bir sevdadan geçişim

Gün be gün eriyişim

O çocuklara benzeyişim vardır', 'Issız sokaklar ardında Nice düşlerim vardır Gözlerinin içi gülen çocuklar gibi İsyan kokan çığlıklarım Lanet dolu haykırışlarım vardır Aynı ...', ARRAY['Türk Edebiyatı','Şiir','Serhat Topçu']::text[], 8.5, '{"poet":"Serhat Topçu","poet_slug":"serhat-topcu","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/cocuklar-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma', 'ogluma-edip-cangonul-7y6ua', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Korkmayasın kurban olduğum 

Ne bu gece ne de dün

Utanmadım yaptığım bir şeyden

Keşke sen de bir yiğit olsan 

Korkmasan hatta

Ben sarhoş olsam sen savunsan

Güya bir gece vakti dışarı çıkmışlıklarımı 

benim

ve geri dönmüşlüklerimi

bir gece vakti senden habersiz

sonra ben savunsam 

ele güne karşı bu bok yemişliklerimizi

hah

yani el

yani yaban bu gurban  

kime ne diyesin', 'Korkmayasın kurban olduğum  Ne bu gece ne de dün Utanmadım yaptığım bir şeyden Keşke sen de bir yiğit olsan  Korkmasan hatta Ben sarhoş olsa...', ARRAY['Türk Edebiyatı','Şiir','Edip Cangönül']::text[], 8.5, '{"poet":"Edip Cangönül","poet_slug":"edip-cangonul","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ogluma-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nasıl Yazsam Şiirini Senin Kardeşim', 'nasil-yazsam-siirini-senin-kardesim-bulent-ozcan-bguu5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', '-Kardeşim Haydar''a.

Nasıl yazsam şiirini senin kardeşim

Yüreğimi onulmazca inciten

Ne çok şeyimdin sen benim

Eski bir fotoğrafta yoksul gülerken

Yazılmamış bir şiir gibi güzeldin

Saf, iyi yürekli, mert bir çocukken

Hapsetseydim ah kalbime seni

Büyümeden henüz küçük bir çiçekken

Kardeşim kanayan yüreğim benim

Bilincim, ışıldayan şiirim, ereğim

Keşke sana engel olabilseydim

''Hırs'' dediğin düşmana yenilmeden

Nasıl yazsam senin şiirini kardeşim

Yüreğimi onulmazca inciten

Ne çok şeyimdin sen benim

Eski bir fotoğrafta yoksul gülerken...

18 Mayıs 2000, 

Hucknall-Nottinghamshire/İngiltere

www.bulentozcan.com', '-Kardeşim Haydar''a. Nasıl yazsam şiirini senin kardeşim Yüreğimi onulmazca inciten Ne çok şeyimdin sen benim Eski bir fotoğrafta yoksul güle...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/nasil-yazsam-siirini-senin-kardesim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevinin Ustası Hüzünün Bilgesi', 'sevinin-ustasi-huzunun-bilgesi-bulent-ozcan-dd54q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Dedem Kuşo''ya.

Dedem suya dokunsa, su olurdu

Işığa dokunsa, ışık

Rüzgâra dokunsa, rüzgâr...

Dedem, bir eski zaman dervişi

Yitik an''ların kanayan şiiri

Sevinin ustası, hüzünün bilgesi

Gönül sarayının mimarı

Sevgi pazarının hünerli terzisi...

Terazilere ayardı terazisi...

Gönül tezgâhında sevgi dokurdu

Yunus''tan, Emrah''tan şiir okurdu

Dostla muhabbette şevkle şakırdı

Dedem bütün zamanların kendisi...

Dedemi gördüm düşümde

Kendi toprağının döşünde

Yunusleyin gülüyordu

Hakk''la gönül işinde...

14 Haziran 2000, 

Hucknall-Notts./İngiltere', 'Dedem Kuşo''ya. Dedem suya dokunsa, su olurdu Işığa dokunsa, ışık Rüzgâra dokunsa, rüzgâr... Dedem, bir eski zaman dervişi Yitik an''ların kan...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/sevinin-ustasi-huzunun-bilgesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Yerde Sen', 'her-yerde-sen-adil-koruyan-bxrdn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Dün kumsalda seni düşündüm.

Ayaklarımın dibinde deniz, 

Ufukta batmakta olan güneş.

Farklı olan  tek bir şey 

Kumsala vuran dalgalar.

Dur durak bilmeden, 

Ümidini yitirmeden, 

Sevgiliye koşar gibi

Kumsalda çoşan dalgalar.

Bana seni getirdi.

Kızıla çalan göğün altında, 

Pembeleşen bulutların, 

Güneşin son ışıklarında

Veda dansını izledim.

İlahi bir müzik eşliğinde

Yüzüme vuran akşam rüzgarında, 

Saçlarının savruluşunu, 

Sevgi dolu yüzünü gördüm. 

Sahile vuran  dalgaların

Beyaz köpükleriyle taçlandırdığı

Kumsaldaki kum taneciklerinde, 

Gözlerindeki ışıltıları gördüm.

Bir kez daha seni yaşadım, 

Yokluğunda varlığını.

17.08.2001', 'Dün kumsalda seni düşündüm. Ayaklarımın dibinde deniz,  Ufukta batmakta olan güneş. Farklı olan  tek bir şey  Kumsala vuran dalgalar. Dur du...', ARRAY['Türk Edebiyatı','Şiir','Adil Koruyan']::text[], 8.5, '{"poet":"Adil Koruyan","poet_slug":"adil-koruyan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/her-yerde-sen-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk''a Sen''le Düşer Yürek', 'ask-a-sen-le-duser-yurek-ahmet-sahin-soner-umy7s', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yüreğimdeki Dosta, Çiçeğime

Gün geceye karışmasın bugün, 

Günün kızıla çaldığı saatlerde

Yağmurun yağması arifesinde

Sen''le düşüyordu aşk''a yüreğim...

Ben seni bekliyordum, 

Sen yağmura karışmış beni

Kısık sesle dinliyorum şarkıları

Ve şarkılara mısra olmuş duyguları

Bir koşmak geliyor içimden

Bir daha gitmiyordu, 

Koşacağım istikamette sen oluyordun hep

Nereye dönsem, sen...

Suskundum, başım önüme eğik

Gün bize suskundu belki, gece bize küskün, 

Nedir bu yüzümüze düşmeyişi yağmurun

Yeşilin ağaçtaki matlığı, 

Renklerin tual''e bulaşmayışı...

Güneşe dönük pencereye akseden buğu, 

Odamın boğuk kokusu, 

Ve korkular arasında seni solumak

Batan güneşe dalıyorum uzun, uzun

Bulutlar arasında isli puslu ışıyan, 

Sen bir mine çiçeği, 

Bense yağmur busesi...

Üzerine damlıyorum, 

Siyah camdan masamda, 

Damla, damla eriyen mumun

Beyaz dantel örtüye, 

Desenler verdiği gibi...

Merdivenler boş ve karanlık, 

Aydınlığa açılıyor üstü cam, altı tokmaklı bir kapı...

Parke taşlı çocukluğum dolu sokaklara düşüyorum yalınayak

Üç beş ağaç eşlik ediyor, 

Bir de batmaya çalışan güneşin kızıllığı, 

Elimde kiremitten bir saksı, 

Saksının içinde bir yürek, 

Yüreğin üzerinde masum bir mine çiçeği, 

Çiçeğin üzerinde ben

Üzerimize düşen yağmur tanelerine

Ve tozu toprağı çamura bulanmış yollara aldırmadan, 

Çamurlu sel sularına karışarak yürüyoruz.

Bulutlar bile umurumuzda olmadan.', 'Yüreğimdeki Dosta, Çiçeğime Gün geceye karışmasın bugün,  Günün kızıla çaldığı saatlerde Yağmurun yağması arifesinde Sen''le düşüyordu aşk''a ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Şahin Soner']::text[], 8.5, '{"poet":"Ahmet Şahin Soner","poet_slug":"ahmet-sahin-soner","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/ask-a-sen-le-duser-yurek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tarih Bilmem Bilem Ne', 'tarih-bilmem-bilem-ne-gurol-genc-pel-van-yuji3', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Tarih bilmem bilmem ne

deli bir sevdaydı yaşadığım.. 

kısaydı ömrü bir gül kadar ama, 

bir ömre bedeldi ağırlığı..

hatırlıyomusun, geçen sene bu gün  söz vermiştin bana

daima beni ''''seveceğine'''' dair..

geçen senede havalar bu kadar sıcaktı, 

değilmi! ! 

tabiki hayalerde..

Yaz akşamlarında konuşurduk hep seninle, ne güzel olurdu 

terlerdik deliler gibi, ama kopamazdık

ayrılmak istemezdi ellerimiz..

her tuşa basışımda, yaklaşırdık sanki birbirimize

harfler değildi dokunduğumuz sanki

''''tenlerimiz''''di

garipseyişi ondandı belkide 

ümitlerimizin bizi, veya terkedişi..

Derken, 

dönmeden arkana ''''gittin'''' hatırlarsın, 

bir sigara yaktım ve başladım ağlamaya 

sanki geri döneceksinde, 

dilemeye başladım tanrıdan seni

tanrı bile duymuyordu haykırışlarımı

 yanlız kaldın dedim kendime gene..

neden hep olmazlar dostum olduki! 

yada düşmanım, düşünüp durdum.

kala kalmıştı bir sevdam daha gözleri kör

ugrak denizleremi açılmalıydı artık..

yoksa hep o limanda o geminin bir gün

elbette, geri döneceğinemi inanmalıydı..

o günden sonra küstüm sevdalara, 

artık sevdasız yaşamak hayatın bir parçası oldu..

belki bazı duygulardan yoksundum ama

''''ağlamıyordum'''' 

geceleri  3 şişe biraya gömmüyordum artık

kafayı bulduktan sonrada

sessiz bir yer arayıp ''''seni'''' haykırmıyordum

deli cocuk derdim kendime 

taşıyamadın bir sevdayı daha......', 'Tarih bilmem bilmem ne deli bir sevdaydı yaşadığım..  kısaydı ömrü bir gül kadar ama,  bir ömre bedeldi ağırlığı.. hatırlıyomusun, geçen sen...', ARRAY['Türk Edebiyatı','Şiir','Gürol Genç Pel Van']::text[], 8.5, '{"poet":"Gürol Genç Pel Van","poet_slug":"gurol-genc-pel-van","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/tarih-bilmem-bilem-ne-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerimiz', 'ellerimiz-erdem-kocaeli-y9orh', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'hurdacıya sattıgımız zenginligimizdi

aslında yokuz biz 

hurdacıya sattıgımız kimligimizdi

hep nedensiz acıkladık

yani acıklamamız nedensizdi

hurdacıya sattıgımız nedenlerimizdi

sen nokta degildin

ben de virgül

hurdacıya sattıgımız ellerimizdi', 'hurdacıya sattıgımız zenginligimizdi aslında yokuz biz  hurdacıya sattıgımız kimligimizdi hep nedensiz acıkladık yani acıklamamız nedensizdi...', ARRAY['Türk Edebiyatı','Şiir','Erdem Kocaeli']::text[], 8.5, '{"poet":"Erdem Kocaeli","poet_slug":"erdem-kocaeli","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ellerimiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgürlük', 'ozgurluk-meryem-akkin-biysm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Özgürlük; kimilerine göre, 

Gece yarısı sarhoşluk edasıyla boş sokaklarda 

                                                                bırakılan naralar

Kimilerine göre, 

Sıska bacaklarda giyilen mini eteklerin

Bir bahar havası gibi aldatıcı olması

Kimilerine göre de; 

Kişisel özgürlükleri ortadan kaldırmak ve 

İnsanca bir yaşam için alandarda çekilen 

                                                                 halaylar.

Hep bir ağızdan çıkan özgürlük türküleridir...

Kendilierini Munzur''un hırçın sularına bırakmıyorlar ki; 

Yaşasınlar gerçekleri 

Korkuyorlar...

Korkuyoruz gerçekleri yaşamaktan.

Daha varmadık insanca yaşamaya, 

Ha yaşadık, ha yaşayacağız derken

Ya arabanın tekeri patlıyor, ya benzini bitiyor.

Bırak kendini Munzur''un hırçın sularına, 

Yaşamak istiyorsan; yanına bir tekerlek, 

                                              ve bir bidon benzin al...!', 'Özgürlük; kimilerine göre,  Gece yarısı sarhoşluk edasıyla boş sokaklarda                                                                  b...', ARRAY['Türk Edebiyatı','Şiir','Meryem Akkın']::text[], 8.5, '{"poet":"Meryem Akkın","poet_slug":"meryem-akkin","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/ozgurluk-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Sana Yazardım', 'seni-sana-yazardim-meryem-akkin-j8adk', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Boş deslerde seninle 

Kazıntılı paslanmış ayakları

Adeta harabeyi andıran sıralarda 

Gökyüzünün maviliğine dalardık

Uzayın sonsuzluğunda buluşurduk; seninle 

Birbirimize söyleyemediklerimizi, 

                              paylaşamadıklarımızı.

Gündüz maviliğe 

Gece karanlığa anlatırdık, 

Sonra kendimi sonsuzluğa kaptırmış

                                                  yıldız gibi

Kaptırdım kalemime 

Mayıs''ta nergizi

Haziranda güneşi 

Eylülde sararmış yaprakları yazardım

Ve hayatımdan hiç kopmayan 

Kır çiçeklerini, havayı, suyu yazardım

Seni Sana Yazardım.', 'Boş deslerde seninle  Kazıntılı paslanmış ayakları Adeta harabeyi andıran sıralarda  Gökyüzünün maviliğine dalardık Uzayın sonsuzluğunda bul...', ARRAY['Türk Edebiyatı','Şiir','Meryem Akkın']::text[], 8.5, '{"poet":"Meryem Akkın","poet_slug":"meryem-akkin","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/seni-sana-yazardim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen Yoksun', 'sen-yoksun-yasar-yabutlu-7ag3e', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sen yoksun, gündüzler sende mi kaldı? 

Sen yoksun beni uçurumlar aldı.

Sen yoksun, ruhumda dünya daraldı, 

Çekip de gidecek karam, ne vardı.

Sensizlik sardı tutuldu güneşim, 

Hayatla yarıda kaldı güreşim, 

Şimdi arkadaşım, Saki kardeşim, 

Gönül bahçemde, güllerde sarardı.

Daha ne kadar sürecek bu serap

Gölgem gibi, ne benimsin ne ırak

Eğer bitmeyecekse bu ızdırap

Mesken tuttuğun kalbi artık bırak.', 'Sen yoksun, gündüzler sende mi kaldı?  Sen yoksun beni uçurumlar aldı. Sen yoksun, ruhumda dünya daraldı,  Çekip de gidecek karam, ne vardı....', ARRAY['Türk Edebiyatı','Şiir','Yaşar Yabutlu']::text[], 8.5, '{"poet":"Yaşar Yabutlu","poet_slug":"yasar-yabutlu","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/sen-yoksun-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aygül Ey', 'aygul-ey-hasan-ali-kasir-3e2p6', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gel, cennetimiz ol bizim aygül ey 

bir  ateş  kuyusu  kenarındayız

altımızda sırattan da ince bir köprü

gayya  denizlerinden  geçmekteyiz

aşk  nimetini  hatırla  yaratan  adına

dünya cehenneminde bırakma bizi yalnız

bir  deli  sevdanın  gündönümündeyiz

yaz bahar aylarında dolaşıyor gölgemiz 

yapayalnız  kalsan  da  gel,  gel  ki

biz de senin cennetin olalım aygül ey

sazımız ozanımız ol, anlat bizi aygül ey

yüreğinin bir köşesine bırak umutlarını

yatır dizine düşlerimizi usulca, uyanmasın

okşa   yasin   kokan   saçlarını   annenin

bir divan sazı farz et  bilcümle sevdalıları

dolaş  perdeleri  arasında  aşkla, sevgiyle

çal usulca; ''hüma kuşu yükseklerden seslenir''

vur  tellerine,  inlet  bilcümle  anka''ları

elindeki mızrabın olalım ahh, n''olursun

sazımız ozanımız ol, anlat bizi aygül ey

güzelimsin bi''tanemsin  aygül ey

sultanısın sen muhabbet ülkesinin

bense sevgi kumaşı satan bir yûsuf

yürek   çarşısında   bir   garip   tâcir

gel müşterim ol benim, yıldızım ol

ürkmeden  gir  ülkeme  bi''başına 

yağmala çarşıda ne var ne yok, varlık adına

talan et sevdadan gayrı  ne bulursan

yürü  gül  kokulu  âşıklar  arasından

kulunu kurbanını sevdalını bul, aygül ey

han''ım ol, canım ol, sevdasız olma aygül ey

bir hırkam var büründüğüm taha kumaşından

dünya malı adına tek varlığım, gördüğün

gel de  can kat  sevda  ateşine, sönmesin

açık  bırak  zamana  bakan  pencerelerini

mekana açılan bütün kapılarını kapalı tut

hülagu  gibi  girer  kanına  sevda  bir  gün

ki  rengi  yoktur  sevdanın,  kokusu  yok

siyahı,  beyazı  yok; milleti  yok, ırkı  yok

canımsın bi''tanemsin sevdalı gülüm aygül ey', 'gel, cennetimiz ol bizim aygül ey  bir  ateş  kuyusu  kenarındayız altımızda sırattan da ince bir köprü gayya  denizlerinden  geçmekteyiz aş...', ARRAY['Türk Edebiyatı','Şiir','Hasan Ali Kasır']::text[], 8.5, '{"poet":"Hasan Ali Kasır","poet_slug":"hasan-ali-kasir","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/aygul-ey-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Tabak Koy Sofrana', 'bir-tabak-koy-sofrana-muammer-erkul-tj94z', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'BİR TABAK KOY SOFRANA...

İftara gelecegim.

Yetisemezsem; ilk gelene yedir benim yemegimi, benim yerime.

Sevabini paylasalim..

Bir tabak koy sofrana; 

Iftara gelecegim..

Tabagima bakislarini koy ve bir cift zeytin.Yeter bana..

Tebessumlerini ser once ustune bir tabak koy, benim icin.

Bardagima sesini doldur... Sesini icip nefesimi birakayim yerine...

Iftar sofralarinda duygu olamli.

Ve sevgi...

Ustune bir damla su, bir cift zeytin ve belki bir

kasik corba... Ama iftar sofralarinda ilgi olmali.

Iftar sofralarinda dua olmali; 

Benden sana, senden bana.

Bir tabak koy sofrana; iftara gelecegim...

Ve tabagimin yanina, boldugun dualardan koy.

Banada bir pay ayir, 

Ne olur? ..

Bir tabak koy sofrana; 

Iftara gelecegim.

Iftar sofralarinda unutma beni, dayanamam unutma...

Gelemeyecegimi bilsem de...

Gelemeyecegimi bilsen de; 

Bir tabak koy sofrana; 

Iftara gelecegim.

Tebessumlerini ser...

Ustune bos bir tabak koy. Corban yoksa bir cift zeytin koy.

O da yoksa bakislarini koy veya bir damla gozyasi...

Ama bir tabak koy bana, gelemesem de...

Bardagima sesini koy; ayni yerden bir sen bir ben icelim! ..

Ve tabagimin kenarina dualarini koy; bu, boldugun en 

buyuk dilim olsun..

Iftar sofranda duygu olsun... Sevgi olsun... Ilgi olsun...

Ben gelemezsem bir kepce corba icir benim yerime; Dua al, paylasalim.

Dayanamam...

Unutma, olur mu? 

Benim icin bir tabak koy sofrana; 

Iftara gelecegim.

Gelecegim...', 'BİR TABAK KOY SOFRANA... İftara gelecegim. Yetisemezsem; ilk gelene yedir benim yemegimi, benim yerime. Sevabini paylasalim.. Bir tabak koy ...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erkul']::text[], 8.5, '{"poet":"Muammer Erkul","poet_slug":"muammer-erkul","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/bir-tabak-koy-sofrana-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğinde Yer Var mı?', 'yureginde-yer-var-mi-muammer-erkul-at8i9', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Parmaklarinin ucunda su an hissediyor musun “ben”i? 

Hisset.

Hisset parmaklarina degen kâgidin içinde dolasan damarlarimi... Hisset

damarlarimdaki kanimin, seni aramak için deliler gibi dolasmasini...

Parmaklarinin ucunda su an hissediyor musun beni? 

Dinle; 

Duyuyor musun yüregimin ritmini? 

Gönlümde esen rüzgârlari dinle...

Nefesimi tutmasam gözlerindeki derin ovalarda titreyen bütün

yesillikler kül olur! Sazlar büyür simsiyah, kuruyan gözpinarlarinda! ..

Parmaklarinin ucunda su an hissediyor musun beni? Yazik; mekânlar

durduruyorsa seni.

Ve yazik kendini bagladiysan maddelere...

Ipsiz bir uçurtmayim ben. Ve, kuyruksuz... Saçlarinin çizgilerinde

süzülen...

Rüzgârim sensin.

Susma ve sakin gözlerini kapatma; 

Düserim! 

Yüreginde yer var mi? 

Parmaklarinin ucunda su an hissediyor musun beni? Ve bir kaynak

suyundan olusan derenin üzerine düsen yaprak gibi; düsürüyor musun

gülüslerini ve öpüslerini sesimin üstüne? ..

Akiyor musun benimle beraber; 

Akiyor musun yildizlara dogru? 

Yildizlar... Yildizlar neden böylesine vefasiz? Neden her üsüyüsümde

lapa lapa yagiyorlar avuçlarima; 

Ve neden eriyip kayboluyorlar? ..

Parmaklarinin ucunda su an hissediyor musun beni, bilmiyorum.

Bilmek istemiyorum...

Ama parmaklarinin ucunda “su an” ne olur hisset beni.

Hisset.

Hisset parmaklarina degen kâgidin içinde dolasan damarlarimi... Hisset

damarlarimdaki kanimin, seni aramak için deliler gibi dolasmasini...

Söylemistim degil mi; ; Ipsiz bir uçurtmayim ben ve kuyruksuz...

Saçlarinin çizgilerinde süzülen...

Rüzgârim sensin.

Susma ve sakin gözlerini kapatma; 

Düserim! 

Yüreginde yer var mi?', 'Parmaklarinin ucunda su an hissediyor musun “ben”i?  Hisset. Hisset parmaklarina degen kâgidin içinde dolasan damarlarimi... Hisset damarlar...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erkul']::text[], 8.5, '{"poet":"Muammer Erkul","poet_slug":"muammer-erkul","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/yureginde-yer-var-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzaklar', 'uzaklar-muammer-erkul-bbo78', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Ben seni soluyorum; Sen uzak iklimleri...

Ayri kitalardaki ayri denizlere daliyor gözlerimiz...

Ama, tepemizde “demirkazık” yildizi! 

Ben seni soluyorum; 

Sen uzak iklimleri...

Ben seni kokluyorum; 

Sen uzak iklimleri...

Terliyor musun? sebnemler parliyor mu teninde? ..

Ne? .. Gögsünde sakli çiçeklerin adı ne? ..

Disinda yürüyen damlalar “içinde” gezinseydi keske. Ve keske

“susuzlugun” olsaydim! 

Ben seni ve sen uzak iklimleri kokluyorken; 

Sen beni özleseydin, 

Uzak iklimler seni! ..

Kalp, kalip tanimiyor...

Zarfsiz da gidebiliyor mektuplar.

Kim demis “rüzgâr nefesini tasiyamaz” diye bana? .. Kim söylemis

yildizlarda göremeyecegimi gözlerini? .. Sen bir kitada ben bir kitada

olsak da... Ve seni bir baska iklim, beni bir baska iklim soluyor olsa

da; 

Kim bilmis yere kulagimi dayadigimda duymadigimi kalbinin sesini? ..

Kim söylemis? ..

Karincalar yok mu orda? .. Hiç serçe görmedin mi? .. Günese gülen

papatyalar beyaz degil mi? .. Durgun sular ve bütün aynalar seni

göstermiyor mu? ..

Karincalar, serçeler ve papatyalar iste surada... Günes, beni

tanimazdan gelmiyor! .. Ve durgun sularla bütün aynalar seni gösteriyor

burada da...

Öyleyse orasi, burasi! 

Kalp, kalip tanımiyor ki; 

Burdasin! ..

Bir kuyrukluyildiz gördüm. “Kuyruklu bir yildiz görürsen dilek tut”

demislerdi. Bir dilek tuttum, kuyrukluyildizin haberi bile olmadan: 

“Dilerim ki kuyrugundan hiç ayrilmazsin...”

O yildiz, kuyruguyla güzeldi çünkü. Çünkü ikisi bir bütündü...

Ben seni soluyorum; Sen uzak iklimleri...

Ayri kitalardaki ayri denizlere daliyor gözlerimiz...

Disinda yürüyen damlalar içinde de geziniyor olsaydi keske, diyorum.

Keske susuzlugun olsaydim.*Bir yildiz, kuyrugunu yüregime dolayip

gidiyor; baska bir iklime dogru...

“kuyrugunla güzelsin” diyorum.

Biliyorum; zarfsiz da gidiyor mektuplar...

Biliyorum kalip tanimadigini kalplerin.

“Ben seni ve sen uzak iklimleri kokluyorken...” Diyorum; 

“Sen beni özleseydin keske...

Ve uzak iklimler seni! ”', 'Ben seni soluyorum; Sen uzak iklimleri... Ayri kitalardaki ayri denizlere daliyor gözlerimiz... Ama, tepemizde “demirkazık” yildizi!  Ben se...', ARRAY['Türk Edebiyatı','Şiir','Muammer Erkul']::text[], 8.5, '{"poet":"Muammer Erkul","poet_slug":"muammer-erkul","theme":"Türk Şiiri","is_hero":false,"total_lines":46,"source_url":"https://www.antoloji.com/uzaklar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yeni Biriyim', 'yeni-biriyim-soner-arica-7jt4h', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Çok güvendin sen kendine

Çok hata ettin, 

İhmallere kurban gitti ah, yüce sevgim

Kim kazandı, 

Kim kaybetti önemli değil

Yalan yoktu

Çok sevmiştim gönül vermiştim

Dur deme boş yere zamanı geldi

Israr etme, 

Gitmeliyim

Ateş bacayı sardı artık 

Yeni bir aşkla yei biriyim...', 'Çok güvendin sen kendine Çok hata ettin,  İhmallere kurban gitti ah, yüce sevgim Kim kazandı,  Kim kaybetti önemli değil Yalan yoktu Çok sev...', ARRAY['Türk Edebiyatı','Şiir','Soner Arıca']::text[], 8.5, '{"poet":"Soner Arıca","poet_slug":"soner-arica","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/yeni-biriyim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gitmeseydin...', 'gitmeseydin-serdar-gumustas-n8cov', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Bir buğu gün batımı camımda...

Bir isim; üzerine yazılmış.

Sana ait...

Bir sevda masalı...

Bir ağıt ardından yakılan, 

Bir ateş hiç sönmeyen

Ve görülen uzakta...

Gelmesi istenmediği halde, 

Aheste gelen bir tren...

Seni alıp götüren...

Çaresiz sızlayan bir yürek, 

Biçare bir dert, 

Umutsuz bir bekleyiş, 

YA DÖNERSEN? 

YA DÖNMEZSEN? 

Ne olacağı bilinmez...

Ölmeli mi? 

Kalmalı mı? 

Terk-i diyar mı eylemeli buraları? 

Cevapsız sorular, 

Çıkmaz yollar...

NE VARDI SANKİ GİTMESEN? 

Serdar Gümüştaş', 'Bir buğu gün batımı camımda... Bir isim; üzerine yazılmış. Sana ait... Bir sevda masalı... Bir ağıt ardından yakılan,  Bir ateş hiç sönmeyen...', ARRAY['Türk Edebiyatı','Şiir','Serdar Gümüştaş']::text[], 8.5, '{"poet":"Serdar Gümüştaş","poet_slug":"serdar-gumustas","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/gitmeseydin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Casablanca'' ya Hiç Gitmedik Değil mi', 'casablanca-ya-hic-gitmedik-degil-mi-nevzat-gurmen-ntce1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'sen olmasan, inan sen olmasan; 

ne bu güneş batabilirdi ufukta, 

ne de doğmaya güç bulabilirdi yeniden.

ilk nerede karşılaşmıştık ben de anımsamıyorum artık.

luxor ''da mıydı ya da bir aztek tapınağında mı

londra metrosunda mı, ''circle line'' da sabahı beklerken.

benim ilk hatırladığım, 

uzun yıllar önce bir iç savaşta görüşmüştük.

yakıcı ispanya güneşinde fransızlarla beraberdik, 

geceleri baladlar söylerdik ateş başında.

fırsat buldukça troçkizmi ve marksizmi tartışırdık; 

üniversite yıllarında hegel ''i tartıştığımız gibi.

hiç aynı fikirde olmadık bu tartışmalarımızda, 

ama hiç unutmadık  birbirimizin düşüncelerini.

amerikalıların ayrılmasından hemen önceydi

bir japon limanında geceyarısını geçe gördüm seni.

alkol duvarını aşmıştım, iki gemici taşıyordu.

kimono giymişsin gibi geldi, o gece öyle geldi.

seni japonya ''da ikinci görüşüm çok sonraydı, 

kyoto ''da sokakta yürüyordun temmuz ortası

yanındaki avrupalıya giydirmiştin kimonoyu, 

sense hergünkü giysinle kalabalığa karışmıştın.

deprem sonrası kobe ''de bir toplantıdaydım o sıra.

davulların ritmine kapılmışken - adı taiko idi galiba -

yürek seslerinin sadece davullardan gelmediğini anladım.

karşımda durmuştun, öylece dinliyordun.

oslo ''da otelin en üst katındaki barda gördüm yıllar sonra, 

vestiyerde sarhoş bir norveç ''liden zor kurtardım.

flam-line''la indiğimiz fiyort çok yormuştu beni

ayakta duramıyordum, adam iri ve sarhoştu.

farkında değildin sen karşılaştığımızın, 

hatta o gece bana kızmış bile olabilirsin.

bir süre unutmuştum ki seni, 

barselona ''da dolaşırken aylak aylak

rambla ''da karşıma çıktın aniden.

öyle heykel gibi duran bir genci seyrediyordun

her para attıklarında delikanlı şekil değiştiriyordu

sen çok eğleniyordun, ama bu kez tanıdın beni.

o haftayı beraber geçirdik

önce gaudi ''yi dolaştık beraber, tüm yapıtlarını, 

kaybolduk sagrada familia ''da.

neyse ki sözleşmiştik, picasso ''da buluşalım diye.

seni ispanya ''da son görüşüm

şarap mahzenlerini gezdikten sonra oldu

flamenko yaptık karşılıklı, benim için ilkti

sen sanki hep dansediyormuşsun gibi geldi o gece.

sahi neden hiçbir şeyi ilk kez yapıyorsun gibi gelmiyor.

lyon ''da seni buluncaya dek neler yaptığını hiç anlatmadın.

ilkinde bir gemi güvertesinde kaçak gelmiştim lyon ''a, 

oniki eylül sonrasıydı, şartlı salıvermişlerdi nasılsa, 

pasaportta bir sorun çıkmamıştı, ama bıçak sırtı bir kaçıştı.

umutsuz değildim ama yorgundum ve beş parasızdım, 

şu fransızlar da hiç ingilizce konuşmuyordu üstelik.

bu kez uçakla gelmiştim kaçak da değildim, 

en azından herkes kadar kaçaktım yaşamdan. 

bir toplantı için gelmiştim, fransızlar ingilizceyi öğrenmişti.

çok sevinmiştim seni karşımda bulduğuma

sen olmasan inan ne tekrar çekebilirdim bu şehri, 

ne de o şatonun mahzeninin tadına bakabilirdim.

yıllandıkça güzelleşen sadece şarap değildi o gece.

 yıllar sonra sorabildim sana milwaukee ''de

göl kıyısında donmuş dalgalar üstünde çocuklar gibi oynarken

benimle mutlu musun diye, hiç cevap vermedin.

noel hazırlığındaki evlerin bahçelerini gezmiştik

aralık sonu geliyordu, hava soğuktu ve sen üşüyordun

sahi neden sen hep çok üşürdün bilmiyorum, 

ısıtamamıştı ayaklarını lyon ''daki şatonun koca şöminesi

neden sonra chicago ''da bir barda sahneden indiğinde

yanıma oturdun ve senden sonra sahnedekini dinlerken

iki blues arası kulağıma fısıldadın

bu beni sevdiğini ilk söylemendi, asırlar sonra ilk defa

bir de blues söylediğini öğrendim o gece

aslında ben pek blues sevmem, yani birkaç parçadan fazlasını

chicago ''daki barda kaç saat blues dinledim bilmiyorum

her iki blues arası kulağıma tekrar fısıldamanı bekledim

ama sen bir daha söylemedin, o geceden sonra kaç yıl geçti

sanırım millenium ''da, bu kez dinlediğimiz blues olmasın.

bazen karıştırıyorum ama, casablanca ''ya hiç gitmedik değil mi

ya da bensiz gitmiş olabilir misin bilmiyorum.

sen olmasan, inan sen olmasan; 

ne bu güneş batabilirdi ufukta, 

ne de doğmaya güç bulabilirdi yeniden.

seni görür gibi oldum bir an ama yanına gelemedim, 

kosova ''da yaralıları geziyorduk çadırlarda.

neden sonra aradım çamurlu yollarda, gitmiştin sanırım.

hissettiklerim biraz karışıktı o gün

halide edib ''in ateşten gömleği ile

filmin sonundaki dr. jivago arası bir yerlerdeydim; 

hani yıllar sonra bir dokunma yakınlığındayken

süzülüp kayboluş parmakların arasından.

yağmur yağıyordu ve ben seni çok seviyordum, 

bu da benim ilk itirafımdı asırlar sonra

yağmur yağıyordu çadırların üstüne ve ben ağlamıyordum.

bir kez daha yıllar önce görüp te gelememiştim yanına

bir miting alanındaydık, hakan ''ı vurmuşlardı 

maltepe camii yokuşunda gözgöze geldik

henüz devrime aşk karışmamıştı bakirdi.

gelemezdim, hoş karşılanmazdı, o kadar.

gerçeği geç de olsa anladı bizim kuşak, nice sonra.

biz devrimi çok sevmiştik ama sevmeyi unutmuştuk

sonraları aşk karıştı ama ortada devrim kalmamıştı.

tekrar görüştük mü o ara bilemiyorum, 

uzun bir süre yoktun gibi geldi.

son görüşmemiz körfez depreminden hemen sonraydı

yardım toplamıştık birbirimizden habersiz, 

istinye limanından yollamak için bekliyorduk.

çadırları battaniyeleri içeren yüke el attığımda hissettim elini, 

aylardan ağustostu ve sen yine üşüyordun.

akşam karanlığında baktım yüzüne, hiç değişmemiştin; 

kahretsin, ne kadar güzeldin.

yıllandıkça güzelleşen sadece şarap değildi biliyordum.

yalnız mıydın yoksa biri mi vardı yanında

tanıyamadın gibi geldi beni, öyle bir baktın.

çok mu değişmiştim son görüştüğümüzden bu yana, 

ben de çok isterdim tanımazlıktan gelmeyi ama yapamadım

birine benzetmiş de yanılmış gibi yapabildim ancak.

ağustos sonuydu, yağmur da yağmıyordu

ama ben çok üşüyordum, ilk kez üşüyordum.

herhalde son görüşmemizdi.

güneş batmıştı o gece seni gördüğümde, 

yeniden doğmaya güç bulabilecek miydi bilmiyordum.', 'sen olmasan, inan sen olmasan;  ne bu güneş batabilirdi ufukta,  ne de doğmaya güç bulabilirdi yeniden. ilk nerede karşılaşmıştık ben de anı...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":121,"source_url":"https://www.antoloji.com/casablanca-ya-hic-gitmedik-degil-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sakın Gelme', 'sakin-gelme-nevzat-gurmen-fwozt', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'tüm bunlar bir yanılsamaysa, 

gerçekten hiç yaşamadıysam seni; 

sakın gelme, bir daha görmek istemem.

bir bulut kadar somut, 

ve bir zehir kadar soyut, 

istemem gözlerindeki yanılgımı.

bırakması zor hiç tanımadığım ellerini, 

sakın gelme bir kez olsun tutmak istemem.

değilmi ki dağılmış saçların, 

ve yeni uyanmış kedi yavrusu bakışınla, 

yanımda uyanmayacaksın; 

o sabahın gecesini de istemem.

sakın gelme, gittiğin yerde kal.

güneşin battığı yerde, 

sabahın olduğu yerde kal.', 'tüm bunlar bir yanılsamaysa,  gerçekten hiç yaşamadıysam seni;  sakın gelme, bir daha görmek istemem. bir bulut kadar somut,  ve bir zehir k...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sakin-gelme-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni Düşündüm', 'seni-dusundum-nevzat-gurmen-zaqgh', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'seni çıplak ayaklarınla

çimlerin üstünde gezinirken düşündüm, 

başında bir şapka, üstünde bir tulum.

seni kumların üstünde

tembel tembel yatarken düşündüm.

ya da bir divanın üstünde, 

bağdaş kurup otururken 

öyküler yazdığını düşündüm, 

üstünde bol bir kazak, 

uzun kolları kalemine takılan.

gözlüğün var mı bilmiyorum, 

ama düşünürken eminim gözlerini kıstığından.

seni mutfakta sebzeleri karıştırırken düşündüm, 

kocaman bir tahta kaşık elinde.

kendimi tutamadım

doğrarken sebzeleri parmağını kestiğini düşündüm, 

ve hemen ağzına götürüşünü, 

düşündüm işte.

akdeniz kıyısında ya da boğazda, 

salaş bir balıkçı meyhanesinde

düşündüm seni.

kahkaha atarken ve yudumlarken içkini, 

nasıl göründüğünü düşündüm.

elimde değildi, seni hep düşündüm.

seni düşündüm, 

düşündüm seni.', 'seni çıplak ayaklarınla çimlerin üstünde gezinirken düşündüm,  başında bir şapka, üstünde bir tulum. seni kumların üstünde tembel tembel yat...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/seni-dusundum-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Özel', 'sana-ozel-nevzat-gurmen-blg2r', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'tüm sıfatlarımı bıraktım sana ait.

sıcak bir dost eli, 

ağlayabileceğin bir kucak; 

ya da bir yürek seni dinleyecek.

seslenmen yeterli, 

iki elim kanda olsa gelirim.

değilmi ki sendeki insanı sevdim, 

bırak içindeki kadını, 

kiminle giderse gitsin.', 'tüm sıfatlarımı bıraktım sana ait. sıcak bir dost eli,  ağlayabileceğin bir kucak;  ya da bir yürek seni dinleyecek. seslenmen yeterli,  iki...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sana-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hepsi Bu', 'hepsi-bu-nevzat-gurmen-2z1r0', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sanma ki seninle başladı yaşam.

ve sanma ki seninle bitiyor.

senden önce de vardı bu yağmur, 

senden sonra da esecek rüzgar.

deniz kabuğumu dinletmemiştim kimseye, 

senden sonra da dinletmeyeceğim, hepsi bu.', 'sanma ki seninle başladı yaşam. ve sanma ki seninle bitiyor. senden önce de vardı bu yağmur,  senden sonra da esecek rüzgar. deniz kabuğumu ...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/hepsi-bu-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neyimsin ki', 'neyimsin-ki-nevzat-gurmen-srw3a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen benim görmeyen gözüm, 

duymayan kulağımsın.

sen benim korkak yüreğim, 

özgürlüğünden kaçanımsın.

sen benim değerini bilmeyenimsin.

sen benim pırıltısını bilenim, 

parlaklığını isteyerek silenimsin.

sen benim sıradışı olmaktan ürkenimsin.

sen benim yanlışını ikileyenim, 

yaptığı seçimi hak edenimsin.

sen benim işin kolayını seçenim, 

zor sevdaları teğet geçenimsin.

sana mutluluklar istediğince, 

sahi, sen benim neyimsin ki?', 'sen benim görmeyen gözüm,  duymayan kulağımsın. sen benim korkak yüreğim,  özgürlüğünden kaçanımsın. sen benim değerini bilmeyenimsin. sen b...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/neyimsin-ki-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gaudi'' den Lancelot'' a', 'gaudi-den-lancelot-a-nevzat-gurmen-890y5', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gaudi bilmiyor muydu sanki

hayallerini bitiremeyeceğini.

ya Van Gogh kulağını kestiğinde

o kulağın bir daha olmayacağını.

kış uykusunu ininde yaşarken

dorukta kayalıktan havalanmak.

doğan günle geleni bilerek, 

Prometheus ''la zincirlenmek. 

Prokofiev ''in Romeo Juliet''i

farklı değil mi Tchaikovsky''den

kapalı gözle yağmuru dinlerken

Beethoven sağırlığını hissetmek.

günboyu örülen ilmekleri, 

Penelope ''la her gece yeniden sökmek. 

King Arthur ''u yaşarken 

ansızın Lancelot oluvermek.

elinde bulduğun cevherin

altın ya da taş olması ne farkeder, 

önemli olan umudu doğuran yıllar.', 'Gaudi bilmiyor muydu sanki hayallerini bitiremeyeceğini. ya Van Gogh kulağını kestiğinde o kulağın bir daha olmayacağını. kış uykusunu inind...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gaudi-den-lancelot-a-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kadınlara Özel', 'kadinlara-ozel-nevzat-gurmen-rq80d', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'hepimiz aynı kadını seviyoruz

sevdiklerimiz hep aynı kadın

yumuşak, sevgi dolu ilk bakışta

sarp kayalar karşınızda

attığınız her adımda

gözlerinizde mi gözleri

saçı, yüzü, elleri

aynı kadın bu sevdiğimiz

fırtınalı deniz gibi değişken

gizemli, sırlarına ulaşılamayan

hep aynı kadın beraber yaşlandığımız

sözcükleri dudaklarında tanıyamadığımız

kışın güneş giymiş, saçları yağmur rengi

kasım yaprağının yerde hiç kurumadığı

hepimiz aynı kadını seviyoruz aslında

ben aklını ve yüreğini aldım

kalanları siz paylaşın', 'hepimiz aynı kadını seviyoruz sevdiklerimiz hep aynı kadın yumuşak, sevgi dolu ilk bakışta sarp kayalar karşınızda attığınız her adımda gözl...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kadinlara-ozel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rüzgarı Anlamak', 'ruzgari-anlamak-nevzat-gurmen-kirbc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'rüzgarı anlamak için

yüzünde hissetmelisin çocuğum.

yarım kalır yoksa tüm duyuların.

başakların salınımını, 

varoluşunu dalgakıranın, 

ne kadar çabalasan

hissedemezsin yüreğinde.

yaprakların devinimi, 

dalda ıslığın fısıldadıkları, 

tohumun savruluşundaki giz

kalır sana yabancı.

koşmalısın rüzgara çocuğum

rüzgara koşmalısın tüm gücünle, 

onu yüzünde hissetmek için.', 'rüzgarı anlamak için yüzünde hissetmelisin çocuğum. yarım kalır yoksa tüm duyuların. başakların salınımını,  varoluşunu dalgakıranın,  ne ka...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ruzgari-anlamak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Rasgele Bir Olasılık Sadece', 'rasgele-bir-olasilik-sadece-nevzat-gurmen-ymhgj', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bir şiir belki karşılaşmamız.

ürkek adımlarla yürüyoruz

yaşamın kıyısındaki çakıllarda.

çıplak ayaklarımız acı içinde

direniyoruz yürekler avucumuzda

ruhumuzu inatla yaşatırcasına.

örselenmekten korumak için bedenini

ve küçük ayaklarını taşlardan

seni kucağımda taşımak geliyor içimden.

oysa rasgele bir olasılık karşılaşmamız.', 'bir şiir belki karşılaşmamız. ürkek adımlarla yürüyoruz yaşamın kıyısındaki çakıllarda. çıplak ayaklarımız acı içinde direniyoruz yürekler a...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/rasgele-bir-olasilik-sadece-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zor Olan', 'zor-olan-nevzat-gurmen-1yc8w', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'zor olan bir sevdayı

hiç yoktan var etmekti

sen yıllardır var olanı

yok etmeyi başardın

tüm çağlarda sevgiyi taptaze tutmaktı

kumsal ateşinin yorgun korlarında 

gün doğumu yürümekti

bir emek işçiliğiydi bu sevda

her çağda üstüne titrediğim

her şey  her an ki bana karşı

bense varoluşun tüm anlamsızlığına

yanlış hayatları doğrulamak için

senin köklerini toprağımdan tırnağımla kazıdım

yaşamın prizması ayırırken renkleri

hiçbir renk tutmaz bir diğerini

seçerek özenle tüm renklerden 

ben seni kendi bedenimden yarattım

alışılmışın karanlığında gözleri görmeyenim 

sen benim zor sevdaları teğet geçenim

yıllardır hep sürgünde bahar dalını 

en yeşilinden kurutmayı başardın', 'zor olan bir sevdayı hiç yoktan var etmekti sen yıllardır var olanı yok etmeyi başardın tüm çağlarda sevgiyi taptaze tutmaktı kumsal ateşini...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zor-olan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gar Binası', 'gar-binasi-nevzat-gurmen-k6jda', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'sarp kayalıkların deniz feneriydim

küreksiz bir sandaldım

ıssız denizin ortasında

demiryolu döşenmemiş bir kentin

yıllar önce yapılmış

kimsesiz gar binasıydım

sabah trenleri hiç kalkmayan

hiçbir yolcusu beklenmeyen

rüzgarsız tepenin yeldeğirmeniydim

yanlış yerdeydim

yanlış zamanda', 'sarp kayalıkların deniz feneriydim küreksiz bir sandaldım ıssız denizin ortasında demiryolu döşenmemiş bir kentin yıllar önce yapılmış kimse...', ARRAY['Türk Edebiyatı','Şiir','Nevzat Gürmen']::text[], 8.5, '{"poet":"Nevzat Gürmen","poet_slug":"nevzat-gurmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/gar-binasi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Hırsızı', 'gonul-hirsizi-kadir-duymaz-jbhae', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'söz verdim, 

gece yarıları, içtiği boş rakı şişelerini, 

arkamdan fırlatan babama, 

''aşık olmayacağım''

diye....', 'söz verdim,  gece yarıları, içtiği boş rakı şişelerini,  arkamdan fırlatan babama,  ''aşık olmayacağım'' diye.......', ARRAY['Türk Edebiyatı','Şiir','Kadir Duymaz']::text[], 8.5, '{"poet":"Kadir Duymaz","poet_slug":"kadir-duymaz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gonul-hirsizi-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şair ile Tekirdağ''ın Söyleşisi', 'sair-ile-tekirdag-in-soylesisi-sefa-madak-1t2uj', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Tekirdağ..! 

Seni bana sevdiren bir dostum yaşar sende.

Çatı katında oturur, 

Mühendislik fakültesinde okur.

Canı nereye isterse

Bırak gezsin sokaklarında.

Bir akşamüstü oturduğunda kıyısına denizinin

Dokunma bırak seyretsin

Şiirler söylesin.

Geç uyanır bilirim cumartesi-pazar

Sonra kalkar balkona çıkar.

Sen mevsime bakma

Nisan edasıyla güneşi çıkar.

Yalnızlığı da hissettirme akşamları olmaz mı? 

Yıldızlarla ay ne güne

Yıldızlarla ayı çıkar.

Havalar da ne sıcak

Ne soğuk olsun

En iyisi bahar olsun.

Karıda sever Allah kahretsin

Boşver ir kaç yılda

Karsız idare etsin.

Sahip çık sokak serserilerine

Korkuyorum peşine düşerler diye

Ve hepsinden önemlisi

Darda kalıp hüzünlendi mi

Bir mektupla bir bardak suda

Bir umut rüzgarı estirki

Dolsun yaşama sevincinin yelkenleri.', 'Tekirdağ..!  Seni bana sevdiren bir dostum yaşar sende. Çatı katında oturur,  Mühendislik fakültesinde okur. Canı nereye isterse Bırak gezsi...', ARRAY['Türk Edebiyatı','Şiir','Sefa Madak']::text[], 8.5, '{"poet":"Sefa Madak","poet_slug":"sefa-madak","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/sair-ile-tekirdag-in-soylesisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ondan Sonra', 'ondan-sonra-emin-uyguner-j1ggr', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'ondan sonra hiç sevilmedim yer yüzünde

hep onu bekledim günlerce 

bekledim ama gelmedi gelmedi işte

zaten istesede gelemezdi 

çünkü toprak çalmıştı onu benden

mayısın o irenç gününde....', 'ondan sonra hiç sevilmedim yer yüzünde hep onu bekledim günlerce  bekledim ama gelmedi gelmedi işte zaten istesede gelemezdi  çünkü toprak ç...', ARRAY['Türk Edebiyatı','Şiir','Emin Uyguner']::text[], 8.5, '{"poet":"Emin Uyguner","poet_slug":"emin-uyguner","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ondan-sonra-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ve 8 Haziran''da Geçti', 've-8-haziran-da-gecti-ozan-arif-9vqbc', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne şahit, ne ispat, ne delil gerek, 

Apaçık ortada yönünüz sizin.

Hain değilseniz gafil olarak.

Tarihe geçecek ününüz sizin.

Dipçiğin rüzgarı tam tepemizde, 

Gazete yazamaz, hürlük var söz de! 

Televizyon sizde, radyo sizde, 

Konuşun ağalar gününüz sizin.

İşiniz sadece bizi yormaktır, 

Adalet değil de, denge kurmaktır.

''Sol''`u göstermektir, ''sağ''`a vurmaktır, 

Budur hüneriniz, feniniz sizin.

Millete boşuna rezil olmayın, 

''Disk'' falan hikâye kafa bulmayın, 

''Ecevit''`i tutup tutup salmayın! ..

Sadece ''Türkeş''`e kininiz sizin.

Sanmayın bu millet hep böyle durur, 

Bu teker, bu yolda ne kadar yürür? 

Rütbeniz çıkınca görürüz, görür! 

Kaç kuruş edecek tonunuz sizin! 

Ramazanda içip, iç açmak sizde, 

Eşarbı men edip, saç açmak sizde, 

Mayo giyin deyip, kıç açmak sizde, 

Nedir meshebiniz dininiz sizin? 

''Oniki Eylül`den önce şöyleydi''

''Oniki Eylül`den önce böyleydi''

Yeter artık yeter zıkkım olaydı, 

Yok mudur hiç başka konunuz sizin? 

Oniki Eylül`den önceki aylar, 

Emrinizde değil miydi alaylar? 

Susmanız demek ki şundanmış beyler: 

Hesapla meşgulmüş dününüz sizin.

Biriniz niyetli en büyük paya, 

Siz de mi düştünüz aynı sevdâya? 

Koltuk yumuşak mı neden kışlaya, 

Dönmek istemiyor canınız sizin.

Siz de alın yavrum(!)    her gelen aldı, 

Villasız, çiftliksiz hanginiz kaldı? 

Köşeyi döndünüz tastamam oldu, 

Hamamınız sizin, hanınız sizin.

Balık baştan kokmuş, baştan bozulmuş, 

Senaryonuz Vaşington`da yazılmış, 

Sanki dersin Holivut`da süzülmüş, 

İyi rol yapıyor ''jönünüz'' sizin.

Kendinize gelin derde kalmayın, 

Gaflete bu kadar fazla dalmayın, 

''Enver Sedat'' kadar sadık olmayın! ..

Beni hiç açmıyor sonunuz sizin.

Kimbilir nelere gebedir zaman

Diyeceğim şu ki; ''El oğlu yaman''

(Sakın ha Arif`i yanlış anlaman) 

Çelikten mi yoksa gönünüz sizin?', 'Ne şahit, ne ispat, ne delil gerek,  Apaçık ortada yönünüz sizin. Hain değilseniz gafil olarak. Tarihe geçecek ününüz sizin. Dipçiğin rüzgar...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":52,"source_url":"https://www.antoloji.com/ve-8-haziran-da-gecti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Gelen Böyle Dedi', 'her-gelen-boyle-dedi-ozan-arif-ubd8i', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Türkiye`den gelen birine sordum, 

Sordum ya elsürme yarama dedi.

Kim ne derse desin, her şeyi gördüm, 

Dokunma orama burama dedi.

Dedim, gardaş neden? Dedi ki dinle! 

Sebep arıyorsan, sebebi tonla.

Tek tek söyliyeyim ârifsen anla! 

Yurdun hali dönmüş drama dedi.

Gümrükçü istedi, avanta haydi! 

Nerde ise beni don gömlek koydu.

Yollarda trafik polisi soydu, 

Zor attım kendimi yöreme dedi.

Ne ise bunları kenara bırak.

Zenginin sofrası baklava, börek, 

Fakirin evinde tamtakır terek, 

Karnında bir lokma arama dedi.

Parası olanın işi yolunda, 

Vitrin vitrin gezer karı kolunda, 

Köylünün mahslü şişmiş elinde, 

Kâr kalmış çektiği cereme dedi.

İşçinin evinde bir dirhem et yok, 

Bebeği ağlıyor, anada süt yok, 

İşinde güven yok, yuvada tat yok, 

Düşünmekten düşmüş vereme dedi.

Dedim daha varmı? Dedi ki bitmez.

Piyasa bir alem, gün günü tutmaz.

Bir günde bir eve on ekmek yetmez, 

Ekmek inmiş üçyüz gırama dedi.

Her sabah onbinle çarşıya çıktım, 

Akşama beş kuruş kalmamış baktım, 

Aldığım bir şey yok, nerede bıraktım.

Ne oldu bilemedim parama dedi.

Resmi dairelik bir işin çıksa, 

Boyun kıravatsız, ayak çarıksa, 

Hele de askerden ahbabın yoksa, 

Kimse bakmaz derde, merama dedi.

Dedim ki; anarşi..! Dedi; eh bitmiş..! 

Velâkin sefalet yerini tutmuş.

Sırtımdaki hançer, karnıma batmış.

Böyle mi bakılır çareme dedi.

Köşeleri meyhaneler bürümüş, 

Küfür çiçek açmış, iman çürümüş, 

Şehirlerde fuhuş almış yürümüş, 

Bunlar hep yokluktan türeme dedi.

Türkiye müslüman, birisi sorsa! 

En baştaki adam orucu yerse(!)

Bu millet de onu ekranda görse; 

Kim uyar dinime, töreme dedi.

Ah... Ulan ah dedi, şu felek yok mu! 

Milliyetçi hapis, bu şimdi hak mı? 

Dedim; hukuk varmış..! Dedi hukuk mu..! 

Vatan hainleri hür ama dedi.

Dedim ki; anlatma kalmadı neşem.

Dedi; Arif gardaş nasıl konuşam? 

Giden ağam dedik, gelene paşam, 

Bizde de kabahat var ama dedi.', 'Türkiye`den gelen birine sordum,  Sordum ya elsürme yarama dedi. Kim ne derse desin, her şeyi gördüm,  Dokunma orama burama dedi. Dedim, gar...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":56,"source_url":"https://www.antoloji.com/her-gelen-boyle-dedi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çağa', 'caga-ozan-arif-5c5c7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bilmez mi kahpe felek, 

Nasıl geldim bu çağa? 

Ben düştüm bayrağımı, 

Düşürmedim alçağa.

Felek tuttu yine bak, 

Fırsat verdi alçağa!', 'Bilmez mi kahpe felek,  Nasıl geldim bu çağa?  Ben düştüm bayrağımı,  Düşürmedim alçağa. Felek tuttu yine bak,  Fırsat verdi alçağa!...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/caga-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zindeyiz', 'zindeyiz-ozan-arif-9mm4z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaradan`a çok şükür, 

Çelik gibi zindeyiz.

Bilevlendik Başbuğ`um, 

Pür dikkat izindeyiz.', 'Yaradan`a çok şükür,  Çelik gibi zindeyiz. Bilevlendik Başbuğ`um,  Pür dikkat izindeyiz....', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zindeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Emrindeyiz', 'emrindeyiz-ozan-arif-erm42', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Vatanın, milletin sahibi biziz.

Başbuğ`um emrinde, emrindeyiz biz.

Bu yolda bir ölür bin diriliriz.

Başbuğ`um emrinde, emrindeyiz biz.

Dinin ve devletin bekâsı için, 

İslâmın mubarek gazâsı için, 

Cenab-ı Allah`ın rızâsı için, 

Başbuğ`um emrinde, emrindeyiz biz.

Bu yol ki, hayatı bu yolda bulduk, 

Bu şuur, bu azmi biz senden aldık.

Tek kafa, tek yürek, tek bilek olduk.

Başbuğ`um emrinde, emrindeyiz biz.

Köy, şehir, kasaba, milli iradem, 

Antepli şahin`im, Maraş`lı edem, 

Yediden yetmişe gardaşım, dedem, 

Başbuğ`um emrinde, emrindeyiz biz.

Başbuğ`um olmasan her şey bitmişti.

Türkiye komünist olup gitmişti.

Sen sağ ol sayende gençlik yetişti.

Başbuğ`um emrinde, emrindeyiz biz.

Bu kervan gidecek ürsün köpekler.

Analar, babalar, doğan bebekler, 

Bozkurtlar hep senden işaret bekler.

Başbuğ`um emrinde, emrindeyiz biz.

Korkaklar gelmesin, geriye dönsün.

Dışarı çıkmasın evinde sinsin, 

Dün sendin, bugün de liderim sensin.

Başbuğ`um emrinde, emrindeyiz biz.

Sen emret her engel az gelir bize, 

Aşılmaz dağ olsa düz gelir bize, 

Zindanmış urganmış vız gelir bize, 

Başbuğ`um emrinde, emrindeyiz biz.

Sabrımız memleket için biline, 

Dileriz akıllar başa alına, 

Bir değil bin Arif feda yoluna, 

Başbuğ`um emrinde, emrindeyiz biz.', 'Vatanın, milletin sahibi biziz. Başbuğ`um emrinde, emrindeyiz biz. Bu yolda bir ölür bin diriliriz. Başbuğ`um emrinde, emrindeyiz biz. Dinin...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/emrindeyiz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üşürüz', 'usuruz-ozan-arif-gccva', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Zincir soğuk, zindan yaş, 

Belki biraz üşürüz.

Hele başım zindandan, 

Çıksında görüşürüz.', 'Zincir soğuk, zindan yaş,  Belki biraz üşürüz. Hele başım zindandan,  Çıksında görüşürüz....', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/usuruz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zelzelenin Söylettiği', 'zelzelenin-soylettigi-ozan-arif-ntfuv', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hikmetinden sual olmaz Yârabbim, 

Affına sığındım bak peşin peşin, 

Zelzeleyi çankaya`ya versene, 

Erzurum`la, Horasan`la ne işin.', 'Hikmetinden sual olmaz Yârabbim,  Affına sığındım bak peşin peşin,  Zelzeleyi çankaya`ya versene,  Erzurum`la, Horasan`la ne işin....', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/zelzelenin-soylettigi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mecburiyet', 'mecburiyet-ozan-arif-fxfbq', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ne onu, ne bunu, ne şunu derdi, 

Milletin tutacak dalı olaydı.

Millet bunları mı lider ederdi? 

Vetodan kaçmanın yolu olaydı.

Tepeden gelmiştir bize bu yara! 

Liderliği bırakalım kenara, 

Bostanını bekletmezdi bunlara, 

Milletin bu işte eli olaydı.

''Selamet'' le ''Tekdal'' meyve tutardı.

Kadayıfın dumanları tüterdi.

Hoca gibi zorlu temel atardı, 

Kazması, küreği, beli olaydı.

''Horoz'' peydah oldu, aslan kesildi, 

Herkes bilir önceleri nasıldı, 

Altı kasım geldi sesi kısıldı, 

Civciv çıkartırdı dölü olaydı.

Eski ''Kırat'' ''Doğru Yol'' da dururdu, 

Vatandaşı sırtladımı götürdü, 

O mirasla onikiden vurdurdu, 

''Avcı'' nın tüfeği dolu olaydı.

''Calp'' denen adamı tanıyın iyi, 

Her çeşit solcudan topladı payı, 

Rüyada görürdü bu kadar reyi, 

Sadece ortanın solu olaydı.

''Sodep'' için ne söylesen kâr etmez, 

Hak her kulu hayır diye yaratmaz! 

''Erdal'' varya babasını aratmaz, 

Birde kulağında pili olaydı.

Bakmayın çıkmaza girdi vatandaş, 

Hırs ile reyini verdi vatandaş, 

Önce geldiğinde yerdi vatandaş, 

Eğer bu ''Arı'' nın balı olaydı.

Arif der; memleket yutmuştur hapı, 

Hepsinden olmaz bir balta sapı, 

Vallahi yanmazdım bunların topu, 

''Türkeş'' in saçının teli olaydı.', 'Ne onu, ne bunu, ne şunu derdi,  Milletin tutacak dalı olaydı. Millet bunları mı lider ederdi?  Vetodan kaçmanın yolu olaydı. Tepeden gelmiş...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":36,"source_url":"https://www.antoloji.com/mecburiyet-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Hayatın Gayesi', 'bir-hayatin-gayesi-ozan-arif-nu4r8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Ey... En kara sevdaların sevdası, 

Bu kim bilir kaç bin kalbin sedası! 

Ey... Nesl-i Asım`ın ana gıdası; 

		Ekmeğim sen, suyum sensin, havam sen, 

		Yaşamamın gayesisin dâvâm sen.

	

Yürek yürek senin ile dolmuşum, 

Vatanıma seni lâyık bulmuşum, 

Senin için terk-i vatan olmuşum.

		Dağım sensin, taşım sensin, ovam sen, 

		Yaşamamın gayesisin dâvâm sen.

  

Ağlıyorum, göze sicim sicimsin.

Tahamülüm, tâkatimsin, gücümsün, 

Şu gurbette gardaşımsın, bacımsın, 

		Anam, babam, evim-barkım, yuvam sen

		Yaşamamın gayesisin dâvâm sen.

Dörtbir yanda kaldı her bir pârem oy...

Senin ile şifa bulur yârem oy...

çaresizlik içindeki çarem oy...

		Tabibim sen, dermanım sen, devâm sen, 

		Yaşamamın gayesisin dâvâm sen.

Kendimi çok zindalarda buldum ben, 

Sen sanmaki bu çileden yıldım ben, 

Bu çileye baştan tâlip oldum ben, 

		ç; ile ile bulacaksın kıvam sen, 

		Yaşamamın gayesisin dâvâm sen.

Zindanın tam önündeki meydanda, 

Son şehidi verdim yağlı urganda, 

Gülle yemiş sur gibiyim şu anda! 

		Temelim sen, duvarım sen, sıvam sen, 

		Yaşamamın gayesisin dâvâm sen.

Ey... Arif`in dilinde ki türküsü! 

Küfrün ve imansızın korkusu

Ey... Ak şafak, ey... Türk-İslâm ülküsü; 

		İlelebed edeceksin devam sen, 

		Yaşamamın gayesisin dâvâm sen.', 'Ey... En kara sevdaların sevdası,  Bu kim bilir kaç bin kalbin sedası!  Ey... Nesl-i Asım`ın ana gıdası;  		Ekmeğim sen, suyum sensin, havam...', ARRAY['Türk Edebiyatı','Şiir','Ozan Arif']::text[], 8.5, '{"poet":"Ozan Arif","poet_slug":"ozan-arif","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/bir-hayatin-gayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kimdi Bunlar?', 'kimdi-bunlar-kadir-eryildirim-7nxpb', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'İki şafak arasında umuttular

Kelleyi koltukta, hayatı kuşkuda unuttular

Kimdi bunlar? Kimdi bunlar? 

Yüreklerinde silahları pusudan pusuya koşanlardı

Namerde kalleşe aldırmadan şafaktan şafağa coşanlardı

Onlar göz bebeklerini büyüten ölümü aşanlardı? 

Kimdi bunlar? Kimdi bunlar? 

Özgürlüğe adanmış hayatlardı

Mayınlı tarlalarda cesetleri görerek

Bir gün gelecek ölümden ürkerek

Seher yeli soğukluğunda titreyerek

Bir ağızdan devrim türküleri söyleyerek

Yürüdüler dağlarda taşlarda ovalarda kentlerde

Ve 

Pusuya düştüler şafak vaktinde

sabah serinliğinde

güneşin alnında

gün kararmada ve kavuşmada, 

iki sevgili kuytu bir köşede sevişmede

                                                               iken

bu topraklar için savaştılar

Kimdi bunlar? Kimdi bunlar? 

Karadelik gibi çekerken intikam yüreklerini

Tedbirsiz yola düşmek bilmeyenler-di-

Mermisiz çıktılar meydana –silahsız-

           Ta ki sırtlarından vurulana

           Özgürlük ufuktan ışıyana

           Kız oğlan kız çocuklar umuda doğana

           Kavga ve hesaplaşmalar arasından demokrasi fışkırana 

                                                                                                  Dek

                                         Savaşanlardı

Kimdi bunlar? Kimdi bunlar?', 'İki şafak arasında umuttular Kelleyi koltukta, hayatı kuşkuda unuttular Kimdi bunlar? Kimdi bunlar?  Yüreklerinde silahları pusudan pusuya k...', ARRAY['Türk Edebiyatı','Şiir','Kadir Eryıldırım']::text[], 8.5, '{"poet":"Kadir Eryıldırım","poet_slug":"kadir-eryildirim","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/kimdi-bunlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yankı', 'yanki-mehmet-sahin-sunx3', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir sevgiyse bana sunduğun

Bunu tanımamazlıktan gelemem.

İçimdeki çocuğa seni anlattım.

Şimdi onun gözlerine kilitlenmiş, 

Kuş savaşı bir rüyasın.

Ben kendime düşeni aldım

Kalması gereken senini içinde.

Şimdi başlayan yağmurda 

Seni giyiniyorum.

Doğurmuyor hiçbir sokak seni, 

Hiç gezilmemiş bir yol yalanı gibi.', 'Bir sevgiyse bana sunduğun Bunu tanımamazlıktan gelemem. İçimdeki çocuğa seni anlattım. Şimdi onun gözlerine kilitlenmiş,  Kuş savaşı bir rü...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Şahin']::text[], 8.5, '{"poet":"Mehmet Şahin","poet_slug":"mehmet-sahin","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/yanki-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yavruma', 'yavruma-murat-cetin-8qk1c', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hissedebiliyorum yavrum.. 

Şu an; 

o minik ellerini çenene dayayıp 

pencere kenarında, 

her an çıkıp gelecekmişim gibi 

düşüncelerle bekliyorsun beni. 

Tıpkı 550 gündür yaptığın gibi.. 

Mektup yazmışsın bana, 

Açtığımda zarfı, o minicik kalbindeki 

devasa hasretin kapladı her yanı. 

Kaleminden özlemin damlamış 

kağıdın her satırına 

“yalnızlıktan sıkıldım, çabuk gel “ demişsin. 

A canım! yalnız değildin ki; 

Anlayabilecek yaşta olsaydın 

kalbinde bulacaktın 

giderken sana 18 ay yetecek kadar 

sevgi bıraktığımı.. 

Ve her gece nöbetimde 

zifiri karanlıkları delip 

buseler gönderirdim o gül yanaklarına 

sen mışıl mışıl uyurken. 

Eskiden; güzelliğine güzellik katan uykundayken 

saçlarını her okşayışımda tebessüm ederdin. 

Geçen gece 02-04 nöbetimde, 

yine okşadım saçlarını gülüm. 

Ve o an inan, 

her zaman ki gibi tebessüm ettiğini 

ve bir ara uyku sersemliğiyle 

boynuma sarıldığını hissettim. 

Göğsümdeki bastıramadığım heyecanımı 

yanağıma ansızın süzülen 

iki damla yaş hafifletmişti. 

O damlalardan birisi sana, 

diğeri de vefalı yarime idi. 

Benim için ise yoktu. 

Çünkü erkekler ağlamazdı. 

Ben de öyle yaptım. 

En azından yapmaya çalıştım. 

Evet, dedim ya çiçeğim 

yalnız değilsin. 

Ben, her gece yanı başındayım, 

bedenim burada olsa da. 

Aslında yüreğimi sana bırakmıştım, 

nemli gözlerle el sallarken arkamdan. 

O şirin avucundaydı. 

Sıkmıştın, sımsıkı tutmuştun, 

ilk kez yaşarken ayrılık acısını. 

Sabır göstergem sona vurmuştu o an 

içime akan göz yaşlarımı 

dışa taşırmamak için çabalarken. 

Neyse ki güzelim 

bunlar geride kaldı artık 

Bak! son saatlerindeyiz 

sonu mutlu bitecek kavuşmamızın. 

Hasreti, ayrılığı elinin tersiyle itmenin 

vakti geliyor yavaş yavaş, 

Gizli gizli, geceleri ağladın belki de 

Sakın ha sakın! gözünde olmasın yaş 

beni karşında görünce 

kollarını açıp koştuğunda 

Sil artık sil! yüzünde olmasın yaş, 

o ıslak, kömür karası gözlerine dayanamaz 

bu hasret yorgunu... 

Hayırlısıyla bitiyor ya 

bu ayrılığın sonu 

Dualarım Mevla’ya... 

Teşekkürlerim Mevla’ya... 

Artık ; baban yanında olacak 

tıpkı diğer çocukların babaları gibi, 

Ve artık soramayacaksın annene 

Neden? Niçin yok? diye 

baba elinden tutmuş bir çocuğu göstererek... 

Ve yine soramayacaksın 

“Orayı çok mu sevdi de gelmiyor? ” diye 

Ah! bir anlayabilsen yavrum, 

Vatan borcunun ne olduğunu 

Ve bu vatan var oldukça 

ödendiğini ve ödeneceğini 

Sayılı günlerin diyetinin de 

ayrılık ve hasret olduğunu.... 

.. 

Neyse, 

Allah’ın izniyle arefesindeyiz ya 

kavuşmanın. 

Şükürlerim Mevla’ya...

..... 

  Ve darısı, asker ocağındaki 

gurbet vurgunu babalara.... 

Selam, sabır ve dua ile....

........04.05.2000', 'Hissedebiliyorum yavrum..  Şu an;  o minik ellerini çenene dayayıp  pencere kenarında,  her an çıkıp gelecekmişim gibi  düşüncelerle bekliyo...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":91,"source_url":"https://www.antoloji.com/yavruma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yar', 'yar-murat-cetin-t9ldp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yalnızlık narından

Korktuğum yarından

Uçurum kenarından

Kurtaransın yar..

Sevgi eksiğimde

Gurbet kesiğimde

Bir örtü isteğimde

Sen, saransın yar..

Kaderin ağına

Soluna ve sağına

Mutluluk durağına

Sen, varansın yar..

Çiçekler gelse dile

Güneşin doğuşu ile

Rüyalarımda bile

Cana canansın yar..

Bakış attığımda

Canıma kattığımda

Elini tuttuğumda

Aşka kanansın yar..

Kaderimin barışığı

Gönlümün tek aşığı

Vurunca yüzüne ay ışığı

Beni sanansın yar..

Sensizken üzülünce

Gözyaşım süzülünce

Hayalde bile ölünce

Canı yanansın yar..

Koşarak sana geldiğim

Sensiz olmaz dediğim

Sen ki, benim sevdiğim

Canımda kansın yar..

Gözlerin güzel

Sözlerin güzel

Özlemin güzel

Güzel yaransın yar..

Sen, benim özlemim

Yokluğun elemim

Dünyadaki gözlemim

İlk ve son sevdiğimsin

Ve öyle KALACAKSIN..

...27.03.2000', 'Yalnızlık narından Korktuğum yarından Uçurum kenarından Kurtaransın yar.. Sevgi eksiğimde Gurbet kesiğimde Bir örtü isteğimde Sen, saransın ...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/yar-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ey Güzelim', 'ey-guzelim-murat-cetin-0s8fn', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Güzele gönül verenim.

Yoluna güller serenim

Sonu olmaz aşkı yerenim

Sevdiğimsin sen ey güzelim.

Olsan da evli ve çocuk sahibi

Ferman dinlemiyor gönül katibi

Seni görmeme engel olsa da kar, tipi

Sevdiğimsin sen ey güzelim.

Birleşemese de bedenler, kalpler bir ya

Bitmesini istemediğim sanki bir rüya

Zamansız karşılaştırdı bizi zalim dünya

Sevdiğimsin sen ey güzelim.

Seni tanıdım uykudan oldum

Yaprak misali sarardım soldum

Yine de mutluluğu sende buldum

Sevdiğimsin sen ey güzelim.

Doğru değil aslında bu yaptığımız

Mantık yolundan saptığımız

Ahirette ne der Taptığımız

Sevdiğimsin sen ey güzelim.

Aslında sen bana yasak meyvesin

Dur, hemen kırılmasın hevesin

Her zaman ensemde nefesin

Sevdiğimsin sen ey güzelim.

Çaresi sensin şu kanayan yaramın

Olayım her an düğünün, bayramın

Anla artık anla, sana hayranım

Sevdiğimsin sen ey güzelim

Saçıma aklar düşse ne çıkar

Elalem nereye kadar can sıkar

Ayrılık bile bu aşktan bıkar

Sevdiğimsin sen ey güzelim.

İnmese bir lokma mideme, sevgin doyurur

Sussa da dilin, sevdanı gözün duyurur

Elinden geleni yapsa da şu gurur

Sevdiğimsin sen ey güzelim.

Bilmezdim sevmenin güzel olduğunu

Sevince kalbe huzur dolduğunu

Benim sende, senin bende yok olduğunu

Sevdiğimsin sen ey güzelim.

Yaşamın güzelliğini sözünde buldum

Sevgi dolu kalbini gözünde buldum

Benim için yaşadığını, özünde buldum.

Sevdiğimsin sen ey güzelim.

Senle gidip senle geliyorum

Çok garip bu aşk, biliyorum

Elimde değil seni çok seviyorum

Sevdiğimsin sen ey güzelim.

Sonu görünmez bir yola girdik

Uyanıversek rüyadan, kendimize gelirdik

Neden, niçin yanlış yaptık, bilirdik

Ama yine de

Sevdiğimsin sen ey güzelim.

Bir araya hiç gelmesekte

Felekten hep sille yesekte

Olmayacak duaya amin desekte

Yine de, yine de, inadına

Sevdiğimsin sen ey güzelim

......nisan 2000', 'Güzele gönül verenim. Yoluna güller serenim Sonu olmaz aşkı yerenim Sevdiğimsin sen ey güzelim. Olsan da evli ve çocuk sahibi Ferman dinlemi...', ARRAY['Türk Edebiyatı','Şiir','Murat Çetin']::text[], 8.5, '{"poet":"Murat Çetin","poet_slug":"murat-cetin","theme":"Türk Şiiri","is_hero":false,"total_lines":59,"source_url":"https://www.antoloji.com/ey-guzelim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk', 'ask-ahmet-i-ldeniz-pktgn', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ruhumun deriliklerinde

Aşktır sevgiyi ölümsüzleştiren 

Senin ölümsuz inadın

Vijdansız beni öldüren 

Neden suskunsun

Neden konuşmuyorsun

Ben seni ölümüne sevdim 

Ben seni yüreme gömdüm

Yanlız gülen yüzünü özledim

Yanlız kadife sesini istedim

Ben senden BİTANEM

Yanlız evimin KADINI OLMANI İSTEDİM', 'Ruhumun deriliklerinde Aşktır sevgiyi ölümsüzleştiren  Senin ölümsuz inadın Vijdansız beni öldüren  Neden suskunsun Neden konuşmuyorsun Ben ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet İldeniz']::text[], 8.5, '{"poet":"Ahmet İldeniz","poet_slug":"ahmet-i-ldeniz","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/ask-60-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hatırlarım Seni', 'hatirlarim-seni-aziz-bulut-klyzl', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hatırlarım seni, her güneş batışında

Hatırlarım seni, her yıldız kayışında

Hatırlarım seni, bir gül koklasamda

Hatırlarım seni, her yağmur yağışında

Senin ile geçen bir anı

Seni, unutmak mümkün mü? 

Kalbimde yaşatıyorum her anı

Sensiz yaşamak mümkün mü? 

Daha dün el ele geziyorduk

Gönül gönüle, aşk sarhoşuyduk

Ne oldu aşkımıza, sevgimize

Ne sözüne, ne gülüşüne doyduk

16-09-2000', 'Hatırlarım seni, her güneş batışında Hatırlarım seni, her yıldız kayışında Hatırlarım seni, bir gül koklasamda Hatırlarım seni, her yağmur y...', ARRAY['Türk Edebiyatı','Şiir','Aziz Bulut']::text[], 8.5, '{"poet":"Aziz Bulut","poet_slug":"aziz-bulut","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/hatirlarim-seni-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ömrümü Böldüm Şiire', 'omrumu-boldum-siire-bulent-ozcan-brbyv', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yaktım denizlerimi

Göğe döktüm yüzümü

Ömrümü böldüm şiire

Kuşlar sürdü izimi...

Yalnızım darmadağın

Şiir ardında dağın.

Yazık ki gece bile

Anlamadı hüznümü...

Eylül 2000, 

Hucknall-Nottinghamshire/İngiltere', 'Yaktım denizlerimi Göğe döktüm yüzümü Ömrümü böldüm şiire Kuşlar sürdü izimi... Yalnızım darmadağın Şiir ardında dağın. Yazık ki gece bile A...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/omrumu-boldum-siire-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özgünlük', 'ozgunluk-bulent-ozcan-445ci', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', '-Yola çıkan ozana.

Göğün her durağında dur

Hüznün her sokağından geç

Göğe yağan kuşların sesine kulak ver

Şiirin tutuşan yüreğini tanı

Zamanın yalansız düşünü kur

Ayaklandır içindeki ormanı

Kapıl rüzgârın uğultusuna

Ayna tut sesinin aynasına

Ozan dediğin kendi olmalı

Benzeme başkasına

Kendi evrenini yarat: Kendine ak

Çağlasın yüreğindeki şiirden ırmak

Işıyacak şiirin göreceksin bak...

21 Temmuz 2000, 

Hucknall-Nottinghamshire/İngiltere', '-Yola çıkan ozana. Göğün her durağında dur Hüznün her sokağından geç Göğe yağan kuşların sesine kulak ver Şiirin tutuşan yüreğini tanı Zaman...', ARRAY['Türk Edebiyatı','Şiir','Bülent Özcan']::text[], 8.5, '{"poet":"Bülent Özcan","poet_slug":"bulent-ozcan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/ozgunluk-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Siyah Koku', 'siyah-koku-sair-khara-lpcya', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ölüm yalnızsa kokar

ve mezar başındaki çiçeklerin bununla alakası yoktur.

be(n) den çürümeden uzaklaşır ruh

ruh, DUAL, yalnızlık..

aynıl; 

söz konusu tek duygudur sıla, 

cezaevinde bayram sabahı

durmadan gelir ve gider çocuklar

AğlatıLIR, AğlatıLIR, alır-götürülür.

hayırr! 

hayır, ölüm değildir kokan

                                          (mezar ziyareti, UCA dedemin)', 'Ölüm yalnızsa kokar ve mezar başındaki çiçeklerin bununla alakası yoktur. be(n) den çürümeden uzaklaşır ruh ruh, DUAL, yalnızlık.. aynıl;  s...', ARRAY['Türk Edebiyatı','Şiir','Şair Khara']::text[], 8.5, '{"poet":"Şair Khara","poet_slug":"sair-khara","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/siyah-koku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sfenks', 'sfenks-sair-khara-f8at9', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Sahtiyandır sevginin tensel dokunuşları

Mitoslarda ruh bulan aşk, 

ın sfeknsi bu anlarda gizil

ve ütopyasında dudakların tuz tadı', 'Sahtiyandır sevginin tensel dokunuşları Mitoslarda ruh bulan aşk,  ın sfeknsi bu anlarda gizil ve ütopyasında dudakların tuz tadı...', ARRAY['Türk Edebiyatı','Şiir','Şair Khara']::text[], 8.5, '{"poet":"Şair Khara","poet_slug":"sair-khara","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/sfenks-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Meleksel İhanet', 'meleksel-i-hanet-sair-khara-xjb1k', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zamanın geçimsizliğine

lanet okur gibi

yine henüz uyanmamış bir şehre üfledim

sigaramın son dumanını.

boş bir evin balkonundan

göremediğim insanların kelimelerini çaldım.

alakasız bir hüzünle

afrikasal bir törende yaşadım, 

şarap tadında özgürlüğü

ve yaşatmak için öldürdüm tanrıyı.

günah sin, li geceden

bütün şehrin uykusunu kıskandığım

sabaha karşısına doğru

meleksel bir ihaneti oynadım

yalnız kelimeler vardı..', 'zamanın geçimsizliğine lanet okur gibi yine henüz uyanmamış bir şehre üfledim sigaramın son dumanını. boş bir evin balkonundan göremediğim i...', ARRAY['Türk Edebiyatı','Şiir','Şair Khara']::text[], 8.5, '{"poet":"Şair Khara","poet_slug":"sair-khara","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/meleksel-ihanet-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sıla', 'sila-sair-khara-1krd2', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'gökyüzüyle sürtüşen duvarlar

