INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güzel Söze Kanmayı Öğrendim', 'bir-guzel-soze-kanmayi-ogrendim-umit-yasar-serifoglu-xx41a', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir tutam sevgiyi paylaşmayı öğrendim.

