INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah İstanbul', 'ah-i-stanbul-mustafa-nomal-58ezy', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Vallahi özledim be ister inan ister inanma

Buralar bana göre değil bize göre hiç değil 

Sanki bir esirim 

Sanki bir sürgünüm

Sanki mapushanedeyim 

Ağlasam ne fayda 

Gülsem ne fayda 

Şöyle alıpta başını göğsüne yaslayıp 

Ne ağlayacağın, nede güleceğin bir dostun var.

Gurbet ocağı dedikleri burası herhal

Sıla dedikleri, Hasret dedikler burası herhal

Olmuyor be dostum 

Hiç bişeyin yerini tutmuyor

Bu koca şehir...! 

Anam, babam, eşim, dostum

Hepsi artık geride kaldı, 

Dönebilirmiyim bir daha, 

Dönermiyim bilmiyorum...! 

ANLA BE BENİ ALLAHSIZ KİTAPSIZ KOCA ŞEHİR İSTEMİYORUM SENİ, 

LÂNET OLSUN SANA BIRAK ARTIK YAKAMI KOCA ŞEHİR............!', 'Vallahi özledim be ister inan ister inanma Buralar bana göre değil bize göre hiç değil  Sanki bir esirim  Sanki bir sürgünüm Sanki mapushane...', ARRAY['Türk Edebiyatı','Şiir','Mustafa Nomal']::text[], 8.5, '{"poet":"Mustafa Nomal","poet_slug":"mustafa-nomal","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/ah-istanbul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Toprak', 'toprak-turhan-torun-guven-icxtu', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'yaşamın en ince yeridir ellerin

çiçek toplayan, öykü yazan ellerin.

armağan ettiğim gülleri tutan

sevgimin yansıyan yeri

uzat yanaklarından bir gül alayım.

yaşamın en ince yeridir ellerin

gül ektiğim küt saçların

ve çiçek açan yüreğin

sevgimin yansıdığı kutsal yerlerin 

uzat uzat öpeyim.', 'yaşamın en ince yeridir ellerin çiçek toplayan, öykü yazan ellerin. armağan ettiğim gülleri tutan sevgimin yansıyan yeri uzat yanaklarından ...', ARRAY['Türk Edebiyatı','Şiir','Turhan Torun Güven']::text[], 8.5, '{"poet":"Turhan Torun Güven","poet_slug":"turhan-torun-guven","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/toprak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lalim', 'lalim-hatice-korkmaz-bnj2f', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Suskunluğa tek tanık

''''Mevcudat''''tı.

Her şey

Ufak bir şehadet ile başladı.

Gönlün sükûtu, 

Kalp ağrıları...

Ballar akmıyordu artık

o cânım dilden

Orada hazan kaldı

Zavallı lâlim 

Bîçâreliklere daldı.

Ne olurdu? 

yalnızca bir kez

dökebilseydi dillerini

bârân olup

dudaktan boşanırcasına.

Kimseye minneti kalmazdı.

Hayfı da olmazdı.

Ah lâlim

Bir teşekkürün kupkuru kaldığı yerde

Islak dualarım vardı. 

Gözyaşları ile yıkanan, 

tertemiz

akardı.

Haykırabilseydi suskunluğunu

Avazı çıktığı kadar

Coşardı

Lâlim, 

boynu büküğüm.

Yetimken, 

öksüzlüğüm.

Sedası sığmazdı

gökyüzüne.

Yaşım yanında

onunkiler 

az kalırdı.

Ve...

Bütün

harfler, 

cümleler 

toplanıp gelse

lâlimi anlatamazdı

Bir paragrafın dallarına 

tutunamazdı.

Ilık rüzgara inat

koşamazdı

Ilık rüzgarlar, 

dalgınlığımızdı.

Lâlim! 

Senin ve benim

İkimizin...

Aynı noktada düğümlenişimiz

Fırtınadan haberi olmayan, 

Ilık rüzgardı.

Böyle bir noktaydı.

Ne olurdu? 

Bir kez, 

yalnızca bir kez

dökülseydi dudaktan...

Ahh 

Lâlim! 

Bir teşekkürün kupkuru kaldığı yerde

Islak dualarım vardı

Gözyaşları ile yıkanan, 

tertemiz, 

ıslak dualar...

En suskun haykırış için akardı.', 'Suskunluğa tek tanık ''''Mevcudat''''tı. Her şey Ufak bir şehadet ile başladı. Gönlün sükûtu,  Kalp ağrıları... Ballar akmıyordu artık o cânım d...', ARRAY['Türk Edebiyatı','Şiir','Hatice Korkmaz']::text[], 8.5, '{"poet":"Hatice Korkmaz","poet_slug":"hatice-korkmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":67,"source_url":"https://www.antoloji.com/lalim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk Diyarı', 'mutluluk-diyari-zerrin-koral-bjhcf', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'mutluluk diyarı şu beni sarıp sarmalayan kolların

hiç açma! ! ! 

yaşayacaksam böyle yaşamalıyım...', 'mutluluk diyarı şu beni sarıp sarmalayan kolların hiç açma! ! !  yaşayacaksam böyle yaşamalıyım......', ARRAY['Türk Edebiyatı','Şiir','Zerrin Koral']::text[], 8.5, '{"poet":"Zerrin Koral","poet_slug":"zerrin-koral","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/mutluluk-diyari-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cânan Yurdu', 'c-nan-yurdu-mehmet-akif-ersoy-sjfzs', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Eyvâh, ıssız diyâr-ı dilber... 

Her hatvesi bir mezâr-ı muğber! 

Uçmuş da bakındığım terâne, 

Kalmış sessiz bir âşiyâne. 

Yer yer medfun durur emeller... 

Gûyâ ki kıyâm-ı haşri bekler! 

Yâ Rab! Niye böyle bir yığın hâk 

Olmuş yatıyor o buk’a-i pâk? 

Yâ Rab, ne için o lem’a nâbûd? 

Yâ Rab, ne için bu sâye memdûd? 

Yâ Rab, ne demek harîm-i cânan 

Üstünde bu perde perde hicran? 

Lâkin görünen kimin hayâli? 

Cânan gibi tıpkı yâl ü bâli... 

Gîsû-yi siyâh-ı târumârı, 

Altında cebîn-i lem’a-dârı, 

Zulmetler içinde subh-i mahmûr; 

Yâ gözbebeğinde nazra-i nûr; 

Yâ ebr-i bahâr içinde cevvâl 

Bâran şeklinde dürr-i seyyâl; 

Yâ sînede her zaman coşan yâd, 

Yâ kayd-i bedende rûh-i âzâd. 

Ey tayf-ı nigeh-firîbi yârın, 

Olmaz mı bir ân için karârın? 

Heyhât, serâb-ı şavka döndün... 

Karşımda parıldamanla söndün! 

Kimden sorayım ki nerde dilber? 

Makber gibi samt içinde her yer. 

Cânan! Cânan! ... dedim, arandım... 

«Bir aks-i nidâ» dedikçe, yandım! 

Yâ Rab, niye hem sağır, hem ebkem,

Dağlar, dereler, bütün şu âlem? 

Ey sevdiğimin sevimli yurdu, 

Hâlin bana şimdi pek dokundu! 

Aç sîneni; yâd-ı nükhetinden 

Bir şemmeye kàilim bugün ben. 

Bir vakt o şemîm-i nâz-perver 

Tâ subha kadar yanımda bekler, 

-Ümmîde verip bekà sabûhu- 

Sermest-i safâ ederdi rûhu. 

Heyhât o nesîm-i sâf şimdi 

Nâzan nâzan semâya gitti. 

Ey lâne-i târumâr söyle, 

Cânan sana artık inmiyor mu? 

Ey mâtem-i pâyidâr söyle, 

Sâhandaki nevha dinmiyor mu? 

Ey ebr-i semâ-güzîn-i seyyâr, 

Yâdında mıdır o nazlı reftâr? 

Ey darbe-i bâda karşı, ra’şân, 

İnşâd-ı enîn eden nihâlân! 

Bir şi’r-i revân olup da cânan, 

Geçmez mi bu gölgeden hırâman? 

Ey dilber-i mihriban, zuhûr et! 

Ömrüm gibi ansızın mürûr et! 

Yâ kalb-i fezâya bir hutûr et: 

Âfâkımı lem’a lem’a nûr et. 

Bin nevha-i cân içimde pür-cûş, 

Geldim bu garîb yurda, medhûş. 

Feryâdımı yok mu eyleyen gûş? 

Yâ Rab, bu nasıl cihân-ı hâmûş: 

Bir «yok! » diyecek sadâ da yokmuş! ...', 'Eyvâh, ıssız diyâr-ı dilber...  Her hatvesi bir mezâr-ı muğber!  Uçmuş da bakındığım terâne,  Kalmış sessiz bir âşiyâne.  Yer yer medfun dur...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":61,"source_url":"https://www.antoloji.com/canan-yurdu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fâtih Câmii', 'f-tih-c-mii-mehmet-akif-ersoy-v1tmt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Yatarken yerde ilhadıyla haşr olmuş sefil efkar,

Yanp edvan yükselmiş bu müdhiş heykel-i ikrar,

Siyeh-reng-i dalalet bir bulut şeklinde maziler,

Civarından kaçar, bulmaksızın bir lahza istikrar; 

Ziya-riz-i hakikat bir seher tavrında müstakbel,

Gelir fevkinden eyler sermedi binlerce nur! sar.

Deraguş etmek ister nazenin-i bezm-i lahfitu:

Kol açmış her menarı sanki bir ümmid-i cür''etkar! 

O revzenler, nazariardan nihan didara müstağrak,

Birer gözdür ki sıyrılmış önünden perde-i esrar.

Bu kudsi ma''bedin üstünde taban fevc fevc ervah,

Bu ulvi ku b benin altında efişan m eve mevc en var.

Tecessüd eylemiş güya ki subhun ruh-i ıİıahmuru; 

Semadan yahud inmiş hake, Sina-reng olup didar! 

Tabiat perde-pfiş-i zulmet olmuş, habe dalmışken,

O; güya kalb-i nuranisidir leylin, durur bidar.

Evet bir kalbdir, bir kalb-i cuşacuş-i aşıktır,

Ki cevfinden demadem yükselir bin nale-i ezkar.

Nümayan cebhesinden Sadr-ı İslam''ın mealisi:

O sadnn feyz-i eniasıyle güya bir yığın ahcar,

Kıyametmiş de, yükselmiş de bir timsal-i nur olmuş.

Nasıl timsal-i nur olmaz? Şu pek sakin duran divar,

Asırlar geçti hala batılın piş-i hücfimunda,

Göğüs germektedir, bir kerre olsun olmadan bizar.

Bu bir ma''bed değil, Ma''bfid''a yükselmiş ibadettir; 

Bu bir manzar değil, didara vasıl mevkib-i enzar. 

Semadan inmemiştir, şüphesiz, lakin semavidir:

Zemini olmayan bir cilve-i feyyazı havidir.

* * *

Bir infilak-ı safadır ki yar-ı canımdır,

Sabahı pek severim, en güzel zamanımdır.

Rida-yı leyli henüz açmaınıştı dest-i sema; 

Saba dahab-ı sükfindan ayılmamıştı daha,

Feza-yı rfihda aksetti, es-sala-perdaz

Müezzinin dem-i mahmfiru, bir hazin avaz.

İçimde cfiş ederek lücce lücce istiğrak,

Ezanı beklemez oldum; açılmadan afak,

Zalamı sineye çekmiş yatan sokaklardan

Kemal-ivecd ile geçtim. Önümde bir meydan

Göründü; Fatih'' e gelmiştim anladım, azıcık

Gidince, ma''bede baktım ki bekliyor uyanık! 

Sokuldum artık onun sine-i münevverine,

Oturdum öndeki maksfireciklerin birine.

Feza-yı ma''bedin encüm-nüma meşa''ilini,

O lem''a lem''a diziimiş ziya kavafilini

Görünce geldi çocukluk zamanlanın yada...

Neler düşündüm o sa''atte bilseniz orada! 

Sekiz yaşında kadardım. Babam gelir: "Bu gece,

Sizinle cami'' e gitsek çocuklar erkence.

Giderseniz gelin amma namazda uslu durun,

Meramınız yaramazlıksa işte ev, oturun! "

Deyip alırdı beraber benimle kardeşimi.

Namaza durdu mu, haliyle koyverir peşimi,

Dalar giderdi. Ben artık kalınca azade,

N e aşıkane koşardım has ır lar üstünde! 

Hayal otuz sene evvelki hali pişimden

Geçirdi, başladım artık yanımda görmeye ben: ·

Beyaz sarıklı, temiz, yaşça elli beş ancak; 

Vücudu zinde, fakat saç, sakal ziyadece ak; 

Mehib yüzlü bir adem: Kılar edeble namaz; 

Yanında bir küçücek kızcağızia pek yaramaz

Yeşil s arıklı bir oğlan ki başta püskül yok.

imamesinde fesin bağlı sade bir boncuk! 

Sarık hemen bozulur, sonra şöyle bir dolanır; 

Biraz geçer, yine rayet misali dalgalanır! 

Koşar koşar duramaz, akıbet denir "amm"

Namaz biter. O zaman kalkarak o pir-i güzin,

Alır çocuklar, oğlan fener çeker önde,

Gelir düşer eve yorgun, dalar pek asilde

Derin bir uykuya...

Derken bu hatırat ı latif

Çekildi aslına, artık haklkatin o kesif

Likası başladı karşımda cilve eylemeye; 

. Zaman da kalmadı zaten hayali dinlemeye:

Sağım, sol um, önüm, arkarn huşfi'' a müstağrak

Zılal i ade m iken, bir s ada bülend olarak,

O kainat ı huzfi''u yerinden oynattı; 

Feza yı mahşere döndürdü gitti eb''adı! 

Suffif ayakta müselsel cibal-i velveledar

Gibiydi. Her birisinden duyuldu sine-fikar,

Birer enin-i tazarru; birer niyaz ı hazm,

Ki kalb-i rahmeti sızlattı şüphesiz o enin! 

Eğildi sonra o dağlar huzur-i izzette; 

Göründü sonra o dağlar zemin-i haşyette! 

İnayetiyle Huda kaldırınca her birini,

Semaya doğru o dağlar da açtı ellerini.

O anda koptu yüreklerden öyle bir feryad,

Ki ruhum eyleyecek taebed o dehşeti yad.

Kesildi bir aralık inleyen hazin av az...

N e oldu Arş ''a kadar yükselen o s uz ü güdaz? 

O cu ş içindeki iman? 

Evet, huruş ederek işte rahmet İ Subbfih,

Bütün yüreklere serpildi kubbeden bir n1h:

Ruh-i itminan.', 'Yatarken yerde ilhadıyla haşr olmuş sefil efkar, Yanp edvan yükselmiş bu müdhiş heykel-i ikrar, Siyeh-reng-i dalalet bir bulut şeklinde mazi...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Akif Ersoy']::text[], 8.5, '{"poet":"Mehmet Akif Ersoy","poet_slug":"mehmet-akif-ersoy","theme":"Türk Şiiri","is_hero":false,"total_lines":94,"source_url":"https://www.antoloji.com/fatih-camii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşka Çiğ Yağdı', 'aska-cig-yagdi-levent-orman-o1usl', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Yağmur yağar, saçlarım filizlenir

bir yıldız düşer omuzlarıma.

Islık çalar ıslanır, 

şarkılarımı söyler geçerim kapından.

Camlların buğusundan ve yağmurun

kokusundan tanırlar beni, bilirler.

En iyi yalanlarını alırım onların, 

adresler sorarım kimseler oturmaz orada.

Ve bilki en kederli yanımla çaresiz, 

düşerim kıyılarına her yağmurda.', 'Yağmur yağar, saçlarım filizlenir bir yıldız düşer omuzlarıma. Islık çalar ıslanır,  şarkılarımı söyler geçerim kapından. Camlların buğusund...', ARRAY['Türk Edebiyatı','Şiir','Levent Orman']::text[], 8.5, '{"poet":"Levent Orman","poet_slug":"levent-orman","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aska-cig-yagdi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eksik Güneşler', 'eksik-gunesler-necati-cumali-g18gd', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kaç günümüz varsa şunun şurasında

O kadar güneşimiz var

Her günlük hakkımızdır mutluluk

Anla

Dün bugün eksilen güneşler

Ödenmez yarınla', 'Kaç günümüz varsa şunun şurasında O kadar güneşimiz var Her günlük hakkımızdır mutluluk Anla Dün bugün eksilen güneşler Ödenmez yarınla...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumalı']::text[], 8.5, '{"poet":"Necati Cumalı","poet_slug":"necati-cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/eksik-gunesler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıplak', 'ciplak-necati-cumali-13hxw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bereketli göğüslerin

Dudakların aşkla ıslak

Cennetten kovulan ırmak

Yatağımda çırılçıplak

Her gece gürül gürül ak

Yıkık yönlerimi götür

Umutsuzluğumu yıka

Yarına beni değiştir.

Geldiğin yerlerim yeşil

Gittiğin yerlerim kurak', 'Bereketli göğüslerin Dudakların aşkla ıslak Cennetten kovulan ırmak Yatağımda çırılçıplak Her gece gürül gürül ak Yıkık yönlerimi götür Umut...', ARRAY['Türk Edebiyatı','Şiir','Necati Cumalı']::text[], 8.5, '{"poet":"Necati Cumalı","poet_slug":"necati-cumali","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ciplak-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Farzet ki', 'farzet-ki-muzaffer-gezer-0n7j7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Farzet ki bir ormanda bir ağacın altındayım

Elim kolum bağlanmış varılmaz yollardayım

Diz çökmüş mangalar namlunun ucundayım

Farzet maphushanede küçük bir hücredeyim

Sesim varmaz öteye sessizlik içindeyim

Işık vurmaz yüzüme karanlık düşlerdeyim

Farzet ıssız bir yolda tek başıma berduşum

Yağmur çiselemekte sırılsıklam olmuşum

Elimde dert şişesi zilzurna sarhoşum

İşte böyle sesssizim, işte böyle çaresiz

İşte böyle ümitsiz gelemiyorum sana', 'Farzet ki bir ormanda bir ağacın altındayım Elim kolum bağlanmış varılmaz yollardayım Diz çökmüş mangalar namlunun ucundayım Farzet maphusha...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/farzet-ki-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gün Gelir de', 'gun-gelir-de-muzaffer-gezer-jnqbm', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yitmeye görsün gökyüzünde ışık

Yıldızın kaymasın bir kere

Ne çiçeklerin rengi vardır artık

Ne de kemanlarda melodi

Şarap kana bulanır

Kan yüzüne

Yüzün karanlığa

Saçlarında rüzgarın elleri

Ellerinse yalnızlıklarda

Kaybolmaya görsün

Göğsünün sol köşesindeki

O esrarengiz cevher

Dudaklarında küçücük titreşimler

Gün geceye karışır

Gece yüreğine

Dostluklar tükenmiş

Sevgiler yitirilmiş

Can çekişen bedeninle

Yalnız kalırsın', 'Yitmeye görsün gökyüzünde ışık Yıldızın kaymasın bir kere Ne çiçeklerin rengi vardır artık Ne de kemanlarda melodi Şarap kana bulanır Kan yü...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/gun-gelir-de-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Üstüne', 'sevgi-ustune-muzaffer-gezer-lypwf', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İki kere iki dört eder''le

Açıklanamaz sevgi

Ya da E eşittir

M çarpı C kare ile

Sensizliğin acısı

Anlıyabilir misin kosinüs''le

Evladını yitirmiş bir annenin feryadını

Bir merminin hızından farklı bir şeydir ağlamak

Acımasızlıktan çakıl taşları

İhannetten kum

Ve öfkeden çimentoyla

Beton atmışlar üzerimize

Ölüm uykusuna yatmışız

O.K. marka prezervatifler

Şişme kadınlarla

Ve protez penislerle

Çevrilmiş dört yanımız

Bir gül için hizmet ederken

Katlanırkan binlerce dikene

Şimdi kendimize yabancılaşmışız

Ne elimizdeki su tabancası

Ne de biz dünkü çocuklarız

Farkında olmadan büyüdüğümüzü

Büyütmüşüz yüreğimizde korkuyu

Aynada görüp kendisini aşık olmuş kimisi

Kimisi masallardaki Dev''e benzetip

Korkmuş kendisinden

Dedim ya

Farkında olmadan büyüdüğümüzü

Büyütmüşüz yüreğimizde korkuyu

Büyütmüşüz öfkeyi

Sevgisizliği sulamışız gözyaşlarımızla

Bilmem kimin koyduğu kuralları

Ayet-i kerime gibi  sindirmişiz içimize

Hem de ne adına

Sevgi adına ihaneti

Özgürlük adına tutsaklığı serpmişiz yeryüzüne

Bilgiçlik taslayıp sonra

Bilmezken kendimizi bile

O en güzel ağuyu

Bilimsel formüllerle

Kara kara mürekkeplerle

Dökmüşüz kitap sayfalarına

Bir amfide ders anlatır gibi

Burcunu okur gibi

Hiç söylenmemiş yalanları söyler gibi

Tecrit etmişiz sevgiyi bedenimizden

Utanmadan sıkılmadan

Bir güne  mahkum etmişiz anlayacağın

Yeter be...

Şimdi kalkmanın tam vaktidir

Binlerce yıl süren uykundan

Üstüne serpilen ölü toprağını silkele at

Üzerine çevrili objektiflere

Projektörlere

Namlulara inat

Bir yere çarpma korkusu taşımadan yüreğinde

Koş koşabildiğince

Ölüm kaçacak

Haykır....''YERYÜZÜ AŞKINYÜZÜ OLACAK''', 'İki kere iki dört eder''le Açıklanamaz sevgi Ya da E eşittir M çarpı C kare ile Sensizliğin acısı Anlıyabilir misin kosinüs''le Evladını yitir...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":60,"source_url":"https://www.antoloji.com/sevgi-ustune-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ucuz Figüranlara', 'ucuz-figuranlara-muzaffer-gezer-39ypm', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Kendi topraklarımızda el gibi

Çalışıp didinmişiz durmadan

Ekmeğimiz çalınmış ölüme yollanmışız

Hasret kalmışız vatana vatan içinde

Biz ki...Bir parça buğdaydan dünya yaratanlar

Biz ki...Zinciri gül, acıyı bal, şiiri kavga

Kavgayı şiir yapanlar

Hep başkalarının yazdığı senaryolarda

Hep başkalarının yönettiği oyunlarda

Ucuz figüranlık yapmışız

Çıkmayacaksın oyunun dışına

Rolünü iyi yapacaksın

Kan tükürüp kızılcık içtim diyeceksin

Halinden memnun görünüp

Ürkütmeyeceksin kurbağaları

Haaa...birde soru sormayacaksın

Neden niçin nasıl

Sileceksin lugatından bu kelimeleri

Anlayacağın yap rolünü çık git

Müstehcen fikirlere de kaptırma kendiniNe o '' koltuk'' mu dedin

MÜSTEHCEN

Çünkü kadın da oturur erkek de

Hem de en müstehcen uzuvlarıyla

Yamalı donlu kıçlarıyla

Kıçla don müstehcen

''Yamalı'' kelimesi bile tehlike, gomonistlik

Attırmayacaksın beylerin tepelerini

Yoksa..

İşte çarmıh

İşte falaka

Dekor kostüm jest replik mimik

Oh ne ala

Hep onlar için oynayan biz

Hiçbir şey anlamadan koyun gibi

Ve bir eleştirmen edasıyla

Çelişkiler içinde alık alık seyreden yine biz

Hayır arkadaş hayır..

Sen yazacaksın bundan böyle oyunu

Sen oynatacaksın kendini

Ucuz figüranlıklarla değil sarsılmaz ustalıklarla

, En güzel kostümlerini giyeceksin

Mavi beyaz gri önlükleri

Şalvarları çiçekli yelekleri

Mavi mavi tulumlarını emeğin

Üniformalarını barışın

Ve 

Bir tirat çekeceksin sevda üstüne

Aydınlığa bezenecek sahne

Karanfillerle papatyalarla

Ama ucuz figüranlıklarla değil sarsılmaz ustalıklarla  Nasıl direndiysen umutsuzluğa karanlığa yine öyle

Nasıl ürettiysen hayatı yeni baştan

Yine sen yöneteceksin

Ve...

Prömierinde dostluğun ve barışın

Son gecesinde lanet karanlığın

Bu sefer sen haykıracaksın.........

PERDE...........!', 'Kendi topraklarımızda el gibi Çalışıp didinmişiz durmadan Ekmeğimiz çalınmış ölüme yollanmışız Hasret kalmışız vatana vatan içinde Biz ki......', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Gezer']::text[], 8.5, '{"poet":"Muzaffer Gezer","poet_slug":"muzaffer-gezer","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/ucuz-figuranlara-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Miras', 'miras-deniz-sonmez-tuoqd', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'yalnızlık bir miras

sevgi de

öfke de

mirasa konmaksa

bize kalan

en eski miras', 'yalnızlık bir miras sevgi de öfke de mirasa konmaksa bize kalan en eski miras...', ARRAY['Türk Edebiyatı','Şiir','Deniz Sönmez']::text[], 8.5, '{"poet":"Deniz Sönmez","poet_slug":"deniz-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/miras-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bin Yılın Aşkı', 'bin-yilin-aski-ozan-kaymak-365of', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bu; 

Bin yılın son şiiri, 

Okudukların; 

Bir yürekte alevlenen, 

Gözlerinde esen, 

Asansörle özleşen, 

Buna rağmen gizlenen, 

Söylenemeyen, 

Çaresi ''sen'' olan bir aşkın, 

Bir kağıtta görünen halidir.

Duydukların; 

''Millenium'' çığlıkları arasında bir kalbin, 

''Gel'' diye seslenen çağrısıdır.

Başlamaktan yorulmamış bir nefesin, 

Elinden tutup seni, 

Yeni bin yıla çekmesidir.

Bin yıllarca sürecek, 

Ama yıllarla ölçülemeyecek, 

Görmediğin, bilmediğin, 

Yalnız hissedebileceğin, 

Bir sevginin ilk dizeleridir.

Gözüm hep yükseklerde, 

Çünkü penceren yükseklerde, 

O kadar yüksek değilim ki, 

Bahar olsun geçeyim pencerenden, 

Çiçekler bırakayım en güzellerinden, 

Güzelliğinle boy ölçüşemeyen.

Asansörde kaldığım doğrudur bir kere, 

Ama benim tamir ettiğim de doğrudur.

Öyle ya da böyle, 

Sonuçta ulaşacağım zirvedeki yerime, 

O zaman bir sen eksik olacaksın.

Bin yılın son şiiri bu, 

Bir el uzat bin yılın aşkına.

Şimdiye dek yaşadıkların, 

Yaşayacakların yanında, 

Bin yıl geride kalacak inan.

Bir el uzat Rüzgar''ın oğluna, 

Meydan okuyalım, 

Etiğini sanan rüzgar bozuntularına.

Bin yılın son şiiri bu, 

Okudukların; 

Bir rüzgarın aşk ilanıdır.', 'Bu;  Bin yılın son şiiri,  Okudukların;  Bir yürekte alevlenen,  Gözlerinde esen,  Asansörle özleşen,  Buna rağmen gizlenen,  Söylenemeyen, ...', ARRAY['Türk Edebiyatı','Şiir','Ozan Kaymak']::text[], 8.5, '{"poet":"Ozan Kaymak","poet_slug":"ozan-kaymak","theme":"Türk Şiiri","is_hero":false,"total_lines":43,"source_url":"https://www.antoloji.com/bin-yilin-aski-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ayışığı', 'ayisigi-tekin-gonenc-43i36', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'sen gidince

ne mi kalır geriye

bir tutam ayışığı

uzanıp aldığım

gözpınarlarından

  

 (Varlık Dergisi, Mart 2001)', 'sen gidince ne mi kalır geriye bir tutam ayışığı uzanıp aldığım gözpınarlarından     (Varlık Dergisi, Mart 2001)...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/ayisigi-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Son Dilek', 'son-dilek-omer-bedrettin-y48kj', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Aşığım, dağlara kurulu tahtım, 

Çobanlar bağrımı dağlarda geçer

Günümü yıl eden şu kara bahtım

Engin gurbetlerde çağlar da geçer...

Hasretle doldurur geçtiğim yeri

Vahşi kuş sesleri, yaban gülleri, 

Bazan Akpınara giden bir peri

İnce yollarımı bağlar da geçer...

Örtse gözlerimi sonsuz bir diyar

Mezarım dağlara kalsa yadigar, 

Gönlümü çiğneyip geçen nazlı yar

Belki mezarımdan ağlar da geçer.', 'Aşığım, dağlara kurulu tahtım,  Çobanlar bağrımı dağlarda geçer Günümü yıl eden şu kara bahtım Engin gurbetlerde çağlar da geçer... Hasretle...', ARRAY['Türk Edebiyatı','Şiir','Ömer Bedrettin']::text[], 8.5, '{"poet":"Ömer Bedrettin","poet_slug":"omer-bedrettin","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/son-dilek-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ne Zaman', 'ne-zaman-stepne-sair-n46o3', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ne zaman yatağıma yatsam

ne zaman yorganıma sarılsam

ne zaman yastığımı baş ucuma koysam

ve ne zaman gözlerimi kapasam

o düş sen olmuyordun

ne zaman yatağım toprak olduğunda 

ne zaman yorganım kefen olduğunda

ne zaman yastığım mezar taşı olduğunda

ve sonsuza gözlerimi kapadığımda

sen yanımda olmuyordun', 'ne zaman yatağıma yatsam ne zaman yorganıma sarılsam ne zaman yastığımı baş ucuma koysam ve ne zaman gözlerimi kapasam o düş sen olmuyordun ...', ARRAY['Türk Edebiyatı','Şiir','Stepne Şair']::text[], 8.5, '{"poet":"Stepne Şair","poet_slug":"stepne-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/ne-zaman-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yağmur', 'yagmur-stepne-sair-bbkid', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'bulutlar bir perde misali 

kapatmıştı gök yüzünü

işte ben dercesine 

geçmişti güneşin önüne

ateşin düşmanı toprağın dostuydu

sanki kara bulutlar

ve işte yağmur 

ağır ağır başlamıştı

yeryüzüne inmeye

toprak yağmura kavuşmanın 

sevincini yaşarken

seyyar manavlar 

3 tekerlikli ekmek teknelerini

bir bucağa saklama çabasında

güneş yavaş yavaş

ışıklarını kara bulutlar arasından

sızdırmaya başlamıştı bile

belki başında söylemeyi unuttum ama

işte bu; 

bir yağmurun öyküsü', 'bulutlar bir perde misali  kapatmıştı gök yüzünü işte ben dercesine  geçmişti güneşin önüne ateşin düşmanı toprağın dostuydu sanki kara bulu...', ARRAY['Türk Edebiyatı','Şiir','Stepne Şair']::text[], 8.5, '{"poet":"Stepne Şair","poet_slug":"stepne-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/yagmur-37-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Ayrılık DestanıII', 'bir-ayrilik-destaniii-stepne-sair-r7ppp', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'gözyaşların akıyordu yanaklarından

dudaklarına kavuşurcasına

içindeki hasretti yeniden 

o damlaları kabartan

hayat sensizliği

sensizlik sessizliği

sessizlik bir soğukluk getiriyordu

damarlarıma

içindeki kanı soğuturcasına

tenim soğuyor dudaklarım çatlıyor

gözyaşlarım yanaklarıma varmadan 

soğuyor kayboluveriyordu

farkettiğim bir şey vardı

o da ikimizinde ağlamasıydı belkide

ne oluyordu bize böyle birdenbire

içimden bir ses bir acıyı

yansıtıyordu sanki dudaklarıma

neydi diye soruyordum

birden bire kendime

ayrılık diyordu bu beden

içime, yüreğime', 'gözyaşların akıyordu yanaklarından dudaklarına kavuşurcasına içindeki hasretti yeniden  o damlaları kabartan hayat sensizliği sensizlik sess...', ARRAY['Türk Edebiyatı','Şiir','Stepne Şair']::text[], 8.5, '{"poet":"Stepne Şair","poet_slug":"stepne-sair","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/bir-ayrilik-destaniii-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Namlu Uçları', 'namlu-uclari-tekin-gonenc-lew5u', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'sonra gittin sen

kendi acılarına dilsiz

yarısı küskün bahçelerde güldüğünün

yarısı sürgünlerde

ışıklar içinde binlerce ada

kulaç kulaç sokulurken denizlerine doğru

aldırmadın gittin

yaralı dağlara gömdün yanılgılarını da

tek bir kurşunla yanıbaşında vurulan

o can arkadaşın gibi

şimdi açılan her mektubunda

sonu gelmez postal sesleri

ve yırtık asker türküleri

sen de öğrendin sonunda

açlığımız da bizim

umulmadık namluların ucundadır

tokluğumuz kadar

			

     Varlık dergisi, sayı 2000/3, mart2000', 'sonra gittin sen kendi acılarına dilsiz yarısı küskün bahçelerde güldüğünün yarısı sürgünlerde ışıklar içinde binlerce ada kulaç kulaç sokul...', ARRAY['Türk Edebiyatı','Şiir','Tekin Gönenç']::text[], 8.5, '{"poet":"Tekin Gönenç","poet_slug":"tekin-gonenc","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/namlu-uclari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mezar', 'mezar-yunus-emre-i76ro', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sabah mezarlığa vardım, 

Baktım herkes ölmüş yatar, 

Her biri çâresiz olup, 

Ömrünü yitirmiş yatar.

Kimi yiğit, kimi koca, 

Kimi vezir kimi hoca, 

Gündüzleri olmuş gece, 

Karanlığa girmiş yatar.

Vardım onların katına, 

Baktım ecel heybetine, 

Ne yiğitler muradına, 

Daha ermemiş yatar.

Nicelerin bağrın deler, 

Kurtlar üstünde gezeler, 

Gepegencecik tâzeler, 

Gül gibice solmuş yatar.

Yarı kalmış tüm işleri, 

Dökülmüş inci dişleri, 

Dağılmış sırma saçları, 

Hep yerlere düşmüş yatar.

Çürüyüp durur tenleri, 

Hakka ulaşmış canları, 

Görmez misin sen bunları? 

Nöbet bize gelmiş yatar.', 'Sabah mezarlığa vardım,  Baktım herkes ölmüş yatar,  Her biri çâresiz olup,  Ömrünü yitirmiş yatar. Kimi yiğit, kimi koca,  Kimi vezir kimi ...', ARRAY['Türk Edebiyatı','Şiir','Yunus Emre']::text[], 8.5, '{"poet":"Yunus Emre","poet_slug":"yunus-emre","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/mezar-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Cennet Ve Cehennem', 'cennet-ve-cehennem-faruk-nafiz-camlibel-fdjx1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Bu akşam bilmediğim bir âlem içindeyim, 

Ya rüyada bir seyyah, ya semavi Çin''deyim, 

Bir orman yangınıyle kızardı karşı dağlar, 

Taraf taraf tutuştu meş''aleler, çırağlar, 

Bir renge girdi eşya günün altın tasında, 

Bu kızıl kâinatın gezerken ortasında.

Birden alev 
..........
..........', 'Bu akşam bilmediğim bir âlem içindeyim,  Ya rüyada bir seyyah, ya semavi Çin''deyim,  Bir orman yangınıyle kızardı karşı dağlar,  Taraf taraf...', ARRAY['Türk Edebiyatı','Şiir','Faruk Nafiz Çamlıbel']::text[], 8.5, '{"poet":"Faruk Nafiz Çamlıbel","poet_slug":"faruk-nafiz-camlibel","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/cennet-ve-cehennem-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayalşehir', 'hayalsehir-yahya-kemal-beyatli-8dntb', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Git bu mevsimde gurup vakti Cihangir''den bak, 

Bir zaman kendini karşındaki rüyaya bırak; 

Başkadır çünkü bu akşam bütün akşamlardan; 

Güneşin vehmi saraylar yaratır camlardan! 

O ilâh isteyip eğlence hayalhanesine, 

Çevirir camları birden peri kâşânesine.

Som ateşten bu saraylarlabütün karşı yaka.

Benzer üç bin sene evvelki mutantan şarka.

Mest olup içtiği altın şarabın zevkinden, 

Elde bir kırmızı kâseyle ufuktan çekilen, 

Nice yüz bin senedir şarkın ışık mimarı

Böyle mâmur eder ettikçe hayal Üsküdar''ı.

O ilahın bütün ilhamı fakat ânidir; 

Bu ateşten yaratılmış yapılar fânidir; 

Kaybolur hepsi de bir anda kararmakla batı, 

Az sürer gerçi fakir Üsküdar''ın saltanatı; 

Esef etmez  güneşin şimdi neler yıktığına, 

Serviler şehri dalar kendi iç aydınlığına.

Ezeli marifetin böyle bir ikliminde

Altının göz boyamaz kalpı kadar halisi de, 

Halkının hilkati her semtini bir cennet eden

Karşı sahilde karanlıkta kalan her tepeden, 

Gece birçok fıkara evlerinin lâmbaları

En sahih aynadan aksettiriyor Üsküdar''ı.', 'Git bu mevsimde gurup vakti Cihangir''den bak,  Bir zaman kendini karşındaki rüyaya bırak;  Başkadır çünkü bu akşam bütün akşamlardan;  Güneş...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/hayalsehir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdarın Dost Işıkları', 'uskudarin-dost-isiklari-yahya-kemal-beyatli-79dty', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Ötmekte fecre karşı horozlar birer birer

Geçtikçe her dakika belirmektedir seher.

Bilmem kaçıncı fecri vatan toprağında, biz, 

Görmekle şimdi bir yaşatan vecd içindeyiz.

Etrafı okşuyor mayısın taze rüzgârı; 

Karşımda köhne Üsküdar''ın dost ışıkları...

Kimlersiniz? Ya bağrı yanık kimselersiniz! 

Yâhut da her sabah uyanık kimselersiniz! 

Dünya yüzünde, bir sefer olsun, tanışmadan, 

Öz çehrenizle sizleri görmekteyim bu an.

Sizlersiniz bu anı ışıklarla Türk eden! 

Eksilmesin şu mutlu şafaklar bu ülkeden! 

Gönlüm, dilim, kanım ve mizacımla sizdenim

Dünya ve ahirette vatandaşlarım benim.', 'Ötmekte fecre karşı horozlar birer birer Geçtikçe her dakika belirmektedir seher. Bilmem kaçıncı fecri vatan toprağında, biz,  Görmekle şimd...', ARRAY['Türk Edebiyatı','Şiir','Yahya Kemal Beyatlı']::text[], 8.5, '{"poet":"Yahya Kemal Beyatlı","poet_slug":"yahya-kemal-beyatli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/uskudarin-dost-isiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk Sancısı', 'ask-sancisi-ferruh-turgut-i-nal-iv26b', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kendime ait  inişlerim  ve  çıkışlarım  var; 

Doğrularım  ve  yalanlarım...

Bir  de  sen  varsın. Kahretsin! Aklımdasın...', 'Kendime ait  inişlerim  ve  çıkışlarım  var;  Doğrularım  ve  yalanlarım... Bir  de  sen  varsın. Kahretsin! Aklımdasın......', ARRAY['Türk Edebiyatı','Şiir','Ferruh Turgut İnal']::text[], 8.5, '{"poet":"Ferruh Turgut İnal","poet_slug":"ferruh-turgut-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/ask-sancisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Duyguyu Seviyorum', 'bu-duyguyu-seviyorum-ferruh-turgut-i-nal-4lz4q', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu  duyguyu  seviyorum...

Gecenin bir yarısında, 

Sessizlik  ve  içimin haykırışları! 

Sensizlik  senfonisi  ve  şefi: kalbimin manalı vuruşları 

Bu  duyguyu  seviyorum...

Bir  gece   yarısı gözlerim  tavanda; 

avizeye vuran  ay  ışığı  yansımasında, 

Bakışımdaki  hüznü, çenemdeki  gamzenin fasıla ile çekilmesini

 Geçmişte senin için yaptığım, belki  basit ama benim için  kayda değer şeyleri

Hatırlamayı  ve  iç çekmeyi...

Neden  ve hala senden vazgeçemediğimi

Derin   bir  nefes alıp  vermesini

Verirken havanın burnumdan çıkarkenki  hissi

Bu  duyguyu  seviyorum  diyebilmeyi  ve   seni  seviyorum', 'Bu  duyguyu  seviyorum... Gecenin bir yarısında,  Sessizlik  ve  içimin haykırışları!  Sensizlik  senfonisi  ve  şefi: kalbimin manalı vuruş...', ARRAY['Türk Edebiyatı','Şiir','Ferruh Turgut İnal']::text[], 8.5, '{"poet":"Ferruh Turgut İnal","poet_slug":"ferruh-turgut-i-nal","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/bu-duyguyu-seviyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlıktan Geliyorum', 'yalnizliktan-geliyorum-cem-ergin-iwo1r', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Bir tren varmış telveli bulutların içinden çıka gelen.

Bir çift el varmış aşınmış yalnızlığa işaret.

Çok uzaklar girmiş araya, geçmiş zaman.

Kılıç kuşanmış beyler gibi gelen nefret.

Mor dağların eteklerine takılmış güneş.

Ardında kimsesiz, solgun bekleyiş. 

Geride kalmış gecelik rengi kavrulmuş ateş.

Ten kokusuna susamış, eskimiş beraberlikler.', 'Bir tren varmış telveli bulutların içinden çıka gelen. Bir çift el varmış aşınmış yalnızlığa işaret. Çok uzaklar girmiş araya, geçmiş zaman....', ARRAY['Türk Edebiyatı','Şiir','Cem Ergin']::text[], 8.5, '{"poet":"Cem Ergin","poet_slug":"cem-ergin","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/yalnizliktan-geliyorum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kılıç Artığı Poe-tik-ler''den', 'kilic-artigi-poe-tik-ler-den-a-hicri-i-zgoren-k7imv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'I

Masallarımız aynı düşlerimiz bir

Aynı ateşin yaktığı ağıtlardan geliyoruz

Kentin en uzak köşeleri

Hüznün ele verecek seni

Öyle mahzun bakma çocuk

''Devletin ve milletin bekası'' zedelenir

Orda aşka yardım ve yataklıktan

Sabıkalıdır şiir

II

Acı ata yadigârıdır

Bin yıllık bir tarihi var

Beni bana kırdırır

Kehribar bir tespih gibi

Çek çek bitmez

Kimi zaman yaşayıp yaşamamak

Birbirine eşittir

Orda zembereksiz bir saat

Kırık bir keman gibidir şiir

III

Hüznü bir bohça gibi vurup sırtına

Söyle hangi acısıydın viran evlerin

Kanlı bir mendil kaldı geride

Serin bir su yavru bir kuş gibiydi

Meçhulümüzdür nasıl bir ölüme gelin gittiği

O mendilin kokusunda

Kanın dördüncü halidir şiir

IV

Maskeler atılmış roller ve replikler

Derin bir uykuya dalmıştır

Bir şarkıda ağlarken

Bir çiçeği sularken

Onlarla konuşur görürsem seni

Demektir

Şiir yeni çığlıklara hazırlıyor kendini

V

Hepsi de yaralı bir cerenin resmidir

Açılırsa bir sayfası unutulmuş defterin

Orda herkes kendi payına düşen

Bir yangınla karşılaşacak

Ve görülecek

Kaç kadın ezilmiş ayak altında

O canavar evlerin

De ki 

O defterin dipnotlarıdır düşünde düş görür şiir

VI

Piyasa şartları nedir

İstatistik yasaları ne söyler bilmem ama

Bir avuntu bulunur her zaman

Peşin fiyatına taksitle

Biraz etik estetik

Biraz kolesterol biraz turnusol

Vazife ulufe biraz felsefe

Bunca havar hiç rayting yapmıyor demek

Vatanperver bir münevver olarak

Sizin bu konuda bakışınız kaç amper

Belki de

Turnusolün sudaki rengidir şiir

VII

Daha yirmi dört saat

Hayati tehlikesi var diyor doktor

Durmadan morfin yapıyorlar

Kurtulsa da izi kalırmış

Yüreğini ezmiş aklının paletleri

Bir saatin tik-taklarıdır orda

Beşinci mevsimin adıdır şiir

VIII

Biz mi taşırız aşkları

Aşklar mı bizi

Şimdi hangi kentte

Yağdığını unuttuğum bir yağmur

Ertelenmiş bir aşkın saçlarını yıkıyor

O günden beri

Öznesi yaralıdır şiirin

IX

Orda yıldızlar daha parlaktır

Aynalar daha ayna

Yaşamaya başladığın an

Biraz daha koyulaşır ağaçların yeşili

Orası

Şiirin kendini göndere çektiği yerdir

X

Sensiz paslı bir çivi gibi duruyorum

Bir duvarın yüzünde

Ateşe ve rüzgâra dair bir dize kuşan

Bu geceyi teslim al

Bir selam uçur bana

Hâlâ bir sabah serinliği ise adresim

İnsana dair her çığlık

De ki şiirdir biraz', 'I Masallarımız aynı düşlerimiz bir Aynı ateşin yaktığı ağıtlardan geliyoruz Kentin en uzak köşeleri Hüznün ele verecek seni Öyle mahzun bakm...', ARRAY['Türk Edebiyatı','Şiir','A. Hicri İzgören']::text[], 8.5, '{"poet":"A. Hicri İzgören","poet_slug":"a-hicri-i-zgoren","theme":"Türk Şiiri","is_hero":false,"total_lines":90,"source_url":"https://www.antoloji.com/kilic-artigi-poe-tik-ler-den-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uzak', 'uzak-a-hicri-i-zgoren-2zw24', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Herkesin bir yağmuru vardır ve bir rüzgarı

Aşk biraz ıslanmaktır

Al götür beni o uzak yağmurlara

Herkesin bir şiiri vardır ve bir şarkısı

Aşk biraz çoğalmaktır

Al götür beni o uzak şarkılara

Herkesin bir akşamı vardır ve bir masalı

Aşk biraz yorulmaktır

Al götür beni o uzak akşamlara', 'Herkesin bir yağmuru vardır ve bir rüzgarı Aşk biraz ıslanmaktır Al götür beni o uzak yağmurlara Herkesin bir şiiri vardır ve bir şarkısı Aş...', ARRAY['Türk Edebiyatı','Şiir','A. Hicri İzgören']::text[], 8.5, '{"poet":"A. Hicri İzgören","poet_slug":"a-hicri-i-zgoren","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/uzak-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Renk', 'renk-atilla-bartinoglu-w47qy', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir göz var siyah

Bir göz var kahverengi

Bir göz var

Mor

Yumruk yemiş', 'Bir göz var siyah Bir göz var kahverengi Bir göz var Mor Yumruk yemiş...', ARRAY['Türk Edebiyatı','Şiir','Atilla Bartınoğlu']::text[], 8.5, '{"poet":"Atilla Bartınoğlu","poet_slug":"atilla-bartinoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/renk-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Asılan Adam', 'asilan-adam-ayhan-hunalp-4zot0', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Böylesine sürüp gidecek karanlıklar

Bu köpek böylesine 

Havlayacak

Gözlerim hep böyle

Ölürcesine

Yollarda kalacak.', 'Böylesine sürüp gidecek karanlıklar Bu köpek böylesine  Havlayacak Gözlerim hep böyle Ölürcesine Yollarda kalacak....', ARRAY['Türk Edebiyatı','Şiir','Ayhan Hünalp']::text[], 8.5, '{"poet":"Ayhan Hünalp","poet_slug":"ayhan-hunalp","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/asilan-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Lorke', 'lorke-ayhan-hunalp-qj6pi', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ömrünce dağları

Gördün Lorke

Bilemezsin denizleri

Hep kartallarla konuştun

İnsanları sevemezsin

Sen Lorkesin

Gözlerin varla yok arası

Kaderin körolası.', 'Ömrünce dağları Gördün Lorke Bilemezsin denizleri Hep kartallarla konuştun İnsanları sevemezsin Sen Lorkesin Gözlerin varla yok arası Kaderi...', ARRAY['Türk Edebiyatı','Şiir','Ayhan Hünalp']::text[], 8.5, '{"poet":"Ayhan Hünalp","poet_slug":"ayhan-hunalp","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/lorke-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zan', 'zan-zeynep-koylu-skw5t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'zamandan önce doğdum. bir avuç sesti ömrüm

gölgemin izi kaldı karanlığın ağzında

aynada haritasız unutmuşum denizi

annemin göğsünde eskiyen aşktım

ben günah işledikçe incelmişti arz

döndüm! kabileydiniz çok yüzlü bir çarmıhta

beni de terkederken bir Tanrıyla aldanın

hiçbir sesi sevmedi ağzımdaki uçurum

serçelerin duasıyla büyümüştüm bir gece

avlunuzun kızıydım. çok denedim ölmeyi

her sokak sevişimde kanardı bileklerim

rüzgârsa içimdeki en eski büyücüydü

onarırdı çöllerde kırılan asasını

gölgeme bağdaş kuran ay perisiyle

masallar ki o eksik gölgemden kalmışlardı

yüzümün yittiğini söylediğinde babam

bendim gökyüzünün son götürdüğü uçurtma

adanmış bir kuyuydum odaların yasına

ırmaklar hiç dönmedi. oysa döndüm

kabileydiniz

zaman şimdi zan altında', 'zamandan önce doğdum. bir avuç sesti ömrüm gölgemin izi kaldı karanlığın ağzında aynada haritasız unutmuşum denizi annemin göğsünde eskiyen ...', ARRAY['Türk Edebiyatı','Şiir','Zeynep Köylü']::text[], 8.5, '{"poet":"Zeynep Köylü","poet_slug":"zeynep-koylu","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Temmuz Geceleri', 'temmuz-geceleri-fatih-cinar-lswli', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'özlemin nehir gibi çağlar gözümde

kendimden geçerim her temmuz gecesinde

şiirler dolanır durur çevremde

bana seni fısıldar her temmuz gecesinde

eski günler hep aklıma gelir

seni hatırlarım gözlerim nemlenir

sanki tüm şarkılar sana seslenir

seni çağırırlar her temmuz gecesinde

aşkımızı mezara gömsem ne olur

hayalini yaksam kül etsem ne olur

beynimde hatıralar dönüp durur

yakarlar içimi her temmuz gecesinde

ilk önce bir merhaba bir temmuz gecesinde

sonra ölümden beter veda temmuzun yirmi yedisinde

giderken sanki yirmiyedi kurşun sıkıp gittin beynime

tüm yaşanmışlıkları yerlebir edercesine', 'özlemin nehir gibi çağlar gözümde kendimden geçerim her temmuz gecesinde şiirler dolanır durur çevremde bana seni fısıldar her temmuz gecesi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/temmuz-geceleri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Günahkar Şiirler', 'gunahkar-siirler-fatih-cinar-79lo9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'şiirler günahkar acımasız zalim

beni her gece uykusuz bırakırlar

bilmezler nedir ne olacak halim

bir güzel sevda için gönlümü kandırırlar

şiirler günahkar isyankar asi

aşkın ateşini yakıp çevirirler küle

en çılgın aşkları bile ederler mazi

yinede dökülür ağızlardan mısra mısra hece hece

şiirler günahkar acımasız zalim

çiğner tüm kuralları yasaktan anlamazlar

dinlemezler elden gitsede güzelliğim gençliğim

aynalara baktırıp her sabah ağlatırlar

şiirler günahkar isyankar asi

yalana çevirirler tüm doğru zamanları

ağaçlar yeşilmiş denizler mavi

yerlebir ederler ormanları kumsalları

şiirler günahkar acımasız zalim

ayrılık düdüklerini onlar çaldırırlar

yol vermezler dönmek istesede sevgilim

ağustos sıcağında zemheri yaşatırlar', 'şiirler günahkar acımasız zalim beni her gece uykusuz bırakırlar bilmezler nedir ne olacak halim bir güzel sevda için gönlümü kandırırlar şi...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gunahkar-siirler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gül Yağsın Ufkumuza', 'gul-yagsin-ufkumuza-refik-durbas-hm989', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'GÜL YAĞSIN UFKUMUZA

Ufka gül yağdığı akşam

yüzleri ucuz

sevdası ezberinde

kiralık evler gibi serin

turfanda kadınlarda sevdi

Ufka gül yağdığı akşam

ölüme ve ayrılığa cesur

esrara dayanıklı

masraf makbuzu kullanmayan

az şekerli kadınlar da sevdi

Ufka gül yağdığı akşam

aynalara abone

kalçalarından gayrı her şeyi helal

çocuk bitmez tarlasını sürdüğü

vadesi dolmuş, kadınlarda sevdi

Ufka gül yağdığı akşam

Herkesten uzakta şimdi', 'GÜL YAĞSIN UFKUMUZA Ufka gül yağdığı akşam yüzleri ucuz sevdası ezberinde kiralık evler gibi serin turfanda kadınlarda sevdi Ufka gül yağdığ...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/gul-yagsin-ufkumuza-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karşılama', 'karsilama-refik-durbas-x2n1i', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'anılardan yontulmuş yüze değil

bir felakete adadım kendimi

deneyerek sesimi yeni bir ölüde, her gün

sabahla, baharın geldiğini

resimlerde yaşayan ikindileri

akşamın yalnızlığa düşürdüğü kafiyeyi

kılıçla kesilen yatsıları

mavi kuş zındanlarını

ve sıkıntıyı adlandıran geceleri müjdeledim.

o, yüreğinde uzun hüzünler besledi.

oysa acılar çoğalmış, dağlar uyumuştu

karanlığın kollarında şehir uyumuştu

denizin derinliğinde söken şafak

yüzündeki dalgınlık

ağzındaki ince harfler uyumuştu

fala mı inanırdım artık, kelimelere mi

su terazilerine, ölü tüccarlarına

geceye ve gündüze mi? 

o gitti. bir sevdaya yasladı kendini

ben kaldım. yalnızlıkla karşıladım her şeyi.', 'anılardan yontulmuş yüze değil bir felakete adadım kendimi deneyerek sesimi yeni bir ölüde, her gün sabahla, baharın geldiğini resimlerde ya...', ARRAY['Türk Edebiyatı','Şiir','Refik Durbaş']::text[], 8.5, '{"poet":"Refik Durbaş","poet_slug":"refik-durbas","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/karsilama-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Trabzona Girdim Seller İçinde', 'trabzona-girdim-seller-i-cinde-fatih-cinar-r363a', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'trabzona girdim seller içinde

akar gözüm yaşı kanlar içinde

nazlı yarin gönlü eller içinde

garibim ne edeyim kullar içinde

bir yalnızlık türküsü tutturmuş dilim

yar fezada bir yıldız uzanmaz elim

dağlar desen yol vermez çetinmi çetin

trabzona girdim seller içinde

garibim ne edeyim kullar içinde

şanlı karadeniz ahımdan inler

kör olmuş bağlamam sağır olmuş teller

yar sinesine uzanmış namahrem eller

trabzona girdim seller içinde

akar gözüm yaşı kanlar içinde

yas tutup ağlar olmuş yemyeşil dağlar

yar namert koynunda namusum kan ağlar

geçit vermez gitsemö koplar ziganalar

trabzona girdim seller içinde

nazlı yarin gönlü eller içinde

ağaç misali yeşil yarin gözleri

çukur ovada pamuk bembeyaz elleri

gel görki bana olmuş zemherimi zemheri

trabzona girdim seller içinde

akar gözüm yaşı kanlar içinde

karadeniz elinde çalınır söylenir türküm

sevenlere nassihat olur yar aşkına söylenen sözüm

yıkıldı sevdam uğruna benliğim özüm ülküm

trabzona girdim seller içinde

garibim ne edeyim kullar içinde

aşkı uğruna ruhum boşlukta sallanır

bayram terk etmiş beni başıma karalar bağlanır

yardan bir seda gelse gönül daha nelere katlanır

trabzona girdim seller içinde

nazlı yarin gönlü eller içinde

garip ankaralı bu işten bir ders alırmola

yürek hiç yorulmaz vermez bir mola

ussuz olunca baş vursan ne sağa sola

trabzona girdim seller içinde

akar gözüm yaşı kanlar içinde', 'trabzona girdim seller içinde akar gözüm yaşı kanlar içinde nazlı yarin gönlü eller içinde garibim ne edeyim kullar içinde bir yalnızlık tür...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":39,"source_url":"https://www.antoloji.com/trabzona-girdim-seller-icinde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Üsküdar ve Ben', 'uskudar-ve-ben-ahmet-kuruoglu-t4ezo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Üsküdar da bir şafak vakti

Yine bıraktığım yerde duruyor kız kulesi

Gün baş ucundan usulca doğarken

Duyulmuyor başka birşey martıların sesinden

Doyulmaz bir hoş seda bu

Kulakları sağır ediyor uğultusu

O sırada: 

Dalmışım, kaçırmış beni dalgalar

Alıp götürmüşler diyar diyar

Yüreğime kadar ıslanmışım boğazın içinde

Görmemişim yanımdaki küçük çingene kızı bile

Sabahın bu kör vaktinde

''Abe bir gül vereyim'' diyor titreyen sesiyle

Ama ben hiç sevmem ki gülleri

Sahipsiz bırakırız onlar için hep masum kır çiçeklerini

Öyleyse: 

Bir simit parasına fal bakayım dedi

Kıramadım, 

Belli ki açtı 

Kokuyordu nefesi

Ve açtım avucumu

Küçük bir çocuğun dilinde aradım umudu

Ve açtım avucumu

Küçük bir çocuğun yalanlarında aradım doğruyu

Bir garip oluverdi birden yüzü

Sanki yokmuş gibi başka sözü

''Sen aşıksın abi'' dedi

Ben bilirim dercesine bakıyordu gözleri

Acaba atıp tutuyor muydu? 

Neden di güzel yüzündeki bu anlamsız kuşku? 

Ve yine konuşmaya başladı

Sanki beni anlatıyordu çatlamış dudakları

Yakınında olacaksın dedi yanıbaşında

Ama uzaktan hep hasret dolu gözlerle bakacaksın ona

Güzel kız denizin ortasında

Sense çaresizsin kıyıda

Vallahide taşımaz

Billahide taşımaz 

Bunca yükü kağıttan sandalın

Zaten izni yok ki sana bu dalgaların

Boşver be abi dedi boşver

Sen Üsküdar gibisin

Aşığı olmuşsun denize rağmen Kız Kulesinin

İşte sevdiğim Üsküdar ve Ben

Ha Kız Kulesi ha Sen.', 'Üsküdar da bir şafak vakti Yine bıraktığım yerde duruyor kız kulesi Gün baş ucundan usulca doğarken Duyulmuyor başka birşey martıların sesin...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Kuruoğlu']::text[], 8.5, '{"poet":"Ahmet Kuruoğlu","poet_slug":"ahmet-kuruoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":45,"source_url":"https://www.antoloji.com/uskudar-ve-ben-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hüznüne Sevda', 'huznune-sevda-varol-ozturk-2q8f7', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Ben hayata yaşamaktan kaçarken tutuldum Sevgili.

Bir intihara koşar gibi kabullendim hayatı.

İnadına ve isyanla yaşadım, 

Ölümler çağırmaktan kısıldı sesim, 

Beter oldum. Yaşadım. Kapanmış bir yarayı dürtüler gibi yaşadım.

Tutup yine de sevmişsem seni, intiharım olan yaşamakta

Aşkın panzehirinin olmayışındandır.

Benim hayatım kaybedişler üzerine kurulmuştur Sevgili.

Eni sonu malum bir cinayetin masum ve meçhul bir maktulüyüm ben.

Ben seni yaraya tuz basar gibi, bütün vuslatları yıkarak sevdim.

Ben seni sadece sevdim.

Dedim sana. Aşk gibi hüznün de sebebi yoktur Sevgili, tutamağı vardır sadece.

Ben şehirleri nemli bodrum katların kaldırım hizası pencerelerinden tanıdım.

Yokulmuş zamanlar ve imkansız mekanlar gibidir benim sevgim.

Bu yüzden büyük umutlarım olmadı, olamaz benim.

Biliyorum. Senin gülüşün benim baharımdır.

Ne ki bodrum katların kör odalarında aslolan hüzündür Sevgili

Ben seni hüznüne sevdim, ben seni sadece sevdim

Biliyorum. Senin gülüşün benim baharımdır.

Oysa benim adım gurbetlere yazılmış, yüreğime hüzün düşürülmüştür.

eylül yorgunu saçlarımla en güzel hüzünleri ben yaşarım.

Ben seni gerekçesiz ve neticesiz sevdim.

Ve nasıl sevmişsem seni böyle dolu dizgin, ulu orta

Öylece hüzne belenmişim işte.

Bazı acılar vardır, tütün gibi işler adamın ciğerine, aşk gibi, yaşamak gibi.

Sevgili, Sevmişsem seni ve yaşıyorsam hala

Tütün çekiyorsam gecenin bir vakti, 

Demli bir hüzne çatmışım belle. Dedim sana.

Aşk gibi hüznün de sebebi yoktur Sevgili, tutamağı vardır sadece.', 'Ben hayata yaşamaktan kaçarken tutuldum Sevgili. Bir intihara koşar gibi kabullendim hayatı. İnadına ve isyanla yaşadım,  Ölümler çağırmakta...', ARRAY['Türk Edebiyatı','Şiir','Varol Öztürk']::text[], 8.5, '{"poet":"Varol Öztürk","poet_slug":"varol-ozturk","theme":"Türk Şiiri","is_hero":false,"total_lines":29,"source_url":"https://www.antoloji.com/huznune-sevda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şahmerdan', 'sahmerdan-yucelay-sal-7d43a', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni yeşil düşün yavrum fazla hasar yok 

Demeyi diyebilmeyi nasıl isterdim soranlara

Van Gogh''la arkadaş olmayı istediğim kadar 

Halamım siyanürü istediği kadar isterdim evet 

Gel gör ki bir yandan yüzümdeki eğreti maske 

Bir yandan benimle büyüyen eski yara izleri 

Dilimdeki sözcükleri kanatmaya götürüyor işte beni

Yeni bir rengi keşfetmenin keyfiyle birlikte 

Tenimize düşen yaralarla da bezeniyor ömrümüz 

Ne kadar yelkovan akrebe darılırken kabuk da bağlasa 

Dökülse de o kabuk düğün evinde kasap oynarken 

En sessiz yerde bağıran bir iz kalıyor yerinde

Ben büyüdükçe benimle büyüyor bu yara izleri 

Böylece efendiler daha bir çöküyorum kağıda ben de

Bıçak sırtı törenlerde herzelik ettim tamam

Kibarca hır çıkartmanın tam yerini de bildim 

Yine de eksiklerim olmalıydı ki yıkıldı siperlerim 

Mesela kentin en güzide yerlerine işemedim hiç 

Pisuarlara izmarit atmanın zevki de benden uzak 

Sonunda yorgun yokuşları düzleyemedim lanet 

Şimdi parmaklarımı çıtlatıyorum bunlan anlatırken 

Ordugâhta akşamlar gürültüyle iniyordu üstümüze 

Mavi kuvvetlerin her neferi gibi kahraman 

Cezalı bir nöbetçi kulesi kadar yalnızdım

Gölgemi günbatımına düşürüp mırıldandığım hava

Luck''nin şu ünlü şarkısıydı ''I''am a lonely cowboy'' 

Aklımda korsan koyarken düşen kırılgan sadak

Kıç cebimde tek güvencim her zaman bir yatağan

Sulann soğuduğu günlerdi kükürt renkli günler

Karanlığın kahpeye çanak tuttuğu bir saatte

Vay bile beklemezken eyvah geldi başıma tertip

Ruhsuz karaltıları kara listemin başına koyup

Vakarla çıkarıp gömdüğüm yerden savaş baltamı 

Mızrağımı öperek dalkılıç daldığım dalkavuklara 

Dönüşüm yoktu artık fünyem çekilmişti bir kere

Kanayan yaralarıma da boşverdim kırılan kalkanıma da

Hatta esen rüzgarla kalkan bir şeyim vardı benim

Onun da ne zamandır bana küsülü kaldığını unuttum

Yavrumlar gözleri uçaksavar sinik ejderhalarım

Yalnız onlar için sağlam tuttum örselenen kalbimi

Çok şeyin yırtık her şeyin buruşuk olduğu bu dünyada 

Bir o dünyaya dışından bakabilmek sıvazladı sırtımı 

Güzelim Haşimiye dehlizinde kaybolduğumda anladım ki 

Ağır çekiç darbeleri altında bunca kıvranmamam için köpeğimin 

adı Kıtrnir olmalıydı bir kere bu kesin

Sağ yanağımda en afilisinden bir şark çıbanı 

Sol gözümde yaygaracı bir trahom olmalıydı 

De hele bir doğru değil mi söylediklerim 

Ey İbrahim''e karşı serin ve sakin olan ateş

Yorgansız yatan Urfalılar çığlık tacirleri

Dövüşün kör tefecileri gökten medet umanlar 

Ne kanatlarında binlerce çağrışım taşıyan Halilrahrnan

Ne yalımlarıyla büyüleyen Anzılha dikilmesin yoluma 

Belli ki beynimde darp izleriyle terkederim bu kenti 

Buralarda hiç yere düşürmedim siyah pelerinimi ama 

Konakladığım ilk korunakta usta işi ağlarım 

Çok vukuatım vardır derinimde bilmezsiniz komutanım', 'Beni yeşil düşün yavrum fazla hasar yok  Demeyi diyebilmeyi nasıl isterdim soranlara Van Gogh''la arkadaş olmayı istediğim kadar  Halamım siy...', ARRAY['Türk Edebiyatı','Şiir','Yücelay Sal']::text[], 8.5, '{"poet":"Yücelay Sal","poet_slug":"yucelay-sal","theme":"Türk Şiiri","is_hero":false,"total_lines":57,"source_url":"https://www.antoloji.com/sahmerdan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yüreğimde Son Şiir', 'yuregimde-son-siir-tolga-yilmaz-lsbu8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Şiirler yazardım hep yüreğimde.

İçimde dolup taşardı, 

Söyleyemezdim.

Hepsini silmek isterdim, 

Silemezdim.

Sana okumak isterdim, 

Okuyamazdım.

Ben hep şiir yazardım yüreğimde.

Hala şiir yazıyorum yüreğimde.

İçimde dolup taşıyor, 

Söyleyemiyorum.

Silmeye çalışıyorum, 

Olmuyor.

Sana okumak istiyorum, 

Yapamıyorum.

Ben hep şiir yazıyorum yüreğimde.

Siir yazmaya devam edeceğim yüreğimde

İçimde dolup dolup taşacak, 

Söyleyemeyeceğim.

Yine de silmeye çalışacağım, 

Sonucunu bilsemde.

Belki sana okumak isteyeceğim, 

Okuyamayacağım.

Tıpkı şu an yazdığım yüreğimde son şiir gibi...

Ama ben yine de hep şiir yazmaya devam edeceğim yüreğimde.

Okunamayacak olmasının cesaretiyle, 

Her şeyi haykıracağım şiirlerimde.

Seni yine sensiz tutacağım yüreğimde, 

Bilmeyeceksin, görmeyeceksin, düşünmeyeceksin ama

Yine de gülüm

Ben sana şiirler yazmaya sürgün edeceğim gönlümü.', 'Şiirler yazardım hep yüreğimde. İçimde dolup taşardı,  Söyleyemezdim. Hepsini silmek isterdim,  Silemezdim. Sana okumak isterdim,  Okuyamazd...', ARRAY['Türk Edebiyatı','Şiir','Tolga Yılmaz']::text[], 8.5, '{"poet":"Tolga Yılmaz","poet_slug":"tolga-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/yuregimde-son-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Henüz...', 'henuz-sair-doktor-jzfx1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Henüz söylemedim sana

zaman durduğunda belki

ya da düştüğümüz an beraber

haritaların dışarısına...

İklim gibi sarardın bedenimi

yağmur gibi yağardın

ruhumun acıya meyilli kuruluğuna

sana söylemedim daha

uzandım ama tutamadım

sıcaklığı yüreğime yayılan

ellerini...

Seni sevdim biliyorum

ıslak bir dünya yabancılığında, 

erken bir sabah mahmurluğunda.

korkan ve ürperen bedenim

ve bana derin bir okyanus gibi gözüken

gözlerin...

Seni sevdim biliyorum

ama en çok gözlerini

sana söylemedim henüz

cinayetimin sebebini! ! ! ...', 'Henüz söylemedim sana zaman durduğunda belki ya da düştüğümüz an beraber haritaların dışarısına... İklim gibi sarardın bedenimi yağmur gibi ...', ARRAY['Türk Edebiyatı','Şiir','Şair Doktor']::text[], 8.5, '{"poet":"Şair Doktor","poet_slug":"sair-doktor","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/henuz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yapayalnız', 'yapayalniz-turkan-akyol-73vju', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'denizin mavisindeki sihrin sırrı

bende cözül...

ne kadar daha yasamam lazım

askı bulmak ıcın

ya da

asık olmak ıcın...

bilmeliyim

daha ne kadar boyle dolasacagım 

yanlız

yapayanlız.', 'denizin mavisindeki sihrin sırrı bende cözül... ne kadar daha yasamam lazım askı bulmak ıcın ya da asık olmak ıcın... bilmeliyim daha ne kad...', ARRAY['Türk Edebiyatı','Şiir','Türkan Akyol']::text[], 8.5, '{"poet":"Türkan Akyol","poet_slug":"turkan-akyol","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/yapayalniz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'usudum', 'usudum-gul-tan-qn3rc', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Tutamıyordum ellerini

Ben yaklaştıkça, 

Sen, uzaklaşıyordun.

Şaşırmadım.

Gerçektede böyle değilmiydi? 

O elleri, ben hiç tutamadım.

Senin hayalini çocuk yüreğimde çizmiştim.

Hiç çıkmadın ki o günden sonra.

Yüreğim büyüdü, sen büyüdün.

Yaşadığım yıllardada seni aradım.

Daha arıyorum.

Ben yarım insandım, kaybolmuştu bir tarihte

Beni tamamlayan yarım.

Sen, 

Benim için hep rüyaydın

Biraz babamın gözlerinden, annemin şevkatinden, 

İlk öğretmenimin aferinlerinden, 

Birşeyler vardı sende.

En güzelide sana olan düşkünlüğüm.

Hiç aşık olmadım, olamadım.

Olsaydım ve seni bir gün bulsaydım.

Gözlerine korkar, bakamazdım.

Seni gördüm rüyamda

Ben dün gece çok üşüdüm.', 'Tutamıyordum ellerini Ben yaklaştıkça,  Sen, uzaklaşıyordun. Şaşırmadım. Gerçektede böyle değilmiydi?  O elleri, ben hiç tutamadım. Senin ha...', ARRAY['Türk Edebiyatı','Şiir','Gül Tan']::text[], 8.5, '{"poet":"Gül Tan","poet_slug":"gul-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/usudum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Olmayacaktı', 'olmayacakti-gul-tan-3cw9f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'İlk deli çağlarımdı...

Dünyayı ben değiştirecektim.

Ağlamayacaktı  soğuktan ve açlıktan, 

Mendil satan çocuklar.

Ben dünyayı değiştirmeyi düşünürken, 

Sen yoktun ki.

Benim, değişmem yoktu ki hiç hesaplarımda.

Soğuktan üşümem yoktu

, Bir türküye günlerce

Ağlamam yoktu ki..

Ben; amacım için yaşayacaktım.

Senin için sessiz şiirlermi yazacaktım? 

Ne dünya nede sen.

Benden başka değişen olmadı.

Herşey aynı yerinde 

Tek sen varsın, değişen yüreğimde.', 'İlk deli çağlarımdı... Dünyayı ben değiştirecektim. Ağlamayacaktı  soğuktan ve açlıktan,  Mendil satan çocuklar. Ben dünyayı değiştirmeyi dü...', ARRAY['Türk Edebiyatı','Şiir','Gül Tan']::text[], 8.5, '{"poet":"Gül Tan","poet_slug":"gul-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/olmayacakti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hani', 'hani-gulsah-solmaz-gy1t3', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Teyzeme...........

Gidişin ansızın oldu

Hani haber verirdin sen giderken? 

Martılar söylerdi hani ölüm türkünü

Dalgaların köpüğünden içerken....

Hani Nemrut’ta güneşin doğuşunu görecek

Beyşehir’de batan günü resmedecektin

Hani Kadıköy’de balık yiyecek, 

Yağan yağmuru içine çekecektin? 

Gidişin ansızın oldu

Sessiz, derin, habersiz....

Benim gelişim ansızın mı olur bilemem...

Ama ben haber verir de gelirim....

Sana haber vermek için Azrail’e bile oyun ederim..', 'Teyzeme........... Gidişin ansızın oldu Hani haber verirdin sen giderken?  Martılar söylerdi hani ölüm türkünü Dalgaların köpüğünden içerken...', ARRAY['Türk Edebiyatı','Şiir','Gülşah Solmaz']::text[], 8.5, '{"poet":"Gülşah Solmaz","poet_slug":"gulsah-solmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/hani-8-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benim mi', 'benim-mi-gul-tan-b0owo', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedenleri, niçinleri düşünme diyorsun.

Başaramıyorum.

Deniyorum olmuyor.

Gördüğüm yerde, hissettiğim yerde, 

Nasıl başarabilirim? 

Umarsızca yaşamayı? 

En önemliside, sen yüreğimdeyken.

Seninle sohbetlerimiz, başka konularda

Ateşli bir konuyu anlatırken, 

Yüzünün en ciddi ifadesinde bile

Ben çatılan kaşlarının arasına, 

Bir öpücük kondurmayı hayal ediyorum.

Oysa sen..

Dinlediğimi zannedip daha bir hiddetle

Tartışıyorsun dünya meselelerini.

Hiç bilemedin seni delice sevdiğimi.

Neden hep aynı zamanda karşılaşıyorduk? 

İkimizde her zaman, aynı yerde olmamız mümkünmüy dü? 

Düşünemediğin en ince ayrıntılarda ben vardım.

Başkasına ait olmana rağmen, 

Seviyorum seni.

Kıskanmıyormuyum zannediyorsun? 

Sen, seni sevdiğimi, 

Sana böylesi şiirler yazdığımı bilmedin.

Bilemeyeceksin.

Seni uzaktan sevmek belki en güzeli.

Ellerimin tutmadığı, gözlerimin görmediği, 

Hiç bir şeye inanmam deyişin korkutuyor beni

Göremiyorsan, tutamıyorsan.

Suç  benim mi?', 'Nedenleri, niçinleri düşünme diyorsun. Başaramıyorum. Deniyorum olmuyor. Gördüğüm yerde, hissettiğim yerde,  Nasıl başarabilirim?  Umarsızca...', ARRAY['Türk Edebiyatı','Şiir','Gül Tan']::text[], 8.5, '{"poet":"Gül Tan","poet_slug":"gul-tan","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/benim-mi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sen İle Sensizlik', 'sen-i-le-sensizlik-nilgun-pakyildiz-5i0pg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yıldızımdın sen benim, 

Kayıverdin gecemden.

Aşk denilen o sırrı, 

Alıverdin avuçlarımdan çözemeden.

Sen ile sensizliğin arasında, 

Kalıverdim başıboş, apansız! 

İnan ki sende kaldığım doğru, 

Yalan olan ayrıldığımız.

Nicedir alacakaranlıklardaydım, 

Sana sığındım lisan-ı aşk ile...

İlkin erişilmezdin, eridi dağlar...

Sonra yol verdi yüreğin, yüreğime...

Lal oldu dilim, boyun eğdim, 

Bahar rüzgarı taşıyan muhabbetine.

Göğsünde yaslı kalaydı, 

Bir ömür boyu dertli başım.

Ülkemden göçmeseydi, 

Ayrılığın ufkuna sevda kuşlarım.

Ne ki duyduğum endişe, bilmiyorum..

Nedendir senden uzak kalışım..

Viraneye döndü hem ruhum, 

Hem de, zaman ve mekanım.

Ellerim yaban ellerde, 

Ellerinin sıcaklığını, şefkatini arıyor.

Alnımda son kondurduğun busen ile, 

Dudaklarımda tebessümün duruyor.

Şimdi, sadece sen varsın düşlerimde...

Hem gecemdesin, hem gündüzümde...

Kalıversende kalbimde aşkımsın, gidiversende...

Aşk buymuş meğer, 

Sevgiliye acı versede!', 'Yıldızımdın sen benim,  Kayıverdin gecemden. Aşk denilen o sırrı,  Alıverdin avuçlarımdan çözemeden. Sen ile sensizliğin arasında,  Kalıverd...', ARRAY['Türk Edebiyatı','Şiir','Nilgün Pakyıldız']::text[], 8.5, '{"poet":"Nilgün Pakyıldız","poet_slug":"nilgun-pakyildiz","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/sen-ile-sensizlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öteden Beri', 'oteden-beri-i-brahim-sadi-gokirmak-ie7x6', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'öteden beri

yalnız

ve mahzundum

nerede bulurum diye aradığım 

senin gözlerindeydi

karadeniz''de gemiler vardı

güneşin peşinden

giden

gemiler

yalnızlık siyahtı

ben yalnızdım

senin gözlerin mavi

sarıydı saçların

karadeniz''de gemiler güneşin

ben senin

peşinde

ihanetteydim

karadeniz''de gemiler vardı

bir yalan hikayenin peşinde koşan

ben

senin yanıbaşımda

ihanetteydim

sen ihanetimdin

benim gözlerimden yağardı yağmur

yalancı yakamozları ben yaratırdım

karadeniz''de gemiler vardı

güneşim peşinden giden

ay''a ihanet eden

gemiler

sen ayrılırken bana

bense senin yüzünden allah''a

ihanetteydim', 'öteden beri yalnız ve mahzundum nerede bulurum diye aradığım  senin gözlerindeydi karadeniz''de gemiler vardı güneşin peşinden giden gemiler ...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadi Gökırmak']::text[], 8.5, '{"poet":"İbrahim Sadi Gökırmak","poet_slug":"i-brahim-sadi-gokirmak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/oteden-beri-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ançüezli Şiir', 'ancuezli-siir-cahit-koytak-g8lb2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'kimi anneler de ançüezli ekmek

verirler küçük oğullarına

ki kafaları büyüsün

ve baş edebilsinler

boğa bakışlı kadere

ama bilmezler

kafa kafaya dövüşmez ki kader..

her gün aynı oyunu

yeni repliklerle girer

ve rollerini unutturur onlara

dillerini büker- böylece

dünkü yüzlerini bugün

maskeye tahvil eder

nice mevsimlik oyunlardan

küçük küçük zaferlerden

bozgunlardan sonra

bir gün aşka da gelir sıra

yalnızca susarak

ya da doğaçlamalarla

konuşabilen aşka..

bir otelin hüzünlere ayrılan odasında

sabahlara kadar uzayan 

dipsiz bir tragedya..

bir tragedya ki, yalnız

alkolle bölünür ara sıra

ya da daha ilk perdede, ateşli

bir tiradın ortasında

dünyaya sıkılan

gül gibi doğaçlama

bir tabanca kurşunuyla..

dumanı sahne tozu kokar

ve ançüezli ekmek tadı bırakır ağızda.', 'kimi anneler de ançüezli ekmek verirler küçük oğullarına ki kafaları büyüsün ve baş edebilsinler boğa bakışlı kadere ama bilmezler kafa kafa...', ARRAY['Türk Edebiyatı','Şiir','Cahit Koytak']::text[], 8.5, '{"poet":"Cahit Koytak","poet_slug":"cahit-koytak","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/ancuezli-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tövbesiz Tapınak', 'tovbesiz-tapinak-i-brahim-sadi-gokirmak-k54s1', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'sen yüreği sevgi kasırgası

tövbesiz tapınak

gözyaşlarını

kurban diye bırak

yüreğin daha çok zülme engel olacak', 'sen yüreği sevgi kasırgası tövbesiz tapınak gözyaşlarını kurban diye bırak yüreğin daha çok zülme engel olacak...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadi Gökırmak']::text[], 8.5, '{"poet":"İbrahim Sadi Gökırmak","poet_slug":"i-brahim-sadi-gokirmak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/tovbesiz-tapinak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-i-brahim-sadi-gokirmak-3um3s', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'ellerin çok yabancıtdı

ve ben hiçbir aşkımda 

bu kadar suskun kalmamıştım

sevecenliğin kadar yakın

tanınmazlığın kadar uzaktın', 'ellerin çok yabancıtdı ve ben hiçbir aşkımda  bu kadar suskun kalmamıştım sevecenliğin kadar yakın tanınmazlığın kadar uzaktın...', ARRAY['Türk Edebiyatı','Şiir','İbrahim Sadi Gökırmak']::text[], 8.5, '{"poet":"İbrahim Sadi Gökırmak","poet_slug":"i-brahim-sadi-gokirmak","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/ellerin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Fark - Sız', 'fark-siz-mehmet-karakulak-onmzj', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hep AŞK şiirleri yazdım

hep aşk şarkıları söyledim

şimdi yine

hep AŞK şiirleri yazıyorum

hep aşk şarkıları söylüyorum

yine acı yine elem yine keder dolu

ne fark var arasında

şiirler farklı değil

ben hiç farklı değilim

fark

fark işte

'' O '' yok

SEN varsın

korkarım

sende değişecek 

FARK yine aynı yerde olacak!', 'Hep AŞK şiirleri yazdım hep aşk şarkıları söyledim şimdi yine hep AŞK şiirleri yazıyorum hep aşk şarkıları söylüyorum yine acı yine elem yin...', ARRAY['Türk Edebiyatı','Şiir','Mehmet Karakulak']::text[], 8.5, '{"poet":"Mehmet Karakulak","poet_slug":"mehmet-karakulak","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/fark-siz-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uçurumda Açan', 'ucurumda-acan-cemal-sureya-sq55j', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Aşktın sen, kokundan bildim seni

Bir ahırın içinde gezdirilmiş gül kokusu

Taşıttan indin, sonra da karşıya geçtin

Elinde tuhaf bir çanta, saçında soku

Akıl almaz işleri şu zambakgillerin

Sokakta bir sövgü gibi akıp gittin

Gözlerin sonsuz uzun, sonsuz çekikti

Baksan uçtan uca Çin Seddi''ni görebilirdin

Yanındaki adam mutlaka kardeşindir

İstanbul öyle ağırbaşlı bir kent değildir

Aşktın sen, gidişinden bildim seni

Neye yarar sağduyuyu a
..........
..........', 'Aşktın sen, kokundan bildim seni Bir ahırın içinde gezdirilmiş gül kokusu Taşıttan indin, sonra da karşıya geçtin Elinde tuhaf bir çanta, sa...', ARRAY['Türk Edebiyatı','Şiir','Cemal Süreya']::text[], 8.5, '{"poet":"Cemal Süreya","poet_slug":"cemal-sureya","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/ucurumda-acan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
