INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Gece', 'bu-gece-ahmet-gumustekin-9g8mw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Düşümde Gördüm

Bu Gece Seni.

Beyazlar İçinde

Bir Melek Gibiydin.

Uyuyordun.

Çiçekler Serdim Çevrene.

Usulca Öptüm Seni.

Kulağına Fısıldadım

Seni Sevdiğimi.

23.12.2001', 'Düşümde Gördüm Bu Gece Seni. Beyazlar İçinde Bir Melek Gibiydin. Uyuyordun. Çiçekler Serdim Çevrene. Usulca Öptüm Seni. Kulağına Fısıldadım ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Gümüştekin']::text[], 8.5, '{"poet":"Ahmet Gümüştekin","poet_slug":"ahmet-gumustekin","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bu-gece-28-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Seni', 'seni-gultekin-samanoglu-hq7yg', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir karanfil, bir yasemin, bir ıtır, 

Bir yaprak üstünde parlayan damla, 

Velhasıl her şiir seni anlatır

İçim burkulur da o eski gamla

Dudaklarım titrer gözlerim dolar

Ruha kurşun gibi çöken akşamla

Sanırım ki bahçelerde sesin var, 

Mehtap yine senin için doğacak

Seni anlatacak bütün şarkılar', 'Bir karanfil, bir yasemin, bir ıtır,  Bir yaprak üstünde parlayan damla,  Velhasıl her şiir seni anlatır İçim burkulur da o eski gamla Dudak...', ARRAY['Türk Edebiyatı','Şiir','Gültekin Samanoğlu']::text[], 8.5, '{"poet":"Gültekin Samanoğlu","poet_slug":"gultekin-samanoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/seni-10-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aynayı Sil, Pencereyi Aç, Rüzgarını Unutma', 'aynayi-sil-pencereyi-ac-ruzgarini-unutma-ozkan-demir-9jpmw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'derin dehliz: Yaz yangınları

camı boğan buğuyu açan soluksun

mermerin çatlayan damarı

derin dehliz: Sil küfürleri

yolculukları başlatan sözden

ve gül anımsatsın seni

derin dehliz: Sal karanfili

o yabanıl akıntılara,  kalpsarsıntılarına

adını unutan kımıltı

ve aynalar dirilsin.', 'derin dehliz: Yaz yangınları camı boğan buğuyu açan soluksun mermerin çatlayan damarı derin dehliz: Sil küfürleri yolculukları başlatan sözd...', ARRAY['Türk Edebiyatı','Şiir','Özkan Demir']::text[], 8.5, '{"poet":"Özkan Demir","poet_slug":"ozkan-demir","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/aynayi-sil-pencereyi-ac-ruzgarini-unutma-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aranan sevgi', 'aranan-sevgi-mahmut-dogan-tl85u', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Küçük ve daracık bir pencereden 

Dalıp giderim bilmediğim uzaklara

Bir yol görürüm upuzun sürüp giden

Tek başıma yürürüm gideceğim yeri bilmeden.

Gittiğim yerde dolanıp dururum 

Neyi ve niçin aradığımı bilmeden

Sonra incecik bir ses duyarım

Şaşkın ve titrek alacakaranlıkta

Gittiğim yerde yine dolanırım

Meğersem ardaığım o incecik ses diilmiş

O bilmediğim uzaklarda ağlarım

Neden ağladığımı bilmeden 

Ve ışıldayan bişey görürüm 

Güneşmi aymı ne olduğunu bilmeden

Bişeyler sölerim daha önce, 

Hiç söylemediğim bişeyler

Sonra ışıldayan şeyi sevmeye başlarım

Oışıldayanın ne olduğunu bilmeden

Fakat içimden bi ses gelir

O bilmediğim uzaklarda aradığım

O sevdiğim ışıltı değil 

Daha önce tatmadığım

Benliğimin tek eksik parçasını arıyorum

Fakat ne olduğunu bilmeden ararım

Obilmediğim uzaklarda...', 'Küçük ve daracık bir pencereden  Dalıp giderim bilmediğim uzaklara Bir yol görürüm upuzun sürüp giden Tek başıma yürürüm gideceğim yeri bilm...', ARRAY['Türk Edebiyatı','Şiir','Mahmut Doğan']::text[], 8.5, '{"poet":"Mahmut Doğan","poet_slug":"mahmut-dogan","theme":"Türk Şiiri","is_hero":false,"total_lines":25,"source_url":"https://www.antoloji.com/aranan-sevgi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Nihan ve Bursa', 'nihan-ve-bursa-savas-ozbek-2rx5y', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'N asıl bir duygu allahım bu? ? ...

İ  çim alev alev kıpır kıpır yanıyor onun için=(.

H ayatımın bir anlamı var artık onunla..

A şkı sevgiyi cenneti yaşattı bana bu dünyada..........

N emutlu bana izin versede ölsem kollarında..sçs aşkısı.

V aktim yoktu öptüm dudaklarından ayrıldım yanından.

E nderin yanlızlıklara düştüm uçağa bindiğim an...

B urkuldu yüreğim titredi kalbim koptum bu dünyadan=((

U zun çok uzun hayallettim aşkımı o yanımda olmadan((

R enkli dünyam karardı aklımzeytin bahçesinde kaldı...

S arılıp öpmüştüm doyamadım dudaklarına beni benden aldı..

A klımı aşkımı kalbimi setbaşındaki liseli birkıs çaldı=(((((

     bursanın en güzel kızına yazılmıştır bu şiir........

adı şiir de saklı..

azerbaycandaki aşkın uzakların adamı ıslatko obiçamte...', 'N asıl bir duygu allahım bu? ? ... İ  çim alev alev kıpır kıpır yanıyor onun için=(. H ayatımın bir anlamı var artık onunla.. A şkı sevgiyi ...', ARRAY['Türk Edebiyatı','Şiir','Savaş özbek']::text[], 8.5, '{"poet":"Savaş özbek","poet_slug":"savas-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/nihan-ve-bursa-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ah Siz İnsanlar', 'ah-siz-i-nsanlar-deger-ulas-turan-ias2e', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ah siz insanlar, 

Acılarınızı kendinizden bile sakladınız... 

Öyle bencildiniz ki, 

Bedeniniz kadar dürüst olamadınız... 

Düşünsellik adına ateşler yaktınız, 

Ama nedense siz yoktunuz, o ateşin harında... 

Bir umuda el vermek adına sözler verdiniz; 

Unuttunuz verilen sözlerinin onurunu... 

Onuru, yalanlarınız kadar yaşatmadınız... 

Umudun adını, yalanlar gibi yaşadınız... 

Ah siz insan kardeşlerim, 

Bir kez olsun sızlamadı içiniz... 

Kalbiniz bir dehliz... 

Düşen her şey boğulur gerçeğinizde... 

Üşüdü bedenleriniz, 

Elleriniz üşüdü, 

Isıttınız... 

Bir sıcaklığı kullandınız, 

Kendinizi ısıtmak adına, 

Kapanıp, kayboldunuz... 

Ama unuttunuz o ateşin harında, 

Verilen sözlerinde yandığını... 

Şimdi hiç bir söz, 

Hiç bir umut kalmadı diye, 

Yine alıp götürüyorsunuz bedenlerinizi, 

Bir diğeri ilgilendirmiyor sizi... 

Bir diğer umut, bir başka söz, 

Yaşam bir diğeri için... 

Ah siz ölüler, 

Kanınız donuk, 

Kalbiniz suskun, 

Bütününüz diye her şey, 

Toprak olmuş... 

Bencilliğinizle çürüyor etleriniz... 

Temiz olsun diye her şey. 

Verdik en masum yerimizden. 

Kelepir fiyatına, 

Satılan insanlığımız, 

Kibrit fiyatına yanan gerçekliğiniz, 

Değeri kadar sıcak kalabildiyse... 

Bu sessiz çığlık, 

Kendine kapalı bu şiir, 

Kaçmak için bir ateşten ötesini bırakmaz... 

Ucuz ve ömürsüz bir yazgı, 

Alıp gittiğiniz... 

Sarhoş bir ayak sesi, kaçışlarınız.. 

Arkanızda bıraktığınız, 

Bir dolu soğumuş hayal... 

Ya baharı bekleyen onca yürek, 

Ya diğerleri... 

Ah siz insan diye sevdiklerim, 

Elleriniz soğuk mu hala, 

Isınmaya gelmiyorsunuz... 

Bekleyen insanlarınız var, 

Bekleyen yeni aşklarınız.. 

Bir şeyler adına söz vermek gerek, 

Yeniden umutlanmak var... 

Yaşamak adına, 

Yeniden bir söz vermek için, 

Bağışladık yüreğimizi, 

Bağışlanacak yüreklerimiz var... 

Onurlu kalsın insanlığımız, 

Küçük bir adımımız olsun, 

Büyük düşlerin, gerçek sevinçlerine... 

Umutluyum hayat kadar, 

Umutluyum insanlığımdan... 

Senden de umutluyum, 

Bilgin bilincinle, 

Yüreğin sevginle, 

Güzelliğin bedeninle, 

Anlamlı olanı yakalar... 

Keşfet hayatı 

Doğru ellerinde... 

Tutmuşsun bak. 

Seni sen yapan her ne varsa, 

Onurlu kılar insanı... 

Yaşamak için daha çok neden var.', 'Ah siz insanlar,  Acılarınızı kendinizden bile sakladınız...  Öyle bencildiniz ki,  Bedeniniz kadar dürüst olamadınız...  Düşünsellik adına ...', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":77,"source_url":"https://www.antoloji.com/ah-siz-insanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neredeyim?', 'neredeyim-deger-ulas-turan-0sjd8', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bir bulut olmuşum, 

Hep aynı toprağa sevdalı. 

Sağanak halim eritir toprağı, 

Özlemimde, Çisil çisil bir bahar. 

Ben hep baharı anımsarım... 

Bilirsin baharlar, 

Yağmurları içtiği vakit, 

Toprağına hayatı 

Ve sevgiyi getirir... 

Bir tohum olmuşum sonra, 

Susmuşum… 

Unutmuşum sonra varlığımı 

Varlığıma ihanetim kalmış 

Bilememişim neredeyim. 

Sormuşum asırlara. 

Zamanların ürkek, 

Zamanların cesur, 

Sessiz çığlıklarına… 

Sormuşum kendimi; 

Neredeyim? 

Anlarım her şeyi birer birer. 

Bir yerdeyim öyle aç, 

Öyle yabancı… 

İsimsiz bir orman, 

Çiçeksiz bir bahar... 

Dokunuşlar, 

Küfür gibi... 

Susmak istiyorum, 

Yasak... 

Konuşmaktan sıkılmışım.. 

Ağlamışım bir toprağa hasret, 

Öyle kayıp bir gök… 

Gülmüşüm, 

Gülüşlerim yitik bir rüya… 

Gördüklerim, 

Sustuklarım... 

Tutmuşum ellerimle toprağı 

Ve renkleri sevmişim... 

Anlamışım artık her şeyi; 

Ellerim yalan, 

Renklerim çaresiz. 

Ölmüşüm meğer…', 'Bir bulut olmuşum,  Hep aynı toprağa sevdalı.  Sağanak halim eritir toprağı,  Özlemimde, Çisil çisil bir bahar.  Ben hep baharı anımsarım......', ARRAY['Türk Edebiyatı','Şiir','Değer Ulaş Turan']::text[], 8.5, '{"poet":"Değer Ulaş Turan","poet_slug":"deger-ulas-turan","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/neredeyim-33-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Özel Bir İnsan Sibel', 'ozel-bir-i-nsan-sibel-savas-ozbek-ie0fh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'S ımsıcak bir insan kor misali ateş gibi...

İ   sim kelime bulamıyorum seni anlatmaya(

B eni bekledi sabah sabah azkaldı donmasına=))

E nçok üzüldüğüm aldım sevgilimi bıraktım onu yapayalnız..

L ekevardır melekte bile onda asla ama savaş vicdansız=((((

not= hala aklımdan çıkmıyor kıs=((sende beni bekledin arkadaşım çok yardımcı oldun=((ama ben anlayışsız biri gibi seni yapayalnız bıraktım okadar beklemene rağmen=(((

tanrı şahit beni ne olur affet..... bursanın en şirin kızı sibel.', 'S ımsıcak bir insan kor misali ateş gibi... İ   sim kelime bulamıyorum seni anlatmaya( B eni bekledi sabah sabah azkaldı donmasına=)) E nçok...', ARRAY['Türk Edebiyatı','Şiir','Savaş özbek']::text[], 8.5, '{"poet":"Savaş özbek","poet_slug":"savas-ozbek","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/ozel-bir-insan-sibel-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bugünü Yaşamak', 'bugunu-yasamak-fatih-cinar-3oo59', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'bu gün en mavi renginde denizler

şimdi dağlarda geziyorum yalın ayak

içimi serinletiyor en isyankar şiirler

dumanlar tütüyor aşkımdan hasretini yakarak

yağmurlu bir bulut gibidir bedenin

güneşin ayı utandırdığı zamansın

saçların kömür beyaz pamuktur ellerin

gel yanıma bedenin bedenimde yansın

sil aklından bütün fenalıkları

duy yalnız sana söylediğim şiirleri

yırt aydınlık çehrenle tüm karanlıkları

parçalayalım seninle gel büyük engelleri

sen acı hayatımda şeker şerbetsin

yalnızlık koynumdadır tüm ekşiliğiyle

benim olan ne varsa senin olsun senin

sadece sen benim ol aşkımın benciliğiyle

birlikte yanalım sönünceye kadar ateşler, 

girelim sevda ırmağına kuruyuncaya kadar

gönlümüzden dökülsün neşe dolu heceler

akmasın zaman donsun saniyeler dakikalar

yanımda en güzelsin tüm aynalara inat

sıcak kanın benim damarımda akmakta

ruhum yanında huzurlu yanında rahat

şimdi bütün saatler sevdamızı vurmakta

dünleri unut gel hatırlama dünleri

tadalım seninle şu anın bal tadını

yaşamadık farzet yalnız seneleri

hapsedelim yüreğimize sevgi dolu anları', 'bu gün en mavi renginde denizler şimdi dağlarda geziyorum yalın ayak içimi serinletiyor en isyankar şiirler dumanlar tütüyor aşkımdan hasret...', ARRAY['Türk Edebiyatı','Şiir','Fatih Çınar']::text[], 8.5, '{"poet":"Fatih Çınar","poet_slug":"fatih-cinar","theme":"Türk Şiiri","is_hero":false,"total_lines":28,"source_url":"https://www.antoloji.com/bugunu-yasamak-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'kara sEvdA', 'kara-sevda-ozgur-gursoy-1xn8x', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'dedim gözlerin ne renk 

dedi sevda karası

dedim yüreğin

hiç sorma dedi gönül yarası

peki dedim ya sevdiğin

ne senden öncesi dedi

nede senden sonrası', 'dedim gözlerin ne renk  dedi sevda karası dedim yüreğin hiç sorma dedi gönül yarası peki dedim ya sevdiğin ne senden öncesi dedi nede senden...', ARRAY['Türk Edebiyatı','Şiir','Özgür Gürsoy']::text[], 8.5, '{"poet":"Özgür Gürsoy","poet_slug":"ozgur-gursoy","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/kara-sevda-6-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bizim Şiir', 'bizim-siir-nail-abbas-sayar-9gns7', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir cefa toprağı olduk 

Her yağmurun seli bizim 

Bahar vakti bahçelerin 

Kuru kalmış dalı bizim 

Dünya kaldı berbatlara 

Çıktılar hep üst katlara 

Bu kavganın feryatlara 

Terkedilmiş teli bizim 

Sonu yok dünya yasının 

Kuluyuz nân kavgasının 

Sofra erkan başkasının 

Eşiklerin çulu bizim 

Peşinde hayat göçünün 

Mestiyiz dünya hiçinin 

Şu dağdaki kel keçinin 

Uzayacak kılı bizim', 'Bir cefa toprağı olduk  Her yağmurun seli bizim  Bahar vakti bahçelerin  Kuru kalmış dalı bizim  Dünya kaldı berbatlara  Çıktılar hep üst ka...', ARRAY['Türk Edebiyatı','Şiir','Nail Abbas Sayar']::text[], 8.5, '{"poet":"Nail Abbas Sayar","poet_slug":"nail-abbas-sayar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bizim-siir-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünmedin', 'gorunmedin-nail-abbas-sayar-lz8xr', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Gözüm boşluk dünya nokta 

Görünmedin görünmedin 

Olmuşumda olacakta 

Görünmedin görünmedin 

Kuru taşa renk yürüdü 

İpek kurdunu aradı 

Denizde sular çürüdü 

Görünmedin görünmedin 

Geceyi dal dal ışıttım 

Camda güneşi üşüttüm 

Bir ses ki senin işittim 

Görünmedin görünmedin 

Yel yel esen nefesimdi 

Boşlukta gezen isimdi 

Gel diyen benim sesimdi 

Görünmedin görünmedin 

Çabam gücüm kul hükmünde 

Boş boş geçti bugün dün de 

Herkes gibi göründün de 

Görünmedin görünmedin', 'Gözüm boşluk dünya nokta  Görünmedin görünmedin  Olmuşumda olacakta  Görünmedin görünmedin  Kuru taşa renk yürüdü  İpek kurdunu aradı  Deniz...', ARRAY['Türk Edebiyatı','Şiir','Nail Abbas Sayar']::text[], 8.5, '{"poet":"Nail Abbas Sayar","poet_slug":"nail-abbas-sayar","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/gorunmedin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çıtırık', 'citirik-nail-abbas-sayar-sc5de', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Şeytanın bindiği dala 

Tut elimden çıkar beni 

Peteğinde koza balım 

Sanma akar kokar beni. 

Yemiş dalında çürümez 

Dal yaprağını arımaz 

Bir gemim var ki yürümez 

Yedeğine takar beni. 

Moğbeçe bize de mey sun! 

Deme ki pişman olursun 

Kendi derdim şöyle dursun 

Elin derdi yakar beni.. 

Bir çivi çaktım beynime 

Türlü dert girdi koynuma 

İp taktı hasret boynuma 

Peşisıra çeker beni', 'Şeytanın bindiği dala  Tut elimden çıkar beni  Peteğinde koza balım  Sanma akar kokar beni.  Yemiş dalında çürümez  Dal yaprağını arımaz  Bi...', ARRAY['Türk Edebiyatı','Şiir','Nail Abbas Sayar']::text[], 8.5, '{"poet":"Nail Abbas Sayar","poet_slug":"nail-abbas-sayar","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/citirik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hazin Bir Öykü', 'hazin-bir-oyku-oguz-atalay-68d6g', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Karanlık bir gecede şakağımda bir silah, 

Korku kaplar içimi yardım eylesin ilah, 

Bu ne biçim bir iştir silahtaki el benim.

Heycandan olsa gerek ter ile doldu tenim; 

Korku heycan boşuna önce verildi karar, 

Yeniden bedenimi güven duygusu sarar, 

Yavaşça eğiliyor iteatkar bir parmak, 

Kolay mı sandıydın sen ten çemberini yarmak.

Yavaş yavaş giderken zorlaşır birden tetik, 

Sakin genleşen horoz bir yılan gibi atik.

Ölümün işareti sese çığlık katışım; 

Hafif hafif atarken hızlandı kalp atışım, 

Ilık bir rüzgar gibi beynime daldı mermi, 

Cihan bir liman ise, limandan çıktı gemi, 

Bedenden ruh çekilir geride kalır zehir, 

Yola koydum son nokta bundan sonrası ahir.

Şahadet getirmeden çekildi son nefesim, 

Kıpırdamaz oldu bak titreyen bu kafesim, 

İşte hazin bir öykü boşluğa bakan bir göz; 

Elveda sevdiklerim burada biter her söz...

                                                      (27/07/2000)', 'Karanlık bir gecede şakağımda bir silah,  Korku kaplar içimi yardım eylesin ilah,  Bu ne biçim bir iştir silahtaki el benim. Heycandan olsa ...', ARRAY['Türk Edebiyatı','Şiir','Oğuz Atalay']::text[], 8.5, '{"poet":"Oğuz Atalay","poet_slug":"oguz-atalay","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/hazin-bir-oyku-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Başına', 'tek-basina-ferhat-gube-ghjdw', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tek kişilik hücremde yalnızım ben, 

 Ranzam, kitaplarım.

 Hayallerimi sarip, 

 Nefes nefes küllendirdiğim cigaram.

 Üst üste gelen korku nöbetleri, 

 Titreme nöbetleri, 

 Santim santim kemiren, 

 Sessizliğin boğucu sesi, 

 Hırçınlığın tohumunu ekiyor

 Heybeti kendinden büyük gece, 

 Kulağımı tırmalıyor; 

 ''Ölüm'' denen iki hece', 'Tek kişilik hücremde yalnızım ben,   Ranzam, kitaplarım.  Hayallerimi sarip,   Nefes nefes küllendirdiğim cigaram.  Üst üste gelen korku nöb...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Gube']::text[], 8.5, '{"poet":"Ferhat Gube","poet_slug":"ferhat-gube","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/tek-basina-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İstanbul''da Bir Akşam Üstü', 'i-stanbul-da-bir-aksam-ustu-ferhat-gube-hmv8m', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Kadıköy''e doğru yol alıyordu vapur

 Martılar uçuşuyordu

 Yarışıyordu birbirleriyle

 Çocuksu bir çoşkuyla

 Dalgalar vuruyordu vapura

 Usul dokunuşlarla

 Sessizce bir cigara yaktım

 Vapur kız gibi süzülüyordu denizde

 İstanbul''u seyrediyordum

 Meraklı bakışlarla', 'Kadıköy''e doğru yol alıyordu vapur  Martılar uçuşuyordu  Yarışıyordu birbirleriyle  Çocuksu bir çoşkuyla  Dalgalar vuruyordu vapura  Usul do...', ARRAY['Türk Edebiyatı','Şiir','Ferhat Gube']::text[], 8.5, '{"poet":"Ferhat Gube","poet_slug":"ferhat-gube","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/istanbul-da-bir-aksam-ustu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beyazlı Rakkase', 'beyazli-rakkase-levent-umit-temiz-542hw', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çek ki

Erişsin gönlünün

              derinliklerine

Bütünleşsin efkarınla

Hapset ki

Yapışsın içine işlemiş

                       sözlere

Cevapsız sorulara

Ve özgür bırak ki

Söküp giderken

                  tüm acıları

Seyredebilesin

Danseden beyazlı

                  rakkaseyi

                     (Merhaba)', 'Çek ki Erişsin gönlünün               derinliklerine Bütünleşsin efkarınla Hapset ki Yapışsın içine işlemiş                        sözlere C...', ARRAY['Türk Edebiyatı','Şiir','Levent Ümit Temiz']::text[], 8.5, '{"poet":"Levent Ümit Temiz","poet_slug":"levent-umit-temiz","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/beyazli-rakkase-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kış', 'kis-refik-recep-pelit-lpr69', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Daha dün yemyeşildi heryer, 

Bahçedeki nar ağacı çiçeklerle doluydu, 

Erikler çiçeklenmiş, 

Çimenler yeşermişti, 

Doya doya içime çekemeden havayı, 

Doya doya bakamadan o güzel gözlerine, 

Sonbahar geçti, kış geldi, 

Görünce kucağında bir demet gülle, 

Koşup sarılmak geldi içimden, 

Gözlerindeki iki damla yaşı görünce 

Hissettim ölümün soğukluğunu, 

Birden anladım! 

Kış sadece bana gelmiş!   07/01/2002', 'Daha dün yemyeşildi heryer,  Bahçedeki nar ağacı çiçeklerle doluydu,  Erikler çiçeklenmiş,  Çimenler yeşermişti,  Doya doya içime çekemeden ...', ARRAY['Türk Edebiyatı','Şiir','Refik Recep Pelit']::text[], 8.5, '{"poet":"Refik Recep Pelit","poet_slug":"refik-recep-pelit","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/kis-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hiç Bir Şiirin Sizi Anlattığı Oldu Mu?', 'hic-bir-siirin-sizi-anlattigi-oldu-mu-ertan-tanoba-k5qq9', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Hiçbir şiir sizi düpedüz anlattı mı? 

Siz anlatamadığınız için şiirin biri

Sizi mutlaka anlatmıştır.

Muhtemelen yalnızdınız.

Hiçbir şey sevmiyordunuz.

Korkuyordunuz.

İt gibi korkuyordunuz hem de

Yalnızdınız.

Bir şiirin, 

Sevdiğiniz değil, adını bile bilmediğiniz bir şiirin sizi anlattığı sıra siz

Dayak yemiş bir sıpa gibi sahillerde pinekliyordunuz.

Boğazınız hıçkırıkla tıka basa dolduğunda bile

Ağlayamıyordunuz.

Birileri sizden önce davranmıştı ve “hıçkırmıştı”

Şimdi hıçkırarak ağlamak size “tuhaf” geliyordu.

Boğazınızdaki düğümü çözmeden bir yenisi düğüm atıyordu.

Boğuluyordunuz.

Anlamıyordunuz.

Hiç birinin nedenini anlamıyordunuz.

Bağırmak isterdiniz, 

Bağırmayı çocukluktan beri isterdiniz.

Çok seyrek gülerdiniz

O zaman etrafı neşeye boğardınız.

Herkes bu kadar açken

Neden daha fazla gülmezdiniz ki? 

Severdiniz bazen

Nadiren severdiniz evet.

Meftunu olur sevdiğinizin, bırakmak bilmezdiniz

Kimse anlamazdı bunu.

Ne yaşarken ne bitmişken 

Kimse anlamazdı.

Siz bir de yaşarken ne çok ölürdünüz

Lakin ölüm size ne çok yakışırdı

Dirildiğinizde içinde bulduğunuz yaşamları selamlayıp

Mağrur ve vakur güler geçerdiniz

Kimse gülmezdi ama. 

Yazık tutunamadınız.

Ya hiç tutunacak bir dal olmadı, 

Ya da oldu siz tutunmayı bilmediniz.

Sizi kimse sevmezdi

Diliniz sivriydi az biraz

Kıvrak olduğu kadar az biraz da oynak, uylak olsaydı

Ne olurdu sanki.

Olmadı mı? 

Söyleyin bunların hiçbiri olmadı mı? 

Peki, diyelim hiçbiri olmadı.

Hiçbir şiir sizi anlatmadı.

Siz bile hiç anlatmak istemediniz mi? 

O zaman, 

Yanlış zaman, 

Yanlış insan.

Ya siz tam bir şiirin sizi anlatması gerektiği yerde değildiniz, 

Ya hiçbir kafa size dönük değildi, 

Ya tam karşı masada bir şiir tam sizi anlatıyorken

Çekip gittiniz birden, 

Ya çoktan anlatmıştı

Ama siz habersizdiniz.

Peki, diyelim hiçbiri olmadı.

Ne siz düşündünüz, 

Ne birileri düşündü

Ne birileri yazdı.

Diyelim bunların hiçbiri olmadı.

Ee... Madem buradayız

Ve madem ben (ya da sen)

Bu soruyu sorduK! 

O zaman çoktan 

		Şiirin biri

		Bir yerlerde

		Bir zaman

Sizi çoktan anlatmıştır! 

Gidin onu bulun.

Bulamazsanız gocunmayın sakın.

Açın yüreğinizi ardına kadar

Aşık olun! 

19 Aralık,2001-Haymatlos', 'Hiçbir şiir sizi düpedüz anlattı mı?  Siz anlatamadığınız için şiirin biri Sizi mutlaka anlatmıştır. Muhtemelen yalnızdınız. Hiçbir şey sevm...', ARRAY['Türk Edebiyatı','Şiir','Ertan Tanoba']::text[], 8.5, '{"poet":"Ertan Tanoba","poet_slug":"ertan-tanoba","theme":"Türk Şiiri","is_hero":false,"total_lines":75,"source_url":"https://www.antoloji.com/hic-bir-siirin-sizi-anlattigi-oldu-mu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sana Aitti...', 'sana-aitti-levent-gunusen-witu8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Lazım mıydı sanki aşk, meşk, sevda

 Umrumda değil bu dünya küsmüşüm hayata

 En güzel şarkılar vızıltı gibi gelir kulagıma

 Madem fazlalığım bu dunyada

 Vasiyetimdir ölmeden koyun beni toprağa

 Eğlenin, gülün boş verin beni

 Ağlarsan asla affetmem seni

 Ne zaman sahile takılırsa gözün

 Naaşımın üstünde ki siyah kefeni hatırla

 Tabutumun üstüne SENİ SEVDİM  yazın', 'Lazım mıydı sanki aşk, meşk, sevda  Umrumda değil bu dünya küsmüşüm hayata  En güzel şarkılar vızıltı gibi gelir kulagıma  Madem fazlalığım ...', ARRAY['Türk Edebiyatı','Şiir','Levent Günüşen']::text[], 8.5, '{"poet":"Levent Günüşen","poet_slug":"levent-gunusen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sana-aitti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dostum', 'dostum-levent-gunusen-8ozn6', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Elveda aşklara

 Elveda yıllara

 Bu nankör zamana 

 Yenildik dostum

 İnsanın insanı

 Ezdigi bu yerde

 Bir ömür harcadık

 Bu ömür harcadı bizi

 Dostum yenildik aşklara

 Dostum direndik ellere

 Sus artık ağlama dostum

 Bir gün yüzümüz gülecek

 Bir gün yumruğumuz

 Havaya kalkacak

 Bizi hor görenler

 Ayaklarımızı öpecek

 Umudu birbirimizden

 Borç almadık

 Umudu birbirimize 

 Verdik', 'Elveda aşklara  Elveda yıllara  Bu nankör zamana   Yenildik dostum  İnsanın insanı  Ezdigi bu yerde  Bir ömür harcadık  Bu ömür harcadı bizi...', ARRAY['Türk Edebiyatı','Şiir','Levent Günüşen']::text[], 8.5, '{"poet":"Levent Günüşen","poet_slug":"levent-gunusen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/dostum-12-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gelip Geçici', 'gelip-gecici-oruc-aruoba-bkr3o', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gelip geçici, geçip gidici değil mi

Herşey - horoz ötüşü

Çocuk gülüşü, deniz kıpırtısı: 

Herşey--- sen ve ben

Gelip geçmedik, geçip gitmiyor muyuz? 

Bak: 

Uçup giden beyaz bulut

Pırıldayıp geçen ışık

Yiten akıntı-

Görülmeden 

İşitilmeden

Gelip geçen

Geçip giden 

Yüzlerimiz, seslerimiz.

Sen ve ben

Yitip giden

Bilinmeden

Yiten.

Gelip geçici, geçip gidici değil

Herşey-sevgi öpüşü

Dinginlik düşü, yürek sızısı: 

Herşey ---sen ve ben

Gelip geçmedik, geçip gitmiyoruz.

Dinle: 

Esip yiten tatlı umut

Genişleyip biten serinlik 

kalan üzüntü-

Görülerek 

İşitilerek

Geçip gitmeyen

Gelip kalan

Yüzlerimiz, seslerimiz.

Sen ve ben 

Gelip kalan 

Bilerek 

Gelen 

kalan.', 'Gelip geçici, geçip gidici değil mi Herşey - horoz ötüşü Çocuk gülüşü, deniz kıpırtısı:  Herşey--- sen ve ben Gelip geçmedik, geçip gitmiyor...', ARRAY['Türk Edebiyatı','Şiir','Oruç Aruoba']::text[], 8.5, '{"poet":"Oruç Aruoba","poet_slug":"oruc-aruoba","theme":"Türk Şiiri","is_hero":false,"total_lines":37,"source_url":"https://www.antoloji.com/gelip-gecici-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Güneşi Sen Çekeceksin Buluttan', 'gunesi-sen-cekeceksin-buluttan-ahmet-telli-jo0aa', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yitirilince güneş

esmer bir bulutun gölgesinde

hayata kulak ver

deniyor seni

yeni bir iklimde

Hayata kulak ver

ginle toprağın sesini

nasılda anlatır gürül gürül

pir sultan''ı, bedrettin''i, dadal''ı

ve köroğlu''nu

AHMET TELLİ

Nice baharlaı suladılar

zındanlarda onlar

filizlenerek karanlık ülkesinde ihanetin

budandıkça büyüyen

serpilen

gül dalıydılar

Eksiltemedi dudaklarından türküleri

boğazlarına ilmiğini geçirirken hain

Örümcek barında zındanların

nasıl da somuşlar deme

mahpusluk

en eski yiğitlerinden

mirastır bu topraklara

nasıl da özümlemiştir

sevdalı yüreklerini onların

Yitirilince güneş

esmer bir bulutun bölgesinde

düşmesin yüreğine

hüznün bakır çalığına buluttan

hayatı sen yeşerteceksin

unutma', 'Yitirilince güneş esmer bir bulutun gölgesinde hayata kulak ver deniyor seni yeni bir iklimde Hayata kulak ver ginle toprağın sesini nasılda...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":32,"source_url":"https://www.antoloji.com/gunesi-sen-cekeceksin-buluttan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zulme Direnmektir Hayat', 'zulme-direnmektir-hayat-ahmet-telli-z43o7', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'On beşine bastımı

       dudaklarında bir türkü

               elinde bayrak

kavga sokaktaki oyuna benzer artık

çocukluğu

    benzemez

          çocukluğa

Deniz okşayabilir mi

sarışın bir dağın

           rüzgarlı saçlarını

uzanarak yelesine hayatın

tutuklayabilir mi zındanlar

onun

        vuruşkan sevdasını

Açar da acının rüzgarına

hüznün solgun yelkenini

ne zından karanlığı

         ne zulüm

                   ne işkence

indiremez dudaklarındaki gülümsemenin bayrağını

AHMET TELLİ', 'On beşine bastımı        dudaklarında bir türkü                elinde bayrak kavga sokaktaki oyuna benzer artık çocukluğu     benzemez      ...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/zulme-direnmektir-hayat-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kahvede', 'kahvede-ahmet-telli-9spst', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Hep öyküler dinledim

buruk, acımsı, kekremsi

Dinlerken yaşadım diyemem

öldüm

Ama ölmemiş 

o bin öykünün serüvencisi

Sunuyor kendini

canlı bir bildiri gibi

kaçarak tırpanından

ölümün

oturmuş karşımdaki sandelyede

demli çaylar istiyor garsondan

Bol içki bir o kadar küfür ve boşvermişlik

bütün hayata

Ucuza kapatılmış

hatta bedavaya gelmişken hayat

dinler mi girdisini çıktısını

o bin serüvenden sonra

Çok öyküler dinledim

cigara dumanıyla yüklü

duvarların taş baskısı resimlerle

süslü köy kahvelerinde

buruk, acımsı, kekremsi

Dinlerin yaşadım diyemem

öldüm

AHMET TELLİ', 'Hep öyküler dinledim buruk, acımsı, kekremsi Dinlerken yaşadım diyemem öldüm Ama ölmemiş  o bin öykünün serüvencisi Sunuyor kendini canlı bi...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/kahvede-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geceleyin Kırda', 'geceleyin-kirda-ahmet-telli-kixv5', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kuytu bir köşesindeyim 

ve yorgun bedenimin altında 

çıtırdıyor kuru yapraklar

Üstte kristal bir gök

ve yıldızlar

ozancasına

Yalnızım 

sıkıntının yayalnızlığı değil bu

Düşlerle el ele

yaşamayı dillendiren

ve yudum yudum özümleten

bir sevgi yanlızlığı

Dinlendiriyor yüreğimi

kafamı

bedenimi

serin okşayışlarıyla doğa

Dinliyorum en güzel türküsünü

kurdun kuşun

Uçmak için

kanat aramıyorum

AHMET TELLİ', 'Kuytu bir köşesindeyim  ve yorgun bedenimin altında  çıtırdıyor kuru yapraklar Üstte kristal bir gök ve yıldızlar ozancasına Yalnızım  sıkın...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":21,"source_url":"https://www.antoloji.com/geceleyin-kirda-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Her Şey Kararırken', 'her-sey-kararirken-ahmet-telli-rwga1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Kara tahtaları

Yeşile çevirdiler de

Yeşil umutlarını

Karaladılar çocukların

AHMET TELL', 'Kara tahtaları Yeşile çevirdiler de Yeşil umutlarını Karaladılar çocukların AHMET TELL...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/her-sey-kararirken-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Parasız Yatılı Dinbazlık', 'parasiz-yatili-dinbazlik-ahmet-telli-70yhf', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Her yoksul biraz 

parasız yatılılık taşır içinde

küçük şeylerdir mutlulukları

korkarlar büyük denizlerden

Her yoksulda biraz

dinbazlık vardır

bu yüzünden korkunç bencildirler

zalim ve korkaktırlar üstelik 

Korkak bir müslümanım ilkin

gizli anlamlar arıyorum

karınca dualarında

ve gizli bir bir defter tutuyorum

ol müridliğimin hikâyesidir: 

AHMET TELLİ', 'Her yoksul biraz  parasız yatılılık taşır içinde küçük şeylerdir mutlulukları korkarlar büyük denizlerden Her yoksulda biraz dinbazlık vardı...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":14,"source_url":"https://www.antoloji.com/parasiz-yatili-dinbazlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vuruşkan Bir Şahandır Umut', 'vuruskan-bir-sahandir-umut-ahmet-telli-g1ms8', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Tuzağa düşmüş bir ceylanın 

bakışındaki hüzün değildir umut

Kınalı keklik gibi ürkek

bir kuş da değildir

Ne yalvar yakar olmuştur 

zulmün pençesinde

ne de düşürmüştür

kırların ve türkülerin

onururunu yere

Baharda bir tomurcuk

gibi patlayan öfkedir umut

barajını yıkan bir ırmaktır

açılır serpilir

ve büyür kıyısında sevda

Emzirir aşkı

emzirir ve büyütür gül nakışlı sabırlardan

ferhat''ın direncini

bin yılların sabır taşını çatlatırlar

açar bin yılların kapısını

Düşman dönük

bir mavzer gibidir umut

yaratır tetik ve parmak

en gürbüz çocuğunu tarihin

AHMET TELLİ', 'Tuzağa düşmüş bir ceylanın  bakışındaki hüzün değildir umut Kınalı keklik gibi ürkek bir kuş da değildir Ne yalvar yakar olmuştur  zulmün pe...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/vuruskan-bir-sahandir-umut-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öfkenin Adını Koy', 'ofkenin-adini-koy-ahmet-telli-lg86y', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Devrilen bir çınar

nasıl uzanırsa boylu boyunca

öylece düştü kollarına

kan-revan içinde dostun

donup kaldı soluk bir gülümseyiş

çocuksu kıvrımında dudaklarının

Kaşın seyirmeye başladı birden

yüreğin körüğü üflüyor

içindeki cehennemi

ve bir boşluğa nasıl çarparsa deli su

öyle uğuldamakta kulakların

bir bora patlıyor göğsünün okyanusunda

Ne ki tutulmuş nalçalı seslerle

umudun köşebaşları

korsanlar dalgalandırıyor

senin deli rüzgarlarınla bayraklarını

ve yitiriyorsun yolunu

balta kesmez ormanında öfkenin

Bil ki dostunda değil çekilen tetik

senin umuduna, unutma bunu

kör bir öfke delirtmesin 

yıkmasın yaşamın direncini

unutma ki her köşebaşında

bunca dostun kurumadı hâlâ kanları

Hele dik tut başını önce

haykır yıkılmadığını, tükenmediğini

yüreğindeki yalım nasıl olsa 

korlaştırır zamanın çeliğini

sen önce öfkenin adını koy

yanıltmasın yüreğini

AHMET TELLİ', 'Devrilen bir çınar nasıl uzanırsa boylu boyunca öylece düştü kollarına kan-revan içinde dostun donup kaldı soluk bir gülümseyiş çocuksu kıvr...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/ofkenin-adini-koy-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalnızlık Yasak', 'yalnizlik-yasak-ahmet-telli-h5up1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Yüklenmiş kanadına uzak kırların

ve gecelerin kar ürpertilerini

taşıyıp gelmiş buraya dek

hâlâ uğulduyor ürkek göğsünde

dağ başlarının çelik fırtınaları

Çocuksu bakışlarında yorgunluk değil 

bir hasretin direnci var daha çok

ama üşüyor yanlızlıktan.üşüyor

tek düşmüşlüğün acımsı utancından

boynu eğik bekliyor şafağı şimdi

Bir yanlızlık mıdır bunca çoğaltan

acıyı ve biberli yanılgıyı

ve bir yanlızlığı kabullenmek midir

inceden ve usuldan başlatan

yürekte burgaçlanan sancıyı

Sessizce çekilmiş dostların arasından

bir yanlışı sürdürmenin ortasından kendince 

Ayrımına bile varılmamış o yangın günlerinde

Ama üşüyor şimdi kar fırtınasına tutulmuş

gibi üşüyor yanlız kuş

Şimdi biliyor artık yalnız kuş

biliyor ki artık gecikmiştir

yolcular varmıştır varacağı yere

Anlıyor ki şimdi yalnız kuş

yalnızlık yanlışlığın ilk adımıdır.

AHMET TELLİ', 'Yüklenmiş kanadına uzak kırların ve gecelerin kar ürpertilerini taşıyıp gelmiş buraya dek hâlâ uğulduyor ürkek göğsünde dağ başlarının çelik...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/yalnizlik-yasak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kavak Yelleri', 'kavak-yelleri-ahmet-telli-jzuei', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'ündöndü ve bakla tarlalarında

sevişmelerin pomakçasını öğreniyorum

o korkunç hazzını duyuyorum

toprağı doyuma kavuşturmanın

ve hâlâ anlatılmaz bir cinsel koku

buharlaşıyor göğsümün kıllarından

anımsadıkça pomak sevgilimi

On sekizindeyim ve tip''i övmekten

suçlanıp sürülüyorum

Okudukça aşık, aşık oldukça

daha çok okumaktayım bu aylar

biraz ayten biraz süeda ayları bunlar

kurutulmuş çiçek mevsimleri yani

yıllar sonra daha iyi anlaşılıyor

o kaçak şevişmlerin tadı

Fabrika bacalarından 

yağlı bir duman ağıyor göğe

çiziyor

İlk gençliğimin haritasını

AHMET TELLİ', 'ündöndü ve bakla tarlalarında sevişmelerin pomakçasını öğreniyorum o korkunç hazzını duyuyorum toprağı doyuma kavuşturmanın ve hâlâ anlatılm...', ARRAY['Türk Edebiyatı','Şiir','Ahmet Telli']::text[], 8.5, '{"poet":"Ahmet Telli","poet_slug":"ahmet-telli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/kavak-yelleri-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Karaağaçlı İbrahim ve Shakespeare', 'karaagacli-i-brahim-ve-shakespeare-erdinc-ozdemir-degec', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Yorgun kentin son perde sokaklarında

Bir varmış... kalaycılar tüymüş

Malacılar çok sakin... yok telaş.

Bizim İbrahim

Yan yan tam afili yürür.

Gözleri yalnız geceleri gören bir martıyla

Gazoz içerler A.Gandalf marketten.

Çünkü, Salı gününün şemsiyesi yoktur.

Hindistan''da karnı ağrıyor bir ineğin, 

Şarkıcı Dalida intihar etmiş, 

Şambali yiyen Kaptan Ahab

                    buna çok darılmış.

Yok artık pasaport Beyaz Balina''ya

Ne çok karalı bir talih.

Arılarla otostop yapıyorken

Malacıların yok telaşındaki harç

Patladı kulaklarında Shakespeare'' in

Durdu kafasındaki büyüyen gemi

Uğuldadı bulutların derinliği

Bir şarkı olup yağdı: 

Bir kartal bir hayatı reddeder, 

Sonra hep o hayatı ister.

Anladı Shakespeare; 

                        bisikletsiz bir aşk kaçıyor.

Çorapları hiç eskimeyen

ey sonsuzluğa tünemiş Hayat! 

Nasılsın?', 'Yorgun kentin son perde sokaklarında Bir varmış... kalaycılar tüymüş Malacılar çok sakin... yok telaş. Bizim İbrahim Yan yan tam afili yürür...', ARRAY['Türk Edebiyatı','Şiir','Erdinç Özdemir']::text[], 8.5, '{"poet":"Erdinç Özdemir","poet_slug":"erdinc-ozdemir","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/karaagacli-ibrahim-ve-shakespeare-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kar Ömrümüzün Ayracı.', 'kar-omrumuzun-ayraci-rabia-can-ulas-ecijy', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'kar yağıyorken rüzgara salarım ömrümü, 

hüzünlerden bir rota verip ellerine, 

salarım caddelere sokaklara, ama yetişemem

yetişemedim..

bakışları buz tutmuş bir çocuğa, , 

unutulmuş bir yaşlıya..

yetişemedik, , 

gözleri kar suskunluğuna gömüldü bir çocuğun..

daha 13 yaşındaydı, 

acemiydi hayata, 

gökyüzünü çatı dünyayı yuva seçmişti kendine..

yanılmıştı..

kar bizde oyun ve seyirdi

yada arabamıza takılacak zinciri anımsatan beyaz taneler..

ama o en büyük oyununu oynadı ve bıraktı soluğunu kara..

boşuna düşülmemiş bu not hayatın kıyısına..

evet kar yağıyorken milyon bekerel hüzün yağıyordur..', 'kar yağıyorken rüzgara salarım ömrümü,  hüzünlerden bir rota verip ellerine,  salarım caddelere sokaklara, ama yetişemem yetişemedim.. bakış...', ARRAY['Türk Edebiyatı','Şiir','Rabia Can Ulaş']::text[], 8.5, '{"poet":"Rabia Can Ulaş","poet_slug":"rabia-can-ulas","theme":"Türk Şiiri","is_hero":false,"total_lines":17,"source_url":"https://www.antoloji.com/kar-omrumuzun-ayraci-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmezim', 'vazgecilmezim-aysun-elagoz-23nn1', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Duyabilseydin 

Sesimi çok uzaklardan, 

Hissedebilseydin 

İçimde kopan fırtınaları, 

Yüreğimdeki sevgilerin

Bir bir batışını nefret denizinde, 

Görebilseydin, 

Ve anlayabilseydin, 

Anlatmaya gerek kalmadan

Hislerimi.

Belki

O zaman vazgeçilmez olabilirdin

Vazgeçilmezim diye kendimi kandırdığım..', 'Duyabilseydin  Sesimi çok uzaklardan,  Hissedebilseydin  İçimde kopan fırtınaları,  Yüreğimdeki sevgilerin Bir bir batışını nefret denizinde...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/vazgecilmezim-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bul', 'bul-aysun-elagoz-f00qy', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Beni hayat kavgalarında bul, 

Mücadelenin kanını içerken..

Gülümse ve hiç konuşma.

Tanımadığım bir yolun yolcusuyum

Bir yanımda tanrı bir yanımda şeytan.

Suskunum, şikayetsizim, yalnızım...', 'Beni hayat kavgalarında bul,  Mücadelenin kanını içerken.. Gülümse ve hiç konuşma. Tanımadığım bir yolun yolcusuyum Bir yanımda tanrı bir ya...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bul-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sonsuza Yürüyüş', 'sonsuza-yuruyus-aysun-elagoz-jcs9h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Rüzgarın sesine uyup, 

Denizi cebime koyup, 

Güneşi sırtıma alıp, 

Sonsuza yürümek 

Hiç işten değil...', 'Rüzgarın sesine uyup,  Denizi cebime koyup,  Güneşi sırtıma alıp,  Sonsuza yürümek  Hiç işten değil......', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/sonsuza-yuruyus-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Uğrunda Ölüm Gülüm', 'ugrunda-olum-gulum-gurcan-gunay-6p4vt', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'En uzakların ötesinde de olsan

Uzaklardan korkma

Uzat elini tutacağım

Sana toz konmamış yollar açacağım

Dipsiz gecelerde kalsan

Zamansız doğan güneşin olacağım

Ellerini buz kesse

Yüreğindeki ateş küllense

Ocağında yanacak ateşin olacağım

Çağırsa seni sonsuzluklar bir gün

Korkma! O yola ben baş koyacağım

Yarını olmayan yarınları sil aklından

Canımla canına can katacağım

Korkma hiç bir şeyden gülüm

Ölümden bile! 

Senin için ölüm döşeklerinde yatacağım

Her gün bin kez ölüp, 

Seni yaşatacağım...', 'En uzakların ötesinde de olsan Uzaklardan korkma Uzat elini tutacağım Sana toz konmamış yollar açacağım Dipsiz gecelerde kalsan Zamansız doğ...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":18,"source_url":"https://www.antoloji.com/ugrunda-olum-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vazgeçilmiş Zamanlar', 'vazgecilmis-zamanlar-hakan-altincekic-312jc', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Yaklaşık iki kişi kadardık! 

Bir sonraki yıl

      hasadı da birlikte kaldıracağımıza söz vererek, 

      vazgeçilmiş zamanlarımızı

      nadasa bıraktık Taksim Parkı''nda!', 'Yaklaşık iki kişi kadardık!  Bir sonraki yıl       hasadı da birlikte kaldıracağımıza söz vererek,        vazgeçilmiş zamanlarımızı       na...', ARRAY['Türk Edebiyatı','Şiir','Hakan Altınçekiç']::text[], 8.5, '{"poet":"Hakan Altınçekiç","poet_slug":"hakan-altincekic","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/vazgecilmis-zamanlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eminim ki Biliyorlar!', 'eminim-ki-biliyorlar-hakan-altincekic-uvo54', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İyi insanlar biliyorlar demek

            cennette çok az yer kaldığını ki, 

            sanki yarışırcasına birbirleriyle, 

            ardı ardına ölüyorlar...', 'İyi insanlar biliyorlar demek             cennette çok az yer kaldığını ki,              sanki yarışırcasına birbirleriyle,              ard...', ARRAY['Türk Edebiyatı','Şiir','Hakan Altınçekiç']::text[], 8.5, '{"poet":"Hakan Altınçekiç","poet_slug":"hakan-altincekic","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/eminim-ki-biliyorlar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yalan Gelirdi Hep', 'yalan-gelirdi-hep-gurcan-gunay-hijem', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Biteceğine inanmazdım bir türlü

Ayrılık mı? 

Asla, diyordum, 

Hep kendi kendime...

Doyumsuzca yaşıyordum

Senle dolu zamanları

Öpüyor öpüyordum

Dudağında açan kızıl gülleri

Gitsen hani bir gün

Nasılsa dönecek diyordum

Ayrılıksa batan güneş

Doğacak güneş vuslattı

Biliyordum...

Nasıl da unutmuşum ahh! 

Ölümsüz oluşunu ayrılıkların

Sonsuz sanılan aşkların

Hep böyle son buluşunu! 

Öylesine aptal olmalıyım ki

Hala kabullenemedim

Bu apansız gidişini

Ayrılık hala yalan gibi

Geçmiş, 

Bir tatlı gülüş, 

Birkaç öpüş...

Uyandığımda bir sabah

Bitiverdi o pembe düş

Ayrılırken ağlamak bile gelmedi aklıma

Dağ gibi ümit saklıydı içimde

Elbet gelecektin

Çıkıp gittiğin kapıdan bir gün

Sevmek inanmaktı

Bağlanmaktı ölesiye

Ayrılık bize günah

Sevişmek sonsuz sevabımızdı

Ahh o mel''un akşam! 

Çalındı kapım belli belirsiz

O meçhul misafirle

Bir meçhule yollandın o akşam

Keşke inanabilseydim

Yalan olduğuna bu gidişin

Görüpte gözlerinde 

İki damla yaş! 

Düşerken ağına acıların

Uyandım gerçeklere

Yaşadığım kısa düşten

Ölümü yaşadım uğruna...

İşte o andı ilk defa

Fark ettim döndüğünü dünyanın

Ve ilk defa sende gördüm

Örneğini vefasızlığın...', 'Biteceğine inanmazdım bir türlü Ayrılık mı?  Asla, diyordum,  Hep kendi kendime... Doyumsuzca yaşıyordum Senle dolu zamanları Öpüyor öpüyord...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":50,"source_url":"https://www.antoloji.com/yalan-gelirdi-hep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşkı Tarif', 'aski-tarif-gurcan-gunay-d9ycu', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Gün olur da hani ansızın

Bir şey kıpırdar derinde bir yerde

Sanki bir cami avlusundan

Bir avuç güvercin kanatlanır

Gönül içre kayalardan

Bir-iki damlacık akışır

Mahçupluğun yüzüne vurur

Yanakların al al olur

Narin kanatlarınla

Zevk verir gönül gezdirmek

Bahar coşkunu arı misali

O çiçek senin bu çiçek benimdir

Eğilip abu hayat ırmağına

Yavru ceylan gibi

Kana kana içmek istersin

İki yeşil ürkek mekik 

Türlü motifler dokur gözlerinde

Saçların ilmek ilmek ipektir

Alımlı çalımlı savrulur

Bahar meltemlerinde

Ağzında bir bebek dili

Anlatamaz içindekini

Bir deli kan damarlarında

Yüreğinde sonsuz heyecan

Seni böyle daldan dala uçuran

Seni deli dolu yapan

Bir AŞK vardır...', 'Gün olur da hani ansızın Bir şey kıpırdar derinde bir yerde Sanki bir cami avlusundan Bir avuç güvercin kanatlanır Gönül içre kayalardan Bir...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":27,"source_url":"https://www.antoloji.com/aski-tarif-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ellerin', 'ellerin-kadircan-keskinbora-yao0b', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Etrafım dedikodu

Tepemde leş kargaları

Arkamda tufan

Önümde yokuşlar

Çalkantılar, 

Kaygan zemin

Bu fırtınalı denizde

Sakin bir koydur

Ellerin...', 'Etrafım dedikodu Tepemde leş kargaları Arkamda tufan Önümde yokuşlar Çalkantılar,  Kaygan zemin Bu fırtınalı denizde Sakin bir koydur Elleri...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/ellerin-7-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Talep', 'talep-kadircan-keskinbora-phv0a', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Buraları karanlık, 

Soğuk ve çamur.

Gelirken yanında güneş de getir, 

Ne olur!', 'Buraları karanlık,  Soğuk ve çamur. Gelirken yanında güneş de getir,  Ne olur!...', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/talep-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anlatı', 'anlati-kadircan-keskinbora-dk6km', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Nöbeti tutmuş sıtmalıya

Oluk oluk çatlamış toprağa

İftar vaktinde yaz oruçlusuna

Suyun anlamıyla eşdeğersin.', 'Nöbeti tutmuş sıtmalıya Oluk oluk çatlamış toprağa İftar vaktinde yaz oruçlusuna Suyun anlamıyla eşdeğersin....', ARRAY['Türk Edebiyatı','Şiir','Kadircan Keskinbora']::text[], 8.5, '{"poet":"Kadircan Keskinbora","poet_slug":"kadircan-keskinbora","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/anlati-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Herzamanki Gibi', 'herzamanki-gibi-cemal-cetin-2-tgx0z', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bu gece

Seni düşünüp uyuyacağım yine.

Kalkmak 

Ölüm olacak yarın.

Sarhoşluğunda

Voltalayacağım geceyi.

Ve aynı sarhoşluğun başağrısı, 

Sabahleyin.

Çekeceğim

Herzamanki gibi...', 'Bu gece Seni düşünüp uyuyacağım yine. Kalkmak  Ölüm olacak yarın. Sarhoşluğunda Voltalayacağım geceyi. Ve aynı sarhoşluğun başağrısı,  Sabah...', ARRAY['Türk Edebiyatı','Şiir','Cemal Çetin 2']::text[], 8.5, '{"poet":"Cemal Çetin 2","poet_slug":"cemal-cetin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/herzamanki-gibi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İnciraltı', 'i-nciralti-cemal-cetin-2-t4p30', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'İnciraltı; 

Kıyıboyu rüzgar, 

Kıyıboyu dalgalar.

Bittiğinde nefesim, 

Islığımı alıp

Çalıyor martılar...', 'İnciraltı;  Kıyıboyu rüzgar,  Kıyıboyu dalgalar. Bittiğinde nefesim,  Islığımı alıp Çalıyor martılar......', ARRAY['Türk Edebiyatı','Şiir','Cemal Çetin 2']::text[], 8.5, '{"poet":"Cemal Çetin 2","poet_slug":"cemal-cetin-2","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/inciralti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Güvercin', 'bir-guvercin-cetin-kural-cgvgd', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Seni bana her sabah, 

Kanatlarında mavilik taşıyan, 

Bir güvercin getirir.

Tıkırdatıp camı, 

Bırakıp gider.

Usulcacık...', 'Seni bana her sabah,  Kanatlarında mavilik taşıyan,  Bir güvercin getirir. Tıkırdatıp camı,  Bırakıp gider. Usulcacık......', ARRAY['Türk Edebiyatı','Şiir','Çetin Kural']::text[], 8.5, '{"poet":"Çetin Kural","poet_slug":"cetin-kural","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/bir-guvercin-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kurşun', 'kursun-gurcan-gunay-dpsks', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sık bir kurşun yüreğimin ortasına

Cansız yığılayım bir gün yol ortasına

Ne sen bana, ne ben sana diyelim

Öleyim ki ben, kurtuluşun olur senin', 'Sık bir kurşun yüreğimin ortasına Cansız yığılayım bir gün yol ortasına Ne sen bana, ne ben sana diyelim Öleyim ki ben, kurtuluşun olur seni...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/kursun-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İçimde Azan Pişmanlık', 'i-cimde-azan-pismanlik-gurcan-gunay-qrvom', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'İşin farkına vardım nice sonra

Özleyeceğim seni

Son zamanlar içimde bir sıkıntı

Başımda bir duman

Derdi çok dağlar gibiyim

Hani patlayacağım dokunsalar

Anlıyorsun derdimi

Özleyeceğim seni

Bu gece dün geceden daha uzun

Şarkılar daha manalı

İçimde bir başka hüzün

İçkim sigaram yok bilirsin

Ama gel gör sarhoş gibiyim

Ellerim titriyor sinirden

Yalan değil anladım

Özleyeceğim seni

Türlü hüzünler yaratıp kendime

Saatlerce yürüyorum akşamları

Dudaklarım tir tir titriyor

Ağlasam ağlarım o dakika

Lakin o aptal mahçupluğum

Gücüm kalmadı artık

Özleyeceğim seni

Kimseyle anlaşamaz oldum

İstemeden kırıyorum herkesi

Avutmuyor teselli etmiyor

Hiç kimse hiçbir şey

Çekilmez oldum

Anlaşılmaz oldum

Hani bir zamanlar

Seni aramam özlemem demiştim ya! 

Unut onu! 

Seni çok özleyeceğim.', 'İşin farkına vardım nice sonra Özleyeceğim seni Son zamanlar içimde bir sıkıntı Başımda bir duman Derdi çok dağlar gibiyim Hani patlayacağım...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":33,"source_url":"https://www.antoloji.com/icimde-azan-pismanlik-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hasret', 'hasret-gurcan-gunay-30l1h', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Yokluğun içime çöktü ağır

Bir mahzun çocuk gibi ezildim

Eridim elemle ağır ağır

Hasretini çekmek neymiş bildim', 'Yokluğun içime çöktü ağır Bir mahzun çocuk gibi ezildim Eridim elemle ağır ağır Hasretini çekmek neymiş bildim...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/hasret-52-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçtim Bu Sevdadan', 'gectim-bu-sevdadan-gurcan-gunay-m2rgy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Küçük çaylarda aktın çağladın sen

Bu ummanlarda boğulamazsın

İçimde bir mum gibi ağır ağır erirken 

Gözyaşlarınla bende çoğalamazsın

Nafile insaf dileme, yalvarma boşuna

İçimde aşktan yana ne var ne yok söndü

Köreldi bütün sevmek duygularım

Ağlayıp yalvardığım günler dündü', 'Küçük çaylarda aktın çağladın sen Bu ummanlarda boğulamazsın İçimde bir mum gibi ağır ağır erirken  Gözyaşlarınla bende çoğalamazsın Nafile ...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gectim-bu-sevdadan-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gülseren', 'gulseren-gulseren-onay-ml0w9', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Gülüm dedım sana sevdim senı delıce

Üzülmedım senı severken sevdıkten sonra acını hıssettım

Leylaklar sundum sana yureğımdekı bahcemden

Sevdım senı delı gıbı adam gıbı

Ellerını tutamasam da gözlerıne bakamasam da

Rüzgarlarda dınledım gönlündekı sesını

En büyük sevdamı sundum sana

Ne sahte nede yalan gercek sevgı', 'Gülüm dedım sana sevdim senı delıce Üzülmedım senı severken sevdıkten sonra acını hıssettım Leylaklar sundum sana yureğımdekı bahcemden Sevd...', ARRAY['Türk Edebiyatı','Şiir','Gülseren Onay']::text[], 8.5, '{"poet":"Gülseren Onay","poet_slug":"gulseren-onay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gulseren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İlk Bahar', 'i-lk-bahar-gurcan-gunay-qskug', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bu ilk mutlu bahar gelen

Bu ilk uyanış seninle dal tomurcuk

Heyecan dolu dolu içimde

Hayat bulmada içimdeki çocuk

Daha bir güzel ötmede kuşlar

Dereler daha dolu akmada sanki

Seninle yeniden doğdum inan ki

Hoşgeldin ömrüme ''ilk'' baharım!', 'Bu ilk mutlu bahar gelen Bu ilk uyanış seninle dal tomurcuk Heyecan dolu dolu içimde Hayat bulmada içimdeki çocuk Daha bir güzel ötmede kuşl...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/ilk-bahar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutlu Son', 'mutlu-son-elif-gultekin-swvt1', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Takvimden kopan her yorgun yaprak, 

Yaklaştırır beni biraz biraz uzağa.

Sokaklara salıverdiğim çocukluğum, 

Yavaş yavaş kaybolur karanlıklarda...

Kendime soramadan ne olduğunu, 

Gençliğim geçer koşa koşa kapımdan...

Daha bitirememişken  gençliğin oyununu, 

Bahar biter yaklaşırım sona doğru...

Günler uzar artık, yaz gelmiştir, 

Gitmek bilmez güneş uzak diyarlara.

En olgun meyvesini verir ağaç.

Tek tek düşer sonra meyveleri, 

Üzüntüden yaprakları dökülür...

Ansızın çıkagelen rüzgar, 

Hayatıma sonbaharı getirir.

Hiddetle yağan yağmur, 

Yorar yağan kar beni...

Sonsuzluk değil ya bu, 

Son yaprak da düşecek, 

Sevdiğinin yüzünden, 

Damlalar süzülecek.

Son sanırsın belki sen, 

Buruşmuştur ellerin, 

Titriyordur bedenin, 

Mutlu sonu beklerken, 

Heyecanlıdır yüreğin...

Son yorgun yaprak da düşerken takviminden, 

Yolculuk vakti gelir, sana göre çok erken...

Sevdiklerin bakarken gözleri yaşla dolu, 

Sen huzura kavuşmuş, yaşarsın mutlu sonu', 'Takvimden kopan her yorgun yaprak,  Yaklaştırır beni biraz biraz uzağa. Sokaklara salıverdiğim çocukluğum,  Yavaş yavaş kaybolur karanlıklar...', ARRAY['Türk Edebiyatı','Şiir','Elif Gültekin']::text[], 8.5, '{"poet":"Elif Gültekin","poet_slug":"elif-gultekin","theme":"Türk Şiiri","is_hero":false,"total_lines":30,"source_url":"https://www.antoloji.com/mutlu-son-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bırak', 'birak-muzaffer-ali-karaoglu-7md2w', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Senin gözlerindir beni sana bağlayan

Senin sözlerindir ta içlerimde ağlayan

Yokuşu tırmanırken yağmurda ayaklarım

Yalın bir düşünceyle sana kilitli aklım

Çektiğim her nefesimdesin sen

Boşlugu yırtan sesimdesin sen

ne karanlık boğuyor geceyi

Ne çığlıklar susturuyor o tek heceyi

Gündüzümde sen gecemde sen

Çığlık olan tek hecemde sen

Aramız uzak  sana gelemem belki

Ellerini tutup seni sevemem belki

Ama olsun sen beni seviyorsun ya

Bana biricik aşkım diyorsun ya

Bende seni seviyorum canımdan cok

Uğrunda yapamayacağım tek şey yok

güneşi getir de getireyim sana 

çırılçıplak gireyim yanan bir volkana

dağlar aşıp sana geleyim

bırakma beni kucağında öleyim', 'Senin gözlerindir beni sana bağlayan Senin sözlerindir ta içlerimde ağlayan Yokuşu tırmanırken yağmurda ayaklarım Yalın bir düşünceyle sana ...', ARRAY['Türk Edebiyatı','Şiir','Muzaffer Ali Karaoğlu']::text[], 8.5, '{"poet":"Muzaffer Ali Karaoğlu","poet_slug":"muzaffer-ali-karaoglu","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/birak-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terzi', 'terzi-i-lyas-tunc-qhufi', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Uzak bir yıldızdı belki

Özenle teğelleyengeceyi

Tanrıların ermiş terzisi

Hızına erişilmez imgenin

Sakladım bu yüzden acısını

Yüksüğe sürtünen iğnenin

Derken ansızın sağanak

Yıldızlar indirdi kepengi

Tanrılar kalmıştı çıplak', 'Uzak bir yıldızdı belki Özenle teğelleyengeceyi Tanrıların ermiş terzisi Hızına erişilmez imgenin Sakladım bu yüzden acısını Yüksüğe sürtüne...', ARRAY['Türk Edebiyatı','Şiir','İlyas Tunç']::text[], 8.5, '{"poet":"İlyas Tunç","poet_slug":"i-lyas-tunc","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/terzi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bendeki Sen', 'bendeki-sen-melik-kurt-ez0sv', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Sessizlik karanlığa kur yapmaya başladığında, 

Rüzgarın adı meltem olduğunda, 

Bulutlar hayaline bürünüp semada toplandığında, 

Kolların yağmur olup beni sardığında, 

Yapraklar bana adını sorduğunda, 

Doğar bir parıltı içimde, yansır dağa, derki; özledim, 

Yansır yıldıza, derki; hasretim, 

Yansır aya  derki; susadım, 

Yansır güneşe, söner ateşi, 

Kıskanır görünce bendeki seni....', 'Sessizlik karanlığa kur yapmaya başladığında,  Rüzgarın adı meltem olduğunda,  Bulutlar hayaline bürünüp semada toplandığında,  Kolların yağ...', ARRAY['Türk Edebiyatı','Şiir','Melik Kurt']::text[], 8.5, '{"poet":"Melik Kurt","poet_slug":"melik-kurt","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/bendeki-sen-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Benzer-im-(si)', 'benzer-im-si-emre-altinok-lxefy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çin yemeğine benzer yüreğim.

Titiz ve ince...

İnce sopalarla yüzeyden karışırım.

Bozguna uğramaz yüzeyden başlarım herşeye

Çin yemeği gibi kurcalanır

Kapaktakiler fırlar, takıntılar çıkar

Beyazdan siyaha dönüşüverir herşey..

Sigaraya benzer hayatım! bir fırt çekerim

Kültablasına koyarım, sonra unutuveririm.

Sigara yanar, yanar, söner

Bir fırtla yetinirim.kırmızıdan mora dönüşüverir herşey..

Gitara benzer sevgilim! herşeyimdir o! 

Teli koparsa telini takarım.

Hüzünlü olduğumda tıngırdarımisevinçli olduğumdada..

Maviden maviye dönüşüverir herşey..', 'Çin yemeğine benzer yüreğim. Titiz ve ince... İnce sopalarla yüzeyden karışırım. Bozguna uğramaz yüzeyden başlarım herşeye Çin yemeği gibi k...', ARRAY['Türk Edebiyatı','Şiir','Emre Altınok']::text[], 8.5, '{"poet":"Emre Altınok","poet_slug":"emre-altinok","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/benzer-im-si-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sensiz', 'sensiz-fatih-gunaydin-86c3e', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Bir boşluğa bakıyorum sessiz, 

                     bir yabancı gözüyle bakıldığında belkide 

yaşıyorum seni sensiz...............', 'Bir boşluğa bakıyorum sessiz,                       bir yabancı gözüyle bakıldığında belkide  yaşıyorum seni sensiz..................', ARRAY['Türk Edebiyatı','Şiir','Fatih Günaydın']::text[], 8.5, '{"poet":"Fatih Günaydın","poet_slug":"fatih-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/sensiz-27-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İkimizde', 'i-kimizde-serdar-sonmez-ipfgs', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'ikimizde aynı günde doğmuşuz

Sen doğarken kuş tüyü mindere ben dağalarda

kar üstüne düşmüşüm

Oyas ikimizde aynı günde doğmuşuz

Senin hüzünlerin, benim; oyuncakları olmuş

Oysa ikimizde aynı günde doğmuşuz

Ve, bir gün  ikimizde öleceğiz

Senin mermerden mezarın, benim; yatacağım yer meçhul kalacak.

Ama öbür dünyada senin tanrıya vereceklerin, 

 benim ise, 

 alacaklarım  olacak....', 'ikimizde aynı günde doğmuşuz Sen doğarken kuş tüyü mindere ben dağalarda kar üstüne düşmüşüm Oyas ikimizde aynı günde doğmuşuz Senin hüzünle...', ARRAY['Türk Edebiyatı','Şiir','Serdar Sönmez']::text[], 8.5, '{"poet":"Serdar Sönmez","poet_slug":"serdar-sonmez","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/ikimizde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Zaman', 'zaman-fatih-gunaydin-3gat8', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Deva olurdu geçtikçe dertlerimize zaman, 

bilseydik, neleri götürdüğünü candan, 

hıçkırarak ağlardık belki o ZAMAN.....................', 'Deva olurdu geçtikçe dertlerimize zaman,  bilseydik, neleri götürdüğünü candan,  hıçkırarak ağlardık belki o ZAMAN........................', ARRAY['Türk Edebiyatı','Şiir','Fatih Günaydın']::text[], 8.5, '{"poet":"Fatih Günaydın","poet_slug":"fatih-gunaydin","theme":"Türk Şiiri","is_hero":false,"total_lines":3,"source_url":"https://www.antoloji.com/zaman-26-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Unutma Gülüm', 'unutma-gulum-gurcan-gunay-2q1mt', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Bu bir dünyayı fanidir ki

Nice yangınlar söner biter

Alevi kalmaz deli gönlün

Sonu bir ince duman tüter

Yanaklarında yaş izleri

Birkaç avuç kül ocağında

Ellerinde ölgün soğukluk

Canın ölüm salıncağında

Ne izin kalır ne hatıran

Yakılır kalan en son resim

Unutulur bir gün her şeyin

Kalır kütükte bir tek ismin

Bir günlüktür o gözyaşları

Arkası düğünler şölenler

Bir iki gün hatırlanır

Sonra unutulur ölenler

Korkarım unutursun sen de

Yarın başkasının olursun

Ben o küçük odamda yalnız

Sen cümbüşlerde kaybolursun

Mum gibi eriyorum her gün

Adım adım gelmede ölüm

Son bir dileğim kaldı senden

Beni asla unutma gülüm', 'Bu bir dünyayı fanidir ki Nice yangınlar söner biter Alevi kalmaz deli gönlün Sonu bir ince duman tüter Yanaklarında yaş izleri Birkaç avuç ...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":24,"source_url":"https://www.antoloji.com/unutma-gulum-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersem Bir Gün...', 'gidersem-bir-gun-gurcan-gunay-uxn17', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Gitsem bir gün bu elden

Kim tutar o yumuk ellerini? 

O hep korktuğun eller mi? 

Kim sarar geceleri seni? 

Korkutmaz mı yalnızlık? 

Ürpermez misin karanlıkta? 

Üstüne üstüne gelmez mi duvarlar? 

Eşyalar seninle konuşur mu? 

Avutur mu pencere önleri? 

Nasıl dizilir lokmalar boğazına

Dönmez mi gözlerin kan çanağına? 

Ağıtlar getirir mi beni sana

Gitsem bir gün bu elden?', 'Gitsem bir gün bu elden Kim tutar o yumuk ellerini?  O hep korktuğun eller mi?  Kim sarar geceleri seni?  Korkutmaz mı yalnızlık?  Ürpermez ...', ARRAY['Türk Edebiyatı','Şiir','Gürcan Günay']::text[], 8.5, '{"poet":"Gürcan Günay","poet_slug":"gurcan-gunay","theme":"Türk Şiiri","is_hero":false,"total_lines":13,"source_url":"https://www.antoloji.com/gidersem-bir-gun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Görünmeyen Dost', 'gorunmeyen-dost-eraai-davrazli-0eied', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Davrazda bembeyaz kar vardır

Üstünde kayıcı günahkar vardır

Seni unutmayan, telini bekleyen vardır

Birbirlerini çok seven dostlar vardır.

Bakar ama görmeyen gözler, vardır

Sözer ama umduğunu bulamayan, gözler vardır

Yılanı deliğinden çıkaran, sözler sözler vardır

Aşığı usandıran, nazlar vardır.

milleti bıktıran, gazlar vardır

Avcıyı peşinden koşturan, kazlar vardır

Bu milletin içinde sevimli, kızlar vardı

İnsanı yerinden hoplatan sazlar vardır.

Benim unutamadığım, yazlar vardır

Okuyupta ağladığım yazılar, vardır

Üzüntüye gark eden, güzle vardır

Umutla baktığım seziler, vardır.', 'Davrazda bembeyaz kar vardır Üstünde kayıcı günahkar vardır Seni unutmayan, telini bekleyen vardır Birbirlerini çok seven dostlar vardır. Ba...', ARRAY['Türk Edebiyatı','Şiir','Eraai Davrazlı']::text[], 8.5, '{"poet":"Eraai Davrazlı","poet_slug":"eraai-davrazli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/gorunmeyen-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Öldürdüğün Günü Hatırla', 'oldurdugun-gunu-hatirla-veli-altioglu-e76dy', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gittiğin günü hatırlasana 

Hani inadına güldüğün günü 

Ben bir köşede boynu bükük 

Seninse dimdik yürüdüğünü 

Sahte mutluluk dağıttığın 

Sonra da kızgınca baktığın 

Öylece mahzun bıraktığın 

O kahrolası günü hatırla. 

Hatırla veda etmeyişini 

Allanıp pullandığın günü 

Yüreğimi paramparça edip 

İnadına inadına güldüğünü 

Gurur, kibir, endamlıca 

Yürüyordun salına salına 

Kendinle baş başa kaldığında 

Beni öldürdüğün günü hatırla', 'Gittiğin günü hatırlasana  Hani inadına güldüğün günü  Ben bir köşede boynu bükük  Seninse dimdik yürüdüğünü  Sahte mutluluk dağıttığın  Son...', ARRAY['Türk Edebiyatı','Şiir','Veli Altıoğlu']::text[], 8.5, '{"poet":"Veli Altıoğlu","poet_slug":"veli-altioglu","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/oldurdugun-gunu-hatirla-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Neler', 'neler-tevfik-basar-woqcr', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Neler

Yani ne Sairler gecti 

bu memleketten

Hepsinin yazdiklarini

sana uyarladim

Ozellikle de

ask uzerine olanlarini

Sabah kaktim siir

Aksam yattim siir

bu ne bicim sihir.

Seni sevdigim zaman

gunes bir baska dogdu

Bu duyguyu kolay kolay ifade edemedim

siirlerimde

Hersey karmasik bir hava aldi

yinede hosgeldin

Ne kadar yalnizmisim 

gelince hissettirdin.

Seninle tadini aldim yedigim yemegin

susayinca ictigim suyun

Seninle gormeyi ogrendim

kime baksam sendin

Bu kadarmi derindin

icimdeki yerini seni taniyinca hissettim.

Seni hep sevdim

hic mola vermeden

Seninle saygi duydum aska inanmasamda 

bir zamanlar.

Saygi duydugum hersey seninle bicimlendi.

Ve her zaman kalbim sana defalarca ve durmadan 

tesekkur etti.', 'Neler Yani ne Sairler gecti  bu memleketten Hepsinin yazdiklarini sana uyarladim Ozellikle de ask uzerine olanlarini Sabah kaktim siir Aksam...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Başar']::text[], 8.5, '{"poet":"Tevfik Başar","poet_slug":"tevfik-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":31,"source_url":"https://www.antoloji.com/neler-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Biz', 'biz-tevfik-basar-uml4q', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Beni degisik ve hic alisilmadik renklerin

diyarina gotur.

Buralari layik gorme

ikimize.

Askimiz okyanuslari gecsin

yeniden dogduralim kendimizi.

sanki gormeyi becerilebilecek

ruyalar gibi

Ekmek kavgasi degil benimkisi

o da var icabinda ama 

bu o degil

Bambaska birsey bendeki

seni bana anlatana dogru 

yonelmem

Ruhunun golgesinde 

dans etmeye  calismam.

Heybeme senin kadar guzel

ve manali birsey aramam.

Bunlarin hepsi gelir gecer

unutmaki bir zamanlar seni cok seven 

biri vardi.

Akibete kapildi

suruklendi boyuna

ve simdi geldigi yerde 

keske sana benzer birsey

olsaydi.', 'Beni degisik ve hic alisilmadik renklerin diyarina gotur. Buralari layik gorme ikimize. Askimiz okyanuslari gecsin yeniden dogduralim kendim...', ARRAY['Türk Edebiyatı','Şiir','Tevfik Başar']::text[], 8.5, '{"poet":"Tevfik Başar","poet_slug":"tevfik-basar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/biz-16-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sadece Kendi Umutların Olsun', 'sadece-kendi-umutlarin-olsun-sait-ferhat-ozmen-6ozto', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Umutsuz bir bekleyiş ise sende herşeyin

Bölük pörçük duyguların karmaşası ise sendeki harkuladelik

Neye olduğunu bilmeden duyulan bir özlemse seninki

Ve sevmeyi dahi beceremeyecek kadar çürümüşse yüreğin

Yazık ediyorsun canım kendine ve o güzel hayallerine...

Çevrilmez zannettiğin suların 

Kolay olmasada zapdedilebileceğini anlamak istemiyorsan

Geçmişte yaşanan olayları senden geri getirilmesi imkansız şeyleri alıp götürdüğüne inanmak hoşuna gidiyorsa; 

Üstesinden gelmeyi düşünmediğin bir hayatın seni öğütmesine aldırmamaksa şayet bu; 

Ve geceler her doğan yeni günün, yeni umutlar vaadettiğini hatırlatamayacak kadar acze düşmüşse sende! 

Herşeyi yeniden düşün! 

Ve bundan böyle mutluluk yolunda 

İleriye attığını zannettiğin adımların

Gerçekte yerinde saydığını görde...

BARİ YIKTIKLARIN SADECE KENDİ UMUTLARIN OLSUN.', 'Umutsuz bir bekleyiş ise sende herşeyin Bölük pörçük duyguların karmaşası ise sendeki harkuladelik Neye olduğunu bilmeden duyulan bir özlems...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sadece-kendi-umutlarin-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hayat', 'hayat-sait-ferhat-ozmen-kvpya', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Hayatın ince ince kemirdiğini hissederken seni, 

Tutunduğun her dal aslında sevdiğindir... 

Bazen kızarsın yanlış dal diye, 

Bazen de sarılırsın... 

Kızsan da, sarılsan da, 

Seni kurtaranın o dal olduğunu anladığında, 

Ya utanacaksındır, 

Yada gururlanacak... 

Sen hep başı dik ve gururlu olmayı tercih et 

Ki... 

Bir gün sarılınacak O dal olabil...', 'Hayatın ince ince kemirdiğini hissederken seni,  Tutunduğun her dal aslında sevdiğindir...  Bazen kızarsın yanlış dal diye,  Bazen de sarılı...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/hayat-40-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ağlama', 'aglama-sait-ferhat-ozmen-slxuk', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Ağladıkça ağlayasım geliyor			

Hemde hıçkıra hıçkıra haykıra haykıra			

Sonra vazgeçiyorum ağlamaktan			

Anlatasım geliyor			

Derdimi sevincimi beni			

Bakıyorum etrafıma boş			

Kaldığım yerden devam ediyorum 			

AĞLAMAYA', 'Ağladıkça ağlayasım geliyor			 Hemde hıçkıra hıçkıra haykıra haykıra			 Sonra vazgeçiyorum ağlamaktan			 Anlatasım geliyor			 Derdimi sevinc...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/aglama-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gönül Dostu', 'gonul-dostu-sait-ferhat-ozmen-935a8', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Hani o ''''gönül dostu'''' varya		

İşte onun gerçek anlamıdır		

Gönülden sevmek		

Sevenler dosttur, 		

Dostlar sevgili.', 'Hani o ''''gönül dostu'''' varya		 İşte onun gerçek anlamıdır		 Gönülden sevmek		 Sevenler dosttur, 		 Dostlar sevgili....', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/gonul-dostu-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Geçmişe Bakış', 'gecmise-bakis-sait-ferhat-ozmen-1aw8n', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Çok sık hüzünlenirim ben				

Çok da sık ağlarım				

Sık sık geçmiş gelir aklıma				

Sonra da o geçmişi silemediğime kızarım...', 'Çok sık hüzünlenirim ben				 Çok da sık ağlarım				 Sık sık geçmiş gelir aklıma				 Sonra da o geçmişi silemediğime kızarım......', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":4,"source_url":"https://www.antoloji.com/gecmise-bakis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Doğrusu Aydı', 'dogrusu-aydi-sait-ferhat-ozmen-7ywzv', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Geceye baktım şöyle, doya doya			

Ay vardı içinde			

Önce ay''ı anlamaya çalıştım			

Herşeye ramen niye orda diye			

Sonra aynaya baktım			

Boştu			

Ay''a hak verdim işte			

Doğrusunu yapan oydu.', 'Geceye baktım şöyle, doya doya			 Ay vardı içinde			 Önce ay''ı anlamaya çalıştım			 Herşeye ramen niye orda diye			 Sonra aynaya baktım			 B...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dogrusu-aydi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Terbiye', 'terbiye-sait-ferhat-ozmen-qpbui', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir Asaf''ı severim ben aslında			

Duygusallaştığımda			

Unutmadan			

Birde Hayyam''ı çok severim hani			

Ne zamanki isyan çekse canım			

Küfür etmek istese			

Ama çekinirim.....', 'Bir Asaf''ı severim ben aslında			 Duygusallaştığımda			 Unutmadan			 Birde Hayyam''ı çok severim hani			 Ne zamanki isyan çekse canım			 Küfü...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/terbiye-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'İki Aşık', 'i-ki-asik-sait-ferhat-ozmen-si2xp', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yolda iki aşık gördüm bugün					

Önce çekindim onlara bakmaya					

Belki kızarlar diye					

Sonra vazgeçtim baktım doya doya 					

Aklıma geldi yaşadıklarım					

Sevgim için yaptıklarım					

Nasıl yürüdüğüm nasıl sarıldığım geldi aklıma önce					

Sonra da ayrıldıktan sonra yaptıklarım					

Düşündüm doğrumuydu yaptıklarım					

Baya bi sıkıldı canım önce					

Daraldım					

Üzüldüm, hatta utandım bile					

Sonra tekrar baktım o iki aşığa					

Döndün bi daha baktım					

Anladım.					

Severken ve birlikteyken yaptıklarım kadar					

Severken ve ayrıyken yaptıklarım da doğruydu					

Seven insan sevdiğinin mutluluğu için yapardı yaptıklarımı					

Yaptım.					

Döndüm birkez daha göreyim dedim o mutluluğu					

Döndüm ama yoktular					

Duygularımda onlarla beraber					

KAYBOLDU.......', 'Yolda iki aşık gördüm bugün					 Önce çekindim onlara bakmaya					 Belki kızarlar diye					 Sonra vazgeçtim baktım doya doya 					 Aklıma ge...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":23,"source_url":"https://www.antoloji.com/iki-asik-2-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Votka-Limon ve Yaptıkları', 'votka-limon-ve-yaptiklari-sait-ferhat-ozmen-5bj0t', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Siz votka-limonu bilirmisiniz						

İnsanı başta oynattığını						

Sonra sonra Müzeyyen Senar''ları, Zeki Müren''leri hatırlattığını						

Sonrasında Makber''i niye ben yazamadım dedirttiğini						

İçtikçe sevildiğini, sevildikçe hatırlattığını						

Hatırladıkça içildiğini.....						

Bilenler evet desin, 						

Bilmeyenler sadece dinlesin.......', 'Siz votka-limonu bilirmisiniz						 İnsanı başta oynattığını						 Sonra sonra Müzeyyen Senar''ları, Zeki Müren''leri hatırlattığını						 Son...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/votka-limon-ve-yaptiklari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Mutluluk?', 'mutluluk-sait-ferhat-ozmen-a1zyh', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Nedir mutluluk denen şey, 		

Sevdiğinle olmak mı? 		

Sevdiğin evcil bir hayvan ise		

Mutlumusundur yani? 		

Yoksa mutluluk sen olmak mı		

Senin seni kabullenmen mi		

Yada aldığın nefesi hissedebilmen mi?', 'Nedir mutluluk denen şey, 		 Sevdiğinle olmak mı? 		 Sevdiğin evcil bir hayvan ise		 Mutlumusundur yani? 		 Yoksa mutluluk sen olmak mı		 Se...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":7,"source_url":"https://www.antoloji.com/mutluluk-18-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek ve Özlemek', 'sevmek-ve-ozlemek-sait-ferhat-ozmen-j79yu', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Bir sevmeyi öğrenemedim ben, 	

Bir de sevgimi söylemeyi.	

Bir seni özlerim ben, 	

Bir de sana söyleyemediklerimi.	

Bir seni özlerim ben, 	

Bir de özlediğim seni.', 'Bir sevmeyi öğrenemedim ben, 	 Bir de sevgimi söylemeyi.	 Bir seni özlerim ben, 	 Bir de sana söyleyemediklerimi.	 Bir seni özlerim ben, 	 B...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/sevmek-ve-ozlemek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmenin Mahçubiyeti', 'sevmenin-mahcubiyeti-sait-ferhat-ozmen-2y6dz', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Sezsizlikteki beni seslendirdiğimde diyebileceğim ki, 				

Aslında sensin istediğim(sevdiğim)  				

Ne zaman yenersem mahçubiyetimi				

İşte o zaman diyeceğim, 				

Seni sevdiğimi.				

Belki aylar sürecek kaçınmalarım belki de yıllar				

Ama sonunda diyeceğim sana gerçeği				

Bir seven var seni				

Bir de mahçubiyeti.', 'Sezsizlikteki beni seslendirdiğimde diyebileceğim ki, 				 Aslında sensin istediğim(sevdiğim)  				 Ne zaman yenersem mahçubiyetimi				 İşte...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":9,"source_url":"https://www.antoloji.com/sevmenin-mahcubiyeti-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevmek ve Hissetmek', 'sevmek-ve-hissetmek-sait-ferhat-ozmen-g6gbk', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Sevmek aslında acı çekmek		

Acısını bile sevebilmek		

Sevmek aslında kabullenmek		

Yanlışını doğru bilmek		

Sevmek aslında sevdiğine		

Seni sevdim		

Seni  		

Sadece seni diyebilmek		

Buna inanmak		

Bunu hissetmek', 'Sevmek aslında acı çekmek		 Acısını bile sevebilmek		 Sevmek aslında kabullenmek		 Yanlışını doğru bilmek		 Sevmek aslında sevdiğine		 Seni ...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/sevmek-ve-hissetmek-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Başlangıç', 'baslangic-sait-ferhat-ozmen-seqea', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Kalp atışlarım hızlandı önce			

Sonra nefesim sıklaştı			

Birden hissedemez oldum beni			

Ve o anda bir ışık parladı			

Önce anlamadım, anlam veremedim hani			

Neydi bu, neyin alameti			

Sonra sonra anlamlaşmaya başladı			

Sağım aydınlık, solum ışık			

Önüm gülen yüzler, arkam mutluluk			

Öldüm sandım önce			

Korktum...			

Hani hakikaten patladı o ödüm, her nerdeyse..			

Sonra durdum			

Anlamaya, algılamaya çalıştım			

Nefes alıyordum ve tuttuğum herşey elime geliyordu			

Baktım korkum boşuna 			

Baktım kaygım nafile			

Ölseydim belki bitecekti			

Oysa sevdim			

Bu ise yeni bir başlangıç idi', 'Kalp atışlarım hızlandı önce			 Sonra nefesim sıklaştı			 Birden hissedemez oldum beni			 Ve o anda bir ışık parladı			 Önce anlamadım, anla...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/baslangic-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Kalem', 'kalem-sait-ferhat-ozmen-wvtdo', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Ne zaman elime alsam kalemi		

Hep birinedir.		

Neden ve niyedir bilemem.		

Ama ben hep birine yazarım		

Ne zamanki kalem elimden düşse, 		

Ben hep yeni birini ararım.......', 'Ne zaman elime alsam kalemi		 Hep birinedir.		 Neden ve niyedir bilemem.		 Ama ben hep birine yazarım		 Ne zamanki kalem elimden düşse, 		 B...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/kalem-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Ünal Küçük''e', 'unal-kucuk-e-sait-ferhat-ozmen-qhuas', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Seni ne eşinden ne de evlattalrından çok sevbilirim				

Seni sadece bir komşu olarak sevmektir hattim				

Birde küçüğün				

Ama ne zaman Zaide''mi dinlesem ağlarım				

Erken gidişine olduğu kadar				

Ulaşılmamış sevgine ağlarım				

Hey gidi Ünal Küçük				

Yanık sesinemi yanayım				

Almadığın nefesine mi				

Yoksa senden öğrenilmesi gereken				

Ama öğretemeden gittiklerine mi				

Erken gittin be Ünal Küçük 				

Çok erken....				

Ama gözün arkanda kalmasın				

Geride bıraktığın iki oğlun bir kızın kadar				

Birde seni sevenlerin var				

Onlarda sevgine sevgilerine sahip çıkmayı				

Senden öğrendi				

Senin ödülünde bu idi				

Mekanın cennet olsun.....!', 'Seni ne eşinden ne de evlattalrından çok sevbilirim				 Seni sadece bir komşu olarak sevmektir hattim				 Birde küçüğün				 Ama ne zaman Zai...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/unal-kucuk-e-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bir Adını Yazamadım', 'bir-adini-yazamadim-sait-ferhat-ozmen-nd8lg', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Şu söylemediklerin varya				

Şu benim bildiğim halde duymak istediklerim				

Aslında beni kızdırıyor tüm bu yaşananlar				

Ne sen bana zannettiğin kadar dürüstsün				

Ne de ben sana samimi				

İkimizdemi bilmiyoruz hissettiklerimizi				

İkimizde bilmiyormuyuz				

Tüm bunları sadece ikimizin çözeceğini				

				

Ne diye susuyoruz sanki				

Ne diye kandırıyoruz kendimizi				

Niye zarar veriyoruz duygularımıza				

Neden onları gömüyoruz karanlığa				

Bir sen varsın sadece				

Bir de ben varım sevginle				

Bu kadar mı zor				

Sevgini söylemek				

				

Biz bizi kandırıyoruz güzelim				

Ne ben senin gönül dostunum 				

Ne de sen benim........(biladerim)', 'Şu söylemediklerin varya				 Şu benim bildiğim halde duymak istediklerim				 Aslında beni kızdırıyor tüm bu yaşananlar				 Ne sen bana zanne...', ARRAY['Türk Edebiyatı','Şiir','Sait Ferhat Özmen']::text[], 8.5, '{"poet":"Sait Ferhat Özmen","poet_slug":"sait-ferhat-ozmen","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/bir-adini-yazamadim-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidişin', 'gidisin-suleyman-avci-zv65b', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'ben felaketi bugün yaşadım

saat 9

senin gidiş saatin

her adım atışında dokuz şiddetinde depremler oldu yüreğimde

yüreğim

sallandı

sallandı

atamadı seni hala...', 'ben felaketi bugün yaşadım saat 9 senin gidiş saatin her adım atışında dokuz şiddetinde depremler oldu yüreğimde yüreğim sallandı sallandı a...', ARRAY['Türk Edebiyatı','Şiir','Süleyman Avcı']::text[], 8.5, '{"poet":"Süleyman Avcı","poet_slug":"suleyman-avci","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/gidisin-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Yasak', 'yasak-gece-karasi-nfd3y', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gene bir gecenin bitimindeyim.

Bir günün sabahına doğru....

Seni düşünüyorum ümitsizce.

Biliyorum sen bana yasaksın.

Yüreğime anlatamıyorum.

Cıkmaz yol ayrımlarındayım.

Kör bir kuyuya atıyorum özlemlerimi..

Üzerini kapatamıyorum.

Sen bana uzaksın biliyorum.

Sen bana yasaksın biliyorum.

Yüreğime dur diyemiyorum.

Bu sevdaya bilerek düşmedim.

Gönlüme gel de gir demedim.

Sen bana yasaksın biliyorum.

Sen bana uzaksın biliyorum.

Sevdama son veremiyorum.! ! ! !', 'Gene bir gecenin bitimindeyim. Bir günün sabahına doğru.... Seni düşünüyorum ümitsizce. Biliyorum sen bana yasaksın. Yüreğime anlatamıyorum....', ARRAY['Türk Edebiyatı','Şiir','Gece Karası']::text[], 8.5, '{"poet":"Gece Karası","poet_slug":"gece-karasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/yasak-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Oğluma', 'ogluma-gece-karasi-qeu4n', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'elim varmadı sana yazmaya

Yaşlarımı yüreğime gömdüm bir tanem

hıckırıklar boğazımda düğüm düğüm, 

Sana özlemim gün gectikce artıyor, 

Ayrılığa isyan ediyorum.

Bebekliğin geliyor gözlerimin önüne, 

Yaşayamadığın cocukluğun! 

yıllar şerit gibi akıyor gözlerimden, 

Her karesi yüreğimi yakıyor...

Bir sabır diliyorum kendime Tanrıdan

sabrediyorum..

Vatan borcun bitecek elbet...

Sana hasretim dinecek...

dinecek ayrılık yaşlarım gözümde.

Bakma sen bana aldırma bir tanem, 

Vatana asker eyledim ya seni, 

Yaşlarım aksa da seller gibi, 

Asker anasıyım biliyorum, 

Ve bunun gururunu taşıyorum  bir tanem...! ! .', 'elim varmadı sana yazmaya Yaşlarımı yüreğime gömdüm bir tanem hıckırıklar boğazımda düğüm düğüm,  Sana özlemim gün gectikce artıyor,  Ayrılı...', ARRAY['Türk Edebiyatı','Şiir','Gece Karası']::text[], 8.5, '{"poet":"Gece Karası","poet_slug":"gece-karasi","theme":"Türk Şiiri","is_hero":false,"total_lines":19,"source_url":"https://www.antoloji.com/ogluma-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Beni Hatırla', 'beni-hatirla-gece-karasi-i1be8', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Bir gece gökyüzüne kaldırınca başını

Görürsen bir yıldızın kaydığını, 

Beni hatırla...  ...

Bir gece  icini  hüzün kaplar da.

yüreğin sıkılırsa sebepsiz.

Beni hatırla...

Bil ki bir yerlerde düşünen var, 

Bil ki bir yürek carpar  inceden, 

Bil ki hüzün kaplamış ruhunu, 

Hayata küsmüş  kadere küsmüş, 

Birini görürden sokağında, 

Beni hatırla...

Bir gün sessiz bir kalabalık, 

Dudaklarda donmuş hıckırıklarla, 

Eller üstünde taşınan bir yolcu, 

Ebedi uykusuna uğurlanıyorsa, 

Beni hatırla...

Birgün yolun düşerse eğer

Uzaklarda bir mezarlığa, üzülme sakın

Bir fatiha yolla Ruhuma, 

Gözünden süzülen bir damla yaşta, 

Beni hatırla....! ! !', 'Bir gece gökyüzüne kaldırınca başını Görürsen bir yıldızın kaydığını,  Beni hatırla...  ... Bir gece  icini  hüzün kaplar da. yüreğin sıkılı...', ARRAY['Türk Edebiyatı','Şiir','Gece Karası']::text[], 8.5, '{"poet":"Gece Karası","poet_slug":"gece-karasi","theme":"Türk Şiiri","is_hero":false,"total_lines":22,"source_url":"https://www.antoloji.com/beni-hatirla-9-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bu Sahilde', 'bu-sahilde-gece-karasi-63dko', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Gözü yaşlı gönlü kırık, 

Biri kaldı bu sahilde, 

Boğazında hıckırık, 

Dondu kaldı bu sahilde...

Yüreğinde bir acı, 

Gezer durur bu sahilde, 

Gözlerinde son umut, 

Arar durur bu sahilde...

Bir rüyaydı gördüğü, 

Sona erdi bu sahilde, 

Sana  tüm mutlulukları, 

Diliyorum o sahilde...

Kışı bilme baharı yaşa, 

Ben ağlarken bu sahilde, 

Hüzün sana uzak olsun, 

Daima gül o sahilde! ! !', 'Gözü yaşlı gönlü kırık,  Biri kaldı bu sahilde,  Boğazında hıckırık,  Dondu kaldı bu sahilde... Yüreğinde bir acı,  Gezer durur bu sahilde, ...', ARRAY['Türk Edebiyatı','Şiir','Gece Karası']::text[], 8.5, '{"poet":"Gece Karası","poet_slug":"gece-karasi","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/bu-sahilde-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Anadolu Garı', 'anadolu-gari-selcuk-yilmaz-woske', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Tozlu yollarından görünür  ırakta silueti öylece

Demişlerdi,  istasyon binası üç çeyrek saat ötede,

Yürüdüm,  ulaştım ince bir kuytuda  yolun sonuna

Vardım sivri çatılı koca binanın tam kıyıcığına,

Bilmem  gayrı ötesini, Anadolu’da bir taşra garı 

Gözümde büyüdü oracıkta, o  kasvetli binası, 

Dediler; Alman bir mimarın eseri 

Gayrı  bundan böyle hep aynıymış ötesi,

Durdum baktım konuşmak ister gibi,

Demir yolların arasında  oynaşmak ister gibi; 

    Ne bir kuş sesi ne de bir rüzgar esintisi

    Her yanı sarıvermiş  kara trenin isi,

    Bekleşir durur katar katar yaşlı vagonlar 

Sessizlik ve mor ötesi ufkunda kesişir makaslar, 

    Çalışır durur oracıkta birkaç demiryolu işçisi,

Mevsimlerden hazan, şunun şurası  zemheri

Değişiminde haykırır tüm benliğiyle doğa

Ufkunda gelmede bir mevsim gelin duvağıyla,

Sanki  hepsi birden  dile geliverircesine

Bu yaşlı istasyon neler  gördü geçirdi dercesine; 

     İlkin Kuvayi Milliyenin kurtuluş cephanesi

Sonrasında kara trenin cepheye götürdüğü şehit erleri,

     Demirle  sırt sırta yol aldı, geçip gittiler garba buradan

     Belki mola anı  içtiler bir yudum memleket suyundan; 

     Geçmişin  sıcaklığında  dalıp gitmişim uzaklara 

Gözümün ferinde yansır düşünceler hiç durmamacasına,

Apansız yansıdı bekleme salonunda  ki sobanın kızıllığı

Üşüyüverdi benliğim akşam zamanı duyumsarken o anı, 

Sobanın başında ısınır tulum giymiş bir iki duvar ustası,

     Köşede kasketi elinde, bir adam darmadağınık saçları; 

     Yanında durur öylece el pençe divan, yazgısına razı

 Basma entarili, yanık tenli cefakar bir köy kadını,

     Aşmış gibi ölümsü yolları, kucağında zayıf bir  bebesi 

Sessizce emer durur o körpe anacığını gizli gizli, 

Daha iki saat var, dediler posta trenine

     Kızıllığa birleşiverdi canlar, duman altı sessizliğinde, 

Kasketi yan dönmüş yaşlı  adam, yüzünde uzun çizgiler

Anadolu  Garında, posta trenini beklerken birer birer...

                                                                                         O. Selçuk YILMAZ

                                                                                                     İzmir/2004', 'Tozlu yollarından görünür  ırakta silueti öylece Demişlerdi,  istasyon binası üç çeyrek saat ötede, Yürüdüm,  ulaştım ince bir kuytuda  yolu...', ARRAY['Türk Edebiyatı','Şiir','Selçuk Yılmaz']::text[], 8.5, '{"poet":"Selçuk Yılmaz","poet_slug":"selcuk-yilmaz","theme":"Türk Şiiri","is_hero":false,"total_lines":40,"source_url":"https://www.antoloji.com/anadolu-gari-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vefalı Dost', 'vefali-dost-aysun-elagoz-qit56', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Sen ki

Beni hiç terketmeyen, 

Ömrümün her anında hep yanımdaydın....

Herşeyi paylaştık seninle

Sevgiyi, hüzünleri, 

Ve hatta her nefesi..

Sen ki

En vefalı dosttan bile vefalı

Sevgili yalnızlığım..

Seni seviyorum.', 'Sen ki Beni hiç terketmeyen,  Ömrümün her anında hep yanımdaydın.... Herşeyi paylaştık seninle Sevgiyi, hüzünleri,  Ve hatta her nefesi.. Se...', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":10,"source_url":"https://www.antoloji.com/vefali-dost-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Gidersen...', 'gidersen-aysun-elagoz-lejb9', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Gidersin 

Sensizliğin kalır bende, 

Susarsın sessizliğin.

Gidişin 

Ölümüm değil, 

Gidişin özlememdir..', 'Gidersin  Sensizliğin kalır bende,  Susarsın sessizliğin. Gidişin  Ölümüm değil,  Gidişin özlememdir.....', ARRAY['Türk Edebiyatı','Şiir','Aysun Elagöz']::text[], 8.5, '{"poet":"Aysun Elagöz","poet_slug":"aysun-elagoz","theme":"Türk Şiiri","is_hero":false,"total_lines":6,"source_url":"https://www.antoloji.com/gidersen-4-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Bebeğim', 'bebegim-ethem-vayvayli-wfkw8', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Karanlık temmuz akşamları

Yollarını ben bekledim

İndirdim hep yıldızları

Işığına nur ekledim

Kurumuş dudaklarında 

Nisan Yağmuru kokladım

Yalnız kalmış bu sevdana

Doksan yıldır yâr aradım

Ülkemin son vuslatında

Özlemimi gidermiştim

Yürüyordun at sırtında

Ben hep sana imrenmiştim

Doğruldun cihana yürek

Gün dediğin gün gelecek

Sevdam buket buket olup

Karanfili dost bilecek

Haydi tut da ellerimi

Gözlerinden bir öpeyim

Çekinmeden tüm mazimi 

Sana emanet edeyim', 'Karanlık temmuz akşamları Yollarını ben bekledim İndirdim hep yıldızları Işığına nur ekledim Kurumuş dudaklarında  Nisan Yağmuru kokladım Ya...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":20,"source_url":"https://www.antoloji.com/bebegim-11-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Umutlarım Beni Sana Getiren', 'umutlarim-beni-sana-getiren-ethem-vayvayli-r0rg2', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Günlerdir dalgın dalgın gezerim

Çekilmez çileler bitmez dertlerim

Hergün bin kez mürde olur bedenim

Umutlarım beni sana getiren

Dağlardan kovulmuş ceylan gibiyim

Kurşuna tutulmuş mercan gibiyim

Enginden engine koşar giderim

Umutlarım beni sana getiren

Ferhat''ın aşkını dağlara yazmışım

Mecnun olup çölde susuz kalmışım

Karanfil dalına düşer gözyaşım

Özlemlerim beni sana getiren', 'Günlerdir dalgın dalgın gezerim Çekilmez çileler bitmez dertlerim Hergün bin kez mürde olur bedenim Umutlarım beni sana getiren Dağlardan ko...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/umutlarim-beni-sana-getiren-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sevgi Mabedim Olsun', 'sevgi-mabedim-olsun-sair-khan-2m7oj', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'SEVGİ MABEDİM OLSUN! ! ! ! ! ! 

YARABBİ! 

bir insan koy kalbime

ama o insan Senin de sevdiğin bir insan olsun

ve beni öyle bir insana sevdir ki

o insanın kalbinde Sen olasın

ki ben o insanın kalbinde Seninle buluşayım

o insanın kalbi Seninle buluştuğum bir mabet olsun

beni öyle bir insanla buluştur ki, benden önce

onunla buluşmuş olan Sen olasın

onunla el ele tutuştuğumda

ikimizin üzerinde Senin elin olsun

bana öyle gözler göster ki

ben o gözlerden Sana bakayım

bana öyle bir sevgili ver ki

o gözler cennete açılan iki pencere olsun

onunla öyle bir yolda yürüyelim ki

kılavuzumuz Sen olasın ey Yarabbi

öyle bir sevgili ver ki bana

ona sarıldığımda kainat bize bakıp

bir birine sarılsın

sevgimiz kurtlarla kuzuları barıştırsın

bize bakıp şeytan ademe secde etsin

günah sevap uğruna kendini feda etsin

ölüler birer birer uyansın sevgimizle

bize öyle bir sevgi ver ki Rabbim

sevgimizden Muhammed sevilsin

öyle sevelim ki birbirimizi

Hatice göklerden bize seslensin

ve desin ki: 

“bak ya Muhammed, bak şu sevgililere

onlar bizde, biz onlardayız

bak aşkımız bir kez daha yaşanıyor yeryüzünde

Allah aşkımızı öyle seviyor ki binlerce insana

yaşatıyor onu....”', 'SEVGİ MABEDİM OLSUN! ! ! ! ! !  YARABBİ!  bir insan koy kalbime ama o insan Senin de sevdiğin bir insan olsun ve beni öyle bir insana sevdir...', ARRAY['Türk Edebiyatı','Şiir','Şair Khan']::text[], 8.5, '{"poet":"Şair Khan","poet_slug":"sair-khan","theme":"Türk Şiiri","is_hero":false,"total_lines":35,"source_url":"https://www.antoloji.com/sevgi-mabedim-olsun-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Korku 1', 'korku-1-ethem-vayvayli-cguae', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yaramaz bir el

Uçuşan hayallerimde 

O kadar ilkel

İçimden kime serzeniş

Uykuma dolan gece

Rüyalarım kima gidiş

Tam bir sürü düşünce

Avuçlarında örselenen mendilin

Kenarları okşar yanaklarımı

Karanlıkta dilleştiğimiz bu el 

Çatlatır dudaklarımı', 'Yaramaz bir el Uçuşan hayallerimde  O kadar ilkel İçimden kime serzeniş Uykuma dolan gece Rüyalarım kima gidiş Tam bir sürü düşünce Avuçları...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/korku-1-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Dalgalar', 'dalgalar-ethem-vayvayli-c63be', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'O asûde yorgunluğumu

Dağlardan denize alandı

Son yongam çınar dalını

Denizler aşırı salandı

Ne zaman oldu da rüzgar

Benimle geçti köprüden

Artık kalır oldum uzak

Deryada akışan sürüden', 'O asûde yorgunluğumu Dağlardan denize alandı Son yongam çınar dalını Denizler aşırı salandı Ne zaman oldu da rüzgar Benimle geçti köprüden A...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/dalgalar-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Tek Antikam', 'tek-antikam-ethem-vayvayli-yttjx', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'Umutların tükendiği bir yolun başında

Dostlarımı kaybettim ve şimdi yalnızım

Dolduruldu gözyaşım kriter yalağına

Armonimdeki yalnızlık tek antikam

Aranan sesimin yanık öyküsünde bir il

Arşa kurulmuş donanma direğimde kertik

Düğümleri çözülmüş yankılarda ben tekil

Duygular darmadağın, düşüncelerim serpik', 'Umutların tükendiği bir yolun başında Dostlarımı kaybettim ve şimdi yalnızım Dolduruldu gözyaşım kriter yalağına Armonimdeki yalnızlık tek a...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/tek-antikam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Aşk-ı Herkül', 'ask-i-herkul-ethem-vayvayli-gprdk', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Daha fazla beklemeye değer mi? 

Alevden yeleğe sarıldı tahammül', 'Daha fazla beklemeye değer mi?  Alevden yeleğe sarıldı tahammül...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":2,"source_url":"https://www.antoloji.com/ask-i-herkul-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çoban Yıldızı', 'coban-yildizi-ethem-vayvayli-1vpdh', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Hiç esmedi yamaçlarımızdan

Zihnet bakışlı yılışık rüzgar

Hayalmiş tastaki fırtına ricattan

Altın bakracında ıslanırken yıldızlar

Utancımızdan düşler yurduna vardık

Dudaklarımızda hasret katarıyla

Bir bir gecenin koynuna yuvarlandık

Güzün salkımında ümit tığlarıyla

Başım öne düştü geceye hicabımdan

Yutkundum aydedenin loş ışıklarını

Camları rengarenk bir bardağın alnından

Duyar gibi oldum çoban ıslıklarını

Üstümüze kubbelenen gökyüzünden

Koparıp aldım çoban yıldızlarını

Gönül ipeği beyaz-sarı zülfünden

Muştularla donattım çarşılarımı', 'Hiç esmedi yamaçlarımızdan Zihnet bakışlı yılışık rüzgar Hayalmiş tastaki fırtına ricattan Altın bakracında ıslanırken yıldızlar Utancımızda...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":16,"source_url":"https://www.antoloji.com/coban-yildizi-3-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Hep O', 'hep-o-ethem-vayvayli-wgzvn', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Oturdum aklıma geldin

kalktım aklımdaydın

Ne zaman bilmam

Bilmem ne zaman

-Farkındaydın!', 'Oturdum aklıma geldin kalktım aklımdaydın Ne zaman bilmam Bilmem ne zaman -Farkındaydın!...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":5,"source_url":"https://www.antoloji.com/hep-o-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şâir', 's-ir-ethem-vayvayli-lsmzk', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Seyrederken rüveyda örtüsünü

Yatsı döleğinin genç saatlerinde

Çan sesleridir ıssızlığı aralayan

Bir de çobanın hey heyleri...

Suya düşen aydedenin övgüleri

Yanarken yolun şarampolünde

Yülekli baltadır kütükte parlayan

Duvarda asılı yalın kılınç gibi!', 'Seyrederken rüveyda örtüsünü Yatsı döleğinin genç saatlerinde Çan sesleridir ıssızlığı aralayan Bir de çobanın hey heyleri... Suya düşen ayd...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/sair-5-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Eski Sokaklar', 'eski-sokaklar-ethem-vayvayli-oeq6f', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Yokuş merdivendi eski devirde

Umudun öldürüldüğü sokaklar

Taşlarda seken ürkek ceylanın

Tedirginliğini çalmıştı ayaklar

Söküldü taş duvarlardan levhalar

Adlarını yitirdi o eski sokaklar

Muhteşem tarihlerinde şehirlerin

Sesini dinlerdi sokaklar denizin

Sessizce güzgöçüne yürüdüler

Sokakları kimsesizliğe sürdüler

Şehrin düşlerinde çarmıha gerildik

Mehlikâ Sultan''a aşık yedi gençtik', 'Yokuş merdivendi eski devirde Umudun öldürüldüğü sokaklar Taşlarda seken ürkek ceylanın Tedirginliğini çalmıştı ayaklar Söküldü taş duvarlar...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/eski-sokaklar-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Sizin Köyün Deresi', 'sizin-koyun-deresi-ethem-vayvayli-ciapw', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=800&auto=format&fit=crop&q=80', 'Sonbahardı

Annemle bizbize

Sözünü ederdik

Geldik mi dizdize

Tahta minderi seslenirdi

Oynak taşların üstünde

Suların dilinde melodi

Derenin senden sesinde

Hergün kıyısına inerdi

Peşinden koşan çocuklar

Sizin köyün deresi

Tüm gün üç kez gülerdi: 

sen gelirken

ben geçerken

ikimiz birken!', 'Sonbahardı Annemle bizbize Sözünü ederdik Geldik mi dizdize Tahta minderi seslenirdi Oynak taşların üstünde Suların dilinde melodi Derenin s...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":15,"source_url":"https://www.antoloji.com/sizin-koyun-deresi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Noktalanmamış Bir Aşk Hikayesi', 'noktalanmamis-bir-ask-hikayesi-sair-evindar-c8txp', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1457369804613-52c61a468e7d?w=800&auto=format&fit=crop&q=80', ': bir noktayı diğerinin üzerine koyarak başlıyordum sözlerime

anlatmaya çalışıyordum sevgimi.öyle çok duyguyu aynı anda yaşıyordumki aynı anda.bir duygu-bir virgül, bir duygu-bir virgül, bir duygu daha -bir virgül daha, duygu -  virgül, duygu-virgül... virgüllerde yetmiyordu sözlerde.sözlerimin sonuna hep üç nokta bırakarak ayrılıyordum senden.

sende konuşmuyor değildin. ee az bişey çenen düşüktü.ama ben sürükleyici bir romanın kilit noktasındaki bir kelimeyi satır yetmezliğinden bölen kısa çizgiyi takip eder gibi dikkatle dinliyordum sözlerini.ve o kilit iki kelimeyi alamıyordum ağzından.ve her ayrılışımızda soru işaretlerinin çengelini beynime saplardın.bende hep beynimde soru işaretlerinle yaşardım

yokluğunun kalbimi sızlattığı günlerde doğaya sığınırdım.aptal aptal konuşurdum kuşlarla.yıldızlara sorardım nerde olduğunu.ünlemler  fırlatırdım dağlara, taşlara, gökyüzüne.seni sevdiğimi bağırırdım.mardin eşiğinde ve asiler kentinin mor ve kara dağlarında yankılanırdısanki sevgilim  dağlarmış gibi cevap verirlerdi SENİ SEVİYORUM diye.

geçmişimdeki o eski, çocukça yaşadığım aşk bozuntularının yanında adını parentez le ayırırdım o ince aşk defterinde. çünkü sen başkaydın. çünkü sen AŞKIMDIN...

benim aşkım hep umut etmekle geçti.hep ümit ettim söyleyeceğin sözler arasında SENİ SEVİYORUM kelimelerini tırnak içine  almayı.hep bekledim. hep

ama sen beni anlamadın. yada başka bi deyişle ben sana kendimi anlatamadım. nedenmi? 

derlerki: soru cümlesinin sonuna soru işareti.sevinç, hüzün, heyecan cümlelerinin sonuna ünlem.düz anlatım cümlelerinin sonuna nokta.yarıda kalmış cümlelerin sonunada üç nokta koyarlarmış.

ama umufu anlatan bir işaret bulamadım ben.herşeye rağmen umudu, ümit etmeyi anlatan bir işaret yoktu.ve eksik kalıyordu bir tarafım, ve beni kahrediyordu.çünkü beni anlamıyordun.beni tanıyamıyordun.

ve şimdi onca -di li geçmiş zaman cümlesinden sonra nokta koyduğumu anlıyorsun biliyorum.o  kadar kolay olmuyor satırlar dolusu yazı yazmak zor gelmezken sadece bir nokta atmak; bu aşkı noktalamak bana çok çok zor geliyor

ben sana bıraktım bu işi. al kalemi eline ve o en önemli ama tanımı bile olmayan boyutrsuz işareti koy bu aşk hikayesinin sonuna', ': bir noktayı diğerinin üzerine koyarak başlıyordum sözlerime anlatmaya çalışıyordum sevgimi.öyle çok duyguyu aynı anda yaşıyordumki aynı an...', ARRAY['Türk Edebiyatı','Şiir','Şair Evindar']::text[], 8.5, '{"poet":"Şair Evindar","poet_slug":"sair-evindar","theme":"Türk Şiiri","is_hero":false,"total_lines":11,"source_url":"https://www.antoloji.com/noktalanmamis-bir-ask-hikayesi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Vaktiyle Diriliş', 'vaktiyle-dirilis-ethem-vayvayli-asnor', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1455390582262-044cdead277a?w=800&auto=format&fit=crop&q=80', 'Alacakaranlığın sardığı bir devirde

Ilgıt ılgıt rüzgarın esmesi vardı

Çığlığını duyardım yaprakların şehirde

Kan rengi toprağa düşmesi vardı

Cılgası kaybolan gecenin sırtından

Toy delikanlıların geçmesi vardı

Yokluğu geberten yamalı pırtıdan 

Asrın adamını seçmesi vardı', 'Alacakaranlığın sardığı bir devirde Ilgıt ılgıt rüzgarın esmesi vardı Çığlığını duyardım yaprakların şehirde Kan rengi toprağa düşmesi vardı...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/vaktiyle-dirilis-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Demirle Savaşan Adam', 'demirle-savasan-adam-sair-evindar-jeal1', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1512820790803-83ca734da794?w=800&auto=format&fit=crop&q=80', 'Gün gece

Yankıda tek bir hece

tak..... tak... tak....

Gecede bir adam

Elinde ateş

Gözlerinde yansı

Ne demirler eritiyor 

Ne çelikler

Söz dinletiyor asi ateşe

Söz dinletiyor kıt demire

Ve  konuşturuyor çekicini

Umut dövüyor demirden

Demirle savaşıyor

Tarla yapıyor demiri

Bileğiyle işliyor

Emek yeşertiyor demirden

Alnının teriyle suluyor tarlasını

Şeref topluyor bu tarladan

Umut yediriyor  çocuklarına

Savaşıyor bu gecede

Gün gece 

Yankıda tek bir hece

Tak.... Tak...TAK! ! ! .....

Gecede bir adam

O adam

Benim BABAM...', 'Gün gece Yankıda tek bir hece tak..... tak... tak.... Gecede bir adam Elinde ateş Gözlerinde yansı Ne demirler eritiyor  Ne çelikler Söz din...', ARRAY['Türk Edebiyatı','Şiir','Şair Evindar']::text[], 8.5, '{"poet":"Şair Evindar","poet_slug":"sair-evindar","theme":"Türk Şiiri","is_hero":false,"total_lines":26,"source_url":"https://www.antoloji.com/demirle-savasan-adam-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Çocukların Şarkısı', 'cocuklarin-sarkisi-ethem-vayvayli-6buim', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1476275466078-4007374efbbe?w=800&auto=format&fit=crop&q=80', 'Özümdeki seslenişi

Çocuklara anlatmıştım

Onlar ağlamasın diye

Şehre adım atmıştım

Hayret doğru, umut yanlış

Vadide kum karış karış

Çocukların şarkısını 

Alıp götürdü bu akış', 'Özümdeki seslenişi Çocuklara anlatmıştım Onlar ağlamasın diye Şehre adım atmıştım Hayret doğru, umut yanlış Vadide kum karış karış Çocukları...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":8,"source_url":"https://www.antoloji.com/cocuklarin-sarkisi-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Memleketime', 'memleketime-sair-evindar-g0boz', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1519682337058-a94d519337bc?w=800&auto=format&fit=crop&q=80', 'Mardin

Memleketim

çocukluğum

ilk arkadaşım

ilk sevgilim

ilk ögretmenim

çok şey öğrettin bana

bitmez tükenmez merdivenlerde

sabretmeyi

azmetmeyi

çıkışların bir inişi olduğu gibi

kötü günleride iyi günlerin beklediğini

bir ırk, kültür, din, dil mozaiğinin içinde

hehese kardeşçe bakmayı

sevmeyi, sevilmeyi öğrettin...

herkes birbiriyle bi yerlerde akraba olduğundan

dost kazığı yemeyide öğrettin aynı zamanda

KIRKIZ tepesinde kışın en sertini

BERRİYE degüneşin en kavurucusuyla tanıştırdın

onlarıda sevmeye alıştık seninle

karanlık abbaralardan geçerken

abbara ucundaki ışıkla ümidi müjdeledin

biz senden öğrendik ümit etmeyi

çıkamadığımız kalenle

ulaşamıyacağımız hedefleri farkettirdin

ve çaresizliği

Anti-sosyal bi coğrafyada olmana rağmen

yaşanılacak birşeyler buldurdun kendinde

çan sesiyle ezan sesinin eşsiz senfonisini dinlettin aynı anda

çektirilen acılarla

evlerindeki taşlar gibi oydun yüreklerimizi

ey memleketim! ! ! 

ilk aşkım

ilk sevgilim

ilk ögretmenim

MARDİNİM

dörtbin yıldır yuvamızsın

evet

belki bir kaç yüzyıllık new york tan gerisin ama

ne diyelim

SANA BUNU RAZI GÖRENLER

                                        UTANSIN! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! ! !', 'Mardin Memleketim çocukluğum ilk arkadaşım ilk sevgilim ilk ögretmenim çok şey öğrettin bana bitmez tükenmez merdivenlerde sabretmeyi azmetm...', ARRAY['Türk Edebiyatı','Şiir','Şair Evindar']::text[], 8.5, '{"poet":"Şair Evindar","poet_slug":"sair-evindar","theme":"Türk Şiiri","is_hero":false,"total_lines":42,"source_url":"https://www.antoloji.com/memleketime-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
INSERT INTO contents (type, title, slug, cover_image, backdrop_image, content_text, summary, genres, global_rating, metadata) VALUES ('poem', 'Şafak', 'safak-ethem-vayvayli-mf4qr', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=800&auto=format&fit=crop&q=80', 'Işıklar deryaya süzülürken akşamları

Şafağa düş kurarım ıssız penceremde

Gece, gelecek sabaha saklarken camları

Merhalesiz hayaller boğuşur içimde

Lehim damlatır sıçrayan zamana

Körüğünde eriyen bir avuç göz yaşı

Sevinci müjdeler sarsılmış insana

Vicdanın iki büklüm duruşuna karşı

Feryatsız kulun tokmağıdır şafak

Sökülürken umut ufkundan  güneş

Sefalet hayallarine çekilir zikzak

Gözyaşıyla yoğrulur şafakta çilekeş', 'Işıklar deryaya süzülürken akşamları Şafağa düş kurarım ıssız penceremde Gece, gelecek sabaha saklarken camları Merhalesiz hayaller boğuşur ...', ARRAY['Türk Edebiyatı','Şiir','Ethem Vayvaylı']::text[], 8.5, '{"poet":"Ethem Vayvaylı","poet_slug":"ethem-vayvayli","theme":"Türk Şiiri","is_hero":false,"total_lines":12,"source_url":"https://www.antoloji.com/safak-siiri/"}'::jsonb) ON CONFLICT (slug) DO NOTHING;
